# ----------------------------
# Style + saving helpers
# ----------------------------
def _set_compact_plot_style():
    plt.rcParams.update({
        "font.size": 10,
        "axes.titlesize": 13,
        "axes.labelsize": 12,
        "xtick.labelsize": 10,
        "ytick.labelsize": 10,
        "legend.fontsize": 10,
        "figure.titlesize": 13,
    })


def _savefig_tight(fig, savefile, dpi=300, pad_inches=0.25):
    os.makedirs(os.path.dirname(savefile), exist_ok=True)
    fig.savefig(savefile, dpi=dpi, bbox_inches="tight", pad_inches=pad_inches)

# ----------------------------
# Generic group histogram plotter
#   (use this for BOTH error and Ksum)
# ----------------------------
def plot_group_histograms(
    group_arrays,
    *,
    title: str,
    xlabel: str,
    savefile: str,
    bins: int = 60,
    density: bool = True,
    xlim=None,
    colors=None,
    auto_close: bool = True,
):
    """
    group_arrays: dict[str -> np.ndarray]
      e.g. {"hM3D": arr, "hM4D": arr, "mCherry": arr}

    density=True gives you the "Density" axis like your error distribution plot.
    density=False gives counts (useful for some Ksum views).
    """
    _set_compact_plot_style()

    if colors is None:
        colors = {"hM3D": "red", "hM4D": "blue", "mCherry": "black"}

    fig, ax = plt.subplots(figsize=(7.0, 5.0), dpi=150)

    order = ["hM3D", "hM4D", "mCherry"]
    for g in order:
        if g not in group_arrays:
            continue
        a = np.asarray(group_arrays[g], dtype=float)
        a = a[np.isfinite(a)]
        if a.size == 0:
            continue

        ax.hist(
            a,
            bins=bins,
            density=density,
            alpha=0.35,
            color=colors.get(g, "gray"),
            label=f"{g} (n={a.size})",
        )

    ax.set_title(title, pad=8)
    ax.set_xlabel(xlabel)
    ax.set_ylabel("Density" if density else "Count")
    if xlim is not None:
        ax.set_xlim(xlim)

    ax.grid(True, alpha=0.2)
    ax.legend(frameon=False, loc="upper right")

    # tighter layout, but also reserve a bit for title
    fig.tight_layout(rect=[0, 0, 1, 0.95])

    _savefig_tight(fig, savefile, dpi=300, pad_inches=0.25)

    if auto_close:
        plt.close(fig)

    return fig, ax


# ----------------------------
# 3b) Aggregate decoded-vs-true 2D density panels across all mice per group
# ----------------------------

def _collect_decoded_true_per_group(
    dec_results: dict,
    mouse_groups: dict,
    condition: str,
    groups=("hM3D", "hM4D", "mCherry"),
    kmin: float = 0.0,
):
    """
    Collect concatenated (true_pos, decoded_pos) arrays per group.

    condition: "within_LT1", "within_LT2", or "LT1_to_LT2"

    For within-session conditions, the LOLO CV result (train_to_test)
    and both directions (leftward, rightward) are
    concatenated.

    kmin : float
        If > 0, only keep decode bins whose Ksum >= kmin.

    Returns
    -------
    group_pairs : dict[str -> (true_pos_1d, decoded_pos_1d)]
    """
    group_true = {g: [] for g in groups}
    group_dec  = {g: [] for g in groups}

    def _append_filtered(g, tp, dp, Ksum):
        """Apply finite + optional Ksum filter, then append."""
        n = min(tp.size, dp.size)
        if n == 0:
            return
        tp, dp = tp[:n], dp[:n]
        m = np.isfinite(tp) & np.isfinite(dp)
        if Ksum is not None and kmin > 0:
            K = np.asarray(Ksum, float)
            K = K[:n]
            m = m & np.isfinite(K) & (K >= kmin)
        if m.sum() == 0:
            return
        group_true[g].append(tp[m])
        group_dec[g].append(dp[m])

    for mouse, res in dec_results.items():
        g = mouse_groups.get(mouse, "NA")
        if g not in group_true:
            continue

        if condition == "LT1_to_LT2":
            blk = res.get("LT1_to_LT2", {})
            if not blk.get("ok", False):
                continue
            out = blk.get("out", {})
            tp = np.asarray(out.get("true_pos", []), float)
            dp = np.asarray(out.get("decoded_pos", []), float)
            Ksum = out.get("Ksum", None)
            _append_filtered(g, tp, dp, Ksum)

        else:
            # within_LT1 or within_LT2
            sess = "LT1" if "LT1" in condition else "LT2"
            within = None
            for kk in (f"within_{sess}_by_dir",
                       f"within_{sess}_by_dir_full",
                       f"within_{sess}_by_dir_mapped"):
                d = res.get(kk)
                if isinstance(d, dict) and len(d) > 0:
                    within = d
                    break
            if within is None:
                continue

            for dir_label, dblk in within.items():
                if not isinstance(dblk, dict) or not dblk.get("ok", False):
                    continue
                for fold_key in ("train_to_test",):
                    step = dblk.get(fold_key)
                    if not isinstance(step, dict):
                        continue
                    out = step.get("out")
                    if not isinstance(out, dict):
                        continue
                    tp = np.asarray(out.get("true_pos", []), float)
                    dp = np.asarray(out.get("decoded_pos", []), float)
                    Ksum = out.get("Ksum", None)
                    _append_filtered(g, tp, dp, Ksum)

    result = {}
    for g in groups:
        if group_true[g]:
            result[g] = (np.concatenate(group_true[g]),
                         np.concatenate(group_dec[g]))
        else:
            result[g] = (np.array([], float), np.array([], float))
    return result


def plot_aggregate_error_density(
    dec_results: dict,
    mouse_groups: dict,
    *,
    save_dir: str,
    session_str: str = "",
    bin_width_px: float = 10.0,
    kmin: float = 0.0,
    auto_close: bool = True,
    groups=("mCherry", "hM3D", "hM4D"),
    colors=None,
    density: bool = True,       # kept for API compat – unused now
):
    """
    3-row × 3-column figure of 2D decoded-vs-true heatmaps.

    Rows   = DREADD groups  (mCherry, hM3D, hM4D)
    Cols   = conditions     (Within LT1, Within LT2, LT1→LT2)

    Each panel is a 2D histogram (bin_width_px × bin_width_px) with a
    diagonal identity line.  Colormap intensity = number of decoded
    time-bins falling in each (true, decoded) cell.

    Parameters
    ----------
    kmin : float
        Minimum Ksum to keep a decode bin (0 = no filter).
    """
    from matplotlib.colors import LogNorm

    _set_compact_plot_style()

    if colors is None:
        colors = {"hM3D": "red", "hM4D": "blue", "mCherry": "black"}

    cond_specs = [
        ("within_LT1", "Within LT1"),
        ("within_LT2", "Within LT2"),
        ("LT1_to_LT2", "LT1 → LT2"),
    ]
    order = list(groups)

    # -- collect decoded/true per group per condition ----------------
    cond_data = {}
    for cond_key, nice in cond_specs:
        cond_data[cond_key] = _collect_decoded_true_per_group(
            dec_results, mouse_groups, cond_key, groups=groups, kmin=kmin,
        )

    # -- determine global axis range ---------------------------------
    all_vals = []
    for cond_key, _ in cond_specs:
        for g in order:
            tp, dp = cond_data[cond_key][g]
            if tp.size:
                all_vals.extend([tp.min(), tp.max(), dp.min(), dp.max()])
    if not all_vals:
        print("[WARN] plot_aggregate_error_density: no data → skip")
        return None, None, ""
    global_lo = min(all_vals)
    global_hi = max(all_vals)
    bins = np.arange(global_lo, global_hi + bin_width_px, bin_width_px)

    # -- figure layout -----------------------------------------------
    # Nature single-column = 89 mm ≈ 3.5 in; double-column = 183 mm ≈ 7.2 in
    # Use full page width (183 mm) with square panels
    panel_size = 2.0   # inches per panel (square)
    n_rows = len(order)
    n_cols = len(cond_specs)
    fig_w = panel_size * n_cols + 1.2   # +1.2 for labels + colorbar
    fig_h = panel_size * n_rows + 0.8   # +0.8 for column titles + x-labels
    fig, axes = plt.subplots(
        n_rows, n_cols,
        figsize=(fig_w, fig_h),
        dpi=200,
        sharex=True, sharey=True,
    )
    if n_rows == 1:
        axes = axes[np.newaxis, :]  # ensure 2D

    # -- pre-compute global vmax for shared colorbar -------------------
    global_max = 1
    for cond_key, _ in cond_specs:
        for g in order:
            tp, dp = cond_data[cond_key][g]
            if tp.size == 0:
                continue
            H_pre, _, _ = np.histogram2d(tp, dp, bins=[bins, bins])
            mx = int(H_pre.max())
            if mx > global_max:
                global_max = mx

    log_norm = LogNorm(vmin=1, vmax=global_max)
    last_mesh = None

    _TITLE_FS = 10
    _LABEL_FS = 9
    _TICK_FS  = 8
    _N_FS     = 7

    for ri, g in enumerate(order):
        for ci, (cond_key, nice) in enumerate(cond_specs):
            ax = axes[ri, ci]

            tp, dp = cond_data[cond_key][g]
            if tp.size == 0:
                ax.text(0.5, 0.5, "no data", transform=ax.transAxes,
                        ha="center", va="center", fontsize=_LABEL_FS, color="0.5")
            else:
                # 2D histogram
                H, xedges, yedges = np.histogram2d(tp, dp, bins=[bins, bins])
                H_masked = np.ma.masked_where(H == 0, H)

                last_mesh = ax.pcolormesh(
                    xedges, yedges, H_masked.T,
                    cmap="inferno",
                    norm=log_norm,
                    rasterized=True,
                )

            # identity line
            ax.plot([global_lo, global_hi], [global_lo, global_hi],
                    color="cyan", linewidth=0.8, alpha=0.7)

            # labels / titles
            if ri == 0:
                ax.set_title(nice, fontsize=_TITLE_FS, pad=4)
            if ci == 0:
                ax.set_ylabel(f"{g}\nDecoded pos ({_LT_1D_DISTANCE_UNIT})", fontsize=_LABEL_FS)
            if ri == n_rows - 1:
                ax.set_xlabel(f"True position ({_LT_1D_DISTANCE_UNIT})", fontsize=_LABEL_FS)

            ax.tick_params(labelsize=_TICK_FS, length=2, width=0.6)

            # n count annotation
            ax.text(0.03, 0.96, f"n={tp.size:,}", transform=ax.transAxes,
                    fontsize=_N_FS, va="top", ha="left", color="white",
                    fontweight="bold",
                    bbox=dict(facecolor="black", alpha=0.45, pad=1.5, edgecolor="none"))

            ax.set_aspect("equal", adjustable="box")
            ax.grid(False)

    fig.tight_layout(rect=[0, 0, 0.91, 1.0], h_pad=0.4, w_pad=0.4)

    # -- shared colorbar on the right --------------------------------
    if last_mesh is not None:
        cbar_ax = fig.add_axes([0.92, 0.10, 0.015, 0.80])
        cbar = fig.colorbar(last_mesh, cax=cbar_ax)
        cbar.set_label("Count", fontsize=_LABEL_FS)
        cbar.ax.tick_params(labelsize=_TICK_FS, length=2)

    _ensure_dir(save_dir)
    kmin_tag = f"_kmin{int(kmin)}" if kmin > 0 else ""
    savefile = os.path.join(
        save_dir,
        f"aggregate_decoded_vs_true_{session_str}{kmin_tag}.png",
    )
    _savefig_tight(fig, savefile, dpi=300, pad_inches=0.3)
    print(f"[SAVED] {savefile}")

    if auto_close:
        plt.close(fig)

    return fig, axes, savefile


# ----------------------------
# 4) Error vs Ksum scatter (LT1→LT2)
# ----------------------------
def plot_error_vs_Ksum_scatter_grouped_LT1_to_LT2(
    dec_results: dict,
    mouse_groups: dict,
    *,
    title: str,
    savefile: str,
    colors=None,
    alpha: float = 0.25,
    s: float = 10,
    max_points_per_mouse: int = None,  # None = all points
    auto_close: bool = True,
):
    """
    Scatter: each point = one decode chunk (Ksum, abs_err), colored by group.
    This is a *distributional* / mechanistic plot, not mouse-level inference.
    """
    if colors is None:
        colors = {"hM3D": "red", "hM4D": "blue", "mCherry": "black"}

    fig, ax = plt.subplots(figsize=(6.0, 4.5), dpi=150)

    for mouse, res in dec_results.items():
        g = mouse_groups.get(mouse, "NA")
        blk = res.get("LT1_to_LT2", {})
        if not blk.get("ok", False):
            continue

        out = blk.get("out", {})
        Ksum = np.asarray(out.get("Ksum", []), dtype=float)
        err = np.asarray(blk.get("abs_err", []), dtype=float)

        n = min(Ksum.size, err.size)
        if n == 0:
            continue
        Ksum = Ksum[:n]
        err = err[:n]

        m = np.isfinite(Ksum) & np.isfinite(err)
        Ksum = Ksum[m]
        err = err[m]
        if Ksum.size == 0:
            continue

        if max_points_per_mouse is not None and Ksum.size > max_points_per_mouse:
            idx = np.random.choice(Ksum.size, size=max_points_per_mouse, replace=False)
            Ksum = Ksum[idx]
            err = err[idx]

        ax.scatter(Ksum, err, color=colors.get(g, "gray"), alpha=alpha, s=s)

    ax.set_xlabel("Total events per decode bin (Ksum)")
    ax.set_ylabel(f"Absolute decoding error ({_LT_1D_DISTANCE_UNIT})")
    ax.set_title(title)
    ax.grid(True, alpha=0.2)

    fig.tight_layout()
    fig.savefig(savefile, dpi=300)
    if auto_close:
        plt.close(fig)
    return fig, ax

# ----------------------------
# 5) One-call wrapper to generate “communication” plots
# ----------------------------
def run_group_summary_plots(
    dec_results,
    mouse_groups,
    *,
    PLOTS_DIR: str,
    session_str: str,
    mapping: str,
    auto_close: bool = True,
    use_median: bool = False,
):
    """
    Produces:
      - within-LT1: dist_abs_err + dist_Ksum + mouse-level metric plots
      - within-LT2: dist_abs_err + dist_Ksum + mouse-level metric plots
      - LT1->LT2:   dist_abs_err + dist_Ksum + mouse-level metric plots (from mixedlm CSV if present)

    use_median: if True, plots use median_err / median_Ksum; if False, mean_err / mean_Ksum.
    CSVs always include both median and mean columns.

    Also writes:
      summary_{session_str}_mapping_{mapping}/mouse_level_summary_within_LT1_all.csv
      summary_{session_str}_mapping_{mapping}/mouse_level_summary_within_LT2_all.csv
    """
    stat_label = "median" if use_median else "mean"
    err_col  = f"{stat_label}_err"
    ksum_col = f"{stat_label}_Ksum"

    save_path = os.path.join(PLOTS_DIR, f"summary_{session_str}_mapping_{mapping}_{stat_label}")
    _ensure_dir(save_path)

    # -----------------------
    # 1) Chunk-level dists: within LT1 and within LT2
    # -----------------------
    within_specs = [
        ("LT1_train_to_test", "LT1 within (LOLO)"),
        ("LT2_train_to_test", "LT2 within (LOLO)"),
    ]

    for cond, pretty in within_specs:
        # abs_err dist
        group_err, used_mice_err, skipped_err = collect_group_abs_err(dec_results, mouse_groups, cond)
        if sum(len(v) for v in used_mice_err.values()) > 0:
            plot_group_error_histograms(
                group_err,
                title=f"{session_str} {pretty}: decoding error distribution",
                savefile=os.path.join(save_path, f"dist_abs_err_{cond}_by_group.png"),
                auto_close=auto_close,
                font_scale=0.80,
            )

        # Ksum dist
        group_Ksum, used_mice_K, skipped_K = collect_group_Ksum(dec_results, mouse_groups, cond)
        if sum(len(v) for v in used_mice_K.values()) > 0:
            plot_group_Ksum_histograms(
                group_Ksum,
                title=f"{session_str} {pretty}: Ksum distribution",
                savefile=os.path.join(save_path, f"dist_Ksum_{cond}_by_group.png"),
                density=True,
                auto_close=auto_close,
                font_scale=0.80,
            )

    # -----------------------
    # 2) Chunk-level dists: LT1 -> LT2
    # -----------------------
    cond = "LT1_to_LT2"
    group_err, _, _ = collect_group_abs_err(dec_results, mouse_groups, cond)
    plot_group_error_histograms(
        group_err,
        title=f"{session_str} LT1→LT2: decoding error distribution",
        savefile=os.path.join(save_path, "dist_abs_err_LT1_to_LT2_by_group.png"),
        auto_close=auto_close,
        font_scale=0.80,
    )

    group_Ksum, _, _ = collect_group_Ksum(dec_results, mouse_groups, cond)
    plot_group_Ksum_histograms(
        group_Ksum,
        title=f"{session_str} LT1→LT2: Ksum distribution",
        savefile=os.path.join(save_path, "dist_Ksum_LT1_to_LT2_by_group.png"),
        density=True,
        auto_close=auto_close,
        font_scale=0.80,
    )

    # -----------------------
    # 3) Mouse-level summaries: within LT1 + within LT2 (computed from dec_results)
    # -----------------------
    # NOTE: these two conditions define "within session" for your summary.
    # If you prefer to average train→test and test→train, say so, and we’ll adjust.
    for sess_label, cond_within in [
        ("LT1", "LT1_train_to_test"),
        ("LT2", "LT2_train_to_test"),
    ]:
        df_within = build_mouse_level_summary_from_dec_results(
            dec_results,
            mouse_groups,
            condition=cond_within,
            lowK_thresh=1,
        )

        out_csv = os.path.join(save_path, f"mouse_level_summary_within_{sess_label}_all.csv")
        df_within.to_csv(out_csv, index=False)

        # If empty, don’t try to plot.
        if df_within.empty:
            print(f"[run_group_summary_plots] No mouse-level rows for within {sess_label} ({cond_within})")
            continue

        plot_mouse_level_metric_by_group(
            df_within,
            metric_col=err_col,
            title=f"{session_str} within-{sess_label}: mouse-level {stat_label} decoding error",
            savefile=os.path.join(save_path, f"mouse_level_{stat_label}_err_within_{sess_label}_by_group.png"),
            auto_close=auto_close,
            font_scale=0.70,
            figsize=(6.6, 4.8),
        )
        plot_mouse_level_metric_by_group(
            df_within,
            metric_col=ksum_col,
            title=f"{session_str} within-{sess_label}: mouse-level {stat_label} Ksum",
            savefile=os.path.join(save_path, f"mouse_level_{stat_label}_Ksum_within_{sess_label}_by_group.png"),
            auto_close=auto_close,
            font_scale=0.70,
            figsize=(6.6, 4.8),
        )

    # -----------------------
    # 4) Mouse-level plots for LT1->LT2 from mixedlm CSV (if present)
    # -----------------------
    mixedlm_dir = os.path.join(PLOTS_DIR, f"mixedlm_{session_str}_mapping_{mapping}_{stat_label}")
    csv_path = os.path.join(mixedlm_dir, "mixedlm_mouse_level_summary.csv")

    if os.path.exists(csv_path):
        df = pd.read_csv(csv_path)
        if {err_col, ksum_col}.issubset(df.columns):
            plot_mouse_level_metric_by_group(
                df,
                metric_col=err_col,
                title=f"{session_str} LT1→LT2: mouse-level {stat_label} decoding error",
                savefile=os.path.join(save_path, f"mouse_level_{stat_label}_err_LT1_to_LT2_by_group.png"),
                auto_close=auto_close,
                font_scale=0.70,
                figsize=(6.6, 4.8),
            )
            plot_mouse_level_metric_by_group(
                df,
                metric_col=ksum_col,
                title=f"{session_str} LT1→LT2: mouse-level {stat_label} Ksum",
                savefile=os.path.join(save_path, f"mouse_level_{stat_label}_Ksum_LT1_to_LT2_by_group.png"),
                auto_close=auto_close,
                font_scale=0.70,
                figsize=(6.6, 4.8),
            )
        else:
            print(f"[run_group_summary_plots] CSV missing expected columns ({err_col}, {ksum_col}): {csv_path}")
    else:
        print(f"[run_group_summary_plots] mixedlm CSV not found: {csv_path}")

    print(f"[run_group_summary_plots] Saved summary plots -> {save_path}")
    return save_path


# ----------------------------
# Style helpers
# ----------------------------
def set_compact_plot_style(font_scale=0.85):
    """
    Smaller, consistent text sizing so titles/legends never clip.
    Call at top of each plotting function (or once globally).
    """
    base = 12.0
    fs = base * float(font_scale)

    plt.rcParams.update({
        "font.size": fs,
        "axes.titlesize": fs * 1.15,
        "axes.labelsize": fs * 1.05,
        "xtick.labelsize": fs * 0.95,
        "ytick.labelsize": fs * 0.95,
        "legend.fontsize": fs * 0.95,
        "figure.titlesize": fs * 1.2,
    })


# ----------------------------
# Collectors (abs_err + Ksum)
# ----------------------------
def collect_group_abs_err(
    dec_results,
    mouse_groups,
    condition,
):
    """
    Collect abs decoding error per group for a given condition.
    Uses all finite bins (no Ksum threshold).

    Returns:
        group_err: dict[group] -> list of 1D arrays (per mouse)
        per_mouse: dict[mouse] -> 1D abs_err array
        reasons: dict[mouse] -> str reason if skipped
    """
    import numpy as np

    group_err = {}
    per_mouse = {}
    reasons = {}

    for mouse, res_mouse in dec_results.items():
        group = mouse_groups.get(mouse, "NA")

        ok, out, abs_err, reason = _get_out_block(res_mouse, condition)

        if not ok:
            reasons[mouse] = reason
            continue

        abs_err = np.asarray(abs_err, float)

        if abs_err.size == 0:
            reasons[mouse] = "empty abs_err"
            continue

        keep = np.isfinite(abs_err)
        abs_err_f = abs_err[keep]

        if abs_err_f.size == 0:
            reasons[mouse] = "no finite bins"
            continue

        per_mouse[mouse] = abs_err_f
        group_err.setdefault(group, []).append(abs_err_f)

    return group_err, per_mouse, reasons


# ----------------------------
# Group distribution plots
# ----------------------------
def plot_group_error_histograms(
    group_err,
    *,
    title,
    savefile,
    bins=40,
    density=True,
    xlim=None,
    font_scale=1.0,   # <-- re-added
    auto_close=True,
):
    """
    group_err: dict[group] -> list of 1D arrays (per mouse)
    Concatenates per-mouse arrays within each group.
    """

    import numpy as np
    import matplotlib.pyplot as plt
    import os

    os.makedirs(os.path.dirname(savefile), exist_ok=True)

    # Optional font scaling
    plt.rcParams.update({
        "font.size": 10 * font_scale,
        "axes.titlesize": 11 * font_scale,
        "axes.labelsize": 10 * font_scale,
        "legend.fontsize": 9 * font_scale,
    })

    # --- concatenate per group ---
    group_vec = {}
    for g, arr_list in group_err.items():
        if not arr_list:
            continue

        flat = []
        for a in arr_list:
            if a is None:
                continue
            a = np.asarray(a, float).ravel()
            a = a[np.isfinite(a)]
            if a.size:
                flat.append(a)

        if flat:
            group_vec[g] = np.concatenate(flat)

    if not group_vec:
        print(f"[WARN] No data for {title}")
        return

    order = ["mCherry", "hM3D", "hM4D"]
    groups = [g for g in order if g in group_vec] + [g for g in group_vec if g not in order]

    color_map = {
        "mCherry": "gray",
        "hM3D": "black",
        "hM4D": "tab:blue",
    }

    plt.figure(figsize=(7.5, 4.5), dpi=150)

    for g in groups:
        vec = group_vec[g]
        plt.hist(
            vec,
            bins=bins,
            density=density,
            histtype="step",
            linewidth=2,
            label=f"{g} (n={vec.size})",
            color=color_map.get(g, None),
        )

    plt.title(title)
    plt.xlabel(f"Absolute decoding error ({_LT_1D_DISTANCE_UNIT})")
    plt.ylabel("Density" if density else "Count")
    plt.legend(frameon=False)

    if xlim is not None:
        plt.xlim(xlim)

    plt.tight_layout()
    plt.savefig(savefile)

    if auto_close:
        plt.close()


def plot_group_Ksum_histograms(
    group_Ksum,
    title,
    savefile,
    bins=50,
    xlim=None,
    density=False,
    auto_close=True,
    font_scale=0.80,
):
    """
    KEEP THIS VERSION (compact + tight saving).
    group_Ksum: dict(group-> np.array)
    """
    set_compact_plot_style(font_scale=font_scale)
    colors = {"hM3D": "red", "hM4D": "blue", "mCherry": "black"}

    fig, ax = plt.subplots(figsize=(6.5, 4.5), dpi=150)

    for group, Ksum in group_Ksum.items():
        Ksum = np.asarray(Ksum)
        if Ksum.size == 0:
            continue
        ax.hist(
            Ksum,
            bins=bins,
            alpha=0.4,
            label=f"{group} (n={Ksum.size})",
            color=colors.get(group, "gray"),
            density=density,
        )

    ax.set_xlabel("Total events per decode bin (Ksum)")
    ax.set_ylabel("Density" if density else "Count")
    ax.set_title(title, pad=8)
    if xlim is not None:
        ax.set_xlim(xlim)

    ax.legend(frameon=False)
    ax.grid(True, alpha=0.2)

    fig.tight_layout(rect=[0, 0, 1, 0.95])
    fig.savefig(savefile, dpi=300, bbox_inches="tight", pad_inches=0.2)

    if auto_close:
        plt.close(fig)

    return fig, ax


# ----------------------------
# Mouse-level plots (FIXED TEXT)
# ----------------------------
def plot_mouse_level_metric_by_group(
    df_mouse_level: pd.DataFrame,
    metric_col: str,
    title: str,
    savefile: str,
    *,
    group_col: str = "group",
    mouse_col: str = "mouse",
    agg_col: str = None,         # unused, kept for compatibility
    auto_close: bool = True,
    font_scale: float = 0.75,    # <-- SMALLER TEXT HERE
    figsize=(6.8, 4.8),
):
    """
    df_mouse_level must have at least columns: [mouse_col, group_col, metric_col]
    Plots per-mouse dots + mean±SEM (or mean±SD if you prefer; this uses SEM).
    """
    set_compact_plot_style(font_scale=font_scale)

    colors = {"hM3D": "red", "hM4D": "blue", "mCherry": "black"}

    fig, ax = plt.subplots(figsize=figsize, dpi=150)

    groups = [g for g in ["hM3D", "hM4D", "mCherry"] if g in set(df_mouse_level[group_col])]
    x_positions = np.arange(len(groups))

    # jittered points + summary bars
    rng = np.random.default_rng(0)
    for xi, g in enumerate(groups):
        sub = df_mouse_level[df_mouse_level[group_col] == g]
        y = sub[metric_col].to_numpy(dtype=float)
        y = y[np.isfinite(y)]
        if y.size == 0:
            continue

        jitter = rng.normal(loc=0.0, scale=0.04, size=y.size)
        ax.scatter(
            np.full(y.size, xi) + jitter,
            y,
            s=55,
            color=colors.get(g, "gray"),
            edgecolor="k",
            linewidth=0.6,
            alpha=0.85,
            zorder=3,
        )

        mean = float(np.mean(y))
        sem = float(np.std(y, ddof=1) / np.sqrt(max(y.size, 1))) if y.size > 1 else 0.0
        ax.errorbar(
            [xi],
            [mean],
            yerr=[sem],
            fmt="none",
            ecolor="k",
            elinewidth=2.5,
            capsize=7,
            zorder=4,
        )

    ax.set_xticks(x_positions)
    ax.set_xticklabels(groups)
    ax.set_title(title, pad=10)
    ax.set_ylabel(metric_col)
    ax.grid(True, axis="y", alpha=0.25)

    # Give extra top margin for long titles (your session strings are huge)
    fig.tight_layout(rect=[0, 0, 1, 0.93])
    fig.savefig(savefile, dpi=300, bbox_inches="tight", pad_inches=0.2)

    if auto_close:
        plt.close(fig)

    return fig, ax

def build_mouse_level_summary_from_dec_results(
    dec_results,
    mouse_groups,
    condition: str,
    *,
    lowK_thresh: int = 1,
    pct_threshold: float = 15.0,
):
    """
    Builds mouse-level summary directly from dec_results via _get_out_block().

    Returns df with:
      mouse, group, condition, median_err, mean_err, pct_correct, …, n_bins
    """
    rows = []

    for mouse, res_mouse in dec_results.items():
        ok, out, abs_err, reason = _get_out_block(res_mouse, condition)
        if (not ok) or (out is None):
            continue

        Ksum = np.asarray(out.get("Ksum", []))
        abs_err = np.asarray(abs_err)

        if abs_err.size == 0:
            continue

        # All finite bins (no Ksum threshold)
        err_fin = abs_err[np.isfinite(abs_err)]
        Ksum_fin = Ksum[np.isfinite(Ksum)] if Ksum.size else np.array([])

        row = dict(
            mouse=mouse,
            group=mouse_groups.get(mouse, None),
            condition=condition,
            median_err=float(np.nanmedian(err_fin)) if err_fin.size else np.nan,
            median_Ksum=float(np.nanmedian(Ksum_fin)) if Ksum_fin.size else np.nan,
            mean_err=float(np.nanmean(err_fin)) if err_fin.size else np.nan,
            mean_Ksum=float(np.nanmean(Ksum_fin)) if Ksum_fin.size else np.nan,
            pct_correct=float(np.mean(err_fin < pct_threshold)) if err_fin.size else np.nan,
            n_bins=int(err_fin.size),
        )
        rows.append(row)

    df = pd.DataFrame(rows)
    if not df.empty:
        df = df[df["group"].notna()].copy()

    return df

# Display labels (requested)
GROUPS = ["mCherry", "hM3D", "hM4D"]
GROUP_LABELS = {"mCherry": "Ctl", "hM3D": "Exc", "hM4D": "Inh"}

CONDS  = ["within_LT1", "within_LT2", "LT1_to_LT2"]
COND_LABELS_ABS = {
    "within_LT1": "Within LT1",
    "within_LT2": "Within LT2",
    "LT1_to_LT2": "LT1 to LT2",
}

def _star(p):
    if p < 0.001: return "***"
    if p < 0.01:  return "**"
    if p < 0.05:  return "*"
    if p < 0.08:  return f"p={p:.2f}"
    return ""

def _pad_axes_for_stars(ax, margin_frac=0.12):
    """Expand y-limits so star annotations don't clip."""
    y_lo, y_hi = ax.get_ylim()
    rng = y_hi - y_lo if y_hi > y_lo else 1.0
    pad = margin_frac * rng
    ax.set_ylim(y_lo - pad, y_hi + pad)

def one_sided_yerr_by_sign(vals, errs):
    """
    yerr for matplotlib where:
      - if vals >= 0: show only upward error (lower=0, upper=err)
      - if vals <  0: show only downward error (lower=err, upper=0)
    Returns shape (2, N): [lower, upper]
    """
    vals = np.asarray(vals, dtype=float)
    errs = np.asarray(errs, dtype=float)
    upper = np.where(vals >= 0, errs, 0.0)
    lower = np.where(vals >= 0, 0.0, errs)
    return np.vstack([lower, upper])


# ===================================================================
# Neural-data diagnostics: explain pre-existing group differences
# ===================================================================

def _skaggs_spatial_info(rate_map, occupancy):
    """
    Skaggs spatial information (bits / event) for a single neuron.

    Parameters
    ----------
    rate_map : (B,) mean event rate per position bin
    occupancy : (B,) time spent in each position bin (seconds)

    Returns
    -------
    float : bits per event (spike)
    """
    rate_map = np.asarray(rate_map, float)
    occupancy = np.asarray(occupancy, float)
    occ_prob = occupancy / np.sum(occupancy)  # probability of being in each bin

    mean_rate = np.dot(occ_prob, rate_map)     # overall mean rate
    if mean_rate <= 0:
        return 0.0

    info = 0.0
    for b in range(len(rate_map)):
        if rate_map[b] > 0 and occ_prob[b] > 0:
            info += occ_prob[b] * rate_map[b] * np.log2(rate_map[b] / mean_rate)
    return info / mean_rate  # bits per event


def compute_LT1_neural_diagnostics(
    LT1_group,
    mouse_groups,
    dec_results=None,
    *,
    min_speed=2.0,
    n_pos_bins=60,
    groups=("mCherry", "hM3D", "hM4D"),
    mapping=None,
    LT2_group=None,
):
    """
    Compute per-mouse neural-data diagnostics for LT1 (pre-CNO) to
    investigate baseline differences that might affect decoder accuracy.

    Parameters
    ----------
    mapping : str, optional
        If provided (e.g. "LT1+LT2"), restrict to cross-registered neurons.
        Requires LT2_group to be provided as well.
    LT2_group : dict, optional
        Dict of mouse -> LT2 LinearTrackSession, needed for cross-reg mapping.

    Returns
    -------
    df : pd.DataFrame  — one row per mouse with columns:
        mouse, group,
        n_neurons, n_frames, n_frames_speed,
        mean_event_rate, median_event_rate,
        frac_active_neurons,
        mean_spatial_info, median_spatial_info,
        n_laps_total, n_laps_R, n_laps_L,
        mean_speed, median_speed,
        mean_Ksum, median_Ksum,
        track_coverage
    """
    use_mapped = mapping is not None and LT2_group is not None
    rows = []

    for mouse, LT1 in LT1_group.items():
        g = mouse_groups.get(mouse, "NA")
        if g not in groups:
            continue

        T_full = LT1.S.shape[1]

        # ---- Select neuron subset ----
        if use_mapped:
            try:
                df_map = LT1.crossreg.get_mappings_cells(mapping_type=mapping)
                cells_LT1 = df_map[LT1.session_group].astype(float).astype(int).tolist()
                S, _ = get_mapped_S_from_unit_ids(LT1, cells_LT1)
            except Exception as e:
                print(f"[WARN] {mouse}: could not get mapped S for {mapping}: {e}")
                continue
        else:
            S = LT1.S  # (N, T)

        N, T = S.shape

        # Position and speed
        x = np.asarray(LT1.miniscope_loc_1d_px, float)[:T]
        x = x * _LT_1D_CM_PER_PX          # px -> cm
        dt = _infer_dt_sec(LT1)
        speed_mask = _get_speed_mask(LT1, min_speed)[:T]
        n_speed = int(np.sum(speed_mask))

        # ---- Firing rates ----
        # Total events per neuron over speed-masked frames
        S_speed = S[:, speed_mask]
        events_per_neuron = np.sum(S_speed, axis=1)
        duration_sec = n_speed * dt
        rates = events_per_neuron / max(duration_sec, 1e-6)  # events/sec
        mean_rate = float(np.mean(rates))
        median_rate = float(np.median(rates))
        frac_active = float(np.mean(events_per_neuron > 0))

        # ---- Running speed ----
        if hasattr(LT1, "velocities_miniscope_smooth") and LT1.velocities_miniscope_smooth is not None:
            v = np.asarray(LT1.velocities_miniscope_smooth, float)[:T]
            v_run = v[speed_mask]
            mean_speed = float(np.mean(v_run)) if v_run.size > 0 else np.nan
            median_speed = float(np.median(v_run)) if v_run.size > 0 else np.nan
        else:
            mean_speed = median_speed = np.nan

        # ---- Spatial information ----
        # Build simple tuning curves (rate maps)
        x_speed = x[speed_mask]
        x_min, x_max = np.nanmin(x_speed), np.nanmax(x_speed)
        if x_max - x_min < 1e-6:
            x_max = x_min + 1.0
        bin_edges = np.linspace(x_min, x_max, n_pos_bins + 1)
        pos_bin = np.clip(np.digitize(x_speed, bin_edges) - 1, 0, n_pos_bins - 1)

        occupancy = np.zeros(n_pos_bins, float)
        for b in range(n_pos_bins):
            occupancy[b] = np.sum(pos_bin == b) * dt

        rate_maps = np.zeros((N, n_pos_bins), float)
        for b in range(n_pos_bins):
            idx = pos_bin == b
            if np.any(idx):
                rate_maps[:, b] = np.sum(S_speed[:, idx], axis=1) / max(occupancy[b], dt)

        spatial_info = np.array([
            _skaggs_spatial_info(rate_maps[i], occupancy) for i in range(N)
        ])
        mean_si = float(np.mean(spatial_info))
        median_si = float(np.median(spatial_info))

        # ---- Place field coverage ----
        # Fraction of position bins with at least one neuron having rate > 2× mean
        peak_thresh = 2.0 * np.mean(rate_maps) if np.mean(rate_maps) > 0 else 0
        has_pf = np.any(rate_maps > peak_thresh, axis=0)
        track_coverage = float(np.mean(has_pf))

        # ---- Lap counts (from dec_results if available) ----
        n_laps_total = n_laps_R = n_laps_L = np.nan
        mean_Ksum = median_Ksum = np.nan
        if dec_results and mouse in dec_results:
            dr = dec_results[mouse]
            # Try appropriate within-LT1 result
            if use_mapped:
                dr_keys = ("within_LT1_by_dir_mapped", "within_LT1_by_dir")
            else:
                dr_keys = ("within_LT1_by_dir_full", "within_LT1_by_dir")
            for key in dr_keys:
                blk = dr.get(key)
                if isinstance(blk, dict) and blk.get("ok", False):
                    n_laps_total = blk.get("n_laps_total", np.nan)
                    n_laps_R = blk.get("n_laps_R", np.nan)
                    n_laps_L = blk.get("n_laps_L", np.nan)
                    break

            # Ksum: population spike counts per decoded time chunk
            Ksums = []
            for key in dr_keys:
                blk = dr.get(key)
                if not isinstance(blk, dict):
                    continue
                for d_label in list(blk.keys()):
                    dblk = blk.get(d_label)
                    if not isinstance(dblk, dict) or not dblk.get("ok", False):
                        continue
                    for fold in ("train_to_test",):
                        fblk = dblk.get(fold)
                        if isinstance(fblk, dict) and "out" in fblk:
                            ks = fblk["out"].get("Ksum")
                            if ks is not None:
                                Ksums.append(np.asarray(ks, float))
            if Ksums:
                all_ks = np.concatenate(Ksums)
                mean_Ksum = float(np.mean(all_ks))
                median_Ksum = float(np.median(all_ks))

        rows.append({
            "mouse": mouse,
            "group": g,
            "n_neurons": N,
            "n_frames": T,
            "n_frames_speed": n_speed,
            "duration_sec": round(duration_sec, 1),
            "mean_event_rate": round(mean_rate, 4),
            "median_event_rate": round(median_rate, 4),
            "frac_active_neurons": round(frac_active, 3),
            "mean_spatial_info": round(mean_si, 4),
            "median_spatial_info": round(median_si, 4),
            "n_laps_total": n_laps_total,
            "n_laps_R": n_laps_R,
            "n_laps_L": n_laps_L,
            "mean_speed": round(mean_speed, 2) if np.isfinite(mean_speed) else np.nan,
            "median_speed": round(median_speed, 2) if np.isfinite(median_speed) else np.nan,
            "mean_Ksum": round(mean_Ksum, 2) if np.isfinite(mean_Ksum) else np.nan,
            "median_Ksum": round(median_Ksum, 2) if np.isfinite(median_Ksum) else np.nan,
            "track_coverage": round(track_coverage, 3),
        })

    df = pd.DataFrame(rows)
    return df


def run_neural_diagnostics_tests(df_diag):
    """
    Run Kruskal-Wallis tests on each diagnostic metric to check for
    group differences (mCherry vs hM3D vs hM4D) in LT1.

    Returns
    -------
    df_tests : pd.DataFrame with columns metric, H, p, significant
    """
    metrics = [
        "n_neurons", "mean_event_rate", "median_event_rate",
        "frac_active_neurons", "mean_spatial_info", "median_spatial_info",
        "n_laps_total", "n_laps_R", "n_laps_L",
        "mean_speed", "median_speed",
        "mean_Ksum", "median_Ksum",
        "track_coverage", "duration_sec", "n_frames_speed",
    ]
    from scipy.stats import kruskal

    test_rows = []
    for metric in metrics:
        vals_per_group = []
        for g in GROUPS:
            v = df_diag.loc[df_diag["group"] == g, metric].dropna().values
            vals_per_group.append(v)

        # Need at least 2 groups with ≥2 observations
        valid = [v for v in vals_per_group if len(v) >= 2]
        if len(valid) < 2:
            test_rows.append({"metric": metric, "H": np.nan, "p": np.nan, "significant": ""})
            continue

        # Guard against all-identical values (scipy raises ValueError)
        all_vals = np.concatenate(valid)
        if np.ptp(all_vals) == 0:
            test_rows.append({"metric": metric, "H": 0.0, "p": 1.0, "significant": ""})
            continue

        H, p = kruskal(*valid)
        sig = "*" if p < 0.05 else ("†" if p < 0.10 else "")
        test_rows.append({"metric": metric, "H": round(H, 3), "p": round(p, 4), "significant": sig})

    return pd.DataFrame(test_rows)


def plot_neural_diagnostics(
    df_diag,
    df_tests,
    *,
    PLOTS_DIR,
    out_name="LT1_neural_diagnostics.png",
):
    """
    Multi-panel strip + box plots showing group distributions for key
    neural-data metrics in LT1, with Kruskal-Wallis p-values.
    """
    out_dir = os.path.join(PLOTS_DIR, "neural_diagnostics")
    os.makedirs(out_dir, exist_ok=True)
    savefile = os.path.join(out_dir, out_name)

    metrics_to_plot = [
        ("n_neurons",          "Number of neurons"),
        ("mean_event_rate",    "Mean event rate\n(events/s)"),
        ("mean_spatial_info",  "Mean spatial info\n(bits/event)"),
        ("mean_Ksum",          "Mean pop. activity\nper chunk (Ksum)"),
        ("n_laps_total",       "Total laps"),
        ("mean_speed",         "Mean running speed\n(cm/s)"),
        ("frac_active_neurons","Fraction active\nneurons"),
        ("track_coverage",     "Track coverage\n(frac bins with PF)"),
    ]

    n_panels = len(metrics_to_plot)
    ncols = 4
    nrows = int(np.ceil(n_panels / ncols))

    fig, axes = plt.subplots(nrows, ncols, figsize=(4.2 * ncols, 4.0 * nrows), dpi=160)
    axes = np.atleast_2d(axes)

    group_colors = {"mCherry": "grey", "hM3D": "red", "hM4D": "blue"}
    group_order = list(GROUPS)

    for idx, (metric, ylabel) in enumerate(metrics_to_plot):
        r, c = divmod(idx, ncols)
        ax = axes[r, c]

        for gi, g in enumerate(group_order):
            vals = df_diag.loc[df_diag["group"] == g, metric].dropna().values
            # jittered strip
            jitter = np.random.default_rng(42).uniform(-0.15, 0.15, size=len(vals))
            ax.scatter(
                np.full(len(vals), gi) + jitter, vals,
                color=group_colors[g], alpha=0.7, s=40, edgecolors="k", linewidths=0.5,
                zorder=3,
            )
            # box summary
            if len(vals) >= 2:
                bp = ax.boxplot(
                    [vals], positions=[gi], widths=0.4,
                    showfliers=False, patch_artist=True,
                    boxprops=dict(facecolor=group_colors[g], alpha=0.25),
                    medianprops=dict(color="black", linewidth=1.5),
                    whiskerprops=dict(color="black"),
                    capprops=dict(color="black"),
                )

        # Kruskal-Wallis p-value
        test_row = df_tests.loc[df_tests["metric"] == metric]
        if not test_row.empty:
            p_val = test_row["p"].values[0]
            if np.isfinite(p_val):
                ax.set_title(f"KW p={p_val:.3f}", fontsize=10,
                             color="red" if p_val < 0.05 else ("orange" if p_val < 0.10 else "black"))

        ax.set_xticks(range(len(group_order)))
        ax.set_xticklabels([GROUP_LABELS[g] for g in group_order], fontsize=11)
        ax.set_ylabel(ylabel, fontsize=10)
        ax.grid(True, axis="y", alpha=0.25)

    # hide unused axes
    for idx in range(n_panels, nrows * ncols):
        r, c = divmod(idx, ncols)
        axes[r, c].set_visible(False)

    fig.suptitle("LT1 (pre-CNO) neural diagnostics by group", fontsize=14, y=1.01)
    plt.tight_layout()
    fig.savefig(savefile, bbox_inches="tight")
    plt.close(fig)
    print(f"[SAVED] {savefile}")
    return savefile

def _format_lt_contrast_title(key: str) -> str:
    """LaTeX-formatted title for LT decoder contrasts, split onto two lines."""
    title = str(key)
    title = title.replace("Within LT1", r"$\mathrm{LT1}_{\mathrm{within}}$")
    title = title.replace("Within LT2", r"$\mathrm{LT2}_{\mathrm{within}}$")
    title = title.replace("LT1 to LT2", r"LT1 $\rightarrow$ LT2")
    parts = title.split(" − ", 1)
    if len(parts) == 2:
        return f"{parts[0]}\n− {parts[1]}"
    return title


# -------------------------------------------------------------------
# R lmer + emmeans via subprocess
# -------------------------------------------------------------------

def _find_rscript() -> str:
    """Locate Rscript with lme4+lmerTest+emmeans. Returns absolute path or raises."""
    candidates = []

    # Prefer Rscript on PATH (works for conda, Linux/macOS, and Windows PATH setups).
    rscript_on_path = shutil.which("Rscript")
    if rscript_on_path:
        candidates.append(rscript_on_path)

    # Windows default install locations.
    candidates.extend(sorted(
        glob.glob(r"C:\Program Files\R\R-*\bin\Rscript.exe"), reverse=True))

    # Common conda locations when PATH is not populated as expected.
    conda_prefix = os.environ.get("CONDA_PREFIX")
    if conda_prefix:
        candidates.extend([
            os.path.join(conda_prefix, "bin", "Rscript"),
            os.path.join(conda_prefix, "Scripts", "Rscript.exe"),
        ])

    # Deduplicate while preserving order.
    seen = set()
    candidates = [c for c in candidates if not (c in seen or seen.add(c))]

    for c in candidates:
        if not os.path.isfile(c):
            continue
        try:
            proc = subprocess.run(
                [c, "-e",
                 "library(lme4); library(lmerTest); library(emmeans); cat('OK')"],
                capture_output=True, text=True, timeout=30)
            if "OK" in proc.stdout:
                return c
        except Exception:
            continue
    raise FileNotFoundError(
        "No Rscript found with lme4+lmerTest+emmeans installed. "
        "Install R in the active environment and run: "
        "install.packages(c('lme4','lmerTest','emmeans'))")


_R_LMER_EMMEANS_SCRIPT = r"""
library(lme4)
library(lmerTest)
library(emmeans)

args  <- commandArgs(trailingOnly = TRUE)
input_csv  <- args[1]
output_dir <- args[2]
y_col      <- args[3]

d <- read.csv(input_csv, stringsAsFactors = FALSE)
d$group     <- factor(d$group,     levels = c("mCherry", "hM3D", "hM4D"))
d$condition <- factor(d$condition, levels = c("within_LT1", "within_LT2", "LT1_to_LT2"))
d$mouse     <- factor(d$mouse)
names(d)[names(d) == y_col] <- "y"

# ---------- fit model ----------
m <- lmer(y ~ group * condition + (1 | mouse), data = d, REML = TRUE)

# 1. Model summary
sink(file.path(output_dir, "model_summary.txt"))
cat("Formula: y ~ group * condition + (1|mouse)\n")
cat("y_col:", y_col, "\n\n")
print(summary(m))
sink()

# 2. Type III ANOVA (Satterthwaite)
aov <- anova(m, type = 3, ddf = "Satterthwaite")
write.csv(as.data.frame(aov), file.path(output_dir, "anova_type3.csv"))

# 3. Marginal means per group x condition
emm <- emmeans(m, ~ group * condition)
write.csv(as.data.frame(summary(emm)),
          file.path(output_dir, "emmeans.csv"), row.names = FALSE)

# 4. Within-group condition contrasts (vs within_LT1 reference)
emm_cg <- emmeans(m, ~ condition | group)
wg      <- contrast(emm_cg, method = "trt.vs.ctrl", ref = "within_LT1")
write.csv(as.data.frame(summary(wg)),
          file.path(output_dir, "contrasts_within_group.csv"), row.names = FALSE)

# 5. Simple between-group pairwise within each condition (Holm within condition)
emm_gc  <- emmeans(m, ~ group | condition)
bg_abs  <- pairs(emm_gc, adjust = "holm")
write.csv(as.data.frame(summary(bg_abs)),
          file.path(output_dir, "pairwise_abs.csv"), row.names = FALSE)

# 6. Interaction contrasts: group pairwise x condition trt.vs.ctrl
#    (Holm across all 6 contrasts)
ic <- contrast(emm, interaction = list(
        condition = "trt.vs.ctrl", group = "pairwise"))
ic_df <- as.data.frame(summary(ic, adjust = "none"))
ic_df$p_holm <- p.adjust(ic_df$p.value, method = "holm")
write.csv(ic_df, file.path(output_dir, "contrasts_interaction.csv"),
          row.names = FALSE)

cat("R_LMER_EMMEANS_DONE\n")
"""


def build_lt_mixedlm_dataframe(
    PLOTS_DIR: str,
    session_str: str,
    mapping: str,
    use_median: bool = False,
    use_pct: bool = False,
    stat_label_override=None,
) -> pd.DataFrame:
    """Read mouse-level summary CSVs and return a clean DataFrame for lmer.

    Columns: mouse, group, condition, {err_col}
    """
    if use_pct:
        err_col = "pct_correct"
    else:
        err_col = "median_err" if use_median else "mean_err"

    stat_label = stat_label_override or ("median" if use_median else "mean")
    save_path = os.path.join(
        PLOTS_DIR, f"summary_{session_str}_mapping_{mapping}_{stat_label}")
    mixedlm_dir = os.path.join(
        PLOTS_DIR, f"mixedlm_{session_str}_mapping_{mapping}_{stat_label}")

    df_w1 = pd.read_csv(
        os.path.join(save_path, "mouse_level_summary_within_LT1_all.csv")
    )[["mouse", "group", err_col]].copy()
    df_w1["condition"] = "within_LT1"

    df_w2 = pd.read_csv(
        os.path.join(save_path, "mouse_level_summary_within_LT2_all.csv")
    )[["mouse", "group", err_col]].copy()
    df_w2["condition"] = "within_LT2"

    _df_ac_all = pd.read_csv(
        os.path.join(mixedlm_dir, "mixedlm_mouse_level_summary.csv")
    )
    df_ac = _df_ac_all.loc[
        _df_ac_all["condition"] == "LT1_to_LT2",
        ["mouse", "group", err_col],
    ].copy()
    df_ac["condition"] = "LT1_to_LT2"

    df = pd.concat([df_w1, df_w2, df_ac], ignore_index=True)
    df["mouse"] = df["mouse"].astype(str)
    df["group"] = df["group"].astype(str)
    df["condition"] = df["condition"].astype(str)

    n_before = len(df)
    df = df.dropna(subset=[err_col]).reset_index(drop=True)
    if len(df) < n_before:
        print(f"[build_lt_mixedlm_dataframe] Dropped "
              f"{n_before - len(df)} NaN rows → {len(df)} remaining")
    return df


def run_r_lmer_emmeans(
    df: pd.DataFrame,
    y_col: str,
    save_dir: str,
) -> dict:
    """Run R lmer + emmeans via subprocess.  Returns dict of DataFrames.

    Parameters
    ----------
    df : DataFrame
        Must have columns: mouse, group, condition, {y_col}.
    y_col : str
        Name of the response column (e.g. "mean_err").
    save_dir : str
        Directory for R outputs (CSVs, model_summary.txt).

    Returns
    -------
    dict with keys:
        emmeans, contrasts_within, pairwise_abs, contrasts_interaction,
        anova, model_summary_path, save_dir
    """
    import subprocess, tempfile, shutil

    os.makedirs(save_dir, exist_ok=True)
    rscript = _find_rscript()

    # Write data to temp CSV
    tmp_csv = os.path.join(save_dir, "_input_data.csv")
    df.to_csv(tmp_csv, index=False)

    # Write R script to temp file
    r_script_path = os.path.join(save_dir, "_lmer_emmeans.R")
    with open(r_script_path, "w", encoding="utf-8") as fh:
        fh.write(_R_LMER_EMMEANS_SCRIPT)

    # Run R
    cmd = [rscript, "--vanilla", r_script_path, tmp_csv, save_dir, y_col]
    print(f"[R] Running: {' '.join(cmd)}")
    proc = subprocess.run(
        cmd, capture_output=True, text=True, timeout=120)

    if proc.returncode != 0:
        print(f"[R STDERR]\n{proc.stderr}")
        raise RuntimeError(
            f"Rscript failed (exit {proc.returncode}):\n{proc.stderr[:2000]}")
    if "R_LMER_EMMEANS_DONE" not in proc.stdout:
        print(f"[R STDOUT]\n{proc.stdout}")
        print(f"[R STDERR]\n{proc.stderr}")
        raise RuntimeError("R script did not complete successfully.")

    print(f"[R] lmer + emmeans finished OK")
    if proc.stderr:
        # Print just warnings (normal for lmerTest)
        for line in proc.stderr.strip().splitlines():
            if "Warning" in line or "warning" in line:
                print(f"  [R warn] {line.strip()}")

    # Parse outputs
    results = {"save_dir": save_dir}
    results["emmeans"] = pd.read_csv(os.path.join(save_dir, "emmeans.csv"))
    results["contrasts_within"] = pd.read_csv(
        os.path.join(save_dir, "contrasts_within_group.csv"))
    results["pairwise_abs"] = pd.read_csv(
        os.path.join(save_dir, "pairwise_abs.csv"))
    results["contrasts_interaction"] = pd.read_csv(
        os.path.join(save_dir, "contrasts_interaction.csv"))
    results["anova"] = pd.read_csv(
        os.path.join(save_dir, "anova_type3.csv"))
    results["model_summary_path"] = os.path.join(
        save_dir, "model_summary.txt")

    return results


def plot_lt_decoder_emmeans(
    r_results: dict,
    save_dir: str,
    model_tag: str,
    use_median: bool = False,
    y_col=None,
    metric_label=None,
):
    """Paper-style LT decoder plots from R emmeans output.

    Produces:
      - Panel A (3-subplot): emmeans per condition with between-group brackets
      - Contrast figure (2-row): condition contrasts with within-group stars
        and between-group interaction brackets (Holm-corrected)
    """
    stat_label = metric_label or ("median" if use_median else "mean")
    _is_pct = (y_col == "pct_correct") if y_col else False
    file_prefix = f"lt_decoder_{model_tag}"
    os.makedirs(save_dir, exist_ok=True)

    emm = r_results["emmeans"]
    wg  = r_results["contrasts_within"]
    pw  = r_results["pairwise_abs"]
    ic  = r_results["contrasts_interaction"]

    groups = GROUPS
    n_groups = len(groups)
    x0 = np.arange(n_groups)
    width = 0.55
    col = _PAPER_COLORS
    col_alpha = 0.7

    # ------------------------------------------------------------------
    # Panel A: absolute emmeans (3 subplots)
    # ------------------------------------------------------------------
    panel_A_conds = [
        ("within_LT1", "Within LT1"),
        ("within_LT2", "Within LT2"),
        ("LT1_to_LT2", "LT1 to LT2"),
    ]

    figA = plt.figure(figsize=(9.4, 5.4), dpi=160)
    gsA = GridSpec(1, 3, figure=figA, wspace=0.24)
    axA = [figA.add_subplot(gsA[0, i]) for i in range(3)]

    for ci, (cond, title) in enumerate(panel_A_conds):
        ax = axA[ci]
        means, sems = [], []
        for g in groups:
            row = emm[(emm["group"] == g) & (emm["condition"] == cond)]
            means.append(float(row["emmean"].iloc[0]))
            sems.append(float(row["SE"].iloc[0]))

        means_arr = np.array(means)
        sems_arr = np.array(sems)
        yerr = one_sided_yerr_by_sign(means_arr, sems_arr)
        bars = ax.bar(x0, means_arr, width=width, yerr=yerr, capsize=3,
                      color=[col[g] for g in groups],
                      edgecolor="black", linewidth=0.6,
                      error_kw=dict(lw=1.5, capthick=1.5))
        for b in bars:
            b.set_alpha(col_alpha)

        # Between-group brackets from pairwise_abs (Holm-corrected within cond)
        pw_cond = pw[pw["condition"] == cond]
        if not pw_cond.empty:
            _g2i = {g: i for i, g in enumerate(groups)}
            tops = np.where(means_arr >= 0, means_arr + sems_arr, means_arr)
            _, y_ax_top = ax.get_ylim()
            y_max = max(np.nanmax(tops), y_ax_top)
            y_rng = max(abs(y_max), 1.0)
            bdy = 0.025 * y_rng
            bgap = 2.4 * bdy
            by = y_ax_top - 0.02 * y_rng

            for _, r in pw_cond.iterrows():
                # Parse group pair from contrast string "mCherry - hM3D"
                pair_str = str(r["contrast"])
                pair_parts = [s.strip() for s in pair_str.split(" - ")]
                if len(pair_parts) != 2:
                    continue
                g1, g2 = pair_parts[0], pair_parts[1]
                if g1 not in _g2i or g2 not in _g2i:
                    continue
                p_val = float(r["p.value"])
                star, fs = _p_to_star(p_val, p_val)
                if star is None:
                    continue
                x1, x2 = x0[_g2i[g1]], x0[_g2i[g2]]
                ax.plot([x1, x1, x2, x2], [by, by + bdy, by + bdy, by],
                        color="#333333", lw=0.7)
                ax.text((x1 + x2) / 2, by + bdy + 0.001 * y_rng, star,
                        ha="center", va="bottom", fontsize=fs, color="#333333")
                by += bgap
            _pad_axes_for_stars(ax)

        ax.set_title(title, fontsize=13)
        ax.set_xticks(x0)
        ax.set_xticklabels([GROUP_LABELS[g] for g in groups], fontsize=12)
        ax.set_ylabel(
            ("Fraction correct (< threshold)"
             if _is_pct else
             f"Predicted {stat_label} decoding error ({_LT_1D_DISTANCE_UNIT})")
            if ci == 0 else "", fontsize=12)
        ax.axhline(0, linewidth=0.8)
        ax.grid(True, axis="y", alpha=0.25)
        ax.tick_params(axis="y", labelsize=11)

    figA.tight_layout()
    for ext in (".png", ".svg"):
        figA.savefig(
            os.path.join(save_dir, f"{file_prefix}_panelA_{stat_label}{ext}"),
            dpi=300, bbox_inches="tight")
    plt.close(figA)
    print(f"[SAVED] {file_prefix}_panelA_{stat_label}.png/.svg")

    # ------------------------------------------------------------------
    # Contrast figure: 2-row stacked
    #   Row 0: Within LT2 − Within LT1
    #   Row 1: (LT1 to LT2) − Within LT1
    # ------------------------------------------------------------------
    contrast_keys = [
        ("within_LT2", "Within LT2 − Within LT1"),
        ("LT1_to_LT2", "(LT1 to LT2) − Within LT1"),
    ]

    figC, axes_c = plt.subplots(2, 1, figsize=(2.8, 6.0), dpi=160)

    for ri, (cond_target, raw_title) in enumerate(contrast_keys):
        ax = axes_c[ri]
        ests, ses, ps_raw = [], [], []
        for g in groups:
            row = wg[(wg["group"] == g) &
                     (wg["contrast"].str.contains(cond_target, na=False))]
            if row.empty:
                # Try matching by the condition label pattern
                row = wg[(wg["group"] == g)]
                row = row[row.index == ri + ri * (len(groups) - 1)]
            ests.append(float(row["estimate"].iloc[0]))
            ses.append(float(row["SE"].iloc[0]))
            ps_raw.append(float(row["p.value"].iloc[0]))

        ests_arr = np.array(ests, float)
        ses_arr = np.array(ses, float)

        yerr = one_sided_yerr_by_sign(ests_arr, ses_arr)
        bars = ax.bar(x0, ests_arr, width=width, yerr=yerr, capsize=3,
                      color=[col[g] for g in groups],
                      edgecolor="black", linewidth=0.6,
                      error_kw=dict(lw=1.5, capthick=1.5))
        for b in bars:
            b.set_alpha(col_alpha)

        # Stars on bars: within-group t-test p-values (uncorrected)
        y_rng = max(np.nanmax(np.abs(ests_arr)), 1.0)
        bump = 0.03 * y_rng
        for i in range(n_groups):
            star, fs = _p_to_star(ps_raw[i], ps_raw[i])
            if star is None:
                continue
            if ests_arr[i] >= 0:
                y = ests_arr[i] + ses_arr[i] + bump
                va = "bottom"
            else:
                y = ests_arr[i] - ses_arr[i] - bump
                va = "top"
            ax.text(i, y, star, ha="center", va=va, fontsize=fs,
                    color="black")
        _pad_axes_for_stars(ax)

        # Between-group interaction brackets (Holm-corrected)
        # Filter interaction contrasts for this condition contrast
        ic_sub = ic[ic.apply(
            lambda r: cond_target in str(r.values), axis=1)]
        if not ic_sub.empty:
            _g2i = {g: i for i, g in enumerate(groups)}
            tops = np.array([
                e + s if e >= 0 else e - s
                for e, s in zip(ests_arr, ses_arr)])
            _, y_ax_top = ax.get_ylim()
            y_max = max(np.nanmax(tops), y_ax_top)
            y_rng2 = max(abs(y_max), 1.0)
            bdy = 0.025 * y_rng2
            bgap = 2.4 * bdy
            by = y_ax_top - 0.02 * y_rng2

            for _, r in ic_sub.iterrows():
                p_holm = float(r["p_holm"])
                p_raw_ic = float(r["p.value"])
                if not np.isfinite(p_holm):
                    continue
                star, fs = _p_to_star(p_holm, p_raw_ic)
                if star is None:
                    continue
                # Parse group pair from row
                gp_str = str(r.get("group_pairwise",
                                   r.get("group", "")))
                gp_parts = [s.strip() for s in gp_str.split(" - ")]
                if len(gp_parts) != 2:
                    continue
                g1, g2 = gp_parts[0], gp_parts[1]
                if g1 not in _g2i or g2 not in _g2i:
                    continue
                x1, x2 = x0[_g2i[g1]], x0[_g2i[g2]]
                ax.plot([x1, x1, x2, x2],
                        [by, by + bdy, by + bdy, by],
                        color="#333333", lw=0.7)
                ax.text((x1 + x2) / 2, by + bdy + 0.001 * y_rng2,
                        star, ha="center", va="bottom",
                        fontsize=fs, color="#333333")
                by += bgap
            _pad_axes_for_stars(ax)

        ax.set_title(_format_lt_contrast_title(raw_title), fontsize=10)
        ax.set_xticks(x0)
        ax.set_xticklabels([GROUP_LABELS[g] for g in groups], fontsize=11)
        ax.set_ylabel(
            "Contrast vs Within LT1 (fraction)"
            if _is_pct else
            f"Contrast vs Within LT1 ({_LT_1D_DISTANCE_UNIT})", fontsize=11)
        ax.axhline(0, linewidth=0.8)
        ax.grid(True, axis="y", alpha=0.25)
        ax.tick_params(axis="y", labelsize=10)

    for ax in axes_c:
        if hasattr(ax, "set_box_aspect"):
            ax.set_box_aspect(2.0)
    figC.tight_layout(h_pad=1.2)
    for ext in (".png", ".svg"):
        figC.savefig(
            os.path.join(save_dir,
                         f"{file_prefix}_contrasts_{stat_label}{ext}"),
            dpi=300, bbox_inches="tight")
    plt.close(figC)
    print(f"[SAVED] {file_prefix}_contrasts_{stat_label}.png/.svg")

    # ------------------------------------------------------------------
    # METHODS.txt
    # ------------------------------------------------------------------
    methods_path = os.path.join(save_dir, f"{file_prefix}_METHODS.txt")
    with open(methods_path, "w", encoding="utf-8") as fh:
        fh.write("Statistical analysis: Linear mixed-effects model\n")
        fh.write("=" * 50 + "\n\n")
        fh.write("Model: lmer(y ~ group * condition + (1|mouse))\n")
        if _is_pct:
            fh.write("  y = proportion of time bins with |error| < threshold "
                     "(pct_correct)\n")
        else:
            fh.write("  y = " + ("median" if use_median else "mean")
                     + " absolute decoding error (cm)\n")
        fh.write("  group: mCherry (control), hM3D (excitatory), "
                 "hM4D (inhibitory)\n")
        fh.write("  condition: within_LT1 (ref), within_LT2, "
                 "LT1_to_LT2\n")
        fh.write("  random intercept per mouse\n\n")
        fh.write("Fitted with R lme4::lmer (REML) + lmerTest "
                 "(Satterthwaite df).\n")
        fh.write("Post-hoc: emmeans package.\n")
        fh.write("  - Marginal means: emmeans(m, ~ group * condition)\n")
        fh.write("  - Within-group contrasts: condition effects vs "
                 "within_LT1 (trt.vs.ctrl)\n")
        fh.write("  - Between-group (Panel A): pairwise group diffs "
                 "within each condition, Holm-corrected within condition\n")
        fh.write("  - Interaction contrasts: group pairwise × condition "
                 "trt.vs.ctrl, Holm-corrected across all 6 contrasts\n")
    print(f"[SAVED] {file_prefix}_METHODS.txt")

    return {"save_dir": save_dir}


# ===================================================================
# Zone-level lmer analysis  (group × zone within each condition)
# ===================================================================

# Collapsed zone scheme: drop endpoints (ambiguous decoding due to
# flickering between arms); merge Upper horiz + Lower horiz → "Arms".
_ZONE_COLLAPSE = {
    "Upper horiz": "Arms",
    "Lower horiz": "Arms",
    "Junction":    "Junction",
}
_COLLAPSED_ZONE_ORDER = ["Arms", "Junction"]


def _collapse_zone_df(df_raw: "pd.DataFrame", y_col: str) -> "pd.DataFrame":
    """Collapse 5-zone CSV into 2 zones (Arms, Junction).

    'Arms' is the n_frames-weighted mean of Upper horiz + Lower horiz.
    Endpoints are dropped entirely.
    """
    df = df_raw.copy()
    if "zone_label" in df.columns:
        df = df.rename(columns={"zone_label": "zone"})
    # Map zone labels and drop unmapped (endpoints)
    df["zone"] = df["zone"].map(_ZONE_COLLAPSE)
    df = df.dropna(subset=["zone", y_col]).reset_index(drop=True)

    # Weighted collapse: Arms = weighted-mean of Upper horiz + Lower horiz
    # Junction passes through unchanged (single row per mouse/cond already)
    agg_rows = []
    for (mouse, group, cond, zone), sub in df.groupby(
            ["mouse", "group", "condition", "zone"], sort=False):
        nf = sub["n_frames"].values.astype(float)
        total_n = nf.sum()
        if total_n == 0:
            continue
        wm = float(np.average(sub[y_col].values, weights=nf))
        row = {"mouse": mouse, "group": group, "condition": cond,
               "zone": zone, y_col: wm, "n_frames": int(total_n)}
        # Carry along other numeric columns if present
        for extra in ("mean_err", "median_err", "pct_correct"):
            if extra != y_col and extra in sub.columns:
                row[extra] = float(np.average(sub[extra].values, weights=nf))
        agg_rows.append(row)
    return pd.DataFrame(agg_rows)


_R_ZONE_LMER_SCRIPT = r"""
library(lme4)
library(lmerTest)
library(emmeans)

args       <- commandArgs(trailingOnly = TRUE)
input_csv  <- args[1]
output_dir <- args[2]
y_col      <- args[3]

d <- read.csv(input_csv, stringsAsFactors = FALSE)
d$group <- factor(d$group, levels = c("mCherry", "hM3D", "hM4D"))
d$zone  <- factor(d$zone,  levels = c("Arms", "Junction"))
d$mouse <- factor(d$mouse)

conditions <- unique(as.character(d$condition))

for (cond in conditions) {
    ds <- d[d$condition == cond, ]
    if (nrow(ds) < 6) next

    cond_dir <- file.path(output_dir, cond)
    dir.create(cond_dir, showWarnings = FALSE, recursive = TRUE)

    fml <- as.formula(paste0(y_col, " ~ group * zone + (1 | mouse)"))

    m <- lmer(fml, data = ds, REML = TRUE)

    # Model summary
    sink(file.path(cond_dir, "model_summary.txt"))
    cat("Condition:", cond, "\n")
    cat("Formula:", deparse(fml), "\n\n")
    print(summary(m))
    sink()

    # Type III ANOVA
    aov <- anova(m, type = 3, ddf = "Satterthwaite")
    write.csv(as.data.frame(aov), file.path(cond_dir, "anova_type3.csv"))

    # Emmeans: group x zone
    emm <- emmeans(m, ~ group * zone)
    write.csv(as.data.frame(summary(emm)),
              file.path(cond_dir, "emmeans.csv"), row.names = FALSE)

    # Between-group pairwise at each zone (Holm within zone)
    emm_gz <- emmeans(m, ~ group | zone)
    pw <- pairs(emm_gz, adjust = "holm")
    write.csv(as.data.frame(summary(pw)),
              file.path(cond_dir, "pairwise_by_zone.csv"), row.names = FALSE)

    # Junction-only pairwise (planned contrast)
    emm_junc <- emmeans(m, ~ group,
                        at = list(zone = "Junction"))
    pw_junc <- pairs(emm_junc, adjust = "holm")
    write.csv(as.data.frame(summary(pw_junc)),
              file.path(cond_dir, "pairwise_junction.csv"), row.names = FALSE)

    # Interaction contrasts: group pairwise x zone contrast
    ic <- contrast(emm, interaction = list(
          zone = "pairwise", group = "pairwise"))
    ic_df <- as.data.frame(summary(ic, adjust = "none"))
    ic_df$p_holm <- p.adjust(ic_df$p.value, method = "holm")
    write.csv(ic_df, file.path(cond_dir, "interaction_contrasts.csv"),
              row.names = FALSE)
}

cat("R_ZONE_LMER_DONE\n")
"""


def run_lt_zone_lmer_analysis(
    zone_csv_path: str,
    save_dir: str,
    *,
    use_PCT_error: bool = True,
    auto_close: bool = True,
) -> dict:
    """Run per-condition zone-level lmer (Arms vs Junction) for every
    combination of metric and stat.

    When *use_PCT_error* is True the dependent variable is ``pct_correct``
    (fraction of frames decoded within the threshold).
    When False, the analysis is run twice: once for ``mean_err`` and once
    for ``median_err``.

    Returns dict  ``{metric_label: {condition: {key: DataFrame, ...}, ...}}``.
    """
    import subprocess

    os.makedirs(save_dir, exist_ok=True)
    rscript = _find_rscript()

    df_raw = pd.read_csv(zone_csv_path)
    if "zone_label" in df_raw.columns:
        df_raw = df_raw.rename(columns={"zone_label": "zone"})

    # Decide which metrics to run
    # Always run mean and median error; add pct_correct when requested.
    metric_runs = [("mean_err", "mean"), ("median_err", "median")]
    if use_PCT_error:
        metric_runs.append(("pct_correct", "pct_correct"))

    all_results = {}  # metric_label → {cond → {key: df}}

    for y_col, metric_label in metric_runs:
        if y_col not in df_raw.columns:
            print(f"[ZONE-LMER] Column {y_col!r} not in CSV, skipping")
            continue

        metric_dir = os.path.join(save_dir, metric_label)
        os.makedirs(metric_dir, exist_ok=True)

        # Collapse to 2 zones
        df_collapsed = _collapse_zone_df(df_raw, y_col)
        if df_collapsed.empty:
            print(f"[ZONE-LMER] No data after collapse for {y_col}")
            continue

        tmp_csv = os.path.join(metric_dir, "_zone_input.csv")
        df_collapsed.to_csv(tmp_csv, index=False)

        r_path = os.path.join(metric_dir, "_zone_lmer.R")
        with open(r_path, "w", encoding="utf-8") as fh:
            fh.write(_R_ZONE_LMER_SCRIPT)

        cmd = [rscript, "--vanilla", r_path, tmp_csv, metric_dir, y_col]
        print(f"[R-ZONE] Running ({metric_label}): {' '.join(cmd)}")
        proc = subprocess.run(cmd, capture_output=True, text=True,
                              timeout=120)

        if proc.returncode != 0:
            print(f"[R-ZONE STDERR]\n{proc.stderr}")
            raise RuntimeError(
                f"Zone lmer R script failed (exit {proc.returncode}):\n"
                + proc.stderr[:2000])
        if "R_ZONE_LMER_DONE" not in proc.stdout:
            print(f"[R-ZONE STDOUT]\n{proc.stdout}")
            print(f"[R-ZONE STDERR]\n{proc.stderr}")
            raise RuntimeError("Zone lmer R script did not complete.")

        print(f"[R-ZONE] lmer finished OK  ({metric_label})")
        if proc.stderr:
            for line in proc.stderr.strip().splitlines():
                if "Warning" in line or "warning" in line:
                    print(f"  [R-ZONE warn] {line.strip()}")

        # Parse per-condition outputs
        results = {}
        for cond in df_collapsed["condition"].unique():
            cond_dir = os.path.join(metric_dir, cond)
            if not os.path.isdir(cond_dir):
                continue
            r = {}
            for key, fname in [
                ("emmeans", "emmeans.csv"),
                ("pairwise_by_zone", "pairwise_by_zone.csv"),
                ("pairwise_junction", "pairwise_junction.csv"),
                ("interaction", "interaction_contrasts.csv"),
                ("anova", "anova_type3.csv"),
            ]:
                p = os.path.join(cond_dir, fname)
                if os.path.isfile(p):
                    r[key] = pd.read_csv(p)
            r["model_summary_path"] = os.path.join(
                cond_dir, "model_summary.txt")
            results[cond] = r

        all_results[metric_label] = results

        # Plot
        plot_lt_zone_emmeans(
            results, metric_dir,
            y_col=y_col, metric_label=metric_label,
            auto_close=auto_close)

    # Methods text
    _write_zone_lmer_methods(save_dir, use_PCT_error)

    return all_results


def _write_zone_lmer_methods(save_dir: str, use_PCT_error: bool):
    meth_path = os.path.join(save_dir, "zone_lmer_METHODS.txt")
    dv_parts = ["mean_err = mean absolute decoding error (cm)",
                "median_err = median absolute decoding error (cm)"]
    if use_PCT_error:
        dv_parts.append("pct_correct = proportion of decoded frames with "
                        "|error| < threshold (cm)")
    dv_desc = "; ".join(dv_parts)
    with open(meth_path, "w", encoding="utf-8") as fh:
        fh.write("Zone-level linear mixed-effects analysis\n")
        fh.write("=" * 50 + "\n\n")
        fh.write("  Zone scheme: endpoints dropped; Upper horiz + "
                 "Lower horiz merged into 'Arms'.\n")
        fh.write("  Two zones analysed: Arms, Junction.\n\n")
        fh.write("Per-condition model:\n")
        fh.write("  lmer(y ~ group * zone + (1|mouse))\n\n")
        fh.write(f"  DV: {dv_desc}\n")
        fh.write("  group: mCherry (control), hM3D (excitatory), "
                 "hM4D (inhibitory)\n")
        fh.write("  zone: Arms, Junction\n")
        fh.write("  random intercept per mouse\n\n")
        fh.write("Post-hoc:\n")
        fh.write("  - EMMs: emmeans(m, ~ group * zone)\n")
        fh.write("  - Between-group at each zone: pairwise, Holm\n")
        fh.write("  - Junction-only between-group pairwise (planned "
                 "contrast), Holm\n")
        fh.write("  - Interaction: group pairwise × zone pairwise, "
                 "Holm-corrected\n")
    print(f"[SAVED] zone_lmer_METHODS.txt")


def plot_lt_zone_emmeans(
    results: dict,
    save_dir: str,
    *,
    y_col: str = "mean_err",
    metric_label: str = "mean",
    auto_close: bool = True,
):
    """Bar chart of collapsed-zone emmeans (Arms vs Junction × 3 groups)."""
    groups = GROUPS
    n_groups = len(groups)
    col = _PAPER_COLORS
    zone_order = _COLLAPSED_ZONE_ORDER
    n_zones = len(zone_order)

    cond_nice = {
        "within_LT1": r"Within $\mathrm{LT1}$",
        "within_LT2": r"Within $\mathrm{LT2}$",
        "LT1_to_LT2": r"$\mathrm{LT1} \to \mathrm{LT2}$",
    }

    if y_col == "pct_correct":
        y_label = "Fraction correct (|error| < threshold)"
    elif y_col == "median_err":
        y_label = f"Predicted median |error| ({_LT_1D_DISTANCE_UNIT})"
    else:
        y_label = f"Predicted mean |error| ({_LT_1D_DISTANCE_UNIT})"

    for cond, r in results.items():
        emm = r.get("emmeans")
        pw = r.get("pairwise_by_zone")
        aov = r.get("anova")
        if emm is None:
            continue

        fig, ax = plt.subplots(figsize=(6, 5.5), dpi=160)
        width = 0.24
        x_base = np.arange(n_zones)

        max_y = 0.0
        bar_data = {}  # (zone_idx, group_idx) → (mean, se, x_pos)
        for gi, g in enumerate(groups):
            offset = (gi - 1) * width
            means, sems = [], []
            for z in zone_order:
                row = emm[(emm["group"] == g) & (emm["zone"] == z)]
                if row.empty:
                    means.append(np.nan)
                    sems.append(np.nan)
                else:
                    means.append(float(row["emmean"].iloc[0]))
                    sems.append(float(row["SE"].iloc[0]))
            means_arr = np.array(means)
            sems_arr = np.array(sems)
            x_pos = x_base + offset

            for zi in range(n_zones):
                bar_data[(zi, gi)] = (means_arr[zi], sems_arr[zi],
                                      x_pos[zi])

            yerr = one_sided_yerr_by_sign(means_arr, sems_arr)
            bars = ax.bar(x_pos, means_arr, width=width, yerr=yerr,
                          capsize=2.5, color=col[g], edgecolor="black",
                          linewidth=0.5, label=GROUP_LABELS[g],
                          error_kw=dict(lw=1.2, capthick=1.2))
            for b in bars:
                b.set_alpha(0.75)

            top = np.nanmax(means_arr + sems_arr)
            if np.isfinite(top) and top > max_y:
                max_y = top

        # Between-group brackets per zone
        if pw is not None and not pw.empty:
            _g2i = {g: i for i, g in enumerate(groups)}
            for zi, z in enumerate(zone_order):
                pw_z = pw[pw["zone"] == z]
                if pw_z.empty:
                    continue
                zone_tops = []
                for gi in range(n_groups):
                    m, s, _ = bar_data[(zi, gi)]
                    if np.isfinite(m) and np.isfinite(s):
                        zone_tops.append(m + s)
                if not zone_tops:
                    continue
                by = max(zone_tops) * 1.04
                bdy = max_y * 0.025
                bgap = bdy * 2.4

                for _, row in pw_z.iterrows():
                    p_val = float(row["p.value"])
                    star, fs = _p_to_star(p_val, p_val)
                    if star is None:
                        continue
                    pair_str = str(row["contrast"])
                    pair_parts = [s.strip()
                                  for s in pair_str.split(" - ")]
                    if len(pair_parts) != 2:
                        continue
                    g1, g2 = pair_parts[0], pair_parts[1]
                    if g1 not in _g2i or g2 not in _g2i:
                        continue
                    _, _, x1 = bar_data[(zi, _g2i[g1])]
                    _, _, x2 = bar_data[(zi, _g2i[g2])]
                    ax.plot([x1, x1, x2, x2],
                            [by, by + bdy, by + bdy, by],
                            color="#333333", lw=0.6)
                    ax.text((x1 + x2) / 2, by + bdy + max_y * 0.002,
                            star, ha="center", va="bottom",
                            fontsize=fs, color="#333333")
                    by += bgap

        # ANOVA annotation
        if aov is not None:
            aov_lines = []
            for _, row in aov.iterrows():
                name = (str(row.iloc[0]) if "Unnamed" not in str(
                    aov.columns[0]) else str(row.name))
                if ":" in str(name) or str(name) in ("group", "zone"):
                    p = row.get("Pr(>F)", row.get("Pr..F.", np.nan))
                    f = row.get("F value", row.get("F.value", np.nan))
                    if np.isfinite(p) and np.isfinite(f):
                        aov_lines.append(
                            f"{name}: F={f:.2f}, p={p:.4f}")
            if aov_lines:
                ax.text(0.98, 0.98, "\n".join(aov_lines),
                        transform=ax.transAxes, fontsize=8,
                        va="top", ha="right",
                        bbox=dict(boxstyle="round,pad=0.3",
                                  facecolor="white", alpha=0.8))

        title = cond_nice.get(cond, cond)
        ax.set_title(f"Zone decoder ({metric_label}) — {title}",
                     fontsize=13)
        ax.set_xticks(x_base)
        ax.set_xticklabels(zone_order, fontsize=11)
        ax.set_xlabel("Track zone", fontsize=12)
        ax.set_ylabel(y_label, fontsize=12)
        ax.legend(fontsize=10, loc="upper left")
        ax.axhline(0, lw=0.8)
        ax.grid(True, axis="y", alpha=0.25)
        _pad_axes_for_stars(ax)
        fig.tight_layout()

        tag = f"zone_emmeans_{metric_label}_{cond}"
        for ext in (".png", ".svg"):
            fig.savefig(os.path.join(save_dir, f"{tag}{ext}"),
                        dpi=300, bbox_inches="tight")
        if auto_close:
            plt.close(fig)
        print(f"[SAVED] {tag}.png/.svg")


# -------------------------------------------------------------------
# Spatial decoding-error profile: mean |error| vs normalised track pos
# -------------------------------------------------------------------

def _collect_spatial_error_per_mouse(
    dec_results: dict,
    mouse_groups: dict,
    *,
    sess: str = "LT1",
    n_pos_bins: int = 20,
    kmin: float = 0.0,
    groups=("mCherry", "hM3D", "hM4D"),
):
    """
    For every mouse, collect per-direction (true_pos_norm, abs_err)
    from both CV folds, normalise position to [0, 1], and bin.

    sess can be "LT1", "LT2", or "LT1_to_LT2".
    For "LT1_to_LT2" (cross-session), there is no direction split
    so only a "combined" profile is produced per mouse.

    Returns
    -------
    mouse_profiles : dict[mouse -> dict]
        mouse_profiles[mouse]["leftward"]  = {"bin_centers": (B,), "mean_err": (B,), "n": (B,)}
        mouse_profiles[mouse]["rightward"] = {"bin_centers": (B,), "mean_err": (B,), "n": (B,)}
        mouse_profiles[mouse]["combined"]  = {"bin_centers": (B,), "mean_err": (B,), "n": (B,)}
        mouse_profiles[mouse]["group"] = str
    """
    bin_edges = np.linspace(0.0, 1.0, n_pos_bins + 1)
    bin_centers = 0.5 * (bin_edges[:-1] + bin_edges[1:])

    mouse_profiles = {}

    is_xfer = (sess == "LT1_to_LT2")

    for mouse, res in dec_results.items():
        g = mouse_groups.get(mouse, "NA")
        if g not in groups:
            continue

        if is_xfer:
            # ---- cross-session LT1→LT2 (flat, no direction split) ----
            blk = res.get("LT1_to_LT2", {})
            if not blk.get("ok", False):
                continue
            out = blk.get("out")
            if not isinstance(out, dict):
                continue
            tp = np.asarray(out.get("true_pos", []), float)
            dp = np.asarray(out.get("decoded_pos", []), float)
            Ksum = np.asarray(out.get("Ksum", []), float)
            ae = np.abs(dp - tp)

            n = min(tp.size, dp.size, Ksum.size)
            if n == 0:
                continue
            tp, dp, ae, Ksum = tp[:n], dp[:n], ae[:n], Ksum[:n]
            m = np.isfinite(tp) & np.isfinite(dp)
            if kmin > 0:
                m = m & (Ksum >= kmin)
            tp_f, ae_f = tp[m], ae[m]
            if tp_f.size == 0:
                continue

            pmin, pmax = tp_f.min(), tp_f.max()
            if pmax - pmin < 1e-6:
                continue
            tp_norm = (tp_f - pmin) / (pmax - pmin)
            err_norm = ae_f / (pmax - pmin)

            mean_err = np.full(n_pos_bins, np.nan)
            counts   = np.zeros(n_pos_bins, int)
            bin_idx  = np.clip(np.digitize(tp_norm, bin_edges) - 1, 0, n_pos_bins - 1)
            for b in range(n_pos_bins):
                sel = bin_idx == b
                counts[b] = sel.sum()
                if counts[b] > 0:
                    mean_err[b] = np.nanmean(err_norm[sel])

            mouse_profiles[mouse] = {
                "group": g,
                "combined": {"bin_centers": bin_centers.copy(), "mean_err": mean_err, "n": counts},
            }
            continue

        # ---- within-session (LT1 / LT2) ----
        # find the within-session dict
        within = None
        for kk in (f"within_{sess}_by_dir",
                   f"within_{sess}_by_dir_full",
                   f"within_{sess}_by_dir_mapped"):
            d = res.get(kk)
            if isinstance(d, dict) and len(d) > 0:
                within = d
                break
        if within is None:
            continue

        dir_data = {}   # dir_label -> (true_norm, err)

        for dir_label, dblk in within.items():
            if not isinstance(dblk, dict) or not dblk.get("ok", False):
                continue

            tp_all, err_all = [], []
            for fold_key in ("train_to_test",):
                step = dblk.get(fold_key)
                if not isinstance(step, dict):
                    continue
                out = step.get("out")
                if not isinstance(out, dict):
                    continue
                tp = np.asarray(out.get("true_pos", []), float)
                dp = np.asarray(out.get("decoded_pos", []), float)
                Ksum = np.asarray(out.get("Ksum", []), float)
                ae = np.abs(dp - tp)

                n = min(tp.size, dp.size, Ksum.size)
                if n == 0:
                    continue
                tp, dp, ae, Ksum = tp[:n], dp[:n], ae[:n], Ksum[:n]
                m = np.isfinite(tp) & np.isfinite(dp)
                if kmin > 0:
                    m = m & (Ksum >= kmin)
                tp_all.append(tp[m])
                err_all.append(ae[m])

            if not tp_all:
                continue

            tp_cat = np.concatenate(tp_all)
            err_cat = np.concatenate(err_all)
            if tp_cat.size == 0:
                continue

            # normalise position to [0,1]
            pmin, pmax = tp_cat.min(), tp_cat.max()
            if pmax - pmin < 1e-6:
                continue
            tp_norm = (tp_cat - pmin) / (pmax - pmin)
            # normalise error the same way (in fraction-of-track units)
            err_norm = err_cat / (pmax - pmin)

            dir_data[dir_label] = (tp_norm, err_norm)

        if not dir_data:
            continue

        prof = {"group": g}
        # per-direction binned profiles
        for dl, (tp_norm, err_norm) in dir_data.items():
            mean_err = np.full(n_pos_bins, np.nan)
            counts   = np.zeros(n_pos_bins, int)
            bin_idx  = np.digitize(tp_norm, bin_edges) - 1
            bin_idx  = np.clip(bin_idx, 0, n_pos_bins - 1)
            for b in range(n_pos_bins):
                sel = bin_idx == b
                counts[b] = sel.sum()
                if counts[b] > 0:
                    mean_err[b] = np.nanmean(err_norm[sel])
            prof[dl] = {"bin_centers": bin_centers.copy(), "mean_err": mean_err, "n": counts}

        # combined: merge both directions
        all_tp = np.concatenate([d[0] for d in dir_data.values()])
        all_err = np.concatenate([d[1] for d in dir_data.values()])
        mean_err_c = np.full(n_pos_bins, np.nan)
        counts_c   = np.zeros(n_pos_bins, int)
        bin_idx_c  = np.clip(np.digitize(all_tp, bin_edges) - 1, 0, n_pos_bins - 1)
        for b in range(n_pos_bins):
            sel = bin_idx_c == b
            counts_c[b] = sel.sum()
            if counts_c[b] > 0:
                mean_err_c[b] = np.nanmean(all_err[sel])
        prof["combined"] = {"bin_centers": bin_centers.copy(), "mean_err": mean_err_c, "n": counts_c}

        mouse_profiles[mouse] = prof

    return mouse_profiles


def plot_spatial_decoding_error(
    dec_results: dict,
    mouse_groups: dict,
    *,
    save_dir: str,
    session_str: str = "",
    n_pos_bins: int = 20,
    kmin: float = 0.0,
    auto_close: bool = True,
    groups=("mCherry", "hM3D", "hM4D"),
    colors=None,
    sessions=("LT1", "LT2"),
):
    """
    Plot mean decoding error vs normalised track position.

    Produces:
      1) Per-mouse plots: leftward & rightward (one figure per mouse per session)
         For LT1_to_LT2: single combined bar chart per mouse (no direction split).
      2) Group-average plots: leftward, rightward, and combined
         (one figure per session, with one line per group)
         For LT1_to_LT2: combined-only group plot.
    """
    _set_compact_plot_style()
    _ensure_dir(save_dir)

    if colors is None:
        colors = {"hM3D": "red", "hM4D": "blue", "mCherry": "black"}

    group_labels = {"hM3D": "hM3D (Gq)", "hM4D": "hM4D (Gi)", "mCherry": "mCherry"}

    for sess in sessions:
        mp = _collect_spatial_error_per_mouse(
            dec_results, mouse_groups,
            sess=sess, n_pos_bins=n_pos_bins, kmin=kmin, groups=groups,
        )
        if not mp:
            print(f"[WARN] No spatial-error data for {sess}")
            continue

        is_xfer = (sess == "LT1_to_LT2")

        # ============================================================
        # 1) Per-mouse plots
        # ============================================================
        per_mouse_dir = os.path.join(save_dir, "per_mouse")
        _ensure_dir(per_mouse_dir)

        for mouse, prof in mp.items():
            g = prof["group"]

            if is_xfer:
                # Cross-session: single combined bar chart
                fig, ax = plt.subplots(figsize=(6, 3.5))
                if "combined" in prof:
                    bc = prof["combined"]["bin_centers"]
                    me = prof["combined"]["mean_err"]
                    ax.bar(bc, me, width=bc[1] - bc[0], color=colors.get(g, "gray"),
                           alpha=0.7, edgecolor="k", linewidth=0.4)
                ax.set_xlabel("Normalised track position")
                ax.set_ylabel("Mean |error| (frac of track)")
                ax.set_xlim(0, 1)
                fig.suptitle(f"{mouse} ({g})  —  LT1\u2192LT2  {session_str}", fontsize=12)
                plt.tight_layout()
                fpath = os.path.join(per_mouse_dir, f"spatial_err_{mouse}_{sess}_{session_str}.png")
                _savefig_tight(fig, fpath)
                if auto_close:
                    plt.close(fig)
                print(f"[SAVED] {fpath}")
            else:
                # Within-session: just show the combined profile
                fig, ax = plt.subplots(figsize=(6, 3.5))
                if "combined" in prof:
                    bc = prof["combined"]["bin_centers"]
                    me = prof["combined"]["mean_err"]
                    ax.bar(bc, me, width=bc[1] - bc[0], color=colors.get(g, "gray"),
                           alpha=0.7, edgecolor="k", linewidth=0.4)
                ax.set_xlabel("Normalised track position")
                ax.set_ylabel("Mean |error| (frac of track)")
                ax.set_xlim(0, 1)
                fig.suptitle(f"{mouse} ({g})  —  {sess}  {session_str}", fontsize=12)
                plt.tight_layout()
                fpath = os.path.join(per_mouse_dir, f"spatial_err_{mouse}_{sess}_{session_str}.png")
                _savefig_tight(fig, fpath)
                if auto_close:
                    plt.close(fig)
                print(f"[SAVED] {fpath}")

        # ============================================================
        # 2) Group averages: combined (all directions pooled)
        # ============================================================
        modes = ("combined",)
        sess_display = "LT1\u2192LT2" if is_xfer else sess

        for mode in modes:
            fig, ax = plt.subplots(figsize=(6, 3.5))

            for g in groups:
                mice_in_group = [m for m, p in mp.items() if p["group"] == g and mode in p]
                if not mice_in_group:
                    continue
                # stack profiles → (n_mice, n_pos_bins)
                stacked = np.stack([mp[m][mode]["mean_err"] for m in mice_in_group])
                group_mean = np.nanmean(stacked, axis=0)
                group_sem  = np.nanstd(stacked, axis=0, ddof=1) / np.sqrt(len(mice_in_group))
                bc = mp[mice_in_group[0]][mode]["bin_centers"]

                ax.plot(bc, group_mean, color=colors.get(g, "gray"), linewidth=1.5,
                        label=f"{group_labels.get(g, g)} (n={len(mice_in_group)})")
                ax.fill_between(bc, group_mean - group_sem, group_mean + group_sem,
                                color=colors.get(g, "gray"), alpha=0.2)

            ax.set_xlabel("Normalised track position")
            ax.set_ylabel("Mean |error| (frac of track)")
            ax.set_xlim(0, 1)
            ax.legend(fontsize=9)
            kmin_str = f"_Kmin{kmin:.0f}" if kmin > 0 else ""
            ax.set_title(f"Group avg decoding error — {mode} — {sess_display}  {session_str}{kmin_str}")
            plt.tight_layout()
            fpath = os.path.join(save_dir, f"group_spatial_err_{mode}_{sess}_{session_str}{kmin_str}.png")
            _savefig_tight(fig, fpath)
            if auto_close:
                plt.close(fig)
            print(f"[SAVED] {fpath}")


def plot_spatial_decoding_error_heatmap(
    dec_results: dict,
    mouse_groups: dict,
    *,
    save_dir: str,
    session_str: str = "",
    n_pos_bins: int = 20,
    kmin: float = 0.0,
    auto_close: bool = True,
    groups=("mCherry", "hM3D", "hM4D"),
    cmap: str = "inferno",
    sessions=("LT1", "LT2"),
):
    """
    1-D heatmap-strip version of plot_spatial_decoding_error.

    For each session × mode (leftward / rightward / combined):
      - Per-mouse figure: one colour strip per mouse (rows grouped by group)
      - Group-average figure: one strip per group (mean across mice)

    Colour encodes group-average mean |error| (fraction of track).
    """
    _set_compact_plot_style()
    _ensure_dir(save_dir)

    group_labels = {"hM3D": "hM3D (Gq)", "hM4D": "hM4D (Gi)", "mCherry": "mCherry"}

    for sess in sessions:
        mp = _collect_spatial_error_per_mouse(
            dec_results, mouse_groups,
            sess=sess, n_pos_bins=n_pos_bins, kmin=kmin, groups=groups,
        )
        if not mp:
            print(f"[WARN] No spatial-error heatmap data for {sess}")
            continue

        is_xfer = (sess == "LT1_to_LT2")
        modes = ("combined",)
        sess_display = "LT1\u2192LT2" if is_xfer else sess
        kmin_str = f"_Kmin{kmin:.0f}" if kmin > 0 else ""

        # ----- determine global vmin/vmax across all groups & modes -----
        all_vals = []
        for prof in mp.values():
            for mode in modes:
                if mode in prof:
                    all_vals.append(prof[mode]["mean_err"])
        if not all_vals:
            continue
        vmin = np.nanmin(np.concatenate(all_vals))
        vmax = np.nanmax(np.concatenate(all_vals))

        # =================================================================
        # 1) Per-mouse heatmap strips (one figure per mode)
        # =================================================================
        per_mouse_dir = os.path.join(save_dir, "per_mouse")
        _ensure_dir(per_mouse_dir)

        for mode in modes:
            # collect rows: list of (mouse_label, mean_err array)
            rows = []
            for g in groups:
                mice_g = sorted([m for m, p in mp.items()
                                 if p["group"] == g and mode in p])
                for m in mice_g:
                    rows.append((f"{m} ({g})", mp[m][mode]["mean_err"]))
            if not rows:
                continue

            n_rows = len(rows)
            fig_h = max(1.5, 0.45 * n_rows + 0.8)
            fig, ax = plt.subplots(figsize=(8, fig_h))

            data = np.stack([r[1] for r in rows])           # (n_rows, n_pos_bins)
            im = ax.imshow(data, aspect="auto", cmap=cmap,
                           vmin=vmin, vmax=vmax,
                           extent=[0, 1, n_rows - 0.5, -0.5])
            ax.set_yticks(range(n_rows))
            ax.set_yticklabels([r[0] for r in rows], fontsize=8)
            ax.set_xlabel("Normalised track position")
            ax.set_title(f"Per-mouse error — {mode} — {sess_display}  {session_str}{kmin_str}",
                         fontsize=11)
            cb = fig.colorbar(im, ax=ax, pad=0.02)
            cb.set_label("Mean |error| (frac of track)", fontsize=9)
            plt.tight_layout()
            fpath = os.path.join(per_mouse_dir,
                                 f"spatial_err_heatmap_{mode}_{sess}_{session_str}{kmin_str}.png")
            _savefig_tight(fig, fpath)
            if auto_close:
                plt.close(fig)
            print(f"[SAVED] {fpath}")

        # =================================================================
        # 2) Group-average heatmap strips (one figure per mode)
        # =================================================================
        for mode in modes:
            strips = []       # (label, mean_err_1d)
            for g in groups:
                mice_g = [m for m, p in mp.items()
                          if p["group"] == g and mode in p]
                if not mice_g:
                    continue
                stacked = np.stack([mp[m][mode]["mean_err"] for m in mice_g])
                group_mean = np.nanmean(stacked, axis=0)
                strips.append((f"{group_labels.get(g, g)} (n={len(mice_g)})", group_mean))
            if not strips:
                continue

            n_strips = len(strips)
            fig_h = max(1.2, 0.6 * n_strips + 0.8)
            fig, ax = plt.subplots(figsize=(8, fig_h))

            data = np.stack([s[1] for s in strips])
            im = ax.imshow(data, aspect="auto", cmap=cmap,
                           vmin=vmin, vmax=vmax,
                           extent=[0, 1, n_strips - 0.5, -0.5])
            ax.set_yticks(range(n_strips))
            ax.set_yticklabels([s[0] for s in strips], fontsize=10)
            ax.set_xlabel("Normalised track position")
            ax.set_title(f"Group avg error — {mode} — {sess_display}  {session_str}{kmin_str}",
                         fontsize=11)
            cb = fig.colorbar(im, ax=ax, pad=0.02)
            cb.set_label("Mean |error| (frac of track)", fontsize=9)
            plt.tight_layout()
            fpath = os.path.join(save_dir,
                                 f"group_spatial_err_heatmap_{mode}_{sess}_{session_str}{kmin_str}.png")
            _savefig_tight(fig, fpath)
            if auto_close:
                plt.close(fig)
            print(f"[SAVED] {fpath}")


# =============================================================================
# ====  2D BAYESIAN DECODER FOR TFC_COND → TEST_B (pre-tone / first 3 min) ====
# =============================================================================

class BayesianDecoder2D:
    """
    Poisson Bayesian decoding for 2D position (open-field / TFC arenas).

    Bins (X, Y) into an (n_x_bins × n_y_bins) grid.
    Trains tuning curves  λ_i(bx, by)  from deconvolved event counts and occupancy.
    Decodes by MAP:  argmax_{bx,by}  P(bx,by | K)
    where K are binned event counts over time-bin chunks.

    Error is 2D Euclidean distance between decoded and true bin centres.
    """

    def __init__(
        self,
        n_x_bins: int = 20,
        n_y_bins: int = 20,
        time_bin_frames: int = 5,
        rate_smooth_eps: float = 1e-6,
        use_occupancy_prior: bool = True,
    ):
        self.n_x_bins = int(n_x_bins)
        self.n_y_bins = int(n_y_bins)
        self.time_bin_frames = int(time_bin_frames)
        self.rate_smooth_eps = float(rate_smooth_eps)
        self.use_occupancy_prior = bool(use_occupancy_prior)

        # learned
        self.x_edges = None           # (n_x_bins+1,)
        self.y_edges = None           # (n_y_bins+1,)
        self.x_centers = None         # (n_x_bins,)
        self.y_centers = None         # (n_y_bins,)
        self.lam = None               # (N, n_x_bins, n_y_bins) rates events/sec
        self.log_prior = None         # (n_x_bins, n_y_bins)
        self.dt_sec = None
        self.fitted = False

    # ------------------------------------------------------------------
    def _make_pos_bins(self, x, y):
        xmin, xmax = np.nanmin(x), np.nanmax(x)
        ymin, ymax = np.nanmin(y), np.nanmax(y)
        x_edges = np.linspace(xmin, xmax, self.n_x_bins + 1)
        y_edges = np.linspace(ymin, ymax, self.n_y_bins + 1)
        x_centers = 0.5 * (x_edges[:-1] + x_edges[1:])
        y_centers = 0.5 * (y_edges[:-1] + y_edges[1:])
        return x_edges, y_edges, x_centers, y_centers

    # ------------------------------------------------------------------
    def fit(
        self,
        S: np.ndarray,           # (N, T)
        x: np.ndarray,           # (T,)  X position
        y: np.ndarray,           # (T,)  Y position
        mask: np.ndarray,        # (T,)  boolean
        dt_sec: float,
        x_edges: Optional[np.ndarray] = None,
        y_edges: Optional[np.ndarray] = None,
    ):
        S = np.asarray(S, dtype=float)
        x = np.asarray(x, dtype=float)
        y = np.asarray(y, dtype=float)
        mask = np.asarray(mask, dtype=bool)

        N, T = S.shape
        x = x[:T]; y = y[:T]; mask = mask[:T]

        # Bin edges
        if x_edges is None or y_edges is None:
            x_edges, y_edges, x_centers, y_centers = self._make_pos_bins(x[mask], y[mask])
        else:
            x_edges = np.asarray(x_edges, float)
            y_edges = np.asarray(y_edges, float)
            x_centers = 0.5 * (x_edges[:-1] + x_edges[1:])
            y_centers = 0.5 * (y_edges[:-1] + y_edges[1:])

        Bx = x_centers.size
        By = y_centers.size

        # Assign each frame to a 2D bin
        xbin = np.clip(np.digitize(x, x_edges) - 1, 0, Bx - 1)
        ybin = np.clip(np.digitize(y, y_edges) - 1, 0, By - 1)

        # Occupancy (seconds) per 2D bin
        occ = np.zeros((Bx, By), dtype=float)
        for bx in range(Bx):
            for by in range(By):
                occ[bx, by] = np.sum(mask & (xbin == bx) & (ybin == by)) * dt_sec

        # Event counts per neuron per 2D bin
        counts = np.zeros((N, Bx, By), dtype=float)
        for bx in range(Bx):
            for by in range(By):
                idx = np.where(mask & (xbin == bx) & (ybin == by))[0]
                if idx.size:
                    counts[:, bx, by] = np.sum(S[:, idx], axis=1)

        # Rate estimate with epsilon smoothing
        occ_safe = np.maximum(occ, dt_sec)
        lam = counts / occ_safe[None, :, :]
        lam = np.maximum(lam, self.rate_smooth_eps)

        # Prior
        if self.use_occupancy_prior:
            p = occ_safe / np.sum(occ_safe)
        else:
            p = np.ones((Bx, By), dtype=float) / (Bx * By)
        log_prior = np.log(np.maximum(p, 1e-12))

        self.x_edges = x_edges
        self.y_edges = y_edges
        self.x_centers = x_centers
        self.y_centers = y_centers
        self.lam = lam              # (N, Bx, By)
        self.log_prior = log_prior  # (Bx, By)
        self.dt_sec = float(dt_sec)
        self.fitted = True

    # ------------------------------------------------------------------
    def decode(
        self,
        S: np.ndarray,           # (N, T)
        x: np.ndarray,           # (T,)
        y: np.ndarray,           # (T,)
        mask: np.ndarray,        # (T,)
        use_posterior_mean: bool = True,
        use_continuity_constraint: bool = False,
        speed_vec: Optional[np.ndarray] = None,
        continuity_sigma_k: float = 60.0,
        continuity_speed_ref: float = 20.0,
        continuity_exp: float = 1.0,
        continuity_sigma_min: float = 20.0,
        continuity_sigma_max: float = 60.0,
        continuity_sigma_default: float = 30.0,
        save_posterior: bool = False,
    ) -> Dict[str, Any]:
        """
        Decode 2D position using Poisson Bayes with non-overlapping chunks.

        Returns dict with:
          decoded_x, decoded_y        – MAP decoded positions
          true_x, true_y              – ground-truth chunk-averaged positions
          decoded_bin_x, decoded_bin_y
          true_bin_x, true_bin_y
          K (n_chunks, N), Ksum (n_chunks,)
          idx_use (n_chunks, w)
          euclidean_err (n_chunks,)    – 2D Euclidean error per chunk
        """
        assert self.fitted, "Call fit() first."

        S = np.asarray(S, dtype=float)
        x = np.asarray(x, dtype=float)
        y = np.asarray(y, dtype=float)
        mask = np.asarray(mask, dtype=bool)

        N, T = S.shape
        x = x[:T]; y = y[:T]; mask = mask[:T]

        Bx = self.x_centers.size
        By = self.y_centers.size
        dt = self.dt_sec
        w = int(self.time_bin_frames)

        # Flatten 2D bins to 1D for vectorised log-posterior
        B_flat = Bx * By
        lam_flat = self.lam.reshape(N, B_flat)          # (N, B_flat)
        log_lam_flat = np.log(lam_flat)                  # (N, B_flat)
        lam_dt_flat = lam_flat * dt * w                  # (N, B_flat)
        log_prior_flat = self.log_prior.reshape(B_flat)  # (B_flat,)

        # Build 2D grid of bin centres for reconstructing decoded (x,y)
        cx = self.x_centers  # (Bx,)
        cy = self.y_centers  # (By,)
        grid_x, grid_y = np.meshgrid(cx, cy, indexing='ij')  # both (Bx, By)
        grid_x_flat = grid_x.ravel()  # (B_flat,)
        grid_y_flat = grid_y.ravel()

        # Build time chunks from masked frames
        idx_all = np.where(mask)[0]
        empty = {
            "decoded_x": np.array([]), "decoded_y": np.array([]),
            "true_x": np.array([]), "true_y": np.array([]),
            "decoded_bin_x": np.array([], dtype=int), "decoded_bin_y": np.array([], dtype=int),
            "true_bin_x": np.array([], dtype=int), "true_bin_y": np.array([], dtype=int),
            "K": np.zeros((0, N)), "Ksum": np.array([]),
            "idx_use": np.zeros((0, w), dtype=int),
            "euclidean_err": np.array([]),
            "frac_active": np.array([]),
            "posterior_entropy": np.array([]),
        }
        if idx_all.size < w:
            return empty

        n_chunks = idx_all.size // w
        idx_use = idx_all[:n_chunks * w].reshape(n_chunks, w)

        # Counts per chunk
        K = np.sum(S[:, idx_use], axis=2).T   # (n_chunks, N)
        Ksum = K.sum(axis=1)
        frac_active = (K > 0).mean(axis=1)  # fraction of cells active per chunk

        # Log posterior (n_chunks, B_flat)
        log_post = (K @ log_lam_flat) - np.sum(lam_dt_flat, axis=0)[None, :] + log_prior_flat[None, :]

        decoded_flat = np.argmax(log_post, axis=1)

        if use_continuity_constraint:
            if speed_vec is not None:
                speed_vec = np.asarray(speed_vec, dtype=float)[:T]
                chunk_speed = np.nanmean(np.abs(speed_vec[idx_use]), axis=1)
            else:
                chunk_speed = None

            def _sigma_from_speed(vt):
                if np.isfinite(vt):
                    vt = max(float(vt), 0.0)
                    sigma = continuity_sigma_k * (vt / max(float(continuity_speed_ref), 1e-9)) ** float(continuity_exp)
                else:
                    sigma = float(continuity_sigma_default)
                sigma = np.clip(sigma, float(continuity_sigma_min), float(continuity_sigma_max))
                return float(sigma)

            decoded_x = np.zeros(n_chunks, dtype=float)
            decoded_y = np.zeros(n_chunks, dtype=float)
            decoded_bin_x = np.zeros(n_chunks, dtype=int)
            decoded_bin_y = np.zeros(n_chunks, dtype=int)
            sigma_per_chunk = np.full(n_chunks, np.nan, dtype=float)
            posterior_entropy = np.zeros(n_chunks, dtype=float)
            if save_posterior:
                full_post = np.zeros((n_chunks, B_flat), dtype=np.float32)

            for t in range(n_chunks):
                lp_t = log_post[t].copy()

                if t > 0:
                    vt = np.nan
                    if chunk_speed is not None and t < chunk_speed.size:
                        vt = chunk_speed[t]
                    sigma_t = _sigma_from_speed(vt)
                    sigma_per_chunk[t] = sigma_t

                    dx = grid_x_flat - decoded_x[t - 1]
                    dy = grid_y_flat - decoded_y[t - 1]
                    lp_t += -(dx * dx + dy * dy) / (2.0 * sigma_t * sigma_t)
                else:
                    sigma_per_chunk[t] = np.nan

                # Normalised posterior for decoding + entropy
                lp_t_s = lp_t - np.max(lp_t)
                post_t = np.exp(lp_t_s)
                post_t /= max(np.sum(post_t), 1e-12)
                posterior_entropy[t] = -np.sum(post_t * np.log(post_t + 1e-12))
                if save_posterior:
                    full_post[t] = post_t

                if use_posterior_mean:
                    decoded_x[t] = np.sum(post_t * grid_x_flat)
                    decoded_y[t] = np.sum(post_t * grid_y_flat)
                    decoded_bin_x[t] = np.clip(np.digitize(decoded_x[t], self.x_edges) - 1, 0, Bx - 1)
                    decoded_bin_y[t] = np.clip(np.digitize(decoded_y[t], self.y_edges) - 1, 0, By - 1)
                else:
                    b = int(np.argmax(lp_t))
                    decoded_x[t] = grid_x_flat[b]
                    decoded_y[t] = grid_y_flat[b]
                    decoded_bin_x[t] = b // By
                    decoded_bin_y[t] = b % By

            decode_mode = "posterior_mean+continuity" if use_posterior_mean else "map+continuity"
        else:
            if use_posterior_mean:
                # Stable softmax over bins, then posterior expectation E[x], E[y].
                log_post_shift = log_post - np.max(log_post, axis=1, keepdims=True)
                post = np.exp(log_post_shift)
                post_sum = np.sum(post, axis=1, keepdims=True)
                post_sum = np.maximum(post_sum, 1e-12)
                post /= post_sum
                decoded_x = post @ grid_x_flat
                decoded_y = post @ grid_y_flat
                decoded_bin_x = np.clip(np.digitize(decoded_x, self.x_edges) - 1, 0, Bx - 1)
                decoded_bin_y = np.clip(np.digitize(decoded_y, self.y_edges) - 1, 0, By - 1)
                posterior_entropy = -np.sum(post * np.log(post + 1e-12), axis=1)
                if save_posterior:
                    full_post = post.astype(np.float32)
                decode_mode = "posterior_mean"
            else:
                log_post_shift = log_post - np.max(log_post, axis=1, keepdims=True)
                post = np.exp(log_post_shift)
                post /= np.maximum(np.sum(post, axis=1, keepdims=True), 1e-12)
                posterior_entropy = -np.sum(post * np.log(post + 1e-12), axis=1)
                if save_posterior:
                    full_post = post.astype(np.float32)
                decoded_x = grid_x_flat[decoded_flat]
                decoded_y = grid_y_flat[decoded_flat]
                decoded_bin_x = decoded_flat // By
                decoded_bin_y = decoded_flat % By
                decode_mode = "map"

        # True positions (chunk average)
        true_x = np.mean(x[idx_use], axis=1)
        true_y = np.mean(y[idx_use], axis=1)

        true_bin_x = np.clip(np.digitize(true_x, self.x_edges) - 1, 0, Bx - 1)
        true_bin_y = np.clip(np.digitize(true_y, self.y_edges) - 1, 0, By - 1)

        euclidean_err = np.sqrt((decoded_x - true_x)**2 + (decoded_y - true_y)**2)

        result = {
            "decoded_x": decoded_x,
            "decoded_y": decoded_y,
            "decoded_bin_x": decoded_bin_x,
            "decoded_bin_y": decoded_bin_y,
            "true_x": true_x,
            "true_y": true_y,
            "true_bin_x": true_bin_x,
            "true_bin_y": true_bin_y,
            "K": K,
            "Ksum": Ksum,
            "idx_use": idx_use,
            "euclidean_err": euclidean_err,
            "decode_mode": decode_mode,
            "frac_active": frac_active,
            "posterior_entropy": posterior_entropy,
        }
        if save_posterior:
            result["posterior"] = full_post
            result["grid_x_flat"] = grid_x_flat
            result["grid_y_flat"] = grid_y_flat
        return result

    # ------------------------------------------------------------------
    @staticmethod
    def euclidean_error(decoded_x, decoded_y, true_x, true_y):
        return np.sqrt((np.asarray(decoded_x) - np.asarray(true_x))**2 +
                       (np.asarray(decoded_y) - np.asarray(true_y))**2)


# ---------------------------------------------------------------------------
#  Pre-tone mask builder
# ---------------------------------------------------------------------------

def build_pretone_mask_TFC(sess, first_n_sec: float = 180.0, use_speed: bool = True,
                           min_speed: float = 2.0,
                           encoder_period: str = "pre-tone") -> np.ndarray:
    """
    Build a boolean mask for the selected period in a TFC / Test session.

    Parameters
    ----------
    encoder_period : str
        ``'pre-tone'`` — frames 0 .. first tone onset (default, original behaviour).
        ``'post-shock'`` — ITI frames after each shock offset and before the
        next tone onset (or session end for the last trial).  Only meaningful
        for ``TraceFearCondSession``; for other session types falls back to
        ``'pre-tone'``.
        ``'post-tone'`` — ITI frames after each tone offset and before the
        next tone onset (or session end for the last trial).  Only meaningful
        for sessions with tones but **no** shocks (e.g. ``TestBSession``);
        falls back to ``'pre-tone'`` for sessions with shocks or no tones.

    Returns
    -------
    mask : (T,) bool
    """
    T = sess.S.shape[1]
    mask = np.zeros(T, dtype=bool)

    if encoder_period == "post-shock":
        # Post-shock ITI periods: shock_offset[i] .. tone_onset[i+1]
        # (last trial: shock_offset[-1] .. session end)
        if (hasattr(sess, 'post_shock_onsets') and
                len(sess.post_shock_onsets) > 0 and
                hasattr(sess, 'post_shock_offsets') and
                len(sess.post_shock_offsets) > 0):
            for ps_on, ps_off in zip(sess.post_shock_onsets,
                                     sess.post_shock_offsets):
                fr_on = min(int(ps_on), T)
                fr_off = min(int(ps_off), T)
                mask[fr_on:fr_off] = True
        else:
            # Session has no shock info — fall back to pre-tone
            if hasattr(sess, 'tone_onsets') and len(sess.tone_onsets) > 0:
                mask[:min(int(sess.tone_onsets[0]), T)] = True
            else:
                dt = _infer_dt_sec(sess)
                mask[:min(int(first_n_sec / dt), T)] = True
    elif encoder_period == "post-tone":
        # Post-tone ITI periods: tone_offset[i] .. tone_onset[i+1]
        # (last trial: tone_offset[-1] .. session end).
        # Only meaningful for sessions with tones but NO shocks (Test_B).
        has_tones = (hasattr(sess, 'post_tone_onsets') and
                     len(sess.post_tone_onsets) > 0 and
                     hasattr(sess, 'post_tone_offsets') and
                     len(sess.post_tone_offsets) > 0)
        has_shocks = (hasattr(sess, 'shock_onsets') and
                      len(sess.shock_onsets) > 0)
        if has_tones and not has_shocks:
            for pt_on, pt_off in zip(sess.post_tone_onsets,
                                     sess.post_tone_offsets):
                fr_on = min(int(pt_on), T)
                fr_off = min(int(pt_off), T)
                mask[fr_on:fr_off] = True
        else:
            # Session has shocks (TFC_cond) or no tones (Test_A) — fall back
            if hasattr(sess, 'tone_onsets') and len(sess.tone_onsets) > 0:
                mask[:min(int(sess.tone_onsets[0]), T)] = True
            else:
                dt = _infer_dt_sec(sess)
                mask[:min(int(first_n_sec / dt), T)] = True
    else:
        # Default: pre-tone
        if hasattr(sess, 'tone_onsets') and len(sess.tone_onsets) > 0:
            last_pretone_frame = int(sess.tone_onsets[0])
        else:
            dt = _infer_dt_sec(sess)
            last_pretone_frame = min(int(first_n_sec / dt), T)
        mask[:min(last_pretone_frame, T)] = True

    if use_speed:
        mask &= _get_speed_mask(sess, min_speed=min_speed)[:T]

    return mask


def _shuffle_is_enabled(enable_shuffle_control: bool, n_shuffles: int, shuffle_type: str) -> bool:
    if not bool(enable_shuffle_control):
        return False
    if int(n_shuffles) <= 0:
        return False
    st = str(shuffle_type).strip().lower()
    return st not in ("", "none", "off", "false", "0")


def _apply_decoder_time_shuffle(
    S: np.ndarray,
    *,
    shuffle_type: str,
    rng: np.random.Generator,
) -> np.ndarray:
    """Apply a null-control temporal shuffle to neural activity matrix (N, T)."""
    S = np.asarray(S)
    if S.ndim != 2 or S.shape[1] < 2:
        return S.copy()

    st = str(shuffle_type).strip().lower()
    out = S.copy()

    if st in ("circular", "circular_shift", "circular_time_shift", "time_shift", "by_time"):
        T = out.shape[1]
        shifts = rng.integers(1, T, size=out.shape[0])
        for i, shift in enumerate(shifts):
            out[i, :] = np.roll(out[i, :], int(shift))
        return out

    if st in ("global_frame_permutation", "frame_permutation", "full_permutation", "permute"):
        perm = rng.permutation(out.shape[1])
        return out[:, perm]

    return out


def _wilcoxon_effect_from_improvement(improvement: np.ndarray) -> Dict[str, Any]:
    """Paired one-sample Wilcoxon on improvement=shuffle-real, with effect summaries."""
    x = np.asarray(improvement, float)
    x = x[np.isfinite(x)]
    nonzero = x[np.abs(x) > 0]
    n = int(nonzero.size)
    if n < 3:
        return {
            "n": n,
            "p_value": np.nan,
            "statistic": np.nan,
            "effect_r": np.nan,
            "rank_biserial": np.nan,
            "median_improvement": float(np.nanmedian(x)) if x.size else np.nan,
            "mean_improvement": float(np.nanmean(x)) if x.size else np.nan,
            "note": "Insufficient non-zero paired samples for Wilcoxon (need >=3).",
        }

    try:
        # improvement > 0 means real decoder outperforms shuffle (lower error).
        w = wilcoxon(nonzero, alternative="greater", zero_method="wilcox")
        p = float(w.pvalue)
        stat = float(w.statistic)
        z_approx = float(norm.isf(max(min(p / 2.0, 1.0 - 1e-12), 1e-12)))
        effect_r = float(z_approx / np.sqrt(max(n, 1)))
    except Exception:
        p = np.nan
        stat = np.nan
        effect_r = np.nan

    n_pos = int(np.sum(nonzero > 0))
    n_neg = int(np.sum(nonzero < 0))
    denom = max(n_pos + n_neg, 1)
    rank_biserial = float((n_pos - n_neg) / denom)

    return {
        "n": n,
        "p_value": p,
        "statistic": stat,
        "effect_r": effect_r,
        "rank_biserial": rank_biserial,
        "median_improvement": float(np.nanmedian(nonzero)),
        "mean_improvement": float(np.nanmean(nonzero)),
        "note": "",
    }


def _save_shuffle_control_comparison(
    all_results: dict,
    *,
    mouse_groups: dict,
    save_path: str,
    train_label: str,
    auto_close: bool = True,
) -> None:
    rows = []
    for mouse, mres in all_results.items():
        group = mouse_groups.get(mouse, "NA") if mouse_groups is not None else "NA"

        wres = mres.get("within_train", {})
        w_shuf = wres.get("shuffle_control", {}) if isinstance(wres, dict) else {}
        if bool(wres.get("ok", False)) and w_shuf.get("ok", False):
            real_med = float(np.nanmedian(np.asarray(wres.get("pooled_euclidean_err", []), float)))
            shuf_med = float(w_shuf.get("median_of_repeat_medians", np.nan))
            rows.append({
                "mouse": mouse,
                "group": group,
                "condition": f"within_{train_label}",
                "real_median_err": real_med,
                "shuffle_median_err": shuf_med,
                "improvement": shuf_med - real_med,
            })

        targets = mres.get("targets", {}) if isinstance(mres, dict) else {}
        for tgt_name, tres in targets.items():
            if not isinstance(tres, dict) or not bool(tres.get("ok", False)):
                continue
            shuf = tres.get("shuffle_control", {})
            if not shuf.get("ok", False):
                continue
            real_med = float(np.nanmedian(np.asarray(tres.get("euclidean_err", []), float)))
            shuf_med = float(shuf.get("median_of_repeat_medians", np.nan))
            rows.append({
                "mouse": mouse,
                "group": group,
                "condition": f"{train_label}_to_{tgt_name}",
                "real_median_err": real_med,
                "shuffle_median_err": shuf_med,
                "improvement": shuf_med - real_med,
            })

    if len(rows) == 0:
        return

    os.makedirs(save_path, exist_ok=True)
    df = pd.DataFrame(rows)
    df.to_csv(os.path.join(save_path, "shuffle_control_comparison_mouse_level.csv"), index=False)

    stats_rows = []
    for cond, dfg in df.groupby("condition", dropna=False):
        st = _wilcoxon_effect_from_improvement(dfg["improvement"].to_numpy(float))
        stats_rows.append({
            "condition": cond,
            **st,
        })
    df_stats = pd.DataFrame(stats_rows)
    df_stats.to_csv(os.path.join(save_path, "shuffle_control_wilcoxon_summary.csv"), index=False)

    try:
        conditions = list(df["condition"].dropna().unique())
        x = np.arange(len(conditions))
        fig, ax = plt.subplots(figsize=(max(7, 1.6 * len(conditions)), 5), dpi=150)
        for i, cond in enumerate(conditions):
            sub = df[df["condition"] == cond]
            real_vals = sub["real_median_err"].to_numpy(float)
            shuf_vals = sub["shuffle_median_err"].to_numpy(float)
            jitter = np.random.uniform(-0.04, 0.04, size=real_vals.size)
            ax.scatter(np.full(real_vals.size, x[i] - 0.15) + jitter, real_vals,
                       s=24, color="black", alpha=0.65, label="Real" if i == 0 else None)
            ax.scatter(np.full(shuf_vals.size, x[i] + 0.15) + jitter, shuf_vals,
                       s=24, color="tab:orange", alpha=0.65, label="Shuffle" if i == 0 else None)
            for rv, sv in zip(real_vals, shuf_vals):
                if np.isfinite(rv) and np.isfinite(sv):
                    ax.plot([x[i] - 0.15, x[i] + 0.15], [rv, sv], color="0.7", lw=0.7, alpha=0.5)

        ax.set_xticks(x)
        ax.set_xticklabels(conditions, rotation=25, ha="right")
        ax.set_ylabel(_euclidean_error_axis_label())
        ax.set_title("Decoder real vs shuffle control (paired, per mouse)")
        ax.grid(True, axis="y", alpha=0.2)
        ax.legend(loc="upper right")
        fig.tight_layout()
        fig.savefig(os.path.join(save_path, "shuffle_control_real_vs_shuffle_paired.png"), dpi=300)
        if auto_close:
            plt.close(fig)
    except Exception as exc:
        print(f"[SHUFFLE] Comparison plot failed: {exc}")


# ---------------------------------------------------------------------------
#  Cross-session 2D TFC_cond → Test_B decoding
# ---------------------------------------------------------------------------

def decode_TFC_to_TestB_2D(
    TFC,
    TestB,
    *,
    mapping: str = "TFC_cond+Test_B",
    n_x_bins: int = 20,
    n_y_bins: int = 20,
    time_bin_frames: int = 5,
    use_posterior_mean: bool = True,
    use_speed: bool = True,
    min_speed: float = 2.0,
    first_n_sec: float = 180.0,
    use_z_score: str = "none",
    shuffle_type: str = "none",
    shuffle_seed: Optional[int] = None,
) -> Dict[str, Any]:
    """
    Train a 2D Bayesian position decoder on TFC_cond pre-tone data,
    then test it on Test_B pre-tone data using cross-registered cells.

    Parameters
    ----------
    TFC : TraceFearCondSession
    TestB : TestBSession
    mapping : str
        Cross-registration mapping string (e.g., 'TFC_cond+Test_B').
    n_x_bins, n_y_bins : int
        Number of spatial bins in X and Y.
    time_bin_frames : int
        Frames per decoding time-bin.
    use_speed : bool
    min_speed : float
    first_n_sec : float
        Fallback pre-tone duration.

    Returns
    -------
    dict with 'ok', 'out', 'euclidean_err', 'n_cells_mapped', etc.
    """

    # --- Cross-registration: get matched cell indices ---
    # TFC.crossreg for TFC_cond day (type 1) won't have Test_B columns.
    # Test_B.crossreg is the type-4 cross-reg that spans TFC_cond, Test_B, Test_B_1wk.
    crossreg = TestB.crossreg   # type-4 mapping

    try:
        df_mapping = crossreg.get_mappings_cells(mapping_type=mapping)
    except KeyError:
        return {"ok": False, "reason": f"Mapping '{mapping}' not found in cross-registration."}

    # Column names in the mapping df correspond to session groups
    col_TFC = TFC.get_df_col(with_crossreg=crossreg)
    col_TestB = TestB.get_df_col(with_crossreg=crossreg)

    cells_TFC = df_mapping[col_TFC].astype(float).astype(int).tolist()
    cells_TestB = df_mapping[col_TestB].astype(float).astype(int).tolist()

    S_tfc, _ = get_mapped_S_from_unit_ids(TFC, cells_TFC)
    S_testb, _ = get_mapped_S_from_unit_ids(TestB, cells_TestB)

    if S_tfc.shape[0] == 0 or S_testb.shape[0] == 0:
        return {"ok": False, "reason": "No cross-registered cells found."}

    # Ensure same number of cells in both
    n = min(S_tfc.shape[0], S_testb.shape[0])
    S_tfc = S_tfc[:n]
    S_testb = S_testb[:n]

    # Optional per-neuron z-scoring policy.
    S_tfc, S_testb = _apply_zscore_pair(S_tfc, S_testb, use_z_score)

    if str(shuffle_type).strip().lower() not in ("", "none", "off", "false", "0"):
        rng = default_rng(shuffle_seed)
        S_tfc = _apply_decoder_time_shuffle(S_tfc, shuffle_type=shuffle_type, rng=rng)
        S_testb = _apply_decoder_time_shuffle(S_testb, shuffle_type=shuffle_type, rng=rng)

    dist_meta = _validate_2d_decoder_distance_meta(TFC, TestB)
    pos_scale = float(dist_meta["scale"])

    # --- Position and timing ---
    dt_tfc = _infer_dt_sec(TFC)
    dt_testb = _infer_dt_sec(TestB)

    x_tfc = _scale_2d_position_array(TFC.loc_X_miniscope_smooth, pos_scale)[:S_tfc.shape[1]]
    y_tfc = _scale_2d_position_array(TFC.loc_Y_miniscope_smooth, pos_scale)[:S_tfc.shape[1]]

    x_testb = _scale_2d_position_array(TestB.loc_X_miniscope_smooth, pos_scale)[:S_testb.shape[1]]
    y_testb = _scale_2d_position_array(TestB.loc_Y_miniscope_smooth, pos_scale)[:S_testb.shape[1]]

    # --- Pre-tone masks ---
    mask_tfc = build_pretone_mask_TFC(TFC, first_n_sec=first_n_sec,
                                       use_speed=use_speed, min_speed=min_speed)[:S_tfc.shape[1]]
    mask_testb = build_pretone_mask_TFC(TestB, first_n_sec=first_n_sec,
                                         use_speed=use_speed, min_speed=min_speed)[:S_testb.shape[1]]

    if np.sum(mask_tfc) < time_bin_frames or np.sum(mask_testb) < time_bin_frames:
        return {"ok": False, "reason": "Insufficient pre-tone frames after masking."}

    # --- Train on TFC_cond pre-tone ---
    dec = BayesianDecoder2D(
        n_x_bins=n_x_bins,
        n_y_bins=n_y_bins,
        time_bin_frames=time_bin_frames,
    )
    dec.fit(S_tfc, x_tfc, y_tfc, mask_tfc, dt_tfc)

    # --- Decode Test_B pre-tone (using TFC_cond bin edges) ---
    out = dec.decode(
        S_testb, x_testb, y_testb, mask_testb,
        use_posterior_mean=use_posterior_mean)
    out = _annotate_2d_decode_output(out, dist_meta)
    euclidean_err = out["euclidean_err"]

    # --- Also do within-session CV on TFC_cond pre-tone (time-split) ---
    within_result = _within_session_2D_cv(
        S_tfc, x_tfc, y_tfc, mask_tfc, dt_tfc,
        n_x_bins=n_x_bins, n_y_bins=n_y_bins,
        time_bin_frames=time_bin_frames,
        use_posterior_mean=use_posterior_mean,
        use_continuity_constraint=True,
        position_unit=dist_meta["unit"],
        position_scale=pos_scale,
    )

    return {
        "ok": True,
        "out": out,
        "euclidean_err": euclidean_err,
        "n_cells_mapped": int(n),
        "dt_train": float(dt_tfc),
        "dt_test": float(dt_testb),
        "n_pretone_frames_tfc": int(np.sum(mask_tfc)),
        "n_pretone_frames_testb": int(np.sum(mask_testb)),
        "within_TFC": within_result,
        "position_unit": dist_meta["unit"],
        "position_scale": pos_scale,
    }


# ---------------------------------------------------------------------------
#  Within-session 2D cross-validation (even/odd time-block split)
# ---------------------------------------------------------------------------

def _within_session_2D_cv(
    S, x, y, mask, dt_sec, *,
    n_x_bins=20, n_y_bins=20, time_bin_frames=5,
    use_posterior_mean: bool = True,
    decoder_type: str = 'bayesian',
    ridge_alpha: float = 1.0,
    use_continuity_constraint: bool = False,
    continuity_sigma_k: float = 60.0,
    continuity_speed_ref: float = 20.0,
    continuity_exp: float = 1.0,
    continuity_sigma_min: float = 20.0,
    continuity_sigma_max: float = 60.0,
    continuity_sigma_default: float = 30.0,
    speed_vec: Optional[np.ndarray] = None,
    position_unit: str = "px",
    position_scale: float = 1.0,
    shuffle_type: str = "none",
    shuffle_seed: Optional[int] = None,
) -> Dict[str, Any]:
    """
    Simple within-session cross-validation for 2D open-field data.
    When decoder_type='bayesian': splits into even/odd halves by 10-s blocks.
    When decoder_type='ridge': 5-fold block CV (1-minute blocks, seed=42).
    """
    if _decoder_is_ridge(decoder_type):
        return _within_session_2D_cv_ridge(
            S, x, y, mask, dt_sec,
            time_bin_frames=time_bin_frames,
            ridge_alpha=ridge_alpha,
        )
    if str(shuffle_type).strip().lower() not in ("", "none", "off", "false", "0"):
        rng = default_rng(shuffle_seed)
        S = _apply_decoder_time_shuffle(S, shuffle_type=shuffle_type, rng=rng)

    T = S.shape[1]
    block_size = max(1, int(10.0 / dt_sec))  # ~10 s blocks

    idx_all = np.where(mask)[0]
    if idx_all.size < 2 * time_bin_frames:
        return {"ok": False, "reason": "Too few masked frames for CV."}

    # Build per-frame speed for continuity if requested and no external speed provided.
    if use_continuity_constraint:
        if speed_vec is None:
            speed_vec = np.zeros(T, dtype=float)
            if T >= 2:
                dx = np.diff(np.asarray(x, dtype=float))
                dy = np.diff(np.asarray(y, dtype=float))
                v = np.sqrt(dx * dx + dy * dy) / max(float(dt_sec), 1e-9)
                speed_vec[1:] = v
                speed_vec[0] = v[0] if v.size else 0.0
        else:
            speed_vec = np.asarray(speed_vec, dtype=float)[:T]

    # Assign each frame to a block index and split even/odd
    block_id = idx_all // block_size
    even_mask = np.zeros(T, dtype=bool)
    odd_mask = np.zeros(T, dtype=bool)
    even_mask[idx_all[block_id % 2 == 0]] = True
    odd_mask[idx_all[block_id % 2 == 1]] = True

    results = {}
    for train_label, train_m, test_label, test_m in [
        ("even", even_mask, "odd", odd_mask),
        ("odd", odd_mask, "even", even_mask),
    ]:
        dec = BayesianDecoder2D(n_x_bins=n_x_bins, n_y_bins=n_y_bins,
                                time_bin_frames=time_bin_frames)
        dec.fit(S, x, y, train_m, dt_sec)
        out = dec.decode(
            S, x, y, test_m,
            use_posterior_mean=use_posterior_mean,
            use_continuity_constraint=use_continuity_constraint,
            speed_vec=speed_vec,
            continuity_sigma_k=continuity_sigma_k,
            continuity_speed_ref=continuity_speed_ref,
            continuity_exp=continuity_exp,
            continuity_sigma_min=continuity_sigma_min,
            continuity_sigma_max=continuity_sigma_max,
            continuity_sigma_default=continuity_sigma_default,
        )
        out = _annotate_2d_decode_output(out, {
            "unit": position_unit,
            "scale": position_scale,
            "px_distance": np.nan,
            "true_distance": np.nan,
        })
        results[f"{train_label}_to_{test_label}"] = {
            "out": out,
            "euclidean_err": out["euclidean_err"],
        }

    # Average errors across the two splits
    err_parts = []
    for k in results:
        e = results[k]["euclidean_err"]
        if e.size > 0:
            err_parts.append(e)
    if err_parts:
        results["pooled_euclidean_err"] = np.concatenate(err_parts)
        results["mean_err"] = float(np.nanmean(results["pooled_euclidean_err"]))
        results["median_err"] = float(np.nanmedian(results["pooled_euclidean_err"]))
    else:
        results["pooled_euclidean_err"] = np.array([])
        results["mean_err"] = np.nan
        results["median_err"] = np.nan
    results["ok"] = True
    results["position_unit"] = position_unit
    results["position_scale"] = float(position_scale)
    return results


def _compute_median_jitter(decoded_x, decoded_y):
    """Median frame-to-frame Euclidean jump in decoded position (temporal jitter)."""
    dx = np.asarray(decoded_x, dtype=float)
    dy = np.asarray(decoded_y, dtype=float)
    if dx.size < 2:
        return np.nan
    jumps = np.sqrt(np.diff(dx)**2 + np.diff(dy)**2)
    return float(np.nanmedian(jumps))


def optimize_2d_decoder_parameters(
    TFC_cond_group: dict,
    *,
    PLOTS_DIR: str,
    encoder_period: str = "pre-tone",
    n_spatial_bins: int = 20,
    time_bin_frames: int = 15,
    use_posterior_mean: bool = True,
    use_z_score: str = "per-session",
    use_continuity_constraint: bool = True,
    continuity_sigma_k: float = 35.0,
    continuity_speed_ref: float = 20.0,
    continuity_exp: float = 1.0,
    continuity_sigma_min: float = 10.0,
    continuity_sigma_max: float = 30.0,
    continuity_sigma_default: float = 18.0,
    optimization_trials: int = 50,
    optimization_seed: int = 42,
    optimization_subset_mouse_count: int = 3,
    optimization_first_n_sec: float = 180.0,
    optimization_target: str = "within_TFC",
    optimization_use_speed: bool = True,
    optimization_min_speed: float = 2.0,
    optimization_n_startup_trials: int = 12,
    jitter_lambda: float = 0.5,
) -> Dict[str, Any]:
    baseline_params = {
        "n_spatial_bins": int(n_spatial_bins),
        "time_bin_frames": int(time_bin_frames),
        "use_posterior_mean": bool(use_posterior_mean),
        "use_z_score": str(use_z_score),
        "use_continuity_constraint": bool(use_continuity_constraint),
        "continuity_sigma_k": float(continuity_sigma_k),
        "continuity_speed_ref": float(continuity_speed_ref),
        "continuity_exp": float(continuity_exp),
        "continuity_sigma_min": float(continuity_sigma_min),
        "continuity_sigma_max": float(continuity_sigma_max),
        "continuity_sigma_default": float(continuity_sigma_default),
    }

    result = {
        "ok": False,
        "ran": False,
        "status": "skipped",
        "baseline_params": dict(baseline_params),
        "best_params": None,
        "applied_params": dict(baseline_params),
        "opt_dir": None,
        "subset_mice": [],
    }

    print("\n" + "=" * 70)
    print("2D Bayesian decoder parameter optimization (subset mode)")
    print("=" * 70)

    os.makedirs(PLOTS_DIR, exist_ok=True)
    opt_dir = os.path.join(PLOTS_DIR, "2D_decoder_optimization")
    os.makedirs(opt_dir, exist_ok=True)
    opt_tables_dir = os.path.join(opt_dir, "tables")
    opt_summary_dir = os.path.join(opt_dir, "summary")
    opt_paramsets_dir = os.path.join(opt_dir, "paramsets")
    os.makedirs(opt_tables_dir, exist_ok=True)
    os.makedirs(opt_summary_dir, exist_ok=True)
    os.makedirs(opt_paramsets_dir, exist_ok=True)
    result["opt_dir"] = opt_dir

    def _normalize_opt_params(params):
        return {
            "n_spatial_bins": int(params["n_spatial_bins"]),
            "time_bin_frames": int(params["time_bin_frames"]),
            "use_posterior_mean": bool(params["use_posterior_mean"]),
            "use_z_score": str(params["use_z_score"]),
            "use_continuity_constraint": bool(params.get("use_continuity_constraint", True)),
            "continuity_sigma_k": float(params["continuity_sigma_k"]),
            "continuity_speed_ref": float(params["continuity_speed_ref"]),
            "continuity_exp": float(params["continuity_exp"]),
            "continuity_sigma_min": float(params["continuity_sigma_min"]),
            "continuity_sigma_max": float(params["continuity_sigma_max"]),
            "continuity_sigma_default": float(params["continuity_sigma_default"]),
        }

    def _param_signature(params):
        p = _normalize_opt_params(params)
        return (
            p["n_spatial_bins"],
            p["time_bin_frames"],
            int(p["use_posterior_mean"]),
            p["use_z_score"],
            int(p["use_continuity_constraint"]),
            round(p["continuity_sigma_k"], 4),
            round(p["continuity_speed_ref"], 4),
            round(p["continuity_exp"], 4),
            round(p["continuity_sigma_min"], 4),
            round(p["continuity_sigma_max"], 4),
            round(p["continuity_sigma_default"], 4),
        )

    def _run_within_cv_for_mouse(mouse, params, first_n_sec_override=None):
        params = _normalize_opt_params(params)
        sess = TFC_cond_group[mouse]
        dt_sec = _infer_dt_sec(sess)
        dist_meta = _get_2d_decoder_distance_meta(sess)
        pos_scale = float(dist_meta["scale"])
        unit_label = dist_meta["unit"]

        S = _apply_zscore_single(sess.S, str(params["use_z_score"]))
        x = _scale_2d_position_array(sess.loc_X_miniscope_smooth, pos_scale)[:S.shape[1]]
        y = _scale_2d_position_array(sess.loc_Y_miniscope_smooth, pos_scale)[:S.shape[1]]
        mask = build_pretone_mask_TFC(
            sess,
            first_n_sec=optimization_first_n_sec if first_n_sec_override is None else float(first_n_sec_override),
            use_speed=optimization_use_speed,
            min_speed=optimization_min_speed,
            encoder_period=encoder_period,
        )[:S.shape[1]]
        speed_vec = _get_miniscope_velocity_vector(sess, T=S.shape[1])

        res = _within_session_2D_cv(
            S,
            x,
            y,
            mask,
            dt_sec,
            n_x_bins=int(params["n_spatial_bins"]),
            n_y_bins=int(params["n_spatial_bins"]),
            time_bin_frames=int(params["time_bin_frames"]),
            use_posterior_mean=bool(params["use_posterior_mean"]),
            decoder_type="bayesian",
            use_continuity_constraint=bool(params["use_continuity_constraint"]),
            continuity_sigma_k=float(params["continuity_sigma_k"]),
            continuity_speed_ref=float(params["continuity_speed_ref"]),
            continuity_exp=float(params["continuity_exp"]),
            continuity_sigma_min=float(params["continuity_sigma_min"]),
            continuity_sigma_max=float(params["continuity_sigma_max"]),
            continuity_sigma_default=float(params["continuity_sigma_default"]),
            speed_vec=speed_vec,
            position_unit=unit_label,
            position_scale=pos_scale,
        )

        return {
            "res": res,
            "n_cells": int(S.shape[0]),
            "n_pretone": int(np.sum(mask)),
            "position_unit": unit_label,
        }

    def _evaluate_decoder_params_on_subset(params, mice_subset, active_first_n_sec):
        rows = []
        for mouse in mice_subset:
            try:
                detail = _run_within_cv_for_mouse(mouse, params, first_n_sec_override=active_first_n_sec)
                res = detail["res"]
            except Exception as exc:
                rows.append({
                    "mouse": mouse,
                    "ok": False,
                    "median_err": np.nan,
                    "median_jitter": np.nan,
                    "n_cells": 0,
                    "n_pretone": 0,
                    "reason": str(exc),
                })
                continue

            if not res.get("ok", False):
                rows.append({
                    "mouse": mouse,
                    "ok": False,
                    "median_err": np.nan,
                    "median_jitter": np.nan,
                    "n_cells": detail["n_cells"],
                    "n_pretone": detail["n_pretone"],
                    "reason": res.get("reason", "decode failed"),
                })
                continue

            # Compute median jitter from decoded positions in both CV folds
            _jitter_parts = []
            for _fold_key in ("even_to_odd", "odd_to_even"):
                _fold = res.get(_fold_key, {})
                _out = _fold.get("out", {})
                _jit = _compute_median_jitter(
                    _out.get("decoded_x", np.array([])),
                    _out.get("decoded_y", np.array([])),
                )
                if np.isfinite(_jit):
                    _jitter_parts.append(_jit)
            _med_jitter = float(np.median(_jitter_parts)) if _jitter_parts else np.nan

            rows.append({
                "mouse": mouse,
                "ok": True,
                "median_err": float(res.get("median_err", np.nan)),
                "median_jitter": _med_jitter,
                "n_cells": detail["n_cells"],
                "n_pretone": detail["n_pretone"],
                "reason": "",
            })

        df_eval = pd.DataFrame(rows)
        valid = df_eval[df_eval["ok"] & np.isfinite(df_eval["median_err"])]
        if valid.empty:
            return np.inf, np.inf, 0, df_eval
        score = float(np.nanmedian(valid["median_err"].to_numpy()))
        jitter_score = float(np.nanmedian(valid["median_jitter"].to_numpy())) if "median_jitter" in valid.columns else 0.0
        return score, jitter_score, int(valid.shape[0]), df_eval

    def _screen_candidate_mice(candidate_mice, first_n_sec_to_use):
        rows = []
        for mouse in candidate_mice:
            try:
                detail = _run_within_cv_for_mouse(mouse, baseline_params, first_n_sec_override=first_n_sec_to_use)
                res = detail["res"]
            except Exception as exc:
                rows.append({
                    "mouse": mouse,
                    "ok": False,
                    "median_err": np.nan,
                    "n_cells": 0,
                    "n_pretone": 0,
                    "reason": f"Exception: {exc}",
                })
                continue

            rows.append({
                "mouse": mouse,
                "ok": bool(res.get("ok", False)),
                "median_err": float(res.get("median_err", np.nan)) if res.get("ok", False) else np.nan,
                "n_cells": int(detail["n_cells"]),
                "n_pretone": int(detail["n_pretone"]),
                "reason": "" if res.get("ok", False) else str(res.get("reason", "decode failed")),
            })

        df_screen = pd.DataFrame(rows)
        if not df_screen.empty:
            df_screen["quality"] = (
                df_screen["n_cells"].astype(float)
                * np.sqrt(np.maximum(df_screen["n_pretone"].astype(float), 1.0))
            )
        return df_screen

    def _plot_xy_true_vs_decoded(split_out, fig_title, save_file, unit_label="px"):
        err = np.asarray(split_out.get("euclidean_err", np.array([])), dtype=float)

        fig, axes = plt.subplots(1, 2, figsize=(12, 5), dpi=150)
        for ax, t, d, lb in [
            (axes[0], split_out["true_x"], split_out["decoded_x"], "X"),
            (axes[1], split_out["true_y"], split_out["decoded_y"], "Y"),
        ]:
            ax.scatter(t, d, s=8, alpha=0.35)
            if len(t) > 0 and len(d) > 0:
                lo = min(np.nanmin(t), np.nanmin(d))
                hi = max(np.nanmax(t), np.nanmax(d))
                ax.plot([lo, hi], [lo, hi], "r-", lw=1.2)
            ax.set_xlabel(f"True {lb} ({unit_label})")
            ax.set_ylabel(f"Decoded {lb} ({unit_label})")
            ax.grid(True, alpha=0.2)
        fig.suptitle(fig_title)
        fig.tight_layout()
        fig.savefig(save_file, dpi=250)
        plt.close(fig)

        fig, ax = plt.subplots(figsize=(7, 7), dpi=150)
        ax.plot(split_out["true_x"], split_out["true_y"], "k-", alpha=0.18, lw=0.6, label="true")
        sc = ax.scatter(
            split_out["decoded_x"],
            split_out["decoded_y"],
            c=err if err.size else np.zeros_like(split_out["decoded_x"]),
            s=12,
            alpha=0.65,
            cmap="hot",
            vmin=0,
            vmax=np.nanpercentile(err, 95) if err.size else 1,
            label="decoded",
        )
        cb = plt.colorbar(sc, ax=ax, pad=0.02)
        cb.set_label(f"Euclidean error ({unit_label})")
        ax.set_xlabel(f"True/Decoded X ({unit_label})")
        ax.set_ylabel(f"True/Decoded Y ({unit_label})")
        ax.set_title(fig_title + " trajectory")
        ax.set_aspect("equal")
        ax.legend(loc="best")
        fig.tight_layout()
        fig.savefig(save_file.replace(".png", "_traj.png"), dpi=250)
        plt.close(fig)

    candidate_mice = sorted(list(TFC_cond_group.keys()))
    if len(candidate_mice) == 0:
        print("[OPT] No TFC_cond sessions available; skipping optimization.")
        return result

    active_optimization_first_n_sec = float(optimization_first_n_sec)
    df_baseline_screen = _screen_candidate_mice(candidate_mice, active_optimization_first_n_sec)
    if not df_baseline_screen.empty:
        baseline_screen_csv = os.path.join(opt_tables_dir, "decoder_2d_baseline_candidate_screen.csv")
        df_baseline_screen.to_csv(baseline_screen_csv, index=False)
        print(f"[OPT] Saved baseline candidate screen: {baseline_screen_csv}")
        df_ok = df_baseline_screen[df_baseline_screen["ok"]].sort_values(
            ["quality", "n_cells", "mouse"], ascending=[False, False, True]
        )
    else:
        df_ok = pd.DataFrame()

    if df_ok.empty:
        print(f"[OPT] No valid baseline decodes for candidate subset at first_n_sec={active_optimization_first_n_sec}.")
        if not df_baseline_screen.empty:
            print("[OPT] Baseline screen failures:")
            print(df_baseline_screen[["mouse", "n_cells", "n_pretone", "reason"]].to_string(index=False))
        print("[OPT] Skipping optimization after baseline-screen failure.")
        return result

    subset_mice = df_ok["mouse"].tolist()[:optimization_subset_mouse_count]
    result["subset_mice"] = list(subset_mice)
    print(f"[OPT] Candidate mice: {len(candidate_mice)}")
    print(f"[OPT] Selected subset ({len(subset_mice)} mice): {subset_mice}")
    print(f"[OPT] Objective: median euclidean error on {optimization_target} (first_n_sec={active_optimization_first_n_sec})")

    optimization_trials_records = []

    try:
        import importlib
        optuna = importlib.import_module("optuna")
    except Exception:
        optuna = None

    if optuna is not None:
        sampler = optuna.samplers.TPESampler(
            seed=optimization_seed,
            n_startup_trials=optimization_n_startup_trials,
        )
        study = optuna.create_study(direction="minimize", sampler=sampler)

        def _objective(trial):
            p_n_bins = int(trial.suggest_int("n_spatial_bins", 12, 30, step=2))
            p_time = int(trial.suggest_int("time_bin_frames", 8, 24, step=1))
            p_post = bool(trial.suggest_categorical("use_posterior_mean", [True, False]))
            p_z = str(trial.suggest_categorical("use_z_score", ["none", "per-session", "across-sessions"]))
            p_k = float(trial.suggest_float("continuity_sigma_k", 15.0, 50.0))
            p_vref = float(trial.suggest_float("continuity_speed_ref", 10.0, 30.0))
            p_exp = float(trial.suggest_float("continuity_exp", 0.8, 1.2))
            p_min = float(trial.suggest_float("continuity_sigma_min", 5.0, 20.0))
            p_max = float(trial.suggest_float("continuity_sigma_max", p_min + 5.0, 40.0))
            p_def = float(trial.suggest_float("continuity_sigma_default", p_min, p_max))

            params = {
                "n_spatial_bins": p_n_bins,
                "time_bin_frames": p_time,
                "use_posterior_mean": p_post,
                "use_z_score": p_z,
                "use_continuity_constraint": True,
                "continuity_sigma_k": p_k,
                "continuity_speed_ref": p_vref,
                "continuity_exp": p_exp,
                "continuity_sigma_min": p_min,
                "continuity_sigma_max": p_max,
                "continuity_sigma_default": p_def,
            }

            score, jitter, n_ok, _ = _evaluate_decoder_params_on_subset(
                params,
                subset_mice,
                active_optimization_first_n_sec,
            )
            penalty = 5000.0 * max(0, len(subset_mice) - n_ok)
            jitter_penalty = jitter_lambda * jitter if np.isfinite(jitter) else 0.0
            score_final = float(score + jitter_penalty + penalty)
            optimization_trials_records.append({
                "trial": int(trial.number),
                "score": score_final,
                "score_raw": float(score),
                "jitter": float(jitter) if np.isfinite(jitter) else 0.0,
                "n_ok_mice": int(n_ok),
                **params,
            })
            return score_final

        study.optimize(_objective, n_trials=optimization_trials, show_progress_bar=False)
        best_params = dict(study.best_params)
        best_params["use_continuity_constraint"] = True
    else:
        print("[OPT][WARN] Optuna not available; using seeded random search fallback.")
        rng = np.random.default_rng(optimization_seed)
        best_score = np.inf
        best_params = None

        for i in range(int(optimization_trials)):
            p_min = float(rng.uniform(5.0, 30.0))
            p_max = float(rng.uniform(p_min + 5.0, 90.0))
            params = {
                "n_spatial_bins": int(rng.integers(12, 31) // 2 * 2),
                "time_bin_frames": int(rng.integers(8, 25)),
                "use_posterior_mean": bool(rng.choice([True, False])),
                "use_z_score": str(rng.choice(["none", "per-session", "across-sessions"])),
                "use_continuity_constraint": True,
                "continuity_sigma_k": float(rng.uniform(20.0, 90.0)),
                "continuity_speed_ref": float(rng.uniform(8.0, 40.0)),
                "continuity_exp": float(rng.uniform(0.6, 1.6)),
                "continuity_sigma_min": p_min,
                "continuity_sigma_max": p_max,
                "continuity_sigma_default": float(rng.uniform(p_min, p_max)),
            }
            score, jitter, n_ok, _ = _evaluate_decoder_params_on_subset(
                params,
                subset_mice,
                active_optimization_first_n_sec,
            )
            jitter_penalty = jitter_lambda * jitter if np.isfinite(jitter) else 0.0
            score_final = float(score + jitter_penalty + 5000.0 * max(0, len(subset_mice) - n_ok))
            optimization_trials_records.append({
                "trial": int(i),
                "score": score_final,
                "score_raw": float(score),
                "n_ok_mice": int(n_ok),
                **params,
            })
            if score_final < best_score:
                best_score = score_final
                best_params = dict(params)

    if best_params is None:
        print("[OPT][WARN] Optimization did not produce a valid best parameter set; keeping baseline.")
        return result

    best_params = _normalize_opt_params(best_params)
    baseline_params = _normalize_opt_params(baseline_params)

    base_score, _, base_n_ok, base_df = _evaluate_decoder_params_on_subset(
        baseline_params,
        subset_mice,
        active_optimization_first_n_sec,
    )
    best_score, _, best_n_ok, best_df = _evaluate_decoder_params_on_subset(
        best_params,
        subset_mice,
        active_optimization_first_n_sec,
    )

    df_trials = pd.DataFrame(optimization_trials_records)
    if not df_trials.empty:
        df_trials = df_trials.sort_values("score", ascending=True)
        trial_csv = os.path.join(opt_tables_dir, "decoder_2d_hyperopt_trials.csv")
        df_trials.to_csv(trial_csv, index=False)
        print(f"[OPT] Saved trial table: {trial_csv}")

    base_csv = os.path.join(opt_tables_dir, "decoder_2d_hyperopt_baseline_subset_eval.csv")
    best_csv = os.path.join(opt_tables_dir, "decoder_2d_hyperopt_best_subset_eval.csv")
    base_df.to_csv(base_csv, index=False)
    best_df.to_csv(best_csv, index=False)
    print(f"[OPT] Saved baseline subset eval: {base_csv}")
    print(f"[OPT] Saved best subset eval: {best_csv}")

    pd.Series(baseline_params, name="baseline_value").to_csv(
        os.path.join(opt_tables_dir, "decoder_2d_baseline_params.csv"),
        header=True,
    )
    pd.Series(best_params, name="best_value").to_csv(
        os.path.join(opt_tables_dir, "decoder_2d_best_params.csv"),
        header=True,
    )

    print("\n[OPT] Baseline params -> score:", f"{base_score:.3f}", f"(n_ok={base_n_ok})")
    print("[OPT] Best params      -> score:", f"{best_score:.3f}", f"(n_ok={best_n_ok})")
    print("[OPT] Applied optimized parameters to runtime configuration.")
    print(
        f"[OPT] N_SPATIAL_BINS={int(best_params['n_spatial_bins'])}, "
        f"TIME_BIN_FRAMES={int(best_params['time_bin_frames'])}, "
        f"use_posterior_mean={bool(best_params['use_posterior_mean'])}, "
        f"use_z_score={str(best_params['use_z_score'])}"
    )
    print(
        f"[OPT] continuity: k={float(best_params['continuity_sigma_k']):.3f}, "
        f"Vref={float(best_params['continuity_speed_ref']):.3f}, "
        f"exp={float(best_params['continuity_exp']):.3f}, "
        f"min={float(best_params['continuity_sigma_min']):.3f}, "
        f"max={float(best_params['continuity_sigma_max']):.3f}, "
        f"default={float(best_params['continuity_sigma_default']):.3f}"
    )

    sample_paramsets = [
        {"label": "baseline", "params": baseline_params},
        {"label": "best", "params": best_params},
    ]

    if not df_trials.empty:
        keep_top = min(6, int(df_trials.shape[0]))
        for _, row in df_trials.head(keep_top).iterrows():
            p_row = {
                "n_spatial_bins": row["n_spatial_bins"],
                "time_bin_frames": row["time_bin_frames"],
                "use_posterior_mean": row["use_posterior_mean"],
                "use_z_score": row["use_z_score"],
                "use_continuity_constraint": row.get("use_continuity_constraint", True),
                "continuity_sigma_k": row["continuity_sigma_k"],
                "continuity_speed_ref": row["continuity_speed_ref"],
                "continuity_exp": row["continuity_exp"],
                "continuity_sigma_min": row["continuity_sigma_min"],
                "continuity_sigma_max": row["continuity_sigma_max"],
                "continuity_sigma_default": row["continuity_sigma_default"],
            }
            sample_paramsets.append({
                "label": f"top_trial_{int(row['trial']):03d}",
                "params": _normalize_opt_params(p_row),
            })

    unique_paramsets = []
    seen = set()
    for item in sample_paramsets:
        sig = _param_signature(item["params"])
        if sig in seen:
            continue
        seen.add(sig)
        unique_paramsets.append(item)

    for idx_ps, item in enumerate(unique_paramsets):
        ps_dir = os.path.join(opt_paramsets_dir, f"{idx_ps:02d}_{item['label']}")
        os.makedirs(ps_dir, exist_ok=True)
        pd.Series(item["params"], name="value").to_csv(
            os.path.join(ps_dir, "params.csv"),
            header=True,
        )

        for mouse in subset_mice:
            mouse_dir = os.path.join(ps_dir, f"mouse_{mouse}")
            os.makedirs(mouse_dir, exist_ok=True)
            try:
                detail = _run_within_cv_for_mouse(
                    mouse,
                    item["params"],
                    first_n_sec_override=active_optimization_first_n_sec,
                )
                res = detail["res"]
                if not res.get("ok", False):
                    with open(os.path.join(mouse_dir, "status.txt"), "w", encoding="utf-8") as f:
                        f.write(f"FAILED: {res.get('reason', 'decode failed')}\n")
                    continue

                split_map = {
                    "even_to_odd": res["even_to_odd"]["out"],
                    "odd_to_even": res["odd_to_even"]["out"],
                }
                for split_name, split_out in split_map.items():
                    fig_title = (
                        f"{mouse} | {item['label']} | {split_name} | "
                        f"med_err={np.nanmedian(split_out['euclidean_err']):.2f}"
                    )
                    save_file = os.path.join(mouse_dir, f"xy_true_vs_decoded_{split_name}.png")
                    _plot_xy_true_vs_decoded(
                        split_out,
                        fig_title,
                        save_file,
                        unit_label=detail["position_unit"],
                    )

                with open(os.path.join(mouse_dir, "status.txt"), "w", encoding="utf-8") as f:
                    f.write("OK\n")
                    f.write(f"n_cells={detail['n_cells']}\n")
                    f.write(f"n_pretone={detail['n_pretone']}\n")
                    f.write(f"median_err={float(res.get('median_err', np.nan)):.4f}\n")
            except Exception as exc:
                with open(os.path.join(mouse_dir, "status.txt"), "w", encoding="utf-8") as f:
                    f.write(f"FAILED: {exc}\n")

    for mouse in subset_mice:
        try:
            base_detail = _run_within_cv_for_mouse(
                mouse,
                baseline_params,
                first_n_sec_override=active_optimization_first_n_sec,
            )
            best_detail = _run_within_cv_for_mouse(
                mouse,
                best_params,
                first_n_sec_override=active_optimization_first_n_sec,
            )
            base_res = base_detail["res"]
            best_res = best_detail["res"]
            if (not base_res.get("ok", False)) or (not best_res.get("ok", False)):
                continue

            fig, axes = plt.subplots(1, 2, figsize=(12, 5.2), dpi=150)
            for ax, split_name in zip(axes, ["even_to_odd", "odd_to_even"]):
                out_base = base_res[split_name]["out"]
                out_best = best_res[split_name]["out"]

                ax.plot(
                    out_base["true_x"], out_base["true_y"],
                    color="black", lw=0.9, alpha=0.28, label="true"
                )
                ax.plot(
                    out_base["decoded_x"], out_base["decoded_y"],
                    color="tab:orange", lw=1.0, alpha=0.75, label="baseline decoded"
                )
                ax.plot(
                    out_best["decoded_x"], out_best["decoded_y"],
                    color="tab:green", lw=1.0, alpha=0.75, label="best decoded"
                )

                m_base = float(np.nanmedian(out_base["euclidean_err"]))
                m_best = float(np.nanmedian(out_best["euclidean_err"]))
                ax.set_title(f"{split_name} | baseline={m_base:.2f}, best={m_best:.2f}")
                ax.set_xlabel(f"X ({base_detail['position_unit']})")
                ax.set_ylabel(f"Y ({base_detail['position_unit']})")
                ax.set_aspect("equal")
                ax.grid(True, alpha=0.2)

            handles, labels = axes[0].get_legend_handles_labels()
            if handles:
                fig.legend(handles, labels, loc="upper center", ncol=3, frameon=False)
            fig.suptitle(f"{mouse}: Baseline vs Best decoded trajectories")
            fig.tight_layout(rect=[0, 0, 1, 0.94])
            fig.savefig(
                os.path.join(opt_summary_dir, f"baseline_vs_best_trajectory_overlay_{mouse}.png"),
                dpi=250,
            )
            plt.close(fig)
        except Exception:
            pass

    if not df_trials.empty:
        z_map = {"none": 0.0, "per-session": 1.0, "across-sessions": 2.0}
        df_plot = df_trials.copy()
        df_plot["use_posterior_mean_num"] = df_plot["use_posterior_mean"].astype(int)
        df_plot["use_z_score_num"] = df_plot["use_z_score"].map(z_map).astype(float)

        plot_cols = [
            "n_spatial_bins", "time_bin_frames",
            "continuity_sigma_k", "continuity_speed_ref", "continuity_exp",
            "continuity_sigma_min", "continuity_sigma_max", "continuity_sigma_default",
            "use_posterior_mean_num", "use_z_score_num",
        ]

        n_cols = 3
        n_rows = int(np.ceil(len(plot_cols) / n_cols))
        fig, axes = plt.subplots(n_rows, n_cols, figsize=(4.5 * n_cols, 3.4 * n_rows), dpi=150)
        axes = np.array(axes).reshape(-1)
        for i, c in enumerate(plot_cols):
            ax = axes[i]
            ax.scatter(df_plot[c], df_plot["score_raw"], s=18, alpha=0.55)
            ax.set_xlabel(c)
            ax.set_ylabel("median error")
            ax.grid(True, alpha=0.2)
        for j in range(len(plot_cols), len(axes)):
            axes[j].axis("off")
        fig.suptitle("Parameter vs error (within-TFC optimization trials)")
        fig.tight_layout()
        fig.savefig(os.path.join(opt_summary_dir, "parameter_vs_error_scatter_grid.png"), dpi=250)
        plt.close(fig)

        corr_vals = {}
        yv = df_plot["score_raw"].to_numpy(dtype=float)
        for c in plot_cols:
            xv = df_plot[c].to_numpy(dtype=float)
            if len(xv) < 3 or np.nanstd(xv) <= 1e-12:
                corr_vals[c] = 0.0
            else:
                corr_vals[c] = float(np.abs(np.corrcoef(xv, yv)[0, 1]))

        corr_items = sorted(corr_vals.items(), key=lambda kv: kv[1], reverse=True)
        fig, ax = plt.subplots(figsize=(10, 4), dpi=150)
        ax.bar([k for k, _ in corr_items], [v for _, v in corr_items], color="slateblue", alpha=0.85)
        ax.set_ylabel("|corr(param, error)|")
        ax.set_title("Bird's-eye parameter influence proxy")
        ax.tick_params(axis="x", rotation=35)
        ax.grid(True, axis="y", alpha=0.25)
        fig.tight_layout()
        fig.savefig(os.path.join(opt_summary_dir, "parameter_influence_proxy.png"), dpi=250)
        plt.close(fig)

        top2 = [k for k, _ in corr_items[:2]]
        if len(top2) == 2:
            fig, ax = plt.subplots(figsize=(7.0, 5.8), dpi=150)
            hb = ax.hexbin(
                df_plot[top2[0]].to_numpy(dtype=float),
                df_plot[top2[1]].to_numpy(dtype=float),
                C=df_plot["score_raw"].to_numpy(dtype=float),
                reduce_C_function=np.mean,
                gridsize=16,
                cmap="viridis",
                mincnt=1,
            )
            cb = fig.colorbar(hb, ax=ax)
            cb.set_label("mean median error")
            ax.set_xlabel(top2[0])
            ax.set_ylabel(top2[1])
            ax.set_title("Error landscape (hexbin over trial space)")
            fig.tight_layout()
            fig.savefig(
                os.path.join(opt_summary_dir, f"error_landscape_hexbin_{top2[0]}_vs_{top2[1]}.png"),
                dpi=250,
            )
            plt.close(fig)

    result["ok"] = True
    result["ran"] = True
    result["status"] = "optimized"
    result["baseline_params"] = dict(baseline_params)
    result["best_params"] = dict(best_params)
    result["applied_params"] = dict(best_params)

    print(f"[OPT] Reporting directory: {opt_dir}")
    return result


# ---------------------------------------------------------------------------
#  Group-aware 2D decoder parameter optimization
# ---------------------------------------------------------------------------

def optimize_2d_decoder_parameters_grouped(
    TFC_cond_group: dict,
    *,
    mouse_groups: dict,
    PLOTS_DIR: str,
    encoder_period: str = "pre-tone",
    paramset: "BayesianDecoderParamset" = None,
    optimization_trials: int = 50,
    optimization_seed: int = 42,
    optimization_first_n_sec: float = 180.0,
    optimization_target: str = "within_TFC",
    optimization_use_speed: bool = True,
    optimization_min_speed: float = 2.0,
    optimization_n_startup_trials: int = 12,
    skip_optimization: bool = False,
    jitter_lambda: float = 0.5,
) -> Dict[str, Any]:
    """Run per-group + pooled Optuna optimizations, cross-evaluate, plot & summarise.

    Parameters
    ----------
    paramset : BayesianDecoderParamset
        Baseline decoder parameters.  The optimizer uses these as starting
        values and search-space anchors.

    Returns a dict with keys:
      - "param_sets": {set_label: param_dict}   (baseline, pooled, <group1>, …)
      - "cross_eval": pd.DataFrame               per-mouse × per-param_set scores
      - "opt_dir": str                            path to output directory
      - "ok": bool
    """
    if paramset is None:
        paramset = BayesianDecoderParamset()

    # ---- extract to locals (rest of function body is unchanged) ----
    n_spatial_bins          = paramset.n_spatial_bins
    time_bin_frames         = paramset.time_bin_frames
    use_posterior_mean      = paramset.use_posterior_mean
    use_z_score             = paramset.use_z_score
    use_continuity_constraint = paramset.use_continuity_constraint
    continuity_sigma_k      = paramset.continuity_sigma_k
    continuity_speed_ref    = paramset.continuity_speed_ref
    continuity_exp          = paramset.continuity_exp
    continuity_sigma_min    = paramset.continuity_sigma_min
    continuity_sigma_max    = paramset.continuity_sigma_max
    continuity_sigma_default = paramset.continuity_sigma_default

    _baseline_z = "per-session" if str(use_z_score).strip().lower() == "optimize" else str(use_z_score)

    baseline_params = {
        "n_spatial_bins": int(n_spatial_bins),
        "time_bin_frames": int(time_bin_frames),
        "use_posterior_mean": bool(use_posterior_mean),
        "use_z_score": _baseline_z,
        "use_continuity_constraint": bool(use_continuity_constraint),
        "continuity_sigma_k": float(continuity_sigma_k),
        "continuity_speed_ref": float(continuity_speed_ref),
        "continuity_exp": float(continuity_exp),
        "continuity_sigma_min": float(continuity_sigma_min),
        "continuity_sigma_max": float(continuity_sigma_max),
        "continuity_sigma_default": float(continuity_sigma_default),
    }

    os.makedirs(PLOTS_DIR, exist_ok=True)
    opt_dir = os.path.join(PLOTS_DIR, "2D_decoder_optimization")
    os.makedirs(opt_dir, exist_ok=True)
    opt_tables_dir = os.path.join(opt_dir, "tables")
    opt_plots_dir = os.path.join(opt_dir, "summary")
    os.makedirs(opt_tables_dir, exist_ok=True)
    os.makedirs(opt_plots_dir, exist_ok=True)

    # ----- helper closures (same logic as original optimizer) -----

    def _normalize(params):
        return {
            "n_spatial_bins": int(params["n_spatial_bins"]),
            "time_bin_frames": int(params["time_bin_frames"]),
            "use_posterior_mean": bool(params["use_posterior_mean"]),
            "use_z_score": str(params["use_z_score"]),
            "use_continuity_constraint": bool(params.get("use_continuity_constraint", True)),
            "continuity_sigma_k": float(params["continuity_sigma_k"]),
            "continuity_speed_ref": float(params["continuity_speed_ref"]),
            "continuity_exp": float(params["continuity_exp"]),
            "continuity_sigma_min": float(params["continuity_sigma_min"]),
            "continuity_sigma_max": float(params["continuity_sigma_max"]),
            "continuity_sigma_default": float(params["continuity_sigma_default"]),
        }

    def _run_cv(mouse, params, first_n_sec_override=None):
        params = _normalize(params)
        sess = TFC_cond_group[mouse]
        dt_sec = _infer_dt_sec(sess)
        dist_meta = _get_2d_decoder_distance_meta(sess)
        pos_scale = float(dist_meta["scale"])
        unit_label = dist_meta["unit"]

        S = _apply_zscore_single(sess.S, str(params["use_z_score"]))
        x = _scale_2d_position_array(sess.loc_X_miniscope_smooth, pos_scale)[:S.shape[1]]
        y = _scale_2d_position_array(sess.loc_Y_miniscope_smooth, pos_scale)[:S.shape[1]]
        mask = build_pretone_mask_TFC(
            sess,
            first_n_sec=optimization_first_n_sec if first_n_sec_override is None else float(first_n_sec_override),
            use_speed=optimization_use_speed,
            min_speed=optimization_min_speed,
            encoder_period=encoder_period,
        )[:S.shape[1]]
        speed_vec = _get_miniscope_velocity_vector(sess, T=S.shape[1])

        res = _within_session_2D_cv(
            S, x, y, mask, dt_sec,
            n_x_bins=int(params["n_spatial_bins"]),
            n_y_bins=int(params["n_spatial_bins"]),
            time_bin_frames=int(params["time_bin_frames"]),
            use_posterior_mean=bool(params["use_posterior_mean"]),
            decoder_type="bayesian",
            use_continuity_constraint=bool(params["use_continuity_constraint"]),
            continuity_sigma_k=float(params["continuity_sigma_k"]),
            continuity_speed_ref=float(params["continuity_speed_ref"]),
            continuity_exp=float(params["continuity_exp"]),
            continuity_sigma_min=float(params["continuity_sigma_min"]),
            continuity_sigma_max=float(params["continuity_sigma_max"]),
            continuity_sigma_default=float(params["continuity_sigma_default"]),
            speed_vec=speed_vec,
            position_unit=unit_label,
            position_scale=pos_scale,
        )
        # Compute median jitter from decoded positions in both CV folds
        if res.get("ok", False):
            _jitter_parts = []
            for _fold_key in ("even_to_odd", "odd_to_even"):
                _fold = res.get(_fold_key, {})
                _out = _fold.get("out", {})
                _jit = _compute_median_jitter(
                    _out.get("decoded_x", np.array([])),
                    _out.get("decoded_y", np.array([])),
                )
                if np.isfinite(_jit):
                    _jitter_parts.append(_jit)
            res["median_jitter"] = float(np.median(_jitter_parts)) if _jitter_parts else np.nan
        return res

    def _eval_on_mice(params, mice_list):
        """Return (score, jitter_score, n_ok, df) where score = median of per-mouse medians."""
        rows = []
        for mouse in mice_list:
            try:
                res = _run_cv(mouse, params, first_n_sec_override=optimization_first_n_sec)
            except Exception as exc:
                rows.append({"mouse": mouse, "ok": False, "median_err": np.nan, "median_jitter": np.nan, "reason": str(exc)})
                continue
            if not res.get("ok", False):
                rows.append({"mouse": mouse, "ok": False, "median_err": np.nan, "median_jitter": np.nan,
                             "reason": res.get("reason", "decode failed")})
                continue
            rows.append({"mouse": mouse, "ok": True,
                         "median_err": float(res.get("median_err", np.nan)),
                         "median_jitter": float(res.get("median_jitter", np.nan)),
                         "reason": ""})
        df = pd.DataFrame(rows)
        valid = df[df["ok"] & np.isfinite(df["median_err"])]
        score = float(np.nanmedian(valid["median_err"].to_numpy())) if not valid.empty else np.inf
        jitter_score = float(np.nanmedian(valid["median_jitter"].to_numpy())) if (not valid.empty and "median_jitter" in valid.columns) else 0.0
        return score, jitter_score, int(valid.shape[0]), df

    # ----- Optuna study runner -----

    def _run_optuna_study(study_label, mice_list, seed_offset=0):
        """Run an Optuna study on *mice_list*. Returns (best_params, df_trials)."""
        try:
            import importlib
            optuna = importlib.import_module("optuna")
        except Exception:
            optuna = None

        trial_records = []

        if optuna is not None:
            sampler = optuna.samplers.TPESampler(
                seed=optimization_seed + seed_offset,
                n_startup_trials=optimization_n_startup_trials,
            )
            study = optuna.create_study(direction="minimize", sampler=sampler)

            def _objective(trial):
                p_n_bins = int(trial.suggest_int("n_spatial_bins", 12, 30, step=2))
                p_time = int(trial.suggest_int("time_bin_frames", 8, 24, step=1))
                p_post = bool(trial.suggest_categorical("use_posterior_mean", [True, False]))
                if _optimize_z_score:
                    p_z = str(trial.suggest_categorical("use_z_score", ["none", "per-session", "across-sessions"]))
                else:
                    p_z = str(use_z_score)
                p_k = float(trial.suggest_float("continuity_sigma_k", 15.0, 50.0))
                p_vref = float(trial.suggest_float("continuity_speed_ref", 10.0, 30.0))
                p_exp = float(trial.suggest_float("continuity_exp", 0.8, 1.2))
                p_min = float(trial.suggest_float("continuity_sigma_min", 5.0, 20.0))
                p_max = float(trial.suggest_float("continuity_sigma_max", p_min + 5.0, 40.0))
                p_def = float(trial.suggest_float("continuity_sigma_default", p_min, p_max))

                params = {
                    "n_spatial_bins": p_n_bins,
                    "time_bin_frames": p_time,
                    "use_posterior_mean": p_post,
                    "use_z_score": p_z,
                    "use_continuity_constraint": True,
                    "continuity_sigma_k": p_k,
                    "continuity_speed_ref": p_vref,
                    "continuity_exp": p_exp,
                    "continuity_sigma_min": p_min,
                    "continuity_sigma_max": p_max,
                    "continuity_sigma_default": p_def,
                }
                score, jitter, n_ok, _ = _eval_on_mice(params, mice_list)
                penalty = 5000.0 * max(0, len(mice_list) - n_ok)
                jitter_penalty = jitter_lambda * jitter if np.isfinite(jitter) else 0.0
                score_final = float(score + jitter_penalty + penalty)
                trial_records.append({
                    "trial": int(trial.number),
                    "score": score_final,
                    "score_raw": float(score),
                    "jitter": float(jitter) if np.isfinite(jitter) else 0.0,
                    "n_ok_mice": int(n_ok),
                    **params,
                })
                return score_final

            study.optimize(_objective, n_trials=optimization_trials, show_progress_bar=False)
            best_p = dict(study.best_params)
            best_p["use_continuity_constraint"] = True
            if not _optimize_z_score:
                best_p["use_z_score"] = str(use_z_score)
        else:
            # random search fallback
            rng = np.random.default_rng(optimization_seed + seed_offset)
            best_score = np.inf
            best_p = None
            for i in range(int(optimization_trials)):
                p_min = float(rng.uniform(5.0, 30.0))
                p_max = float(rng.uniform(p_min + 5.0, 90.0))
                _rng_z = str(rng.choice(["none", "per-session", "across-sessions"])) if _optimize_z_score else str(use_z_score)
                params = {
                    "n_spatial_bins": int(rng.integers(12, 31) // 2 * 2),
                    "time_bin_frames": int(rng.integers(8, 25)),
                    "use_posterior_mean": bool(rng.choice([True, False])),
                    "use_z_score": _rng_z,
                    "use_continuity_constraint": True,
                    "continuity_sigma_k": float(rng.uniform(20.0, 90.0)),
                    "continuity_speed_ref": float(rng.uniform(8.0, 40.0)),
                    "continuity_exp": float(rng.uniform(0.6, 1.6)),
                    "continuity_sigma_min": p_min,
                    "continuity_sigma_max": p_max,
                    "continuity_sigma_default": float(rng.uniform(p_min, p_max)),
                }
                score, jitter, n_ok, _ = _eval_on_mice(params, mice_list)
                jitter_penalty = jitter_lambda * jitter if np.isfinite(jitter) else 0.0
                score_final = float(score + jitter_penalty + 5000.0 * max(0, len(mice_list) - n_ok))
                trial_records.append({
                    "trial": int(i), "score": score_final, "score_raw": float(score),
                    "jitter": float(jitter) if np.isfinite(jitter) else 0.0,
                    "n_ok_mice": int(n_ok), **params,
                })
                if score_final < best_score:
                    best_score = score_final
                    best_p = dict(params)

        df_trials = pd.DataFrame(trial_records)
        if best_p is not None:
            best_p = _normalize(best_p)
        return best_p, df_trials

    # ==================================================================
    # 1) Build per-group mouse lists
    # ==================================================================

    available_mice = sorted(TFC_cond_group.keys())
    group_labels = sorted(set(mouse_groups.get(m, "NA") for m in available_mice))
    group_to_mice = {}
    for gl in group_labels:
        group_to_mice[gl] = sorted(m for m in available_mice if mouse_groups.get(m, "NA") == gl)

    print("\n" + "=" * 70)
    print("2D Bayesian decoder GROUPED parameter optimization")
    print("=" * 70)
    for gl in group_labels:
        print(f"  {gl}: {group_to_mice[gl]}")
    _optimize_z_score = str(use_z_score).strip().lower() == "optimize"
    print(f"  ALL: {available_mice}")
    print(f"  Trials per study: {optimization_trials}")
    if _optimize_z_score:
        print(f"  use_z_score: OPTIMIZED (searching none / per-session / across-sessions)")
    else:
        print(f"  use_z_score (fixed): {use_z_score}")
    print("=" * 70)

    import json as _json

    # ==================================================================
    # CACHE SHORTCUT: reload param_sets + df_cross from saved files
    # ==================================================================
    if skip_optimization:
        _cached_params_json = os.path.join(opt_tables_dir, "all_param_sets.json")
        _cached_cross_csv = os.path.join(opt_tables_dir, "cross_evaluation.csv")
        if os.path.isfile(_cached_params_json) and os.path.isfile(_cached_cross_csv):
            print(f"[OPT-GRP] skip_optimization=True: loading cached results")
            with open(_cached_params_json, "r", encoding="utf-8") as _f:
                param_sets = _json.load(_f)
            # Ensure baseline is present with current hand-set values
            if "baseline" not in param_sets:
                param_sets["baseline"] = _normalize(baseline_params)
            df_cross = pd.read_csv(_cached_cross_csv)
            print(f"[OPT-GRP]   param_sets loaded: {list(param_sets.keys())}")
            print(f"[OPT-GRP]   cross_eval rows: {len(df_cross)}")
        else:
            missing = []
            if not os.path.isfile(_cached_params_json):
                missing.append(_cached_params_json)
            if not os.path.isfile(_cached_cross_csv):
                missing.append(_cached_cross_csv)
            print(f"[OPT-GRP][WARN] skip_optimization=True but cache files missing: {missing}")
            print(f"[OPT-GRP][WARN] Falling through to full optimization.")
            skip_optimization = False  # fall through

    if not skip_optimization:
        # ==================================================================
        # 2) Run optimizations: one per group + pooled
        # ==================================================================

        param_sets = {"baseline": _normalize(baseline_params)}
        all_trials = {}

        study_specs = [(gl, group_to_mice[gl]) for gl in group_labels]
        study_specs.append(("pooled", available_mice))

        for idx, (study_label, mice_list) in enumerate(study_specs):
            if len(mice_list) == 0:
                print(f"[OPT-GRP] Skipping '{study_label}': no mice available.")
                continue
            print(f"\n[OPT-GRP] Running study '{study_label}' on {len(mice_list)} mice: {mice_list}")
            best_p, df_tr = _run_optuna_study(study_label, mice_list, seed_offset=idx * 1000)

            if best_p is not None:
                param_sets[study_label] = best_p
                print(f"[OPT-GRP] '{study_label}' best score on own mice: "
                      f"{_eval_on_mice(best_p, mice_list)[0]:.3f}")
            else:
                print(f"[OPT-GRP] '{study_label}': optimization produced no valid params; skipping.")

            if not df_tr.empty:
                all_trials[study_label] = df_tr
                csv_path = os.path.join(opt_tables_dir, f"trials_{study_label}.csv")
                df_tr.sort_values("score").to_csv(csv_path, index=False)
                print(f"[OPT-GRP] Saved: {csv_path}")

        # Save param sets
        for ps_label, ps_params in param_sets.items():
            ps_csv = os.path.join(opt_tables_dir, f"params_{ps_label}.csv")
            pd.Series(ps_params, name="value").to_csv(ps_csv, header=True)

        # ==================================================================
        # 3) Cross-evaluation: every param_set × every mouse
        # ==================================================================

        print(f"\n[OPT-GRP] Cross-evaluation: {len(param_sets)} param sets × {len(available_mice)} mice")
        cross_rows = []
        for ps_label, ps_params in param_sets.items():
            for mouse in available_mice:
                grp = mouse_groups.get(mouse, "NA")
                try:
                    res = _run_cv(mouse, ps_params, first_n_sec_override=optimization_first_n_sec)
                    ok = res.get("ok", False)
                    med_err = float(res.get("median_err", np.nan)) if ok else np.nan
                except Exception as exc:
                    ok = False
                    med_err = np.nan
                cross_rows.append({
                    "param_set": ps_label,
                    "mouse": mouse,
                    "group": grp,
                    "median_err": med_err,
                    "ok": ok,
                })
        df_cross = pd.DataFrame(cross_rows)
        cross_csv = os.path.join(opt_tables_dir, "cross_evaluation.csv")
        df_cross.to_csv(cross_csv, index=False)
        print(f"[OPT-GRP] Saved: {cross_csv}")

    # ==================================================================
    # 4) Summary statistics table
    # ==================================================================

    summary_rows = []
    ps_labels = list(param_sets.keys())
    for ps_label in ps_labels:
        sub = df_cross[(df_cross["param_set"] == ps_label) & df_cross["ok"]]
        for grp in group_labels + ["ALL"]:
            if grp == "ALL":
                vals = sub["median_err"].to_numpy(dtype=float)
            else:
                vals = sub[sub["group"] == grp]["median_err"].to_numpy(dtype=float)
            vals = vals[np.isfinite(vals)]
            summary_rows.append({
                "param_set": ps_label,
                "eval_group": grp,
                "n_mice": len(vals),
                "mean_err": float(np.mean(vals)) if len(vals) > 0 else np.nan,
                "median_err": float(np.median(vals)) if len(vals) > 0 else np.nan,
                "std_err": float(np.std(vals, ddof=1)) if len(vals) > 1 else np.nan,
                "min_err": float(np.min(vals)) if len(vals) > 0 else np.nan,
                "max_err": float(np.max(vals)) if len(vals) > 0 else np.nan,
            })
    df_summary = pd.DataFrame(summary_rows)
    summary_csv = os.path.join(opt_tables_dir, "cross_eval_summary.csv")
    df_summary.to_csv(summary_csv, index=False)
    print(f"[OPT-GRP] Saved: {summary_csv}")

    # ==================================================================
    # 5) Plots  (use module-level _OPT_PS_COLORS, PLOT_RC, etc.)
    # ==================================================================

    # Apply Nature-width RC params for all optimizer plots
    import matplotlib as _mpl
    _saved_rc = {k: _mpl.rcParams[k] for k in PLOT_RC}
    _mpl.rcParams.update(PLOT_RC)

    def _ps_color(ps):
        return _OPT_PS_COLORS.get(ps, "#cccccc")

    def _ps_dot_color(ps):
        return _OPT_PS_DOT_COLORS.get(ps, "#aaaaaa")

    def _ps_label(ps):
        return _OPT_PS_LABELS.get(ps, ps)

    _BP_KW_OPT = dict(
        patch_artist=True,
        showfliers=False,
        medianprops=dict(color="black", lw=1.0),
        whiskerprops=dict(color="black", lw=0.6),
        capprops=dict(color="black", lw=0.6),
    )

    def _style_bp_opt(bp, ps, *, linestyle="-"):
        """Style boxplot patches for a given param-set key."""
        for patch in bp["boxes"]:
            patch.set_facecolor(_ps_color(ps))
            patch.set_alpha(_OPT_PS_ALPHA)
            patch.set_edgecolor("black")
            patch.set_linewidth(0.8)
            patch.set_linestyle(linestyle)
        for w in bp["whiskers"]:
            w.set_linestyle(linestyle)
        for c in bp["caps"]:
            c.set_linestyle(linestyle)

    # --- Pre-compute ALL pairwise Wilcoxon signed-rank tests (Holm-corrected) ---
    # Used by plots 5c and 5d to annotate significance stars/brackets.
    from scipy import stats as _sp_wcx
    from itertools import combinations as _combinations_pre

    _wilcox_all_pairs = {}  # (ps_a, ps_b) -> {"W", "p_raw", "p_holm", "sig", "direction"}
    _wilcox_vs_bl = {}       # ps_label -> same dict (subset for baseline comparisons)

    # Build error vectors per param set (mice common to ALL param sets)
    _ok_cross_pre = df_cross[df_cross["ok"]].copy()
    _mice_per_ps_pre = {ps: set(_ok_cross_pre[_ok_cross_pre["param_set"] == ps]["mouse"])
                        for ps in ps_labels}
    _common_mice_pre = sorted(set.intersection(*_mice_per_ps_pre.values())) if _mice_per_ps_pre else []

    if len(_common_mice_pre) >= 3 and len(ps_labels) >= 2:
        _err_vecs_pre = {}
        for ps in ps_labels:
            sub = _ok_cross_pre[_ok_cross_pre["param_set"] == ps].set_index("mouse")
            _err_vecs_pre[ps] = np.array([float(sub.loc[m, "median_err"]) for m in _common_mice_pre])

        _raw_pairs = []
        for ps_a, ps_b in _combinations_pre(ps_labels, 2):
            a_vals = _err_vecs_pre[ps_a]
            b_vals = _err_vecs_pre[ps_b]
            diff = a_vals - b_vals
            if np.all(diff == 0):
                _wilcox_all_pairs[(ps_a, ps_b)] = {
                    "W": np.nan, "p_raw": 1.0, "p_holm": 1.0, "sig": "ns",
                    "direction": "equal", "mean_diff": 0.0}
                _raw_pairs.append(((ps_a, ps_b), 1.0))
                continue
            try:
                _wst, _wp = _sp_wcx.wilcoxon(a_vals, b_vals, alternative="two-sided")
            except Exception:
                _wst, _wp = np.nan, 1.0
            _d_mean = float(np.mean(diff))
            direction = f"{ps_a} better" if _d_mean < 0 else f"{ps_b} better"
            _wilcox_all_pairs[(ps_a, ps_b)] = {
                "W": float(_wst), "p_raw": float(_wp), "mean_diff": _d_mean,
                "direction": direction}
            _raw_pairs.append(((ps_a, ps_b), float(_wp)))

        # Holm-Bonferroni correction across ALL pairs
        _sorted_pairs = sorted(_raw_pairs, key=lambda x: x[1])
        _m_corr_all = len(_sorted_pairs)
        _prev_p_all = 0.0
        for _rnk, (pair_key, _prw) in enumerate(_sorted_pairs):
            _pcw = min(1.0, _prw * (_m_corr_all - _rnk))
            _pcw = max(_pcw, _prev_p_all)
            _wilcox_all_pairs[pair_key]["p_holm"] = _pcw
            _prev_p_all = _pcw
        for pair_key in _wilcox_all_pairs:
            _phw = _wilcox_all_pairs[pair_key].get("p_holm", 1.0)
            if _phw < 0.001:
                _sig_label = "***"
            elif _phw < 0.01:
                _sig_label = "**"
            elif _phw < 0.05:
                _sig_label = "*"
            elif _phw < 0.08:
                _sig_label = f"p={_phw:.3f}"
            else:
                _sig_label = "ns"
            _wilcox_all_pairs[pair_key]["sig"] = _sig_label

        # Extract vs-baseline subset for delta plot
        for _wps in [ps for ps in ps_labels if ps != "baseline"]:
            key = ("baseline", _wps)
            if key in _wilcox_all_pairs:
                _wilcox_vs_bl[_wps] = _wilcox_all_pairs[key]
            else:
                rev_key = (_wps, "baseline")
                if rev_key in _wilcox_all_pairs:
                    _wilcox_vs_bl[_wps] = _wilcox_all_pairs[rev_key]

        # Print summary
        _sig_pairs = [(k, v) for k, v in _wilcox_all_pairs.items() if v["sig"] != "ns"]
        if _sig_pairs:
            print(f"[OPT-GRP] Significant pairwise Wilcoxon (Holm-corrected, {_m_corr_all} comparisons):")
            for (pa, pb), v in _sig_pairs:
                print(f"  {pa} vs {pb}: {v['sig']} (p_holm={v['p_holm']:.4g}, {v['direction']})")
        else:
            print(f"[OPT-GRP] No significant pairwise comparisons after Holm correction ({_m_corr_all} tests)")

    # --- 5a) Grouped bar chart: param_set × eval_group → mean error ---
    eval_groups_for_plot = group_labels + ["ALL"]
    n_ps = len(ps_labels)
    n_eg = len(eval_groups_for_plot)
    bar_width = 0.8 / max(n_ps, 1)

    fig, ax = plt.subplots(figsize=(NATURE_1COL_WIDTH_IN, NATURE_1COL_WIDTH_IN * 0.75))
    x_base = np.arange(n_eg)
    for i, ps in enumerate(ps_labels):
        means = []
        sems = []
        for eg in eval_groups_for_plot:
            row = df_summary[(df_summary["param_set"] == ps) & (df_summary["eval_group"] == eg)]
            if row.empty or np.isnan(row.iloc[0]["mean_err"]):
                means.append(0)
                sems.append(0)
            else:
                means.append(row.iloc[0]["mean_err"])
                n = row.iloc[0]["n_mice"]
                sems.append(row.iloc[0]["std_err"] / np.sqrt(n) if n > 1 else 0)
        offset = (i - n_ps / 2 + 0.5) * bar_width
        ax.bar(x_base + offset, means, bar_width * 0.9, yerr=sems, capsize=2,
               label=_ps_label(ps), color=_ps_color(ps), alpha=0.85,
               edgecolor="black", linewidth=0.6)
    ax.set_xticks(x_base)
    ax.set_xticklabels(eval_groups_for_plot)
    ax.set_ylabel("Median decoding error (cm)")
    ax.set_title("Cross-evaluation: param set × evaluation group")
    from matplotlib.patches import Patch as _Patch5a
    handles = [_Patch5a(facecolor=_ps_color(ps), alpha=0.85,
                        edgecolor="black", lw=0.6, label=_ps_label(ps))
               for ps in ps_labels]
    ax.legend(handles=handles, title="Param set")
    ax.grid(True, axis="y", alpha=0.25)
    fig.tight_layout()
    fig.savefig(os.path.join(opt_plots_dir, "cross_eval_grouped_bar.pdf"))
    fig.savefig(os.path.join(opt_plots_dir, "cross_eval_grouped_bar.png"))
    plt.close(fig)

    # --- 5b) Per-mouse heatmap ---
    pivot = df_cross.pivot_table(index="mouse", columns="param_set",
                                 values="median_err", aggfunc="first")
    # Sort rows by group then mouse
    mouse_order = []
    for gl in group_labels:
        mouse_order.extend(sorted(m for m in pivot.index if mouse_groups.get(m, "NA") == gl))
    pivot = pivot.reindex(index=mouse_order, columns=ps_labels)

    _hm_h = max(NATURE_1COL_WIDTH_IN * 0.6, 0.25 * len(mouse_order) + 0.8)
    fig, ax = plt.subplots(figsize=(NATURE_1COL_WIDTH_IN, _hm_h))
    data_mat = pivot.to_numpy(dtype=float)
    im = ax.imshow(data_mat, aspect="auto", cmap="RdYlGn_r")
    ax.set_xticks(range(len(ps_labels)))
    ax.set_xticklabels(ps_labels, rotation=35, ha="right")
    ax.set_yticks(range(len(mouse_order)))
    ylabels = [f"{m} ({mouse_groups.get(m, '?')})" for m in mouse_order]
    ax.set_yticklabels(ylabels)
    # Annotate cells
    _annot_fs = max(4.5, 6 - 0.1 * len(mouse_order))  # shrink if many mice
    for r in range(data_mat.shape[0]):
        for c in range(data_mat.shape[1]):
            v = data_mat[r, c]
            if np.isfinite(v):
                ax.text(c, r, f"{v:.1f}", ha="center", va="center", fontsize=_annot_fs,
                        color="white" if v > np.nanpercentile(data_mat, 70) else "black")
    cb = fig.colorbar(im, ax=ax, pad=0.02, shrink=0.85)
    cb.set_label("Median decoding error (cm)")
    ax.set_title("Per-mouse × param-set decoding error")
    fig.tight_layout()
    fig.savefig(os.path.join(opt_plots_dir, "cross_eval_heatmap.pdf"))
    fig.savefig(os.path.join(opt_plots_dir, "cross_eval_heatmap.png"))
    plt.close(fig)

    # --- 5c) Box plot: per param_set, paper colour scheme ---
    # Uses _OPT_PS_COLORS for box fill, _PAPER_DOT_COLORS for scatter by group.
    fig, ax = plt.subplots(figsize=(NATURE_1COL_WIDTH_IN, NATURE_1COL_WIDTH_IN * 0.85))
    # Dot colours keyed by mouse group (same palette as paper panels)
    _group_dot_map = {
        "mCherry": _PAPER_DOT_COLORS.get("mCherry", "#7a7a7a"),
        "hM3D":    _PAPER_DOT_COLORS.get("hM3D",    "#d98e8e"),
        "hM4D":    _PAPER_DOT_COLORS.get("hM4D",    "#8fb5d5"),
    }

    for i, ps in enumerate(ps_labels):
        sub = df_cross[(df_cross["param_set"] == ps) & df_cross["ok"]]
        all_vals = sub["median_err"].dropna().to_numpy()
        if len(all_vals) > 0:
            bp = ax.boxplot([all_vals], positions=[i], widths=0.5, **_BP_KW_OPT, zorder=2)
            _style_bp_opt(bp, ps)
        for gl in group_labels:
            vals = sub[sub["group"] == gl]["median_err"].dropna().to_numpy()
            jitter = np.random.default_rng(42 + i).uniform(-0.12, 0.12, size=len(vals))
            ax.scatter(np.full_like(vals, i) + jitter, vals,
                       color=_group_dot_map.get(gl, "#888888"), s=30, alpha=0.85,
                       edgecolors="white", linewidths=0.3, zorder=3)
    ax.set_xticks(range(n_ps))
    ax.set_xticklabels([_ps_label(ps) for ps in ps_labels], rotation=25, ha="right")
    ax.set_ylabel("Median decoding error (cm)")
    ax.set_title("Error distributions by param set (dots coloured by group)")
    from matplotlib.patches import Patch as _Patch5c
    from matplotlib.lines import Line2D
    # Two-part legend: param-set boxes + group dots
    box_handles = [_Patch5c(facecolor=_ps_color(ps), alpha=_OPT_PS_ALPHA,
                            edgecolor="black", lw=0.6, label=_ps_label(ps))
                   for ps in ps_labels]
    dot_handles = [Line2D([0], [0], marker='o', color='w',
                          markerfacecolor=_group_dot_map.get(gl, "#888"),
                          markeredgecolor="white", markeredgewidth=0.3,
                          markersize=7, label=gl) for gl in group_labels]
    leg1 = ax.legend(handles=box_handles, title="Param set",
                     loc="upper left", framealpha=0.9,
                     edgecolor="none")
    ax.add_artist(leg1)
    ax.legend(handles=dot_handles, title="Group",
              loc="upper right", framealpha=0.9,
              edgecolor="none")
    # Annotate ALL significant pairwise comparisons with bracket stars
    if _wilcox_all_pairs:
        _sig_bracket_pairs = [(pa, pb, v["sig"]) for (pa, pb), v in _wilcox_all_pairs.items()
                              if v["sig"] != "ns"]
        if _sig_bracket_pairs:
            _ps_idx = {ps: i for i, ps in enumerate(ps_labels)}
            _ylo_5c, _yhi_5c = ax.get_ylim()
            _bracket_h = (_yhi_5c - _ylo_5c) * 0.03   # bracket arm height
            _bracket_gap = (_yhi_5c - _ylo_5c) * 0.04  # gap between stacked brackets
            # Sort by span width so narrow brackets are drawn first (lower)
            _sig_bracket_pairs.sort(key=lambda t: abs(_ps_idx[t[0]] - _ps_idx[t[1]]))
            # Start first bracket above data
            _all_data_max = df_cross[df_cross["ok"]]["median_err"].max()
            _bracket_y = _all_data_max + (_yhi_5c - _ylo_5c) * 0.05
            for _pa, _pb, _sig_str in _sig_bracket_pairs:
                _x1 = _ps_idx[_pa]
                _x2 = _ps_idx[_pb]
                if _x1 > _x2:
                    _x1, _x2 = _x2, _x1
                # Draw bracket: two vertical arms + horizontal bar
                ax.plot([_x1, _x1, _x2, _x2],
                        [_bracket_y, _bracket_y + _bracket_h,
                         _bracket_y + _bracket_h, _bracket_y],
                        color="black", lw=0.8, clip_on=False)
                ax.text((_x1 + _x2) / 2, _bracket_y + _bracket_h,
                        _sig_str, ha="center", va="bottom",
                        fontsize=8, fontweight="bold")
                _bracket_y += _bracket_h + _bracket_gap
            # Expand y-axis to fit brackets
            ax.set_ylim(_ylo_5c, _bracket_y + _bracket_gap)
    ax.grid(True, axis="y", alpha=0.25)
    fig.tight_layout()
    fig.savefig(os.path.join(opt_plots_dir, "cross_eval_box_by_group.pdf"))
    fig.savefig(os.path.join(opt_plots_dir, "cross_eval_box_by_group.png"))
    plt.close(fig)

    # --- 5d) Improvement-over-baseline: param-set coloured, dashed/solid borders ---
    baseline_errs = {}
    for _, row in df_cross[df_cross["param_set"] == "baseline"].iterrows():
        if row["ok"]:
            baseline_errs[row["mouse"]] = row["median_err"]

    non_baseline_ps = [ps for ps in ps_labels if ps != "baseline"]
    if baseline_errs and non_baseline_ps:
        fig, ax = plt.subplots(figsize=(NATURE_1COL_WIDTH_IN, NATURE_1COL_WIDTH_IN * 0.75))
        for i, ps in enumerate(non_baseline_ps):
            means_by_eg = []
            sems_by_eg = []
            for eg in eval_groups_for_plot:
                sub = df_cross[(df_cross["param_set"] == ps) & df_cross["ok"]]
                if eg != "ALL":
                    sub = sub[sub["group"] == eg]
                deltas = []
                for _, row in sub.iterrows():
                    bval = baseline_errs.get(row["mouse"], np.nan)
                    if np.isfinite(bval) and np.isfinite(row["median_err"]):
                        deltas.append(row["median_err"] - bval)
                if deltas:
                    means_by_eg.append(np.mean(deltas))
                    sems_by_eg.append(np.std(deltas, ddof=1) / np.sqrt(len(deltas)) if len(deltas) > 1 else 0)
                else:
                    means_by_eg.append(0)
                    sems_by_eg.append(0)
            offset = (i - len(non_baseline_ps) / 2 + 0.5) * bar_width
            fc = _ps_color(ps)
            for j, (d, sem) in enumerate(zip(means_by_eg, sems_by_eg)):
                ls = "-" if d >= 0 else "--"
                ax.bar(x_base[j] + offset, d, bar_width * 0.9,
                       color=fc, alpha=0.75, edgecolor="black",
                       linewidth=0.8, linestyle=ls)
                ax.errorbar(x_base[j] + offset, d, yerr=sem,
                            fmt="none", ecolor="black", capsize=3, lw=0.8)
        # Annotate "ALL" column with significance stars (paired Wilcoxon vs baseline)
        if _wilcox_vs_bl and "ALL" in eval_groups_for_plot:
            _all_col_idx = eval_groups_for_plot.index("ALL")
            _ylo_5d, _yhi_5d = ax.get_ylim()
            _ystep_5d = (_yhi_5d - _ylo_5d) * 0.02
            for _i5d, _ps5d in enumerate(non_baseline_ps):
                _sig5d = _wilcox_vs_bl.get(_ps5d, {}).get("sig", "ns")
                if _sig5d != "ns":
                    _off5d = (_i5d - len(non_baseline_ps) / 2 + 0.5) * bar_width
                    _x5d = x_base[_all_col_idx] + _off5d
                    # Recompute delta + SEM for star placement
                    _sub5d = df_cross[(df_cross["param_set"] == _ps5d) & df_cross["ok"]]
                    _dlt5d = [row["median_err"] - baseline_errs.get(row["mouse"], np.nan)
                              for _, row in _sub5d.iterrows()
                              if np.isfinite(baseline_errs.get(row["mouse"], np.nan))
                              and np.isfinite(row["median_err"])]
                    _md5d = np.mean(_dlt5d) if _dlt5d else 0
                    _se5d = (np.std(_dlt5d, ddof=1) / np.sqrt(len(_dlt5d))
                             if len(_dlt5d) > 1 else 0)
                    if _md5d < 0:
                        ax.text(_x5d, _md5d - _se5d - _ystep_5d, _sig5d,
                                ha="center", va="top", fontsize=8, fontweight="bold")
                    else:
                        ax.text(_x5d, _md5d + _se5d + _ystep_5d, _sig5d,
                                ha="center", va="bottom", fontsize=8, fontweight="bold")
        ax.axhline(0, color="black", linewidth=0.8)
        ax.set_xticks(x_base)
        ax.set_xticklabels(eval_groups_for_plot)
        ax.set_ylabel("Δ error vs baseline (cm, negative = better)")
        ax.set_title("Improvement over baseline by group")
        from matplotlib.patches import Patch as _Patch5d
        handles = [_Patch5d(facecolor=_ps_color(ps), alpha=0.75,
                            edgecolor="black", lw=0.6, label=_ps_label(ps))
                   for ps in non_baseline_ps]
        ax.legend(handles=handles, title="Param set")
        ax.grid(True, axis="y", alpha=0.25)
        fig.tight_layout()
        fig.savefig(os.path.join(opt_plots_dir, "cross_eval_delta_vs_baseline.pdf"))
        fig.savefig(os.path.join(opt_plots_dir, "cross_eval_delta_vs_baseline.png"))
        plt.close(fig)

    # Restore original rcParams
    _mpl.rcParams.update(_saved_rc)

    # ==================================================================
    # 6) Text summary
    # ==================================================================

    summary_lines = []
    summary_lines.append("=" * 70)
    summary_lines.append("GROUP-AWARE DECODER OPTIMIZATION SUMMARY")
    summary_lines.append("=" * 70)
    summary_lines.append(f"Date: {pd.Timestamp.now().strftime('%Y-%m-%d %H:%M:%S')}")
    summary_lines.append(f"Trials per study: {optimization_trials}")
    if _optimize_z_score:
        summary_lines.append(f"use_z_score: OPTIMIZED (searching none / per-session / across-sessions)")
    else:
        summary_lines.append(f"use_z_score (fixed): {use_z_score}")
    summary_lines.append(f"Groups: {group_labels}")
    summary_lines.append(f"Mice per group: { {gl: len(group_to_mice[gl]) for gl in group_labels} }")
    summary_lines.append("")

    # Param comparison table
    summary_lines.append("-" * 70)
    summary_lines.append("OPTIMIZED PARAMETER SETS")
    summary_lines.append("-" * 70)
    param_keys = list(baseline_params.keys())
    header = f"{'param':<30s}" + "".join(f"{ps:<20s}" for ps in ps_labels)
    summary_lines.append(header)
    for pk in param_keys:
        row_str = f"{pk:<30s}"
        for ps in ps_labels:
            v = param_sets[ps].get(pk, "N/A")
            if isinstance(v, float):
                row_str += f"{v:<20.4f}"
            else:
                row_str += f"{str(v):<20s}"
        summary_lines.append(row_str)
    summary_lines.append("")

    # Cross-eval table
    summary_lines.append("-" * 70)
    summary_lines.append("CROSS-EVALUATION: MEAN MEDIAN ERROR (param_set × eval_group)")
    summary_lines.append("-" * 70)
    header = f"{'param_set':<20s}" + "".join(f"{eg:<15s}" for eg in eval_groups_for_plot)
    summary_lines.append(header)
    for ps in ps_labels:
        row_str = f"{ps:<20s}"
        for eg in eval_groups_for_plot:
            row = df_summary[(df_summary["param_set"] == ps) & (df_summary["eval_group"] == eg)]
            if row.empty or np.isnan(row.iloc[0]["mean_err"]):
                row_str += f"{'N/A':<15s}"
            else:
                me = row.iloc[0]["mean_err"]
                se = row.iloc[0]["std_err"]
                n = row.iloc[0]["n_mice"]
                sem = se / np.sqrt(n) if n > 1 and np.isfinite(se) else 0
                row_str += f"{me:.2f}±{sem:.2f}     "
        summary_lines.append(row_str)
    summary_lines.append("")

    # Best param set per group
    summary_lines.append("-" * 70)
    summary_lines.append("BEST PARAM SET PER EVALUATION GROUP (lowest mean error)")
    summary_lines.append("-" * 70)
    for eg in eval_groups_for_plot:
        sub = df_summary[df_summary["eval_group"] == eg].dropna(subset=["mean_err"])
        if sub.empty:
            summary_lines.append(f"  {eg}: N/A")
        else:
            best_row = sub.loc[sub["mean_err"].idxmin()]
            summary_lines.append(
                f"  {eg}: {best_row['param_set']} "
                f"(mean={best_row['mean_err']:.2f}, n={int(best_row['n_mice'])})"
            )
    summary_lines.append("")

    # Delta vs baseline
    summary_lines.append("-" * 70)
    summary_lines.append("IMPROVEMENT VS BASELINE (negative = better)")
    summary_lines.append("-" * 70)
    hdr = f"  {'param_set':<18s}" + "".join(f"{eg:<15s}" for eg in eval_groups_for_plot)
    summary_lines.append(hdr)
    base_row = df_summary[df_summary["param_set"] == "baseline"]
    for ps in ps_labels:
        if ps == "baseline":
            continue
        row_str = f"  {ps:<18s}"
        for eg in eval_groups_for_plot:
            ps_row = df_summary[(df_summary["param_set"] == ps) & (df_summary["eval_group"] == eg)]
            b_row = base_row[base_row["eval_group"] == eg]
            if ps_row.empty or b_row.empty:
                row_str += f"{'N/A':<15s}"
            else:
                delta = ps_row.iloc[0]["mean_err"] - b_row.iloc[0]["mean_err"]
                row_str += f"{delta:+.2f}          "
        summary_lines.append(row_str)

    summary_lines.append("")
    summary_lines.append("=" * 70)
    summary_text = "\n".join(summary_lines)

    print(summary_text)

    summary_path = os.path.join(opt_dir, "optimization_summary.txt")
    with open(summary_path, "w", encoding="utf-8") as f:
        f.write(summary_text)
    print(f"\n[OPT-GRP] Summary saved: {summary_path}")

    # ==================================================================
    # 7) Statistical comparison of param sets (paired across mice)
    # ==================================================================
    #   Every mouse is evaluated under every param set, so comparisons
    #   are paired (within-subject).  Tests used:
    #     - Friedman test: non-parametric repeated-measures ANOVA
    #     - Pairwise Wilcoxon signed-rank tests with Holm-Bonferroni
    #     - Paired Cohen's d effect sizes
    # ------------------------------------------------------------------

    from scipy import stats as _sp_stats_opt
    from itertools import combinations as _combinations

    stat_lines = []
    stat_lines.append("")
    stat_lines.append("=" * 70)
    stat_lines.append("STATISTICAL COMPARISON OF PARAM SETS (paired across mice)")
    stat_lines.append("=" * 70)

    # Build a mouse × param_set error matrix (only mice that succeeded in ALL sets)
    _ok_cross = df_cross[df_cross["ok"]].copy()
    _mice_per_ps = {ps: set(_ok_cross[_ok_cross["param_set"] == ps]["mouse"])
                    for ps in ps_labels}
    _common_mice = sorted(set.intersection(*_mice_per_ps.values())) if _mice_per_ps else []
    stat_lines.append(f"Mice included (succeeded in all {len(ps_labels)} param sets): "
                      f"{len(_common_mice)}/{len(available_mice)}")
    stat_lines.append(f"  {_common_mice}")
    stat_lines.append("")

    if len(_common_mice) >= 3 and len(ps_labels) >= 2:
        # Build matrix: rows = mice, columns = param sets
        _err_matrix = {}   # ps_label -> np.array of errors in _common_mice order
        for ps in ps_labels:
            sub = _ok_cross[_ok_cross["param_set"] == ps].set_index("mouse")
            _err_matrix[ps] = np.array([sub.loc[m, "median_err"] for m in _common_mice])

        # ---- 7a) Friedman test (all param sets simultaneously) ----
        stat_lines.append("-" * 70)
        stat_lines.append("FRIEDMAN TEST (all param sets)")
        stat_lines.append("-" * 70)
        try:
            _friedman_arrays = [_err_matrix[ps] for ps in ps_labels]
            _fr_stat, _fr_p = _sp_stats_opt.friedmanchisquare(*_friedman_arrays)
            stat_lines.append(f"  χ²({len(ps_labels)-1}) = {_fr_stat:.3f},  p = {_fr_p:.4g}")
            if _fr_p < 0.05:
                stat_lines.append("  → Significant: param sets produce different errors (p < 0.05)")
            else:
                stat_lines.append("  → Not significant at α = 0.05")
        except Exception as _exc:
            stat_lines.append(f"  Friedman test failed: {_exc}")
        stat_lines.append("")

        # ---- 7b) Pairwise Wilcoxon signed-rank tests ----
        stat_lines.append("-" * 70)
        stat_lines.append("PAIRWISE WILCOXON SIGNED-RANK TESTS")
        stat_lines.append("-" * 70)

        _wilcox_rows = []
        for ps_a, ps_b in _combinations(ps_labels, 2):
            a_vals = _err_matrix[ps_a]
            b_vals = _err_matrix[ps_b]
            diff = a_vals - b_vals
            if np.all(diff == 0):
                _wilcox_rows.append({
                    "param_set_A": ps_a, "param_set_B": ps_b,
                    "mean_diff": 0.0, "W_stat": np.nan, "p_raw": 1.0,
                    "cohens_d": 0.0, "direction": "equal",
                })
                continue
            try:
                _w_stat, _w_p = _sp_stats_opt.wilcoxon(a_vals, b_vals, alternative="two-sided")
            except Exception:
                _w_stat, _w_p = np.nan, np.nan
            # Paired Cohen's d = mean(diff) / std(diff)
            _d_mean = np.mean(diff)
            _d_std = np.std(diff, ddof=1)
            _cohens_d = _d_mean / _d_std if _d_std > 0 else 0.0
            direction = f"{ps_a} better" if _d_mean < 0 else f"{ps_b} better"
            _wilcox_rows.append({
                "param_set_A": ps_a, "param_set_B": ps_b,
                "mean_diff": float(_d_mean), "W_stat": float(_w_stat),
                "p_raw": float(_w_p), "cohens_d": float(_cohens_d),
                "direction": direction,
            })

        df_wilcox = pd.DataFrame(_wilcox_rows)

        # Holm-Bonferroni correction
        if len(df_wilcox) > 0:
            _raw_ps = df_wilcox["p_raw"].to_numpy(dtype=float)
            _sorted_idx = np.argsort(_raw_ps)
            _m = len(_raw_ps)
            _corrected = np.ones(_m)
            for rank, idx in enumerate(_sorted_idx):
                _corrected[idx] = min(1.0, _raw_ps[idx] * (_m - rank))
            # Enforce monotonicity
            _prev = 0.0
            for idx in _sorted_idx:
                _corrected[idx] = max(_corrected[idx], _prev)
                _prev = _corrected[idx]
            df_wilcox["p_holm"] = _corrected
            df_wilcox["sig"] = df_wilcox["p_holm"].apply(
                lambda p: "***" if p < 0.001 else ("**" if p < 0.01 else ("*" if p < 0.05 else "ns"))
            )

        # Print table
        stat_lines.append(
            f"  {'A':<12s} {'B':<12s} {'mean(A-B)':>10s} {'W':>8s} "
            f"{'p_raw':>10s} {'p_holm':>10s} {'d':>8s} {'sig':>5s}  {'direction'}")
        for _, r in df_wilcox.iterrows():
            stat_lines.append(
                f"  {r['param_set_A']:<12s} {r['param_set_B']:<12s} "
                f"{r['mean_diff']:>10.3f} {r['W_stat']:>8.0f} "
                f"{r['p_raw']:>10.4g} {r['p_holm']:>10.4g} "
                f"{r['cohens_d']:>8.3f} {r['sig']:>5s}  {r['direction']}")
        stat_lines.append("")

        # Save CSV
        wilcox_csv = os.path.join(opt_tables_dir, "pairwise_wilcoxon.csv")
        df_wilcox.to_csv(wilcox_csv, index=False)
        stat_lines.append(f"  Saved: {wilcox_csv}")

        # ---- 7c) Rank summary: average rank of each param set (Friedman-style) ----
        stat_lines.append("")
        stat_lines.append("-" * 70)
        stat_lines.append("AVERAGE RANK PER PARAM SET (1 = best per mouse, lower = better)")
        stat_lines.append("-" * 70)
        _rank_matrix = np.column_stack([_err_matrix[ps] for ps in ps_labels])
        _ranks = _sp_stats_opt.rankdata(_rank_matrix, axis=1)
        _mean_ranks = _ranks.mean(axis=0)
        for i, ps in enumerate(ps_labels):
            stat_lines.append(f"  {ps:<18s}  mean_rank = {_mean_ranks[i]:.2f}")
        _best_rank_ps = ps_labels[int(np.argmin(_mean_ranks))]
        stat_lines.append(f"  → Best average rank: {_best_rank_ps}")
        stat_lines.append("")

        # ---- 7d) Win-count matrix: how often does each param set beat each other? ----
        stat_lines.append("-" * 70)
        stat_lines.append(f"WIN-COUNT MATRIX (out of {len(_common_mice)} mice)")
        stat_lines.append("-" * 70)
        header_wc = f"  {'wins↓ vs→':<14s}" + "".join(f"{ps:<12s}" for ps in ps_labels)
        stat_lines.append(header_wc)
        for i, ps_a in enumerate(ps_labels):
            row_str = f"  {ps_a:<14s}"
            for j, ps_b in enumerate(ps_labels):
                if i == j:
                    row_str += f"{'---':<12s}"
                else:
                    n_wins = int(np.sum(_err_matrix[ps_a] < _err_matrix[ps_b]))
                    row_str += f"{n_wins:<12d}"
            stat_lines.append(row_str)
        stat_lines.append("")

    else:
        stat_lines.append("  Insufficient data for statistical tests (need ≥3 common mice and ≥2 param sets).")
        stat_lines.append("")
        df_wilcox = pd.DataFrame()

    stat_lines.append("=" * 70)
    stat_text = "\n".join(stat_lines)
    print(stat_text)

    # Append statistics to the summary file
    with open(summary_path, "a", encoding="utf-8") as f:
        f.write("\n" + stat_text)
    print(f"[OPT-GRP] Statistics appended to: {summary_path}")

    # Save all param sets as a single JSON for the cache
    all_params_json = os.path.join(opt_tables_dir, "all_param_sets.json")
    with open(all_params_json, "w", encoding="utf-8") as f:
        _json.dump(param_sets, f, indent=2)
    print(f"[OPT-GRP] All param sets saved: {all_params_json}")

    return {
        "ok": True,
        "param_sets": param_sets,
        "cross_eval": df_cross,
        "summary": df_summary,
        "opt_dir": opt_dir,
        "stats_wilcoxon": df_wilcox,
    }


# ---------------------------------------------------------------------------
#  PF-based 2D decoder: grouped parameter optimization
# ---------------------------------------------------------------------------

def optimize_2d_pf_decoder_parameters_grouped(
    TFC_cond_group: dict,
    *,
    mouse_groups: dict,
    PLOTS_DIR: str,
    encoder_period: str = "pre-tone",
    paramset: "BayesianDecoderParamset" = None,
    optimization_trials: int = 50,
    optimization_seed: int = 42,
    optimization_first_n_sec: float = 180.0,
    optimization_target: str = "within_TFC",
    optimization_use_speed: bool = True,
    optimization_min_speed: float = 2.0,
    optimization_n_startup_trials: int = 12,
    skip_optimization: bool = False,
    jitter_lambda: float = 0.5,
) -> Dict[str, Any]:
    """Run per-group + pooled Optuna optimizations for the PF-based 2D decoder.

    Parameters
    ----------
    paramset : BayesianDecoderParamset
        Baseline PF-decoder parameters.

    Mirrors ``optimize_2d_decoder_parameters_grouped`` but uses
    ``BayesianDecoder2D_PF`` (place-field rate-map tuning curves) with
    continuity constraints for the within-session CV objective.

    Outputs go to ``<PLOTS_DIR>/2D_pf_decoder_optimization/``.

    Returns a dict with keys:
      - "param_sets": {set_label: param_dict}
      - "cross_eval": pd.DataFrame
      - "opt_dir": str
      - "ok": bool
    """
    if paramset is None:
        paramset = BayesianDecoderParamset()

    # ---- extract to locals (rest of function body is unchanged) ----
    time_bin_frames         = paramset.time_bin_frames
    use_posterior_mean      = paramset.use_posterior_mean
    use_z_score             = paramset.use_z_score
    use_continuity_constraint = paramset.use_continuity_constraint
    continuity_sigma_k      = paramset.continuity_sigma_k
    continuity_speed_ref    = paramset.continuity_speed_ref
    continuity_exp          = paramset.continuity_exp
    continuity_sigma_min    = paramset.continuity_sigma_min
    continuity_sigma_max    = paramset.continuity_sigma_max
    continuity_sigma_default = paramset.continuity_sigma_default
    place_cells_only        = paramset.place_cells_only
    use_pf_num              = paramset.use_pf_num
    use_occupancy_fallback  = paramset.use_occupancy_fallback

    _baseline_z = "per-session" if str(use_z_score).strip().lower() == "optimize" else str(use_z_score)

    baseline_params = {
        "time_bin_frames": int(time_bin_frames),
        "use_posterior_mean": bool(use_posterior_mean),
        "use_z_score": _baseline_z,
        "use_continuity_constraint": bool(use_continuity_constraint),
        "continuity_sigma_k": float(continuity_sigma_k),
        "continuity_speed_ref": float(continuity_speed_ref),
        "continuity_exp": float(continuity_exp),
        "continuity_sigma_min": float(continuity_sigma_min),
        "continuity_sigma_max": float(continuity_sigma_max),
        "continuity_sigma_default": float(continuity_sigma_default),
        "place_cells_only": bool(place_cells_only),
        "use_pf_num": int(use_pf_num),
        "use_occupancy_fallback": bool(use_occupancy_fallback),
    }

    os.makedirs(PLOTS_DIR, exist_ok=True)
    opt_dir = os.path.join(PLOTS_DIR, "2D_pf_decoder_optimization")
    os.makedirs(opt_dir, exist_ok=True)
    opt_tables_dir = os.path.join(opt_dir, "tables")
    opt_plots_dir = os.path.join(opt_dir, "summary")
    os.makedirs(opt_tables_dir, exist_ok=True)
    os.makedirs(opt_plots_dir, exist_ok=True)

    # ----- helper: normalise params -----

    def _normalize(params):
        return {
            "time_bin_frames": int(params["time_bin_frames"]),
            "use_posterior_mean": bool(params["use_posterior_mean"]),
            "use_z_score": str(params["use_z_score"]),
            "use_continuity_constraint": bool(params.get("use_continuity_constraint", True)),
            "continuity_sigma_k": float(params["continuity_sigma_k"]),
            "continuity_speed_ref": float(params["continuity_speed_ref"]),
            "continuity_exp": float(params["continuity_exp"]),
            "continuity_sigma_min": float(params["continuity_sigma_min"]),
            "continuity_sigma_max": float(params["continuity_sigma_max"]),
            "continuity_sigma_default": float(params["continuity_sigma_default"]),
            "place_cells_only": bool(params.get("place_cells_only", True)),
            "use_pf_num": int(params.get("use_pf_num", -1)),
            "use_occupancy_fallback": bool(params.get("use_occupancy_fallback", False)),
        }

    # ----- helper: within-session PF CV for one mouse -----

    def _run_cv(mouse, params, first_n_sec_override=None):
        params = _normalize(params)
        sess = TFC_cond_group[mouse]

        # Validate FM availability
        if not hasattr(sess, 'fm') or sess.fm is None:
            return {"ok": False, "reason": "No FluorescenceMap (.fm) attached."}
        fm = sess.fm
        if fm.fluorescence_map_occup is None:
            return {"ok": False, "reason": "fm.fluorescence_map_occup is None."}
        if not hasattr(fm, 'pf') or fm.pf is None:
            return {"ok": False, "reason": "fm has no PlaceFields (.pf)."}
        if not hasattr(sess, 'loc') or sess.loc is None:
            return {"ok": False, "reason": "No Location_XY (.loc) attached."}

        dt_sec = _infer_dt_sec(sess)
        dist_meta = _get_2d_decoder_distance_meta(sess)
        pos_scale = float(dist_meta["scale"])
        unit_label = dist_meta["unit"]

        # Z-score the activity matrix
        S = _apply_zscore_single(sess.S, str(params["use_z_score"]))

        # Positions (scaled)
        x = _scale_2d_position_array(sess.loc_X_miniscope_smooth, pos_scale)[:S.shape[1]]
        y = _scale_2d_position_array(sess.loc_Y_miniscope_smooth, pos_scale)[:S.shape[1]]

        # Pre-tone mask
        _fns = optimization_first_n_sec if first_n_sec_override is None else float(first_n_sec_override)
        mask = build_pretone_mask_TFC(
            sess,
            first_n_sec=_fns,
            use_speed=optimization_use_speed,
            min_speed=optimization_min_speed,
            encoder_period=encoder_period,
        )[:S.shape[1]]

        speed_vec = _get_miniscope_velocity_vector(sess, T=S.shape[1])

        # --- Identify PF-eligible cells ---
        fm_cells_list = list(fm.cells) if fm.cells is not None else []
        all_S_indices = list(range(S.shape[0]))  # all neurons in (possibly z-scored) S
        # We need to map session S indices → fm cell indices
        # sess.S rows correspond to sess.cells; fm.cells are indices into sess.S
        keep_mask = []
        fm_cell_indices = []
        _pcells_only = bool(params["place_cells_only"])
        _pf_num = int(params["use_pf_num"])
        _occ_fb = bool(params["use_occupancy_fallback"])

        for s_row_idx in range(S.shape[0]):
            # s_row_idx is a direct row index into S.  For the full session
            # S matrix (not remapped), s_row_idx == cell index in fm convention.
            s_idx = s_row_idx  # direct index
            if s_idx not in fm_cells_list:
                continue
            fm_idx = fm_cells_list.index(s_idx)

            if _pcells_only:
                if not (fm.sig_responses is not None and s_idx in fm.sig_responses):
                    continue
            if _pf_num >= 1:
                if s_idx not in fm.pf.model_:
                    continue
                n_merged_pf = len(fm.pf.merged_means.get(s_idx, []))
                if n_merged_pf == 0 or n_merged_pf > _pf_num:
                    continue
            elif not _occ_fb:
                if s_idx not in fm.pf.model_:
                    continue

            keep_mask.append(s_row_idx)
            fm_cell_indices.append(fm_idx)

        if not keep_mask:
            return {"ok": False, "reason": "No PF-eligible cells found."}

        S_kept = S[keep_mask]

        # --- Build PF decoder ---
        rate_map = fm.fluorescence_map_occup
        occupancy = sess.loc.occupancy
        bin_width = float(sess.loc.bin_width) * pos_scale

        dec = BayesianDecoder2D_PF(time_bin_frames=int(params["time_bin_frames"]))
        dec.fit_from_place_fields(
            fm.pf, rate_map, occupancy,
            fm_cells=fm_cells_list,
            cell_indices=fm_cell_indices,
            dt_sec=dt_sec,
            bin_width=bin_width,
            use_occupancy_fallback=_occ_fb,
        )

        # --- Even/odd CV split (same as _within_session_2D_PF_cv) ---
        T = S_kept.shape[1]
        block_size = max(1, int(10.0 / dt_sec))
        idx_all = np.where(mask[:T])[0]
        tbf = int(params["time_bin_frames"])
        if idx_all.size < 2 * tbf:
            return {"ok": False, "reason": "Too few masked frames for CV."}

        block_id = idx_all // block_size
        even_mask = np.zeros(T, dtype=bool)
        odd_mask = np.zeros(T, dtype=bool)
        even_mask[idx_all[block_id % 2 == 0]] = True
        odd_mask[idx_all[block_id % 2 == 1]] = True

        _use_cc = bool(params["use_continuity_constraint"])
        _cc_kwargs = dict(
            use_continuity_constraint=_use_cc,
            continuity_sigma_k=float(params["continuity_sigma_k"]),
            continuity_speed_ref=float(params["continuity_speed_ref"]),
            continuity_exp=float(params["continuity_exp"]),
            continuity_sigma_min=float(params["continuity_sigma_min"]),
            continuity_sigma_max=float(params["continuity_sigma_max"]),
            continuity_sigma_default=float(params["continuity_sigma_default"]),
            speed_vec=speed_vec,
        )

        err_parts = []
        jitter_parts = []
        for test_m in [even_mask, odd_mask]:
            out = dec.decode(
                S_kept, x, y, test_m,
                use_posterior_mean=bool(params["use_posterior_mean"]),
                **_cc_kwargs,
            )
            if out["euclidean_err"].size > 0:
                err_parts.append(out["euclidean_err"])
                _jit = _compute_median_jitter(
                    out.get("decoded_x", np.array([])),
                    out.get("decoded_y", np.array([])),
                )
                if np.isfinite(_jit):
                    jitter_parts.append(_jit)

        if err_parts:
            pooled = np.concatenate(err_parts)
            return {
                "ok": True,
                "median_err": float(np.nanmedian(pooled)),
                "mean_err": float(np.nanmean(pooled)),
                "median_jitter": float(np.median(jitter_parts)) if jitter_parts else np.nan,
                "n_cells": len(keep_mask),
            }
        return {"ok": False, "reason": "CV produced no decoded frames."}

    # ----- helper: evaluate on a list of mice -----

    def _eval_on_mice(params, mice_list):
        rows = []
        for mouse in mice_list:
            try:
                res = _run_cv(mouse, params, first_n_sec_override=optimization_first_n_sec)
            except Exception as exc:
                rows.append({"mouse": mouse, "ok": False, "median_err": np.nan, "median_jitter": np.nan, "reason": str(exc)})
                continue
            if not res.get("ok", False):
                rows.append({"mouse": mouse, "ok": False, "median_err": np.nan, "median_jitter": np.nan,
                             "reason": res.get("reason", "decode failed")})
                continue
            rows.append({"mouse": mouse, "ok": True,
                         "median_err": float(res.get("median_err", np.nan)),
                         "median_jitter": float(res.get("median_jitter", np.nan)),
                         "reason": ""})
        df = pd.DataFrame(rows)
        valid = df[df["ok"] & np.isfinite(df["median_err"])]
        score = float(np.nanmedian(valid["median_err"].to_numpy())) if not valid.empty else np.inf
        jitter_score = float(np.nanmedian(valid["median_jitter"].to_numpy())) if (not valid.empty and "median_jitter" in valid.columns) else 0.0
        return score, jitter_score, int(valid.shape[0]), df

    # ----- Optuna study runner -----

    def _run_optuna_study(study_label, mice_list, seed_offset=0):
        try:
            import importlib
            optuna = importlib.import_module("optuna")
        except Exception:
            optuna = None

        trial_records = []

        if optuna is not None:
            sampler = optuna.samplers.TPESampler(
                seed=optimization_seed + seed_offset,
                n_startup_trials=optimization_n_startup_trials,
            )
            study = optuna.create_study(direction="minimize", sampler=sampler)

            def _objective(trial):
                p_time = int(trial.suggest_int("time_bin_frames", 8, 24, step=1))
                p_post = bool(trial.suggest_categorical("use_posterior_mean", [True, False]))
                if _optimize_z_score:
                    p_z = str(trial.suggest_categorical("use_z_score",
                              ["none", "per-session", "across-sessions"]))
                else:
                    p_z = str(use_z_score)
                p_k = float(trial.suggest_float("continuity_sigma_k", 15.0, 50.0))
                p_vref = float(trial.suggest_float("continuity_speed_ref", 10.0, 30.0))
                p_exp = float(trial.suggest_float("continuity_exp", 0.8, 1.2))
                p_min = float(trial.suggest_float("continuity_sigma_min", 5.0, 20.0))
                p_max = float(trial.suggest_float("continuity_sigma_max", p_min + 5.0, 40.0))
                p_def = float(trial.suggest_float("continuity_sigma_default", p_min, p_max))
                # PF-specific: place_cells_only, use_occupancy_fallback,
                # and use_pf_num are fixed constraints — not tunable.

                params = {
                    "time_bin_frames": p_time,
                    "use_posterior_mean": p_post,
                    "use_z_score": p_z,
                    "use_continuity_constraint": True,
                    "continuity_sigma_k": p_k,
                    "continuity_speed_ref": p_vref,
                    "continuity_exp": p_exp,
                    "continuity_sigma_min": p_min,
                    "continuity_sigma_max": p_max,
                    "continuity_sigma_default": p_def,
                    "place_cells_only": True,
                    "use_pf_num": int(use_pf_num),
                    "use_occupancy_fallback": False,
                }
                score, jitter, n_ok, _ = _eval_on_mice(params, mice_list)
                penalty = 5000.0 * max(0, len(mice_list) - n_ok)
                jitter_penalty = jitter_lambda * jitter if np.isfinite(jitter) else 0.0
                score_final = float(score + jitter_penalty + penalty)
                trial_records.append({
                    "trial": int(trial.number),
                    "score": score_final,
                    "score_raw": float(score),
                    "jitter": float(jitter) if np.isfinite(jitter) else 0.0,
                    "n_ok_mice": int(n_ok),
                    **params,
                })
                return score_final

            study.optimize(_objective, n_trials=optimization_trials, show_progress_bar=False)
            best_p = dict(study.best_params)
            best_p["use_continuity_constraint"] = True
            if not _optimize_z_score:
                best_p["use_z_score"] = str(use_z_score)
        else:
            # Random search fallback
            rng = np.random.default_rng(optimization_seed + seed_offset)
            best_score = np.inf
            best_p = None
            for i in range(int(optimization_trials)):
                p_min = float(rng.uniform(5.0, 30.0))
                p_max = float(rng.uniform(p_min + 5.0, 90.0))
                _rng_z = (str(rng.choice(["none", "per-session", "across-sessions"]))
                          if _optimize_z_score else str(use_z_score))
                params = {
                    "time_bin_frames": int(rng.integers(8, 25)),
                    "use_posterior_mean": bool(rng.choice([True, False])),
                    "use_z_score": _rng_z,
                    "use_continuity_constraint": True,
                    "continuity_sigma_k": float(rng.uniform(20.0, 90.0)),
                    "continuity_speed_ref": float(rng.uniform(8.0, 40.0)),
                    "continuity_exp": float(rng.uniform(0.6, 1.6)),
                    "continuity_sigma_min": p_min,
                    "continuity_sigma_max": p_max,
                    "continuity_sigma_default": float(rng.uniform(p_min, p_max)),
                    "place_cells_only": True,
                    "use_pf_num": int(use_pf_num),
                    "use_occupancy_fallback": False,
                }
                score, jitter, n_ok, _ = _eval_on_mice(params, mice_list)
                jitter_penalty = jitter_lambda * jitter if np.isfinite(jitter) else 0.0
                score_final = float(score + jitter_penalty + 5000.0 * max(0, len(mice_list) - n_ok))
                trial_records.append({
                    "trial": int(i), "score": score_final, "score_raw": float(score),
                    "jitter": float(jitter) if np.isfinite(jitter) else 0.0,
                    "n_ok_mice": int(n_ok), **params,
                })
                if score_final < best_score:
                    best_score = score_final
                    best_p = dict(params)

        df_trials = pd.DataFrame(trial_records)
        if best_p is not None:
            best_p = _normalize(best_p)
        return best_p, df_trials

    # ==================================================================
    # 1) Build per-group mouse lists (only mice that have .fm attached)
    # ==================================================================

    available_mice = sorted(m for m in TFC_cond_group
                            if hasattr(TFC_cond_group[m], 'fm')
                            and TFC_cond_group[m].fm is not None
                            and hasattr(TFC_cond_group[m].fm, 'pf')
                            and TFC_cond_group[m].fm.pf is not None)
    group_labels = sorted(set(mouse_groups.get(m, "NA") for m in available_mice))
    group_to_mice = {}
    for gl in group_labels:
        group_to_mice[gl] = sorted(m for m in available_mice if mouse_groups.get(m, "NA") == gl)

    print("\n" + "=" * 70)
    print("2D PF-based decoder GROUPED parameter optimization")
    print("=" * 70)
    for gl in group_labels:
        print(f"  {gl}: {group_to_mice[gl]}")
    _optimize_z_score = str(use_z_score).strip().lower() == "optimize"
    print(f"  ALL: {available_mice}")
    print(f"  Trials per study: {optimization_trials}")
    if _optimize_z_score:
        print(f"  use_z_score: OPTIMIZED (searching none / per-session / across-sessions)")
    else:
        print(f"  use_z_score (fixed): {use_z_score}")
    print("=" * 70)

    # Hard stop when no mice have place-field data
    if not available_mice:
        all_mice = sorted(TFC_cond_group.keys())
        _missing_fm = [m for m in all_mice
                       if not hasattr(TFC_cond_group[m], 'fm') or TFC_cond_group[m].fm is None]
        _missing_pf = [m for m in all_mice if m not in _missing_fm
                       and (not hasattr(TFC_cond_group[m].fm, 'pf') or TFC_cond_group[m].fm.pf is None)]
        print("\n" + "!" * 70)
        print("  ERROR: PF decoder optimization impossible — no mice have .fm.pf attached.")
        if _missing_fm:
            print(f"  Mice missing .fm entirely ({len(_missing_fm)}): {_missing_fm}")
        if _missing_pf:
            print(f"  Mice with .fm but missing .fm.pf ({len(_missing_pf)}): {_missing_pf}")
        print("  Ensure place-field fitting (attach_merged_pf_attributes / fit PFs)")
        print("  runs BEFORE the PF decoder optimization block.")
        print("!" * 70 + "\n")
        raise RuntimeError(
            "optimize_2d_pf_decoder_parameters_grouped: no mice have .fm.pf attached. "
            "Place-field fitting must run before the PF decoder optimizer."
        )

    import json as _json

    # ==================================================================
    # CACHE SHORTCUT
    # ==================================================================
    if skip_optimization:
        _cached_params_json = os.path.join(opt_tables_dir, "all_param_sets.json")
        _cached_cross_csv = os.path.join(opt_tables_dir, "cross_evaluation.csv")
        if os.path.isfile(_cached_params_json) and os.path.isfile(_cached_cross_csv):
            print(f"[OPT-PF] skip_optimization=True: loading cached results")
            with open(_cached_params_json, "r", encoding="utf-8") as _f:
                param_sets = _json.load(_f)
            if "baseline" not in param_sets:
                param_sets["baseline"] = _normalize(baseline_params)
            df_cross = pd.read_csv(_cached_cross_csv)
            print(f"[OPT-PF]   param_sets loaded: {list(param_sets.keys())}")
            print(f"[OPT-PF]   cross_eval rows: {len(df_cross)}")
        else:
            missing = []
            if not os.path.isfile(_cached_params_json):
                missing.append(_cached_params_json)
            if not os.path.isfile(_cached_cross_csv):
                missing.append(_cached_cross_csv)
            print(f"[OPT-PF][WARN] skip_optimization=True but cache files missing: {missing}")
            print(f"[OPT-PF][WARN] Falling through to full optimization.")
            skip_optimization = False

    if not skip_optimization:
        # ==================================================================
        # 2) Run optimizations: one per group + pooled
        # ==================================================================

        param_sets = {"baseline": _normalize(baseline_params)}
        all_trials = {}

        study_specs = [(gl, group_to_mice[gl]) for gl in group_labels]
        study_specs.append(("pooled", available_mice))

        for idx, (study_label, mice_list) in enumerate(study_specs):
            if len(mice_list) == 0:
                print(f"[OPT-PF] Skipping '{study_label}': no mice available.")
                continue
            print(f"\n[OPT-PF] Running study '{study_label}' on {len(mice_list)} mice: {mice_list}")
            best_p, df_tr = _run_optuna_study(study_label, mice_list, seed_offset=idx * 1000)

            if best_p is not None:
                param_sets[study_label] = best_p
                print(f"[OPT-PF] '{study_label}' best score on own mice: "
                      f"{_eval_on_mice(best_p, mice_list)[0]:.3f}")
            else:
                print(f"[OPT-PF] '{study_label}': optimization produced no valid params; skipping.")

            if not df_tr.empty:
                all_trials[study_label] = df_tr
                csv_path = os.path.join(opt_tables_dir, f"trials_{study_label}.csv")
                df_tr.sort_values("score").to_csv(csv_path, index=False)
                print(f"[OPT-PF] Saved: {csv_path}")

        for ps_label, ps_params in param_sets.items():
            ps_csv = os.path.join(opt_tables_dir, f"params_{ps_label}.csv")
            pd.Series(ps_params, name="value").to_csv(ps_csv, header=True)

        # ==================================================================
        # 3) Cross-evaluation: every param_set × every mouse
        # ==================================================================

        print(f"\n[OPT-PF] Cross-evaluation: {len(param_sets)} param sets × {len(available_mice)} mice")
        cross_rows = []
        for ps_label, ps_params in param_sets.items():
            for mouse in available_mice:
                grp = mouse_groups.get(mouse, "NA")
                try:
                    res = _run_cv(mouse, ps_params,
                                  first_n_sec_override=optimization_first_n_sec)
                    ok = res.get("ok", False)
                    med_err = float(res.get("median_err", np.nan)) if ok else np.nan
                except Exception as exc:
                    ok = False
                    med_err = np.nan
                cross_rows.append({
                    "param_set": ps_label,
                    "mouse": mouse,
                    "group": grp,
                    "median_err": med_err,
                    "ok": ok,
                })
        df_cross = pd.DataFrame(cross_rows)
        cross_csv = os.path.join(opt_tables_dir, "cross_evaluation.csv")
        df_cross.to_csv(cross_csv, index=False)
        print(f"[OPT-PF] Saved: {cross_csv}")

    # ==================================================================
    # 4) Summary statistics table
    # ==================================================================

    summary_rows = []
    ps_labels = list(param_sets.keys())
    for ps_label in ps_labels:
        sub = df_cross[(df_cross["param_set"] == ps_label) & df_cross["ok"]]
        for grp in group_labels + ["ALL"]:
            if grp == "ALL":
                vals = sub["median_err"].to_numpy(dtype=float)
            else:
                vals = sub[sub["group"] == grp]["median_err"].to_numpy(dtype=float)
            vals = vals[np.isfinite(vals)]
            summary_rows.append({
                "param_set": ps_label,
                "eval_group": grp,
                "n_mice": len(vals),
                "mean_err": float(np.mean(vals)) if len(vals) > 0 else np.nan,
                "median_err": float(np.median(vals)) if len(vals) > 0 else np.nan,
                "std_err": float(np.std(vals, ddof=1)) if len(vals) > 1 else np.nan,
                "min_err": float(np.min(vals)) if len(vals) > 0 else np.nan,
                "max_err": float(np.max(vals)) if len(vals) > 0 else np.nan,
            })
    df_summary = pd.DataFrame(summary_rows)
    summary_csv = os.path.join(opt_tables_dir, "cross_eval_summary.csv")
    df_summary.to_csv(summary_csv, index=False)
    print(f"[OPT-PF] Saved: {summary_csv}")

    # ==================================================================
    # 5) Plots  (identical layout to non-PF optimizer)
    # ==================================================================

    import matplotlib as _mpl
    _saved_rc = {k: _mpl.rcParams[k] for k in PLOT_RC}
    _mpl.rcParams.update(PLOT_RC)

    def _ps_color(ps):
        return _OPT_PS_COLORS.get(ps, "#cccccc")

    def _ps_dot_color(ps):
        return _OPT_PS_DOT_COLORS.get(ps, "#aaaaaa")

    def _ps_label(ps):
        return _OPT_PS_LABELS.get(ps, ps)

    _BP_KW_OPT = dict(
        patch_artist=True, notch=False,
        showfliers=True, flierprops=dict(marker="o", markersize=3, alpha=0.4),
        boxprops=dict(linewidth=0.7), whiskerprops=dict(linewidth=0.7),
        capprops=dict(linewidth=0.7), medianprops=dict(linewidth=1.2, color="black"),
    )

    def _style_bp_opt(bp, ps, *, linestyle="-"):
        fc = _ps_color(ps)
        for box in bp["boxes"]:
            box.set_facecolor(fc)
            box.set_alpha(_OPT_PS_ALPHA)
            box.set_linestyle(linestyle)

    # Pre-compute pairwise Wilcoxon for annotation
    eval_groups_for_plot = group_labels + ["ALL"]
    n_ps = len(ps_labels)
    n_eg = len(eval_groups_for_plot)
    bar_width = 0.8 / max(n_ps, 1)

    _wilcox_all_pairs = {}
    _wilcox_vs_bl = {}
    _ok_cross_5 = df_cross[df_cross["ok"]].copy()
    _mice_per_ps_5 = {ps: set(_ok_cross_5[_ok_cross_5["param_set"] == ps]["mouse"])
                      for ps in ps_labels}
    _common_mice_5 = sorted(set.intersection(*_mice_per_ps_5.values())) if _mice_per_ps_5 else []

    if len(_common_mice_5) >= 3 and len(ps_labels) >= 2:
        from scipy import stats as _sp5
        from itertools import combinations as _comb5
        _err_mat_5 = {}
        for ps in ps_labels:
            sub = _ok_cross_5[_ok_cross_5["param_set"] == ps].set_index("mouse")
            _err_mat_5[ps] = np.array([sub.loc[m, "median_err"] for m in _common_mice_5])
        _raw_pairs = []
        for ps_a, ps_b in _comb5(ps_labels, 2):
            a_vals = _err_mat_5[ps_a]; b_vals = _err_mat_5[ps_b]
            diff = a_vals - b_vals
            if np.all(diff == 0):
                _wilcox_all_pairs[(ps_a, ps_b)] = {
                    "W": np.nan, "p_raw": 1.0, "mean_diff": 0.0, "direction": "equal"}
                _raw_pairs.append(((ps_a, ps_b), 1.0))
                continue
            try:
                _wst, _wp = _sp5.wilcoxon(a_vals, b_vals, alternative="two-sided")
            except Exception:
                _wst, _wp = np.nan, np.nan
            _d_mean = float(np.mean(diff))
            direction = f"{ps_a} better" if _d_mean < 0 else f"{ps_b} better"
            _wilcox_all_pairs[(ps_a, ps_b)] = {
                "W": float(_wst), "p_raw": float(_wp), "mean_diff": _d_mean,
                "direction": direction}
            _raw_pairs.append(((ps_a, ps_b), float(_wp)))

        _sorted_pairs = sorted(_raw_pairs, key=lambda x: x[1])
        _m_corr_all = len(_sorted_pairs)
        _prev_p_all = 0.0
        for _rnk, (pair_key, _prw) in enumerate(_sorted_pairs):
            _pcw = min(1.0, _prw * (_m_corr_all - _rnk))
            _pcw = max(_pcw, _prev_p_all)
            _wilcox_all_pairs[pair_key]["p_holm"] = _pcw
            _prev_p_all = _pcw
        for pair_key in _wilcox_all_pairs:
            _phw = _wilcox_all_pairs[pair_key].get("p_holm", 1.0)
            if _phw < 0.001:
                _sig_label = "***"
            elif _phw < 0.01:
                _sig_label = "**"
            elif _phw < 0.05:
                _sig_label = "*"
            elif _phw < 0.08:
                _sig_label = f"p={_phw:.3f}"
            else:
                _sig_label = "ns"
            _wilcox_all_pairs[pair_key]["sig"] = _sig_label

        for _wps in [ps for ps in ps_labels if ps != "baseline"]:
            key = ("baseline", _wps)
            if key in _wilcox_all_pairs:
                _wilcox_vs_bl[_wps] = _wilcox_all_pairs[key]
            else:
                rev_key = (_wps, "baseline")
                if rev_key in _wilcox_all_pairs:
                    _wilcox_vs_bl[_wps] = _wilcox_all_pairs[rev_key]

        _sig_pairs = [(k, v) for k, v in _wilcox_all_pairs.items() if v["sig"] != "ns"]
        if _sig_pairs:
            print(f"[OPT-PF] Significant pairwise Wilcoxon (Holm-corrected, {_m_corr_all} comparisons):")
            for (pa, pb), v in _sig_pairs:
                print(f"  {pa} vs {pb}: {v['sig']} (p_holm={v['p_holm']:.4g}, {v['direction']})")
        else:
            print(f"[OPT-PF] No significant pairwise comparisons after Holm correction ({_m_corr_all} tests)")

    # --- 5a) Grouped bar chart ---
    fig, ax = plt.subplots(figsize=(NATURE_1COL_WIDTH_IN, NATURE_1COL_WIDTH_IN * 0.75))
    x_base = np.arange(n_eg)
    for i, ps in enumerate(ps_labels):
        means = []; sems = []
        for eg in eval_groups_for_plot:
            row = df_summary[(df_summary["param_set"] == ps) & (df_summary["eval_group"] == eg)]
            if row.empty or np.isnan(row.iloc[0]["mean_err"]):
                means.append(0); sems.append(0)
            else:
                means.append(row.iloc[0]["mean_err"])
                n = row.iloc[0]["n_mice"]
                sems.append(row.iloc[0]["std_err"] / np.sqrt(n) if n > 1 else 0)
        offset = (i - n_ps / 2 + 0.5) * bar_width
        ax.bar(x_base + offset, means, bar_width * 0.9, yerr=sems, capsize=2,
               label=_ps_label(ps), color=_ps_color(ps), alpha=0.85,
               edgecolor="black", linewidth=0.6)
    ax.set_xticks(x_base)
    ax.set_xticklabels(eval_groups_for_plot)
    ax.set_ylabel("Median decoding error (cm)")
    ax.set_title("PF decoder cross-evaluation: param set × group")
    from matplotlib.patches import Patch as _Patch5a_pf
    handles = [_Patch5a_pf(facecolor=_ps_color(ps), alpha=0.85,
                           edgecolor="black", lw=0.6, label=_ps_label(ps))
               for ps in ps_labels]
    ax.legend(handles=handles, title="Param set")
    ax.grid(True, axis="y", alpha=0.25)
    fig.tight_layout()
    fig.savefig(os.path.join(opt_plots_dir, "cross_eval_grouped_bar.pdf"))
    fig.savefig(os.path.join(opt_plots_dir, "cross_eval_grouped_bar.png"))
    plt.close(fig)

    # --- 5b) Per-mouse heatmap ---
    pivot = df_cross.pivot_table(index="mouse", columns="param_set",
                                 values="median_err", aggfunc="first")
    mouse_order = []
    for gl in group_labels:
        mouse_order.extend(sorted(m for m in pivot.index if mouse_groups.get(m, "NA") == gl))
    pivot = pivot.reindex(index=mouse_order, columns=ps_labels)

    _hm_h = max(NATURE_1COL_WIDTH_IN * 0.6, 0.25 * len(mouse_order) + 0.8)
    fig, ax = plt.subplots(figsize=(NATURE_1COL_WIDTH_IN, _hm_h))
    data_mat = pivot.to_numpy(dtype=float)
    im = ax.imshow(data_mat, aspect="auto", cmap="RdYlGn_r")
    ax.set_xticks(range(len(ps_labels)))
    ax.set_xticklabels(ps_labels, rotation=35, ha="right")
    ax.set_yticks(range(len(mouse_order)))
    ylabels = [f"{m} ({mouse_groups.get(m, '?')})" for m in mouse_order]
    ax.set_yticklabels(ylabels)
    _annot_fs = max(4.5, 6 - 0.1 * len(mouse_order))
    for r in range(data_mat.shape[0]):
        for c in range(data_mat.shape[1]):
            v = data_mat[r, c]
            if np.isfinite(v):
                ax.text(c, r, f"{v:.1f}", ha="center", va="center", fontsize=_annot_fs,
                        color="white" if v > np.nanpercentile(data_mat, 70) else "black")
    cb = fig.colorbar(im, ax=ax, pad=0.02, shrink=0.85)
    cb.set_label("Median decoding error (cm)")
    ax.set_title("PF decoder: per-mouse × param-set error")
    fig.tight_layout()
    fig.savefig(os.path.join(opt_plots_dir, "cross_eval_heatmap.pdf"))
    fig.savefig(os.path.join(opt_plots_dir, "cross_eval_heatmap.png"))
    plt.close(fig)

    # --- 5c) Box plot with scatter by group ---
    fig, ax = plt.subplots(figsize=(NATURE_1COL_WIDTH_IN, NATURE_1COL_WIDTH_IN * 0.85))
    _group_dot_map = {
        "mCherry": _PAPER_DOT_COLORS.get("mCherry", "#7a7a7a"),
        "hM3D":    _PAPER_DOT_COLORS.get("hM3D",    "#d98e8e"),
        "hM4D":    _PAPER_DOT_COLORS.get("hM4D",    "#8fb5d5"),
    }
    for i, ps in enumerate(ps_labels):
        sub = df_cross[(df_cross["param_set"] == ps) & df_cross["ok"]]
        all_vals = sub["median_err"].dropna().to_numpy()
        if len(all_vals) > 0:
            bp = ax.boxplot([all_vals], positions=[i], widths=0.5, **_BP_KW_OPT, zorder=2)
            _style_bp_opt(bp, ps)
        for gl in group_labels:
            vals = sub[sub["group"] == gl]["median_err"].dropna().to_numpy()
            jitter = np.random.default_rng(42 + i).uniform(-0.12, 0.12, size=len(vals))
            ax.scatter(np.full_like(vals, i) + jitter, vals,
                       color=_group_dot_map.get(gl, "#888888"), s=30, alpha=0.85,
                       edgecolors="white", linewidths=0.3, zorder=3)
    ax.set_xticks(range(n_ps))
    ax.set_xticklabels([_ps_label(ps) for ps in ps_labels], rotation=25, ha="right")
    ax.set_ylabel("Median decoding error (cm)")
    ax.set_title("PF decoder: error by param set (dots by group)")
    from matplotlib.patches import Patch as _Patch5c_pf
    from matplotlib.lines import Line2D as _Line2D_pf
    box_handles = [_Patch5c_pf(facecolor=_ps_color(ps), alpha=_OPT_PS_ALPHA,
                               edgecolor="black", lw=0.6, label=_ps_label(ps))
                   for ps in ps_labels]
    dot_handles = [_Line2D_pf([0], [0], marker='o', color='w',
                              markerfacecolor=_group_dot_map.get(gl, "#888"),
                              markeredgecolor="white", markeredgewidth=0.3,
                              markersize=7, label=gl) for gl in group_labels]
    leg1 = ax.legend(handles=box_handles, title="Param set",
                     loc="upper left", framealpha=0.9, edgecolor="none")
    ax.add_artist(leg1)
    ax.legend(handles=dot_handles, title="Group",
              loc="upper right", framealpha=0.9, edgecolor="none")
    # Bracket annotations for significant pairs
    if _wilcox_all_pairs:
        _sig_bracket_pairs = [(pa, pb, v["sig"]) for (pa, pb), v in _wilcox_all_pairs.items()
                              if v["sig"] != "ns"]
        if _sig_bracket_pairs:
            _ps_idx = {ps: i for i, ps in enumerate(ps_labels)}
            _ylo_5c, _yhi_5c = ax.get_ylim()
            _bracket_h = (_yhi_5c - _ylo_5c) * 0.03
            _bracket_gap = (_yhi_5c - _ylo_5c) * 0.04
            _sig_bracket_pairs.sort(key=lambda t: abs(_ps_idx[t[0]] - _ps_idx[t[1]]))
            _all_data_max = df_cross[df_cross["ok"]]["median_err"].max()
            _bracket_y = _all_data_max + (_yhi_5c - _ylo_5c) * 0.05
            for _pa, _pb, _sig_str in _sig_bracket_pairs:
                _x1 = _ps_idx[_pa]; _x2 = _ps_idx[_pb]
                if _x1 > _x2:
                    _x1, _x2 = _x2, _x1
                ax.plot([_x1, _x1, _x2, _x2],
                        [_bracket_y, _bracket_y + _bracket_h,
                         _bracket_y + _bracket_h, _bracket_y],
                        color="black", lw=0.8, clip_on=False)
                ax.text((_x1 + _x2) / 2, _bracket_y + _bracket_h,
                        _sig_str, ha="center", va="bottom",
                        fontsize=8, fontweight="bold")
                _bracket_y += _bracket_h + _bracket_gap
            ax.set_ylim(_ylo_5c, _bracket_y + _bracket_gap)
    ax.grid(True, axis="y", alpha=0.25)
    fig.tight_layout()
    fig.savefig(os.path.join(opt_plots_dir, "cross_eval_box_by_group.pdf"))
    fig.savefig(os.path.join(opt_plots_dir, "cross_eval_box_by_group.png"))
    plt.close(fig)

    # --- 5d) Delta vs baseline ---
    baseline_errs = {}
    for _, row in df_cross[df_cross["param_set"] == "baseline"].iterrows():
        if row["ok"]:
            baseline_errs[row["mouse"]] = row["median_err"]

    non_baseline_ps = [ps for ps in ps_labels if ps != "baseline"]
    if baseline_errs and non_baseline_ps:
        fig, ax = plt.subplots(figsize=(NATURE_1COL_WIDTH_IN, NATURE_1COL_WIDTH_IN * 0.75))
        for i, ps in enumerate(non_baseline_ps):
            means_by_eg = []; sems_by_eg = []
            for eg in eval_groups_for_plot:
                sub = df_cross[(df_cross["param_set"] == ps) & df_cross["ok"]]
                if eg != "ALL":
                    sub = sub[sub["group"] == eg]
                deltas = []
                for _, row in sub.iterrows():
                    bval = baseline_errs.get(row["mouse"], np.nan)
                    if np.isfinite(bval) and np.isfinite(row["median_err"]):
                        deltas.append(row["median_err"] - bval)
                if deltas:
                    means_by_eg.append(np.mean(deltas))
                    sems_by_eg.append(np.std(deltas, ddof=1) / np.sqrt(len(deltas))
                                      if len(deltas) > 1 else 0)
                else:
                    means_by_eg.append(0); sems_by_eg.append(0)
            offset = (i - len(non_baseline_ps) / 2 + 0.5) * bar_width
            fc = _ps_color(ps)
            for j, (d, sem) in enumerate(zip(means_by_eg, sems_by_eg)):
                ls = "-" if d >= 0 else "--"
                ax.bar(x_base[j] + offset, d, bar_width * 0.9,
                       color=fc, alpha=0.75, edgecolor="black",
                       linewidth=0.8, linestyle=ls)
                ax.errorbar(x_base[j] + offset, d, yerr=sem,
                            fmt="none", ecolor="black", capsize=3, lw=0.8)
        if _wilcox_vs_bl and "ALL" in eval_groups_for_plot:
            _all_col_idx = eval_groups_for_plot.index("ALL")
            _ylo_5d, _yhi_5d = ax.get_ylim()
            _ystep_5d = (_yhi_5d - _ylo_5d) * 0.02
            for _i5d, _ps5d in enumerate(non_baseline_ps):
                _sig5d = _wilcox_vs_bl.get(_ps5d, {}).get("sig", "ns")
                if _sig5d != "ns":
                    _off5d = (_i5d - len(non_baseline_ps) / 2 + 0.5) * bar_width
                    _x5d = x_base[_all_col_idx] + _off5d
                    _sub5d = df_cross[(df_cross["param_set"] == _ps5d) & df_cross["ok"]]
                    _dlt5d = [row["median_err"] - baseline_errs.get(row["mouse"], np.nan)
                              for _, row in _sub5d.iterrows()
                              if np.isfinite(baseline_errs.get(row["mouse"], np.nan))
                              and np.isfinite(row["median_err"])]
                    _md5d = np.mean(_dlt5d) if _dlt5d else 0
                    _se5d = (np.std(_dlt5d, ddof=1) / np.sqrt(len(_dlt5d))
                             if len(_dlt5d) > 1 else 0)
                    if _md5d < 0:
                        ax.text(_x5d, _md5d - _se5d - _ystep_5d, _sig5d,
                                ha="center", va="top", fontsize=8, fontweight="bold")
                    else:
                        ax.text(_x5d, _md5d + _se5d + _ystep_5d, _sig5d,
                                ha="center", va="bottom", fontsize=8, fontweight="bold")
        ax.axhline(0, color="black", linewidth=0.8)
        ax.set_xticks(x_base)
        ax.set_xticklabels(eval_groups_for_plot)
        ax.set_ylabel("Δ error vs baseline (cm, negative = better)")
        ax.set_title("PF decoder: improvement over baseline by group")
        from matplotlib.patches import Patch as _Patch5d_pf
        handles = [_Patch5d_pf(facecolor=_ps_color(ps), alpha=0.75,
                               edgecolor="black", lw=0.6, label=_ps_label(ps))
                   for ps in non_baseline_ps]
        ax.legend(handles=handles, title="Param set")
        ax.grid(True, axis="y", alpha=0.25)
        fig.tight_layout()
        fig.savefig(os.path.join(opt_plots_dir, "cross_eval_delta_vs_baseline.pdf"))
        fig.savefig(os.path.join(opt_plots_dir, "cross_eval_delta_vs_baseline.png"))
        plt.close(fig)

    # Restore rcParams
    _mpl.rcParams.update(_saved_rc)

    # ==================================================================
    # 6) Text summary
    # ==================================================================

    summary_lines = []
    summary_lines.append("=" * 70)
    summary_lines.append("GROUP-AWARE PF DECODER OPTIMIZATION SUMMARY")
    summary_lines.append("=" * 70)
    summary_lines.append(f"Date: {pd.Timestamp.now().strftime('%Y-%m-%d %H:%M:%S')}")
    summary_lines.append(f"Trials per study: {optimization_trials}")
    if _optimize_z_score:
        summary_lines.append(f"use_z_score: OPTIMIZED (searching none / per-session / across-sessions)")
    else:
        summary_lines.append(f"use_z_score (fixed): {use_z_score}")
    summary_lines.append(f"Groups: {group_labels}")
    summary_lines.append(f"Mice per group: { {gl: len(group_to_mice[gl]) for gl in group_labels} }")
    summary_lines.append("")

    summary_lines.append("-" * 70)
    summary_lines.append("OPTIMIZED PARAMETER SETS")
    summary_lines.append("-" * 70)
    param_keys = list(baseline_params.keys())
    header = f"{'param':<30s}" + "".join(f"{ps:<20s}" for ps in ps_labels)
    summary_lines.append(header)
    for pk in param_keys:
        row_str = f"{pk:<30s}"
        for ps in ps_labels:
            v = param_sets[ps].get(pk, "N/A")
            if isinstance(v, float):
                row_str += f"{v:<20.4f}"
            else:
                row_str += f"{str(v):<20s}"
        summary_lines.append(row_str)
    summary_lines.append("")

    summary_lines.append("-" * 70)
    summary_lines.append("CROSS-EVALUATION: MEAN MEDIAN ERROR (param_set × eval_group)")
    summary_lines.append("-" * 70)
    header = f"{'param_set':<20s}" + "".join(f"{eg:<15s}" for eg in eval_groups_for_plot)
    summary_lines.append(header)
    for ps in ps_labels:
        row_str = f"{ps:<20s}"
        for eg in eval_groups_for_plot:
            row = df_summary[(df_summary["param_set"] == ps) & (df_summary["eval_group"] == eg)]
            if row.empty or np.isnan(row.iloc[0]["mean_err"]):
                row_str += f"{'N/A':<15s}"
            else:
                me = row.iloc[0]["mean_err"]
                se = row.iloc[0]["std_err"]
                n = row.iloc[0]["n_mice"]
                sem = se / np.sqrt(n) if n > 1 and np.isfinite(se) else 0
                row_str += f"{me:.2f}±{sem:.2f}     "
        summary_lines.append(row_str)
    summary_lines.append("")

    summary_lines.append("-" * 70)
    summary_lines.append("BEST PARAM SET PER EVALUATION GROUP (lowest mean error)")
    summary_lines.append("-" * 70)
    for eg in eval_groups_for_plot:
        sub = df_summary[df_summary["eval_group"] == eg].dropna(subset=["mean_err"])
        if sub.empty:
            summary_lines.append(f"  {eg}: N/A")
        else:
            best_row = sub.loc[sub["mean_err"].idxmin()]
            summary_lines.append(
                f"  {eg}: {best_row['param_set']} "
                f"(mean={best_row['mean_err']:.2f}, n={int(best_row['n_mice'])})")
    summary_lines.append("")

    summary_lines.append("-" * 70)
    summary_lines.append("IMPROVEMENT VS BASELINE (negative = better)")
    summary_lines.append("-" * 70)
    hdr = f"  {'param_set':<18s}" + "".join(f"{eg:<15s}" for eg in eval_groups_for_plot)
    summary_lines.append(hdr)
    base_row = df_summary[df_summary["param_set"] == "baseline"]
    for ps in ps_labels:
        if ps == "baseline":
            continue
        row_str = f"  {ps:<18s}"
        for eg in eval_groups_for_plot:
            ps_row = df_summary[(df_summary["param_set"] == ps) & (df_summary["eval_group"] == eg)]
            b_row = base_row[base_row["eval_group"] == eg]
            if ps_row.empty or b_row.empty:
                row_str += f"{'N/A':<15s}"
            else:
                delta = ps_row.iloc[0]["mean_err"] - b_row.iloc[0]["mean_err"]
                row_str += f"{delta:+.2f}          "
        summary_lines.append(row_str)

    summary_lines.append("")
    summary_lines.append("=" * 70)
    summary_text = "\n".join(summary_lines)
    print(summary_text)

    summary_path = os.path.join(opt_dir, "optimization_summary.txt")
    with open(summary_path, "w", encoding="utf-8") as f:
        f.write(summary_text)
    print(f"\n[OPT-PF] Summary saved: {summary_path}")

    # ==================================================================
    # 7) Statistical comparison (identical to non-PF optimizer)
    # ==================================================================

    from scipy import stats as _sp_stats_opt_pf
    from itertools import combinations as _combinations_pf

    stat_lines = []
    stat_lines.append("")
    stat_lines.append("=" * 70)
    stat_lines.append("STATISTICAL COMPARISON OF PF PARAM SETS (paired across mice)")
    stat_lines.append("=" * 70)

    _ok_cross = df_cross[df_cross["ok"]].copy()
    _mice_per_ps = {ps: set(_ok_cross[_ok_cross["param_set"] == ps]["mouse"])
                    for ps in ps_labels}
    _common_mice = sorted(set.intersection(*_mice_per_ps.values())) if _mice_per_ps else []
    stat_lines.append(f"Mice included (succeeded in all {len(ps_labels)} param sets): "
                      f"{len(_common_mice)}/{len(available_mice)}")
    stat_lines.append(f"  {_common_mice}")
    stat_lines.append("")

    df_wilcox = pd.DataFrame()
    if len(_common_mice) >= 3 and len(ps_labels) >= 2:
        _err_matrix = {}
        for ps in ps_labels:
            sub = _ok_cross[_ok_cross["param_set"] == ps].set_index("mouse")
            _err_matrix[ps] = np.array([sub.loc[m, "median_err"] for m in _common_mice])

        # 7a) Friedman
        stat_lines.append("-" * 70)
        stat_lines.append("FRIEDMAN TEST (all param sets)")
        stat_lines.append("-" * 70)
        try:
            _friedman_arrays = [_err_matrix[ps] for ps in ps_labels]
            _fr_stat, _fr_p = _sp_stats_opt_pf.friedmanchisquare(*_friedman_arrays)
            stat_lines.append(f"  χ²({len(ps_labels)-1}) = {_fr_stat:.3f},  p = {_fr_p:.4g}")
            if _fr_p < 0.05:
                stat_lines.append("  → Significant: param sets produce different errors (p < 0.05)")
            else:
                stat_lines.append("  → Not significant at α = 0.05")
        except Exception as _exc:
            stat_lines.append(f"  Friedman test failed: {_exc}")
        stat_lines.append("")

        # 7b) Pairwise Wilcoxon
        stat_lines.append("-" * 70)
        stat_lines.append("PAIRWISE WILCOXON SIGNED-RANK TESTS")
        stat_lines.append("-" * 70)
        _wilcox_rows = []
        for ps_a, ps_b in _combinations_pf(ps_labels, 2):
            a_vals = _err_matrix[ps_a]; b_vals = _err_matrix[ps_b]
            diff = a_vals - b_vals
            if np.all(diff == 0):
                _wilcox_rows.append({
                    "param_set_A": ps_a, "param_set_B": ps_b,
                    "mean_diff": 0.0, "W_stat": np.nan, "p_raw": 1.0,
                    "cohens_d": 0.0, "direction": "equal"})
                continue
            try:
                _w_stat, _w_p = _sp_stats_opt_pf.wilcoxon(a_vals, b_vals, alternative="two-sided")
            except Exception:
                _w_stat, _w_p = np.nan, np.nan
            _d_mean = np.mean(diff)
            _d_std = np.std(diff, ddof=1)
            _cohens_d = _d_mean / _d_std if _d_std > 0 else 0.0
            direction = f"{ps_a} better" if _d_mean < 0 else f"{ps_b} better"
            _wilcox_rows.append({
                "param_set_A": ps_a, "param_set_B": ps_b,
                "mean_diff": float(_d_mean), "W_stat": float(_w_stat),
                "p_raw": float(_w_p), "cohens_d": float(_cohens_d),
                "direction": direction})

        df_wilcox = pd.DataFrame(_wilcox_rows)
        if len(df_wilcox) > 0:
            _raw_ps = df_wilcox["p_raw"].to_numpy(dtype=float)
            _sorted_idx = np.argsort(_raw_ps)
            _m = len(_raw_ps)
            _corrected = np.ones(_m)
            for rank, idx in enumerate(_sorted_idx):
                _corrected[idx] = min(1.0, _raw_ps[idx] * (_m - rank))
            _prev = 0.0
            for idx in _sorted_idx:
                _corrected[idx] = max(_corrected[idx], _prev)
                _prev = _corrected[idx]
            df_wilcox["p_holm"] = _corrected
            df_wilcox["sig"] = df_wilcox["p_holm"].apply(
                lambda p: "***" if p < 0.001 else ("**" if p < 0.01 else
                          ("*" if p < 0.05 else (f"p={p:.3f}" if p < 0.08 else "ns"))))

        stat_lines.append(
            f"  {'A':<12s} {'B':<12s} {'mean(A-B)':>10s} {'W':>8s} "
            f"{'p_raw':>10s} {'p_holm':>10s} {'d':>8s} {'sig':>5s}  {'direction'}")
        for _, r in df_wilcox.iterrows():
            stat_lines.append(
                f"  {r['param_set_A']:<12s} {r['param_set_B']:<12s} "
                f"{r['mean_diff']:>10.3f} {r['W_stat']:>8.0f} "
                f"{r['p_raw']:>10.4g} {r['p_holm']:>10.4g} "
                f"{r['cohens_d']:>8.3f} {r['sig']:>5s}  {r['direction']}")
        stat_lines.append("")
        wilcox_csv = os.path.join(opt_tables_dir, "pairwise_wilcoxon.csv")
        df_wilcox.to_csv(wilcox_csv, index=False)
        stat_lines.append(f"  Saved: {wilcox_csv}")

        # 7c) Average rank
        stat_lines.append("")
        stat_lines.append("-" * 70)
        stat_lines.append("AVERAGE RANK PER PARAM SET (1 = best per mouse, lower = better)")
        stat_lines.append("-" * 70)
        _rank_matrix = np.column_stack([_err_matrix[ps] for ps in ps_labels])
        _ranks = _sp_stats_opt_pf.rankdata(_rank_matrix, axis=1)
        _mean_ranks = _ranks.mean(axis=0)
        for i, ps in enumerate(ps_labels):
            stat_lines.append(f"  {ps:<18s}  mean_rank = {_mean_ranks[i]:.2f}")
        _best_rank_ps = ps_labels[int(np.argmin(_mean_ranks))]
        stat_lines.append(f"  → Best average rank: {_best_rank_ps}")
        stat_lines.append("")

        # 7d) Win-count matrix
        stat_lines.append("-" * 70)
        stat_lines.append(f"WIN-COUNT MATRIX (out of {len(_common_mice)} mice)")
        stat_lines.append("-" * 70)
        header_wc = f"  {'wins↓ vs→':<14s}" + "".join(f"{ps:<12s}" for ps in ps_labels)
        stat_lines.append(header_wc)
        for i, ps_a in enumerate(ps_labels):
            row_str = f"  {ps_a:<14s}"
            for j, ps_b in enumerate(ps_labels):
                if i == j:
                    row_str += f"{'---':<12s}"
                else:
                    n_wins = int(np.sum(_err_matrix[ps_a] < _err_matrix[ps_b]))
                    row_str += f"{n_wins:<12d}"
            stat_lines.append(row_str)
        stat_lines.append("")
    else:
        stat_lines.append("  Insufficient data for statistical tests "
                          "(need ≥3 common mice and ≥2 param sets).")
        stat_lines.append("")

    stat_lines.append("=" * 70)
    stat_text = "\n".join(stat_lines)
    print(stat_text)

    with open(summary_path, "a", encoding="utf-8") as f:
        f.write("\n" + stat_text)
    print(f"[OPT-PF] Statistics appended to: {summary_path}")

    all_params_json = os.path.join(opt_tables_dir, "all_param_sets.json")
    with open(all_params_json, "w", encoding="utf-8") as f:
        _json.dump(param_sets, f, indent=2)
    print(f"[OPT-PF] All param sets saved: {all_params_json}")

    return {
        "ok": True,
        "param_sets": param_sets,
        "cross_eval": df_cross,
        "summary": df_summary,
        "opt_dir": opt_dir,
        "stats_wilcoxon": df_wilcox,
    }


# ---------------------------------------------------------------------------
#  Master pipeline: run 2D TFC_cond→Test_B decoding for all mice
# ---------------------------------------------------------------------------

def run_TFC_2D_decoding_all_mice(
    TFC_cond_group: dict,
    Test_B_group: dict,
    *,
    mapping: str = "TFC_cond+Test_B",
    n_x_bins: int = 20,
    n_y_bins: int = 20,
    time_bin_frames: int = 5,
    use_posterior_mean: bool = True,
    use_speed: bool = True,
    min_speed: float = 2.0,
    first_n_sec: float = 180.0,
    use_z_score: str = "none",
    enable_shuffle_control: bool = False,
    shuffle_type: str = "circular_time_shift",
    n_shuffles: int = 5,
    shuffle_seed: int = 42,
    PLOTS_DIR: str = "",
    session_str: str = "TFC_2D",
    mouse_groups: dict = None,
    plot_debug: bool = True,
    auto_close: bool = True,
) -> dict:
    """
    Runs 2D Bayesian decoding:
      1) Within-session CV on TFC_cond pre-tone (all cross-registered cells)
      2) Cross-session  TFC_cond → Test_B  (pre-tone, cross-registered cells)

    Returns dict[mouse] -> result dict.
    """
    if mouse_groups is None:
        mouse_groups = {}

    shuffle_suffix = "_shuffle" if _shuffle_is_enabled(enable_shuffle_control, n_shuffles, shuffle_type) else ""
    save_path = os.path.join(PLOTS_DIR, f"bayes_2D_{session_str}_mapping_{mapping}_{_z_score_dir_tag(use_z_score)}{shuffle_suffix}")
    os.makedirs(save_path, exist_ok=True)

    all_results = {}
    mice = sorted(set(TFC_cond_group.keys()) & set(Test_B_group.keys()))

    for mouse in mice:
        TFC = TFC_cond_group[mouse]
        TB = Test_B_group[mouse]
        group = mouse_groups.get(mouse, "NA")

        print(f"[2D-DECODE] {mouse} ({group}) ...")

        res = decode_TFC_to_TestB_2D(
            TFC, TB,
            mapping=mapping,
            n_x_bins=n_x_bins,
            n_y_bins=n_y_bins,
            time_bin_frames=time_bin_frames,
            use_posterior_mean=use_posterior_mean,
            use_speed=use_speed,
            min_speed=min_speed,
            first_n_sec=first_n_sec,
            use_z_score=use_z_score,
        )

        all_results[mouse] = res

        if not res.get("ok", False):
            print(f"  [SKIP] {mouse}: {res.get('reason', '?')}")
            continue

        if _shuffle_is_enabled(enable_shuffle_control, n_shuffles, shuffle_type):
            _xfer_repeat_rows = []
            _xfer_repeat_medians = []
            _within_repeat_medians = []
            for _rep in range(int(n_shuffles)):
                _seed = int(shuffle_seed) + _stable_seed_from_text(f"tfc|{mouse}|{mapping}") + int(_rep)
                _sh = decode_TFC_to_TestB_2D(
                    TFC, TB,
                    mapping=mapping,
                    n_x_bins=n_x_bins,
                    n_y_bins=n_y_bins,
                    time_bin_frames=time_bin_frames,
                    use_posterior_mean=use_posterior_mean,
                    use_speed=use_speed,
                    min_speed=min_speed,
                    first_n_sec=first_n_sec,
                    use_z_score=use_z_score,
                    shuffle_type=shuffle_type,
                    shuffle_seed=_seed,
                )
                if not _sh.get("ok", False):
                    continue
                _x = np.asarray(_sh.get("euclidean_err", []), float)
                _x = _x[np.isfinite(_x)]
                if _x.size > 0:
                    _med = float(np.nanmedian(_x))
                    _xfer_repeat_medians.append(_med)
                    _xfer_repeat_rows.append({"repeat": int(_rep), "median_err": _med, "seed": int(_seed)})
                _w = np.asarray(_sh.get("within_TFC", {}).get("pooled_euclidean_err", []), float)
                _w = _w[np.isfinite(_w)]
                if _w.size > 0:
                    _within_repeat_medians.append(float(np.nanmedian(_w)))

            res["shuffle_control"] = {
                "ok": len(_xfer_repeat_medians) > 0,
                "shuffle_type": shuffle_type,
                "n_shuffles": int(n_shuffles),
                "repeat_rows": _xfer_repeat_rows,
                "median_of_repeat_medians": float(np.nanmedian(_xfer_repeat_medians)) if len(_xfer_repeat_medians) > 0 else np.nan,
                "mean_of_repeat_medians": float(np.nanmean(_xfer_repeat_medians)) if len(_xfer_repeat_medians) > 0 else np.nan,
            }
            res.setdefault("within_TFC", {})["shuffle_control"] = {
                "ok": len(_within_repeat_medians) > 0,
                "shuffle_type": shuffle_type,
                "n_shuffles": int(n_shuffles),
                "median_of_repeat_medians": float(np.nanmedian(_within_repeat_medians)) if len(_within_repeat_medians) > 0 else np.nan,
                "mean_of_repeat_medians": float(np.nanmean(_within_repeat_medians)) if len(_within_repeat_medians) > 0 else np.nan,
            }

        unit_label = res.get("position_unit", _TFC_TEST_2D_DISTANCE_UNIT)

        print(f"  n_cells={res['n_cells_mapped']}  "
              f"pretone_tfc={res['n_pretone_frames_tfc']}  "
              f"pretone_testb={res['n_pretone_frames_testb']}  "
              f"median_err_xfer={np.nanmedian(res['euclidean_err']):.1f}{unit_label}")

        # --- Per-mouse diagnostic plots ---
        tag_base = f"{mouse}_{group}_{session_str}"

        # 1) Error histogram (cross-session)
        fig, ax = plt.subplots(figsize=(8, 5), dpi=150)
        ax.hist(res["euclidean_err"], bins=50, color="steelblue", alpha=0.8)
        ax.set_xlabel(_euclidean_error_axis_label())
        ax.set_ylabel("Count")
        ax.set_title(f"{mouse} {group} — TFC→TestB 2D error")
        ax.axvline(np.nanmedian(res["euclidean_err"]), color="red", ls="--",
                    label=f"median={np.nanmedian(res['euclidean_err']):.1f}")
        ax.legend()
        fig.tight_layout()
        fig.savefig(os.path.join(save_path, f"{tag_base}_xfer_errhist.png"), dpi=300)
        if plot_debug:
            plt.show()
        if auto_close:
            plt.close(fig)

        # 2) Decoded vs true scatter (X and Y)
        out = res["out"]
        fig, axes = plt.subplots(1, 2, figsize=(12, 5), dpi=150)
        for ax, true, dec, label in [
            (axes[0], out["true_x"], out["decoded_x"], "X"),
            (axes[1], out["true_y"], out["decoded_y"], "Y"),
        ]:
            ax.scatter(true, dec, s=6, alpha=0.3)
            lo = min(np.nanmin(true), np.nanmin(dec))
            hi = max(np.nanmax(true), np.nanmax(dec))
            ax.plot([lo, hi], [lo, hi], "r-", lw=1.5)
            ax.set_xlabel(f"True {label} ({unit_label})")
            ax.set_ylabel(f"Decoded {label} ({unit_label})")
            ax.set_title(f"{mouse} {group} — TFC→TestB {label}")
            ax.grid(True, alpha=0.2)
        fig.tight_layout()
        fig.savefig(os.path.join(save_path, f"{tag_base}_xfer_scatter_XY.png"), dpi=300)
        if plot_debug:
            plt.show()
        if auto_close:
            plt.close(fig)

        # 3) 2D trajectory overlay: true vs decoded
        fig, ax = plt.subplots(figsize=(7, 7), dpi=150)
        ax.plot(out["true_x"], out["true_y"], "k-", alpha=0.15, lw=0.5, label="true")
        ax.scatter(out["decoded_x"], out["decoded_y"], c=res["euclidean_err"],
                   s=10, alpha=0.6, cmap="hot", vmin=0,
                   vmax=np.nanpercentile(res["euclidean_err"], 95))
        cb = plt.colorbar(ax.collections[-1], ax=ax, pad=0.02)
        cb.set_label(f"Eucl. error ({unit_label})")
        ax.set_xlabel(_xy_axis_label("X")); ax.set_ylabel(_xy_axis_label("Y"))
        ax.set_title(f"{mouse} {group} — TFC→TestB decoded trajectory")
        ax.set_aspect("equal")
        fig.tight_layout()
        fig.savefig(os.path.join(save_path, f"{tag_base}_xfer_traj2D.png"), dpi=300)
        if plot_debug:
            plt.show()
        if auto_close:
            plt.close(fig)

        # 4) Within-session TFC CV
        within = res.get("within_TFC", {})
        if within.get("ok", False):
            w_err = within.get("pooled_euclidean_err", np.array([]))
            if w_err.size > 0:
                fig, ax = plt.subplots(figsize=(8, 5), dpi=150)
                ax.hist(w_err, bins=50, color="seagreen", alpha=0.8)
                ax.set_xlabel(_euclidean_error_axis_label())
                ax.set_ylabel("Count")
                ax.set_title(f"{mouse} {group} — within-TFC 2D CV")
                ax.axvline(np.nanmedian(w_err), color="red", ls="--",
                            label=f"median={np.nanmedian(w_err):.1f}")
                ax.legend()
                fig.tight_layout()
                fig.savefig(os.path.join(save_path, f"{tag_base}_withinTFC_errhist.png"), dpi=300)
                if plot_debug:
                    plt.show()
                if auto_close:
                    plt.close(fig)

    if _shuffle_is_enabled(enable_shuffle_control, n_shuffles, shuffle_type):
        _target_lbl = "xfer"
        try:
            _parts = [p.strip() for p in str(mapping).split("+") if len(p.strip()) > 0]
            if len(_parts) >= 2:
                _target_lbl = _parts[-1]
        except Exception:
            _target_lbl = "xfer"
        _save_shuffle_control_comparison(
            {
                m: {
                    "group": mouse_groups.get(m, "NA"),
                    "within_train": v.get("within_TFC", {}),
                    "targets": {_target_lbl: v} if v.get("ok", False) else {},
                }
                for m, v in all_results.items()
            },
            mouse_groups=mouse_groups,
            save_path=os.path.join(save_path, "shuffle_control_stats"),
            train_label="TFC",
            auto_close=auto_close,
        )

    print(f"[2D-DECODE] Done. {len(all_results)} mice processed, "
          f"{sum(1 for v in all_results.values() if v.get('ok'))} succeeded.")
    return all_results


# ---------------------------------------------------------------------------
#  Statistics & group-level plotting for 2D TFC → Test_B decoding
# ---------------------------------------------------------------------------

def _normalize_scoring_methods(use_scoring_method: str) -> List[str]:
    """Return one or more scoring methods from user switch input."""
    method = str(use_scoring_method).strip().lower()
    if method == "both":
        return ["euclidean", "rsquared"]
    if method in {"euclidean", "rsquared"}:
        return [method]
    print(f"[SCORING] Unknown scoring method '{use_scoring_method}', falling back to 'euclidean'.")
    return ["euclidean"]


def _compute_r2_vaf_stable(
    y_true: np.ndarray,
    y_pred: np.ndarray,
    *,
    min_points: int = 5,
    min_std_px: float = 3.0,
) -> float:
    """Robust VAF/R2 for decoding traces; skips low-dynamic-range segments."""
    y_true = np.asarray(y_true, float)
    y_pred = np.asarray(y_pred, float)
    keep = np.isfinite(y_true) & np.isfinite(y_pred)
    if np.sum(keep) < min_points:
        return np.nan

    yt = y_true[keep]
    yp = y_pred[keep]

    # Near-constant true position leads to unstable and arbitrarily negative R2.
    if np.nanstd(yt) < float(min_std_px):
        return np.nan

    den = np.sum((yt - np.mean(yt)) ** 2)
    if den <= 0:
        return np.nan
    num = np.sum((yp - yt) ** 2)
    return float(1.0 - (num / den))

def build_TFC_2D_summary_dataframe(
    dec_results_2D: dict,
    mouse_groups: dict,
    use_scoring_method: str = "euclidean",
    pct_threshold: float = 15.0,
) -> pd.DataFrame:
    """
    Build a mouse-level summary DataFrame with columns:
        mouse, group, condition, median_err, mean_err, n_chunks, median_Ksum,
        mean_Ksum, error_unit, distance_scale_cm_per_px
    Conditions:
        'within_TFC'   – within-session CV on TFC_cond pre-tone
        'TFC_to_TestB'  – cross-session transfer
    """
    rows = []

    def _compute_r2_vaf(y_true: np.ndarray, y_pred: np.ndarray) -> float:
        return _compute_r2_vaf_stable(y_true, y_pred)

    def _score_from_out(out: dict, ksum: Optional[np.ndarray] = None) -> np.ndarray:
        method = str(use_scoring_method).strip().lower()
        if method != "rsquared":
            err = np.asarray(out.get("euclidean_err", []), float)
            return err[np.isfinite(err)]

        tx = np.asarray(out.get("true_x", []), float)
        ty = np.asarray(out.get("true_y", []), float)
        dx = np.asarray(out.get("decoded_x", []), float)
        dy = np.asarray(out.get("decoded_y", []), float)
        n = min(tx.size, ty.size, dx.size, dy.size)
        if n == 0:
            return np.array([])
        tx = tx[:n]; ty = ty[:n]; dx = dx[:n]; dy = dy[:n]
        keep = np.isfinite(tx) & np.isfinite(ty) & np.isfinite(dx) & np.isfinite(dy)
        r2x = _compute_r2_vaf(tx[keep], dx[keep]) if np.any(keep) else np.nan
        r2y = _compute_r2_vaf(ty[keep], dy[keep]) if np.any(keep) else np.nan
        r2m = float(np.nanmean([r2x, r2y])) if np.isfinite(r2x) or np.isfinite(r2y) else np.nan
        return np.array([r2m]) if np.isfinite(r2m) else np.array([])

    for mouse, res in dec_results_2D.items():
        group = mouse_groups.get(mouse, "NA")
        if not res.get("ok", False):
            continue
        unit_label = res.get("position_unit", _TFC_TEST_2D_DISTANCE_UNIT)
        pos_scale = float(res.get("position_scale", _TFC_TEST_2D_CM_PER_PX))

        # --- Cross-session: TFC → Test_B ---
        Ksum_xfer = np.asarray(res["out"]["Ksum"], float)
        err_xfer = _score_from_out(res["out"], Ksum_xfer)
        n_chunks_xfer = int(np.asarray(res["out"].get("Ksum", [])).size)
        # PCT always from euclidean errors (meaningful even when scoring is R²)
        _euc_xfer = np.asarray(res["out"].get("euclidean_err", []), float)
        _euc_xfer = _euc_xfer[np.isfinite(_euc_xfer)]
        rows.append({
            "mouse": mouse,
            "group": group,
            "condition": "TFC_to_TestB",
            "median_err": float(np.nanmedian(err_xfer)) if err_xfer.size else np.nan,
            "mean_err": float(np.nanmean(err_xfer)) if err_xfer.size else np.nan,
            "pct_correct": float(np.mean(_euc_xfer < pct_threshold)) if _euc_xfer.size else np.nan,
            "n_chunks": n_chunks_xfer,
            "median_Ksum": float(np.nanmedian(Ksum_xfer)),
            "mean_Ksum": float(np.nanmean(Ksum_xfer)),
            "n_cells": int(res["n_cells_mapped"]),
            "error_unit": unit_label,
            "distance_scale_cm_per_px": pos_scale,
        })

        # --- Within-session TFC CV ---
        within = res.get("within_TFC", {})
        if within.get("ok", False):
            # For within, collect Ksum from both splits
            out_parts = []
            w_Ksum_parts = []
            for split_key in ["even_to_odd", "odd_to_even"]:
                sp = within.get(split_key, {})
                if "out" in sp and "Ksum" in sp["out"]:
                    out_parts.append(sp["out"])
                    w_Ksum_parts.append(np.asarray(sp["out"]["Ksum"], float))
            w_Ksum = np.concatenate(w_Ksum_parts) if w_Ksum_parts else np.array([])
            if out_parts:
                out_cat = {
                    "true_x": np.concatenate([np.asarray(o.get("true_x", []), float) for o in out_parts]),
                    "true_y": np.concatenate([np.asarray(o.get("true_y", []), float) for o in out_parts]),
                    "decoded_x": np.concatenate([np.asarray(o.get("decoded_x", []), float) for o in out_parts]),
                    "decoded_y": np.concatenate([np.asarray(o.get("decoded_y", []), float) for o in out_parts]),
                    "euclidean_err": np.concatenate([np.asarray(o.get("euclidean_err", []), float) for o in out_parts]),
                }
                w_err = _score_from_out(out_cat, w_Ksum if w_Ksum.size else None)
                n_chunks_w = int(np.asarray(out_cat.get("decoded_x", [])).size)
            else:
                w_err = np.asarray(within.get("pooled_euclidean_err", []), float)
                w_err = w_err[np.isfinite(w_err)]
                n_chunks_w = int(w_err.size)

            # PCT from euclidean errors for within-TFC
            if out_parts:
                _euc_w = np.asarray(out_cat.get("euclidean_err", []), float)
            else:
                _euc_w = np.asarray(within.get("pooled_euclidean_err", []), float)
            _euc_w = _euc_w[np.isfinite(_euc_w)]
            rows.append({
                "mouse": mouse,
                "group": group,
                "condition": "within_TFC",
                "median_err": float(np.nanmedian(w_err)) if w_err.size else np.nan,
                "mean_err": float(np.nanmean(w_err)) if w_err.size else np.nan,
                "pct_correct": float(np.mean(_euc_w < pct_threshold)) if _euc_w.size else np.nan,
                "n_chunks": n_chunks_w,
                "median_Ksum": float(np.nanmedian(w_Ksum)) if w_Ksum.size else np.nan,
                "mean_Ksum": float(np.nanmean(w_Ksum)) if w_Ksum.size else np.nan,
                "n_cells": int(res["n_cells_mapped"]),
                "error_unit": unit_label,
                "distance_scale_cm_per_px": pos_scale,
            })

    return pd.DataFrame(rows)


def run_TFC_2D_stats_and_plots(
    dec_results_2D: dict,
    mouse_groups: dict,
    PLOTS_DIR: str,
    session_str: str = "TFC_2D",
    mapping: str = "TFC_cond+Test_B",
    use_scoring_method: str = "euclidean",
    use_median: bool = True,
    auto_close: bool = True,
    pct_threshold: float = 15.0,
    stat_label_override=None,
):
    """
    1) Builds mouse-level summary DataFrame.
    2) Fits mixed-effects model:  err ~ group * condition + (1|mouse)
    3) Group boxplot of decoding error (within_TFC vs TFC→TestB) per group.

    Returns df, model_result
    """
    methods = _normalize_scoring_methods(use_scoring_method)
    if len(methods) > 1:
        out = {}
        print("[TFC-2D-STATS] Running both scoring methods: euclidean + rsquared")
        for method in methods:
            out[method] = run_TFC_2D_stats_and_plots(
                dec_results_2D,
                mouse_groups,
                PLOTS_DIR,
                session_str=session_str,
                mapping=mapping,
                use_scoring_method=method,
                use_median=use_median,
                auto_close=auto_close,
                pct_threshold=pct_threshold,
                stat_label_override=stat_label_override,
            )
        return out

    use_scoring_method = methods[0]
    stat_label = stat_label_override if stat_label_override else ("median" if use_median else "mean")
    score_tag = str(use_scoring_method).strip().lower()
    save_path = os.path.join(PLOTS_DIR,
                             f"TFC_2D_stats_{session_str}_mapping_{mapping}_{stat_label}_score_{score_tag}")
    os.makedirs(save_path, exist_ok=True)

    # --- Build summary ---
    df = build_TFC_2D_summary_dataframe(dec_results_2D, mouse_groups,
                                         use_scoring_method=use_scoring_method,
                                         pct_threshold=pct_threshold)
    df.to_csv(os.path.join(save_path, "TFC_2D_mouse_summary.csv"), index=False)
    print(f"[TFC-2D-STATS] Summary table ({len(df)} rows):")
    print(df.to_string(index=False))

    err_col = "pct_correct" if stat_label == "pct" else f"{stat_label}_err"

    # --- Mixed-effects model ---
    model_result = None
    df_model = df[np.isfinite(df[err_col])].copy()
    if len(df_model) > 3 and df_model["condition"].nunique() > 1:
        df_model["group"] = df_model["group"].astype("category")
        df_model["condition"] = df_model["condition"].astype("category")
        try:
            formula = f"{err_col} ~ group * condition"
            md = smf.mixedlm(formula, df_model, groups=df_model["mouse"])
            model_result = md.fit(reml=False)
            with open(os.path.join(save_path, f"mixedlm_{stat_label}_err.txt"), "w") as f:
                f.write(str(model_result.summary()))
            print(f"[TFC-2D-STATS] MixedLM saved.")
        except Exception as e:
            print(f"[TFC-2D-STATS] MixedLM failed: {e}")

    # Also fit a simpler model: TFC_to_TestB error ~ group only
    df_xfer = df_model[df_model["condition"] == "TFC_to_TestB"].copy()
    model_xfer = None
    if len(df_xfer) >= 3 and df_xfer["group"].nunique() > 1:
        try:
            md2 = smf.mixedlm(f"{err_col} ~ group", df_xfer, groups=df_xfer["mouse"])
            model_xfer = md2.fit(reml=False)
            with open(os.path.join(save_path, f"mixedlm_{stat_label}_err_xfer_only.txt"), "w") as f:
                f.write(str(model_xfer.summary()))
        except Exception as e:
            print(f"[TFC-2D-STATS] MixedLM (xfer-only) failed: {e}")

    # --- Boxplot: groups × conditions ---
    _plot_TFC_2D_group_boxplot(df, err_col, save_path, session_str, stat_label,
                                use_scoring_method=use_scoring_method,
                                auto_close=auto_close)

    return df, model_result, model_xfer


def _plot_TFC_2D_group_boxplot(
    df, err_col, save_path, session_str, stat_label,
    use_scoring_method: str = "euclidean",
    auto_close=True,
):
    """
    Grouped boxplot: X = condition, hue = manipulation group, Y = decoding error.
    """
    group_order = ["mCherry", "hM3D", "hM4D"]
    colors = {"mCherry": "black", "hM3D": "red", "hM4D": "blue"}
    cond_order = [c for c in ["within_TFC", "TFC_to_TestB"] if c in set(df["condition"].astype(str))]
    if len(cond_order) == 0:
        return

    width = 0.22
    x_base = np.arange(len(cond_order))
    fig, ax = plt.subplots(figsize=(max(6, 3 * len(cond_order)), 5), dpi=150)
    for gi, grp in enumerate(group_order):
        positions = x_base + (gi - 1) * width
        data_per_cond = []
        for cond in cond_order:
            vals = df.loc[(df["group"] == grp) & (df["condition"] == cond), err_col].dropna().values
            data_per_cond.append(vals)
        bp = ax.boxplot(data_per_cond, positions=positions, widths=width * 0.85,
                        patch_artist=True, showfliers=False)
        for patch in bp["boxes"]:
            patch.set_facecolor(colors.get(grp, "gray"))
            patch.set_alpha(0.5)
        for ml in bp["medians"]:
            ml.set_color("black")
        for ci, cond in enumerate(cond_order):
            vals = df.loc[(df["group"] == grp) & (df["condition"] == cond), err_col].dropna().values
            if vals.size == 0:
                continue
            jitter = np.random.uniform(-width * 0.2, width * 0.2, size=vals.size)
            ax.scatter(np.full(vals.size, positions[ci]) + jitter, vals,
                       color=colors.get(grp, "gray"), s=25, zorder=5,
                       edgecolors="white", linewidths=0.5)

    method = str(use_scoring_method).strip().lower()
    ylabel = _euclidean_error_title(stat_label)
    if method == "rsquared":
        ylabel = f"{stat_label.capitalize()} R^2 (variance accounted for)"

    ax.set_xticks(x_base)
    ax.set_xticklabels([c.replace("_", "\n") for c in cond_order], fontsize=9)
    ax.set_ylabel(ylabel)
    ax.set_title(f"TFC 2D decoding — {session_str}")
    from matplotlib.patches import Patch
    legend_handles = [Patch(facecolor=colors[g], alpha=0.5, label=g) for g in group_order]
    ax.legend(handles=legend_handles, loc="upper left")
    ax.grid(True, alpha=0.15, axis="y")
    ax.spines["right"].set_visible(False); ax.spines["top"].set_visible(False)
    fig.tight_layout()
    fig.savefig(os.path.join(save_path, f"TFC_2D_boxplot_{stat_label}.png"), dpi=300)
    if auto_close:
        plt.close(fig)

# =============================================================================
# ====  RIDGE REGRESSION DECODER (2D position)  ==============================
# =============================================================================

class RidgeDecoder2D:
    """
    Ridge regression decoding for 2D position (open-field / TFC arenas).

    Segments neural activity into non-overlapping chunks of *time_bin_frames*
    and uses the **chunk-mean** activity of each neuron as features.  One
    Ridge model is fit for X and one for Y.

    For within-session accuracy the Pearson correlation between true and
    predicted positions is the primary metric; Euclidean error is also
    returned for compatibility with the Bayesian pipeline.
    """

    def __init__(self, time_bin_frames: int = 5, alpha: float = 1.0):
        self.time_bin_frames = int(time_bin_frames)
        self.alpha = float(alpha)
        self.reg_x = None
        self.reg_y = None
        self.dt_sec = None
        self.fitted = False

    # ------------------------------------------------------------------
    def _chunk(self, S, x, y, mask):
        """Return (idx_use, X_feat, true_x, true_y, K) or all-Nones."""
        w = self.time_bin_frames
        N, T = S.shape
        x = np.asarray(x, float)[:T]
        y = np.asarray(y, float)[:T]
        mask = np.asarray(mask, bool)[:T]
        idx_all = np.where(mask)[0]
        n = idx_all.size // w
        if n < 1:
            return None, None, None, None, None
        idx_use = idx_all[:n * w].reshape(n, w)
        X_feat  = np.mean(S[:, idx_use], axis=2).T   # (n, N)
        K       = np.sum(S[:, idx_use], axis=2).T    # (n, N) — for Ksum compat
        true_x  = np.mean(x[idx_use], axis=1)
        true_y  = np.mean(y[idx_use], axis=1)
        return idx_use, X_feat, true_x, true_y, K

    # ------------------------------------------------------------------
    def fit(self, S, x, y, mask, dt_sec):
        from sklearn.linear_model import Ridge
        S = np.asarray(S, float)
        _, X_feat, true_x, true_y, _ = self._chunk(S, x, y, mask)
        if X_feat is None or X_feat.shape[0] < 2:
            raise ValueError("Too few chunks to fit RidgeDecoder2D.")
        self.reg_x = Ridge(alpha=self.alpha).fit(X_feat, true_x)
        self.reg_y = Ridge(alpha=self.alpha).fit(X_feat, true_y)
        self.dt_sec = float(dt_sec)
        self.fitted = True

    # ------------------------------------------------------------------
    def decode(self, S, x, y, mask, **kwargs) -> Dict[str, Any]:
        from scipy.stats import pearsonr
        assert self.fitted, "Call fit() first."
        S = np.asarray(S, float)
        w, N = self.time_bin_frames, S.shape[0]
        idx_use, X_feat, true_x, true_y, K = self._chunk(S, x, y, mask)
        if X_feat is None or X_feat.shape[0] < 1:
            return {
                "decoded_x": np.array([]), "decoded_y": np.array([]),
                "true_x": np.array([]),    "true_y": np.array([]),
                "euclidean_err": np.array([]),
                "idx_use": np.zeros((0, w), dtype=int),
                "K": np.zeros((0, N)),     "Ksum": np.array([]),
                "pearson_r_x": np.nan,     "pearson_r_y": np.nan,
                "decode_mode": "ridge",
            }
        decoded_x = self.reg_x.predict(X_feat)
        decoded_y = self.reg_y.predict(X_feat)
        euclidean_err = np.sqrt((decoded_x - true_x) ** 2 +
                                (decoded_y - true_y) ** 2)
        r_x = pearsonr(true_x, decoded_x)[0] if true_x.size > 2 else np.nan
        r_y = pearsonr(true_y, decoded_y)[0] if true_y.size > 2 else np.nan
        return {
            "decoded_x": decoded_x,
            "decoded_y": decoded_y,
            "true_x": true_x,
            "true_y": true_y,
            "euclidean_err": euclidean_err,
            "idx_use": idx_use,
            "K": K,
            "Ksum": K.sum(axis=1),
            "pearson_r_x": float(r_x),
            "pearson_r_y": float(r_y),
            "decode_mode": "ridge",
        }


def _decoder_is_ridge(decoder_type: str) -> bool:
    """Return True if decoder_type requests ridge regression decoding."""
    dt = str(decoder_type).strip().lower()
    return dt in ("ridge", "ridge-regression", "ridge_regression")


# ---------------------------------------------------------------------------
#  Within-session 5-fold block CV for ridge regression
# ---------------------------------------------------------------------------

def _within_session_2D_cv_ridge(
    S, x, y, mask, dt_sec, *,
    time_bin_frames: int = 5,
    ridge_alpha: float = 1.0,
    block_min: float = 1.0,
    n_folds: int = 5,
) -> Dict[str, Any]:
    """
    5-fold block cross-validation for ridge 2D decoding within a session.

    The recording is split into non-overlapping blocks of *block_min* minutes.
    Blocks are randomly (but deterministically with seed=42) assigned to one
    of *n_folds* groups; each group serves as the held-out test set once.
    This mirrors the procedure described in Jennings et al. (2023) to prevent
    leakage between neighbouring frames.

    Returns a dict compatible with _within_session_2D_cv output:
        ok, pooled_euclidean_err, mean_err, median_err,
        pearson_r_x, pearson_r_y

    Also returns per-chunk traces for plotting helpers:
        true_x, true_y, decoded_x, decoded_y, idx_use
    """
    from sklearn.linear_model import Ridge
    from scipy.stats import pearsonr
    w = time_bin_frames
    N, T = S.shape
    x = np.asarray(x, float)[:T]
    y = np.asarray(y, float)[:T]
    mask = np.asarray(mask, bool)[:T]
    idx_all = np.where(mask)[0]
    n_chunks = idx_all.size // w
    if n_chunks < n_folds:
        return {"ok": False, "reason": "Too few chunks for ridge CV."}

    idx_use = idx_all[:n_chunks * w].reshape(n_chunks, w)
    X_feat  = np.mean(S[:, idx_use], axis=2).T   # (n_chunks, N)
    true_x  = np.mean(x[idx_use], axis=1)
    true_y  = np.mean(y[idx_use], axis=1)

    # Assign chunks to ~block_min-minute blocks, then randomly to folds
    chunks_per_min = max(1.0, (60.0 / dt_sec) / w)
    block_size = max(1, int(block_min * chunks_per_min))
    block_ids  = np.arange(n_chunks) // block_size
    n_blocks   = int(block_ids[-1]) + 1
    rng = np.random.RandomState(42)
    fold_of_block = rng.permutation(n_blocks) % n_folds
    chunk_fold    = fold_of_block[block_ids]

    all_decoded_x = np.full(n_chunks, np.nan)
    all_decoded_y = np.full(n_chunks, np.nan)
    for fold in range(n_folds):
        test_idx  = np.where(chunk_fold == fold)[0]
        train_idx = np.where(chunk_fold != fold)[0]
        if train_idx.size < 2 or test_idx.size < 1:
            continue
        reg_x = Ridge(alpha=ridge_alpha).fit(X_feat[train_idx], true_x[train_idx])
        reg_y = Ridge(alpha=ridge_alpha).fit(X_feat[train_idx], true_y[train_idx])
        all_decoded_x[test_idx] = reg_x.predict(X_feat[test_idx])
        all_decoded_y[test_idx] = reg_y.predict(X_feat[test_idx])

    valid = np.isfinite(all_decoded_x) & np.isfinite(all_decoded_y)
    euclidean_err = np.full(n_chunks, np.nan)
    euclidean_err[valid] = np.sqrt(
        (all_decoded_x[valid] - true_x[valid]) ** 2 +
        (all_decoded_y[valid] - true_y[valid]) ** 2)
    err_valid = euclidean_err[valid]
    r_x = pearsonr(true_x[valid], all_decoded_x[valid])[0] if valid.sum() > 2 else np.nan
    r_y = pearsonr(true_y[valid], all_decoded_y[valid])[0] if valid.sum() > 2 else np.nan
    return {
        "ok": True,
        "pooled_euclidean_err": err_valid if err_valid.size > 0 else np.array([]),
        "mean_err":   float(np.nanmean(err_valid))   if err_valid.size > 0 else np.nan,
        "median_err": float(np.nanmedian(err_valid)) if err_valid.size > 0 else np.nan,
        "pearson_r_x": float(r_x),
        "pearson_r_y": float(r_y),
        "true_x": true_x,
        "true_y": true_y,
        "decoded_x": all_decoded_x,
        "decoded_y": all_decoded_y,
        "idx_use": idx_use,
        "valid_mask": valid,
    }


# =============================================================================
# ====  GENERALIZED MULTI-TARGET 2D CROSS-SESSION DECODING  ==================
    colors = {"mCherry": "black", "hM3D": "red", "hM4D": "blue"}

    fig, ax = plt.subplots(figsize=(8, 6), dpi=150)

    # Prepare data
    conditions = [c for c in condition_order if c in df["condition"].values]
    n_cond = len(conditions)
    n_groups = len(group_order)
    width = 0.22
    x_base = np.arange(n_cond)

    for gi, grp in enumerate(group_order):
        positions = x_base + (gi - 1) * width
        data_per_cond = []
        for ci, cond in enumerate(conditions):
            vals = df.loc[(df["group"] == grp) & (df["condition"] == cond), err_col].dropna().values
            data_per_cond.append(vals)
        bp = ax.boxplot(
            data_per_cond,
            positions=positions,
            widths=width * 0.85,
            patch_artist=True,
            showfliers=False,
        )
        for patch in bp["boxes"]:
            patch.set_facecolor(colors.get(grp, "gray"))
            patch.set_alpha(0.5)
        for median_line in bp["medians"]:
            median_line.set_color("black")

        # Overlay individual mouse points
        for ci, cond in enumerate(conditions):
            vals = df.loc[(df["group"] == grp) & (df["condition"] == cond), err_col].dropna().values
            jitter = np.random.uniform(-width * 0.2, width * 0.2, size=vals.size)
            ax.scatter(np.full(vals.size, positions[ci]) + jitter, vals,
                       color=colors.get(grp, "gray"), s=30, zorder=5, edgecolors="white", linewidths=0.5)

    ax.set_xticks(x_base)
    ax.set_xticklabels([c.replace("_", " ") for c in conditions])
    ax.set_ylabel(_euclidean_error_title(stat_label))
    ax.set_title(f"2D Bayesian decoding — TFC pre-tone — {session_str}")

    # Legend
    from matplotlib.patches import Patch
    legend_handles = [Patch(facecolor=colors[g], alpha=0.5, label=g) for g in group_order]
    ax.legend(handles=legend_handles, loc="upper left")
    ax.grid(True, alpha=0.15, axis="y")
    ax.spines["right"].set_visible(False)
    ax.spines["top"].set_visible(False)
    fig.tight_layout()
    fig.savefig(os.path.join(save_path, f"TFC_2D_group_boxplot_{stat_label}.png"), dpi=300)
    plt.show()
    if auto_close:
        plt.close(fig)
    print(f"[TFC-2D-STATS] Boxplot saved.")


# =============================================================================
# ====  PLACE-FIELD-BASED 2D DECODER (uses precomputed rate maps from fm)  ====
# =============================================================================

class BayesianDecoder2D_PF:
    """
    2D Poisson MAP decoder that uses precomputed place-field GMM models
    (from FluorescenceMap.pf) as tuning curves.

    For each place cell, the fitted Bayesian GMM's probability density is
    evaluated at every spatial bin centre and scaled by the cell's mean
    in-field fluorescence rate.  This produces a smooth, Gaussian-shaped
    tuning curve centred on the detected place fields.

    An alternative ``fit_from_ratemap()`` is retained for backward
    compatibility: it simply uses the raw occupancy-corrected map.

    During decoding:
        log P(bx, by | K) ∝ Σ_i K_i · log λ_i(by, bx) − λ_i(by, bx) · dt · w
                            + log π(by, bx)
    """

    def __init__(
        self,
        time_bin_frames: int = 5,
        rate_smooth_eps: float = 1e-6,
        use_occupancy_prior: bool = True,
    ):
        self.time_bin_frames = int(time_bin_frames)
        self.rate_smooth_eps = float(rate_smooth_eps)
        self.use_occupancy_prior = bool(use_occupancy_prior)

        # set during fit_from_place_fields() or fit_from_ratemap()
        self.lam = None           # (N, Ny, Nx) events/sec
        self.log_prior = None     # (Ny, Nx)
        self.bin_width = None
        self.Ny = None
        self.Nx = None
        self.dt_sec = None
        self.fitted = False

    # ------------------------------------------------------------------
    def fit_from_place_fields(
        self,
        pf,                              # PlaceFields object
        fluorescence_map_occup,          # (Ny, Nx, n_fm_cells) occ-corrected rate map
        occupancy,                       # (Ny, Nx) in ms
        fm_cells: list,                  # fm.cells — cell indices into S
        cell_indices: list,              # which of fm_cells to use (indices into axis-2 of fm)
        dt_sec: Optional[float] = None,
        bin_width: Optional[float] = None,
        use_occupancy_fallback: bool = True,
    ):
        """
        Build tuning curves from the GMM place-field models.

        For each cell *c* in *cell_indices*:
            1. Look up ``pf.model_[s_idx]`` where s_idx = fm_cells[c]
               — this is the fitted BayesianGaussianMixture.
            2. Evaluate the GMM log-density at every (y_bin, x_bin) centre
               (in bin-index space, since the GMM was fit on bin indices).
            3. Convert to density and scale by the cell's max in-field
               fluorescence so the resulting λ values have the right
               magnitude.

        Falls back to the occupancy-corrected rate map for cells that
        have no GMM model (shouldn't happen if cell_indices is properly
        filtered to place cells).
        """
        fm = np.asarray(fluorescence_map_occup, dtype=float)
        occ = np.asarray(occupancy, dtype=float)
        Ny, Nx, _ = fm.shape
        N = len(cell_indices)

        self.Ny = Ny
        self.Nx = Nx
        self.bin_width = bin_width
        self.dt_sec = float(dt_sec) if dt_sec is not None else 1.0 / 20.0

        # Grid of bin-index centres for GMM evaluation
        # The GMM was fit on integer bin coordinates [y_bin, x_bin],
        # so we evaluate at the centre of each bin (integer values).
        y_coords = np.arange(Ny, dtype=float)   # 0, 1, 2, … Ny-1
        x_coords = np.arange(Nx, dtype=float)
        grid_y, grid_x = np.meshgrid(y_coords, x_coords, indexing='ij')  # (Ny, Nx)
        grid_points = np.column_stack([grid_y.ravel(), grid_x.ravel()])   # (Ny*Nx, 2)

        lam = np.full((N, Ny, Nx), self.rate_smooth_eps, dtype=float)

        for i, fm_idx in enumerate(cell_indices):
            s_idx = fm_cells[fm_idx]  # cell index into the session's S matrix

            if s_idx in pf.model_:
                gmm = pf.model_[s_idx]
                # score_samples returns log-density; convert to density
                log_dens = gmm.score_samples(grid_points)       # (Ny*Nx,)
                dens = np.exp(log_dens).reshape(Ny, Nx)         # (Ny, Nx)

                # Scale: make the peak of the GMM-derived tuning curve match
                # the peak of the occupancy-corrected rate map for this cell.
                # This preserves the correct firing-rate magnitude.
                peak_fm = np.max(fm[:, :, fm_idx])
                peak_dens = np.max(dens)
                if peak_dens > 0 and peak_fm > 0:
                    scale = peak_fm / peak_dens
                else:
                    scale = 1.0
                lam[i] = np.maximum(dens * scale, self.rate_smooth_eps)
            else:
                # Fallback: use the raw rate map for this cell
                if use_occupancy_fallback:
                    lam[i] = np.maximum(fm[:, :, fm_idx], self.rate_smooth_eps)
                # else: lam[i] stays at eps (cell effectively ignored)

        # Prior from occupancy
        if self.use_occupancy_prior:
            occ_safe = np.maximum(occ, 1.0)
            p = occ_safe / np.sum(occ_safe)
        else:
            p = np.ones((Ny, Nx), dtype=float) / (Ny * Nx)
        log_prior = np.log(np.maximum(p, 1e-12))

        self.lam = lam
        self.log_prior = log_prior
        self.fitted = True

    # ------------------------------------------------------------------
    def fit_from_ratemap(
        self,
        fluorescence_map_occup: np.ndarray,
        occupancy: np.ndarray,
        cell_indices: Optional[List[int]] = None,
        dt_sec: Optional[float] = None,
        bin_width: Optional[float] = None,
    ):
        """
        Build the decoder from the raw occupancy-corrected rate map
        (backward-compatible path — does NOT use GMM place fields).
        """
        fm = np.asarray(fluorescence_map_occup, dtype=float)   # (Ny, Nx, C)
        occ = np.asarray(occupancy, dtype=float)                # (Ny, Nx)

        if cell_indices is not None:
            fm = fm[:, :, cell_indices]

        Ny, Nx, N = fm.shape
        self.Ny = Ny
        self.Nx = Nx
        self.bin_width = bin_width
        self.dt_sec = float(dt_sec) if dt_sec is not None else 1.0 / 20.0

        # The rate map is already in units of (summed deconvolved signal per
        # occupancy-ms).  Convert occupancy to seconds for consistency, then
        # the product λ·dt gives expected counts per frame.
        # Actually, fluorescence_map_occup = Σ S / occupancy_frames  (occupancy
        # in the map is divided by frame count, not seconds).  The exact unit
        # depends on how FluorescenceMap.generate_occupancy_map normalised.
        # We treat the map values as *rates per frame* and multiply by
        # n_frames_in_chunk during decoding.  To be safe we just ensure
        # positive floor.
        lam = np.maximum(fm.transpose(2, 0, 1), self.rate_smooth_eps)  # (N, Ny, Nx)

        # Prior from occupancy
        if self.use_occupancy_prior:
            occ_safe = np.maximum(occ, 1.0)
            p = occ_safe / np.sum(occ_safe)
        else:
            p = np.ones((Ny, Nx), dtype=float) / (Ny * Nx)
        log_prior = np.log(np.maximum(p, 1e-12))

        self.lam = lam
        self.log_prior = log_prior
        self.fitted = True

    # ------------------------------------------------------------------
    def decode(
        self,
        S: np.ndarray,            # (N, T)
        loc_X: np.ndarray,        # (T,)  raw X position (pixels)
        loc_Y: np.ndarray,        # (T,)  raw Y position (pixels)
        mask: np.ndarray,         # (T,)
        use_posterior_mean: bool = True,
        use_continuity_constraint: bool = False,
        speed_vec: Optional[np.ndarray] = None,
        continuity_sigma_k: float = 60.0,
        continuity_speed_ref: float = 20.0,
        continuity_exp: float = 1.0,
        continuity_sigma_min: float = 20.0,
        continuity_sigma_max: float = 60.0,
        continuity_sigma_default: float = 30.0,
        save_posterior: bool = False,
    ) -> Dict[str, Any]:
        """
        Decode 2D position using Poisson MAP with precomputed rate maps.

        Positions are binned using ``int(loc / bin_width)`` to match the
        FluorescenceMap / Location_XY convention.

        Returns
        -------
        dict with decoded_x, decoded_y (in pixel-bin units × bin_width),
        true_x, true_y, euclidean_err, K, Ksum, idx_use.
        """
        assert self.fitted, "Call fit_from_place_fields() or fit_from_ratemap() first."

        S = np.asarray(S, dtype=float)
        loc_X = np.asarray(loc_X, dtype=float)
        loc_Y = np.asarray(loc_Y, dtype=float)
        mask = np.asarray(mask, dtype=bool)

        N, T = S.shape
        loc_X = loc_X[:T]; loc_Y = loc_Y[:T]; mask = mask[:T]

        Ny = self.Ny
        Nx = self.Nx
        dt = self.dt_sec
        w = int(self.time_bin_frames)

        # Flatten 2D grid
        B_flat = Ny * Nx
        lam_flat = self.lam.reshape(N, B_flat)            # (N, B_flat)
        log_lam_flat = np.log(lam_flat)                    # (N, B_flat)
        lam_dt_flat = lam_flat * dt * w                    # (N, B_flat)
        log_prior_flat = self.log_prior.reshape(B_flat)

        # Bin-centre coordinates (pixel units) — centres of integer bins
        bw = self.bin_width
        # bin index b corresponds to pixel range [b*bw, (b+1)*bw), centre = (b+0.5)*bw
        y_centers = (np.arange(Ny) + 0.5) * bw   # (Ny,)
        x_centers = (np.arange(Nx) + 0.5) * bw   # (Nx,)
        grid_y, grid_x = np.meshgrid(y_centers, x_centers, indexing='ij')  # (Ny, Nx)
        grid_y_flat = grid_y.ravel()
        grid_x_flat = grid_x.ravel()

        # Build time chunks
        idx_all = np.where(mask)[0]
        empty = {
            "decoded_x": np.array([]), "decoded_y": np.array([]),
            "true_x": np.array([]), "true_y": np.array([]),
            "decoded_bin_x": np.array([], dtype=int), "decoded_bin_y": np.array([], dtype=int),
            "true_bin_x": np.array([], dtype=int), "true_bin_y": np.array([], dtype=int),
            "K": np.zeros((0, N)), "Ksum": np.array([]),
            "idx_use": np.zeros((0, w), dtype=int),
            "euclidean_err": np.array([]),
            "frac_active": np.array([]),
            "posterior_entropy": np.array([]),
        }
        if idx_all.size < w:
            return empty

        n_chunks = idx_all.size // w
        idx_use = idx_all[:n_chunks * w].reshape(n_chunks, w)

        K = np.sum(S[:, idx_use], axis=2).T   # (n_chunks, N)
        Ksum = K.sum(axis=1)
        frac_active = (K > 0).mean(axis=1)  # fraction of cells active per chunk

        # Log posterior
        log_post = (K @ log_lam_flat) - np.sum(lam_dt_flat, axis=0)[None, :] + log_prior_flat[None, :]

        decoded_flat = np.argmax(log_post, axis=1)

        if use_continuity_constraint:
            if speed_vec is not None:
                speed_vec = np.asarray(speed_vec, dtype=float)[:T]
                chunk_speed = np.nanmean(np.abs(speed_vec[idx_use]), axis=1)
            else:
                chunk_speed = None

            def _sigma_from_speed(vt):
                if np.isfinite(vt):
                    vt = max(float(vt), 0.0)
                    sigma = continuity_sigma_k * (vt / max(float(continuity_speed_ref), 1e-9)) ** float(continuity_exp)
                else:
                    sigma = float(continuity_sigma_default)
                sigma = np.clip(sigma, float(continuity_sigma_min), float(continuity_sigma_max))
                return float(sigma)

            decoded_x_px = np.zeros(n_chunks, dtype=float)
            decoded_y_px = np.zeros(n_chunks, dtype=float)
            decoded_bin_x = np.zeros(n_chunks, dtype=int)
            decoded_bin_y = np.zeros(n_chunks, dtype=int)
            sigma_per_chunk = np.full(n_chunks, np.nan, dtype=float)
            posterior_entropy = np.zeros(n_chunks, dtype=float)
            if save_posterior:
                full_post = np.zeros((n_chunks, B_flat), dtype=np.float32)

            for t in range(n_chunks):
                lp_t = log_post[t].copy()

                if t > 0:
                    vt = np.nan
                    if chunk_speed is not None and t < chunk_speed.size:
                        vt = chunk_speed[t]
                    sigma_t = _sigma_from_speed(vt)
                    sigma_per_chunk[t] = sigma_t

                    dx = grid_x_flat - decoded_x_px[t - 1]
                    dy = grid_y_flat - decoded_y_px[t - 1]
                    lp_t += -(dx * dx + dy * dy) / (2.0 * sigma_t * sigma_t)
                else:
                    sigma_per_chunk[t] = np.nan

                # Normalised posterior for decoding + entropy
                lp_t_s = lp_t - np.max(lp_t)
                post_t = np.exp(lp_t_s)
                post_t /= max(np.sum(post_t), 1e-12)
                posterior_entropy[t] = -np.sum(post_t * np.log(post_t + 1e-12))
                if save_posterior:
                    full_post[t] = post_t.astype(np.float32)

                if use_posterior_mean:
                    decoded_x_px[t] = np.sum(post_t * grid_x_flat)
                    decoded_y_px[t] = np.sum(post_t * grid_y_flat)
                    decoded_bin_x[t] = np.clip(int(decoded_x_px[t] / bw), 0, Nx - 1)
                    decoded_bin_y[t] = np.clip(int(decoded_y_px[t] / bw), 0, Ny - 1)
                else:
                    b = int(np.argmax(lp_t))
                    decoded_x_px[t] = grid_x_flat[b]
                    decoded_y_px[t] = grid_y_flat[b]
                    decoded_bin_y[t] = b // Nx
                    decoded_bin_x[t] = b % Nx

            decode_mode = "posterior_mean+continuity" if use_posterior_mean else "map+continuity"
        else:
            if use_posterior_mean:
                log_post_shift = log_post - np.max(log_post, axis=1, keepdims=True)
                post = np.exp(log_post_shift)
                post_sum = np.sum(post, axis=1, keepdims=True)
                post_sum = np.maximum(post_sum, 1e-12)
                post /= post_sum
                decoded_x_px = post @ grid_x_flat
                decoded_y_px = post @ grid_y_flat
                decoded_bin_x = np.clip((decoded_x_px / bw).astype(int), 0, Nx - 1)
                decoded_bin_y = np.clip((decoded_y_px / bw).astype(int), 0, Ny - 1)
                posterior_entropy = -np.sum(post * np.log(post + 1e-12), axis=1)
                decode_mode = "posterior_mean"
            else:
                log_post_shift = log_post - np.max(log_post, axis=1, keepdims=True)
                post = np.exp(log_post_shift)
                post /= np.maximum(np.sum(post, axis=1, keepdims=True), 1e-12)
                posterior_entropy = -np.sum(post * np.log(post + 1e-12), axis=1)
                decoded_x_px = grid_x_flat[decoded_flat]
                decoded_y_px = grid_y_flat[decoded_flat]
                decoded_bin_y = decoded_flat // Nx
                decoded_bin_x = decoded_flat % Nx
                decode_mode = "map"

        # True position per chunk (mean of raw pixel positions)
        true_x_px = np.mean(loc_X[idx_use], axis=1)
        true_y_px = np.mean(loc_Y[idx_use], axis=1)
        true_bin_x = np.clip((true_x_px / bw).astype(int), 0, Nx - 1)
        true_bin_y = np.clip((true_y_px / bw).astype(int), 0, Ny - 1)

        euclidean_err = np.sqrt((decoded_x_px - true_x_px)**2 +
                                (decoded_y_px - true_y_px)**2)

        result = {
            "decoded_x": decoded_x_px,
            "decoded_y": decoded_y_px,
            "decoded_bin_x": decoded_bin_x,
            "decoded_bin_y": decoded_bin_y,
            "true_x": true_x_px,
            "true_y": true_y_px,
            "true_bin_x": true_bin_x,
            "true_bin_y": true_bin_y,
            "K": K,
            "Ksum": Ksum,
            "idx_use": idx_use,
            "euclidean_err": euclidean_err,
            "decode_mode": decode_mode,
            "frac_active": frac_active,
            "posterior_entropy": posterior_entropy,
        }
        if save_posterior:
            if use_continuity_constraint:
                result["posterior"] = full_post
            else:
                result["posterior"] = post.astype(np.float32)
            result["grid_x_flat"] = grid_x_flat
            result["grid_y_flat"] = grid_y_flat
        return result

    @staticmethod
    def euclidean_error(decoded_x, decoded_y, true_x, true_y):
        return np.sqrt((np.asarray(decoded_x) - np.asarray(true_x))**2 +
                       (np.asarray(decoded_y) - np.asarray(true_y))**2)


# ---------------------------------------------------------------------------
#  Cross-session 2D TFC_cond → Test_B using precomputed place-field rate maps
# ---------------------------------------------------------------------------

def decode_TFC_to_TestB_2D_PF(
    TFC,
    TestB,
    *,
    mapping: str = "TFC_cond+Test_B",
    time_bin_frames: int = 5,
    use_posterior_mean: bool = True,
    use_speed: bool = True,
    min_speed: float = 2.0,
    first_n_sec: float = 180.0,
    place_cells_only: bool = True,
    use_pf_num: int = -1,
    use_occupancy_fallback: bool = True,
    use_z_score: str = "none",
) -> Dict[str, Any]:
    """
    Train a 2D Bayesian decoder using the precomputed place-field rate maps
    from TFC_cond (sess.fm), then decode Test_B pre-tone activity using
    cross-registered cells.

    Parameters
    ----------
    TFC : TraceFearCondSession
        Must have .fm (FluorescenceMap) attached.
    TestB : TestBSession
    mapping : str
    time_bin_frames : int
    use_speed : bool
    min_speed : float
    first_n_sec : float
    place_cells_only : bool
        If True, restrict to cells with significant place fields
        (i.e., cells present in TFC.fm.sig_responses).

    Returns
    -------
    dict with ok, out, euclidean_err, within_TFC, etc.
    """

    # --- Validate that TFC has fluorescence map and place fields ---
    if not hasattr(TFC, 'fm') or TFC.fm is None:
        return {"ok": False, "reason": "TFC session has no FluorescenceMap (.fm) attached."}
    fm = TFC.fm
    if fm.fluorescence_map_occup is None:
        return {"ok": False, "reason": "TFC.fm.fluorescence_map_occup is None."}
    if not hasattr(fm, 'pf') or fm.pf is None:
        return {"ok": False, "reason": "TFC.fm has no PlaceFields (.pf). Run find_place_fields() first."}
    if not hasattr(TFC, 'loc') or TFC.loc is None:
        return {"ok": False, "reason": "TFC session has no Location_XY (.loc) attached."}

    # --- Cross-registration ---
    crossreg = TestB.crossreg
    try:
        df_mapping = crossreg.get_mappings_cells(mapping_type=mapping)
    except KeyError:
        return {"ok": False, "reason": f"Mapping '{mapping}' not found in cross-registration."}

    col_TFC = TFC.get_df_col(with_crossreg=crossreg)
    col_TestB = TestB.get_df_col(with_crossreg=crossreg)

    cells_TFC_ids = df_mapping[col_TFC].astype(float).astype(int).tolist()
    cells_TestB_ids = df_mapping[col_TestB].astype(float).astype(int).tolist()

    # Get S matrices for cross-registered cells
    S_tfc, _ = get_mapped_S_from_unit_ids(TFC, cells_TFC_ids)
    S_testb, _ = get_mapped_S_from_unit_ids(TestB, cells_TestB_ids)

    if S_tfc.shape[0] == 0 or S_testb.shape[0] == 0:
        return {"ok": False, "reason": "No cross-registered cells found."}

    n = min(S_tfc.shape[0], S_testb.shape[0])
    S_tfc = S_tfc[:n]
    S_testb = S_testb[:n]
    cells_TFC_ids = cells_TFC_ids[:n]

    # --- Map cross-registered TFC cell unit-IDs to indices into fm ---
    # fm.cells is the list of cell indices (into TFC.S) that were used to
    # build the fluorescence map.  We need to find which of our cross-
    # registered cells appear in fm.cells.
    fm_cells_list = list(fm.cells) if fm.cells is not None else []
    tfc_S_indices = TFC.get_S_indeces(cells_TFC_ids)  # indices into TFC.S

    # Build mapping: for each cross-reg cell, find its index in fm.cells
    keep_mask = []
    fm_cell_indices = []
    for i, s_idx in enumerate(tfc_S_indices):
        if s_idx in fm_cells_list:
            fm_idx = fm_cells_list.index(s_idx)
            # If place_cells_only, further check if this cell has sig responses
            if place_cells_only:
                if not (fm.sig_responses is not None and s_idx in fm.sig_responses):
                    continue
            # PF number / occupancy-fallback filter
            if use_pf_num >= 1:
                if s_idx not in fm.pf.model_:
                    continue
                n_merged_pf = len(fm.pf.merged_means.get(s_idx, []))
                if n_merged_pf == 0 or n_merged_pf > use_pf_num:
                    continue
            elif not use_occupancy_fallback:
                if s_idx not in fm.pf.model_:
                    continue
            keep_mask.append(i)
            fm_cell_indices.append(fm_idx)

    if len(keep_mask) == 0:
        return {"ok": False, "reason": "No cross-registered cells found in the fluorescence map."}

    # Subset S matrices to only kept cells
    S_tfc_kept = S_tfc[keep_mask]
    S_testb_kept = S_testb[keep_mask]
    n_cells_used = len(keep_mask)

    # Optional per-neuron z-scoring policy.
    S_tfc_kept, S_testb_kept = _apply_zscore_pair(S_tfc_kept, S_testb_kept, use_z_score)

    dist_meta = _validate_2d_decoder_distance_meta(TFC, TestB)
    pos_scale = float(dist_meta["scale"])

    # --- Build decoder from GMM place-field models ---
    rate_map = fm.fluorescence_map_occup         # (Ny, Nx, n_fm_cells)
    occupancy = TFC.loc.occupancy                # (Ny, Nx)
    bin_width = float(TFC.loc.bin_width) * pos_scale
    dt_tfc = _infer_dt_sec(TFC)
    dt_testb = _infer_dt_sec(TestB)

    dec = BayesianDecoder2D_PF(time_bin_frames=time_bin_frames)
    dec.fit_from_place_fields(
        fm.pf, rate_map, occupancy,
        fm_cells=fm_cells_list,
        cell_indices=fm_cell_indices,
        dt_sec=dt_tfc,
        bin_width=bin_width,
        use_occupancy_fallback=use_occupancy_fallback,
    )

    # --- Positions ---
    x_tfc = _scale_2d_position_array(TFC.loc_X_miniscope_smooth, pos_scale)[:S_tfc_kept.shape[1]]
    y_tfc = _scale_2d_position_array(TFC.loc_Y_miniscope_smooth, pos_scale)[:S_tfc_kept.shape[1]]
    x_testb = _scale_2d_position_array(TestB.loc_X_miniscope_smooth, pos_scale)[:S_testb_kept.shape[1]]
    y_testb = _scale_2d_position_array(TestB.loc_Y_miniscope_smooth, pos_scale)[:S_testb_kept.shape[1]]

    # --- Pre-tone masks ---
    mask_tfc = build_pretone_mask_TFC(TFC, first_n_sec=first_n_sec,
                                       use_speed=use_speed, min_speed=min_speed)[:S_tfc_kept.shape[1]]
    mask_testb = build_pretone_mask_TFC(TestB, first_n_sec=first_n_sec,
                                         use_speed=use_speed, min_speed=min_speed)[:S_testb_kept.shape[1]]

    if np.sum(mask_tfc) < time_bin_frames or np.sum(mask_testb) < time_bin_frames:
        return {"ok": False, "reason": "Insufficient pre-tone frames after masking."}

    # --- Decode Test_B pre-tone ---
    out = dec.decode(
        S_testb_kept, x_testb, y_testb, mask_testb,
        use_posterior_mean=use_posterior_mean)
    out = _annotate_2d_decode_output(out, dist_meta)
    euclidean_err = out["euclidean_err"]

    # --- Within-session TFC CV (using same GMM PF models but splitting time) ---
    within_result = _within_session_2D_PF_cv(
        S_tfc_kept, x_tfc, y_tfc, mask_tfc, dt_tfc,
        pf=fm.pf,
        rate_map=rate_map,
        occupancy=occupancy,
        fm_cells=fm_cells_list,
        fm_cell_indices=fm_cell_indices,
        bin_width=bin_width,
        time_bin_frames=time_bin_frames,
        use_posterior_mean=use_posterior_mean,
        use_pf_num=use_pf_num,
        use_occupancy_fallback=use_occupancy_fallback,
        position_unit=dist_meta["unit"],
        position_scale=pos_scale,
    )

    return {
        "ok": True,
        "out": out,
        "euclidean_err": euclidean_err,
        "n_cells_mapped": int(n_cells_used),
        "n_cells_crossreg_total": int(n),
        "dt_train": float(dt_tfc),
        "dt_test": float(dt_testb),
        "n_pretone_frames_tfc": int(np.sum(mask_tfc)),
        "n_pretone_frames_testb": int(np.sum(mask_testb)),
        "within_TFC": within_result,
        "place_cells_only": place_cells_only,
        "position_unit": dist_meta["unit"],
        "position_scale": pos_scale,
    }


def _within_session_2D_PF_cv(
    S, loc_X, loc_Y, mask, dt_sec, *,
    pf, rate_map, occupancy, fm_cells, fm_cell_indices, bin_width,
    time_bin_frames=5,
    use_posterior_mean: bool = True,
    use_pf_num: int = -1,
    use_occupancy_fallback: bool = True,
    use_continuity_constraint: bool = False,
    speed_vec: Optional[np.ndarray] = None,
    continuity_sigma_k: float = 60.0,
    continuity_speed_ref: float = 20.0,
    continuity_exp: float = 1.0,
    continuity_sigma_min: float = 20.0,
    continuity_sigma_max: float = 60.0,
    continuity_sigma_default: float = 30.0,
    position_unit: str = "px",
    position_scale: float = 1.0,
) -> Dict[str, Any]:
    """
    Within-session CV using GMM place-field models.
    Splits masked frames into even/odd 10 s blocks for test sets;
    the tuning curve (derived from the GMM PF models) is always the
    same precomputed one.
    """
    T = S.shape[1]
    block_size = max(1, int(10.0 / dt_sec))

    idx_all = np.where(mask)[0]
    if idx_all.size < 2 * time_bin_frames:
        return {"ok": False, "reason": "Too few masked frames for CV."}

    block_id = idx_all // block_size
    even_mask = np.zeros(T, dtype=bool)
    odd_mask = np.zeros(T, dtype=bool)
    even_mask[idx_all[block_id % 2 == 0]] = True
    odd_mask[idx_all[block_id % 2 == 1]] = True

    dec = BayesianDecoder2D_PF(time_bin_frames=time_bin_frames)
    dec.fit_from_place_fields(pf, rate_map, occupancy,
                         fm_cells=fm_cells,
                         cell_indices=fm_cell_indices,
                         dt_sec=dt_sec, bin_width=bin_width,
                         use_occupancy_fallback=use_occupancy_fallback)

    results = {}
    for label, test_m in [("even", even_mask), ("odd", odd_mask)]:
        out = dec.decode(
            S, loc_X, loc_Y, test_m,
            use_posterior_mean=use_posterior_mean,
            use_continuity_constraint=use_continuity_constraint,
            speed_vec=speed_vec,
            continuity_sigma_k=continuity_sigma_k,
            continuity_speed_ref=continuity_speed_ref,
            continuity_exp=continuity_exp,
            continuity_sigma_min=continuity_sigma_min,
            continuity_sigma_max=continuity_sigma_max,
            continuity_sigma_default=continuity_sigma_default)
        out = _annotate_2d_decode_output(out, {
            "unit": position_unit,
            "scale": position_scale,
            "px_distance": np.nan,
            "true_distance": np.nan,
        })
        results[label] = {
            "out": out,
            "euclidean_err": out["euclidean_err"],
        }

    err_parts = [results[k]["euclidean_err"] for k in results
                 if results[k]["euclidean_err"].size > 0]
    if err_parts:
        results["pooled_euclidean_err"] = np.concatenate(err_parts)
        results["mean_err"] = float(np.nanmean(results["pooled_euclidean_err"]))
        results["median_err"] = float(np.nanmedian(results["pooled_euclidean_err"]))
    else:
        results["pooled_euclidean_err"] = np.array([])
        results["mean_err"] = np.nan
        results["median_err"] = np.nan
    results["ok"] = True
    results["position_unit"] = position_unit
    results["position_scale"] = float(position_scale)
    return results


# ---------------------------------------------------------------------------
#  Master pipeline: PF-based 2D decoding for all mice
# ---------------------------------------------------------------------------

def run_TFC_2D_PF_decoding_all_mice(
    TFC_cond_group: dict,
    Test_B_group: dict,
    *,
    mapping: str = "TFC_cond+Test_B",
    time_bin_frames: int = 5,
    use_posterior_mean: bool = True,
    use_speed: bool = True,
    min_speed: float = 2.0,
    first_n_sec: float = 180.0,
    place_cells_only: bool = True,
    use_pf_num: int = -1,
    use_occupancy_fallback: bool = True,
    use_z_score: str = "none",
    PLOTS_DIR: str = "",
    session_str: str = "TFC_2D_PF",
    mouse_groups: dict = None,
    plot_debug: bool = True,
    auto_close: bool = True,
) -> dict:
    """
    Runs place-field-based 2D Bayesian decoding for all mice:
      1) Within-session CV on TFC_cond pre-tone (rate maps from fm)
      2) Cross-session TFC_cond → Test_B (pre-tone, cross-registered cells)

    Requires that each TFC session has .fm and .loc already attached
    (via plot_fluorescence_map / get_fluorescence_map in the main pipeline).
    """
    if mouse_groups is None:
        mouse_groups = {}

    save_path = os.path.join(PLOTS_DIR,
                             f"bayes_2D_PF_{session_str}_mapping_{mapping}_{_z_score_dir_tag(use_z_score)}")
    os.makedirs(save_path, exist_ok=True)

    pf_str = "pcells" if place_cells_only else "allcells"
    all_results = {}
    mice = sorted(set(TFC_cond_group.keys()) & set(Test_B_group.keys()))

    for mouse in mice:
        TFC = TFC_cond_group[mouse]
        TB = Test_B_group[mouse]
        group = mouse_groups.get(mouse, "NA")

        print(f"[2D-PF-DECODE] {mouse} ({group}) [{pf_str}] ...")

        res = decode_TFC_to_TestB_2D_PF(
            TFC, TB,
            mapping=mapping,
            time_bin_frames=time_bin_frames,
            use_posterior_mean=use_posterior_mean,
            use_speed=use_speed,
            min_speed=min_speed,
            first_n_sec=first_n_sec,
            place_cells_only=place_cells_only,
            use_pf_num=use_pf_num,
            use_occupancy_fallback=use_occupancy_fallback,
            use_z_score=use_z_score,
        )

        all_results[mouse] = res

        if not res.get("ok", False):
            print(f"  [SKIP] {mouse}: {res.get('reason', '?')}")
            continue

        unit_label = res.get("position_unit", _TFC_TEST_2D_DISTANCE_UNIT)

        print(f"  n_cells_PF={res['n_cells_mapped']}  "
              f"n_cells_xreg={res['n_cells_crossreg_total']}  "
              f"pretone_tfc={res['n_pretone_frames_tfc']}  "
              f"pretone_testb={res['n_pretone_frames_testb']}  "
              f"median_err_xfer={np.nanmedian(res['euclidean_err']):.1f}{unit_label}")

        # --- Per-mouse diagnostic plots ---
        tag_base = f"{mouse}_{group}_{session_str}_{pf_str}"

        # 1) Error histogram (cross-session)
        fig, ax = plt.subplots(figsize=(8, 5), dpi=150)
        ax.hist(res["euclidean_err"], bins=50, color="darkorange", alpha=0.8)
        ax.set_xlabel(_euclidean_error_axis_label())
        ax.set_ylabel("Count")
        ax.set_title(f"{mouse} {group} — TFC→TestB 2D-PF ({pf_str})")
        ax.axvline(np.nanmedian(res["euclidean_err"]), color="red", ls="--",
                    label=f"median={np.nanmedian(res['euclidean_err']):.1f}")
        ax.legend()
        fig.tight_layout()
        fig.savefig(os.path.join(save_path, f"{tag_base}_xfer_errhist.png"), dpi=300)
        if plot_debug:
            plt.show()
        if auto_close:
            plt.close(fig)

        # 2) Decoded vs true scatter
        out = res["out"]
        fig, axes = plt.subplots(1, 2, figsize=(12, 5), dpi=150)
        for ax, true, dec_pos, label in [
            (axes[0], out["true_x"], out["decoded_x"], "X"),
            (axes[1], out["true_y"], out["decoded_y"], "Y"),
        ]:
            ax.scatter(true, dec_pos, s=6, alpha=0.3)
            lo = min(np.nanmin(true), np.nanmin(dec_pos))
            hi = max(np.nanmax(true), np.nanmax(dec_pos))
            ax.plot([lo, hi], [lo, hi], "r-", lw=1.5)
            ax.set_xlabel(f"True {label} ({unit_label})")
            ax.set_ylabel(f"Decoded {label} ({unit_label})")
            ax.set_title(f"{mouse} {group} — TFC→TestB PF {label}")
            ax.grid(True, alpha=0.2)
        fig.tight_layout()
        fig.savefig(os.path.join(save_path, f"{tag_base}_xfer_scatter_XY.png"), dpi=300)
        if plot_debug:
            plt.show()
        if auto_close:
            plt.close(fig)

        # 3) 2D trajectory overlay
        fig, ax = plt.subplots(figsize=(7, 7), dpi=150)
        ax.plot(out["true_x"], out["true_y"], "k-", alpha=0.15, lw=0.5, label="true")
        ax.scatter(out["decoded_x"], out["decoded_y"], c=res["euclidean_err"],
                   s=10, alpha=0.6, cmap="hot", vmin=0,
                   vmax=np.nanpercentile(res["euclidean_err"], 95))
        cb = plt.colorbar(ax.collections[-1], ax=ax, pad=0.02)
        cb.set_label(f"Eucl. error ({unit_label})")
        ax.set_xlabel(_xy_axis_label("X")); ax.set_ylabel(_xy_axis_label("Y"))
        ax.set_title(f"{mouse} {group} — TFC→TestB PF traj ({pf_str})")
        ax.set_aspect("equal")
        fig.tight_layout()
        fig.savefig(os.path.join(save_path, f"{tag_base}_xfer_traj2D.png"), dpi=300)
        if plot_debug:
            plt.show()
        if auto_close:
            plt.close(fig)

        # 4) Within-TFC CV
        within = res.get("within_TFC", {})
        if within.get("ok", False):
            w_err = within.get("pooled_euclidean_err", np.array([]))
            if w_err.size > 0:
                fig, ax = plt.subplots(figsize=(8, 5), dpi=150)
                ax.hist(w_err, bins=50, color="teal", alpha=0.8)
                ax.set_xlabel(_euclidean_error_axis_label())
                ax.set_ylabel("Count")
                ax.set_title(f"{mouse} {group} — within-TFC 2D-PF CV ({pf_str})")
                ax.axvline(np.nanmedian(w_err), color="red", ls="--",
                            label=f"median={np.nanmedian(w_err):.1f}")
                ax.legend()
                fig.tight_layout()
                fig.savefig(os.path.join(save_path,
                            f"{tag_base}_withinTFC_errhist.png"), dpi=300)
                if plot_debug:
                    plt.show()
                if auto_close:
                    plt.close(fig)

    print(f"[2D-PF-DECODE] Done. {len(all_results)} mice processed, "
          f"{sum(1 for v in all_results.values() if v.get('ok'))} succeeded.")
    return all_results


# ---------------------------------------------------------------------------
#  Stats & plots for PF-based 2D decoder
# ---------------------------------------------------------------------------

def run_TFC_2D_PF_stats_and_plots(
    dec_results_2D_PF: dict,
    mouse_groups: dict,
    PLOTS_DIR: str,
    session_str: str = "TFC_2D_PF",
    mapping: str = "TFC_cond+Test_B",
    use_scoring_method: str = "euclidean",
    use_median: bool = True,
    auto_close: bool = True,
    pct_threshold: float = 15.0,
    stat_label_override=None,
):
    """
    Reuses build_TFC_2D_summary_dataframe and _plot_TFC_2D_group_boxplot
    for the PF-based results (same output dict structure).
    """
    methods = _normalize_scoring_methods(use_scoring_method)
    if len(methods) > 1:
        out = {}
        print("[TFC-2D-PF-STATS] Running both scoring methods: euclidean + rsquared")
        for method in methods:
            out[method] = run_TFC_2D_PF_stats_and_plots(
                dec_results_2D_PF,
                mouse_groups,
                PLOTS_DIR,
                session_str=session_str,
                mapping=mapping,
                use_scoring_method=method,
                use_median=use_median,
                auto_close=auto_close,
                pct_threshold=pct_threshold,
                stat_label_override=stat_label_override,
            )
        return out

    use_scoring_method = methods[0]
    stat_label = stat_label_override if stat_label_override else ("median" if use_median else "mean")
    score_tag = str(use_scoring_method).strip().lower()
    save_path = os.path.join(PLOTS_DIR,
                             f"TFC_2D_PF_stats_{session_str}_mapping_{mapping}_{stat_label}_score_{score_tag}")
    os.makedirs(save_path, exist_ok=True)

    df = build_TFC_2D_summary_dataframe(dec_results_2D_PF, mouse_groups,
                                         use_scoring_method=use_scoring_method,
                                         pct_threshold=pct_threshold)
    df.to_csv(os.path.join(save_path, "TFC_2D_PF_mouse_summary.csv"), index=False)
    print(f"[TFC-2D-PF-STATS] Summary table ({len(df)} rows):")
    print(df.to_string(index=False))

    err_col = "pct_correct" if stat_label == "pct" else f"{stat_label}_err"

    model_result = None
    df_model = df[np.isfinite(df[err_col])].copy()
    if len(df_model) > 3 and df_model["condition"].nunique() > 1:
        df_model["group"] = df_model["group"].astype("category")
        df_model["condition"] = df_model["condition"].astype("category")
        try:
            md = smf.mixedlm(f"{err_col} ~ group * condition", df_model,
                             groups=df_model["mouse"])
            model_result = md.fit(reml=False)
            with open(os.path.join(save_path,
                      f"mixedlm_{stat_label}_err.txt"), "w") as f:
                f.write(str(model_result.summary()))
            print(f"[TFC-2D-PF-STATS] MixedLM saved.")
        except Exception as e:
            print(f"[TFC-2D-PF-STATS] MixedLM failed: {e}")

    model_xfer = None
    df_xfer = df_model[df_model["condition"] == "TFC_to_TestB"].copy()
    if len(df_xfer) >= 3 and df_xfer["group"].nunique() > 1:
        try:
            md2 = smf.mixedlm(f"{err_col} ~ group", df_xfer,
                               groups=df_xfer["mouse"])
            model_xfer = md2.fit(reml=False)
            with open(os.path.join(save_path,
                      f"mixedlm_{stat_label}_err_xfer_only.txt"), "w") as f:
                f.write(str(model_xfer.summary()))
        except Exception as e:
            print(f"[TFC-2D-PF-STATS] MixedLM (xfer-only) failed: {e}")

    _plot_TFC_2D_group_boxplot(df, err_col, save_path, session_str + "_PF",
                                stat_label, use_scoring_method=use_scoring_method,
                                auto_close=auto_close)

    return df, model_result, model_xfer


# =============================================================================
# ====  GENERALIZED MULTI-TARGET 2D CROSS-SESSION DECODING  ==================
# =============================================================================

def _make_pair_mapping(type_a: str, type_b: str) -> str:
    """Construct the '+'-joined mapping string from two session type labels."""
    return "+".join(sorted([type_a, type_b]))


# ---------------------------------------------------------------------------
#  Generalized 2D cross-session decode (raw-S-based)
# ---------------------------------------------------------------------------

def _collect_crossreg_candidates(sess_a, sess_b):
    """
    Gather all unique crossreg objects from both sessions, checking
    .crossreg (primary) and .crossreg_full (5-session fallback).
    """
    seen = set()
    out = []
    for attr in ('crossreg', 'crossreg_full'):
        for sess in (sess_a, sess_b):
            c = getattr(sess, attr, None)
            if c is not None and id(c) not in seen:
                seen.add(id(c))
                out.append(c)
    return out


def _find_crossreg_with_mapping(sess_a, sess_b, mapping: str):
    """
    Search both sessions' crossreg objects for one that contains *mapping*.
    Returns (crossreg, df_mapping) or (None, None).
    """
    for candidate in _collect_crossreg_candidates(sess_a, sess_b):
        try:
            df = candidate.get_mappings_cells(mapping_type=mapping)
            return candidate, df
        except (KeyError, Exception):
            continue
    return None, None


def _stable_seed_from_text(text: str) -> int:
    """Deterministic small integer hash for reproducible RNG seeding."""
    acc = 0
    for i, ch in enumerate(str(text)):
        acc = (acc + (i + 1) * ord(ch)) % 2147483647
    return int(acc)


def _test_n_available_by_group(df_summary: "pd.DataFrame", save_dir: str,
                               label: str = "") -> None:
    """Test whether n_available differs across DREADD groups.

    Runs Kruskal-Wallis (+ pairwise Mann-Whitney U) on the unique
    mouse-level n_available, both per-target and pooled (mean across
    targets per mouse).  Results are printed and saved to
    ``<save_dir>/n_available_by_group.txt``.
    """
    from scipy import stats as sp_stats
    import itertools

    if df_summary is None or df_summary.empty:
        return
    needed = {"mouse", "group", "n_available"}
    if not needed.issubset(df_summary.columns):
        return

    lines: list[str] = []
    lines.append(f"=== n_available ~ DREADD group{f' ({label})' if label else ''} ===\n")

    def _run_tests(df_in: "pd.DataFrame", section: str) -> None:
        uniq = df_in.drop_duplicates(subset=["mouse"])[["mouse", "group", "n_available"]].copy()
        uniq["n_available"] = pd.to_numeric(uniq["n_available"], errors="coerce")
        uniq = uniq.dropna(subset=["n_available"])
        groups = sorted(uniq["group"].unique().tolist())
        if len(groups) < 2:
            lines.append(f"  {section}: <2 groups, skipping.\n")
            return

        lines.append(f"--- {section} ---")
        for g in groups:
            vals = uniq.loc[uniq["group"] == g, "n_available"]
            lines.append(f"  {g:10s}: n={len(vals)}, mean={vals.mean():.1f}, "
                         f"median={vals.median():.1f}, sd={vals.std():.1f}, "
                         f"range=[{vals.min():.0f}, {vals.max():.0f}]")

        arrays = [uniq.loc[uniq["group"] == g, "n_available"].to_numpy() for g in groups]
        try:
            H, p_kw = sp_stats.kruskal(*arrays)
        except ValueError:
            H, p_kw = float("nan"), float("nan")
        lines.append(f"  Kruskal-Wallis H={H:.3f}, p={p_kw:.4f}")

        for g1, g2 in itertools.combinations(groups, 2):
            a1 = uniq.loc[uniq["group"] == g1, "n_available"].to_numpy()
            a2 = uniq.loc[uniq["group"] == g2, "n_available"].to_numpy()
            try:
                U, p_mw = sp_stats.mannwhitneyu(a1, a2, alternative="two-sided")
            except ValueError:
                U, p_mw = float("nan"), float("nan")
            lines.append(f"    {g1} vs {g2}: U={U:.0f}, p={p_mw:.4f}")
        lines.append("")

    # Per-target tests
    if "target" in df_summary.columns:
        for tgt in sorted(df_summary["target"].dropna().unique().tolist()):
            df_t = df_summary[df_summary["target"] == tgt]
            _run_tests(df_t, section=f"Target: {tgt}")

    # Pooled: mean n_available across targets per mouse
    pooled = (df_summary.drop_duplicates(subset=["mouse", "target"])
              .groupby(["mouse", "group"], as_index=False)["n_available"]
              .mean())
    _run_tests(pooled, section="Pooled (mean n_available across targets)")

    text = "\n".join(lines)
    print(text)
    out_path = os.path.join(save_dir, "n_available_by_group.txt")
    with open(out_path, "w") as fh:
        fh.write(text)
    print(f"[POP-CURVE] n_available group test saved: {out_path}")

    # ---- Plot: n_available by group (per-target + pooled) ----
    try:
        _colors = {"mCherry": "#4a4a4a", "hM3D": "#c45a5a", "hM4D": "#5b8db8"}
        _dot_colors = {"mCherry": "#7a7a7a", "hM3D": "#d98e8e", "hM4D": "#8fb5d5"}
        _labels = {"mCherry": "Control", "hM3D": "Excitatory", "hM4D": "Inhibitory"}
        _box_alpha = 0.30

        targets = sorted(df_summary["target"].dropna().unique().tolist()) if "target" in df_summary.columns else []
        panels = targets + ["Pooled"]
        n_panels = len(panels)

        fig, axes = plt.subplots(1, n_panels, figsize=(3.0 * n_panels, 4.0), dpi=150,
                                 sharey=True, squeeze=False)
        axes = axes.ravel()

        group_order = sorted(pooled["group"].unique().tolist())

        for ax_i, panel_name in enumerate(panels):
            ax = axes[ax_i]
            if panel_name == "Pooled":
                df_plot = pooled.copy()
            else:
                df_plot = (df_summary[df_summary["target"] == panel_name]
                           .drop_duplicates(subset=["mouse"])[["mouse", "group", "n_available"]].copy())
            df_plot["n_available"] = pd.to_numeric(df_plot["n_available"], errors="coerce")

            # Box per group
            bp_data = [df_plot.loc[df_plot["group"] == g, "n_available"].dropna().to_numpy()
                       for g in group_order]
            bp = ax.boxplot(bp_data, positions=list(range(len(group_order))),
                            widths=0.5, patch_artist=True, showfliers=False,
                            medianprops=dict(color="k", lw=1.2))
            for patch, g in zip(bp["boxes"], group_order):
                patch.set_facecolor(_colors.get(g, "#888"))
                patch.set_alpha(_box_alpha)

            # Individual mice as strip dots (jittered)
            rng = np.random.default_rng(42)
            for gi, g in enumerate(group_order):
                vals = df_plot.loc[df_plot["group"] == g, "n_available"].dropna().to_numpy()
                jitter = rng.uniform(-0.12, 0.12, size=len(vals))
                ax.scatter(np.full(len(vals), gi) + jitter, vals,
                           c=_dot_colors.get(g, "#888"), edgecolors="k",
                           linewidths=0.4, s=28, zorder=5, alpha=0.85)

            ax.set_xticks(range(len(group_order)))
            ax.set_xticklabels([_labels.get(g, g) for g in group_order], fontsize=8, rotation=30, ha="right")
            ax.set_title(panel_name, fontsize=9)
            if ax_i == 0:
                ax.set_ylabel("n available neurons", fontsize=9)
            ax.grid(axis="y", alpha=0.2)

        fig.suptitle(f"n_available by DREADD group{f' ({label})' if label else ''}",
                     fontsize=10, y=1.02)
        fig.tight_layout()
        plot_path = os.path.join(save_dir, "n_available_by_group.png")
        fig.savefig(plot_path, dpi=300, bbox_inches="tight")
        print(f"[POP-CURVE] n_available group plot saved: {plot_path}")
        plt.close(fig)
    except Exception as exc:
        print(f"[POP-CURVE] n_available group plot failed: {exc}")


def _test_population_curve_group_interaction(
    df_summary: "pd.DataFrame",
    save_dir: str,
    label: str = "",
) -> None:
    """Test whether neuron-subset size N interacts with DREADD group on decoder error.

    Fits a Linear Mixed Model (LMM):
        score_median ~ C(group, Treatment('mCherry')) * N
    with random intercept per mouse (and random slope for N if it converges).
    Reports main effects, interaction term, and coefficient table.
    Runs per-target and pooled.  Saves to ``<save_dir>/population_curve_group_interaction.txt``.
    """
    needed = {"mouse", "group", "N", "score_median"}
    if df_summary is None or df_summary.empty:
        return
    if not needed.issubset(df_summary.columns):
        print(f"[POP-CURVE] group×N interaction test skipped — missing columns: "
              f"{needed - set(df_summary.columns)}")
        return

    lines: list[str] = []
    lines.append(f"=== score_median ~ group * N  (LMM){f'  ({label})' if label else ''} ===\n")

    def _fit_section(df_in: "pd.DataFrame", section: str) -> None:
        df_m = df_in[["mouse", "group", "N", "score_median"]].dropna().copy()
        df_m["N"] = pd.to_numeric(df_m["N"], errors="coerce")
        df_m["score_median"] = pd.to_numeric(df_m["score_median"], errors="coerce")
        df_m = df_m.dropna()
        groups = sorted(df_m["group"].unique().tolist())
        if len(groups) < 2 or len(df_m["mouse"].unique()) < 3:
            lines.append(f"--- {section} ---")
            lines.append("  <2 groups or <3 mice, skipping.\n")
            return

        lines.append(f"--- {section} ---")
        lines.append(f"  N obs = {len(df_m)}, mice = {df_m['mouse'].nunique()}, "
                     f"groups = {groups}")

        formula = "score_median ~ C(group, Treatment(reference='mCherry')) * N"

        # Try random intercept + slope first; fall back to intercept-only.
        fitted = None
        for re_form, re_label in [("~N", "random intercept + slope"),
                                   ("~1", "random intercept only")]:
            try:
                md = smf.mixedlm(formula, df_m, groups=df_m["mouse"],
                                 re_formula=re_form)
                fitted = md.fit(reml=False)
                lines.append(f"  Model converged ({re_label}).")
                break
            except Exception as exc:
                lines.append(f"  Model with {re_label} failed: {exc}")

        if fitted is None:
            lines.append("  ** Could not fit any LMM variant.\n")
            return

        # Coefficient table
        coef_df = fitted.summary().tables[1]
        if hasattr(coef_df, "to_string"):
            lines.append(coef_df.to_string())
        else:
            lines.append(str(coef_df))

        # Extract interaction p-values (rows containing ":N")
        lines.append("")
        for idx_name in fitted.pvalues.index:
            if ":N" in str(idx_name) or "N:" in str(idx_name):
                coef = fitted.fe_params[idx_name]
                pval = fitted.pvalues[idx_name]
                lines.append(f"  Interaction {idx_name}: coef={coef:.6f}, p={pval:.4f}"
                             f"{'  *' if pval < 0.05 else ''}")

        # Main effect of N
        if "N" in fitted.pvalues.index:
            lines.append(f"  Main effect of N: coef={fitted.fe_params['N']:.6f}, "
                         f"p={fitted.pvalues['N']:.4f}")

        lines.append(f"  Log-Likelihood = {fitted.llf:.2f}")
        lines.append(f"  AIC ~ {-2 * fitted.llf + 2 * len(fitted.fe_params):.1f}")
        lines.append("")

    # Per-target
    if "target" in df_summary.columns:
        for tgt in sorted(df_summary["target"].dropna().unique().tolist()):
            _fit_section(df_summary[df_summary["target"] == tgt], section=f"Target: {tgt}")

    # Pooled: average score_median across targets per (mouse, group, N)
    pooled = (df_summary.groupby(["mouse", "group", "N"], as_index=False)["score_median"]
              .mean())
    _fit_section(pooled, section="Pooled (mean across targets)")

    text = "\n".join(lines)
    print(text)
    out_path = os.path.join(save_dir, "population_curve_group_interaction.txt")
    with open(out_path, "w") as fh:
        fh.write(text)
    print(f"[POP-CURVE] group×N interaction test saved: {out_path}")

    # ---- Boxplot: per-mouse slope of score_median vs N, by group ----
    try:
        from scipy import stats as _sp_stats

        def _mouse_slopes(df_in: "pd.DataFrame") -> "pd.DataFrame":
            """OLS slope of score_median ~ N per mouse."""
            rows = []
            for mouse, mdf in df_in.groupby("mouse"):
                mdf2 = mdf[["N", "score_median"]].dropna()
                mdf2["N"] = pd.to_numeric(mdf2["N"], errors="coerce")
                mdf2["score_median"] = pd.to_numeric(mdf2["score_median"], errors="coerce")
                mdf2 = mdf2.dropna()
                if len(mdf2) < 2:
                    continue
                slope, intercept, r, p, se = _sp_stats.linregress(mdf2["N"], mdf2["score_median"])
                grp = mdf["group"].iloc[0]
                rows.append({"mouse": mouse, "group": grp, "slope": slope})
            return pd.DataFrame(rows)

        targets = (sorted(df_summary["target"].dropna().unique().tolist())
                   if "target" in df_summary.columns else [])
        panels = targets + ["Pooled"]
        n_panels = len(panels)

        fig, axes = plt.subplots(1, n_panels, figsize=(3.0 * n_panels, 4.0), dpi=150,
                                 sharey=True, squeeze=False)
        axes = axes.ravel()

        _colors     = {"mCherry": "#4a4a4a", "hM3D": "#c45a5a", "hM4D": "#5b8db8"}
        _dot_colors = {"mCherry": "#7a7a7a", "hM3D": "#d98e8e", "hM4D": "#8fb5d5"}
        _labels_map = {"mCherry": "Control", "hM3D": "Excitatory", "hM4D": "Inhibitory"}
        _box_alpha  = 0.30

        for ax_i, panel_name in enumerate(panels):
            ax = axes[ax_i]
            if panel_name == "Pooled":
                slopes_df = _mouse_slopes(pooled)
            else:
                slopes_df = _mouse_slopes(df_summary[df_summary["target"] == panel_name])

            if slopes_df.empty:
                ax.set_title(panel_name, fontsize=9)
                ax.text(0.5, 0.5, "no data", ha="center", va="center", transform=ax.transAxes)
                continue

            group_order = [g for g in ["mCherry", "hM3D", "hM4D"] if g in slopes_df["group"].unique()]
            bp_data = [slopes_df.loc[slopes_df["group"] == g, "slope"].to_numpy() for g in group_order]

            bp = ax.boxplot(bp_data, positions=list(range(len(group_order))),
                            widths=0.5, patch_artist=True, showfliers=False,
                            medianprops=dict(color="k", lw=1.2))
            for patch, g in zip(bp["boxes"], group_order):
                patch.set_facecolor(_colors.get(g, "#888"))
                patch.set_alpha(_box_alpha)

            rng = np.random.default_rng(42)
            for gi, g in enumerate(group_order):
                vals = slopes_df.loc[slopes_df["group"] == g, "slope"].to_numpy()
                jitter = rng.uniform(-0.12, 0.12, size=len(vals))
                ax.scatter(np.full(len(vals), gi) + jitter, vals,
                           c=_dot_colors.get(g, "#888"), edgecolors="k",
                           linewidths=0.4, s=28, zorder=5, alpha=0.85)

            ax.axhline(0, color="k", ls="--", lw=0.6, alpha=0.4)
            ax.set_xticks(range(len(group_order)))
            ax.set_xticklabels([_labels_map.get(g, g) for g in group_order],
                               fontsize=8, rotation=30, ha="right")
            ax.set_title(panel_name, fontsize=9)
            if ax_i == 0:
                ax.set_ylabel("Slope (error / neuron)", fontsize=9)
            ax.grid(axis="y", alpha=0.2)

        fig.suptitle(
            f"Per-mouse slope of decoder error vs N{f' ({label})' if label else ''}",
            fontsize=10, y=1.02)
        fig.tight_layout()
        plot_path = os.path.join(save_dir, "population_curve_slope_by_group.png")
        fig.savefig(plot_path, dpi=300, bbox_inches="tight")
        print(f"[POP-CURVE] slope-by-group boxplot saved: {plot_path}")
        plt.close(fig)
    except Exception as exc:
        print(f"[POP-CURVE] slope-by-group boxplot failed: {exc}")


# Path to the methods/ directory co-located with this script
_METHODS_DIR = os.path.join(os.path.dirname(os.path.abspath(__file__)), "methods")

# Path to the repo-level analysis_methods_templates/ directory
_ANALYSIS_METHODS_TEMPLATES_DIR = os.path.join(
    os.path.dirname(os.path.abspath(__file__)), "..", "analysis_methods_templates")


def _copy_analysis_methods_template(template_filename: str, dest_dir: str) -> None:
    """Copy a template from analysis_methods_templates/ into *dest_dir* (skip if already present)."""
    dest_path = os.path.join(dest_dir, template_filename)
    if os.path.isfile(dest_path):
        return
    src_path = os.path.join(_ANALYSIS_METHODS_TEMPLATES_DIR, template_filename)
    if not os.path.isfile(src_path):
        print(f"[METHODS] Template not found: {src_path}")
        return
    import shutil
    os.makedirs(dest_dir, exist_ok=True)
    shutil.copy2(src_path, dest_path)
    print(f"[METHODS] Copied {template_filename} → {dest_path}")


def _copy_methods_txt(subfolder: str, dest_dir: str) -> None:
    """Copy methods/<subfolder>/METHODS.txt into *dest_dir* (skip if already present)."""
    dest_path = os.path.join(dest_dir, "METHODS.txt")
    if os.path.isfile(dest_path):
        return
    src_path = os.path.join(_METHODS_DIR, subfolder, "METHODS.txt")
    if not os.path.isfile(src_path):
        print(f"[METHODS] Source not found: {src_path}")
        return
    import shutil
    os.makedirs(dest_dir, exist_ok=True)
    shutil.copy2(src_path, dest_path)
    print(f"[METHODS] Copied METHODS.txt → {dest_path}")


def _fmt_p_text(p):
    try:
        p = float(p)
    except Exception:
        return "NA"
    if not np.isfinite(p):
        return "NA"
    if p < 1e-4:
        return f"{p:.2e}"
    return f"{p:.4f}"


def _tfc_top_effects_text(df, *, p_col="p", stat_col="z", top_n=6):
    if df is None or df.empty or p_col not in df.columns:
        return "No valid effects were available."
    d = df.copy()
    d[p_col] = pd.to_numeric(d[p_col], errors="coerce")
    d = d[np.isfinite(d[p_col])].sort_values(p_col).head(top_n)
    if d.empty:
        return "No valid effects were available."

    out = []
    for _, r in d.iterrows():
        g = str(r.get("group", "NA"))
        g_lbl = _TFC_GROUP_LABELS.get(g, g)
        contrast = str(r.get("contrast", "contrast"))
        est = float(r.get("est", np.nan))
        se = float(r.get("se", np.nan))
        stat = float(r.get(stat_col, np.nan)) if stat_col in r else np.nan
        out.append(
            f"{contrast} [{g_lbl}: beta={est:.2f}, SE={se:.2f}, {stat_col}={stat:.2f}, p={_fmt_p_text(r[p_col])}]"
        )
    return "; ".join(out)


def _write_tfc_methods_txt(
    save_path: str,
    *,
    file_prefix: str,
    err_col: str,
    df_model: "pd.DataFrame",
    df_wald: "pd.DataFrame",
    df_f: "pd.DataFrame",
    df_lrt: "pd.DataFrame",
    emmeans_out: dict,
) -> None:
    """Render METHODS.txt for TFC MixedLM analyses using runtime statistics."""
    template_path = os.path.join(_METHODS_DIR, "tfc_mixedlm", "METHODS.txt")
    if not os.path.isfile(template_path):
        print(f"[METHODS] TFC template not found: {template_path}")
        return

    with open(template_path, "r", encoding="utf-8") as f:
        template = f.read()

    n_rows = int(len(df_model)) if df_model is not None else 0
    n_mice = int(df_model["mouse"].nunique()) if df_model is not None and "mouse" in df_model else 0
    n_groups = int(df_model["group"].nunique()) if df_model is not None and "group" in df_model else 0
    n_conditions = int(df_model["condition"].nunique()) if df_model is not None and "condition" in df_model else 0

    model_par = (
        f"A mixed-effects model was fitted to {err_col} using the formula "
        f"{err_col} ~ group * condition with a random intercept for mouse "
        f"(n_rows={n_rows}, n_mice={n_mice}, n_groups={n_groups}, "
        f"n_conditions={n_conditions})."
    )

    wald_sig = int(np.nansum(pd.to_numeric(df_wald.get("p", pd.Series(dtype=float)), errors="coerce") < 0.05)) if df_wald is not None else 0
    wald_total = int(len(df_wald)) if df_wald is not None else 0
    wald_par = (
        f"Planned Wald z-tests were computed for all within-group contrasts; "
        f"{wald_sig}/{wald_total} contrasts were significant at p<0.05. "
        f"Top effects: {_tfc_top_effects_text(df_wald, p_col='p', stat_col='z', top_n=6)}."
    )

    if df_f is not None and not df_f.empty and "p" in df_f.columns:
        f_sig = int(np.nansum(pd.to_numeric(df_f["p"], errors="coerce") < 0.05))
        f_total = int(len(df_f))
        f_par = (
            f"Complementary fixed-effects OLS HC3 F-tests were run on the same "
            f"planned contrasts; {f_sig}/{f_total} contrasts were significant at "
            f"p<0.05. Top effects: {_tfc_top_effects_text(df_f, p_col='p', stat_col='f', top_n=6)}."
        )
    else:
        f_par = (
            "Complementary fixed-effects OLS HC3 F-tests were not available "
            "for this run (fixed-effects model not fitted)."
        )

    if df_lrt is not None and not df_lrt.empty:
        lrt_bits = []
        for _, r in df_lrt.iterrows():
            lrt_bits.append(
                f"{r.get('test', 'test')}: LR={float(r.get('lr_stat', np.nan)):.2f}, "
                f"df={int(r.get('df', 0)) if np.isfinite(r.get('df', np.nan)) else 'NA'}, "
                f"p={_fmt_p_text(r.get('p', np.nan))}"
            )
        lrt_par = "Omnibus likelihood-ratio tests compared nested MixedLM fits (ML): " + "; ".join(lrt_bits) + "."
    else:
        lrt_par = "Omnibus likelihood-ratio tests were requested but no valid LRT output was produced."

    emm_pair = emmeans_out.get("pairwise") if isinstance(emmeans_out, dict) else None
    emm_within = emmeans_out.get("within") if isinstance(emmeans_out, dict) else None
    if emm_pair is not None and not emm_pair.empty:
        holm_sig = int(np.nansum(pd.to_numeric(emm_pair.get("p_holm", pd.Series(dtype=float)), errors="coerce") < 0.05))
        tukey_sig = int(np.nansum(pd.to_numeric(emm_pair.get("p_tukey_inf", pd.Series(dtype=float)), errors="coerce") < 0.05))
        emm_total = int(len(emm_pair))
        emm_top = _tfc_top_effects_text(
            emm_within if emm_within is not None else pd.DataFrame(),
            p_col="p", stat_col="z", top_n=4,
        )
        emmeans_par = (
            f"EMMeans-style post hoc outputs were generated from model-based marginal means; "
            f"pairwise between-group contrast differences yielded {holm_sig}/{emm_total} "
            f"significant comparisons with Holm correction and {tukey_sig}/{emm_total} "
            f"with Tukey-style adjustment. Representative within-group contrast effects: {emm_top}."
        )
    else:
        emmeans_par = "EMMeans-style post hoc outputs were requested but no valid pairwise table was produced."

    replacements = {
        "FILE_PREFIX": file_prefix,
        "MODEL_PARAGRAPH": model_par,
        "WALD_PARAGRAPH": wald_par,
        "FTEST_PARAGRAPH": f_par,
        "LRT_PARAGRAPH": lrt_par,
        "EMMEANS_PARAGRAPH": emmeans_par,
    }
    out_text = template
    for k, v in replacements.items():
        out_text = out_text.replace(f"{{{{{k}}}}}", str(v))

    out_path = os.path.join(save_path, "METHODS.txt")
    with open(out_path, "w", encoding="utf-8") as f:
        f.write(out_text)
    print(f"[METHODS] Wrote runtime METHODS.txt -> {out_path}")


def _plot_population_curve_group_overlays(
    df_summary: "pd.DataFrame",
    save_dir: str,
    train_label: str,
    *,
    variant_tag: str = "",
    plot_debug: bool = True,
    auto_close: bool = True,
    min_mice_common: int = 2,
) -> None:
    """Plot three group-overlay variants per target from population-curve summary data.

    1. **Raw** – group mean ± SEM at every N (original plot, all data).
    2. **Common-N** – restricted to N values where every group has ≥ *min_mice_common* mice.
    3. **Normalized** – each mouse's curve divided by its score at the first grid point,
       so group means reflect within-mouse relative change.

    All three are produced in a single pass over *df_summary* (no decoder re-run).
    """
    if df_summary is None or df_summary.empty:
        return
    _copy_methods_txt("population_curve", save_dir)
    prefix = f"[POP-CURVE{'-' + variant_tag if variant_tag else ''}]"

    for tgt_name in sorted(df_summary["target"].dropna().unique().tolist()):
        df_t = df_summary[df_summary["target"] == tgt_name].copy()
        if df_t.empty:
            continue

        groups = sorted(df_t["group"].dropna().unique().tolist())

        # --- pre-compute per-group stats at each N (shared across plots) ---
        group_stats = {}  # grp -> DataFrame with N, mean, sem
        for grp in groups:
            df_g = df_t[df_t["group"] == grp]
            if df_g.empty:
                continue
            agg = df_g.groupby("N", as_index=False)["score_median"].agg(["mean", "sem"]).reset_index()
            agg.columns = ["N", "mean", "sem"]
            agg = agg.sort_values("N")
            group_stats[grp] = agg

        if not group_stats:
            continue

        # Helper: draw one mean ± SEM overlay on a given ax
        def _draw(ax, stats_dict, n_filter=None):
            for grp in groups:
                if grp not in stats_dict:
                    continue
                agg = stats_dict[grp]
                if n_filter is not None:
                    agg = agg[agg["N"].isin(n_filter)]
                if agg.empty:
                    continue
                x = agg["N"].to_numpy(dtype=float)
                y = agg["mean"].to_numpy(dtype=float)
                s = agg["sem"].to_numpy(dtype=float)
                c_line = _PAPER_COLORS.get(grp, "gray")
                c_fill = _PAPER_DOT_COLORS.get(grp, "#aaaaaa")
                ax.plot(x, y, lw=1.8, marker="o", label=grp, color=c_line)
                ax.fill_between(x, y - s, y + s, alpha=0.22, color=c_fill)

        title_base = f"{train_label}->{tgt_name}"
        tag = variant_tag + "_" if variant_tag else ""

        # ---- PLOT 1: Raw (all N) ----
        fig, ax = plt.subplots(figsize=(8, 5), dpi=150)
        _draw(ax, group_stats)
        ax.set_xlabel("Neuron subset size N")
        ax.set_ylabel(_euclidean_error_axis_label())
        ax.set_title(f"Group {tag}population curves — {title_base}")
        ax.grid(True, alpha=0.2); ax.legend(); fig.tight_layout()
        p = os.path.join(save_dir, f"population_curve_group_overlay_{tgt_name}.png")
        fig.savefig(p, dpi=300); print(f"{prefix} saved group overlay: {p}")
        if plot_debug: plt.show()
        if auto_close: plt.close(fig)

        # ---- PLOT 2: Common-N (only N where every group has ≥ min_mice_common) ----
        n_counts_per_group = {}
        for grp in groups:
            df_g = df_t[df_t["group"] == grp]
            c = df_g.groupby("N")["mouse"].nunique()
            n_counts_per_group[grp] = set(c[c >= min_mice_common].index.tolist())
        common_ns = sorted(set.intersection(*n_counts_per_group.values())) if n_counts_per_group else []

        if len(common_ns) >= 2:
            # Re-compute stats restricted to mice present across common_ns
            common_stats = {}
            for grp in groups:
                df_g = df_t[(df_t["group"] == grp) & (df_t["N"].isin(common_ns))]
                # Only mice that appear at ALL common N values
                mice_at_all = df_g.groupby("mouse")["N"].nunique()
                full_mice = mice_at_all[mice_at_all == len(common_ns)].index
                df_g = df_g[df_g["mouse"].isin(full_mice)]
                if df_g.empty:
                    continue
                agg = df_g.groupby("N", as_index=False)["score_median"].agg(["mean", "sem"]).reset_index()
                agg.columns = ["N", "mean", "sem"]
                agg = agg.sort_values("N")
                common_stats[grp] = agg

            fig, ax = plt.subplots(figsize=(8, 5), dpi=150)
            _draw(ax, common_stats)
            ax.set_xlabel("Neuron subset size N")
            ax.set_ylabel(_euclidean_error_axis_label())
            ax.set_title(f"Group {tag}population curves (common N, matched mice) — {title_base}")
            ax.grid(True, alpha=0.2); ax.legend(); fig.tight_layout()
            p = os.path.join(save_dir, f"population_curve_group_overlay_commonN_{tgt_name}.png")
            fig.savefig(p, dpi=300); print(f"{prefix} saved common-N overlay: {p}")
            if plot_debug: plt.show()
            if auto_close: plt.close(fig)
        else:
            print(f"{prefix} common-N overlay skipped for {tgt_name}: <2 common N values")

        # ---- PLOT 3: Normalized to baseline (first grid point per mouse) ----
        norm_rows = []
        for (mouse, grp), mdf in df_t.groupby(["mouse", "group"]):
            mdf = mdf.sort_values("N")
            baseline = mdf["score_median"].iloc[0]
            if baseline <= 0 or np.isnan(baseline):
                continue
            for _, row in mdf.iterrows():
                norm_rows.append({
                    "mouse": mouse, "group": grp, "N": row["N"],
                    "norm_score": row["score_median"] / baseline,
                })
        if norm_rows:
            df_norm = pd.DataFrame(norm_rows)
            norm_stats = {}
            for grp in groups:
                df_g = df_norm[df_norm["group"] == grp]
                if df_g.empty:
                    continue
                agg = df_g.groupby("N", as_index=False)["norm_score"].agg(["mean", "sem"]).reset_index()
                agg.columns = ["N", "mean", "sem"]
                agg = agg.sort_values("N")
                norm_stats[grp] = agg

            # -- Per-mouse slope statistics ----------------------------------
            from scipy import stats as _sp_pop
            slope_by_group = {}  # grp -> array of per-mouse slopes
            for grp in groups:
                df_g = df_norm[df_norm["group"] == grp]
                if df_g.empty:
                    continue
                mice = df_g["mouse"].unique()
                slopes = []
                for m in mice:
                    mdf = df_g[df_g["mouse"] == m].sort_values("N")
                    if len(mdf) < 2:
                        continue
                    sl, _, _, _, _ = _sp_pop.linregress(mdf["N"].to_numpy(dtype=float),
                                                        mdf["norm_score"].to_numpy(dtype=float))
                    slopes.append(sl)
                if slopes:
                    slope_by_group[grp] = np.array(slopes)

            # Per-group: one-sample Wilcoxon signed-rank (H0: median slope = 0)
            stat_lines = []
            stat_lines.append(f"{prefix} Slope stats for {title_base}:")
            p_values_per_group = {}
            for grp in groups:
                if grp not in slope_by_group or len(slope_by_group[grp]) < 3:
                    stat_lines.append(f"  {grp}: n<3 mice, skipped")
                    continue
                sl = slope_by_group[grp]
                # One-sided: is slope < 0?
                try:
                    stat_w, p_two = _sp_pop.wilcoxon(sl, alternative="two-sided")
                    # For one-sided (slope < 0): halve p if median is negative
                    if np.median(sl) < 0:
                        p_one = p_two / 2.0
                    else:
                        p_one = 1.0 - p_two / 2.0
                except ValueError:
                    stat_w, p_two, p_one = np.nan, np.nan, np.nan
                p_values_per_group[grp] = p_one
                stat_lines.append(
                    f"  {grp}: n={len(sl)} mice, median slope={np.median(sl):.6f}, "
                    f"mean slope={np.mean(sl):.6f}, "
                    f"Wilcoxon p(two-sided)={p_two:.4g}, p(one-sided, <0)={p_one:.4g}"
                )

            # Kruskal-Wallis across groups (do slopes differ?)
            valid_groups = [g for g in groups if g in slope_by_group and len(slope_by_group[g]) >= 2]
            if len(valid_groups) >= 2:
                kw_stat, kw_p = _sp_pop.kruskal(
                    *[slope_by_group[g] for g in valid_groups]
                )
                stat_lines.append(
                    f"  Kruskal-Wallis (slope ~ group): H={kw_stat:.4f}, p={kw_p:.4g}"
                )
            else:
                kw_p = np.nan
                stat_lines.append("  Kruskal-Wallis: <2 valid groups, skipped")
            for ln in stat_lines:
                print(ln)

            # -- Build annotation text for the plot --------------------------
            annot_parts = []
            for grp in groups:
                if grp in p_values_per_group:
                    p_val = p_values_per_group[grp]
                    n_mice = len(slope_by_group[grp])
                    med_sl = np.median(slope_by_group[grp]) * 1000  # per-1000 neurons for readability
                    annot_parts.append(
                        f"{grp} (n={n_mice}): slope={med_sl:+.2f}e-3, p={p_val:.3g}"
                    )
            if not np.isnan(kw_p):
                annot_parts.append(f"KW group diff: p={kw_p:.3g}")
            annot_text = "\n".join(annot_parts)

            fig, ax = plt.subplots(figsize=(8, 5), dpi=150)
            _draw(ax, norm_stats)
            ax.axhline(1.0, color="k", ls="--", lw=0.8, alpha=0.4)
            if annot_text:
                ax.text(0.98, 0.02, annot_text, transform=ax.transAxes,
                        fontsize=7, va="bottom", ha="right",
                        bbox=dict(boxstyle="round,pad=0.3", fc="white", ec="0.7", alpha=0.85))
            ax.set_xlabel("Neuron subset size N")
            ax.set_ylabel("Normalized error (relative to first N)")
            ax.set_title(f"Group {tag}population curves (baseline-normalized) — {title_base}")
            ax.grid(True, alpha=0.2); ax.legend(); fig.tight_layout()
            p = os.path.join(save_dir, f"population_curve_group_overlay_normalized_{tgt_name}.png")
            fig.savefig(p, dpi=300); print(f"{prefix} saved normalized overlay: {p}")
            if plot_debug: plt.show()
            if auto_close: plt.close(fig)


def _resolve_mapping_for_target(mapping, tgt_name: str) -> str:
    """If *mapping* is a dict keyed by target name, return the entry for
    *tgt_name* (or a ``"default"`` key); otherwise return the string as-is."""
    if isinstance(mapping, dict):
        if tgt_name in mapping:
            return str(mapping[tgt_name])
        if "default" in mapping:
            return str(mapping["default"])
        raise KeyError(
            f"mapping dict has no entry for target '{tgt_name}' and no 'default' key. "
            f"Available keys: {sorted(mapping.keys())}"
        )
    return str(mapping)


def _resolve_cross_session_mapping(train_sess, test_sess, mapping: str, require_exact_mapping: bool = False):
    """
    Resolve the best available cross-registration mapping and return
    (crossreg, df_mapping, mapping_used, reason_if_failed).
    """
    train_type = train_sess.session_type
    test_type = test_sess.session_type
    mapping_labels = set(mapping.split('+'))

    crossreg, df_mapping = None, None
    mapping_used = str(mapping)

    # Only attempt multi-session mapping if both train & test types are in it.
    if train_type in mapping_labels and test_type in mapping_labels:
        crossreg, df_mapping = _find_crossreg_with_mapping(train_sess, test_sess, mapping)

    if require_exact_mapping:
        if crossreg is None:
            cand_info = [(f"type{c.crossreg_type}", sorted(c.mappings_labels.keys())) for c in _collect_crossreg_candidates(train_sess, test_sess)]
            if train_type not in mapping_labels or test_type not in mapping_labels:
                reason = (
                    f"Exact mapping required for {train_type}->{test_type}, but mapping '{mapping}' "
                    f"does not include both session types. Candidates: {cand_info}"
                )
            else:
                reason = (
                    f"Exact mapping '{mapping}' required for {train_type}->{test_type}, but it was not found. "
                    f"Candidates: {cand_info}"
                )
            return None, None, mapping_used, reason
        return crossreg, df_mapping, mapping_used, ""

    if crossreg is None:
        fallback = _make_pair_mapping(train_type, test_type)
        crossreg, df_mapping = _find_crossreg_with_mapping(train_sess, test_sess, fallback)
        if crossreg is not None:
            mapping_used = fallback

    candidates = _collect_crossreg_candidates(train_sess, test_sess)

    if crossreg is None and len(mapping_labels) >= 2 and train_type in mapping_labels and test_type in mapping_labels:
        # Broad N-way fallback: cells present across all mapping labels.
        for candidate in candidates:
            try:
                df_mapping = candidate.get_cells_for_pair(*mapping_labels)
                crossreg = candidate
                mapping_used = f"{'+'.join(sorted(mapping_labels))}(broad)"
                break
            except KeyError:
                continue

    if crossreg is None:
        # Broad pair fallback: cells present in train+test only.
        for candidate in candidates:
            try:
                df_mapping = candidate.get_cells_for_pair(train_type, test_type)
                crossreg = candidate
                mapping_used = f"{train_type}+{test_type}(broad)"
                break
            except KeyError:
                continue

    if crossreg is None:
        cand_info = [(f"type{c.crossreg_type}", sorted(c.mappings_labels.keys())) for c in candidates]
        reason = f"No crossreg mapping found for {train_type}->{test_type}. Candidates: {cand_info}"
        return None, None, mapping_used, reason

    return crossreg, df_mapping, mapping_used, ""


def _get_cross_session_available_cells(train_sess, test_sess, *, mapping: str, require_exact_mapping: bool = False) -> Dict[str, Any]:
    """Return matched-cell availability for one train/test pair after mapping resolution."""
    crossreg, df_mapping, mapping_used, reason = _resolve_cross_session_mapping(
        train_sess, test_sess, mapping, require_exact_mapping=require_exact_mapping)
    if crossreg is None:
        return {"ok": False, "reason": reason, "n_cells_available": 0, "mapping_used": mapping_used}

    try:
        col_train = train_sess.get_df_col(with_crossreg=crossreg)
        col_test = test_sess.get_df_col(with_crossreg=crossreg)
        cells_train = df_mapping[col_train].astype(float).astype(int).tolist()
        cells_test = df_mapping[col_test].astype(float).astype(int).tolist()
        S_train, _ = get_mapped_S_from_unit_ids(train_sess, cells_train)
        S_test, _ = get_mapped_S_from_unit_ids(test_sess, cells_test)
    except Exception as exc:
        return {
            "ok": False,
            "reason": f"Failed to compute matched cells: {exc}",
            "n_cells_available": 0,
            "mapping_used": mapping_used,
        }

    n_avail = int(min(S_train.shape[0], S_test.shape[0]))
    return {
        "ok": n_avail > 0,
        "reason": "" if n_avail > 0 else "No cross-registered cells found.",
        "n_cells_available": n_avail,
        "mapping_used": mapping_used,
    }


def _get_cross_session_available_cells_pf(
    train_sess,
    test_sess,
    *,
    mapping: str,
    require_exact_mapping: bool,
    place_cells_only: bool,
    use_pf_num: int,
    use_occupancy_fallback: bool,
) -> Dict[str, Any]:
    """Return PF-eligible matched-cell availability for one train/test pair."""
    if not hasattr(train_sess, 'fm') or train_sess.fm is None:
        return {
            "ok": False,
            "reason": "Train session has no FluorescenceMap (.fm).",
            "n_cells_available": 0,
            "mapping_used": mapping,
        }

    fm = train_sess.fm
    if fm.fluorescence_map_occup is None or not hasattr(fm, 'pf') or fm.pf is None:
        return {
            "ok": False,
            "reason": "Train session .fm is missing occupancy/PF model.",
            "n_cells_available": 0,
            "mapping_used": mapping,
        }

    crossreg, df_mapping, mapping_used, reason = _resolve_cross_session_mapping(
        train_sess, test_sess, mapping, require_exact_mapping=require_exact_mapping)
    if crossreg is None:
        return {
            "ok": False,
            "reason": reason,
            "n_cells_available": 0,
            "mapping_used": mapping_used,
        }

    try:
        col_train = train_sess.get_df_col(with_crossreg=crossreg)
        col_test = test_sess.get_df_col(with_crossreg=crossreg)
        cells_train_ids = df_mapping[col_train].astype(float).astype(int).tolist()
        cells_test_ids = df_mapping[col_test].astype(float).astype(int).tolist()
        S_train, _ = get_mapped_S_from_unit_ids(train_sess, cells_train_ids)
        S_test, _ = get_mapped_S_from_unit_ids(test_sess, cells_test_ids)
    except Exception as exc:
        return {
            "ok": False,
            "reason": f"Failed to compute matched PF cells: {exc}",
            "n_cells_available": 0,
            "mapping_used": mapping_used,
        }

    n = int(min(S_train.shape[0], S_test.shape[0]))
    if n <= 0:
        return {
            "ok": False,
            "reason": "No cross-registered cells found.",
            "n_cells_available": 0,
            "mapping_used": mapping_used,
        }

    cells_train_ids = cells_train_ids[:n]
    fm_cells_list = list(fm.cells) if fm.cells is not None else []
    train_S_indices = train_sess.get_S_indeces(cells_train_ids)

    n_keep = 0
    for s_idx in train_S_indices:
        if s_idx not in fm_cells_list:
            continue
        if place_cells_only and not (fm.sig_responses is not None and s_idx in fm.sig_responses):
            continue
        if use_pf_num >= 1:
            if s_idx not in fm.pf.model_:
                continue
            n_merged_pf = len(fm.pf.merged_means.get(s_idx, []))
            if n_merged_pf == 0 or n_merged_pf > use_pf_num:
                continue
        elif not use_occupancy_fallback and s_idx not in fm.pf.model_:
            continue
        n_keep += 1

    return {
        "ok": n_keep > 0,
        "reason": "" if n_keep > 0 else "No PF-eligible cross-registered cells found.",
        "n_cells_available": int(n_keep),
        "mapping_used": mapping_used,
    }


def decode_2D_cross_session(
    train_sess,
    test_sess,
    *,
    mapping: str = "TFC_cond+Test_B+Test_B_1wk",
    n_x_bins: int = 20,
    n_y_bins: int = 20,
    time_bin_frames: int = 5,
    use_posterior_mean: bool = True,
    decoder_type: str = 'bayesian',
    ridge_alpha: float = 1.0,
    use_continuity_constraint: bool = True,
    continuity_sigma_k: float = 60.0,
    continuity_speed_ref: float = 20.0,
    continuity_exp: float = 1.0,
    continuity_sigma_min: float = 20.0,
    continuity_sigma_max: float = 60.0,
    continuity_sigma_default: float = 30.0,
    use_speed: bool = True,
    min_speed: float = 2.0,
    first_n_sec: float = 180.0,
    encoder_period: str = "pre-tone",
    use_z_score: str = "none",
    require_exact_mapping: bool = False,
    neuron_subset_size: Optional[int] = None,
    neuron_subset_seed: Optional[int] = None,
    shuffle_type: str = "none",
    shuffle_seed: Optional[int] = None,
) -> Dict[str, Any]:
    """
    Train a 2D Bayesian decoder on *train_sess* pre-tone, decode *test_sess*
    pre-tone using cross-registered cells.

    Uses the 3-way mapping ('TFC_cond+Test_B+Test_B_1wk') by default so that
    the same cell population is used across all decode targets.  Falls back to
    the pairwise mapping if the 3-way is unavailable (e.g., G07, G15).

    Returns dict with ok, out, euclidean_err, n_cells_mapped, mapping, …
    """
    crossreg, df_mapping, mapping, reason = _resolve_cross_session_mapping(
        train_sess, test_sess, mapping, require_exact_mapping=require_exact_mapping)
    if crossreg is None:
        return {"ok": False, "reason": reason}

    col_train = train_sess.get_df_col(with_crossreg=crossreg)
    col_test  = test_sess.get_df_col(with_crossreg=crossreg)

    cells_train = df_mapping[col_train].astype(float).astype(int).tolist()
    cells_test  = df_mapping[col_test].astype(float).astype(int).tolist()

    S_train, _ = get_mapped_S_from_unit_ids(train_sess, cells_train)
    S_test, _  = get_mapped_S_from_unit_ids(test_sess,  cells_test)

    if S_train.shape[0] == 0 or S_test.shape[0] == 0:
        return {"ok": False, "reason": "No cross-registered cells found."}

    n = min(S_train.shape[0], S_test.shape[0])
    S_train = S_train[:n]
    S_test = S_test[:n]
    n_total_mapped = int(n)

    if neuron_subset_size is not None:
        n_subset = int(neuron_subset_size)
        if n_subset <= 0:
            return {"ok": False, "reason": f"Invalid neuron_subset_size={neuron_subset_size}"}
        n_subset = min(n_subset, n_total_mapped)
        if n_subset < n_total_mapped:
            rng = default_rng(neuron_subset_seed)
            keep = np.sort(rng.choice(n_total_mapped, size=n_subset, replace=False))
            S_train = S_train[keep, :]
            S_test = S_test[keep, :]
        n = n_subset

    # Optional per-neuron z-scoring policy.
    S_train, S_test = _apply_zscore_pair(S_train, S_test, use_z_score)

    if str(shuffle_type).strip().lower() not in ("", "none", "off", "false", "0"):
        rng = default_rng(shuffle_seed)
        S_train = _apply_decoder_time_shuffle(S_train, shuffle_type=shuffle_type, rng=rng)
        S_test = _apply_decoder_time_shuffle(S_test, shuffle_type=shuffle_type, rng=rng)

    dist_meta = _validate_2d_decoder_distance_meta(train_sess, test_sess)
    pos_scale = float(dist_meta["scale"])

    dt_train = _infer_dt_sec(train_sess)
    dt_test  = _infer_dt_sec(test_sess)

    for _label, _sess in [("train", train_sess), ("test", test_sess)]:
        if not hasattr(_sess, 'loc_X_miniscope_smooth'):
            return {"ok": False, "reason": (
                f"{_label} session {getattr(_sess, 'mouse', '?')} "
                f"{getattr(_sess, 'session_type', '?')} has no location data "
                f"(loc_X_miniscope_smooth). Re-initialise sessions after ensuring "
                f"LocationOutput.csv or saver pkl files exist.")}

    x_tr = _scale_2d_position_array(train_sess.loc_X_miniscope_smooth, pos_scale)[:S_train.shape[1]]
    y_tr = _scale_2d_position_array(train_sess.loc_Y_miniscope_smooth, pos_scale)[:S_train.shape[1]]
    x_te = _scale_2d_position_array(test_sess.loc_X_miniscope_smooth, pos_scale)[:S_test.shape[1]]
    y_te = _scale_2d_position_array(test_sess.loc_Y_miniscope_smooth, pos_scale)[:S_test.shape[1]]
    v_te = _scale_2d_position_array(_get_miniscope_velocity_vector(test_sess, T=S_test.shape[1]), pos_scale)

    (continuity_sigma_k_u,
     continuity_speed_ref_u,
     continuity_sigma_min_u,
     continuity_sigma_max_u,
     continuity_sigma_default_u) = _scale_2d_decoder_lengths(
        pos_scale,
        continuity_sigma_k,
        continuity_speed_ref,
        continuity_sigma_min,
        continuity_sigma_max,
        continuity_sigma_default,
    )

    mask_train = build_pretone_mask_TFC(train_sess, first_n_sec=first_n_sec,
                                         use_speed=use_speed, min_speed=min_speed,
                                         encoder_period=encoder_period)[:S_train.shape[1]]
    mask_test  = build_pretone_mask_TFC(test_sess, first_n_sec=first_n_sec,
                                         use_speed=use_speed, min_speed=min_speed,
                                         encoder_period="pre-tone")[:S_test.shape[1]]

    if np.sum(mask_train) < time_bin_frames or np.sum(mask_test) < time_bin_frames:
        return {"ok": False, "reason": "Insufficient pre-tone frames."}

    if _decoder_is_ridge(decoder_type):
        dec = RidgeDecoder2D(time_bin_frames=time_bin_frames, alpha=ridge_alpha)
        dec.fit(S_train, x_tr, y_tr, mask_train, dt_train)
        out = dec.decode(S_test, x_te, y_te, mask_test)
    else:
        dec = BayesianDecoder2D(n_x_bins=n_x_bins, n_y_bins=n_y_bins,
                                time_bin_frames=time_bin_frames)
        dec.fit(S_train, x_tr, y_tr, mask_train, dt_train)
        out = dec.decode(S_test, x_te, y_te, mask_test,
                         use_posterior_mean=use_posterior_mean,
                         use_continuity_constraint=use_continuity_constraint,
                         speed_vec=v_te,
                         continuity_sigma_k=continuity_sigma_k_u,
                         continuity_speed_ref=continuity_speed_ref_u,
                         continuity_exp=continuity_exp,
                         continuity_sigma_min=continuity_sigma_min_u,
                         continuity_sigma_max=continuity_sigma_max_u,
                         continuity_sigma_default=continuity_sigma_default_u)

    out = _annotate_2d_decode_output(out, dist_meta)

    return {
        "ok": True,
        "out": out,
        "euclidean_err": out["euclidean_err"],
        "n_cells_mapped": int(n),
        "n_cells_crossreg_total": int(n_total_mapped),
        "n_cells_used": int(n),
        "dt_train": float(dt_train),
        "dt_test": float(dt_test),
        "n_pretone_frames_train": int(np.sum(mask_train)),
        "n_pretone_frames_test":  int(np.sum(mask_test)),
        "mobile_sec_train": float(np.sum(mask_train) * dt_train),
        "mobile_sec_test":  float(np.sum(mask_test) * dt_test),
        "mapping": mapping,
        "encoder_period": encoder_period,
        "neuron_subset_seed": neuron_subset_seed,
        "position_unit": dist_meta["unit"],
        "position_scale": pos_scale,
    }


# ---------------------------------------------------------------------------
#  Generalized 2D PF cross-session decode (place-field rate-map-based)
# ---------------------------------------------------------------------------

def decode_2D_PF_cross_session(
    train_sess,
    test_sess,
    *,
    mapping: str = "TFC_cond+Test_B+Test_B_1wk",
    time_bin_frames: int = 5,
    use_posterior_mean: bool = True,
    decoder_type: str = 'bayesian',
    ridge_alpha: float = 1.0,
    use_continuity_constraint: bool = True,
    continuity_sigma_k: float = 60.0,
    continuity_speed_ref: float = 20.0,
    continuity_exp: float = 1.0,
    continuity_sigma_min: float = 20.0,
    continuity_sigma_max: float = 60.0,
    continuity_sigma_default: float = 30.0,
    use_speed: bool = True,
    min_speed: float = 2.0,
    first_n_sec: float = 180.0,
    place_cells_only: bool = True,
    use_pf_num: int = -1,
    use_occupancy_fallback: bool = True,
    encoder_period: str = "pre-tone",
    use_z_score: str = "none",
    require_exact_mapping: bool = False,
    neuron_subset_size: Optional[int] = None,
    neuron_subset_seed: Optional[int] = None,
    shuffle_type: str = "none",
    shuffle_seed: Optional[int] = None,
) -> Dict[str, Any]:
    """
    Decode *test_sess* pre-tone using the precomputed place-field rate maps
    from *train_sess.fm*.  Cross-registered cells are obtained via the
    type-4 cross-registration.

    Uses the 3-way mapping by default so the same cell population is used
    across all decode targets.  Falls back to pairwise if unavailable.

    Returns dict with ok, out, euclidean_err, n_cells_mapped, mapping, …
    """
    if not hasattr(train_sess, 'fm') or train_sess.fm is None:
        return {"ok": False, "reason": "Train session has no FluorescenceMap (.fm)."}
    fm = train_sess.fm
    if fm.fluorescence_map_occup is None:
        return {"ok": False, "reason": "train_sess.fm.fluorescence_map_occup is None."}
    if not hasattr(fm, 'pf') or fm.pf is None:
        return {"ok": False, "reason": "train_sess.fm has no PlaceFields (.pf). Run find_place_fields() first."}
    if not hasattr(train_sess, 'loc') or train_sess.loc is None:
        return {"ok": False, "reason": "Train session has no Location_XY (.loc)."}

    crossreg, df_mapping, mapping, reason = _resolve_cross_session_mapping(
        train_sess, test_sess, mapping, require_exact_mapping=require_exact_mapping)
    if crossreg is None:
        return {"ok": False, "reason": reason}

    col_train = train_sess.get_df_col(with_crossreg=crossreg)
    col_test  = test_sess.get_df_col(with_crossreg=crossreg)

    cells_train_ids = df_mapping[col_train].astype(float).astype(int).tolist()
    cells_test_ids  = df_mapping[col_test].astype(float).astype(int).tolist()

    S_train, _ = get_mapped_S_from_unit_ids(train_sess, cells_train_ids)
    S_test, _  = get_mapped_S_from_unit_ids(test_sess,  cells_test_ids)

    if S_train.shape[0] == 0 or S_test.shape[0] == 0:
        return {"ok": False, "reason": "No cross-registered cells found."}

    n = min(S_train.shape[0], S_test.shape[0])
    S_train = S_train[:n]; S_test = S_test[:n]
    cells_train_ids = cells_train_ids[:n]
    cells_test_ids = cells_test_ids[:n]

    # --- Map cross-registered train cell unit-IDs to fm.cells indices ---
    fm_cells_list = list(fm.cells) if fm.cells is not None else []
    train_S_indices = train_sess.get_S_indeces(cells_train_ids)

    keep_mask = []
    fm_cell_indices = []
    for i, s_idx in enumerate(train_S_indices):
        if s_idx in fm_cells_list:
            fm_idx = fm_cells_list.index(s_idx)
            if place_cells_only:
                if not (fm.sig_responses is not None and s_idx in fm.sig_responses):
                    continue
            if use_pf_num >= 1:
                if s_idx not in fm.pf.model_:
                    continue
                n_merged_pf = len(fm.pf.merged_means.get(s_idx, []))
                if n_merged_pf == 0 or n_merged_pf > use_pf_num:
                    continue
            elif not use_occupancy_fallback:
                if s_idx not in fm.pf.model_:
                    continue
            keep_mask.append(i)
            fm_cell_indices.append(fm_idx)

    if len(keep_mask) == 0:
        return {"ok": False, "reason": "No cross-registered cells found in fluorescence map."}

    S_train_kept = S_train[keep_mask]
    S_test_kept  = S_test[keep_mask]
    n_cells_used = len(keep_mask)

    if neuron_subset_size is not None:
        n_subset = int(neuron_subset_size)
        if n_subset <= 0:
            return {"ok": False, "reason": f"Invalid neuron_subset_size={neuron_subset_size}"}
        n_subset = min(n_subset, n_cells_used)
        if n_subset < n_cells_used:
            rng = default_rng(neuron_subset_seed)
            keep_sub = np.sort(rng.choice(n_cells_used, size=n_subset, replace=False))
            S_train_kept = S_train_kept[keep_sub, :]
            S_test_kept = S_test_kept[keep_sub, :]
            fm_cell_indices = [fm_cell_indices[i] for i in keep_sub]
        n_cells_used = int(n_subset)

    # Optional per-neuron z-scoring policy.
    S_train_kept, S_test_kept = _apply_zscore_pair(S_train_kept, S_test_kept, use_z_score)

    if str(shuffle_type).strip().lower() not in ("", "none", "off", "false", "0"):
        rng = default_rng(shuffle_seed)
        S_train_kept = _apply_decoder_time_shuffle(S_train_kept, shuffle_type=shuffle_type, rng=rng)
        S_test_kept = _apply_decoder_time_shuffle(S_test_kept, shuffle_type=shuffle_type, rng=rng)

    dist_meta = _validate_2d_decoder_distance_meta(train_sess, test_sess)
    pos_scale = float(dist_meta["scale"])

    rate_map  = fm.fluorescence_map_occup
    occupancy = train_sess.loc.occupancy
    bin_width = float(train_sess.loc.bin_width) * pos_scale
    dt_train  = _infer_dt_sec(train_sess)
    dt_test   = _infer_dt_sec(test_sess)

    if not hasattr(test_sess, 'loc_X_miniscope_smooth'):
        return {"ok": False, "reason": (
            f"test session {getattr(test_sess, 'mouse', '?')} "
            f"{getattr(test_sess, 'session_type', '?')} has no location data "
            f"(loc_X_miniscope_smooth). Re-initialise sessions after ensuring "
            f"LocationOutput.csv or saver pkl files exist.")}

    x_te = _scale_2d_position_array(test_sess.loc_X_miniscope_smooth, pos_scale)[:S_test_kept.shape[1]]
    y_te = _scale_2d_position_array(test_sess.loc_Y_miniscope_smooth, pos_scale)[:S_test_kept.shape[1]]
    v_te = _scale_2d_position_array(_get_miniscope_velocity_vector(test_sess, T=S_test_kept.shape[1]), pos_scale)

    (continuity_sigma_k_u,
     continuity_speed_ref_u,
     continuity_sigma_min_u,
     continuity_sigma_max_u,
     continuity_sigma_default_u) = _scale_2d_decoder_lengths(
        pos_scale,
        continuity_sigma_k,
        continuity_speed_ref,
        continuity_sigma_min,
        continuity_sigma_max,
        continuity_sigma_default,
    )

    mask_test = build_pretone_mask_TFC(test_sess, first_n_sec=first_n_sec,
                                       use_speed=use_speed, min_speed=min_speed,
                                       encoder_period="pre-tone")[:S_test_kept.shape[1]]

    if np.sum(mask_test) < time_bin_frames:
        return {"ok": False, "reason": "Insufficient pre-tone frames in test session."}

    if _decoder_is_ridge(decoder_type):
        if not hasattr(train_sess, 'loc_X_miniscope_smooth'):
            return {"ok": False, "reason": "Train session has no loc_X_miniscope_smooth for ridge fit."}
        x_tr_r = _scale_2d_position_array(train_sess.loc_X_miniscope_smooth, pos_scale)[:S_train_kept.shape[1]]
        y_tr_r = _scale_2d_position_array(train_sess.loc_Y_miniscope_smooth, pos_scale)[:S_train_kept.shape[1]]
        mask_train_r = build_pretone_mask_TFC(train_sess, first_n_sec=first_n_sec,
                                              use_speed=use_speed, min_speed=min_speed,
                                              encoder_period=encoder_period)[:S_train_kept.shape[1]]
        if np.sum(mask_train_r) < time_bin_frames:
            return {"ok": False, "reason": "Insufficient train pre-tone frames for ridge."}
        dec_r = RidgeDecoder2D(time_bin_frames=time_bin_frames, alpha=ridge_alpha)
        dec_r.fit(S_train_kept, x_tr_r, y_tr_r, mask_train_r, dt_train)
        out = dec_r.decode(S_test_kept, x_te, y_te, mask_test)
    else:
        dec_pf = BayesianDecoder2D_PF(time_bin_frames=time_bin_frames)
        dec_pf.fit_from_place_fields(fm.pf, rate_map, occupancy,
                                     fm_cells=fm_cells_list,
                                     cell_indices=fm_cell_indices,
                                     dt_sec=dt_train, bin_width=bin_width,
                                     use_occupancy_fallback=use_occupancy_fallback)
        out = dec_pf.decode(S_test_kept, x_te, y_te, mask_test,
                            use_posterior_mean=use_posterior_mean,
                            use_continuity_constraint=use_continuity_constraint,
                            speed_vec=v_te,
                            continuity_sigma_k=continuity_sigma_k_u,
                            continuity_speed_ref=continuity_speed_ref_u,
                            continuity_exp=continuity_exp,
                            continuity_sigma_min=continuity_sigma_min_u,
                            continuity_sigma_max=continuity_sigma_max_u,
                            continuity_sigma_default=continuity_sigma_default_u)

    out = _annotate_2d_decode_output(out, dist_meta)

    return {
        "ok": True,
        "out": out,
        "euclidean_err": out["euclidean_err"],
        "n_cells_mapped": int(n_cells_used),
        "n_cells_crossreg_total": int(n),
        "dt_train": float(dt_train),
        "dt_test": float(dt_test),
        "n_pretone_frames_test": int(np.sum(mask_test)),
        "mobile_sec_test": float(np.sum(mask_test) * dt_test),
        "mapping": mapping,
        "place_cells_only": place_cells_only,
        "encoder_period": encoder_period,
        "position_unit": dist_meta["unit"],
        "position_scale": pos_scale,
    }


# ---------------------------------------------------------------------------
#  Multi-target master pipeline: 2D (raw S)
# ---------------------------------------------------------------------------

def run_2D_decoder_all_mice(
    train_sessions: dict,
    test_targets: dict,
    *,
    train_label: str = "TFC_cond",
    mapping = "TFC_cond+Test_B+Test_B_1wk",
    require_exact_mapping: bool = False,
    n_x_bins: int = 20,
    n_y_bins: int = 20,
    time_bin_frames: int = 5,
    use_posterior_mean: bool = True,
    decoder_type: str = 'bayesian',
    ridge_alpha: float = 1.0,
    use_continuity_constraint: bool = True,
    continuity_sigma_k: float = 60.0,
    continuity_speed_ref: float = 20.0,
    continuity_exp: float = 1.0,
    continuity_sigma_min: float = 20.0,
    continuity_sigma_max: float = 60.0,
    continuity_sigma_default: float = 30.0,
    use_speed: bool = True,
    min_speed: float = 2.0,
    first_n_sec: float = 180.0,
    encoder_period: str = "pre-tone",
    use_z_score: str = "none",
    enable_population_curve: bool = False,
    population_curve_n_values: Optional[List[int]] = None,
    population_curve_n_values_max_shared: bool = False,
    population_curve_per_pair_grid: bool = False,
    population_curve_n_step: int = 10,
    population_curve_quantile: float = 0.25,
    population_curve_repeats: int = 100,
    population_curve_seed: int = 42,
    population_curve_metric: str = "median_err",
    manual_killswitch: bool = True,
    killswitch_prompt_every: str = "N_step",
    population_curve_print_level: str = "medium",
    population_curve_suffix: str = "_population_curve",
    population_curve_load_cached: bool = False,
    enable_shuffle_control: bool = False,
    shuffle_type: str = "circular_time_shift",
    n_shuffles: int = 5,
    shuffle_seed: int = 42,
    opt_tag: str = "",
    PLOTS_DIR: str = "",
    session_str: str = "",
    mouse_groups: dict = None,
    plot_debug: bool = True,
    auto_close: bool = True,
) -> dict:
    """
    For each mouse, train a 2D Bayesian decoder on *train_sessions[mouse]*
    and decode each session in *test_targets*.

    Parameters
    ----------
    train_sessions : dict[str, Session]
        {mouse: training_session}
    test_targets : dict[str, dict[str, Session]]
        {"Test_B": {mouse: session}, "Test_B_1wk": {mouse: session}, …}
    train_label : str
        Label for the training session type (for file naming / prints).
    """
    if mouse_groups is None:
        mouse_groups = {}

    decoder_dir_tag = "ridge_2D" if _decoder_is_ridge(decoder_type) else "bayes_2D"
    pop_curve_suffix = str(population_curve_suffix) if enable_population_curve else ""
    _opt_tag_str = f"_opt-{opt_tag}" if opt_tag else ""
    shuffle_suffix = "_shuffle" if _shuffle_is_enabled(enable_shuffle_control, n_shuffles, shuffle_type) else ""
    save_path = os.path.join(PLOTS_DIR,
                             f"{decoder_dir_tag}_multitgt_train_{train_label}_{session_str}_{_z_score_dir_tag(use_z_score)}{_opt_tag_str}{pop_curve_suffix}{shuffle_suffix}")
    os.makedirs(save_path, exist_ok=True)

    target_names = list(test_targets.keys())
    all_results = {}
    all_mice = sorted(train_sessions.keys())
    user_requested_stop = False

    # Population-curve pre-scan: estimate matched-cell availability per mouse-target.
    popcurve_availability = {}
    popcurve_n_grid: List[int] = []
    popcurve_metric = "mean_err" if str(population_curve_metric).strip().lower() == "mean_err" else "median_err"
    stdin_is_tty = hasattr(sys, "stdin") and callable(getattr(sys.stdin, "isatty", None)) and bool(sys.stdin.isatty())
    killswitch_active = bool(enable_population_curve and manual_killswitch and stdin_is_tty)
    if enable_population_curve and manual_killswitch and not stdin_is_tty:
        print("[POP-CURVE] manual_killswitch requested but stdin is non-interactive; disabling prompts.")

    if enable_population_curve:
        avail_counts = []
        print("[POP-CURVE] Scanning matched-cell availability...")
        print(f"[POP-CURVE] Output root: {save_path}")
        for mouse in all_mice:
            if mouse not in train_sessions:
                continue
            train_s = train_sessions[mouse]
            for tgt_name in target_names:
                tgt_dict = test_targets.get(tgt_name, {})
                if mouse not in tgt_dict:
                    continue
                tgt_mapping = _resolve_mapping_for_target(mapping, tgt_name)
                info = _get_cross_session_available_cells(
                    train_s, tgt_dict[mouse], mapping=tgt_mapping, require_exact_mapping=require_exact_mapping)
                popcurve_availability[(mouse, tgt_name)] = info
                if info.get("ok", False):
                    avail_counts.append(int(info.get("n_cells_available", 0)))

        if len(avail_counts) == 0:
            print("[POP-CURVE] No valid train-target pairs with matched cells. Curve mode disabled for this run.")
            enable_population_curve = False
        else:
            avail_arr = np.array(avail_counts, dtype=int)
            use_max_shared = bool(population_curve_n_values_max_shared)
            q = float(np.clip(population_curve_quantile, 0.0, 1.0))
            if use_max_shared:
                n_cap = int(np.min(avail_arr))
                n_cap = max(1, n_cap)
                step = max(1, int(population_curve_n_step))
                if n_cap < step:
                    popcurve_n_grid = [n_cap]
                else:
                    popcurve_n_grid = list(range(step, n_cap + 1, step))
                    if popcurve_n_grid[-1] != n_cap:
                        popcurve_n_grid.append(n_cap)
                if population_curve_n_values is not None:
                    print("[POP-CURVE] population_curve_n_values_max_shared=True -> ignoring manual population_curve_n_values and using shared grid.")
            else:
                n_cap = int(np.floor(np.quantile(avail_arr, q)))
                n_cap = max(1, n_cap)

                if population_curve_n_values is not None:
                    manual_grid = sorted({int(v) for v in population_curve_n_values if int(v) > 0})
                    popcurve_n_grid = [v for v in manual_grid if v <= n_cap]
                    if len(popcurve_n_grid) == 0 and len(manual_grid) > 0:
                        popcurve_n_grid = [min(min(manual_grid), n_cap)]
                else:
                    step = max(1, int(population_curve_n_step))
                    if n_cap < step:
                        popcurve_n_grid = [n_cap]
                    else:
                        popcurve_n_grid = list(range(step, n_cap + 1, step))
                        if popcurve_n_grid[-1] != n_cap:
                            popcurve_n_grid.append(n_cap)

            print(
                f"[POP-CURVE] pairs={len(avail_counts)}  repeats={int(population_curve_repeats)}  "
                f"metric={popcurve_metric}  seed={int(population_curve_seed)}"
            )
            print(
                f"[POP-CURVE] availability min/median/max = "
                f"{int(np.min(avail_arr))}/{int(np.median(avail_arr))}/{int(np.max(avail_arr))}; "
                f"{'max_shared(min-availability)' if use_max_shared else f'quantile={q:.2f}'} -> N_cap={n_cap}; grid={popcurve_n_grid}"
            )

    popcurve_repeat_rows = []
    popcurve_summary_rows = []

    # ---- Cache shortcut: load previously saved CSVs and skip to plots ----
    _cache_dir = os.path.join(NPY_SAVE_PATH, "population_curve_cache")
    _cache_tag = os.path.basename(save_path)
    _cache_summary_path = os.path.join(_cache_dir, f"{_cache_tag}_summary.csv")
    _cache_repeat_path  = os.path.join(_cache_dir, f"{_cache_tag}_repeat.csv")

    if enable_population_curve and population_curve_load_cached:
        if os.path.isfile(_cache_summary_path):
            print(f"[POP-CURVE] Loading cached summary: {_cache_summary_path}")
            _cached_summary = pd.read_csv(_cache_summary_path)
            _cached_repeat  = pd.read_csv(_cache_repeat_path) if os.path.isfile(_cache_repeat_path) else pd.DataFrame()

            popcurve_dir = os.path.join(save_path, "population_curve_tables")
            os.makedirs(popcurve_dir, exist_ok=True)

            # Write into plots subdir so everything is co-located.
            _cached_summary.to_csv(os.path.join(popcurve_dir, "population_curve_summary_level.csv"), index=False)
            if not _cached_repeat.empty:
                _cached_repeat.to_csv(os.path.join(popcurve_dir, "population_curve_repeat_level.csv"), index=False)

            _test_n_available_by_group(_cached_summary, popcurve_dir, label="raw-S")
            _test_population_curve_group_interaction(_cached_summary, popcurve_dir, label="raw-S")
            _plot_population_curve_group_overlays(
                _cached_summary, popcurve_dir, train_label,
                variant_tag="raw-S", plot_debug=plot_debug, auto_close=auto_close,
            )
            print(f"[POP-CURVE] Cache-load complete. Skipping pop-curve repeats; running decoder loop.")
            enable_population_curve = False  # skip pop-curve in main loop, but still decode
        else:
            print(f"[POP-CURVE] population_curve_load_cached=True but no cache found at:\n  {_cache_summary_path}")
            print("[POP-CURVE] Falling through to full computation.")

    for mouse in all_mice:
        train_s = train_sessions[mouse]
        group = mouse_groups.get(mouse, "NA")
        dist_meta = _get_2d_decoder_distance_meta(train_s)
        pos_scale = float(dist_meta["scale"])
        unit_label = dist_meta["unit"]
        print(f"[2D-MT] {mouse} ({group}) train={train_label} ...")

        mouse_res = {"group": group, "targets": {}, "population_curve": {}}

        # Within-session CV on training session
        dt_train = _infer_dt_sec(train_s)
        x_tr = _scale_2d_position_array(train_s.loc_X_miniscope_smooth, pos_scale)
        y_tr = _scale_2d_position_array(train_s.loc_Y_miniscope_smooth, pos_scale)
        S_tr = train_s.S
        S_tr = _apply_zscore_single(S_tr, use_z_score)
        x_tr = x_tr[:S_tr.shape[1]]; y_tr = y_tr[:S_tr.shape[1]]
        mask_tr = build_pretone_mask_TFC(train_s, first_n_sec=first_n_sec,
                                          use_speed=use_speed, min_speed=min_speed,
                                          encoder_period=encoder_period)[:S_tr.shape[1]]
        within = _within_session_2D_cv(S_tr, x_tr, y_tr, mask_tr, dt_train,
                        n_x_bins=n_x_bins, n_y_bins=n_y_bins,
                        time_bin_frames=time_bin_frames,
                        use_posterior_mean=use_posterior_mean,
                        decoder_type=decoder_type,
                        ridge_alpha=ridge_alpha,
                        use_continuity_constraint=use_continuity_constraint,
                        continuity_sigma_k=continuity_sigma_k,
                        continuity_speed_ref=continuity_speed_ref,
                        continuity_exp=continuity_exp,
                        continuity_sigma_min=continuity_sigma_min,
                        continuity_sigma_max=continuity_sigma_max,
                        continuity_sigma_default=continuity_sigma_default,
                        position_unit=unit_label,
                        position_scale=pos_scale)

        if _shuffle_is_enabled(enable_shuffle_control, n_shuffles, shuffle_type):
            _w_med = []
            _w_repeat = []
            for _rep in range(int(n_shuffles)):
                _seed = int(shuffle_seed) + _stable_seed_from_text(f"within|{mouse}|{train_label}") + int(_rep)
                _ws = _within_session_2D_cv(
                    S_tr, x_tr, y_tr, mask_tr, dt_train,
                    n_x_bins=n_x_bins, n_y_bins=n_y_bins,
                    time_bin_frames=time_bin_frames,
                    use_posterior_mean=use_posterior_mean,
                    decoder_type=decoder_type,
                    ridge_alpha=ridge_alpha,
                    use_continuity_constraint=use_continuity_constraint,
                    continuity_sigma_k=continuity_sigma_k,
                    continuity_speed_ref=continuity_speed_ref,
                    continuity_exp=continuity_exp,
                    continuity_sigma_min=continuity_sigma_min,
                    continuity_sigma_max=continuity_sigma_max,
                    continuity_sigma_default=continuity_sigma_default,
                    position_unit=unit_label,
                    position_scale=pos_scale,
                    shuffle_type=shuffle_type,
                    shuffle_seed=_seed,
                )
                if _ws.get("ok", False):
                    _w_e = np.asarray(_ws.get("pooled_euclidean_err", []), float)
                    _w_e = _w_e[np.isfinite(_w_e)]
                    if _w_e.size > 0:
                        _w_med.append(float(np.nanmedian(_w_e)))
                        _w_repeat.append({"repeat": int(_rep), "median_err": float(np.nanmedian(_w_e)), "seed": int(_seed)})
            within["shuffle_control"] = {
                "ok": len(_w_med) > 0,
                "shuffle_type": shuffle_type,
                "n_shuffles": int(n_shuffles),
                "repeat_rows": _w_repeat,
                "median_of_repeat_medians": float(np.nanmedian(_w_med)) if len(_w_med) > 0 else np.nan,
                "mean_of_repeat_medians": float(np.nanmean(_w_med)) if len(_w_med) > 0 else np.nan,
            }
        mouse_res["within_train"] = within

        if within.get("ok", False):
            w_err = within.get("pooled_euclidean_err", np.array([]))
            if w_err.size > 0:
                print(f"  within-{train_label}: median_err={np.nanmedian(w_err):.1f}{unit_label}")
                tag_wt = f"{mouse}_{group}_{session_str}_within_{train_label}"
                fig, ax = plt.subplots(figsize=(8, 5), dpi=150)
                ax.hist(w_err, bins=50, color="seagreen", alpha=0.8)
                ax.set_xlabel(_euclidean_error_axis_label()); ax.set_ylabel("Count")
                ax.set_title(f"{mouse} {group} — within-{train_label} 2D CV")
                ax.axvline(np.nanmedian(w_err), color="red", ls="--",
                            label=f"median={np.nanmedian(w_err):.1f}")
                ax.legend(); fig.tight_layout()
                fig.savefig(os.path.join(save_path, f"{tag_wt}_errhist.png"), dpi=300)
                if plot_debug: plt.show()
                if auto_close: plt.close(fig)

        # Decode each target
        for tgt_name in target_names:
            tgt_dict = test_targets[tgt_name]
            if mouse not in tgt_dict:
                print(f"  [SKIP-TGT] {tgt_name}: mouse {mouse} not available.")
                mouse_res["targets"][tgt_name] = {"ok": False, "reason": "Mouse not in target dict."}
                continue

            test_s = tgt_dict[mouse]
            tgt_mapping = _resolve_mapping_for_target(mapping, tgt_name)
            res = decode_2D_cross_session(
                train_s, test_s,
                mapping=tgt_mapping,
                require_exact_mapping=require_exact_mapping,
                n_x_bins=n_x_bins, n_y_bins=n_y_bins,
                time_bin_frames=time_bin_frames,
                use_posterior_mean=use_posterior_mean,
                decoder_type=decoder_type, ridge_alpha=ridge_alpha,
                use_continuity_constraint=use_continuity_constraint,
                continuity_sigma_k=continuity_sigma_k,
                continuity_speed_ref=continuity_speed_ref,
                continuity_exp=continuity_exp,
                continuity_sigma_min=continuity_sigma_min,
                continuity_sigma_max=continuity_sigma_max,
                continuity_sigma_default=continuity_sigma_default,
                use_speed=use_speed, min_speed=min_speed,
                first_n_sec=first_n_sec,
                encoder_period=encoder_period,
                use_z_score=use_z_score,
            )
            mouse_res["targets"][tgt_name] = res

            if not res.get("ok", False):
                print(f"  [SKIP-TGT] {tgt_name}: {res.get('reason', '?')}")
                continue

            if _shuffle_is_enabled(enable_shuffle_control, n_shuffles, shuffle_type):
                _repeat_rows = []
                _repeat_medians = []
                for _rep in range(int(n_shuffles)):
                    _seed = (
                        int(shuffle_seed)
                        + _stable_seed_from_text(f"xfer|{mouse}|{train_label}|{tgt_name}")
                        + int(_rep)
                    )
                    _sh = decode_2D_cross_session(
                        train_s, test_s,
                        mapping=tgt_mapping,
                        require_exact_mapping=require_exact_mapping,
                        n_x_bins=n_x_bins, n_y_bins=n_y_bins,
                        time_bin_frames=time_bin_frames,
                        use_posterior_mean=use_posterior_mean,
                        decoder_type=decoder_type, ridge_alpha=ridge_alpha,
                        use_continuity_constraint=use_continuity_constraint,
                        continuity_sigma_k=continuity_sigma_k,
                        continuity_speed_ref=continuity_speed_ref,
                        continuity_exp=continuity_exp,
                        continuity_sigma_min=continuity_sigma_min,
                        continuity_sigma_max=continuity_sigma_max,
                        continuity_sigma_default=continuity_sigma_default,
                        use_speed=use_speed, min_speed=min_speed,
                        first_n_sec=first_n_sec,
                        encoder_period=encoder_period,
                        use_z_score=use_z_score,
                        shuffle_type=shuffle_type,
                        shuffle_seed=_seed,
                    )
                    if not _sh.get("ok", False):
                        continue
                    _e = np.asarray(_sh.get("euclidean_err", []), float)
                    _e = _e[np.isfinite(_e)]
                    if _e.size == 0:
                        continue
                    _med = float(np.nanmedian(_e))
                    _repeat_medians.append(_med)
                    _repeat_rows.append({"repeat": int(_rep), "median_err": _med, "seed": int(_seed)})
                res["shuffle_control"] = {
                    "ok": len(_repeat_medians) > 0,
                    "shuffle_type": shuffle_type,
                    "n_shuffles": int(n_shuffles),
                    "repeat_rows": _repeat_rows,
                    "median_of_repeat_medians": float(np.nanmedian(_repeat_medians)) if len(_repeat_medians) > 0 else np.nan,
                    "mean_of_repeat_medians": float(np.nanmean(_repeat_medians)) if len(_repeat_medians) > 0 else np.nan,
                }

            err = res["euclidean_err"]
            print(f"  → {tgt_name}: n_cells={res['n_cells_mapped']}  "
                f"median_err={np.nanmedian(err):.1f}{unit_label}  "
                f"mapping={res['mapping']}")

            # --- Per-target diagnostic plots ---
            tag = f"{mouse}_{group}_{session_str}_{train_label}_to_{tgt_name}"
            out = res["out"]

            # 1) Error histogram
            fig, ax = plt.subplots(figsize=(8, 5), dpi=150)
            ax.hist(err, bins=50, color="steelblue", alpha=0.8)
            ax.set_xlabel(_euclidean_error_axis_label()); ax.set_ylabel("Count")
            ax.set_title(f"{mouse} {group} — {train_label}→{tgt_name}")
            ax.axvline(np.nanmedian(err), color="red", ls="--",
                        label=f"median={np.nanmedian(err):.1f}")
            ax.legend(); fig.tight_layout()
            fig.savefig(os.path.join(save_path, f"{tag}_errhist.png"), dpi=300)
            if plot_debug: plt.show()
            if auto_close: plt.close(fig)

            # 2) X/Y scatter
            fig, axes = plt.subplots(1, 2, figsize=(12, 5), dpi=150)
            for ax, t, d, lb in [(axes[0], out["true_x"], out["decoded_x"], "X"),
                                  (axes[1], out["true_y"], out["decoded_y"], "Y")]:
                ax.scatter(t, d, s=6, alpha=0.3)
                lo = min(np.nanmin(t), np.nanmin(d))
                hi = max(np.nanmax(t), np.nanmax(d))
                ax.plot([lo, hi], [lo, hi], "r-", lw=1.5)
                ax.set_xlabel(f"True {lb} ({unit_label})"); ax.set_ylabel(f"Decoded {lb} ({unit_label})")
                ax.set_title(f"{mouse} {group} — {train_label}→{tgt_name} {lb}")
                ax.grid(True, alpha=0.2)
            fig.tight_layout()
            fig.savefig(os.path.join(save_path, f"{tag}_scatter_XY.png"), dpi=300)
            if plot_debug: plt.show()
            if auto_close: plt.close(fig)

            # 3) 2D trajectory overlay
            fig, ax = plt.subplots(figsize=(7, 7), dpi=150)
            ax.plot(out["true_x"], out["true_y"], "k-", alpha=0.15, lw=0.5, label="true")
            ax.scatter(out["decoded_x"], out["decoded_y"], c=err,
                       s=10, alpha=0.6, cmap="hot", vmin=0,
                       vmax=np.nanpercentile(err, 95) if err.size > 0 else 1)
            cb = plt.colorbar(ax.collections[-1], ax=ax, pad=0.02)
            cb.set_label(f"Eucl. error ({unit_label})")
            ax.set_xlabel(_xy_axis_label("X")); ax.set_ylabel(_xy_axis_label("Y"))
            ax.set_title(f"{mouse} {group} — {train_label}→{tgt_name} traj")
            ax.set_aspect("equal"); fig.tight_layout()
            fig.savefig(os.path.join(save_path, f"{tag}_traj2D.png"), dpi=300)
            if plot_debug: plt.show()
            if auto_close: plt.close(fig)

            # Optional neuron-dropping population-size curve for this mouse-target pair.
            if enable_population_curve:
                avail_info = popcurve_availability.get((mouse, tgt_name), {})
                n_available = int(avail_info.get("n_cells_available", 0)) if avail_info else 0
                if population_curve_per_pair_grid:
                    _step = max(1, int(population_curve_n_step))
                    if n_available < _step:
                        usable_grid = []  # below step — skip (would be orphan grid point)
                    else:
                        usable_grid = list(range(_step, n_available + 1, _step))
                else:
                    usable_grid = [n for n in popcurve_n_grid if int(n) <= n_available]
                curve_res = {
                    "ok": False,
                    "reason": "",
                    "n_available": int(n_available),
                    "n_grid_used": usable_grid,
                    "repeats": int(population_curve_repeats),
                    "metric": popcurve_metric,
                    "rows": [],
                }

                if n_available <= 0:
                    curve_res["reason"] = "No matched cells for curve mode."
                    mouse_res["population_curve"][tgt_name] = curve_res
                    continue

                if len(usable_grid) == 0:
                    curve_res["reason"] = "No usable N values after cap/grid filtering."
                    mouse_res["population_curve"][tgt_name] = curve_res
                    continue

                if str(population_curve_print_level).strip().lower() in {"medium", "high"}:
                    print(
                        f"    [POP-CURVE] {mouse} {tgt_name}: n_available={n_available}, "
                        f"N-grid={usable_grid}, repeats={int(population_curve_repeats)}"
                    )

                for n_idx, n_sub in enumerate(usable_grid):
                    if killswitch_active and str(killswitch_prompt_every).strip().lower() == "n_step" and n_idx > 0:
                        answer = input(
                            f"[manual_killswitch] {mouse} {tgt_name} next N={n_sub}. "
                            "Press Enter to continue, type anything to stop: "
                        )
                        if len(answer.strip()) > 0:
                            user_requested_stop = True
                            curve_res["reason"] = "Stopped by manual_killswitch."
                            print("[POP-CURVE] Stop requested by user. Saving partial results and exiting loops.")
                            break

                    n_t0 = time.time()
                    repeat_scores = []
                    ok_repeats = 0

                    for rep_idx in range(int(population_curve_repeats)):
                        rep_seed = (
                            int(population_curve_seed)
                            + _stable_seed_from_text(f"{mouse}|{tgt_name}")
                            + int(n_sub) * 100003
                            + int(rep_idx)
                        )

                        rep_res = decode_2D_cross_session(
                            train_s,
                            test_s,
                            mapping=tgt_mapping,
                            require_exact_mapping=require_exact_mapping,
                            n_x_bins=n_x_bins,
                            n_y_bins=n_y_bins,
                            time_bin_frames=time_bin_frames,
                            use_posterior_mean=use_posterior_mean,
                            decoder_type=decoder_type,
                            ridge_alpha=ridge_alpha,
                            use_continuity_constraint=use_continuity_constraint,
                            continuity_sigma_k=continuity_sigma_k,
                            continuity_speed_ref=continuity_speed_ref,
                            continuity_exp=continuity_exp,
                            continuity_sigma_min=continuity_sigma_min,
                            continuity_sigma_max=continuity_sigma_max,
                            continuity_sigma_default=continuity_sigma_default,
                            use_speed=use_speed,
                            min_speed=min_speed,
                            first_n_sec=first_n_sec,
                            encoder_period=encoder_period,
                            use_z_score=use_z_score,
                            neuron_subset_size=int(n_sub),
                            neuron_subset_seed=int(rep_seed),
                        )
                        if not rep_res.get("ok", False):
                            continue

                        rep_err = np.asarray(rep_res.get("euclidean_err", np.array([])), dtype=float)
                        if rep_err.size == 0:
                            continue
                        if popcurve_metric == "mean_err":
                            score = float(np.nanmean(rep_err))
                        else:
                            score = float(np.nanmedian(rep_err))
                        if not np.isfinite(score):
                            continue

                        ok_repeats += 1
                        repeat_scores.append(score)
                        popcurve_repeat_rows.append({
                            "mouse": mouse,
                            "group": group,
                            "target": tgt_name,
                            "N": int(n_sub),
                            "repeat": int(rep_idx),
                            "score": float(score),
                            "metric": popcurve_metric,
                            "n_available": int(n_available),
                            "mapping": str(rep_res.get("mapping", mapping)),
                            "seed": int(rep_seed),
                        })

                    repeat_scores_arr = np.asarray(repeat_scores, dtype=float)
                    if repeat_scores_arr.size > 0:
                        summary_row = {
                            "mouse": mouse,
                            "group": group,
                            "target": tgt_name,
                            "N": int(n_sub),
                            "repeats_ok": int(ok_repeats),
                            "repeats_requested": int(population_curve_repeats),
                            "score_mean": float(np.nanmean(repeat_scores_arr)),
                            "score_median": float(np.nanmedian(repeat_scores_arr)),
                            "score_std": float(np.nanstd(repeat_scores_arr)),
                            "score_q25": float(np.nanpercentile(repeat_scores_arr, 25.0)),
                            "score_q75": float(np.nanpercentile(repeat_scores_arr, 75.0)),
                            "metric": popcurve_metric,
                            "n_available": int(n_available),
                        }
                        curve_res["rows"].append(summary_row)
                        popcurve_summary_rows.append(summary_row)

                    elapsed_n = time.time() - n_t0
                    if str(population_curve_print_level).strip().lower() in {"medium", "high"}:
                        if repeat_scores_arr.size > 0:
                            print(
                                f"      [POP-CURVE] N={int(n_sub)} ok={int(ok_repeats)}/{int(population_curve_repeats)} "
                                f"median={float(np.nanmedian(repeat_scores_arr)):.2f}{unit_label} "
                                f"mean={float(np.nanmean(repeat_scores_arr)):.2f}{unit_label} "
                                f"t={elapsed_n:.1f}s"
                            )
                        else:
                            print(
                                f"      [POP-CURVE] N={int(n_sub)} no valid repeats "
                                f"(requested={int(population_curve_repeats)}) t={elapsed_n:.1f}s"
                            )

                    if user_requested_stop:
                        break

                if len(curve_res["rows"]) > 0:
                    curve_res["ok"] = True
                elif len(curve_res["reason"]) == 0:
                    curve_res["reason"] = "No valid repeats completed."

                mouse_res["population_curve"][tgt_name] = curve_res

                if curve_res.get("ok", False):
                    try:
                        df_local = pd.DataFrame(curve_res["rows"]).sort_values("N")
                        curve_plot_path = os.path.join(save_path, f"{tag}_population_curve.png")
                        fig, ax = plt.subplots(figsize=(8, 5), dpi=150)
                        x_n = df_local["N"].to_numpy(dtype=float)
                        y_med = df_local["score_median"].to_numpy(dtype=float)
                        y_q25 = df_local["score_q25"].to_numpy(dtype=float)
                        y_q75 = df_local["score_q75"].to_numpy(dtype=float)
                        ax.plot(x_n, y_med, color="black", lw=1.8, marker="o")
                        ax.fill_between(x_n, y_q25, y_q75, color="gray", alpha=0.25)
                        ax.set_xlabel("Neuron subset size N")
                        ax.set_ylabel(_euclidean_error_axis_label())
                        ax.set_title(f"{mouse} {group} — {train_label}->{tgt_name} population curve")
                        ax.grid(True, alpha=0.2)
                        fig.tight_layout()
                        fig.savefig(curve_plot_path, dpi=300)
                        print(f"    [POP-CURVE] saved mouse curve: {curve_plot_path}")
                        if plot_debug:
                            plt.show()
                        if auto_close:
                            plt.close(fig)
                    except Exception as exc:
                        print(f"    [POP-CURVE] plot failed for {mouse} {tgt_name}: {exc}")

                if user_requested_stop:
                    break

        if user_requested_stop:
            all_results[mouse] = mouse_res
            break

        all_results[mouse] = mouse_res

    # Save population-curve tables/plots after loop, even if stopped early.
    if enable_population_curve:
        popcurve_dir = os.path.join(save_path, "population_curve_tables")
        os.makedirs(popcurve_dir, exist_ok=True)
        print(f"[POP-CURVE] Tables/overlays dir: {popcurve_dir}")

        if len(popcurve_repeat_rows) > 0:
            df_repeat = pd.DataFrame(popcurve_repeat_rows)
            df_repeat.to_csv(os.path.join(popcurve_dir, "population_curve_repeat_level.csv"), index=False)
        else:
            df_repeat = pd.DataFrame()

        if len(popcurve_summary_rows) > 0:
            df_summary = pd.DataFrame(popcurve_summary_rows)
            df_summary = df_summary.sort_values(["target", "group", "mouse", "N"])
            df_summary.to_csv(os.path.join(popcurve_dir, "population_curve_summary_level.csv"), index=False)

            # Save cache copy to NPY location.
            os.makedirs(_cache_dir, exist_ok=True)
            df_summary.to_csv(_cache_summary_path, index=False)
            print(f"[POP-CURVE] Cached summary -> {_cache_summary_path}")
            if not df_repeat.empty:
                df_repeat.to_csv(_cache_repeat_path, index=False)
                print(f"[POP-CURVE] Cached repeat  -> {_cache_repeat_path}")

            # Test n_available ~ DREADD group.
            _test_n_available_by_group(df_summary, popcurve_dir, label="raw-S")
            _test_population_curve_group_interaction(df_summary, popcurve_dir, label="raw-S")

            # Group-level curve overlays (raw, common-N, normalized).
            _plot_population_curve_group_overlays(
                df_summary, popcurve_dir, train_label,
                variant_tag="raw-S", plot_debug=plot_debug, auto_close=auto_close,
            )
        else:
            df_summary = pd.DataFrame()

        with open(os.path.join(popcurve_dir, "population_curve_run_status.txt"), "w") as f:
            status_mode = "max_shared_min_availability" if bool(population_curve_n_values_max_shared) else "quantile"
            f.write(f"stopped_by_user={bool(user_requested_stop)}\n")
            f.write(f"n_grid_mode={status_mode}\n")
            f.write(f"metric={popcurve_metric}\n")
            f.write(f"repeats={int(population_curve_repeats)}\n")
            f.write(f"seed={int(population_curve_seed)}\n")
            f.write(f"n_grid={popcurve_n_grid}\n")
            f.write(f"n_rows_repeat={len(popcurve_repeat_rows)}\n")
            f.write(f"n_rows_summary={len(popcurve_summary_rows)}\n")

        if user_requested_stop:
            print("[POP-CURVE] Stopped by manual_killswitch. Partial results saved.")

    if _shuffle_is_enabled(enable_shuffle_control, n_shuffles, shuffle_type):
        _save_shuffle_control_comparison(
            all_results,
            mouse_groups=mouse_groups,
            save_path=os.path.join(save_path, "shuffle_control_stats"),
            train_label=train_label,
            auto_close=auto_close,
        )

    n_ok = sum(1 for v in all_results.values()
               if any(v["targets"].get(t, {}).get("ok") for t in target_names))
    print(f"[2D-MT] Done. {len(all_results)} mice, {n_ok} with ≥1 successful target.")
    return all_results


# ---------------------------------------------------------------------------
#  Multi-target master pipeline: 2D PF (place-field rate-map-based)
# ---------------------------------------------------------------------------

def run_2D_PF_decoder_all_mice(
    train_sessions: dict,
    test_targets: dict,
    *,
    train_label: str = "TFC_cond",
    mapping: str = "TFC_cond+Test_B+Test_B_1wk",
    require_exact_mapping: bool = False,
    time_bin_frames: int = 5,
    use_posterior_mean: bool = True,
    decoder_type: str = 'bayesian',
    ridge_alpha: float = 1.0,
    use_continuity_constraint: bool = True,
    continuity_sigma_k: float = 60.0,
    continuity_speed_ref: float = 20.0,
    continuity_exp: float = 1.0,
    continuity_sigma_min: float = 20.0,
    continuity_sigma_max: float = 60.0,
    continuity_sigma_default: float = 30.0,
    use_speed: bool = True,
    min_speed: float = 2.0,
    first_n_sec: float = 180.0,
    place_cells_only: bool = True,
    use_pf_num: int = -1,
    use_occupancy_fallback: bool = True,
    encoder_period: str = "pre-tone",
    use_z_score: str = "none",
    enable_population_curve: bool = False,
    population_curve_n_values: Optional[List[int]] = None,
    population_curve_n_values_max_shared: bool = False,
    population_curve_per_pair_grid: bool = False,
    population_curve_n_step: int = 10,
    population_curve_quantile: float = 0.25,
    population_curve_repeats: int = 100,
    population_curve_seed: int = 42,
    population_curve_metric: str = "median_err",
    manual_killswitch: bool = True,
    killswitch_prompt_every: str = "N_step",
    population_curve_print_level: str = "medium",
    population_curve_suffix: str = "_population_curve",
    population_curve_load_cached: bool = False,
    enable_shuffle_control: bool = False,
    shuffle_type: str = "circular_time_shift",
    n_shuffles: int = 5,
    shuffle_seed: int = 42,
    opt_tag: str = "",
    PLOTS_DIR: str = "",
    session_str: str = "",
    mouse_groups: dict = None,
    plot_debug: bool = True,
    auto_close: bool = True,
) -> dict:
    """
    For each mouse, build a PF-based 2D decoder from *train_sessions[mouse].fm*
    and decode each session in *test_targets*.

    Parameters
    ----------
    train_sessions : dict[str, Session]
        Must have .fm and .loc attached.
    test_targets : dict[str, dict[str, Session]]
        {"Test_B": {mouse: session}, "Test_B_1wk": {mouse: session}, …}
    """
    if mouse_groups is None:
        mouse_groups = {}

    pf_str = "pcells" if place_cells_only else "allcells"
    decoder_dir_tag = "ridge_2D_PF" if _decoder_is_ridge(decoder_type) else "bayes_2D_PF"
    pop_curve_suffix = str(population_curve_suffix) if enable_population_curve else ""
    _opt_tag_str = f"_opt-{opt_tag}" if opt_tag else ""
    shuffle_suffix = "_shuffle" if _shuffle_is_enabled(enable_shuffle_control, n_shuffles, shuffle_type) else ""
    save_path = os.path.join(PLOTS_DIR,
                             f"{decoder_dir_tag}_multitgt_train_{train_label}_{session_str}_{pf_str}_{_z_score_dir_tag(use_z_score)}{_opt_tag_str}{pop_curve_suffix}{shuffle_suffix}")
    os.makedirs(save_path, exist_ok=True)

    target_names = list(test_targets.keys())
    all_results = {}
    all_mice = sorted(train_sessions.keys())
    user_requested_stop = False

    # Population-curve pre-scan (PF-specific): estimate PF-eligible matched-cell availability.
    popcurve_availability = {}
    popcurve_n_grid: List[int] = []
    popcurve_metric = "mean_err" if str(population_curve_metric).strip().lower() == "mean_err" else "median_err"
    stdin_is_tty = hasattr(sys, "stdin") and callable(getattr(sys.stdin, "isatty", None)) and bool(sys.stdin.isatty())
    killswitch_active = bool(enable_population_curve and manual_killswitch and stdin_is_tty)
    if enable_population_curve and manual_killswitch and not stdin_is_tty:
        print("[POP-CURVE-PF] manual_killswitch requested but stdin is non-interactive; disabling prompts.")

    if enable_population_curve:
        avail_counts = []
        print("[POP-CURVE-PF] Scanning PF-eligible matched-cell availability...")
        print(f"[POP-CURVE-PF] Output root: {save_path}")
        for mouse in all_mice:
            if mouse not in train_sessions:
                continue
            train_s = train_sessions[mouse]
            for tgt_name in target_names:
                tgt_dict = test_targets.get(tgt_name, {})
                if mouse not in tgt_dict:
                    continue
                tgt_mapping = _resolve_mapping_for_target(mapping, tgt_name)
                info = _get_cross_session_available_cells_pf(
                    train_s,
                    tgt_dict[mouse],
                    mapping=tgt_mapping,
                    require_exact_mapping=require_exact_mapping,
                    place_cells_only=place_cells_only,
                    use_pf_num=use_pf_num,
                    use_occupancy_fallback=use_occupancy_fallback,
                )
                popcurve_availability[(mouse, tgt_name)] = info
                if info.get("ok", False):
                    avail_counts.append(int(info.get("n_cells_available", 0)))

        if len(avail_counts) == 0:
            print("[POP-CURVE-PF] No valid train-target pairs with PF-eligible matched cells. Curve mode disabled for this run.")
            enable_population_curve = False
        else:
            avail_arr = np.array(avail_counts, dtype=int)
            use_max_shared = bool(population_curve_n_values_max_shared)
            q = float(np.clip(population_curve_quantile, 0.0, 1.0))
            if use_max_shared:
                n_cap = int(np.min(avail_arr))
                n_cap = max(1, n_cap)
                step = max(1, int(population_curve_n_step))
                if n_cap < step:
                    popcurve_n_grid = [n_cap]
                else:
                    popcurve_n_grid = list(range(step, n_cap + 1, step))
                    if popcurve_n_grid[-1] != n_cap:
                        popcurve_n_grid.append(n_cap)
                if population_curve_n_values is not None:
                    print("[POP-CURVE-PF] population_curve_n_values_max_shared=True -> ignoring manual population_curve_n_values and using shared grid.")
            else:
                n_cap = int(np.floor(np.quantile(avail_arr, q)))
                n_cap = max(1, n_cap)

                if population_curve_n_values is not None:
                    manual_grid = sorted({int(v) for v in population_curve_n_values if int(v) > 0})
                    popcurve_n_grid = [v for v in manual_grid if v <= n_cap]
                    if len(popcurve_n_grid) == 0 and len(manual_grid) > 0:
                        popcurve_n_grid = [min(min(manual_grid), n_cap)]
                else:
                    step = max(1, int(population_curve_n_step))
                    if n_cap < step:
                        popcurve_n_grid = [n_cap]
                    else:
                        popcurve_n_grid = list(range(step, n_cap + 1, step))
                        if popcurve_n_grid[-1] != n_cap:
                            popcurve_n_grid.append(n_cap)

            print(
                f"[POP-CURVE-PF] pairs={len(avail_counts)}  repeats={int(population_curve_repeats)}  "
                f"metric={popcurve_metric}  seed={int(population_curve_seed)}"
            )
            print(
                f"[POP-CURVE-PF] availability min/median/max = "
                f"{int(np.min(avail_arr))}/{int(np.median(avail_arr))}/{int(np.max(avail_arr))}; "
                f"{'max_shared(min-availability)' if use_max_shared else f'quantile={q:.2f}'} -> N_cap={n_cap}; grid={popcurve_n_grid}"
            )

    popcurve_repeat_rows = []
    popcurve_summary_rows = []

    # ---- Cache shortcut: load previously saved CSVs and skip to plots ----
    _cache_dir = os.path.join(NPY_SAVE_PATH, "population_curve_cache")
    _cache_tag = os.path.basename(save_path)
    _cache_summary_path = os.path.join(_cache_dir, f"{_cache_tag}_summary.csv")
    _cache_repeat_path  = os.path.join(_cache_dir, f"{_cache_tag}_repeat.csv")

    if enable_population_curve and population_curve_load_cached:
        if os.path.isfile(_cache_summary_path):
            print(f"[POP-CURVE-PF] Loading cached summary: {_cache_summary_path}")
            _cached_summary = pd.read_csv(_cache_summary_path)
            _cached_repeat  = pd.read_csv(_cache_repeat_path) if os.path.isfile(_cache_repeat_path) else pd.DataFrame()

            popcurve_dir = os.path.join(save_path, "population_curve_tables_pf")
            os.makedirs(popcurve_dir, exist_ok=True)

            _cached_summary.to_csv(os.path.join(popcurve_dir, "population_curve_summary_level.csv"), index=False)
            if not _cached_repeat.empty:
                _cached_repeat.to_csv(os.path.join(popcurve_dir, "population_curve_repeat_level.csv"), index=False)

            _test_n_available_by_group(_cached_summary, popcurve_dir, label="PF")
            _test_population_curve_group_interaction(_cached_summary, popcurve_dir, label="PF")
            _plot_population_curve_group_overlays(
                _cached_summary, popcurve_dir, train_label,
                variant_tag="PF", plot_debug=plot_debug, auto_close=auto_close,
            )
            print(f"[POP-CURVE-PF] Cache-load complete. Skipping pop-curve repeats; running decoder loop.")
            enable_population_curve = False  # skip pop-curve in main loop, but still decode
        else:
            print(f"[POP-CURVE-PF] population_curve_load_cached=True but no cache found at:\n  {_cache_summary_path}")
            print("[POP-CURVE-PF] Falling through to full computation.")

    for mouse in all_mice:
        train_s = train_sessions[mouse]
        group = mouse_groups.get(mouse, "NA")
        dist_meta = _get_2d_decoder_distance_meta(train_s)
        pos_scale = float(dist_meta["scale"])
        unit_label = dist_meta["unit"]
        print(f"[2D-PF-MT] {mouse} ({group}) train={train_label} [{pf_str}] ...")

        mouse_res = {"group": group, "targets": {}, "population_curve": {}}

        # Within-session PF CV on training session
        if hasattr(train_s, 'fm') and train_s.fm is not None and hasattr(train_s, 'loc') and train_s.loc is not None:
            fm = train_s.fm
            fm_cells_list = list(fm.cells) if fm.cells is not None else []
            # Use all fm cells (or place cells only)
            if place_cells_only and fm.sig_responses is not None:
                fm_cell_indices_all = [i for i, c in enumerate(fm_cells_list)
                                       if c in fm.sig_responses]
            else:
                fm_cell_indices_all = list(range(len(fm_cells_list)))

            if len(fm_cell_indices_all) > 0:
                S_tr_all = train_s.S[fm_cells_list, :]
                S_tr_pf  = S_tr_all[fm_cell_indices_all, :]
                S_tr_pf = _apply_zscore_single(S_tr_pf, use_z_score)
                dt_train = _infer_dt_sec(train_s)
                x_tr = _scale_2d_position_array(train_s.loc_X_miniscope_smooth, pos_scale)[:S_tr_pf.shape[1]]
                y_tr = _scale_2d_position_array(train_s.loc_Y_miniscope_smooth, pos_scale)[:S_tr_pf.shape[1]]
                mask_tr = build_pretone_mask_TFC(train_s, first_n_sec=first_n_sec,
                                                  use_speed=use_speed, min_speed=min_speed,
                                                  encoder_period=encoder_period)[:S_tr_pf.shape[1]]

                if _decoder_is_ridge(decoder_type):
                    within = _within_session_2D_cv_ridge(
                        S_tr_pf, x_tr, y_tr, mask_tr, dt_train,
                        time_bin_frames=time_bin_frames,
                        ridge_alpha=ridge_alpha,
                    )
                else:
                    # Compute speed vector and scale continuity lengths
                    _v_tr = _scale_2d_position_array(
                        _get_miniscope_velocity_vector(train_s, T=S_tr_pf.shape[1]),
                        pos_scale)[:S_tr_pf.shape[1]]
                    (_cc_sigma_k_u, _cc_speed_ref_u,
                     _cc_sigma_min_u, _cc_sigma_max_u,
                     _cc_sigma_default_u) = _scale_2d_decoder_lengths(
                        pos_scale,
                        continuity_sigma_k, continuity_speed_ref,
                        continuity_sigma_min, continuity_sigma_max,
                        continuity_sigma_default)
                    within = _within_session_2D_PF_cv(
                        S_tr_pf, x_tr, y_tr, mask_tr, dt_train,
                        pf=fm.pf,
                        rate_map=fm.fluorescence_map_occup,
                        occupancy=train_s.loc.occupancy,
                        fm_cells=fm_cells_list,
                        fm_cell_indices=fm_cell_indices_all,
                        bin_width=float(train_s.loc.bin_width) * pos_scale,
                        time_bin_frames=time_bin_frames,
                        use_posterior_mean=use_posterior_mean,
                        use_pf_num=use_pf_num,
                        use_occupancy_fallback=use_occupancy_fallback,
                        use_continuity_constraint=use_continuity_constraint,
                        speed_vec=_v_tr,
                        continuity_sigma_k=_cc_sigma_k_u,
                        continuity_speed_ref=_cc_speed_ref_u,
                        continuity_exp=continuity_exp,
                        continuity_sigma_min=_cc_sigma_min_u,
                        continuity_sigma_max=_cc_sigma_max_u,
                        continuity_sigma_default=_cc_sigma_default_u,
                        position_unit=unit_label,
                        position_scale=pos_scale,
                    )
                mouse_res["within_train"] = within

                if within.get("ok", False):
                    w_err = within.get("pooled_euclidean_err", np.array([]))
                    if w_err.size > 0:
                        print(f"  within-{train_label} PF: median_err={np.nanmedian(w_err):.1f}{unit_label}")
                        tag_wt = f"{mouse}_{group}_{session_str}_within_{train_label}_{pf_str}"
                        fig, ax = plt.subplots(figsize=(8, 5), dpi=150)
                        ax.hist(w_err, bins=50, color="teal", alpha=0.8)
                        ax.set_xlabel(_euclidean_error_axis_label()); ax.set_ylabel("Count")
                        ax.set_title(f"{mouse} {group} — within-{train_label} PF CV ({pf_str})")
                        ax.axvline(np.nanmedian(w_err), color="red", ls="--",
                                    label=f"median={np.nanmedian(w_err):.1f}")
                        ax.legend(); fig.tight_layout()
                        fig.savefig(os.path.join(save_path, f"{tag_wt}_errhist.png"), dpi=300)
                        if plot_debug: plt.show()
                        if auto_close: plt.close(fig)
            else:
                mouse_res["within_train"] = {"ok": False, "reason": "No PF cells for within-CV."}
        else:
            mouse_res["within_train"] = {"ok": False, "reason": "No .fm on training session."}

        # Decode each target
        for tgt_name in target_names:
            tgt_dict = test_targets[tgt_name]
            if mouse not in tgt_dict:
                print(f"  [SKIP-TGT] {tgt_name}: mouse {mouse} not available.")
                mouse_res["targets"][tgt_name] = {"ok": False, "reason": "Mouse not in target dict."}
                continue

            test_s = tgt_dict[mouse]
            tgt_mapping = _resolve_mapping_for_target(mapping, tgt_name)
            res = decode_2D_PF_cross_session(
                train_s, test_s,
                mapping=tgt_mapping,
                require_exact_mapping=require_exact_mapping,
                time_bin_frames=time_bin_frames,
                use_posterior_mean=use_posterior_mean,
                decoder_type=decoder_type, ridge_alpha=ridge_alpha,
                use_continuity_constraint=use_continuity_constraint,
                continuity_sigma_k=continuity_sigma_k,
                continuity_speed_ref=continuity_speed_ref,
                continuity_exp=continuity_exp,
                continuity_sigma_min=continuity_sigma_min,
                continuity_sigma_max=continuity_sigma_max,
                continuity_sigma_default=continuity_sigma_default,
                use_speed=use_speed, min_speed=min_speed,
                first_n_sec=first_n_sec,
                place_cells_only=place_cells_only,
                use_pf_num=use_pf_num,
                use_occupancy_fallback=use_occupancy_fallback,
                encoder_period=encoder_period,
                use_z_score=use_z_score,
            )
            mouse_res["targets"][tgt_name] = res

            if not res.get("ok", False):
                print(f"  [SKIP-TGT] {tgt_name}: {res.get('reason', '?')}")
                continue

            if _shuffle_is_enabled(enable_shuffle_control, n_shuffles, shuffle_type):
                _repeat_rows = []
                _repeat_medians = []
                for _rep in range(int(n_shuffles)):
                    _seed = (
                        int(shuffle_seed)
                        + _stable_seed_from_text(f"pf-xfer|{mouse}|{train_label}|{tgt_name}")
                        + int(_rep)
                    )
                    _sh = decode_2D_PF_cross_session(
                        train_s, test_s,
                        mapping=tgt_mapping,
                        require_exact_mapping=require_exact_mapping,
                        time_bin_frames=time_bin_frames,
                        use_posterior_mean=use_posterior_mean,
                        decoder_type=decoder_type, ridge_alpha=ridge_alpha,
                        use_continuity_constraint=use_continuity_constraint,
                        continuity_sigma_k=continuity_sigma_k,
                        continuity_speed_ref=continuity_speed_ref,
                        continuity_exp=continuity_exp,
                        continuity_sigma_min=continuity_sigma_min,
                        continuity_sigma_max=continuity_sigma_max,
                        continuity_sigma_default=continuity_sigma_default,
                        use_speed=use_speed, min_speed=min_speed,
                        first_n_sec=first_n_sec,
                        place_cells_only=place_cells_only,
                        use_pf_num=use_pf_num,
                        use_occupancy_fallback=use_occupancy_fallback,
                        encoder_period=encoder_period,
                        use_z_score=use_z_score,
                        shuffle_type=shuffle_type,
                        shuffle_seed=_seed,
                    )
                    if not _sh.get("ok", False):
                        continue
                    _e = np.asarray(_sh.get("euclidean_err", []), float)
                    _e = _e[np.isfinite(_e)]
                    if _e.size == 0:
                        continue
                    _med = float(np.nanmedian(_e))
                    _repeat_medians.append(_med)
                    _repeat_rows.append({"repeat": int(_rep), "median_err": _med, "seed": int(_seed)})
                res["shuffle_control"] = {
                    "ok": len(_repeat_medians) > 0,
                    "shuffle_type": shuffle_type,
                    "n_shuffles": int(n_shuffles),
                    "repeat_rows": _repeat_rows,
                    "median_of_repeat_medians": float(np.nanmedian(_repeat_medians)) if len(_repeat_medians) > 0 else np.nan,
                    "mean_of_repeat_medians": float(np.nanmean(_repeat_medians)) if len(_repeat_medians) > 0 else np.nan,
                }

            err = res["euclidean_err"]
            print(f"  → {tgt_name}: n_cells_PF={res['n_cells_mapped']}  "
                f"median_err={np.nanmedian(err):.1f}{unit_label}  "
                f"mapping={res['mapping']}")

            # --- Per-target diagnostic plots ---
            tag = f"{mouse}_{group}_{session_str}_{train_label}_to_{tgt_name}_{pf_str}"
            out = res["out"]

            # 1) Error histogram
            fig, ax = plt.subplots(figsize=(8, 5), dpi=150)
            ax.hist(err, bins=50, color="darkorange", alpha=0.8)
            ax.set_xlabel(_euclidean_error_axis_label()); ax.set_ylabel("Count")
            ax.set_title(f"{mouse} {group} — {train_label} PF→{tgt_name} ({pf_str})")
            ax.axvline(np.nanmedian(err), color="red", ls="--",
                        label=f"median={np.nanmedian(err):.1f}")
            ax.legend(); fig.tight_layout()
            fig.savefig(os.path.join(save_path, f"{tag}_errhist.png"), dpi=300)
            if plot_debug: plt.show()
            if auto_close: plt.close(fig)

            # 2) X/Y scatter
            fig, axes = plt.subplots(1, 2, figsize=(12, 5), dpi=150)
            for ax, t, d, lb in [(axes[0], out["true_x"], out["decoded_x"], "X"),
                                  (axes[1], out["true_y"], out["decoded_y"], "Y")]:
                ax.scatter(t, d, s=6, alpha=0.3)
                lo = min(np.nanmin(t), np.nanmin(d))
                hi = max(np.nanmax(t), np.nanmax(d))
                ax.plot([lo, hi], [lo, hi], "r-", lw=1.5)
                ax.set_xlabel(f"True {lb} ({unit_label})"); ax.set_ylabel(f"Decoded {lb} ({unit_label})")
                ax.set_title(f"{mouse} {group} — {train_label} PF→{tgt_name} {lb}")
                ax.grid(True, alpha=0.2)
            fig.tight_layout()
            fig.savefig(os.path.join(save_path, f"{tag}_scatter_XY.png"), dpi=300)
            if plot_debug: plt.show()
            if auto_close: plt.close(fig)

            # 3) 2D trajectory
            fig, ax = plt.subplots(figsize=(7, 7), dpi=150)
            ax.plot(out["true_x"], out["true_y"], "k-", alpha=0.15, lw=0.5, label="true")
            ax.scatter(out["decoded_x"], out["decoded_y"], c=err,
                       s=10, alpha=0.6, cmap="hot", vmin=0,
                       vmax=np.nanpercentile(err, 95) if err.size > 0 else 1)
            cb = plt.colorbar(ax.collections[-1], ax=ax, pad=0.02)
            cb.set_label(f"Eucl. error ({unit_label})")
            ax.set_xlabel(_xy_axis_label("X")); ax.set_ylabel(_xy_axis_label("Y"))
            ax.set_title(f"{mouse} {group} — {train_label} PF→{tgt_name} ({pf_str})")
            ax.set_aspect("equal"); fig.tight_layout()
            fig.savefig(os.path.join(save_path, f"{tag}_traj2D.png"), dpi=300)
            if plot_debug: plt.show()
            if auto_close: plt.close(fig)

            # Optional neuron-dropping population-size curve for this mouse-target pair.
            if enable_population_curve:
                avail_info = popcurve_availability.get((mouse, tgt_name), {})
                n_available = int(avail_info.get("n_cells_available", 0)) if avail_info else 0
                if population_curve_per_pair_grid:
                    _step = max(1, int(population_curve_n_step))
                    if n_available < _step:
                        usable_grid = []  # below step — skip (would be orphan grid point)
                    else:
                        usable_grid = list(range(_step, n_available + 1, _step))
                else:
                    usable_grid = [n for n in popcurve_n_grid if int(n) <= n_available]
                curve_res = {
                    "ok": False,
                    "reason": "",
                    "n_available": int(n_available),
                    "n_grid_used": usable_grid,
                    "repeats": int(population_curve_repeats),
                    "metric": popcurve_metric,
                    "rows": [],
                }

                if n_available <= 0:
                    curve_res["reason"] = "No PF-eligible matched cells for curve mode."
                    mouse_res["population_curve"][tgt_name] = curve_res
                    continue

                if len(usable_grid) == 0:
                    curve_res["reason"] = "No usable N values after cap/grid filtering."
                    mouse_res["population_curve"][tgt_name] = curve_res
                    continue

                if str(population_curve_print_level).strip().lower() in {"medium", "high"}:
                    print(
                        f"    [POP-CURVE-PF] {mouse} {tgt_name}: n_available={n_available}, "
                        f"N-grid={usable_grid}, repeats={int(population_curve_repeats)}"
                    )

                for n_idx, n_sub in enumerate(usable_grid):
                    if killswitch_active and str(killswitch_prompt_every).strip().lower() == "n_step" and n_idx > 0:
                        answer = input(
                            f"[manual_killswitch] PF {mouse} {tgt_name} next N={n_sub}. "
                            "Press Enter to continue, type anything to stop: "
                        )
                        if len(answer.strip()) > 0:
                            user_requested_stop = True
                            curve_res["reason"] = "Stopped by manual_killswitch."
                            print("[POP-CURVE-PF] Stop requested by user. Saving partial results and exiting loops.")
                            break

                    n_t0 = time.time()
                    repeat_scores = []
                    ok_repeats = 0

                    for rep_idx in range(int(population_curve_repeats)):
                        rep_seed = (
                            int(population_curve_seed)
                            + _stable_seed_from_text(f"PF|{mouse}|{tgt_name}")
                            + int(n_sub) * 100003
                            + int(rep_idx)
                        )

                        rep_res = decode_2D_PF_cross_session(
                            train_s,
                            test_s,
                            mapping=tgt_mapping,
                            require_exact_mapping=require_exact_mapping,
                            time_bin_frames=time_bin_frames,
                            use_posterior_mean=use_posterior_mean,
                            decoder_type=decoder_type,
                            ridge_alpha=ridge_alpha,
                            use_continuity_constraint=use_continuity_constraint,
                            continuity_sigma_k=continuity_sigma_k,
                            continuity_speed_ref=continuity_speed_ref,
                            continuity_exp=continuity_exp,
                            continuity_sigma_min=continuity_sigma_min,
                            continuity_sigma_max=continuity_sigma_max,
                            continuity_sigma_default=continuity_sigma_default,
                            use_speed=use_speed,
                            min_speed=min_speed,
                            first_n_sec=first_n_sec,
                            place_cells_only=place_cells_only,
                            use_pf_num=use_pf_num,
                            use_occupancy_fallback=use_occupancy_fallback,
                            encoder_period=encoder_period,
                            use_z_score=use_z_score,
                            neuron_subset_size=int(n_sub),
                            neuron_subset_seed=int(rep_seed),
                        )

                        if not rep_res.get("ok", False):
                            continue

                        rep_err = np.asarray(rep_res.get("euclidean_err", []), float)
                        rep_err = rep_err[np.isfinite(rep_err)]
                        if rep_err.size == 0:
                            continue

                        score = float(np.nanmean(rep_err)) if popcurve_metric == "mean_err" else float(np.nanmedian(rep_err))
                        if not np.isfinite(score):
                            continue

                        ok_repeats += 1
                        repeat_scores.append(score)
                        popcurve_repeat_rows.append({
                            "mouse": mouse,
                            "group": group,
                            "target": tgt_name,
                            "N": int(n_sub),
                            "rep": int(rep_idx),
                            "score": float(score),
                            "metric": popcurve_metric,
                            "mapping_used": rep_res.get("mapping", mapping),
                            "n_cells_total": int(rep_res.get("n_cells_crossreg_total", np.nan)),
                            "n_cells_used": int(rep_res.get("n_cells_mapped", np.nan)),
                            "decoder_variant": "PF",
                        })

                    elapsed_n = float(time.time() - n_t0)
                    if len(repeat_scores) > 0:
                        arr = np.asarray(repeat_scores, float)
                        row = {
                            "mouse": mouse,
                            "group": group,
                            "target": tgt_name,
                            "N": int(n_sub),
                            "score_median": float(np.nanmedian(arr)),
                            "score_mean": float(np.nanmean(arr)),
                            "score_q25": float(np.nanpercentile(arr, 25)),
                            "score_q75": float(np.nanpercentile(arr, 75)),
                            "n_repeats_ok": int(ok_repeats),
                            "repeats_requested": int(population_curve_repeats),
                            "metric": popcurve_metric,
                            "n_available": int(n_available),
                            "decoder_variant": "PF",
                        }
                        popcurve_summary_rows.append(row)
                        curve_res["rows"].append(row)
                        curve_res["ok"] = True

                    if str(population_curve_print_level).strip().lower() in {"medium", "high"}:
                        if len(repeat_scores) > 0:
                            print(
                                f"      [POP-CURVE-PF] N={int(n_sub)} ok={int(ok_repeats)}/{int(population_curve_repeats)} "
                                f"median={np.nanmedian(repeat_scores):.2f} mean={np.nanmean(repeat_scores):.2f} t={elapsed_n:.1f}s"
                            )
                        else:
                            print(
                                f"      [POP-CURVE-PF] N={int(n_sub)} no valid repeats "
                                f"(requested={int(population_curve_repeats)}) t={elapsed_n:.1f}s"
                            )

                    if user_requested_stop:
                        break

                if not curve_res["ok"] and len(curve_res["reason"]) == 0:
                    curve_res["reason"] = "All repeats invalid at requested N values."
                mouse_res["population_curve"][tgt_name] = curve_res

                if curve_res["ok"] and len(curve_res["rows"]) > 0:
                    try:
                        df_local = pd.DataFrame(curve_res["rows"]).sort_values("N")
                        curve_plot_path = os.path.join(save_path, f"{tag}_population_curve.png")
                        fig, ax = plt.subplots(figsize=(8, 5), dpi=150)
                        x_n = df_local["N"].to_numpy(dtype=float)
                        y_med = df_local["score_median"].to_numpy(dtype=float)
                        y_q25 = df_local["score_q25"].to_numpy(dtype=float)
                        y_q75 = df_local["score_q75"].to_numpy(dtype=float)
                        ax.plot(x_n, y_med, color="black", lw=1.8, marker="o")
                        ax.fill_between(x_n, y_q25, y_q75, color="gray", alpha=0.25)
                        ax.set_xlabel("Neuron subset size N")
                        ax.set_ylabel(_euclidean_error_axis_label())
                        ax.set_title(f"{mouse} {group} - {train_label} PF->{tgt_name} population curve")
                        ax.grid(True, alpha=0.2)
                        fig.tight_layout()
                        fig.savefig(curve_plot_path, dpi=300)
                        print(f"    [POP-CURVE-PF] saved mouse curve: {curve_plot_path}")
                        if plot_debug:
                            plt.show()
                        if auto_close:
                            plt.close(fig)
                    except Exception as exc:
                        print(f"    [POP-CURVE-PF] plot failed for {mouse} {tgt_name}: {exc}")

                if user_requested_stop:
                    break

        if user_requested_stop:
            all_results[mouse] = mouse_res
            break

        all_results[mouse] = mouse_res

    # Save population-curve tables/plots after loop, even if stopped early.
    if enable_population_curve:
        popcurve_dir = os.path.join(save_path, "population_curve_tables_pf")
        os.makedirs(popcurve_dir, exist_ok=True)
        print(f"[POP-CURVE-PF] Tables/overlays dir: {popcurve_dir}")

        if len(popcurve_repeat_rows) > 0:
            df_repeat = pd.DataFrame(popcurve_repeat_rows)
            df_repeat.to_csv(os.path.join(popcurve_dir, "population_curve_repeat_level.csv"), index=False)
        else:
            df_repeat = pd.DataFrame()

        if len(popcurve_summary_rows) > 0:
            df_summary = pd.DataFrame(popcurve_summary_rows)
            df_summary = df_summary.sort_values(["target", "group", "mouse", "N"])
            df_summary.to_csv(os.path.join(popcurve_dir, "population_curve_summary_level.csv"), index=False)

            # Save cache copy to NPY location.
            os.makedirs(_cache_dir, exist_ok=True)
            df_summary.to_csv(_cache_summary_path, index=False)
            print(f"[POP-CURVE-PF] Cached summary -> {_cache_summary_path}")
            if not df_repeat.empty:
                df_repeat.to_csv(_cache_repeat_path, index=False)
                print(f"[POP-CURVE-PF] Cached repeat  -> {_cache_repeat_path}")

            # Test n_available ~ DREADD group.
            _test_n_available_by_group(df_summary, popcurve_dir, label="PF")
            _test_population_curve_group_interaction(df_summary, popcurve_dir, label="PF")

            # Group-level curve overlays (raw, common-N, normalized).
            _plot_population_curve_group_overlays(
                df_summary, popcurve_dir, train_label,
                variant_tag="PF", plot_debug=plot_debug, auto_close=auto_close,
            )
        else:
            df_summary = pd.DataFrame()

        with open(os.path.join(popcurve_dir, "population_curve_run_status.txt"), "w") as f:
            status_mode = "max_shared_min_availability" if bool(population_curve_n_values_max_shared) else "quantile"
            f.write(f"stopped_by_user={bool(user_requested_stop)}\n")
            f.write(f"n_grid_mode={status_mode}\n")
            f.write(f"metric={popcurve_metric}\n")
            f.write(f"repeats={int(population_curve_repeats)}\n")
            f.write(f"seed={int(population_curve_seed)}\n")
            f.write(f"n_grid={popcurve_n_grid}\n")
            f.write(f"n_rows_repeat={len(popcurve_repeat_rows)}\n")
            f.write(f"n_rows_summary={len(popcurve_summary_rows)}\n")
            f.write("decoder_variant=PF\n")

        if user_requested_stop:
            print("[POP-CURVE-PF] Stopped by manual_killswitch. Partial results saved.")

    if _shuffle_is_enabled(enable_shuffle_control, n_shuffles, shuffle_type):
        _save_shuffle_control_comparison(
            all_results,
            mouse_groups=mouse_groups,
            save_path=os.path.join(save_path, "shuffle_control_stats"),
            train_label=train_label,
            auto_close=auto_close,
        )

    n_ok = sum(1 for v in all_results.values()
               if any(v["targets"].get(t, {}).get("ok") for t in target_names))
    print(f"[2D-PF-MT] Done. {len(all_results)} mice, {n_ok} with ≥1 successful target.")
    return all_results


# ---------------------------------------------------------------------------
#  Multi-target summary DataFrame
# ---------------------------------------------------------------------------

def build_decoder_summary_dataframe(
    all_results: dict,
    mouse_groups: dict,
    train_label: str = "TFC_cond",
    use_scoring_method: str = "euclidean",
    pct_threshold: float = 15.0,
) -> pd.DataFrame:
    """
    Build a mouse-level summary DataFrame from multi-target decoding results.

    Conditions produced:
        'within_{train_label}' — within-session CV on training session
        '{train_label}_to_{target_name}' — cross-session transfer per target

    Output columns also include explicit unit metadata for error values:
        error_unit, distance_scale_cm_per_px
    """
    rows = []

    def _compute_r2_vaf(y_true: np.ndarray, y_pred: np.ndarray) -> float:
        return _compute_r2_vaf_stable(y_true, y_pred)

    def _score_from_out(out: dict, ksum: Optional[np.ndarray] = None) -> np.ndarray:
        method = str(use_scoring_method).strip().lower()
        if method != "rsquared":
            err = np.asarray(out.get("euclidean_err", []), float)
            return err[np.isfinite(err)]

        tx = np.asarray(out.get("true_x", []), float)
        ty = np.asarray(out.get("true_y", []), float)
        dx = np.asarray(out.get("decoded_x", []), float)
        dy = np.asarray(out.get("decoded_y", []), float)
        n = min(tx.size, ty.size, dx.size, dy.size)
        if n == 0:
            return np.array([])
        tx = tx[:n]; ty = ty[:n]; dx = dx[:n]; dy = dy[:n]
        keep = np.isfinite(tx) & np.isfinite(ty) & np.isfinite(dx) & np.isfinite(dy)
        r2x = _compute_r2_vaf(tx[keep], dx[keep]) if np.any(keep) else np.nan
        r2y = _compute_r2_vaf(ty[keep], dy[keep]) if np.any(keep) else np.nan
        r2m = float(np.nanmean([r2x, r2y])) if np.isfinite(r2x) or np.isfinite(r2y) else np.nan
        return np.array([r2m]) if np.isfinite(r2m) else np.array([])

    for mouse, mres in all_results.items():
        group = mouse_groups.get(mouse, mres.get("group", "NA"))
        default_unit = mres.get("position_unit", _TFC_TEST_2D_DISTANCE_UNIT)
        default_scale = float(mres.get("position_scale", _TFC_TEST_2D_CM_PER_PX))

        # Within-train CV
        within = mres.get("within_train", {})
        if within.get("ok", False):
            within_unit = within.get("position_unit", default_unit)
            within_scale = float(within.get("position_scale", default_scale))
            out_parts = []
            w_Ksum_parts = []
            for split_key in ["even_to_odd", "odd_to_even", "even", "odd"]:
                sp = within.get(split_key, {})
                if "out" in sp and "Ksum" in sp["out"]:
                    out_parts.append(sp["out"])
                    w_Ksum_parts.append(np.asarray(sp["out"]["Ksum"], float))
            w_Ksum = np.concatenate(w_Ksum_parts) if w_Ksum_parts else np.array([])
            if out_parts:
                out_cat = {
                    "true_x": np.concatenate([np.asarray(o.get("true_x", []), float) for o in out_parts]),
                    "true_y": np.concatenate([np.asarray(o.get("true_y", []), float) for o in out_parts]),
                    "decoded_x": np.concatenate([np.asarray(o.get("decoded_x", []), float) for o in out_parts]),
                    "decoded_y": np.concatenate([np.asarray(o.get("decoded_y", []), float) for o in out_parts]),
                    "euclidean_err": np.concatenate([np.asarray(o.get("euclidean_err", []), float) for o in out_parts]),
                }
                w_err = _score_from_out(out_cat, w_Ksum if w_Ksum.size else None)
                n_chunks_w = int(np.asarray(out_cat.get("decoded_x", [])).size)
            else:
                w_err = np.asarray(within.get("pooled_euclidean_err", []), float)
                w_err = w_err[np.isfinite(w_err)]
                n_chunks_w = int(w_err.size)

            # PCT always from euclidean errors
            if out_parts:
                _euc_w = np.asarray(out_cat.get("euclidean_err", []), float)
            else:
                _euc_w = np.asarray(within.get("pooled_euclidean_err", []), float)
            _euc_w = _euc_w[np.isfinite(_euc_w)]
            rows.append({
                "mouse": mouse, "group": group,
                "condition": f"within_{train_label}",
                "median_err": float(np.nanmedian(w_err)) if w_err.size else np.nan,
                "mean_err": float(np.nanmean(w_err)) if w_err.size else np.nan,
                "pct_correct": float(np.mean(_euc_w < pct_threshold)) if _euc_w.size else np.nan,
                "n_chunks": n_chunks_w,
                "error_unit": within_unit,
                "distance_scale_cm_per_px": within_scale,
            })

        # Cross-session targets
        targets = mres.get("targets", {})
        for tgt_name, tgt_res in targets.items():
            if not tgt_res.get("ok", False):
                continue
            tgt_unit = tgt_res.get("position_unit", default_unit)
            tgt_scale = float(tgt_res.get("position_scale", default_scale))
            Ksum = np.asarray(tgt_res["out"]["Ksum"], float)
            err = _score_from_out(tgt_res["out"], Ksum)
            n_chunks_tgt = int(np.asarray(tgt_res["out"].get("Ksum", [])).size)
            # PCT always from euclidean errors
            _euc_tgt = np.asarray(tgt_res["out"].get("euclidean_err", []), float)
            _euc_tgt = _euc_tgt[np.isfinite(_euc_tgt)]

            cond_label = f"{train_label}_to_{tgt_name}"
            rows.append({
                "mouse": mouse, "group": group,
                "condition": cond_label,
                "median_err": float(np.nanmedian(err)) if err.size else np.nan,
                "mean_err": float(np.nanmean(err)) if err.size else np.nan,
                "pct_correct": float(np.mean(_euc_tgt < pct_threshold)) if _euc_tgt.size else np.nan,
                "n_chunks": n_chunks_tgt,
                "n_cells": int(tgt_res.get("n_cells_mapped", 0)),
                "mobile_sec_train": float(tgt_res.get("mobile_sec_train", np.nan)),
                "mobile_sec_test":  float(tgt_res.get("mobile_sec_test", np.nan)),
                "error_unit": tgt_unit,
                "distance_scale_cm_per_px": tgt_scale,
            })

    return pd.DataFrame(rows)


# ---------------------------------------------------------------------------
#  Velocity statistics / histograms / data-driven continuity params
# ---------------------------------------------------------------------------

def collect_velocity_stats(*session_dicts: dict) -> dict:
    """
    Pool ``velocities_miniscope_smooth`` (fallback ``velocities_miniscope``)
    across one or more session dicts ``{mouse: session, ...}`` and return
    summary statistics.

    Returns
    -------
    vel_stats : dict
        Keys: ``all_vel`` (np.ndarray), ``median``, ``p5``, ``p95``,
        ``p99``, ``max``, ``n_frames``.
    """
    all_vels = []
    for sd in session_dicts:
        for mouse, sess in sd.items():
            vel = getattr(sess, "velocities_miniscope_smooth", None)
            if vel is None:
                vel = getattr(sess, "velocities_miniscope", None)
            if vel is None:
                continue
            vel = np.asarray(vel, dtype=float)
            vel = vel[np.isfinite(vel)]
            if vel.size:
                all_vels.append(vel)

    if all_vels:
        all_vel = np.concatenate(all_vels)
        return {
            'all_vel':  all_vel,
            'median':   float(np.median(all_vel)),
            'p5':       float(np.percentile(all_vel, 5)),
            'p95':      float(np.percentile(all_vel, 95)),
            'p99':      float(np.percentile(all_vel, 99)),
            'max':      float(np.max(all_vel)),
            'n_frames': int(all_vel.size),
        }
    return {
        'all_vel': np.array([]), 'median': np.nan, 'p5': np.nan,
        'p95': np.nan, 'p99': np.nan, 'max': np.nan, 'n_frames': 0,
    }


def compute_continuity_params(
    vel_stats: dict,
    time_bin_frames: int,
    dt_sec: float = 1.0 / 30.0,
    speed_threshold: float = 2.0,
    margin: float = 1.5,
) -> dict:
    """
    Derive continuity-constraint sigma parameters from observed velocity data.

    With ``exp=1`` the transition prior width equals the expected displacement
    per time bin: ``sigma_t = v_t * dt_bin``.  The clamp parameters
    (min/max/default) are set to the displacement corresponding to the low,
    high, and typical velocities observed in the data.

    Parameters
    ----------
    vel_stats : dict
        Output of :func:`collect_velocity_stats` or
        :func:`plot_velocity_histograms`.
    time_bin_frames : int
        Number of miniscope frames per decoded time bin.
    dt_sec : float
        Duration of one miniscope frame in seconds (default 1/30).
    speed_threshold : float
        Mobility threshold in cm/s (frames below this are "immobile").
    margin : float
        Safety multiplier on the upper sigma bound so that the fastest
        real movements are not over-penalised (default 1.5).

    Returns
    -------
    params : dict
        Keys match the ``continuity_*`` arguments of the decoders.
    """
    dt_bin = time_bin_frames * dt_sec  # seconds per decoded chunk

    v_median = vel_stats['median']
    v_p95    = vel_stats['p95']
    v_p99    = vel_stats['p99']

    sigma_min     = speed_threshold * dt_bin        # floor: barely-mobile displacement
    sigma_max     = v_p99 * dt_bin * margin         # ceiling: fastest observed + margin
    sigma_default = v_median * dt_bin               # fallback: typical speed

    # With exp=1, sigma_t = sigma_k * (v_t / speed_ref).
    # Choose speed_ref = v_median  →  sigma_k = v_median * dt_bin = sigma_default.
    speed_ref = v_median
    sigma_k   = speed_ref * dt_bin

    params = {
        'continuity_sigma_k':       round(sigma_k, 3),
        'continuity_speed_ref':     round(speed_ref, 3),
        'continuity_exp':           1.0,
        'continuity_sigma_min':     round(sigma_min, 3),
        'continuity_sigma_max':     round(sigma_max, 3),
        'continuity_sigma_default': round(sigma_default, 3),
    }

    print(f"[CONTINUITY] dt_bin={dt_bin:.4f}s  "
          f"v_median={v_median:.1f}  v_p95={v_p95:.1f}  v_p99={v_p99:.1f} cm/s")
    print(f"[CONTINUITY] → sigma_k={params['continuity_sigma_k']:.3f}  "
          f"speed_ref={params['continuity_speed_ref']:.2f}  "
          f"sigma_min={params['continuity_sigma_min']:.3f}  "
          f"sigma_max={params['continuity_sigma_max']:.3f}  "
          f"sigma_default={params['continuity_sigma_default']:.3f}  (cm)")

    return params


def save_continuity_params_txt(params, save_dir, tag="", time_bin_frames=None, dt_sec=1.0/30.0):
    """Write computed continuity parameters to ``continuity_params.txt``."""
    os.makedirs(save_dir, exist_ok=True)
    path = os.path.join(save_dir, "continuity_params.txt")
    mode = "a" if os.path.exists(path) else "w"
    with open(path, mode, encoding="utf-8") as f:
        if tag:
            f.write(f"--- {tag} ---\n")
        if time_bin_frames is not None:
            dt_bin = time_bin_frames * dt_sec
            f.write(f"time_bin_frames : {time_bin_frames}\n")
            f.write(f"dt_bin_sec      : {dt_bin:.6f}\n")
        for k in ['continuity_sigma_k', 'continuity_speed_ref', 'continuity_exp',
                  'continuity_sigma_min', 'continuity_sigma_max', 'continuity_sigma_default']:
            f.write(f"{k:28s}: {params[k]}\n")
        f.write("\n")
    print(f"[CONTINUITY] Saved \u2192 {path}")


def plot_velocity_histograms(
    *session_dicts: dict,
    mouse_groups: dict,
    PLOTS_DIR: str,
    session_tags: tuple = None,
    auto_close: bool = True,
) -> dict:
    """
    Per-mouse and group-pooled velocity histograms.

    Accepts one or more session dicts (e.g. ``LT1_group, LT2_group`` or
    ``TFC_cond, Test_B, Test_B_1wk``).  Each dict is labelled by
    *session_tags* (defaults to ``("S1", "S2", ...)``).

    Returns
    -------
    vel_stats : dict
        Pooled velocity statistics (see :func:`collect_velocity_stats`).
    """
    n_dicts = len(session_dicts)
    if session_tags is None:
        session_tags = tuple(f"S{i+1}" for i in range(n_dicts))
    assert len(session_tags) == n_dicts

    save_dir = os.path.join(PLOTS_DIR, "velocity_histogram")
    os.makedirs(save_dir, exist_ok=True)

    vel_bins = np.arange(0, 62, 2)  # 0–60 cm/s in 2-cm/s bins

    # collect per-group velocities for the pooled plot
    group_vels = {tag: {g: [] for g in _PAPER_GROUP_ORDER} for tag in session_tags}
    all_vels = []

    for tag, sd in zip(session_tags, session_dicts):
        for mouse, sess in sd.items():
            grp = mouse_groups.get(mouse)
            if grp is None:
                continue

            vel = getattr(sess, "velocities_miniscope_smooth", None)
            if vel is None:
                vel = getattr(sess, "velocities_miniscope", None)
            if vel is None:
                print(f"[VEL-HIST] No velocity data for {mouse} {tag}, skipping")
                continue
            vel = np.asarray(vel, dtype=float)
            vel = vel[np.isfinite(vel)]

            group_vels[tag][grp].append(vel)
            all_vels.append(vel)

            # --- per-mouse histogram ---
            fig, ax = plt.subplots(figsize=(4.5, 3.0), dpi=200)
            ax.hist(vel, bins=vel_bins, color=_PAPER_COLORS.get(grp, "gray"),
                    alpha=0.7, edgecolor="white", linewidth=0.4)
            ax.axvline(2.0, color="red", ls="--", lw=0.8, label="speed thr (2 cm/s)")
            ax.set_xlabel("Velocity (cm/s)")
            ax.set_ylabel("Frame count")
            ax.set_title(f"{mouse}  ({_PAPER_LABELS.get(grp, grp)})  –  {tag}",
                         fontsize=9)
            ax.legend(fontsize=7, loc="upper right")
            fig.tight_layout()
            fig.savefig(os.path.join(save_dir, f"vel_hist_{mouse}_{tag}.png"), dpi=200)
            if auto_close:
                plt.close(fig)

    # --- group-pooled histograms ---
    for tag in session_tags:
        groups_present = [g for g in _PAPER_GROUP_ORDER if len(group_vels[tag][g]) > 0]
        if not groups_present:
            continue

        fig, axes = plt.subplots(1, len(groups_present),
                                 figsize=(4.0 * len(groups_present), 3.0),
                                 dpi=200, sharey=True)
        if len(groups_present) == 1:
            axes = [axes]

        for ax, grp in zip(axes, groups_present):
            pooled = np.concatenate(group_vels[tag][grp])
            ax.hist(pooled, bins=vel_bins, color=_PAPER_COLORS[grp],
                    alpha=0.7, edgecolor="white", linewidth=0.4, density=True)
            ax.axvline(2.0, color="red", ls="--", lw=0.8)
            ax.set_xlabel("Velocity (cm/s)")
            ax.set_title(f"{_PAPER_LABELS[grp]}  ({len(group_vels[tag][grp])} mice)",
                         fontsize=9)
        axes[0].set_ylabel("Density")
        fig.suptitle(f"Pooled velocity distribution – {tag}", fontsize=10, y=1.02)
        fig.tight_layout()
        fig.savefig(os.path.join(save_dir, f"vel_hist_group_{tag}.png"),
                    dpi=200, bbox_inches="tight")
        if auto_close:
            plt.close(fig)

    print(f"[VEL-HIST] Saved to {save_dir}")

    # --- compute pooled velocity statistics ---
    vel_stats = collect_velocity_stats(*session_dicts)

    print(f"[VEL-HIST] Pooled stats: median={vel_stats['median']:.1f}, "
          f"p95={vel_stats['p95']:.1f}, p99={vel_stats['p99']:.1f}, "
          f"max={vel_stats['max']:.1f} cm/s  (n={vel_stats['n_frames']} frames)")

    return vel_stats


# ---------------------------------------------------------------------------
#  Mobility-seconds boxplot (encoding vs decoding, by group)
# ---------------------------------------------------------------------------

def plot_mobility_seconds_boxplots(
    all_results: dict,
    mouse_groups: dict,
    PLOTS_DIR: str,
    train_label: str = "TFC_cond",
    decoder_tag: str = "2D",
    session_str: str = "",
    auto_close: bool = True,
):
    """
    Plot mobile seconds used for encoding and decoding as separate boxplots
    across the three DREADD groups.

    Builds a summary DataFrame internally from *all_results*.
    """
    import matplotlib.pyplot as plt
    from matplotlib.patches import Patch

    df_summary = build_decoder_summary_dataframe(
        all_results, mouse_groups, train_label=train_label)

    save_path = os.path.join(PLOTS_DIR,
                             f"mobility_seconds_{decoder_tag}_{train_label}_{session_str}")
    os.makedirs(save_path, exist_ok=True)

    # --- one figure per condition ---
    for cond in sorted(df_summary["condition"].unique()):
        dfc = df_summary[df_summary["condition"] == cond].copy()

        for sec_col, label in [("mobile_sec_train", "Encoding"),
                                ("mobile_sec_test",  "Decoding")]:
            if sec_col not in dfc.columns or dfc[sec_col].isna().all():
                continue

            grp_order = [g for g in _PAPER_GROUP_ORDER if g in dfc["group"].values]
            if not grp_order:
                continue

            fig, ax = plt.subplots(figsize=(3.5, 4.0), dpi=200)
            data_per_grp = [dfc.loc[dfc["group"] == g, sec_col].dropna().values
                            for g in grp_order]
            bp = ax.boxplot(data_per_grp, positions=range(len(grp_order)),
                            widths=0.55, patch_artist=True,
                            showfliers=False, showmeans=True,
                            meanprops=dict(marker="D", markersize=5,
                                           markerfacecolor="white",
                                           markeredgecolor="black"))
            for i, (patch, g) in enumerate(zip(bp["boxes"], grp_order)):
                c = _PAPER_COLORS.get(g, "#888888")
                patch.set_facecolor(c)
                patch.set_alpha(_PAPER_BOX_ALPHA)
                patch.set_edgecolor(c)
                jitter = np.random.default_rng(42).uniform(-0.12, 0.12,
                                                            size=len(data_per_grp[i]))
                ax.scatter(np.full(len(data_per_grp[i]), i) + jitter,
                           data_per_grp[i], s=_PAPER_SCATTER_SIZE,
                           c=_PAPER_DOT_COLORS.get(g, "#aaaaaa"),
                           edgecolors="none", alpha=0.8, zorder=3)

            ax.set_xticks(range(len(grp_order)))
            ax.set_xticklabels([_PAPER_LABELS.get(g, g) for g in grp_order],
                               fontsize=8)
            ax.set_ylabel(f"{label} mobile time (s)", fontsize=9)
            title_cond = cond.replace("_", " ")
            ax.set_title(f"{label} – {title_cond}", fontsize=9)
            ax.tick_params(axis="both", labelsize=8)
            fig.tight_layout()
            fname = (f"mobility_{sec_col}_{cond.replace(' ', '_')}.png")
            fig.savefig(os.path.join(save_path, fname), dpi=300)
            plt.show()
            if auto_close:
                plt.close(fig)

    print(f"[MOBILITY] Boxplots saved → {save_path}")


# ---------------------------------------------------------------------------
#  Multi-target stats & plots
# ---------------------------------------------------------------------------

def run_decoder_stats_and_plots(
    all_results: dict,
    mouse_groups: dict,
    PLOTS_DIR: str,
    train_label: str = "TFC_cond",
    session_str: str = "",
    decoder_tag: str = "2D",
    use_scoring_method: str = "euclidean",
    use_z_score: str = "none",
    use_median: bool = True,
    auto_close: bool = True,
    pct_threshold: float = 15.0,
    stat_label_override=None,
):
    """
    Build summary DataFrame, fit mixed-effects models, and generate
    group boxplot for multi-target decoding results.
    """
    methods = _normalize_scoring_methods(use_scoring_method)
    if len(methods) > 1:
        out = {}
        print("[MT-STATS] Running both scoring methods: euclidean + rsquared")
        for method in methods:
            out[method] = run_decoder_stats_and_plots(
                all_results,
                mouse_groups,
                PLOTS_DIR,
                train_label=train_label,
                session_str=session_str,
                decoder_tag=decoder_tag,
                use_scoring_method=method,
                use_z_score=use_z_score,
                use_median=use_median,
                auto_close=auto_close,
                pct_threshold=pct_threshold,
                stat_label_override=stat_label_override,
            )
        return out

    use_scoring_method = methods[0]
    stat_label = stat_label_override if stat_label_override else ("median" if use_median else "mean")
    z_tag = _z_score_dir_tag(use_z_score)
    score_tag = str(use_scoring_method).strip().lower()
    save_path = os.path.join(PLOTS_DIR,
                             f"multi_target_stats_{decoder_tag}_{train_label}_{session_str}_{stat_label}_{z_tag}_score_{score_tag}")
    os.makedirs(save_path, exist_ok=True)
    fe_save_path = os.path.join(
        PLOTS_DIR,
        f"fixed_effects_multi_target_stats_{decoder_tag}_{train_label}_{session_str}_{stat_label}_{z_tag}_score_{score_tag}",
    )
    os.makedirs(fe_save_path, exist_ok=True)

    def _write_methods_file(out_dir: str, analysis_name: str, methods_text: str):
        os.makedirs(out_dir, exist_ok=True)
        with open(os.path.join(out_dir, "METHODS_analysis_details.txt"), "w", encoding="utf-8") as f:
            f.write(f"{analysis_name}\n")
            f.write("=" * len(analysis_name) + "\n\n")
            f.write(methods_text.strip() + "\n")

    def _rewrite_analysis_index(root_dir: str):
        """Deterministically rewrite ANALYSIS_INDEX.txt from existing analysis folders."""
        os.makedirs(root_dir, exist_ok=True)
        idx_path = os.path.join(root_dir, "ANALYSIS_INDEX.txt")

        analysis_dirs = []
        for name in sorted(os.listdir(root_dir)):
            full = os.path.join(root_dir, name)
            if not os.path.isdir(full):
                continue
            if name.startswith("multi_target_stats_") or name.startswith("fixed_effects_multi_target_stats_"):
                analysis_dirs.append((name, full))

        with open(idx_path, "w", encoding="utf-8") as f:
            f.write("Decoder Analysis Index\n")
            f.write("======================\n\n")
            f.write("This file is regenerated deterministically from directories present in this folder.\n")
            f.write("\n")

            if not analysis_dirs:
                f.write("No multi-target analysis directories found.\n")
                return

            for name, full in analysis_dirs:
                f.write(f"{name}\n")
                f.write("-" * len(name) + "\n")
                f.write(f"Path: {full}\n")

                methods_file = os.path.join(full, "METHODS_analysis_details.txt")
                if os.path.exists(methods_file):
                    f.write(f"Methods: {methods_file}\n")

                summary_file = os.path.join(full, "mouse_summary.csv")
                if os.path.exists(summary_file):
                    f.write(f"Summary table: {summary_file}\n")

                # List direct sub-analysis folders deterministically.
                subdirs = []
                for subname in sorted(os.listdir(full)):
                    subdir = os.path.join(full, subname)
                    if os.path.isdir(subdir):
                        subdirs.append(subdir)
                for sub_dir in subdirs:
                    f.write(f"Sub-analysis: {sub_dir}\n")
                    sub_methods = os.path.join(sub_dir, "METHODS_analysis_details.txt")
                    if os.path.exists(sub_methods):
                        f.write(f"Sub-analysis methods: {sub_methods}\n")

                f.write("\n")

    df = build_decoder_summary_dataframe(all_results, mouse_groups,
                                               train_label=train_label,
                                               use_scoring_method=use_scoring_method,
                                               pct_threshold=pct_threshold)
    df.to_csv(os.path.join(save_path, "mouse_summary.csv"), index=False)
    df.to_csv(os.path.join(fe_save_path, "mouse_summary.csv"), index=False)
    print(f"[MT-STATS] Summary table ({len(df)} rows):")
    print(df.to_string(index=False))

    err_col = "pct_correct" if stat_label == "pct" else f"{stat_label}_err"
    df_model = df[np.isfinite(df[err_col])].copy()

    # --- Full model: err ~ group * condition + (1|mouse) ---
    model_full = None
    if len(df_model) > 3 and df_model["condition"].nunique() > 1 and df_model["group"].nunique() > 1:
        df_model["group"] = df_model["group"].astype("category")
        df_model["condition"] = df_model["condition"].astype("category")
        try:
            md = smf.mixedlm(f"{err_col} ~ group * condition", df_model,
                             groups=df_model["mouse"])
            model_full = md.fit(reml=False)
            with open(os.path.join(save_path, f"mixedlm_full.txt"), "w") as f:
                f.write(str(model_full.summary()))
            print(f"[MT-STATS] Full MixedLM saved.")
        except Exception as e:
            print(f"[MT-STATS] Full MixedLM failed: {e}")

    # --- Per-condition models: err ~ group + (1|mouse) ---
    model_per_cond = {}
    for cond in df_model["condition"].unique():
        dfc = df_model[df_model["condition"] == cond].copy()
        if len(dfc) >= 3 and dfc["group"].nunique() > 1:
            try:
                md2 = smf.mixedlm(f"{err_col} ~ group", dfc, groups=dfc["mouse"])
                mfit = md2.fit(reml=False)
                model_per_cond[cond] = mfit
                fname = f"mixedlm_{cond.replace(' ', '_')}.txt"
                with open(os.path.join(save_path, fname), "w") as f:
                    f.write(str(mfit.summary()))
            except Exception as e:
                print(f"[MT-STATS] MixedLM for '{cond}' failed: {e}")

    # --- Fixed-effects models (non-mixed): subject fixed effects via OLS ---
    fe_model_full = None
    if len(df_model) > 3 and df_model["condition"].nunique() > 1 and df_model["group"].nunique() > 1:
        try:
            df_fe = df_model.copy()
            df_fe["group"] = df_fe["group"].astype("category")
            df_fe["condition"] = df_fe["condition"].astype("category")
            df_fe["mouse"] = df_fe["mouse"].astype("category")

            # Subject fixed effects are included via C(mouse).
            fe_formula = f"{err_col} ~ group * condition + C(mouse)"
            fe_model_full = smf.ols(fe_formula, data=df_fe).fit(cov_type="HC3")
            with open(os.path.join(fe_save_path, "fixed_effects_full_ols.txt"), "w") as f:
                f.write(str(fe_model_full.summary()))
            print(f"[MT-STATS] Fixed-effects OLS saved.")
        except Exception as e:
            print(f"[MT-STATS] Fixed-effects OLS failed: {e}")

    fe_model_per_cond = {}
    for cond in df_model["condition"].unique():
        dfc = df_model[df_model["condition"] == cond].copy()
        if len(dfc) >= 3 and dfc["group"].nunique() > 1:
            try:
                # Per-condition between-group comparison (non-mixed OLS).
                fe_cond = smf.ols(f"{err_col} ~ group", data=dfc).fit(cov_type="HC3")
                fe_model_per_cond[cond] = fe_cond
                fname = f"fixed_effects_{cond.replace(' ', '_')}.txt"
                with open(os.path.join(fe_save_path, fname), "w") as f:
                    f.write(str(fe_cond.summary()))
            except Exception as e:
                print(f"[MT-STATS] Fixed-effects OLS for '{cond}' failed: {e}")

    # --- Fixed-effects model plots (analogous model-interpretation outputs) ---
    fe_plot_dir = os.path.join(fe_save_path, "model_plots")
    os.makedirs(fe_plot_dir, exist_ok=True)
    if fe_model_full is not None and len(df_model) > 0:
        try:
            # 1) Forest plot of fixed-effect terms (excluding mouse dummies).
            params = fe_model_full.params
            ci = fe_model_full.conf_int()
            keep_terms = [
                t for t in params.index
                if t != "Intercept" and ("C(mouse)" not in t)
            ]
            if keep_terms:
                ord_terms = sorted(keep_terms, key=lambda t: abs(float(params[t])), reverse=True)
                est = np.asarray([float(params[t]) for t in ord_terms], dtype=float)
                lo = np.asarray([float(ci.loc[t, 0]) for t in ord_terms], dtype=float)
                hi = np.asarray([float(ci.loc[t, 1]) for t in ord_terms], dtype=float)
                y = np.arange(len(ord_terms))

                fig, ax = plt.subplots(figsize=(8.5, max(3.0, 0.45 * len(ord_terms))), dpi=180)
                ax.errorbar(est, y, xerr=[est - lo, hi - est], fmt="o", color="#2f5c8a", ecolor="#7a7a7a", capsize=2)
                ax.axvline(0.0, color="black", ls="--", lw=1.0)
                ax.set_yticks(y)
                ax.set_yticklabels(ord_terms, fontsize=8)
                ax.set_xlabel(f"Effect on {err_col}")
                ax.set_title("Fixed-effects OLS terms (95% CI)")
                ax.grid(True, axis="x", alpha=0.2)
                fig.tight_layout()
                fig.savefig(os.path.join(fe_plot_dir, f"fixed_effects_terms_forest_{stat_label}.png"), dpi=300)
                if auto_close:
                    plt.close(fig)

            # 2) Model-predicted means by condition and group.
            cond_levels = sorted(df_model["condition"].astype(str).unique(), key=lambda c: (0 if c.startswith("within") else 1, c))
            grp_levels = [g for g in ["mCherry", "hM3D", "hM4D"] if g in set(df_model["group"].astype(str))]
            mouse_levels = sorted(df_model["mouse"].astype(str).unique())
            ref_mouse = mouse_levels[0] if mouse_levels else "mouse_ref"

            pred_rows = []
            for cond in cond_levels:
                for grp in grp_levels:
                    new_df = pd.DataFrame({"group": [grp], "condition": [cond], "mouse": [ref_mouse]})
                    sf = fe_model_full.get_prediction(new_df).summary_frame(alpha=0.05).iloc[0]
                    pred_rows.append({
                        "condition": cond,
                        "group": grp,
                        "mean": float(sf["mean"]),
                        "ci_low": float(sf["mean_ci_lower"]),
                        "ci_high": float(sf["mean_ci_upper"]),
                    })

            df_pred = pd.DataFrame(pred_rows)
            if len(df_pred) > 0:
                df_pred.to_csv(os.path.join(fe_plot_dir, "fixed_effects_predicted_means.csv"), index=False)
                x = np.arange(len(cond_levels))
                fig, ax = plt.subplots(figsize=(max(7.5, 1.4 * len(cond_levels)), 4.8), dpi=180)
                colors = {"mCherry": "#3f3f3f", "hM3D": "#c44e52", "hM4D": "#4c72b0"}
                for grp in grp_levels:
                    dfg = df_pred[df_pred["group"] == grp].copy()
                    dfg = dfg.set_index("condition").reindex(cond_levels).reset_index()
                    y = dfg["mean"].values.astype(float)
                    lo = dfg["ci_low"].values.astype(float)
                    hi = dfg["ci_high"].values.astype(float)
                    ax.errorbar(
                        x, y,
                        yerr=[y - lo, hi - y],
                        marker="o", lw=1.8, capsize=3,
                        color=colors.get(grp, "gray"), label=grp,
                    )
                ax.set_xticks(x)
                ax.set_xticklabels([c.replace("_", "\n") for c in cond_levels], fontsize=8)
                ax.set_ylabel(f"Predicted {err_col}")
                ax.set_title("Fixed-effects OLS predicted means by group and condition")
                ax.grid(True, axis="y", alpha=0.2)
                ax.spines["top"].set_visible(False)
                ax.spines["right"].set_visible(False)
                ax.legend(frameon=False, fontsize=8)
                fig.tight_layout()
                fig.savefig(os.path.join(fe_plot_dir, f"fixed_effects_predicted_means_{stat_label}.png"), dpi=300)
                if auto_close:
                    plt.close(fig)
        except Exception as e:
            print(f"[MT-STATS] Fixed-effects plotting failed: {e}")

    # --- Repeated-measures style analysis (subject fixed effects) ---
    rm_save_path = os.path.join(fe_save_path, "repeated_measures_style_subject_fixed_effects")
    os.makedirs(rm_save_path, exist_ok=True)

    if len(df_model) > 0:
        cond_order_rm = sorted(df_model["condition"].unique(), key=lambda c: (0 if str(c).startswith("within") else 1, str(c)))
        grp_order_rm = [g for g in ["mCherry", "hM3D", "hM4D"] if g in set(df_model["group"].astype(str))]
        if grp_order_rm and cond_order_rm:
            fig, axes = plt.subplots(1, len(grp_order_rm), figsize=(4.2 * len(grp_order_rm), 4.2), dpi=180, sharey=True)
            if len(grp_order_rm) == 1:
                axes = [axes]

            x_map = {c: i for i, c in enumerate(cond_order_rm)}
            colors_rm = {"mCherry": "#3f3f3f", "hM3D": "#c44e52", "hM4D": "#4c72b0"}

            for ax, grp in zip(axes, grp_order_rm):
                dfg = df_model[df_model["group"] == grp].copy()
                # Individual mouse trajectories across available conditions.
                for mouse, dmouse in dfg.groupby("mouse"):
                    dmouse = dmouse.sort_values("condition", key=lambda s: s.map(lambda v: x_map.get(v, 10**6)))
                    x = [x_map[c] for c in dmouse["condition"].values if c in x_map]
                    y = [float(v) for c, v in zip(dmouse["condition"].values, dmouse[err_col].values) if c in x_map and np.isfinite(v)]
                    if len(x) >= 2:
                        ax.plot(x, y, color=colors_rm.get(grp, "gray"), alpha=0.25, lw=1.0)
                    if len(x) >= 1:
                        ax.scatter(x, y, color=colors_rm.get(grp, "gray"), alpha=0.35, s=18)

                # Group means per condition.
                means = []
                ses = []
                xs = []
                for c in cond_order_rm:
                    vals = dfg.loc[dfg["condition"] == c, err_col].dropna().values
                    if vals.size == 0:
                        continue
                    xs.append(x_map[c])
                    means.append(float(np.nanmean(vals)))
                    ses.append(float(np.nanstd(vals, ddof=1) / np.sqrt(max(vals.size, 1))) if vals.size > 1 else 0.0)
                if xs:
                    ax.errorbar(xs, means, yerr=ses, color=colors_rm.get(grp, "gray"), marker="o", lw=2.0, capsize=3)

                ax.set_title(str(grp), fontsize=10)
                ax.set_xticks(range(len(cond_order_rm)))
                ax.set_xticklabels([str(c).replace("_", "\n") for c in cond_order_rm], fontsize=8)
                ax.grid(True, alpha=0.2, axis="y")
                ax.spines["top"].set_visible(False)
                ax.spines["right"].set_visible(False)

            method_rm = str(use_scoring_method).strip().lower()
            if method_rm == "rsquared":
                axes[0].set_ylabel(f"{stat_label.capitalize()} R^2 (variance accounted for)")
            else:
                axes[0].set_ylabel(_euclidean_error_title(stat_label))
            fig.suptitle("Repeated-measures style: subject trajectories + group means", fontsize=11)
            fig.tight_layout()
            fig.savefig(os.path.join(rm_save_path, f"rm_style_subject_fe_{stat_label}.png"), dpi=300)
            if auto_close:
                plt.close(fig)

    rm_methods_text = f"""
Analysis objective
This analysis summarizes decoder performance using a repeated-measures style view of the data, where each mouse contributes multiple observations across decoding conditions.

Data unit and outcome
- Unit of analysis: mouse-by-condition summary.
- Outcome analyzed: {err_col}.
- Conditions include within-session decoding and cross-session target decoding.

Modeling rationale
Because observations from the same mouse are not independent, we visualize and model within-mouse condition structure explicitly. This directory focuses on subject-level repeated structure using mouse-specific trajectories and group-level summaries.

What is computed
1) Per-mouse trajectories across conditions within each manipulation group.
2) Group means and standard errors across mice for each condition.
3) Complementary fixed-effects model outputs are saved in the parent fixed-effects directory, where subject identity is included as C(mouse).

Interpretation guidance
This repeated-measures style plot is descriptive and emphasizes within-subject patterning and group-level trends. Formal inferential tests are provided in dedicated model outputs (fixed-effects OLS, ANOVA tables, and post hoc contrasts).
"""
    _write_methods_file(rm_save_path,
                        "Repeated-measures style decoder analysis",
                        rm_methods_text)

    # --- ANOVA from fixed-effects OLS + post hoc contrasts (Holm/FDR) ---
    anova_save_path = os.path.join(fe_save_path, "anova_posthoc")
    os.makedirs(anova_save_path, exist_ok=True)
    df_post = pd.DataFrame()  # initialised before the try block so it is always in scope

    if fe_model_full is not None:
        from statsmodels.stats.anova import anova_lm
        from statsmodels.stats.multitest import multipletests

        # Type-II ANOVA on the fixed-effects OLS fit.
        try:
            anova_tbl = anova_lm(fe_model_full, typ=2)
            anova_tbl.to_csv(os.path.join(anova_save_path, "anova_type2_table.csv"))
        except Exception as e:
            print(f"[MT-STATS] ANOVA table failed: {e}")
            anova_tbl = None

        # Post hoc contrasts from OLS fixed-effects model:
        # pairwise group differences within each condition.
        try:
            cond_levels = sorted(df_model["condition"].unique(), key=lambda c: (0 if str(c).startswith("within") else 1, str(c)))
            grp_levels = [g for g in ["mCherry", "hM3D", "hM4D"] if g in set(df_model["group"].astype(str))]
            mouse_levels = sorted(df_model["mouse"].astype(str).unique())
            ref_mouse = mouse_levels[0] if mouse_levels else "mouse_ref"

            di = fe_model_full.model.data.design_info

            def _row_vec(group_name: str, cond_name: str):
                new_df = pd.DataFrame({
                    "group": [group_name],
                    "condition": [cond_name],
                    "mouse": [ref_mouse],
                })
                ex = dmatrix(di, new_df, return_type="dataframe")
                # Align to model coefficient order.
                ex = ex.reindex(columns=fe_model_full.params.index, fill_value=0.0)
                return np.asarray(ex.iloc[0], dtype=float)

            posthoc_rows = []
            for cond in cond_levels:
                for i in range(len(grp_levels)):
                    for j in range(i + 1, len(grp_levels)):
                        g1 = grp_levels[i]
                        g2 = grp_levels[j]
                        L = _row_vec(g1, cond) - _row_vec(g2, cond)
                        t_res = fe_model_full.t_test(L)
                        est = float(np.squeeze(t_res.effect))
                        se = float(np.squeeze(t_res.sd))
                        p_raw = float(np.squeeze(t_res.pvalue))
                        zcrit = 1.96
                        posthoc_rows.append({
                            "condition": cond,
                            "contrast": f"{g1} - {g2}",
                            "estimate": est,
                            "se": se,
                            "ci_low": est - zcrit * se,
                            "ci_high": est + zcrit * se,
                            "p_raw": p_raw,
                        })

            df_post = pd.DataFrame(posthoc_rows)
            if len(df_post) > 0:
                rej_holm, p_holm, _, _ = multipletests(df_post["p_raw"].values, method="holm")
                rej_fdr, p_fdr, _, _ = multipletests(df_post["p_raw"].values, method="fdr_bh")
                df_post["p_holm"] = p_holm
                df_post["sig_holm"] = rej_holm
                df_post["p_fdr_bh"] = p_fdr
                df_post["sig_fdr_bh"] = rej_fdr
                df_post.to_csv(os.path.join(anova_save_path, "posthoc_group_contrasts_within_condition.csv"), index=False)

                # Separate plot: ANOVA term significance + posthoc contrast forest.
                fig, (ax1, ax2) = plt.subplots(1, 2, figsize=(13, 4.8), dpi=180)

                if anova_tbl is not None and "PR(>F)" in anova_tbl.columns:
                    anova_plot = anova_tbl.copy()
                    anova_plot = anova_plot[np.isfinite(anova_plot["PR(>F)"])]
                    if len(anova_plot) > 0:
                        terms = list(anova_plot.index.astype(str))
                        pvals = np.clip(np.asarray(anova_plot["PR(>F)"], dtype=float), 1e-300, 1.0)
                        score = -np.log10(pvals)
                        ax1.barh(range(len(terms)), score, color="#6d8fb3")
                        ax1.axvline(-np.log10(0.05), color="red", ls="--", lw=1.0)
                        ax1.set_yticks(range(len(terms)))
                        ax1.set_yticklabels(terms, fontsize=8)
                        ax1.set_xlabel("-log10(p)")
                        ax1.set_title("ANOVA (Type II) terms")
                    else:
                        ax1.text(0.5, 0.5, "No ANOVA terms", ha="center", va="center")
                        ax1.set_axis_off()
                else:
                    ax1.text(0.5, 0.5, "ANOVA unavailable", ha="center", va="center")
                    ax1.set_axis_off()

                dfp = df_post.copy()
                dfp["label"] = dfp["condition"].astype(str) + " | " + dfp["contrast"].astype(str)
                dfp = dfp.sort_values("estimate")
                y = np.arange(len(dfp))
                colors = np.where(dfp["sig_holm"].values, "#c44e52", "#4c72b0")
                ax2.errorbar(
                    dfp["estimate"].values,
                    y,
                    xerr=[dfp["estimate"].values - dfp["ci_low"].values,
                          dfp["ci_high"].values - dfp["estimate"].values],
                    fmt="none", ecolor="0.5", elinewidth=1.0, capsize=2,
                )
                ax2.scatter(dfp["estimate"].values, y, c=colors, s=28)
                ax2.axvline(0.0, color="black", ls="--", lw=1.0)
                ax2.set_yticks(y)
                ax2.set_yticklabels(dfp["label"].tolist(), fontsize=7)
                ax2.set_xlabel("Contrast estimate (group difference)")
                ax2.set_title("Post hoc contrasts (Holm highlighted)")

                fig.tight_layout()
                fig.savefig(os.path.join(anova_save_path, f"anova_posthoc_{stat_label}.png"), dpi=300)
                if auto_close:
                    plt.close(fig)
        except Exception as e:
            print(f"[MT-STATS] ANOVA/posthoc failed: {e}")

    anova_methods_text = f"""
Analysis objective
This analysis quantifies condition and group effects on decoder performance using a fixed-effects linear model and ANOVA decomposition, then performs post hoc contrasts with multiplicity control.

Data unit and outcome
- Unit of analysis: mouse-by-condition summary.
- Outcome analyzed: {err_col}.

Primary fixed-effects model
The model is:
    {err_col} ~ group * condition + C(mouse)
where C(mouse) introduces subject fixed effects to account for stable between-mouse offsets.

ANOVA table
ANOVA is computed from the fitted fixed-effects OLS model (Type II sum-of-squares in this implementation). This provides term-level tests for group, condition, and interaction effects.

Post hoc contrasts
Post hoc tests are model-based linear contrasts comparing groups within each condition. For each contrast, the estimate, standard error, confidence interval, and p-value are reported.

Multiple comparisons
Adjusted p-values are reported using:
- Holm family-wise error control (p_holm)
- Benjamini-Hochberg FDR control (p_fdr_bh)

Interpretation guidance
ANOVA provides omnibus evidence for factor effects, while post hoc contrasts localize where differences occur. Holm-adjusted significance is emphasized for stricter family-wise control.
"""
    _write_methods_file(anova_save_path,
                        "ANOVA and post hoc decoder analysis",
                        anova_methods_text)

    mixedlm_methods_text = f"""
Analysis objective
This directory contains mixed-effects model analyses for decoder performance.

Model
The full model uses a random intercept for mouse:
    {err_col} ~ group * condition + (1 | mouse)

Rationale
This model treats mouse as a sampled subject-level effect and estimates between-subject variance directly, supporting subject-specific inference under mixed-model assumptions.

Outputs
- Full mixed model summary
- Per-condition mixed models (group effect within each condition)
- Summary table used for model fitting
"""
    _write_methods_file(save_path,
                        "Mixed-effects decoder analysis",
                        mixedlm_methods_text)

    fe_methods_text = f"""
Analysis objective
This directory contains fixed-effects (non-mixed) decoder analyses.

Models
1) Full subject fixed-effects OLS:
   {err_col} ~ group * condition + C(mouse)
2) Per-condition OLS:
   {err_col} ~ group

Rationale
Subject fixed effects absorb stable between-mouse offsets without estimating a random-effect distribution. This can be useful when emphasizing within-sample subject adjustment.

Outputs
- Full OLS summary with subject fixed effects
- Per-condition OLS summaries
- Summary table used for modeling
"""
    _write_methods_file(fe_save_path,
                        "Fixed-effects decoder analysis",
                        fe_methods_text)

    fe_plot_methods_text = f"""
Analysis objective
This subdirectory provides model-interpretation plots for the fixed-effects OLS model.

Plots produced
1) Fixed-effects terms forest plot:
   Estimates and 95% confidence intervals for non-mouse terms (group, condition, interactions).

2) Predicted means plot:
   Model-predicted {err_col} by group and condition with 95% confidence intervals.

Implementation details
- Predictions are generated from the fitted fixed-effects OLS model.
- Subject fixed effects are included in model fitting via C(mouse).
- For plotting group/condition profiles, predictions are evaluated at a reference mouse level,
  so contrasts reflect fixed-effects structure while keeping subject indicator fixed.
"""
    _write_methods_file(fe_plot_dir,
                        "Fixed-effects model plots",
                        fe_plot_methods_text)

    # --- Deterministic top-level audit index (one file in the paradigm root dir) ---
    _rewrite_analysis_index(PLOTS_DIR)

    # --- Multi-target boxplot ---
    _plot_decoder_group_boxplot(df, err_col, save_path,
                                     session_str=session_str,
                                     train_label=train_label,
                                     decoder_tag=decoder_tag,
                                     use_scoring_method=use_scoring_method,
                                     stat_label=stat_label,
                                     auto_close=auto_close)

    # --- Paper-quality boxplot with significance brackets ---
    _plot_decoder_group_boxplot_paper(df, err_col, save_path,
                                           session_str=session_str,
                                           train_label=train_label,
                                           decoder_tag=decoder_tag,
                                           use_scoring_method=use_scoring_method,
                                           stat_label=stat_label,
                                           auto_close=auto_close)

    # --- Paper boxplots for new analysis-specific directories ---
    # Build model-based between-group p-value dicts for FE and posthoc annotations.
    from itertools import combinations as _combs
    from statsmodels.stats.multitest import multipletests as _mt

    # Fixed-effects per-condition OLS contrasts → fe_pvals
    fe_pvals = {}
    if fe_model_per_cond:
        _fe_groups = [g for g in ["mCherry", "hM3D", "hM4D"]
                      if g in set(df_model["group"].astype(str))]
        for _cond, _cond_model in fe_model_per_cond.items():
            try:
                _pnames = list(_cond_model.params.index)
                _raw_ps, _pair_info = [], []
                for _g1, _g2 in _combs(_fe_groups, 2):
                    _L = np.zeros(len(_pnames))
                    for _i, _p in enumerate(_pnames):
                        if _p == f"group[T.{_g1}]":
                            _L[_i] = 1.0
                        elif _p == f"group[T.{_g2}]":
                            _L[_i] = -1.0
                    try:
                        _t = _cond_model.t_test(_L)
                        _p_raw = float(np.squeeze(_t.pvalue))
                    except Exception:
                        _p_raw = 1.0
                    _raw_ps.append(_p_raw)
                    _pair_info.append((_g1, _g2, _p_raw))
                if _raw_ps:
                    _, _p_holm_arr, _, _ = _mt(_raw_ps, method="holm")
                else:
                    _p_holm_arr = np.array([])
                fe_pvals[_cond] = [
                    {"g1": _g1, "g2": _g2, "p_raw": _pr,
                     "p_holm": float(_p_holm_arr[_k]) if _k < len(_p_holm_arr) else 1.0}
                    for _k, (_g1, _g2, _pr) in enumerate(_pair_info)
                ]
            except Exception as _e:
                print(f"[MT-STATS] fe_pvals build failed for {_cond}: {_e}")

    # Model-based posthoc contrasts → posthoc_pvals
    posthoc_pvals = {}
    if len(df_post) > 0:
        for _cond in df_post["condition"].unique():
            _dc = df_post[df_post["condition"] == _cond]
            _pairs = []
            for _, _row in _dc.iterrows():
                _parts = str(_row["contrast"]).split(" - ")
                if len(_parts) == 2:
                    _pairs.append({
                        "g1": _parts[0].strip(),
                        "g2": _parts[1].strip(),
                        "p_raw": float(_row["p_raw"]),
                        "p_holm": float(_row["p_holm"]),
                    })
            if _pairs:
                posthoc_pvals[_cond] = _pairs

    _paper_kw = dict(session_str=session_str, train_label=train_label,
                     decoder_tag=decoder_tag, stat_label=stat_label,
                     auto_close=auto_close)

    # Fixed-effects dir: Panel A brackets from per-cond OLS contrasts, Panel B paired t-tests.
    _plot_decoder_group_boxplot_paper(
        df, err_col, fe_save_path,
        between_pvals=fe_pvals if fe_pvals else None,
        **_paper_kw)

    # ANOVA/posthoc dir: Panel A brackets from model-based posthoc contrasts.
    _plot_decoder_group_boxplot_paper(
        df, err_col, anova_save_path,
        between_pvals=posthoc_pvals if posthoc_pvals else None,
        **_paper_kw)

    # RM-style dir: standard t-test brackets (paired Panel B already reflects RM structure).
    _plot_decoder_group_boxplot_paper(
        df, err_col, rm_save_path,
        **_paper_kw)

    return df, model_full, model_per_cond


def _plot_decoder_group_boxplot(
    df, err_col, save_path, *,
    session_str="", train_label="", decoder_tag="2D",
    use_scoring_method: str = "euclidean",
    stat_label="median", auto_close=True,
):
    """
    Grouped boxplot: X = condition, hue = manipulation group, Y = error.
    Dynamically adapts to any set of conditions.
    """
    def _compute_broken_axis_limits(values: np.ndarray) -> Optional[Dict[str, Tuple[float, float]]]:
        vals = np.asarray(values, float)
        vals = vals[np.isfinite(vals)]
        if vals.size < 10:
            return None
        vmin = float(np.nanmin(vals))
        main_low = float(np.nanpercentile(vals, 15))
        tail_high = float(np.nanpercentile(vals, 5))
        main_high = float(np.nanpercentile(vals, 98))
        if not np.isfinite(vmin + main_low + tail_high + main_high):
            return None
        if (main_low - tail_high) < 1.0:
            return None
        if vmin >= (tail_high - 1e-9):
            return None

        low_span = max(tail_high - vmin, 1.0)
        main_span = max(main_high - main_low, 1.0)
        lower = (vmin - 0.08 * low_span, tail_high + 0.05 * low_span)
        upper = (main_low - 0.08 * main_span, main_high + 0.08 * main_span)
        if lower[1] >= upper[0]:
            return None
        return {"lower": lower, "upper": upper}

    def _add_break_marks(ax_top, ax_bottom):
        d = 0.008
        kwargs = dict(color='k', clip_on=False, linewidth=0.8)
        ax_top.plot((-d, +d), (-d, +d), transform=ax_top.transAxes, **kwargs)
        ax_top.plot((1 - d, 1 + d), (-d, +d), transform=ax_top.transAxes, **kwargs)
        ax_bottom.plot((-d, +d), (1 - d, 1 + d), transform=ax_bottom.transAxes, **kwargs)
        ax_bottom.plot((1 - d, 1 + d), (1 - d, 1 + d), transform=ax_bottom.transAxes, **kwargs)

    group_order = ["mCherry", "hM3D", "hM4D"]
    colors = {"mCherry": "black", "hM3D": "red", "hM4D": "blue"}

    # Sort conditions: within first, then alphabetical targets
    all_conds = sorted(df["condition"].unique(),
                       key=lambda c: (0 if c.startswith("within") else 1, c))

    n_cond = len(all_conds)
    n_groups = len(group_order)
    width = 0.22
    x_base = np.arange(n_cond)

    fig, ax = plt.subplots(figsize=(max(8, 3 * n_cond), 6), dpi=150)

    def _draw_grouped_boxplot(_ax):
        for gi, grp in enumerate(group_order):
            positions = x_base + (gi - 1) * width
            data_per_cond = []
            for ci, cond in enumerate(all_conds):
                vals = df.loc[(df["group"] == grp) & (df["condition"] == cond), err_col].dropna().values
                data_per_cond.append(vals)
            bp = _ax.boxplot(
                data_per_cond, positions=positions, widths=width * 0.85,
                patch_artist=True, showfliers=False,
            )
            for patch in bp["boxes"]:
                patch.set_facecolor(colors.get(grp, "gray"))
                patch.set_alpha(0.5)
            for ml in bp["medians"]:
                ml.set_color("black")

            for ci, cond in enumerate(all_conds):
                vals = df.loc[(df["group"] == grp) & (df["condition"] == cond), err_col].dropna().values
                # Deterministic jitter for reproducible companion plots
                rng = np.random.default_rng(42 + gi * 100 + ci)
                jitter = rng.uniform(-width * 0.2, width * 0.2, size=vals.size)
                _ax.scatter(np.full(vals.size, positions[ci]) + jitter, vals,
                            color=colors.get(grp, "gray"), s=30, zorder=5,
                            edgecolors="white", linewidths=0.5)

    _draw_grouped_boxplot(ax)

    ax.set_xticks(x_base)
    ax.set_xticklabels([c.replace("_", "\n") for c in all_conds], fontsize=9)
    method = str(use_scoring_method).strip().lower()
    if method == "rsquared":
        ax.set_ylabel(f"{stat_label.capitalize()} R^2 (variance accounted for)")
    else:
        ax.set_ylabel(_euclidean_error_title(stat_label))
    ax.set_title(f"{decoder_tag} decoding — train {train_label} — {session_str}")

    from matplotlib.patches import Patch
    legend_handles = [Patch(facecolor=colors[g], alpha=0.5, label=g) for g in group_order]
    ax.legend(handles=legend_handles, loc="upper left")
    ax.grid(True, alpha=0.15, axis="y")
    ax.spines["right"].set_visible(False); ax.spines["top"].set_visible(False)
    fig.tight_layout()
    fig.savefig(os.path.join(save_path, f"multi_target_boxplot_{stat_label}.png"), dpi=300)

    # Optional companion for rsquared runs: broken-axis view for large negative tails.
    if method == "rsquared":
        lims = _compute_broken_axis_limits(df[err_col].values)
        if lims is not None:
            fig_b, (ax_top, ax_bot) = plt.subplots(
                2, 1, sharex=True,
                figsize=(max(8, 3 * n_cond), 6.8), dpi=150,
                gridspec_kw={"height_ratios": [3.0, 1.2], "hspace": 0.05},
            )
            _draw_grouped_boxplot(ax_top)
            _draw_grouped_boxplot(ax_bot)

            ax_top.set_ylim(*lims["upper"])
            ax_bot.set_ylim(*lims["lower"])

            ax_top.set_ylabel(f"{stat_label.capitalize()} R^2 (variance accounted for)")
            ax_top.set_title(f"{decoder_tag} decoding — train {train_label} — {session_str} (broken-axis)")
            ax_bot.set_xticks(x_base)
            ax_bot.set_xticklabels([c.replace("_", "\n") for c in all_conds], fontsize=9)

            for a in (ax_top, ax_bot):
                a.grid(True, alpha=0.15, axis="y")
                a.spines["right"].set_visible(False)
                a.spines["top"].set_visible(False)

            ax_top.spines["bottom"].set_visible(False)
            ax_bot.spines["top"].set_visible(False)
            ax_top.tick_params(labelbottom=False)
            _add_break_marks(ax_top, ax_bot)

            ax_top.legend(handles=legend_handles, loc="upper left")
            fig_b.tight_layout()
            fig_b.savefig(
                os.path.join(save_path, f"multi_target_boxplot_{stat_label}_broken_axis.png"),
                dpi=300,
            )
            if auto_close:
                plt.close(fig_b)
            print("[MT-STATS] Broken-axis companion plot saved.")

    plt.show()
    if auto_close:
        plt.close(fig)
    print(f"[MT-STATS] Multi-target boxplot saved.")


