def _p_to_star(p_holm, p_raw):
    """Return (star_label, fontsize) or (None, None) if not significant."""
    if p_holm < 0.001:
        return "***", 9
    elif p_holm < 0.01:
        return "**", 9
    elif p_holm < 0.05:
        return "*", 9
    elif 0.05 <= p_raw <= 0.08:
        return f"p={p_raw:.2f}", 7.5
    return None, None


