def _build_cond_label_map(all_conds):
    """Condition string → nice multi-line label."""
    m = {}
    for c in all_conds:
        if c.startswith("within_"):
            m[c] = "Within\n" + c.replace("within_", "").replace("_", " ")
        elif "_to_" in c:
            parts = c.split("_to_")
            m[c] = (parts[0].replace("_", " ") + " →\n"
                    + parts[1].replace("_", " "))
        else:
            m[c] = c.replace("_", " ")
    return m


def _sort_conditions(conds):
    """Within first, then alphabetical targets."""
    return sorted(conds, key=lambda c: (0 if c.startswith("within") else 1, c))


def _plot_decoder_group_boxplot_paper_between_broken_axis(
    df,
    err_col,
    save_path,
    *,
    stat_label,
    y_label,
    all_conds,
    cond_label,
    groups_present,
    auto_close=True,
):
    """Companion broken-axis version of paper Panel A (between-group)."""
    vals = np.asarray(df[err_col].values, float)
    vals = vals[np.isfinite(vals)]
    if vals.size < 10:
        return

    vmin = float(np.nanmin(vals))
    main_low = float(np.nanpercentile(vals, 15))
    tail_high = float(np.nanpercentile(vals, 5))
    main_high = float(np.nanpercentile(vals, 98))
    if (main_low - tail_high) < 1.0 or vmin >= (tail_high - 1e-9):
        return

    low_span = max(tail_high - vmin, 1.0)
    main_span = max(main_high - main_low, 1.0)
    lower_ylim = (vmin - 0.08 * low_span, tail_high + 0.05 * low_span)
    upper_ylim = (main_low - 0.08 * main_span, main_high + 0.08 * main_span)
    if lower_ylim[1] >= upper_ylim[0]:
        return

    box_pos = {}
    tick_pos = []
    tick_labels_a = []
    x_cur = 0.0
    for ci, cond in enumerate(all_conds):
        for gi, grp in enumerate(groups_present):
            box_pos[(ci, gi)] = x_cur
            tick_pos.append(x_cur)
            tick_labels_a.append(cond_label.get(cond, cond))
            x_cur += 1.0
        x_cur += 0.5

    _BP_KW = dict(
        patch_artist=True,
        showfliers=False,
        medianprops=dict(color="black", lw=1.0),
        whiskerprops=dict(color="black", lw=0.6),
        capprops=dict(color="black", lw=0.6),
    )

    def _style_bp(bp, grp):
        for patch in bp["boxes"]:
            patch.set_facecolor(_PAPER_COLORS[grp])
            patch.set_alpha(_PAPER_BOX_ALPHA)
            patch.set_edgecolor("black")
            patch.set_linewidth(0.6)

    def _draw(ax):
        bw = 0.60
        for gi, grp in enumerate(groups_present):
            for ci, c in enumerate(all_conds):
                xp = box_pos[(ci, gi)]
                vals_c = df.loc[(df["group"] == grp) & (df["condition"] == c), err_col].dropna().values
                if vals_c.size == 0:
                    continue
                bp = ax.boxplot([vals_c], positions=[xp], widths=bw, **_BP_KW)
                _style_bp(bp, grp)
                rng = np.random.default_rng(42 + gi * 100 + ci)
                jit = rng.uniform(-bw * 0.18, bw * 0.18, size=vals_c.size)
                ax.scatter(
                    xp + jit,
                    vals_c,
                    color=_PAPER_DOT_COLORS.get(grp, "gray"),
                    s=18,
                    zorder=5,
                    edgecolors="white",
                    linewidths=0.25,
                )

    fig_w = max(4.0, 0.55 * (tick_pos[-1] - tick_pos[0] + 1))
    fig, (ax_top, ax_bot) = plt.subplots(
        2, 1, sharex=True,
        figsize=(fig_w, 4.6), dpi=300,
        gridspec_kw={"height_ratios": [3.0, 1.2], "hspace": 0.05},
    )
    _draw(ax_top)
    _draw(ax_bot)

    ax_top.set_ylim(*upper_ylim)
    ax_bot.set_ylim(*lower_ylim)
    ax_top.set_xlim(tick_pos[0] - 0.5, tick_pos[-1] + 0.5)
    ax_bot.set_xlim(tick_pos[0] - 0.5, tick_pos[-1] + 0.5)

    ax_top.set_ylabel(y_label, fontsize=8)
    ax_bot.set_xticks(tick_pos)
    ax_bot.set_xticklabels(tick_labels_a, fontsize=5.5, rotation=-30, ha="left")

    for a in (ax_top, ax_bot):
        a.grid(True, alpha=0.15, axis="y")
        a.tick_params(axis="both", which="both", labelsize=7, length=3, width=0.6, pad=2)
        a.spines["right"].set_visible(False)
        a.spines["top"].set_visible(False)

    ax_top.spines["bottom"].set_visible(False)
    ax_bot.spines["top"].set_visible(False)
    ax_top.tick_params(labelbottom=False)

    d = 0.008
    kwargs = dict(color='k', clip_on=False, linewidth=0.8)
    ax_top.plot((-d, +d), (-d, +d), transform=ax_top.transAxes, **kwargs)
    ax_top.plot((1 - d, 1 + d), (-d, +d), transform=ax_top.transAxes, **kwargs)
    ax_bot.plot((-d, +d), (1 - d, 1 + d), transform=ax_bot.transAxes, **kwargs)
    ax_bot.plot((1 - d, 1 + d), (1 - d, 1 + d), transform=ax_bot.transAxes, **kwargs)

    from matplotlib.patches import Patch
    handles = [Patch(facecolor=_PAPER_COLORS[g], alpha=_PAPER_BOX_ALPHA,
                     edgecolor="black", lw=0.6,
                     label=_PAPER_LABELS.get(g, g))
               for g in groups_present]
    ax_top.legend(handles=handles, loc="upper right", fontsize=6.5,
                  frameon=True, framealpha=0.9, edgecolor="none",
                  handlelength=1.0, handletextpad=0.4, borderpad=0.3)
    ax_top.set_title("Panel A (between-group, broken-axis)", fontsize=8)

    fig.tight_layout(pad=0.3)
    for ext in (".png", ".svg"):
        fig.savefig(os.path.join(save_path, f"panelA_between_group_{stat_label}_paper_broken_axis{ext}"),
                    dpi=300, bbox_inches="tight")
    plt.show()
    if auto_close:
        plt.close(fig)
    print(f"[MT-STATS] Panel A (between-group, broken-axis) saved → {save_path}")


# =====================================================================
#  Unified paper boxplot panel (Panel A or Panel B)
# =====================================================================

def _plot_decoder_group_boxplot_paper_panel(
    df, err_col, save_path, *,
    mode="between",
    session_str="", train_label="", decoder_tag="2D",
    use_scoring_method: str = "euclidean",
    stat_label="median", auto_close=True,
    between_pvals=None,
):
    """
    Paper-quality boxplot panel.

    Parameters
    ----------
    mode : str
        ``"between"`` → **Panel A**: conditions on x-axis, groups clustered,
        between-group significance brackets (independent t-tests, Holm).
        ``"within"`` → **Panel B**: one sub-panel per group, conditions on x,
        within-group cross-condition brackets (paired t-tests, Holm).
    between_pvals : dict or None
        Optional pre-computed p-values for Panel A (between mode).
        Format: {condition: [{"g1": str, "g2": str, "p_raw": float, "p_holm": float}, ...]}
        If None, independent t-tests are computed from the raw data.
    """
    from scipy import stats as sp_stats
    from statsmodels.stats.multitest import multipletests
    from itertools import combinations
    from matplotlib.patches import Patch

    method = str(use_scoring_method).strip().lower()
    y_label = (
        f"{stat_label.capitalize()} R^2 (variance accounted for)"
        if method == "rsquared"
        else _euclidean_error_title(stat_label)
    )

    # ---- common setup ----
    all_conds = _sort_conditions(df["condition"].unique())
    cond_label = _build_cond_label_map(all_conds)
    n_cond = len(all_conds)
    groups_present = [g for g in _PAPER_GROUP_ORDER
                      if g in df["group"].unique()]
    n_groups = len(groups_present)
    x_base = np.arange(n_cond)

    _BP_KW = dict(patch_artist=True, showfliers=False,
                  medianprops=dict(color="black", lw=1.0),
                  whiskerprops=dict(color="black", lw=0.6),
                  capprops=dict(color="black", lw=0.6))

    def _style_bp(bp, grp):
        for patch in bp["boxes"]:
            patch.set_facecolor(_PAPER_COLORS[grp])
            patch.set_alpha(_PAPER_BOX_ALPHA)
            patch.set_edgecolor("black")
            patch.set_linewidth(0.6)

    def _scatter(ax, x_pos, vals, grp, seed, jit_range=0.10):
        jit = np.random.default_rng(seed).uniform(
            -jit_range, jit_range, size=vals.size)
        ax.scatter(x_pos + jit, vals,
                   color=_PAPER_DOT_COLORS.get(grp, "gray"),
                   s=18, zorder=5, edgecolors="white", linewidths=0.25)

    def _draw_bracket(ax, x1, x2, by, bdy, y_rng, star, fs,
                      color="#333333", bold=False):
        ax.plot([x1, x1, x2, x2], [by, by + bdy, by + bdy, by],
                color=color, lw=0.7)
        ax.text((x1 + x2) / 2, by + bdy + 0.001 * y_rng, star,
                ha="center", va="bottom", fontsize=fs, color=color,
                fontweight="bold" if bold else "normal")

    def _fmt_ax(ax, ylabel=True):
        ax.spines["top"].set_visible(False)
        ax.spines["right"].set_visible(False)
        ax.tick_params(axis="both", which="both", labelsize=7,
                       length=3, width=0.6, pad=2)
        ax.spines["bottom"].set_linewidth(0.6)
        if ylabel:
            ax.set_ylabel(y_label, fontsize=8)
            ax.spines["left"].set_linewidth(0.6)

    # ==================================================================
    #  MODE: "between" — Panel A
    # ==================================================================
    if mode == "between":
        # -- between-group pairwise significance per condition --
        if between_pvals is not None:
            pw_per_cond = between_pvals
        else:
            pw_per_cond = {}
            for cond in all_conds:
                pairs = list(combinations(groups_present, 2))
                raw_ps, info = [], []
                for g1, g2 in pairs:
                    v1 = df.loc[(df["group"] == g1) & (df["condition"] == cond),
                                err_col].dropna().values
                    v2 = df.loc[(df["group"] == g2) & (df["condition"] == cond),
                                err_col].dropna().values
                    if len(v1) >= 2 and len(v2) >= 2:
                        _, p = sp_stats.ttest_ind(v1, v2)
                    else:
                        p = 1.0
                    raw_ps.append(p)
                    info.append((g1, g2, p))
                if raw_ps:
                    _, p_holm, _, _ = multipletests(raw_ps, method="holm")
                else:
                    p_holm = np.array([])
                pw_per_cond[cond] = [
                    {"g1": g1, "g2": g2, "p_raw": pr,
                     "p_holm": float(p_holm[k]) if k < len(p_holm) else 1.0}
                    for k, (g1, g2, pr) in enumerate(info)
                ]

        # -- position map: (cond_idx, group_idx) → x_pos --
        box_pos = {}        # (ci, gi) → x
        tick_pos = []
        tick_labels_a = []
        x_cur = 0.0
        for ci, cond in enumerate(all_conds):
            for gi, grp in enumerate(groups_present):
                box_pos[(ci, gi)] = x_cur
                tick_pos.append(x_cur)
                tick_labels_a.append(cond_label.get(cond, cond))
                x_cur += 1.0
            x_cur += 0.5          # extra gap between condition clusters

        bw = 0.60  # box width
        fig_w = max(4.0, 0.55 * (tick_pos[-1] - tick_pos[0] + 1))
        fig, ax = plt.subplots(figsize=(fig_w, 3.2), dpi=300)

        for gi, grp in enumerate(groups_present):
            for ci, c in enumerate(all_conds):
                xp = box_pos[(ci, gi)]
                vals = df.loc[(df["group"] == grp) & (df["condition"] == c),
                              err_col].dropna().values
                if vals.size == 0:
                    continue
                bp = ax.boxplot([vals], positions=[xp], widths=bw,
                                **_BP_KW)
                _style_bp(bp, grp)
                _scatter(ax, xp, vals, grp,
                         42 + gi * 100 + ci, jit_range=bw * 0.18)

        # -- brackets --
        y_max = df[err_col].max()
        y_min = df[err_col].min()
        y_rng = max(y_max - y_min, 10.0)
        bdy = 0.030 * y_rng
        bgap = 2.6 * bdy

        for ci, cond in enumerate(all_conds):
            by = y_max + 0.02 * y_rng
            pw_sorted = sorted(
                pw_per_cond[cond],
                key=lambda p: abs(groups_present.index(p["g2"])
                                  - groups_present.index(p["g1"])))
            for pw in pw_sorted:
                star, fs = _p_to_star(pw["p_holm"], pw["p_raw"])
                if star is None:
                    continue
                g1i = groups_present.index(pw["g1"])
                g2i = groups_present.index(pw["g2"])
                x1 = box_pos[(ci, g1i)]
                x2 = box_pos[(ci, g2i)]
                _draw_bracket(ax, x1, x2, by, bdy, y_rng, star, fs,
                              color="#333333")
                by += bgap

        ax.set_xticks(tick_pos)
        ax.set_xticklabels(tick_labels_a,
                           fontsize=5.5, rotation=-30, ha="left")
        _fmt_ax(ax)
        ax.set_xlim(tick_pos[0] - 0.5, tick_pos[-1] + 0.5)

        handles = [Patch(facecolor=_PAPER_COLORS[g], alpha=_PAPER_BOX_ALPHA,
                         edgecolor="black", lw=0.6,
                         label=_PAPER_LABELS.get(g, g))
                   for g in groups_present]
        ax.legend(handles=handles, loc="upper right", fontsize=6.5,
                  frameon=True, framealpha=0.9, edgecolor="none",
                  handlelength=1.0, handletextpad=0.4, borderpad=0.3)

        fig.tight_layout(pad=0.3)
        tag = f"panelA_between_group_{stat_label}_paper"
        label = "Panel A (between-group)"

        if method == "rsquared":
            _plot_decoder_group_boxplot_paper_between_broken_axis(
                df, err_col, save_path,
                stat_label=stat_label,
                y_label=y_label,
                all_conds=all_conds,
                cond_label=cond_label,
                groups_present=groups_present,
                auto_close=auto_close,
            )

    # ==================================================================
    #  MODE: "within" — Panel B
    # ==================================================================
    else:
        fig, axes = plt.subplots(
            1, n_groups, figsize=(1.8 * n_groups + 0.3, 3.2),
            dpi=300, sharey=True)
        if n_groups == 1:
            axes = [axes]

        for gi, grp in enumerate(groups_present):
            ax = axes[gi]

            data = [df.loc[(df["group"] == grp) & (df["condition"] == c),
                           err_col].dropna().values for c in all_conds]
            bp = ax.boxplot(data, positions=x_base, widths=0.45, **_BP_KW)
            _style_bp(bp, grp)
            for ci in range(n_cond):
                _scatter(ax, x_base[ci], data[ci], grp,
                         42 + gi * 100 + ci)

            # -- within-group paired t-tests across conditions --
            mouse_vals = {}
            for ci, c in enumerate(all_conds):
                sub = df.loc[(df["group"] == grp) & (df["condition"] == c),
                             ["mouse", err_col]].dropna(subset=[err_col])
                for _, row in sub.iterrows():
                    mouse_vals.setdefault(row["mouse"], {})[ci] = row[err_col]

            cond_pairs = list(combinations(range(n_cond), 2))
            raw_ps, meta = [], []
            for ci1, ci2 in cond_pairs:
                paired = [(mouse_vals[m][ci1], mouse_vals[m][ci2])
                          for m in mouse_vals
                          if ci1 in mouse_vals[m] and ci2 in mouse_vals[m]]
                if len(paired) >= 3:
                    v1 = np.array([p[0] for p in paired])
                    v2 = np.array([p[1] for p in paired])
                    _, p_raw = sp_stats.ttest_rel(v1, v2)
                else:
                    p_raw = 1.0
                raw_ps.append(p_raw)
                meta.append((ci1, ci2, p_raw))

            if raw_ps:
                _, p_holm_arr, _, _ = multipletests(raw_ps, method="holm")
            else:
                p_holm_arr = np.array([])

            y_max_ax = (max(np.nanmax(d) for d in data if d.size)
                        if any(d.size for d in data) else 1.0)
            y_min_ax = (min(np.nanmin(d) for d in data if d.size)
                        if any(d.size for d in data) else 0.0)
            y_rng = max(y_max_ax - y_min_ax, 10.0)
            bdy = 0.030 * y_rng
            bgap = 2.6 * bdy
            by = y_max_ax + 0.06 * y_rng

            idxs_sorted = sorted(
                range(len(meta)),
                key=lambda k: abs(meta[k][1] - meta[k][0]))
            for k in idxs_sorted:
                ci1, ci2, p_raw = meta[k]
                p_h = float(p_holm_arr[k]) if k < len(p_holm_arr) else 1.0
                star, fs = _p_to_star(p_h, p_raw)
                if star is None:
                    continue
                _draw_bracket(ax, x_base[ci1], x_base[ci2], by, bdy, y_rng,
                              star, fs, color="black", bold=True)
                by += bgap

            ax.set_title(_PAPER_LABELS.get(grp, grp), fontsize=8,
                         color="black", fontweight="bold", pad=4)
            ax.set_xticks(x_base)
            ax.set_xticklabels([cond_label.get(c, c) for c in all_conds],
                               fontsize=5.5, rotation=-30, ha="left")
            ax.spines["top"].set_visible(False)
            ax.tick_params(axis="both", which="both", labelsize=7,
                           length=3, width=0.6, pad=2)
            ax.spines["bottom"].set_visible(False)

            if gi == 0:
                ax.set_ylabel(y_label, fontsize=8)
                ax.spines["left"].set_linewidth(0.6)
                ax.spines["right"].set_visible(False)
            else:
                ax.spines["left"].set_visible(False)
                ax.spines["right"].set_visible(False)
                ax.tick_params(axis="y", left=False, labelleft=False)

        # tighten x-axis margins on each subplot
        for a in axes:
            a.set_xlim(x_base[0] - 0.35, x_base[-1] + 0.35)
        fig.subplots_adjust(wspace=0.02)
        fig.tight_layout(pad=0.25, w_pad=0.02)

        # Draw continuous bottom x-axis line across all subplots
        from matplotlib.lines import Line2D as _Line2D
        left_bbox = axes[0].get_position()
        right_bbox = axes[-1].get_position()
        fig.add_artist(_Line2D(
            [left_bbox.x0, right_bbox.x1],
            [left_bbox.y0, left_bbox.y0],
            transform=fig.transFigure, color="black", lw=0.6,
            clip_on=False))

        tag = f"panelB_within_group_{stat_label}_paper"
        label = "Panel B (within-group trajectory)"

    # ---- common save / show / close ----
    for ext in (".png", ".svg"):
        fig.savefig(os.path.join(save_path, f"{tag}{ext}"),
                    dpi=300, bbox_inches="tight")
    plt.show()
    if auto_close:
        plt.close(fig)
    print(f"[MT-STATS] {label} saved → {save_path}")


# =====================================================================
#  Wrapper: generate both Panel A and Panel B
# =====================================================================

def _plot_decoder_group_boxplot_paper(
    df, err_col, save_path, *,
    session_str="", train_label="", decoder_tag="2D",
    use_scoring_method: str = "euclidean",
    stat_label="median", auto_close=True,
    between_pvals=None,
):
    """Generate Panel A (between-group) and Panel B (within-group trajectory)."""
    kw = dict(session_str=session_str, train_label=train_label,
              decoder_tag=decoder_tag, use_scoring_method=use_scoring_method,
              stat_label=stat_label,
              auto_close=auto_close)
    _plot_decoder_group_boxplot_paper_panel(
        df, err_col, save_path, mode="between", between_pvals=between_pvals, **kw)
    _plot_decoder_group_boxplot_paper_panel(
        df, err_col, save_path, mode="within", **kw)


# ---------------------------------------------------------------------------
#  Spatial error heatmaps (group-averaged 2D maps of decoding error)
# ---------------------------------------------------------------------------

def _bin_spatial_error(true_x, true_y, err, x_edges, y_edges):
    """
    Bin Euclidean errors by (x, y) position and return mean error per bin.

    Returns
    -------
    mean_err : (n_y_bins, n_x_bins) – mean error per bin (NaN where no data)
    count    : (n_y_bins, n_x_bins) – number of observations per bin
    """
    n_x = len(x_edges) - 1
    n_y = len(y_edges) - 1
    x_idx = np.clip(np.digitize(true_x, x_edges) - 1, 0, n_x - 1)
    y_idx = np.clip(np.digitize(true_y, y_edges) - 1, 0, n_y - 1)
    valid = np.isfinite(err)
    sum_err = np.zeros((n_y, n_x), dtype=float)
    count = np.zeros((n_y, n_x), dtype=float)
    np.add.at(sum_err, (y_idx[valid], x_idx[valid]), err[valid])
    np.add.at(count, (y_idx[valid], x_idx[valid]), 1)
    mean_err = np.full((n_y, n_x), np.nan)
    mask = count > 0
    mean_err[mask] = sum_err[mask] / count[mask]
    return mean_err, count


def _extract_within_outs(within_res):
    """
    Extract list of 'out' dicts from a within-session CV result,
    handling the LOLO key (train_to_test) and
    the PF keys (even, odd).  Also accepts legacy even_to_odd / odd_to_even
    keys for backward compatibility with cached .npy files.
    """
    outs = []
    for key in ["train_to_test",
                "even_to_odd", "odd_to_even", "even", "odd"]:
        entry = within_res.get(key, {})
        if isinstance(entry, dict) and "out" in entry:
            outs.append(entry["out"])
    return outs


def plot_decoder_spatial_error_heatmaps(
    all_results: dict,
    mouse_groups: dict,
    PLOTS_DIR: str,
    *,
    train_label: str = "TFC_cond",
    session_str: str = "",
    decoder_tag: str = "2D_PF",
    n_bins: int = 20,
    kmin: float = 5.0,
    vmax_pctl: float = 95.0,
    auto_close: bool = True,
):
    """
    For each condition (within-train + each cross-session target), produce
    a 1×3 heatmap figure showing group-averaged spatial decoding error
    on the physical environment layout.

    Two versions are produced per condition:
      • **Annotated** — larger figure, per-panel colorbars, mouse counts
      • **Paper-ready** — compact, shared colorbar, clean labels

    Parameters
    ----------
    all_results : dict
        Output from ``run_2D_decoder_all_mice`` or
        ``run_2D_PF_decoder_all_mice``.
    mouse_groups : dict
        {mouse: group_label}
    n_bins : int
        Number of spatial bins per axis.
    kmin : float
        Minimum ``Ksum`` for a time-chunk to be included.
    vmax_pctl : float
        Colorbar upper limit as percentile of the group-averaged error.
    """
    _paper_group_order = ["mCherry", "hM3D", "hM4D"]
    _paper_labels = {"mCherry": "Ctl", "hM3D": "Exc", "hM4D": "Inh"}
    _paper_colors = {
        "mCherry": "#2c2c2c",
        "hM3D":    "#d62728",
        "hM4D":    "#1f77b4",
    }
    group_order = [g for g in _paper_group_order if g in set(mouse_groups.values())]

    save_path = os.path.join(
        PLOTS_DIR,
        f"spatial_error_heatmaps_{decoder_tag}_{train_label}_{session_str}",
    )
    os.makedirs(save_path, exist_ok=True)

    # ------------------------------------------------------------------
    # 1. Collect per-mouse (true_x, true_y, err) for each condition
    # ------------------------------------------------------------------
    conditions: Dict[str, Dict[str, tuple]] = {}  # {cond: {mouse: (tx,ty,err,group)}}

    for mouse, mres in all_results.items():
        grp = mouse_groups.get(mouse, mres.get("group", "NA"))

        # ---- within-session ----
        within = mres.get("within_train", {})
        if within.get("ok", False):
            outs = _extract_within_outs(within)
            if outs:
                tx = np.concatenate([o["true_x"] for o in outs])
                ty = np.concatenate([o["true_y"] for o in outs])
                err = np.concatenate([o["euclidean_err"] for o in outs])
                Ks = np.concatenate([o["Ksum"] for o in outs])
                keep = np.isfinite(err) & np.isfinite(Ks) & (Ks >= kmin)
                if np.any(keep):
                    cond_name = f"within_{train_label}"
                    conditions.setdefault(cond_name, {})[mouse] = (
                        tx[keep], ty[keep], err[keep], grp)

        # ---- cross-session targets ----
        for tgt_name, tgt_res in mres.get("targets", {}).items():
            if not tgt_res.get("ok", False):
                continue
            out = tgt_res["out"]
            tx = out["true_x"]
            ty = out["true_y"]
            err = out["euclidean_err"]
            Ks = out["Ksum"]
            keep = np.isfinite(err) & np.isfinite(Ks) & (Ks >= kmin)
            if np.any(keep):
                cond_name = f"{train_label}_to_{tgt_name}"
                conditions.setdefault(cond_name, {})[mouse] = (
                    tx[keep], ty[keep], err[keep], grp)

    if not conditions:
        print("[SPATIAL-ERR] No data to plot.")
        return

    # ------------------------------------------------------------------
    # 2. Global spatial edges (shared across all conditions)
    # ------------------------------------------------------------------
    all_x = np.concatenate([d[0] for cd in conditions.values() for d in cd.values()])
    all_y = np.concatenate([d[1] for cd in conditions.values() for d in cd.values()])
    x_lo, x_hi = np.nanmin(all_x), np.nanmax(all_x)
    y_lo, y_hi = np.nanmin(all_y), np.nanmax(all_y)
    x_edges = np.linspace(x_lo, x_hi, n_bins + 1)
    y_edges = np.linspace(y_lo, y_hi, n_bins + 1)
    extent = [x_lo, x_hi, y_lo, y_hi]

    # Sort conditions: within first, then alphabetical targets
    all_conds = sorted(conditions.keys(),
                       key=lambda c: (0 if c.startswith("within") else 1, c))

    # Friendly condition labels
    _cond_nice = {}
    for c in all_conds:
        if c.startswith("within_"):
            _cond_nice[c] = "Within " + c.replace("within_", "").replace("_", " ")
        elif "_to_" in c:
            parts = c.split("_to_")
            _cond_nice[c] = (parts[0].replace("_", " ") + " → "
                             + parts[1].replace("_", " "))
        else:
            _cond_nice[c] = c.replace("_", " ")

    # ------------------------------------------------------------------
    # 3. Per-condition plots
    # ------------------------------------------------------------------
    for cond_name in all_conds:
        cond_data = conditions[cond_name]

        # ---- bin per-mouse, then average within group ----
        group_maps = {g: [] for g in group_order}
        group_counts = {g: 0 for g in group_order}

        for mouse, (tx, ty, err, grp) in cond_data.items():
            if grp not in group_maps:
                continue
            m_map, _ = _bin_spatial_error(tx, ty, err, x_edges, y_edges)
            group_maps[grp].append(m_map)
            group_counts[grp] += 1

        avg_maps = {}
        for g in group_order:
            if group_maps[g]:
                avg_maps[g] = np.nanmean(np.stack(group_maps[g]), axis=0)
            else:
                avg_maps[g] = np.full((n_bins, n_bins), np.nan)

        # Common colour limits
        all_vals = np.concatenate([m.ravel() for m in avg_maps.values()])
        finite = all_vals[np.isfinite(all_vals)]
        if finite.size == 0:
            continue
        vmin = 0.0
        vmax = float(np.percentile(finite, vmax_pctl))
        if vmax <= 0:
            vmax = float(np.nanmax(finite)) if np.nanmax(finite) > 0 else 1.0

        cond_nice = _cond_nice.get(cond_name, cond_name)
        fname_base = f"spatial_err_{cond_name}"

        # ==============================================================
        # ANNOTATED version
        # ==============================================================
        n_g = len(group_order)
        fig, axes = plt.subplots(1, n_g, figsize=(5.2 * n_g, 4.8), dpi=150)
        if n_g == 1:
            axes = [axes]

        for gi, g in enumerate(group_order):
            ax = axes[gi]
            im = ax.imshow(
                avg_maps[g], origin="lower", cmap="inferno",
                vmin=vmin, vmax=vmax, extent=extent, aspect="equal",
                interpolation="nearest",
            )
            ax.set_title(f"{g}  (n={group_counts[g]})", fontsize=12)
            ax.set_xlabel(_xy_axis_label("X"), fontsize=10)
            if gi == 0:
                ax.set_ylabel(_xy_axis_label("Y"), fontsize=10)
            else:
                ax.set_yticklabels([])
            cb = plt.colorbar(im, ax=ax, fraction=0.046, pad=0.04)
            cb.set_label(_mean_error_axis_label(), fontsize=9)
            cb.ax.tick_params(labelsize=8)

        fig.suptitle(
            f"{decoder_tag} spatial decoding error — {cond_nice}",
            fontsize=13, y=1.02,
        )
        fig.tight_layout()
        fig.savefig(os.path.join(save_path, f"{fname_base}_annotated.png"),
                    dpi=300, bbox_inches="tight")
        plt.show()
        if auto_close:
            plt.close(fig)

        # ==============================================================
        # PAPER version
        # ==============================================================
        fig_p, axes_p = plt.subplots(1, n_g, figsize=(2.6 * n_g + 0.8, 2.8),
                                      dpi=300)
        if n_g == 1:
            axes_p = [axes_p]

        for gi, g in enumerate(group_order):
            ax = axes_p[gi]
            im_p = ax.imshow(
                avg_maps[g], origin="lower", cmap="inferno",
                vmin=vmin, vmax=vmax, extent=extent, aspect="equal",
                interpolation="nearest",
            )
            ax.set_title(_paper_labels.get(g, g), fontsize=10, pad=4)
            ax.tick_params(labelsize=6)
            if gi == 0:
                ax.set_ylabel(_xy_axis_label("Y"), fontsize=8)
            else:
                ax.set_yticklabels([])
            ax.set_xlabel(_xy_axis_label("X"), fontsize=8)

        # Shared colorbar on the right
        fig_p.subplots_adjust(right=0.87, wspace=0.08)
        cbar_ax = fig_p.add_axes([0.89, 0.15, 0.025, 0.70])
        cb_p = fig_p.colorbar(im_p, cax=cbar_ax)
        cb_p.set_label(_mean_error_axis_label(), fontsize=8)
        cb_p.ax.tick_params(labelsize=6)

        fig_p.savefig(os.path.join(save_path, f"{fname_base}_paper.png"),
                      dpi=300, bbox_inches="tight")
        fig_p.savefig(os.path.join(save_path, f"{fname_base}_paper.svg"),
                      bbox_inches="tight")
        plt.show()
        if auto_close:
            plt.close(fig_p)

    print(f"[SPATIAL-ERR] Heatmaps saved → {save_path}")


# =============================================================================
# ====  Per-mouse X/Y position vs time plots  =================================
# =============================================================================

def plot_xy_time_per_mouse(
    all_results: dict,
    PLOTS_DIR: str,
    train_label: str,
    session_str: str,
    decoder_tag: str = "2D",
    auto_close: bool = True,
) -> None:
    """
    For each mouse × target combination with successful decoding, produce a
    landscape figure (2 subplots, x on top, y on bottom) showing:

      • black solid curve  — real (true) position over time
      • dark-grey dashed curve — Bayesian decoded position over time

    Figures are saved into ``PLOTS_DIR/xy_position_vs_time/``.

    Parameters
    ----------
    all_results : dict
        Output from any ``run_2D_*_all_mice`` function.  Structure::

            {mouse: {"group": str, "targets": {tgt_name: res_dict}}}

        Each ``res_dict`` must have ``"ok"`` and ``"out"`` keys, where
        ``out`` contains ``true_x``, ``true_y``, ``decoded_x``,
        ``decoded_y``, and optionally ``idx_use``.  ``res_dict`` may also
        contain ``"dt_test"`` for converting frame indices to seconds.
    PLOTS_DIR : str
        Root directory for this paradigm's plots.  A sub-directory
        ``xy_position_vs_time`` will be created inside it.
    train_label : str
        Label for the training session (used in file names and titles).
    session_str : str
        Short paradigm identifier (e.g. ``"paradigmA"``).
    decoder_tag : str
        Short decoder label (``"2D"`` or ``"2D_PF"``), appended to filenames.
    auto_close : bool
        Close figures after saving (default ``True``).
    """
    save_dir = os.path.join(PLOTS_DIR, "xy_position_vs_time")
    os.makedirs(save_dir, exist_ok=True)

    def _plot_single(mouse, group, tgt_name, res, out, dt_key="dt_test"):
        true_x = np.asarray(out.get("true_x", []), dtype=float)
        true_y = np.asarray(out.get("true_y", []), dtype=float)
        dec_x = np.asarray(out.get("decoded_x", []), dtype=float)
        dec_y = np.asarray(out.get("decoded_y", []), dtype=float)
        unit_label = out.get("position_unit", _TFC_TEST_2D_DISTANCE_UNIT)

        if true_x.size == 0:
            return

        dt_val = res.get(dt_key, None) if isinstance(res, dict) else None
        idx_use = out.get("idx_use")
        if (dt_val is not None and idx_use is not None and len(idx_use) > 0):
            t = np.mean(idx_use, axis=1) * float(dt_val)
            xlabel = "Time (s)"
        else:
            t = np.arange(len(true_x))
            xlabel = "Chunk index"

        tag = (f"{mouse}_{group}_{session_str}_{train_label}"
               f"_to_{tgt_name}_{decoder_tag}")

        fig, (ax_x, ax_y) = plt.subplots(
            2, 1, figsize=(14, 5), dpi=150, sharex=True)

        ax_x.plot(t, true_x, color="black", lw=1.2, label="Real")
        ax_x.plot(t, dec_x, color="#555555", lw=1.0, ls="--", label="Decoded")
        ax_x.set_ylabel(f"X position ({unit_label})")
        ax_x.set_title(f"{mouse} ({group})  {train_label} -> {tgt_name}  [{decoder_tag}]")
        ax_x.legend(loc="upper right", fontsize=8)
        ax_x.grid(True, alpha=0.25)

        ax_y.plot(t, true_y, color="black", lw=1.2, label="Real")
        ax_y.plot(t, dec_y, color="#555555", lw=1.0, ls="--", label="Decoded")
        ax_y.set_ylabel(f"Y position ({unit_label})")
        ax_y.set_xlabel(xlabel)
        ax_y.legend(loc="upper right", fontsize=8)
        ax_y.grid(True, alpha=0.25)

        fig.tight_layout()
        fig.savefig(os.path.join(save_dir, f"{tag}_xy_vs_time.png"), dpi=300)
        if auto_close:
            plt.close(fig)

    for mouse, mouse_res in all_results.items():
        group = mouse_res.get("group", "NA")

        # Cross-session or pooled target plots
        targets = mouse_res.get("targets", {})
        for tgt_name, res in targets.items():
            if not res.get("ok", False):
                continue
            out = res.get("out")
            if out is None:
                continue
            _plot_single(mouse, group, tgt_name, res, out, dt_key="dt_test")

        # Within-session CV plots (run_2D_*_all_mice style)
        within_train = mouse_res.get("within_train")
        if isinstance(within_train, dict) and within_train.get("ok", False):
            # Ridge within-CV returns top-level traces (no split dict with "out").
            if all(k in within_train for k in ("true_x", "true_y", "decoded_x", "decoded_y")):
                out_w = {
                    "true_x": np.asarray(within_train.get("true_x", []), float),
                    "true_y": np.asarray(within_train.get("true_y", []), float),
                    "decoded_x": np.asarray(within_train.get("decoded_x", []), float),
                    "decoded_y": np.asarray(within_train.get("decoded_y", []), float),
                    "idx_use": within_train.get("idx_use", None),
                }
                valid = np.asarray(within_train.get("valid_mask", []), bool)
                if valid.size == out_w["true_x"].size and valid.size > 0:
                    out_w["true_x"] = out_w["true_x"][valid]
                    out_w["true_y"] = out_w["true_y"][valid]
                    out_w["decoded_x"] = out_w["decoded_x"][valid]
                    out_w["decoded_y"] = out_w["decoded_y"][valid]
                    idx_use = out_w.get("idx_use", None)
                    if idx_use is not None:
                        idx_use = np.asarray(idx_use)
                        if idx_use.shape[0] == valid.size:
                            out_w["idx_use"] = idx_use[valid]

                _plot_single(
                    mouse,
                    group,
                    f"within_{train_label}_ridge_cv",
                    {"dt_test": mouse_res.get("dt_train", None)},
                    out_w,
                    dt_key="dt_test",
                )

            for split_name, split_res in within_train.items():
                if split_name in {"ok", "reason", "pooled_euclidean_err", "mean_err", "median_err", "r_x", "r_y"}:
                    continue
                if not isinstance(split_res, dict):
                    continue
                out_w = split_res.get("out")
                if out_w is None:
                    continue
                _plot_single(
                    mouse,
                    group,
                    f"within_{train_label}_{split_name}",
                    {"dt_test": mouse_res.get("dt_train", None)},
                    out_w,
                    dt_key="dt_test",
                )

        # Within-session CV plots (run_TFC_2D_decoding_all_mice legacy style)
        within_tfc = mouse_res.get("within_TFC")
        if isinstance(within_tfc, dict) and within_tfc.get("ok", False):
            for split_name, split_res in within_tfc.items():
                if split_name in {"ok", "reason", "pooled_euclidean_err", "mean_err", "median_err", "r_x", "r_y"}:
                    continue
                if not isinstance(split_res, dict):
                    continue
                out_w = split_res.get("out")
                if out_w is None:
                    continue
                _plot_single(
                    mouse,
                    group,
                    f"within_TFC_{split_name}",
                    {"dt_test": mouse_res.get("dt_train", None)},
                    out_w,
                    dt_key="dt_test",
                )

    print(f"[XY-TIME] Saved per-mouse position vs time plots → {save_dir}")


# =============================================================================
# ====  PARADIGM F: Pooled-target decoding  ====================================
# ====  Train on one session, decode pooled (A+A_1wk) or (B+B_1wk)  ===========
# =============================================================================

def _pool_test_sessions_for_cells(
    train_sess,
    test_sessions: list,
    *,
    mapping: str,
    use_speed: bool = True,
    min_speed: float = 2.0,
    first_n_sec: float = 180.0,
    encoder_period: str = "pre-tone",
):
    """
    Resolve cross-registration for *train_sess* vs **all** *test_sessions*,
    keep only the intersection of cells present in every session, and
    concatenate test S / position / mask arrays.

    Returns
    -------
    dict with 'ok' and, on success:
        S_train, S_test_pooled, x_pooled, y_pooled, mask_pooled,
        dt_train, dt_test (median across test sessions),
        n_cells, mapping_used, n_pretone_per_sess
    """
    train_type = train_sess.session_type
    mapping_labels = set(mapping.split('+'))

    # --- find cross-reg and cell IDs for every test session -----------------
    per_sess = []
    for test_sess in test_sessions:
        test_type = test_sess.session_type
        crossreg, df_mapping = None, None

        if train_type in mapping_labels and test_type in mapping_labels:
            crossreg, df_mapping = _find_crossreg_with_mapping(
                train_sess, test_sess, mapping)

        if crossreg is None:
            fallback = _make_pair_mapping(train_type, test_type)
            crossreg, df_mapping = _find_crossreg_with_mapping(
                train_sess, test_sess, fallback)

        _candidates = _collect_crossreg_candidates(train_sess, test_sess)

        if crossreg is None:
            for cand in _candidates:
                try:
                    df_mapping = cand.get_cells_for_pair(train_type, test_type)
                    crossreg = cand
                    break
                except KeyError:
                    continue

        if crossreg is None:
            return {"ok": False,
                    "reason": f"No crossreg for {train_type}→{test_type}."}

        col_tr = train_sess.get_df_col(with_crossreg=crossreg)
        col_te = test_sess.get_df_col(with_crossreg=crossreg)
        cells_tr = df_mapping[col_tr].astype(float).astype(int).tolist()
        cells_te = df_mapping[col_te].astype(float).astype(int).tolist()
        per_sess.append({
            "test_sess": test_sess,
            "crossreg": crossreg,
            "cells_train": cells_tr,
            "cells_test": cells_te,
        })

    # --- intersect on the *train* cell-id lists (same physical cells) ------
    common_train_cells = None
    for ps in per_sess:
        s = set(ps["cells_train"])
        common_train_cells = s if common_train_cells is None else common_train_cells & s
    if not common_train_cells:
        return {"ok": False, "reason": "No shared cross-registered cells."}
    common_train_cells = sorted(common_train_cells)

    # For each test session, get S_test for common cells (in the same order)
    S_train, _ = get_mapped_S_from_unit_ids(train_sess, common_train_cells)
    if S_train.shape[0] == 0:
        return {"ok": False, "reason": "S_train empty after intersection."}

    dist_meta = _validate_2d_decoder_distance_meta(train_sess, *[ps["test_sess"] for ps in per_sess])
    pos_scale = float(dist_meta["scale"])

    dt_train = _infer_dt_sec(train_sess)
    x_tr = _scale_2d_position_array(train_sess.loc_X_miniscope_smooth, pos_scale)[:S_train.shape[1]]
    y_tr = _scale_2d_position_array(train_sess.loc_Y_miniscope_smooth, pos_scale)[:S_train.shape[1]]
    mask_train = build_pretone_mask_TFC(
        train_sess, first_n_sec=first_n_sec,
        use_speed=use_speed, min_speed=min_speed,
        encoder_period=encoder_period)[:S_train.shape[1]]

    S_test_parts, x_parts, y_parts, mask_parts, v_parts = [], [], [], [], []
    dt_tests = []
    n_pretone_per_sess = {}
    for ps in per_sess:
        test_sess = ps["test_sess"]
        # Map common_train_cells → corresponding test cell IDs
        tr2te = dict(zip(ps["cells_train"], ps["cells_test"]))
        ordered_test_cells = [tr2te[c] for c in common_train_cells]

        S_te, _ = get_mapped_S_from_unit_ids(test_sess, ordered_test_cells)
        if S_te.shape[0] == 0:
            return {"ok": False,
                    "reason": f"S_test empty for {test_sess.session_type}"}

        dt_te = _infer_dt_sec(test_sess)
        dt_tests.append(dt_te)
        x_te = _scale_2d_position_array(test_sess.loc_X_miniscope_smooth, pos_scale)[:S_te.shape[1]]
        y_te = _scale_2d_position_array(test_sess.loc_Y_miniscope_smooth, pos_scale)[:S_te.shape[1]]
        v_te = _scale_2d_position_array(_get_miniscope_velocity_vector(test_sess, T=S_te.shape[1]), pos_scale)
        mask_te = build_pretone_mask_TFC(
            test_sess, first_n_sec=first_n_sec,
            use_speed=use_speed, min_speed=min_speed,
            encoder_period="pre-tone")[:S_te.shape[1]]

        n_pretone_per_sess[test_sess.session_type] = int(np.sum(mask_te))
        S_test_parts.append(S_te)
        x_parts.append(x_te)
        y_parts.append(y_te)
        mask_parts.append(mask_te)
        if v_te is not None:
            v_parts.append(v_te)
        else:
            v_parts.append(np.full(S_te.shape[1], np.nan, dtype=float))

    # Concatenate test data along time axis
    S_test_pooled = np.concatenate(S_test_parts, axis=1)
    x_pooled = np.concatenate(x_parts)
    y_pooled = np.concatenate(y_parts)
    mask_pooled = np.concatenate(mask_parts)
    v_pooled = np.concatenate(v_parts)

    return {
        "ok": True,
        "S_train": S_train,
        "x_tr": x_tr, "y_tr": y_tr, "mask_train": mask_train,
        "S_test_pooled": S_test_pooled,
        "x_pooled": x_pooled, "y_pooled": y_pooled, "mask_pooled": mask_pooled,
        "v_pooled": v_pooled,
        "dt_train": dt_train,
        "dt_test": float(np.median(dt_tests)),
        "n_cells": S_train.shape[0],
        "mapping_used": mapping,
        "n_pretone_per_sess": n_pretone_per_sess,
        "common_train_cells": common_train_cells,
        "mobile_sec_train": float(np.sum(mask_train) * dt_train),
        "mobile_sec_test_pooled": float(np.sum(mask_pooled) * float(np.median(dt_tests))),
        "position_unit": dist_meta["unit"],
        "position_scale": pos_scale,
    }


# ---------------------------------------------------------------------------
#  Occupancy-based 2D decode with pooled test sessions
# ---------------------------------------------------------------------------

def decode_2D_pooled(
    train_sess,
    test_sessions: list,
    *,
    mapping: str = "TFC_cond+Test_A+Test_A_1wk",
    n_x_bins: int = 20,
    n_y_bins: int = 20,
    time_bin_frames: int = 5,
    use_posterior_mean: bool = True,
    decoder_type: str = 'bayesian',
    ridge_alpha: float = 1.0,
    use_continuity_constraint: bool = True,
    continuity_sigma_k: float = 60.0,
    continuity_speed_ref: float = 20.0,
    continuity_exp: float = 1.0,
    continuity_sigma_min: float = 20.0,
    continuity_sigma_max: float = 60.0,
    continuity_sigma_default: float = 30.0,
    use_speed: bool = True,
    min_speed: float = 2.0,
    first_n_sec: float = 180.0,
    encoder_period: str = "pre-tone",
    use_z_score: str = "none",
) -> Dict[str, Any]:
    """
    Train a 2D Bayesian decoder on *train_sess* pre-tone, then decode
    the **concatenated** pre-tone data of all *test_sessions*.

    This pools e.g. Test_A + Test_A_1wk into a single, longer test set.
    """
    pool = _pool_test_sessions_for_cells(
        train_sess, test_sessions,
        mapping=mapping, use_speed=use_speed,
        min_speed=min_speed, first_n_sec=first_n_sec,
        encoder_period=encoder_period)
    if not pool["ok"]:
        return pool

    if (np.sum(pool["mask_train"]) < time_bin_frames or
            np.sum(pool["mask_pooled"]) < time_bin_frames):
        return {"ok": False, "reason": "Insufficient pre-tone frames."}

    S_train_use, S_test_use = _apply_zscore_pair(
        pool["S_train"], pool["S_test_pooled"], use_z_score
    )

    (continuity_sigma_k_u,
     continuity_speed_ref_u,
     continuity_sigma_min_u,
     continuity_sigma_max_u,
     continuity_sigma_default_u) = _scale_2d_decoder_lengths(
        pool.get("position_scale", 1.0),
        continuity_sigma_k,
        continuity_speed_ref,
        continuity_sigma_min,
        continuity_sigma_max,
        continuity_sigma_default,
    )

    if _decoder_is_ridge(decoder_type):
        dec = RidgeDecoder2D(time_bin_frames=time_bin_frames, alpha=ridge_alpha)
        dec.fit(S_train_use, pool["x_tr"], pool["y_tr"],
                pool["mask_train"], pool["dt_train"])
        out = dec.decode(S_test_use, pool["x_pooled"],
                         pool["y_pooled"], pool["mask_pooled"])
    else:
        dec = BayesianDecoder2D(n_x_bins=n_x_bins, n_y_bins=n_y_bins,
                                time_bin_frames=time_bin_frames)
        dec.fit(S_train_use, pool["x_tr"], pool["y_tr"],
                pool["mask_train"], pool["dt_train"])
        out = dec.decode(S_test_use, pool["x_pooled"],
                         pool["y_pooled"], pool["mask_pooled"],
                 use_posterior_mean=use_posterior_mean,
                 use_continuity_constraint=use_continuity_constraint,
                 speed_vec=pool.get("v_pooled", None),
                 continuity_sigma_k=continuity_sigma_k_u,
                 continuity_speed_ref=continuity_speed_ref_u,
                 continuity_exp=continuity_exp,
                 continuity_sigma_min=continuity_sigma_min_u,
                 continuity_sigma_max=continuity_sigma_max_u,
                 continuity_sigma_default=continuity_sigma_default_u)

    out = _annotate_2d_decode_output(out, {
        "unit": pool.get("position_unit", "px"),
        "scale": pool.get("position_scale", 1.0),
        "px_distance": float(_TFC_TEST_2D_PX_DISTANCE),
        "true_distance": float(_TFC_TEST_2D_TRUE_DISTANCE),
    })

    return {
        "ok": True,
        "out": out,
        "euclidean_err": out["euclidean_err"],
        "n_cells_mapped": pool["n_cells"],
        "dt_train": pool["dt_train"],
        "dt_test": pool["dt_test"],
        "n_pretone_frames_train": int(np.sum(pool["mask_train"])),
        "n_pretone_frames_test_pooled": int(np.sum(pool["mask_pooled"])),
        "n_pretone_per_sess": pool["n_pretone_per_sess"],
        "mapping": pool["mapping_used"],
        "mobile_sec_train": pool["mobile_sec_train"],
        "mobile_sec_test": pool["mobile_sec_test_pooled"],
        "encoder_period": encoder_period,
        "position_unit": pool.get("position_unit", "px"),
        "position_scale": pool.get("position_scale", 1.0),
    }


# ---------------------------------------------------------------------------
#  PF-based 2D decode with pooled test sessions
# ---------------------------------------------------------------------------

def decode_2D_PF_pooled(
    train_sess,
    test_sessions: list,
    *,
    mapping: str = "TFC_cond+Test_A+Test_A_1wk",
    time_bin_frames: int = 5,
    use_posterior_mean: bool = True,
    decoder_type: str = 'bayesian',
    ridge_alpha: float = 1.0,
    use_continuity_constraint: bool = True,
    continuity_sigma_k: float = 60.0,
    continuity_speed_ref: float = 20.0,
    continuity_exp: float = 1.0,
    continuity_sigma_min: float = 20.0,
    continuity_sigma_max: float = 60.0,
    continuity_sigma_default: float = 30.0,
    use_speed: bool = True,
    min_speed: float = 2.0,
    first_n_sec: float = 180.0,
    place_cells_only: bool = True,
    use_pf_num: int = -1,
    use_occupancy_fallback: bool = True,
    encoder_period: str = "pre-tone",
    use_z_score: str = "none",
) -> Dict[str, Any]:
    """
    Train a PF-based 2D Bayesian decoder on *train_sess* GMM place fields,
    then decode the **concatenated** pre-tone data of all *test_sessions*.
    """
    if not hasattr(train_sess, 'fm') or train_sess.fm is None:
        return {"ok": False, "reason": "Train session has no FluorescenceMap (.fm)."}
    fm = train_sess.fm
    if fm.fluorescence_map_occup is None:
        return {"ok": False, "reason": "train_sess.fm.fluorescence_map_occup is None."}
    if not hasattr(fm, 'pf') or fm.pf is None:
        return {"ok": False, "reason": "No PlaceFields (.pf) on train session."}
    if not hasattr(train_sess, 'loc') or train_sess.loc is None:
        return {"ok": False, "reason": "Train session has no Location_XY (.loc)."}

    pool = _pool_test_sessions_for_cells(
        train_sess, test_sessions,
        mapping=mapping, use_speed=use_speed,
        min_speed=min_speed, first_n_sec=first_n_sec,
        encoder_period=encoder_period)
    if not pool["ok"]:
        return pool

    if np.sum(pool["mask_pooled"]) < time_bin_frames:
        return {"ok": False, "reason": "Insufficient pre-tone frames in pooled test."}

    # --- Map common_train_cells to fm cell indices -------------------------
    fm_cells_list = list(fm.cells) if fm.cells is not None else []
    train_S_indices = train_sess.get_S_indeces(pool["common_train_cells"])

    keep_mask = []
    fm_cell_indices = []
    for i, s_idx in enumerate(train_S_indices):
        if s_idx in fm_cells_list:
            fm_idx = fm_cells_list.index(s_idx)
            if place_cells_only:
                if not (fm.sig_responses is not None and s_idx in fm.sig_responses):
                    continue
            if use_pf_num >= 1:
                if s_idx not in fm.pf.model_:
                    continue
                n_merged_pf = len(fm.pf.merged_means.get(s_idx, []))
                if n_merged_pf == 0 or n_merged_pf > use_pf_num:
                    continue
            elif not use_occupancy_fallback:
                if s_idx not in fm.pf.model_:
                    continue
            keep_mask.append(i)
            fm_cell_indices.append(fm_idx)

    if len(keep_mask) == 0:
        return {"ok": False, "reason": "No train cells in fluorescence map."}

    S_train_kept = pool["S_train"][keep_mask]
    S_test_kept = pool["S_test_pooled"][keep_mask]
    n_cells_used = len(keep_mask)

    S_train_kept, S_test_kept = _apply_zscore_pair(
        S_train_kept, S_test_kept, use_z_score
    )

    rate_map = fm.fluorescence_map_occup
    occupancy = train_sess.loc.occupancy
    bin_width = float(train_sess.loc.bin_width) * float(pool.get("position_scale", 1.0))
    dt_train = pool["dt_train"]

    (continuity_sigma_k_u,
     continuity_speed_ref_u,
     continuity_sigma_min_u,
     continuity_sigma_max_u,
     continuity_sigma_default_u) = _scale_2d_decoder_lengths(
        pool.get("position_scale", 1.0),
        continuity_sigma_k,
        continuity_speed_ref,
        continuity_sigma_min,
        continuity_sigma_max,
        continuity_sigma_default,
    )

    if _decoder_is_ridge(decoder_type):
        dec_r = RidgeDecoder2D(time_bin_frames=time_bin_frames, alpha=ridge_alpha)
        dec_r.fit(S_train_kept, pool["x_tr"], pool["y_tr"],
                  pool["mask_train"], dt_train)
        out = dec_r.decode(S_test_kept, pool["x_pooled"],
                           pool["y_pooled"], pool["mask_pooled"])
    else:
        dec_pf = BayesianDecoder2D_PF(time_bin_frames=time_bin_frames)
        dec_pf.fit_from_place_fields(fm.pf, rate_map, occupancy,
                                     fm_cells=fm_cells_list,
                                     cell_indices=fm_cell_indices,
                                     dt_sec=dt_train, bin_width=bin_width,
                                     use_occupancy_fallback=use_occupancy_fallback)
        out = dec_pf.decode(S_test_kept,
                            pool["x_pooled"], pool["y_pooled"],
                            pool["mask_pooled"],
                            use_posterior_mean=use_posterior_mean,
                            use_continuity_constraint=use_continuity_constraint,
                            speed_vec=pool.get("v_pooled", None),
                            continuity_sigma_k=continuity_sigma_k_u,
                            continuity_speed_ref=continuity_speed_ref_u,
                            continuity_exp=continuity_exp,
                            continuity_sigma_min=continuity_sigma_min_u,
                            continuity_sigma_max=continuity_sigma_max_u,
                            continuity_sigma_default=continuity_sigma_default_u)

    out = _annotate_2d_decode_output(out, {
        "unit": pool.get("position_unit", "px"),
        "scale": pool.get("position_scale", 1.0),
        "px_distance": float(_TFC_TEST_2D_PX_DISTANCE),
        "true_distance": float(_TFC_TEST_2D_TRUE_DISTANCE),
    })

    return {
        "ok": True,
        "out": out,
        "euclidean_err": out["euclidean_err"],
        "n_cells_mapped": n_cells_used,
        "n_cells_crossreg_total": pool["n_cells"],
        "dt_train": dt_train,
        "dt_test": pool["dt_test"],
        "n_pretone_frames_test_pooled": int(np.sum(pool["mask_pooled"])),
        "n_pretone_per_sess": pool["n_pretone_per_sess"],
        "mapping": pool["mapping_used"],
        "place_cells_only": place_cells_only,
        "mobile_sec_train": pool["mobile_sec_train"],
        "mobile_sec_test": pool["mobile_sec_test_pooled"],
        "encoder_period": encoder_period,
        "position_unit": pool.get("position_unit", "px"),
        "position_scale": pool.get("position_scale", 1.0),
    }


# ---------------------------------------------------------------------------
#  Pipeline wrappers for pooled-target decoding (all mice)
# ---------------------------------------------------------------------------

def run_2D_pooled_decoder_all_mice(
    train_sessions: dict,
    pooled_targets: dict,
    *,
    train_label: str = "TFC_cond",
    mapping = "TFC_cond+Test_A+Test_A_1wk",  # str or dict[target_name→str]
    n_x_bins: int = 20,
    n_y_bins: int = 20,
    time_bin_frames: int = 5,
    use_posterior_mean: bool = True,
    decoder_type: str = 'bayesian',
    ridge_alpha: float = 1.0,
    use_continuity_constraint: bool = True,
    continuity_sigma_k: float = 60.0,
    continuity_speed_ref: float = 20.0,
    continuity_exp: float = 1.0,
    continuity_sigma_min: float = 20.0,
    continuity_sigma_max: float = 60.0,
    continuity_sigma_default: float = 30.0,
    use_speed: bool = True,
    min_speed: float = 2.0,
    first_n_sec: float = 180.0,
    encoder_period: str = "pre-tone",
    use_z_score: str = "none",
    PLOTS_DIR: str = "",
    session_str: str = "",
    mouse_groups: dict = None,
    plot_debug: bool = True,
    auto_close: bool = True,
) -> dict:
    """
    For each mouse, train a 2D Bayesian decoder on *train_sessions[mouse]*
    and decode each **pooled** target.

    Parameters
    ----------
    train_sessions : dict[str, Session]
    pooled_targets : dict[str, dict[str, list[Session]]]
        {"A_pooled": {mouse: [sess_24h, sess_1wk]}, …}
    mapping : str or dict
        A single mapping string (used for all targets) or a dict mapping
        target name -> mapping string.
    """
    if mouse_groups is None:
        mouse_groups = {}

    decoder_dir_tag = "ridge_2D" if _decoder_is_ridge(decoder_type) else "bayes_2D"
    save_path = os.path.join(PLOTS_DIR,
                             f"{decoder_dir_tag}_pooled_train_{train_label}_{session_str}_{_z_score_dir_tag(use_z_score)}")
    os.makedirs(save_path, exist_ok=True)

    target_names = list(pooled_targets.keys())
    all_results = {}
    all_mice = sorted(train_sessions.keys())

    for mouse in all_mice:
        train_s = train_sessions[mouse]
        group = mouse_groups.get(mouse, "NA")
        dist_meta = _get_2d_decoder_distance_meta(train_s)
        pos_scale = float(dist_meta["scale"])
        unit_label = dist_meta["unit"]
        print(f"[2D-POOL] {mouse} ({group}) train={train_label} ...")

        mouse_res = {"group": group, "targets": {}}

        # Within-session CV on training session
        dt_train = _infer_dt_sec(train_s)
        x_tr = _scale_2d_position_array(train_s.loc_X_miniscope_smooth, pos_scale)
        y_tr = _scale_2d_position_array(train_s.loc_Y_miniscope_smooth, pos_scale)
        S_tr = train_s.S
        S_tr = _apply_zscore_single(S_tr, use_z_score)
        x_tr = x_tr[:S_tr.shape[1]]; y_tr = y_tr[:S_tr.shape[1]]
        mask_tr = build_pretone_mask_TFC(train_s, first_n_sec=first_n_sec,
                                          use_speed=use_speed,
                                          min_speed=min_speed,
                                          encoder_period=encoder_period)[:S_tr.shape[1]]
        within = _within_session_2D_cv(S_tr, x_tr, y_tr, mask_tr, dt_train,
                        n_x_bins=n_x_bins, n_y_bins=n_y_bins,
                        time_bin_frames=time_bin_frames,
                        use_posterior_mean=use_posterior_mean,
                        decoder_type=decoder_type,
                        ridge_alpha=ridge_alpha,
                        position_unit=unit_label,
                        position_scale=pos_scale)
        mouse_res["within_train"] = within

        if within.get("ok", False):
            w_err = within.get("pooled_euclidean_err", np.array([]))
            if w_err.size > 0:
                print(f"  within-{train_label}: median_err="
                      f"{np.nanmedian(w_err):.1f}{unit_label}")
                tag_wt = f"{mouse}_{group}_{session_str}_within_{train_label}"
                fig, ax = plt.subplots(figsize=(8, 5), dpi=150)
                ax.hist(w_err, bins=50, color="seagreen", alpha=0.8)
                ax.set_xlabel(_euclidean_error_axis_label())
                ax.set_ylabel("Count")
                ax.set_title(f"{mouse} {group} — within-{train_label} 2D CV")
                ax.axvline(np.nanmedian(w_err), color="red", ls="--",
                            label=f"median={np.nanmedian(w_err):.1f}")
                ax.legend(); fig.tight_layout()
                fig.savefig(os.path.join(save_path,
                            f"{tag_wt}_errhist.png"), dpi=300)
                if plot_debug:
                    plt.show()
                if auto_close:
                    plt.close(fig)

        # Decode each pooled target
        for tgt_name in target_names:
            tgt_dict = pooled_targets[tgt_name]
            if mouse not in tgt_dict:
                print(f"  [SKIP-TGT] {tgt_name}: mouse {mouse} not available.")
                mouse_res["targets"][tgt_name] = {
                    "ok": False, "reason": "Mouse not in target dict."}
                continue

            test_sess_list = tgt_dict[mouse]
            tgt_mapping = (mapping[tgt_name] if isinstance(mapping, dict)
                          else mapping)
            res = decode_2D_pooled(
                train_s, test_sess_list,
                mapping=tgt_mapping,
                n_x_bins=n_x_bins, n_y_bins=n_y_bins,
                time_bin_frames=time_bin_frames,
                use_posterior_mean=use_posterior_mean,
                decoder_type=decoder_type, ridge_alpha=ridge_alpha,
                use_continuity_constraint=use_continuity_constraint,
                continuity_sigma_k=continuity_sigma_k,
                continuity_speed_ref=continuity_speed_ref,
                continuity_exp=continuity_exp,
                continuity_sigma_min=continuity_sigma_min,
                continuity_sigma_max=continuity_sigma_max,
                continuity_sigma_default=continuity_sigma_default,
                use_speed=use_speed, min_speed=min_speed,
                first_n_sec=first_n_sec,
                encoder_period=encoder_period,
                use_z_score=use_z_score,
            )
            mouse_res["targets"][tgt_name] = res

            if not res.get("ok", False):
                print(f"  [SKIP-TGT] {tgt_name}: {res.get('reason', '?')}")
                continue

            err = res["euclidean_err"]
            print(f"  → {tgt_name}: n_cells={res['n_cells_mapped']}  "
                f"median_err={np.nanmedian(err):.1f}{unit_label}  "
                f"pretone_per_sess={res['n_pretone_per_sess']}")

            # --- Diagnostic plots ---
            tag = f"{mouse}_{group}_{session_str}_{train_label}_to_{tgt_name}"
            out = res["out"]

            fig, ax = plt.subplots(figsize=(8, 5), dpi=150)
            ax.hist(err, bins=50, color="steelblue", alpha=0.8)
            ax.set_xlabel(_euclidean_error_axis_label())
            ax.set_ylabel("Count")
            ax.set_title(f"{mouse} {group} — {train_label}→{tgt_name}")
            ax.axvline(np.nanmedian(err), color="red", ls="--",
                        label=f"median={np.nanmedian(err):.1f}")
            ax.legend(); fig.tight_layout()
            fig.savefig(os.path.join(save_path, f"{tag}_errhist.png"), dpi=300)
            if plot_debug:
                plt.show()
            if auto_close:
                plt.close(fig)

            fig, axes = plt.subplots(1, 2, figsize=(12, 5), dpi=150)
            for ax, t, d, lb in [(axes[0], out["true_x"], out["decoded_x"], "X"),
                                  (axes[1], out["true_y"], out["decoded_y"], "Y")]:
                ax.scatter(t, d, s=6, alpha=0.3)
                lo = min(np.nanmin(t), np.nanmin(d))
                hi = max(np.nanmax(t), np.nanmax(d))
                ax.plot([lo, hi], [lo, hi], "r-", lw=1.5)
                ax.set_xlabel(f"True {lb} ({unit_label})")
                ax.set_ylabel(f"Decoded {lb} ({unit_label})")
                ax.set_title(f"{mouse} {group} — {train_label}→{tgt_name} {lb}")
                ax.grid(True, alpha=0.2)
            fig.tight_layout()
            fig.savefig(os.path.join(save_path,
                        f"{tag}_scatter_XY.png"), dpi=300)
            if plot_debug:
                plt.show()
            if auto_close:
                plt.close(fig)

            fig, ax = plt.subplots(figsize=(7, 7), dpi=150)
            ax.plot(out["true_x"], out["true_y"], "k-", alpha=0.15,
                    lw=0.5, label="true")
            ax.scatter(out["decoded_x"], out["decoded_y"], c=err,
                       s=10, alpha=0.6, cmap="hot", vmin=0,
                       vmax=np.nanpercentile(err, 95) if err.size > 0 else 1)
            cb = plt.colorbar(ax.collections[-1], ax=ax, pad=0.02)
            cb.set_label(f"Eucl. error ({unit_label})")
            ax.set_xlabel(_xy_axis_label("X")); ax.set_ylabel(_xy_axis_label("Y"))
            ax.set_title(f"{mouse} {group} — {train_label}→{tgt_name} traj")
            ax.set_aspect("equal"); fig.tight_layout()
            fig.savefig(os.path.join(save_path, f"{tag}_traj2D.png"), dpi=300)
            if plot_debug:
                plt.show()
            if auto_close:
                plt.close(fig)

        all_results[mouse] = mouse_res

    n_ok = sum(1 for v in all_results.values()
               if any(v["targets"].get(t, {}).get("ok") for t in target_names))
    print(f"[2D-POOL] Done. {len(all_results)} mice, "
          f"{n_ok} with ≥1 successful target.")
    return all_results


def run_2D_PF_pooled_decoder_all_mice(
    train_sessions: dict,
    pooled_targets: dict,
    *,
    train_label: str = "TFC_cond",
    mapping = "TFC_cond+Test_A+Test_A_1wk",  # str or dict[target_name→str]
    time_bin_frames: int = 5,
    use_posterior_mean: bool = True,
    decoder_type: str = 'bayesian',
    ridge_alpha: float = 1.0,
    use_continuity_constraint: bool = True,
    continuity_sigma_k: float = 60.0,
    continuity_speed_ref: float = 20.0,
    continuity_exp: float = 1.0,
    continuity_sigma_min: float = 20.0,
    continuity_sigma_max: float = 60.0,
    continuity_sigma_default: float = 30.0,
    use_speed: bool = True,
    min_speed: float = 2.0,
    first_n_sec: float = 180.0,
    place_cells_only: bool = True,
    use_pf_num: int = -1,
    use_occupancy_fallback: bool = True,
    encoder_period: str = "pre-tone",
    use_z_score: str = "none",
    PLOTS_DIR: str = "",
    session_str: str = "",
    mouse_groups: dict = None,
    plot_debug: bool = True,
    auto_close: bool = True,
) -> dict:
    """
    PF-based 2D decoder: train on *train_sessions[mouse].fm* GMM place
    fields, decode pooled test sessions.
    """
    if mouse_groups is None:
        mouse_groups = {}

    decoder_dir_tag = "ridge_2D_PF" if _decoder_is_ridge(decoder_type) else "bayes_2D_PF"
    save_path = os.path.join(PLOTS_DIR,
                             f"{decoder_dir_tag}_pooled_train_{train_label}_{session_str}_{_z_score_dir_tag(use_z_score)}")
    os.makedirs(save_path, exist_ok=True)

    pf_str = "pcells" if place_cells_only else "allcells"
    target_names = list(pooled_targets.keys())
    all_results = {}
    all_mice = sorted(train_sessions.keys())

    for mouse in all_mice:
        train_s = train_sessions[mouse]
        group = mouse_groups.get(mouse, "NA")
        dist_meta = _get_2d_decoder_distance_meta(train_s)
        pos_scale = float(dist_meta["scale"])
        unit_label = dist_meta["unit"]
        print(f"[2D-PF-POOL] {mouse} ({group}) [{pf_str}] "
              f"train={train_label} ...")

        mouse_res = {"group": group, "targets": {}}

        # Within-session PF CV
        if hasattr(train_s, 'fm') and train_s.fm is not None:
            fm = train_s.fm
            if (fm.fluorescence_map_occup is not None and
                    hasattr(fm, 'pf') and fm.pf is not None and
                    hasattr(train_s, 'loc') and train_s.loc is not None):
                dt_tr = _infer_dt_sec(train_s)
                S_tr_all = train_s.S
                S_tr_all = _apply_zscore_single(S_tr_all, use_z_score)
                x_tr = _scale_2d_position_array(train_s.loc_X_miniscope_smooth,
                                  pos_scale)[:S_tr_all.shape[1]]
                y_tr = _scale_2d_position_array(train_s.loc_Y_miniscope_smooth,
                                  pos_scale)[:S_tr_all.shape[1]]
                mask_tr = build_pretone_mask_TFC(
                    train_s, first_n_sec=first_n_sec,
                    use_speed=use_speed,
                    min_speed=min_speed,
                    encoder_period=encoder_period)[:S_tr_all.shape[1]]

                if _decoder_is_ridge(decoder_type):
                    within = _within_session_2D_cv_ridge(
                        S_tr_all, x_tr, y_tr, mask_tr, dt_tr,
                        time_bin_frames=time_bin_frames,
                        ridge_alpha=ridge_alpha,
                    )
                else:
                    within = _within_session_2D_PF_cv(
                        S_tr_all, x_tr, y_tr, mask_tr, dt_tr,
                        pf=fm.pf, rate_map=fm.fluorescence_map_occup,
                        occupancy=train_s.loc.occupancy,
                        fm_cells=list(fm.cells) if fm.cells is not None else [],
                        fm_cell_indices=list(range(len(fm.cells)))
                            if fm.cells is not None else [],
                        bin_width=float(train_s.loc.bin_width) * pos_scale,
                        time_bin_frames=time_bin_frames,
                        use_posterior_mean=use_posterior_mean,
                        use_pf_num=use_pf_num,
                        use_occupancy_fallback=use_occupancy_fallback,
                        position_unit=unit_label,
                        position_scale=pos_scale)
                mouse_res["within_train"] = within
            else:
                mouse_res["within_train"] = {
                    "ok": False, "reason": "fm/pf/loc incomplete."}
        else:
            mouse_res["within_train"] = {
                "ok": False, "reason": "No .fm on train session."}

        within = mouse_res["within_train"]
        if within.get("ok", False):
            w_err = within.get("pooled_euclidean_err", np.array([]))
            if w_err.size > 0:
                print(f"  within-{train_label} PF: median_err="
                      f"{np.nanmedian(w_err):.1f}{unit_label}")

        # Decode each pooled target
        for tgt_name in target_names:
            tgt_dict = pooled_targets[tgt_name]
            if mouse not in tgt_dict:
                mouse_res["targets"][tgt_name] = {
                    "ok": False, "reason": "Mouse not in target dict."}
                continue

            test_sess_list = tgt_dict[mouse]
            tgt_mapping = (mapping[tgt_name] if isinstance(mapping, dict)
                          else mapping)
            res = decode_2D_PF_pooled(
                train_s, test_sess_list,
                mapping=tgt_mapping,
                time_bin_frames=time_bin_frames,
                use_posterior_mean=use_posterior_mean,
                decoder_type=decoder_type, ridge_alpha=ridge_alpha,
                use_continuity_constraint=use_continuity_constraint,
                continuity_sigma_k=continuity_sigma_k,
                continuity_speed_ref=continuity_speed_ref,
                continuity_exp=continuity_exp,
                continuity_sigma_min=continuity_sigma_min,
                continuity_sigma_max=continuity_sigma_max,
                continuity_sigma_default=continuity_sigma_default,
                use_speed=use_speed, min_speed=min_speed,
                first_n_sec=first_n_sec,
                place_cells_only=place_cells_only,
                use_pf_num=use_pf_num,
                use_occupancy_fallback=use_occupancy_fallback,
                encoder_period=encoder_period,
                use_z_score=use_z_score,
            )
            mouse_res["targets"][tgt_name] = res

            if not res.get("ok", False):
                print(f"  [SKIP-TGT] {tgt_name}: {res.get('reason', '?')}")
                continue

            err = res["euclidean_err"]
            print(f"  → {tgt_name}: n_cells={res['n_cells_mapped']}  "
                f"median_err={np.nanmedian(err):.1f}{unit_label}  "
                f"pretone_per_sess={res['n_pretone_per_sess']}")

            # --- Diagnostic plots ---
            tag = (f"{mouse}_{group}_{session_str}_{train_label}"
                   f"_to_{tgt_name}_{pf_str}")
            out = res["out"]

            fig, ax = plt.subplots(figsize=(8, 5), dpi=150)
            ax.hist(err, bins=50, color="darkorange", alpha=0.8)
            ax.set_xlabel(_euclidean_error_axis_label())
            ax.set_ylabel("Count")
            ax.set_title(
                f"{mouse} {group} — {train_label}→{tgt_name} PF")
            ax.axvline(np.nanmedian(err), color="red", ls="--",
                        label=f"median={np.nanmedian(err):.1f}")
            ax.legend(); fig.tight_layout()
            fig.savefig(os.path.join(save_path,
                        f"{tag}_errhist.png"), dpi=300)
            if plot_debug:
                plt.show()
            if auto_close:
                plt.close(fig)

            fig, axes = plt.subplots(1, 2, figsize=(12, 5), dpi=150)
            for ax, t, d, lb in [
                (axes[0], out["true_x"], out["decoded_x"], "X"),
                (axes[1], out["true_y"], out["decoded_y"], "Y"),
            ]:
                ax.scatter(t, d, s=6, alpha=0.3)
                lo = min(np.nanmin(t), np.nanmin(d))
                hi = max(np.nanmax(t), np.nanmax(d))
                ax.plot([lo, hi], [lo, hi], "r-", lw=1.5)
                ax.set_xlabel(f"True {lb} ({unit_label})")
                ax.set_ylabel(f"Decoded {lb} ({unit_label})")
                ax.set_title(
                    f"{mouse} {group} — {train_label}→{tgt_name} PF {lb}")
                ax.grid(True, alpha=0.2)
            fig.tight_layout()
            fig.savefig(os.path.join(save_path,
                        f"{tag}_scatter_XY.png"), dpi=300)
            if plot_debug:
                plt.show()
            if auto_close:
                plt.close(fig)

            fig, ax = plt.subplots(figsize=(7, 7), dpi=150)
            ax.plot(out["true_x"], out["true_y"], "k-", alpha=0.15,
                    lw=0.5, label="true")
            ax.scatter(out["decoded_x"], out["decoded_y"], c=err,
                       s=10, alpha=0.6, cmap="hot", vmin=0,
                       vmax=(np.nanpercentile(err, 95)
                             if err.size > 0 else 1))
            cb = plt.colorbar(ax.collections[-1], ax=ax, pad=0.02)
            cb.set_label(f"Eucl. error ({unit_label})")
            ax.set_xlabel(_xy_axis_label("X")); ax.set_ylabel(_xy_axis_label("Y"))
            ax.set_title(
                f"{mouse} {group} — {train_label}→{tgt_name} PF traj")
            ax.set_aspect("equal"); fig.tight_layout()
            fig.savefig(os.path.join(save_path,
                        f"{tag}_traj2D.png"), dpi=300)
            if plot_debug:
                plt.show()
            if auto_close:
                plt.close(fig)

        all_results[mouse] = mouse_res

    n_ok = sum(1 for v in all_results.values()
               if any(v["targets"].get(t, {}).get("ok")
                      for t in target_names))
    print(f"[2D-PF-POOL] Done. {len(all_results)} mice, "
          f"{n_ok} with ≥1 successful target.")
    return all_results


# =====================================================================
#  TFC cross-session vs within-session MixedLM comparison
# =====================================================================

def build_tfc_cross_vs_within_df(
    results_A: dict,
    results_B: dict,
    results_C: dict,
    mouse_groups: dict,
    use_scoring_method: str = "euclidean",
    pct_threshold=15.0,
) -> pd.DataFrame:
    """
    Combine paradigm A/B/C multi-target results into a single DataFrame
    for cross-session vs within-session MixedLM analysis.

    Extracts:
      - from paradigm A (train TFC_cond): within_TFC_cond, TFC_cond_to_Test_B,
                                           TFC_cond_to_Test_A
      - from paradigm B (train Test_B):   within_Test_B
      - from paradigm C (train Test_A):   within_Test_A
    """
    df_A = build_decoder_summary_dataframe(
        results_A, mouse_groups, train_label="TFC_cond",
        use_scoring_method=use_scoring_method,
        pct_threshold=pct_threshold)
    df_B = build_decoder_summary_dataframe(
        results_B, mouse_groups, train_label="Test_B",
        use_scoring_method=use_scoring_method,
        pct_threshold=pct_threshold)
    df_C = build_decoder_summary_dataframe(
        results_C, mouse_groups, train_label="Test_A",
        use_scoring_method=use_scoring_method,
        pct_threshold=pct_threshold)

    parts = [
        df_A[df_A["condition"] == "within_TFC_cond"],
        df_A[df_A["condition"] == "TFC_cond_to_Test_B"],
        df_A[df_A["condition"] == "TFC_cond_to_Test_A"],
        df_B[df_B["condition"] == "within_Test_B"],
        df_C[df_C["condition"] == "within_Test_A"],
    ]
    return pd.concat([p for p in parts if len(p) > 0], ignore_index=True)


# ---------------------------------------------------------------------------
#  Generic design-vector / contrast helpers (arbitrary conditions)
# ---------------------------------------------------------------------------

def _fe_design_vector_generic(param_index, group, cond):
    """
    Build a fixed-effects design vector for *any* group × condition model
    (treatment-coded, reference = mCherry × first condition level).
    """
    idx = list(param_index)
    x = np.zeros(len(idx), dtype=float)

    def _set(name, val=1.0):
        if name in idx:
            x[idx.index(name)] = val

    _set("Intercept", 1.0)

    # group main effect
    for g in ["hM3D", "hM4D"]:
        if group == g:
            _set(f"group[T.{g}]", 1.0)

    # condition main effect & interactions — scan param names
    for name in idx:
        if name.startswith("condition[T.") and name.endswith("]"):
            c_level = name[len("condition[T."):-1]
            if cond == c_level:
                _set(name, 1.0)
        elif ":condition[T." in name and name.startswith("group[T."):
            g_part, c_part = name.split(":")
            g_level = g_part[len("group[T."):-1]
            c_level = c_part[len("condition[T."):-1]
            if group == g_level and cond == c_level:
                _set(name, 1.0)

    return x


def _predicted_mean_sem_generic(res, group, cond):
    """Model-based predicted mean and SEM for any group × condition."""
    beta = res.fe_params.values
    cov = np.asarray(res.cov_params())
    p_fe = len(res.fe_params)
    cov = cov[:p_fe, :p_fe]

    x = _fe_design_vector_generic(res.fe_params.index, group, cond)
    mean_val = float(x @ beta)
    sem_val = float(np.sqrt(max(x @ cov @ x, 0.0)))
    return mean_val, sem_val


def _param_index_values_cov_generic(res):
    """Return parameter index, values, and covariance for MixedLM or OLS results."""
    if hasattr(res, "fe_params"):
        params = res.fe_params
        cov = np.asarray(res.cov_params())
        p_fe = len(params)
        cov = cov[:p_fe, :p_fe]
    else:
        params = res.params
        cov = np.asarray(res.cov_params())
    return params.index, np.asarray(params.values, dtype=float), cov


def _estimate_se_from_contrast_vector(res, d):
    """Estimate and SE for a linear contrast vector aligned to result params."""
    _, beta, cov = _param_index_values_cov_generic(res)
    est = float(d @ beta)
    var_val = float(d @ cov @ d)
    se = float(np.sqrt(max(var_val, 0.0)))
    return est, se


def _wald_contrast_generic(res, group, cond_A, cond_B):
    """Wald z-test for (cond_A − cond_B) within *group*. Generic version."""
    beta = res.fe_params.values
    cov = np.asarray(res.cov_params())
    p_fe = len(res.fe_params)
    cov = cov[:p_fe, :p_fe]

    xA = _fe_design_vector_generic(res.fe_params.index, group, cond_A)
    xB = _fe_design_vector_generic(res.fe_params.index, group, cond_B)
    d = xA - xB

    est = float(d @ beta)
    var_val = float(d @ cov @ d)
    se = float(np.sqrt(max(var_val, 0.0)))
    z = est / se if se > 0 else np.nan
    p = 2 * (1 - norm.cdf(abs(z))) if np.isfinite(z) else np.nan
    return dict(est=est, se=se, z=z, p=p)


def _wald_contrast_between_groups(res, group_i, group_j, cond_A, cond_B):
    """Wald z-test for whether (condA − condB) differs between group_i and group_j.

    Tests H0: [group_i's (condA−condB)] == [group_j's (condA−condB)].
    """
    beta = res.fe_params.values
    cov = np.asarray(res.cov_params())
    p_fe = len(res.fe_params)
    cov = cov[:p_fe, :p_fe]

    xAi = _fe_design_vector_generic(res.fe_params.index, group_i, cond_A)
    xBi = _fe_design_vector_generic(res.fe_params.index, group_i, cond_B)
    xAj = _fe_design_vector_generic(res.fe_params.index, group_j, cond_A)
    xBj = _fe_design_vector_generic(res.fe_params.index, group_j, cond_B)

    d = (xAi - xBi) - (xAj - xBj)
    est = float(d @ beta)
    var_val = float(d @ cov @ d)
    se = float(np.sqrt(max(var_val, 0.0)))
    z = est / se if se > 0 else np.nan
    p = 2 * (1 - norm.cdf(abs(z))) if np.isfinite(z) else np.nan
    return dict(est=est, se=se, z=z, p=p)


def _f_contrast_generic(res, group, cond_A, cond_B):
    """F-test for (cond_A − cond_B) within *group* from a fixed-effects model."""
    from scipy.stats import f as f_dist

    param_index, _, _ = _param_index_values_cov_generic(res)
    xA = _fe_design_vector_generic(param_index, group, cond_A)
    xB = _fe_design_vector_generic(param_index, group, cond_B)
    d = xA - xB

    est, se = _estimate_se_from_contrast_vector(res, d)
    try:
        f_res = res.f_test(np.atleast_2d(d))
        f_val = float(np.asarray(f_res.fvalue).squeeze())
        p_val = float(np.asarray(f_res.pvalue).squeeze())
        df_num = float(np.asarray(getattr(f_res, "df_num", 1.0)).squeeze())
        df_den = float(np.asarray(getattr(f_res, "df_denom", np.nan)).squeeze())
    except Exception:
        t_val = est / se if se > 0 else np.nan
        f_val = float(t_val ** 2) if np.isfinite(t_val) else np.nan
        df_num = 1.0
        df_den = float(getattr(res, "df_resid", np.nan))
        p_val = 1 - f_dist.cdf(f_val, df_num, df_den) if np.isfinite(f_val) else np.nan

    return dict(est=est, se=se, f=f_val, p=p_val, df_num=df_num, df_den=df_den)


def _f_contrast_between_groups(res, group_i, group_j, cond_A, cond_B):
    """F-test for whether (condA − condB) differs between group_i and group_j."""
    from scipy.stats import f as f_dist

    param_index, _, _ = _param_index_values_cov_generic(res)
    xAi = _fe_design_vector_generic(param_index, group_i, cond_A)
    xBi = _fe_design_vector_generic(param_index, group_i, cond_B)
    xAj = _fe_design_vector_generic(param_index, group_j, cond_A)
    xBj = _fe_design_vector_generic(param_index, group_j, cond_B)
    d = (xAi - xBi) - (xAj - xBj)

    est, se = _estimate_se_from_contrast_vector(res, d)
    try:
        f_res = res.f_test(np.atleast_2d(d))
        f_val = float(np.asarray(f_res.fvalue).squeeze())
        p_val = float(np.asarray(f_res.pvalue).squeeze())
        df_num = float(np.asarray(getattr(f_res, "df_num", 1.0)).squeeze())
        df_den = float(np.asarray(getattr(f_res, "df_denom", np.nan)).squeeze())
    except Exception:
        t_val = est / se if se > 0 else np.nan
        f_val = float(t_val ** 2) if np.isfinite(t_val) else np.nan
        df_num = 1.0
        df_den = float(getattr(res, "df_resid", np.nan))
        p_val = 1 - f_dist.cdf(f_val, df_num, df_den) if np.isfinite(f_val) else np.nan

    return dict(est=est, se=se, f=f_val, p=p_val, df_num=df_num, df_den=df_den)


def _run_tfc_mixedlm_lrt_suite(df_model, err_col, save_path, *,
                               file_prefix="tfc_cross_vs_within"):
    """Run omnibus nested-model LRTs for MixedLM fixed effects.

    Tests:
      1) interaction: group * condition vs group + condition
      2) group main effect: group + condition vs condition
      3) condition main effect: group + condition vs group
    """
    model_specs = [
        ("full", f"{err_col} ~ group * condition"),
        ("additive", f"{err_col} ~ group + condition"),
        ("condition_only", f"{err_col} ~ condition"),
        ("group_only", f"{err_col} ~ group"),
    ]

    fitted = {}
    _lrt_methods = ["lbfgs", "powell", "cg", "nm"]
    for name, formula in model_specs:
        _fit_ok = False
        for _m in _lrt_methods:
            try:
                md = smf.mixedlm(formula, df_model, groups=df_model["mouse"])
                res = md.fit(reml=False, method=_m, maxiter=2000, disp=False)
                fitted[name] = res
                print(f"[TFC-LRT | {file_prefix}] Fit {name}: llf={res.llf:.3f}, "
                      f"params={len(res.fe_params)} (method={_m})")
                _fit_ok = True
                break
            except Exception as e:
                pass
        if not _fit_ok:
            print(f"[TFC-LRT | {file_prefix}] Failed to fit {name} with all methods")
            fitted[name] = None

    comparisons = [
        ("group:condition interaction", "full", "additive"),
        ("group main effect", "additive", "condition_only"),
        ("condition main effect", "additive", "group_only"),
    ]

    rows = []
    for label, full_name, red_name in comparisons:
        full_res = fitted.get(full_name)
        red_res = fitted.get(red_name)
        if full_res is None or red_res is None:
            rows.append(dict(
                test=label,
                full_model=full_name,
                reduced_model=red_name,
                lr_stat=np.nan,
                df=np.nan,
                p=np.nan,
                llf_full=np.nan if full_res is None else float(full_res.llf),
                llf_reduced=np.nan if red_res is None else float(red_res.llf),
            ))
            continue

        df_diff = len(full_res.fe_params) - len(red_res.fe_params)
        lr_stat = 2.0 * (float(full_res.llf) - float(red_res.llf))
        p_val = float(chi2.sf(max(lr_stat, 0.0), df_diff)) if df_diff > 0 else np.nan
        rows.append(dict(
            test=label,
            full_model=full_name,
            reduced_model=red_name,
            lr_stat=lr_stat,
            df=df_diff,
            p=p_val,
            llf_full=float(full_res.llf),
            llf_reduced=float(red_res.llf),
        ))

    df_lrt = pd.DataFrame(rows)
    csv_path = os.path.join(save_path, f"{file_prefix}_lrt_omnibus.csv")
    df_lrt.to_csv(csv_path, index=False)
    print(f"[TFC-LRT | {file_prefix}] Saved omnibus LRT CSV -> {csv_path}")
    print(df_lrt.to_string(index=False))

    try:
        fig, ax = plt.subplots(figsize=(4.4, 3.0), dpi=160)
        x = np.arange(len(df_lrt))
        vals = df_lrt["lr_stat"].to_numpy(dtype=float)
        vals = np.where(np.isfinite(vals), vals, 0.0)
        bars = ax.bar(x, vals, color="#7f8c8d", edgecolor="black", linewidth=0.6)
        for b in bars:
            b.set_alpha(0.8)

        ax.set_xticks(x)
        ax.set_xticklabels(["interaction", "group", "condition"], rotation=15, ha="right")
        ax.set_ylabel("LRT statistic")
        ax.set_title("MixedLM omnibus LRTs", fontsize=11)
        ax.grid(True, axis="y", alpha=0.25)

        y_max = max(np.nanmax(vals) if vals.size else 0.0, 1.0)
        for i, row in df_lrt.iterrows():
            if not np.isfinite(row["p"]):
                continue
            s = _star(float(row["p"]))
            if not s:
                s = f"p={float(row['p']):.2f}"
            ax.text(i, vals[i] + 0.05 * y_max, s, ha="center", va="bottom",
                    fontsize=7.5 if s.startswith("p=") else 9)
        _pad_axes_for_stars(ax, margin_frac=0.16)
        fig.tight_layout()
        for ext in (".png", ".svg"):
            out_path = os.path.join(save_path, f"{file_prefix}_lrt_omnibus{ext}")
            fig.savefig(out_path, dpi=300, bbox_inches="tight")
            print(f"[TFC-LRT | {file_prefix}] Saved omnibus LRT figure -> {out_path}")
        plt.show()
        plt.close(fig)
    except Exception as e:
        print(f"[TFC-LRT | {file_prefix}] Failed to plot omnibus LRTs: {e}")

    return df_lrt


def _run_tfc_emmeans_posthoc_suite(model_res, contrast_spec, save_path, *,
                                   file_prefix="tfc_cross_vs_within"):
    """EMMeans-style post hoc summaries from the fitted MixedLM fixed effects.

    Notes:
      - Uses model-based estimated marginal means (group × condition).
      - Uses asymptotic z-based inference for planned contrasts.
      - Adds Holm correction and a Tukey-style p approximation (k=3, df=inf)
        for pairwise group comparisons within each contrast.
    """
    from statsmodels.stats.multitest import multipletests

    # Conditions that appear in requested planned contrasts
    conds = []
    for _, cA, cB in contrast_spec:
        if cA not in conds:
            conds.append(cA)
        if cB not in conds:
            conds.append(cB)

    # --- Estimated marginal means (group × condition) ---
    emm_rows = []
    for cond in conds:
        for g in _TFC_GROUPS:
            m, s = _predicted_mean_sem_generic(model_res, g, cond)
            emm_rows.append(dict(group=g, condition=cond, emmean=m, se=s))
    df_emm = pd.DataFrame(emm_rows)
    emm_csv = os.path.join(save_path, f"{file_prefix}_emmeans_marginal_means.csv")
    df_emm.to_csv(emm_csv, index=False)
    print(f"[TFC-EMMeans | {file_prefix}] Saved marginal means -> {emm_csv}")

    # --- Planned contrasts within each group (condA - condB) ---
    within_rows = []
    for label, cA, cB in contrast_spec:
        for g in _TFC_GROUPS:
            c = _wald_contrast_generic(model_res, g, cA, cB)
            within_rows.append(dict(
                contrast=label,
                group=g,
                cond_A=cA,
                cond_B=cB,
                est=c["est"],
                se=c["se"],
                z=c["z"],
                p=c["p"],
            ))
    df_within = pd.DataFrame(within_rows)
    within_csv = os.path.join(save_path, f"{file_prefix}_emmeans_contrasts_within_group.csv")
    df_within.to_csv(within_csv, index=False)
    print(f"[TFC-EMMeans | {file_prefix}] Saved within-group contrast table -> {within_csv}")

    # --- Pairwise group differences of planned contrasts ---
    pair_rows = []
    pairs = list(itertools.combinations(_TFC_GROUPS, 2))
    for label, cA, cB in contrast_spec:
        raw_ps = []
        per_pair = []
        for g1, g2 in pairs:
            c = _wald_contrast_between_groups(model_res, g1, g2, cA, cB)
            raw_ps.append(float(c["p"]))
            per_pair.append((g1, g2, c))

        # Holm within each contrast family (3 group-pairs)
        _, p_holm, _, _ = multipletests(raw_ps, method="holm")

        for i, (g1, g2, c) in enumerate(per_pair):
            p_tukey_inf = np.nan
            try:
                # Tukey-style approximation from studentized-range with df=inf
                # q = sqrt(2)*|z| for pairwise mean differences.
                from scipy.stats import studentized_range
                z_abs = abs(float(c["z"])) if np.isfinite(float(c["z"])) else np.nan
                if np.isfinite(z_abs):
                    q_stat = np.sqrt(2.0) * z_abs
                    p_tukey_inf = float(studentized_range.sf(q_stat, len(_TFC_GROUPS), np.inf))
            except Exception:
                p_tukey_inf = np.nan

            pair_rows.append(dict(
                contrast=label,
                cond_A=cA,
                cond_B=cB,
                group_1=g1,
                group_2=g2,
                est_diff=c["est"],
                se=c["se"],
                z=c["z"],
                p_raw=c["p"],
                p_holm=float(p_holm[i]),
                p_tukey_inf=p_tukey_inf,
            ))

    df_pair = pd.DataFrame(pair_rows)
    pair_csv = os.path.join(save_path, f"{file_prefix}_emmeans_pairwise_group_differences.csv")
    df_pair.to_csv(pair_csv, index=False)
    print(f"[TFC-EMMeans | {file_prefix}] Saved pairwise group-difference table -> {pair_csv}")

    def _format_contrast_title_emm(key: str) -> str:
        title = str(key)
        title = title.replace("Within TFC_cond", r"$\mathrm{Cond}_{\mathrm{within}}$")
        title = title.replace("Within Test A", r"$\mathrm{TestA}_{\mathrm{within}}$")
        title = title.replace("Within Test B", r"$\mathrm{TestB}_{\mathrm{within}}$")
        title = title.replace("TFC", "Cond")
        parts = title.split(" − ", 1)
        if len(parts) == 2:
            return f"{parts[0]}\n− {parts[1]}"
        return title

    def _draw_emmeans_between_axis(ax, key, *, p_col, ylabel):
        groups = _TFC_GROUPS
        x0 = np.arange(len(groups))
        width = 0.55
        col = _PAPER_COLORS

        sub = df_within[df_within["contrast"] == key].copy()
        if sub.empty:
            return
        sub["group"] = pd.Categorical(sub["group"], categories=groups, ordered=True)
        sub = sub.sort_values("group")
        ests = sub["est"].to_numpy(dtype=float)
        ses = sub["se"].to_numpy(dtype=float)

        yerr = one_sided_yerr_by_sign(ests, ses)
        bars = ax.bar(x0, ests, width=width, yerr=yerr, capsize=3,
                      color=[col[g] for g in groups],
                      edgecolor="black", linewidth=0.6,
                      error_kw=dict(lw=1.5, capthick=1.5))
        for b in bars:
            b.set_alpha(0.7)

        ax.set_title(_format_contrast_title_emm(key), fontsize=10)
        ax.set_xticks(x0)
        ax.set_xticklabels([_TFC_GROUP_LABELS[g] for g in groups], fontsize=11)
        ax.set_ylabel(ylabel, fontsize=11)
        ax.axhline(0, linewidth=0.8)
        ax.grid(True, axis="y", alpha=0.25)
        ax.tick_params(axis="y", labelsize=10)
        _pad_axes_for_stars(ax)

        psub = df_pair[df_pair["contrast"] == key].copy()
        if psub.empty or p_col not in psub.columns:
            return

        g_to_i = {g: i for i, g in enumerate(groups)}
        pairs = []
        for _, r in psub.iterrows():
            g1 = str(r["group_1"])
            g2 = str(r["group_2"])
            if g1 not in g_to_i or g2 not in g_to_i:
                continue
            p_use = float(r[p_col]) if np.isfinite(r[p_col]) else np.nan
            p_raw = float(r["p_raw"]) if np.isfinite(r["p_raw"]) else np.nan
            pairs.append((g_to_i[g1], g_to_i[g2], p_use, p_raw))

        if not pairs:
            return

        tops = np.array([e + s if e >= 0 else e - s for e, s in zip(ests, ses)])
        _, y_ax_top = ax.get_ylim()
        y_max = max(np.nanmax(tops), y_ax_top)
        y_rng = max(abs(y_max), 1.0)
        bdy = 0.025 * y_rng
        bgap = 2.4 * bdy
        by = y_ax_top - 0.02 * y_rng

        order = sorted(range(len(pairs)), key=lambda k: abs(pairs[k][1] - pairs[k][0]))
        for k in order:
            i, j, p_use, p_raw = pairs[k]
            if not np.isfinite(p_use):
                continue
            star, fs = _p_to_star(p_use, p_raw if np.isfinite(p_raw) else p_use)
            if star is None:
                continue
            x1, x2 = x0[i], x0[j]
            ax.plot([x1, x1, x2, x2], [by, by + bdy, by + bdy, by], color="#333333", lw=0.7)
            ax.text((x1 + x2) / 2, by + bdy + 0.001 * y_rng, star,
                    ha="center", va="bottom", fontsize=fs, color="#333333")
            by += bgap

        _pad_axes_for_stars(ax)

    stat_tag = "mean" if "_mean" in os.path.basename(save_path) else "median"

    def _save_emmeans_between_family(panel_keys, family_name, *, p_col, suffix):
        fig, axes = plt.subplots(2, 1, figsize=(2.8, 6.0), dpi=160)
        _draw_emmeans_between_axis(axes[0], panel_keys[0], p_col=p_col, ylabel="Contrast vs ref")
        _draw_emmeans_between_axis(axes[1], panel_keys[1], p_col=p_col, ylabel="Contrast vs within")
        for ax in axes:
            if hasattr(ax, "set_box_aspect"):
                ax.set_box_aspect(2.0)
        fig.tight_layout(h_pad=1.2)
        saved = []
        for ext in (".png", ".svg"):
            out = os.path.join(
                save_path,
                f"{file_prefix}_contrasts_{family_name}_{stat_tag}_{suffix}{ext}",
            )
            fig.savefig(out, dpi=300, bbox_inches="tight")
            saved.append(out)
        plt.show()
        plt.close(fig)
        print(f"[TFC-EMMeans | {file_prefix}] Saved {family_name} {suffix}:")
        for p in saved:
            print(f"  - {p}")

    if file_prefix == "tfc_cross_vs_withinCond":
        panel_B_keys = [
            "Within Test A − Within TFC_cond",
            "(TFC → Test A) − Within TFC_cond",
        ]
        panel_C_keys = [
            "Within Test B − Within TFC_cond",
            "(TFC → Test B) − Within TFC_cond",
        ]
    else:
        panel_B_keys = [
            "Within Test A − Within TFC_cond",
            "(TFC → Test A) − Within Test A",
        ]
        panel_C_keys = [
            "Within Test B − Within TFC_cond",
            "(TFC → Test B) − Within Test B",
        ]

    _save_emmeans_between_family(
        panel_B_keys, "TestA", p_col="p_holm", suffix="emmeans_between_holm")
    _save_emmeans_between_family(
        panel_C_keys, "TestB", p_col="p_holm", suffix="emmeans_between_holm")
    _save_emmeans_between_family(
        panel_B_keys, "TestA", p_col="p_tukey_inf", suffix="emmeans_between_tukey")
    _save_emmeans_between_family(
        panel_C_keys, "TestB", p_col="p_tukey_inf", suffix="emmeans_between_tukey")

    # Brief methods note in output folder for provenance
    note_path = os.path.join(save_path, f"{file_prefix}_emmeans_notes.txt")
    with open(note_path, "w", encoding="utf-8") as f:
        f.write("EMMeans-style post hoc outputs\n")
        f.write("================================\n")
        f.write("Model source: MixedLM fixed effects from statsmodels (asymptotic).\n")
        f.write("Within-group contrasts and pairwise group-difference contrasts use z-based Wald inference.\n")
        f.write("Pairwise tables include Holm-corrected p-values and a Tukey-style p approximation\n")
        f.write("from the studentized-range distribution with k=3 groups and df=inf.\n")
    print(f"[TFC-EMMeans | {file_prefix}] Saved notes -> {note_path}")

    return dict(emmeans=df_emm, within=df_within, pairwise=df_pair)


# ---------------------------------------------------------------------------
#  Main TFC cross-vs-within analysis pipeline
# ---------------------------------------------------------------------------

_TFC_COND_ORDER = [
    "within_TFC_cond",
    "within_Test_A",
    "within_Test_B",
    "TFC_cond_to_Test_A",
    "TFC_cond_to_Test_B",
]

_TFC_GROUPS = ["mCherry", "hM3D", "hM4D"]
_TFC_GROUP_LABELS = {"mCherry": "Ctl", "hM3D": "Exc", "hM4D": "Inh"}


def run_tfc_cross_vs_within_analysis(
    results_A: dict,
    results_B: dict,
    results_C: dict,
    mouse_groups: dict,
    PLOTS_DIR: str,
    use_scoring_method: str = "euclidean",
    use_median: bool = True,
    run_fixed_effects_models: bool = True,
    auto_close: bool = True,
    pct_threshold=15.0,
    stat_label_override=None,
):
    """
    MixedLM analysis of TFC cross-session vs within-session decoding.

    Fits a single model with 5 condition levels:
      within_TFC_cond (ref), within_Test_A, within_Test_B,
      TFC_cond_to_Test_A, TFC_cond_to_Test_B

    Generates one figure:
      Panel A (3 subplots): predicted mean errors for Within TFC_cond,
                             Within Test_B, Within Test_A
      Panel B (2 stacked):  Test A contrasts
        - Within Test_A − Within TFC_cond
        - (TFC → Test_A) − Within Test_A
      Panel C (2 stacked):  Test B contrasts
        - Within Test_B − Within TFC_cond
        - (TFC → Test_B) − Within Test_B
    """
    scoring_method = str(use_scoring_method).strip().lower()
    methods = _normalize_scoring_methods(use_scoring_method)
    if len(methods) > 1:
        out = {}
        print("[TFC-MixedLM] Running both scoring methods: euclidean + rsquared")
        for method in methods:
            out[method] = run_tfc_cross_vs_within_analysis(
                results_A,
                results_B,
                results_C,
                mouse_groups,
                PLOTS_DIR,
                use_scoring_method=method,
                use_median=use_median,
                run_fixed_effects_models=run_fixed_effects_models,
                auto_close=auto_close,
                pct_threshold=pct_threshold,
                stat_label_override=stat_label_override,
            )
        return out

    scoring_method = methods[0]
    stat_label = stat_label_override if stat_label_override else ("median" if use_median else "mean")
    err_col = "pct_correct" if stat_label == "pct" else f"{stat_label}_err"
    score_tag = "rsquared" if scoring_method == "rsquared" else "euclidean"

    save_path = os.path.join(PLOTS_DIR,
                             f"tfc_cross_vs_within_mixedlm_{score_tag}_{stat_label}")
    os.makedirs(save_path, exist_ok=True)

    # Build combined DataFrame (5 conditions)
    df = build_tfc_cross_vs_within_df(
        results_A, results_B, results_C,
        mouse_groups,
        use_scoring_method=scoring_method,
        pct_threshold=pct_threshold)
    df.to_csv(os.path.join(save_path, "tfc_cross_vs_within_summary.csv"),
              index=False)
    print(f"\n[TFC-MixedLM] Combined summary ({len(df)} rows):")
    print(df.to_string(index=False))

    # Enforce categories
    cond_levels = [c for c in _TFC_COND_ORDER if c in df["condition"].unique()]
    df["group"] = pd.Categorical(df["group"], categories=_TFC_GROUPS)
    df["condition"] = pd.Categorical(df["condition"], categories=cond_levels)

    df_model = df[np.isfinite(df[err_col])].copy()
    if len(df_model) < 5 or df_model["condition"].nunique() < 2:
        print("[TFC-MixedLM] Not enough data to fit model.")
        return {}

    # --- Fit MixedLM: err ~ group * condition + (1|mouse) ---
    model_res = None
    try:
        md = smf.mixedlm(f"{err_col} ~ group * condition", df_model,
                         groups=df_model["mouse"])
        model_res = md.fit(reml=False)
        with open(os.path.join(save_path, "mixedlm_full.txt"), "w") as f:
            f.write(str(model_res.summary()))
        print(f"\n[TFC-MixedLM] Full model summary:")
        print(model_res.summary())
    except Exception as e:
        print(f"[TFC-MixedLM] Model failed: {e}")
        return {}

    fe_model = None
    if run_fixed_effects_models:
        try:
            fe_formula = f"{err_col} ~ group * condition + C(mouse)"
            fe_model = smf.ols(fe_formula, data=df_model).fit(cov_type="HC3")
            with open(os.path.join(save_path, "fixed_effects_full_ols.txt"), "w") as f:
                f.write(str(fe_model.summary()))
            try:
                from statsmodels.stats.anova import anova_lm
                fe_anova = anova_lm(fe_model, typ=2)
                fe_anova.to_csv(os.path.join(save_path, "fixed_effects_anova_type2.csv"))
            except Exception as _e_anova:
                print(f"[TFC-MixedLM] Fixed-effects ANOVA failed: {_e_anova}")
            print("[TFC-MixedLM] Fixed-effects OLS summary saved.")
        except Exception as e:
            print(f"[TFC-MixedLM] Fixed-effects OLS failed: {e}")

    print("[TFC-Inference] Wald = MixedLM asymptotic z-test on planned fixed-effect contrasts.")

    # --- Wald contrasts ---
    contrast_spec = [
        # Panel B: Test A
        ("Within Test A − Within TFC_cond",
         "within_Test_A", "within_TFC_cond"),
        ("(TFC → Test A) − Within Test A",
         "TFC_cond_to_Test_A", "within_Test_A"),
        # Panel C: Test B
        ("Within Test B − Within TFC_cond",
         "within_Test_B", "within_TFC_cond"),
        ("(TFC → Test B) − Within Test B",
         "TFC_cond_to_Test_B", "within_Test_B"),
    ]
    all_contrasts = {}
    for label, cA, cB in contrast_spec:
        rows = []
        for g in _TFC_GROUPS:
            c = _wald_contrast_generic(model_res, g, cA, cB)
            c["group"] = g
            c["contrast"] = label
            rows.append(c)
        df_c = pd.DataFrame(rows)
        all_contrasts[label] = df_c
        print(f"\n[TFC-MixedLM] {label}:")
        print(df_c.to_string(index=False))

    df_all_contrasts = pd.concat(all_contrasts.values(), ignore_index=True)
    df_all_contrasts.to_csv(
        os.path.join(save_path, "contrasts_all.csv"), index=False)

    # Build contrast → (condA, condB) mapping for between-group brackets
    contrast_cond_map = {label: (cA, cB) for label, cA, cB in contrast_spec}

    # --- Plot ---
    _plot_tfc_cross_vs_within_figure(
        df_model, err_col, model_res, all_contrasts,
        stat_label=stat_label, scoring_method=scoring_method, save_path=save_path,
        auto_close=auto_close,
        contrast_cond_map=contrast_cond_map,
    )

    df_all_f_contrasts = None
    if fe_model is not None:
        print("[TFC-Inference] F = fixed-effects OLS HC3 contrast test with mouse included as a fixed effect.")
        all_f_contrasts = {}
        for label, cA, cB in contrast_spec:
            rows = []
            for g in _TFC_GROUPS:
                c = _f_contrast_generic(fe_model, g, cA, cB)
                c["group"] = g
                c["contrast"] = label
                rows.append(c)
            df_c = pd.DataFrame(rows)
            all_f_contrasts[label] = df_c
            print(f"\n[TFC-FTest] {label}:")
            print(df_c.to_string(index=False))

        df_all_f_contrasts = pd.concat(all_f_contrasts.values(), ignore_index=True)
        df_all_f_contrasts.to_csv(
            os.path.join(save_path, "contrasts_all_f_tests.csv"), index=False)

        _plot_tfc_cross_vs_within_figure(
            df_model, err_col, model_res, all_f_contrasts,
            stat_label=stat_label, scoring_method=scoring_method, save_path=save_path,
            auto_close=auto_close,
            contrast_cond_map=contrast_cond_map,
            annotation_prefix="f",
            save_panel_a=False,
            contrast_between_res=fe_model,
            contrast_between_test_kind="f",
        )
    else:
        print("[TFC-FTest] Skipping F-test contrast plots: fixed-effects OLS model unavailable.")

    df_lrt = _run_tfc_mixedlm_lrt_suite(
        df_model, err_col, save_path,
        file_prefix="tfc_cross_vs_within")

    emmeans_out = _run_tfc_emmeans_posthoc_suite(
        model_res, contrast_spec, save_path,
        file_prefix="tfc_cross_vs_within")

    _write_tfc_methods_txt(
        save_path,
        file_prefix="tfc_cross_vs_within",
        err_col=err_col,
        df_model=df_model,
        df_wald=df_all_contrasts,
        df_f=df_all_f_contrasts,
        df_lrt=df_lrt,
        emmeans_out=emmeans_out,
    )

    return dict(df=df, model=model_res, fixed_effects_model=fe_model, contrasts=df_all_contrasts)


# ---------------------------------------------------------------------------
#  Plotting: 3-panel figure matching LT 2-panel style
#    A (3 subplots): absolute predicted errors
#    B (2 stacked):  Test A contrasts
#    C (2 stacked):  Test B contrasts
# ---------------------------------------------------------------------------

def _plot_tfc_cross_vs_within_figure(
    df, err_col, model_res, all_contrasts, *,
    stat_label, scoring_method, save_path, auto_close=True,
    panel_B_keys=None, panel_C_keys=None, file_prefix="tfc_cross_vs_within",
    contrast_cond_map=None,
    annotation_prefix="wald",
    save_panel_a=True,
    contrast_between_res=None,
    contrast_between_test_kind="wald",
):
    """
        Save figures for TFC cross-vs-within MixedLM:
            1) Panel-A (3 subplots): absolute predicted means
            2) Test A contrast figure (2 rows)
            3) Test B contrast figure (2 rows)

        panel_B_keys / panel_C_keys let callers override which contrasts
        appear in the Test-A and Test-B contrast panels.
    """

    groups = _TFC_GROUPS
    n_groups = len(groups)
    x0 = np.arange(n_groups)
    width = 0.55
    if contrast_between_res is None:
        contrast_between_res = model_res

    # --- Panel A conditions ---
    panel_A_conds = [
        ("within_TFC_cond", "Within Cond"),
        ("within_Test_B",   "Within Test B"),
        ("within_Test_A",   "Within Test A"),
    ]

    # --- Panel B & C contrast keys (matching keys in all_contrasts dict) ---
    if panel_B_keys is None:
        panel_B_keys = [
            "Within Test A − Within TFC_cond",
            "(TFC → Test A) − Within Test A",
        ]
    if panel_C_keys is None:
        panel_C_keys = [
            "Within Test B − Within TFC_cond",
            "(TFC → Test B) − Within Test B",
        ]

    col = _PAPER_COLORS
    col_alpha = 0.7
    is_r2 = str(scoring_method).strip().lower() == "rsquared"
    score_label = "R2 (VAF)" if is_r2 else "decoding error"

    def _format_contrast_title(key: str) -> str:
        # Render within-session terms as mathtext; split on '−' for two lines.
        title = str(key)
        title = title.replace(
            "Within TFC_cond", r"$\mathrm{Cond}_{\mathrm{within}}$")
        title = title.replace(
            "Within Test A", r"$\mathrm{TestA}_{\mathrm{within}}$")
        title = title.replace(
            "Within Test B", r"$\mathrm{TestB}_{\mathrm{within}}$")
        title = title.replace("TFC", "Cond")
        # Two-line: put the subtracted term on its own line
        parts = title.split(" − ", 1)
        if len(parts) == 2:
            return f"{parts[0]}\n− {parts[1]}"
        return title

    def _draw_contrast_axis(ax, key, *, ylabel,
                            show_vs0=True, show_between=False):
        df_c = all_contrasts[key]
        ests = df_c["est"].values
        ses_arr = df_c["se"].values
        ps_arr = df_c["p"].values

        yerr = one_sided_yerr_by_sign(ests, ses_arr)
        bars = ax.bar(x0, ests, width=width, yerr=yerr, capsize=3,
                      color=[col[g] for g in groups],
                      edgecolor="black", linewidth=0.6,
                      error_kw=dict(lw=1.5, capthick=1.5))
        for b in bars:
            b.set_alpha(col_alpha)

        ax.set_title(_format_contrast_title(key), fontsize=10)
        ax.set_xticks(x0)
        ax.set_xticklabels([_TFC_GROUP_LABELS[g] for g in groups],
                           fontsize=11)
        ax.set_ylabel(ylabel, fontsize=11)
        ax.axhline(0, linewidth=0.8)
        ax.grid(True, axis="y", alpha=0.25)
        ax.tick_params(axis="y", labelsize=10)

        if show_vs0:
            # Stars on each bar (Wald test vs 0)
            y_rng = max(np.nanmax(np.abs(ests)), 1.0)
            bump = 0.03 * y_rng
            for i in range(n_groups):
                s = _star(ps_arr[i])
                if not s:
                    continue
                is_pval = s.startswith("p=")
                fs = 7.5 if is_pval else 9
                if ests[i] >= 0:
                    y = ests[i] + ses_arr[i] + bump
                    va = "bottom"
                else:
                    y = ests[i] - ses_arr[i] - bump
                    va = "top"
                ax.text(i, y, s, ha="center", va=va, fontsize=fs,
                        color="black")
            _pad_axes_for_stars(ax)

        if show_between and contrast_cond_map and key in contrast_cond_map:
            # Between-group Wald brackets for this contrast
            cA, cB = contrast_cond_map[key]
            _draw_tfc_contrast_between_group_brackets(
                ax, contrast_between_res, cA, cB, x0, ests, ses_arr,
                test_kind=contrast_between_test_kind)
            _pad_axes_for_stars(ax)

    # ======================================================================
    # Figure 1: Panel A only (3 subplots)
    # ======================================================================
    if save_panel_a:
        figA = plt.figure(figsize=(9.4, 5.4), dpi=160)
        gsA = GridSpec(1, 3, figure=figA, wspace=0.24)
        axA = [figA.add_subplot(gsA[0, i]) for i in range(3)]

        # ========== Panel A: absolute predicted means ==========
        for ci, (cond, title) in enumerate(panel_A_conds):
            ax = axA[ci]
            means, sems = [], []
            for g in groups:
                m, s = _predicted_mean_sem_generic(model_res, g, cond)
                means.append(m)
                sems.append(s)

            yerr = one_sided_yerr_by_sign(np.array(means), np.array(sems))
            bars = ax.bar(x0, means, width=width, yerr=yerr, capsize=3,
                          color=[col[g] for g in groups],
                          edgecolor="black", linewidth=0.6,
                          error_kw=dict(lw=1.5, capthick=1.5))
            for b in bars:
                b.set_alpha(col_alpha)

            # Between-group significance brackets
            _draw_tfc_between_group_brackets(ax, model_res, cond, x0, means, sems)

            ax.set_title(title, fontsize=13)
            ax.set_xticks(x0)
            ax.set_xticklabels([_TFC_GROUP_LABELS[g] for g in groups], fontsize=12)
            if ci == 0:
                if stat_label == "pct":
                    _ylabel_a = _euclidean_error_title(stat_label)
                else:
                    _ylabel_a = f"Predicted {stat_label} {score_label}"
            else:
                _ylabel_a = ""
            ax.set_ylabel(_ylabel_a, fontsize=12)
            ax.axhline(0, linewidth=0.8)
            ax.grid(True, axis="y", alpha=0.25)
            ax.tick_params(axis="y", labelsize=11)

        figA.tight_layout()
        for ext in (".png", ".svg"):
            figA.savefig(
                os.path.join(save_path,
                             f"{file_prefix}_panelA_{stat_label}{ext}"),
                dpi=300, bbox_inches="tight")
        plt.show()
        if auto_close:
            plt.close(figA)

    def _save_contrast_family(panel_keys, family_name, suffix, *,
                              show_vs0, show_between):
        fig, axes = plt.subplots(2, 1, figsize=(2.8, 6.0), dpi=160)
        _draw_contrast_axis(
            axes[0], panel_keys[0], ylabel="Contrast vs ref",
            show_vs0=show_vs0, show_between=show_between)
        _draw_contrast_axis(
            axes[1], panel_keys[1], ylabel="Contrast vs within",
            show_vs0=show_vs0, show_between=show_between)

        for ax in axes:
            if hasattr(ax, "set_box_aspect"):
                ax.set_box_aspect(2.0)  # height:width = 2:1
        fig.tight_layout(h_pad=1.2)

        saved_paths = []
        for ext in (".png", ".svg"):
            out_path = os.path.join(
                save_path,
                f"{file_prefix}_contrasts_{family_name}_{stat_label}_{suffix}{ext}",
            )
            fig.savefig(out_path, dpi=300, bbox_inches="tight")
            saved_paths.append(out_path)

        print(
            f"[TFC-MixedLM | {file_prefix}] Saved {family_name} {suffix}:"
        )
        for p in saved_paths:
            print(f"  - {p}")
        plt.show()
        if auto_close:
            plt.close(fig)

    # Contrast families: save two annotation variants each
    _save_contrast_family(
        panel_B_keys, "TestA", f"{annotation_prefix}_vs_0",
        show_vs0=True, show_between=False)
    _save_contrast_family(
        panel_B_keys, "TestA", f"{annotation_prefix}_between",
        show_vs0=False, show_between=True)
    _save_contrast_family(
        panel_C_keys, "TestB", f"{annotation_prefix}_vs_0",
        show_vs0=True, show_between=False)
    _save_contrast_family(
        panel_C_keys, "TestB", f"{annotation_prefix}_between",
        show_vs0=False, show_between=True)
    print(f"\n[TFC-MixedLM] Figures saved → {save_path}")
    print(f"  file_prefix = {file_prefix}")


def _draw_tfc_between_group_brackets(ax, model_res, cond, x0, means, sems):
    """Between-group Wald significance brackets on a Panel-A subplot."""
    from itertools import combinations

    groups = _TFC_GROUPS
    pairs = list(combinations(range(len(groups)), 2))

    if not pairs:
        return

    # Collect contrasts
    raw_ps, meta = [], []
    for i, j in pairs:
        c = _wald_contrast_generic(model_res, groups[i], cond, cond)
        # We need group difference, not condition difference.
        # Contrast: group_i − group_j within this condition
        beta = model_res.fe_params.values
        cov = np.asarray(model_res.cov_params())
        p_fe = len(model_res.fe_params)
        cov = cov[:p_fe, :p_fe]
        xI = _fe_design_vector_generic(model_res.fe_params.index,
                                       groups[i], cond)
        xJ = _fe_design_vector_generic(model_res.fe_params.index,
                                       groups[j], cond)
        d = xI - xJ
        est = float(d @ beta)
        var_val = float(d @ cov @ d)
        se = float(np.sqrt(max(var_val, 0.0)))
        z = est / se if se > 0 else np.nan
        p = 2 * (1 - norm.cdf(abs(z))) if np.isfinite(z) else np.nan
        raw_ps.append(p)
        meta.append((i, j, p))

    # Holm correction
    from statsmodels.stats.multitest import multipletests
    _, p_holm, _, _ = multipletests(raw_ps, method="holm")

    # Determine bar tops
    tops = np.array([m + s if m >= 0 else m for m, s in zip(means, sems)])
    y_max = max(tops)
    y_rng = max(y_max, 10.0)
    bdy = 0.030 * y_rng
    bgap = 2.6 * bdy
    by = y_max + 0.05 * y_rng

    # Sort by span (narrow first)
    order = sorted(range(len(meta)),
                   key=lambda k: abs(meta[k][1] - meta[k][0]))
    for k in order:
        i, j, p_raw = meta[k]
        p_h = float(p_holm[k])
        star, fs = _p_to_star(p_h, p_raw)
        if star is None:
            continue
        x1, x2 = x0[i], x0[j]
        ax.plot([x1, x1, x2, x2], [by, by + bdy, by + bdy, by],
                color="#333333", lw=0.7)
        ax.text((x1 + x2) / 2, by + bdy + 0.001 * y_rng, star,
                ha="center", va="bottom", fontsize=fs, color="#333333")
        by += bgap


def _draw_tfc_contrast_between_group_brackets(ax, model_res, cond_A, cond_B,
                                               x0, ests, ses,
                                               test_kind="wald"):
    """Between-group Wald brackets on a contrast subplot (condA − condB)."""
    from itertools import combinations
    from statsmodels.stats.multitest import multipletests

    groups = _TFC_GROUPS
    pairs = list(combinations(range(len(groups)), 2))
    if not pairs:
        return

    raw_ps, meta = [], []
    for i, j in pairs:
        if test_kind == "f":
            c = _f_contrast_between_groups(
                model_res, groups[i], groups[j], cond_A, cond_B)
        else:
            c = _wald_contrast_between_groups(
                model_res, groups[i], groups[j], cond_A, cond_B)
        raw_ps.append(c["p"])
        meta.append((i, j, c["p"]))

    _, p_holm, _, _ = multipletests(raw_ps, method="holm")

    # Bar tops: account for sign (positive bars extend upward, negative down)
    tops = np.array([
        e + s if e >= 0 else e - s for e, s in zip(ests, ses)])
    # Start brackets above the current axis top (which already includes
    # space for per-bar stars from _pad_axes_for_stars)
    _, y_ax_top = ax.get_ylim()
    y_max = max(np.nanmax(tops), y_ax_top)
    y_rng = max(abs(y_max), 1.0)
    bdy = 0.025 * y_rng
    bgap = 2.4 * bdy
    by = y_ax_top - 0.02 * y_rng  # start just inside padded top

    order = sorted(range(len(meta)),
                   key=lambda k: abs(meta[k][1] - meta[k][0]))
    for k in order:
        i, j, p_raw = meta[k]
        p_h = float(p_holm[k])
        star, fs = _p_to_star(p_h, p_raw)
        if star is None:
            continue
        x1, x2 = x0[i], x0[j]
        ax.plot([x1, x1, x2, x2], [by, by + bdy, by + bdy, by],
                color="#333333", lw=0.7)
        ax.text((x1 + x2) / 2, by + bdy + 0.001 * y_rng, star,
                ha="center", va="bottom", fontsize=fs, color="#333333")
        by += bgap


# ---------------------------------------------------------------------------
#  Variant: cross-session vs within-TFC_cond baseline
#  Contrasts: (TFC→TestA) − Within_TFC_cond,
#             (TFC→TestB) − Within_TFC_cond
# ---------------------------------------------------------------------------

def run_tfc_cross_vs_within_cond_baseline_analysis(
    results_A: dict,
    results_B: dict,
    results_C: dict,
    mouse_groups: dict,
    PLOTS_DIR: str,
    use_scoring_method: str = "euclidean",
    use_median: bool = True,
    run_fixed_effects_models: bool = True,
    auto_close: bool = True,
    pct_threshold=15.0,
    stat_label_override=None,
):
    """
    MixedLM: cross-session error vs the *conditioning* within-session baseline.

    Uses Paradigm A/B/C results.  Fits a 5-condition model (same as the
    original analysis) but the contrast set references Within TFC_cond as
    the baseline for both cross-session conditions:

    Contrasts:
      Within Test A    −  Within TFC_cond   (Panel B top)
      (TFC → Test A)   −  Within TFC_cond   (Panel B bottom)
      Within Test B    −  Within TFC_cond   (Panel C top)
      (TFC → Test B)   −  Within TFC_cond   (Panel C bottom)
    """
    methods = _normalize_scoring_methods(use_scoring_method)
    if len(methods) > 1:
        out = {}
        for method in methods:
            out[method] = run_tfc_cross_vs_within_cond_baseline_analysis(
                results_A, results_B, results_C,
                mouse_groups, PLOTS_DIR,
                use_scoring_method=method,
                use_median=use_median,
                run_fixed_effects_models=run_fixed_effects_models,
                auto_close=auto_close,
                pct_threshold=pct_threshold,
                stat_label_override=stat_label_override,
            )
        return out

    scoring_method = methods[0]
    stat_label = stat_label_override if stat_label_override else ("median" if use_median else "mean")
    err_col = "pct_correct" if stat_label == "pct" else f"{stat_label}_err"
    score_tag = "rsquared" if scoring_method == "rsquared" else "euclidean"

    save_path = os.path.join(
        PLOTS_DIR,
        f"tfc_cross_vs_withinCond_mixedlm_{score_tag}_{stat_label}")
    os.makedirs(save_path, exist_ok=True)

    # Build combined DataFrame (5 conditions) from A/B/C
    df = build_tfc_cross_vs_within_df(
        results_A, results_B, results_C,
        mouse_groups,
        use_scoring_method=scoring_method,
        pct_threshold=pct_threshold)
    df.to_csv(os.path.join(save_path, "tfc_cross_vs_withinCond_summary.csv"),
              index=False)
    print(f"\n[TFC-MixedLM-CondBase] Combined summary ({len(df)} rows):")
    print(df.to_string(index=False))

    cond_levels = [c for c in _TFC_COND_ORDER if c in df["condition"].unique()]
    df["group"] = pd.Categorical(df["group"], categories=_TFC_GROUPS)
    df["condition"] = pd.Categorical(df["condition"], categories=cond_levels)

    df_model = df[np.isfinite(df[err_col])].copy()
    if len(df_model) < 5 or df_model["condition"].nunique() < 2:
        print("[TFC-MixedLM-CondBase] Not enough data to fit model.")
        return {}

    # --- Fit MixedLM: err ~ group * condition + (1|mouse) ---
    model_res = None
    try:
        md = smf.mixedlm(f"{err_col} ~ group * condition", df_model,
                         groups=df_model["mouse"])
        model_res = md.fit(reml=False)
        with open(os.path.join(save_path, "mixedlm_full.txt"), "w") as f:
            f.write(str(model_res.summary()))
        print(f"\n[TFC-MixedLM-CondBase] Full model summary:")
        print(model_res.summary())
    except Exception as e:
        print(f"[TFC-MixedLM-CondBase] Model failed: {e}")
        return {}

    fe_model = None
    if run_fixed_effects_models:
        try:
            fe_formula = f"{err_col} ~ group * condition + C(mouse)"
            fe_model = smf.ols(fe_formula, data=df_model).fit(cov_type="HC3")
            with open(os.path.join(save_path, "fixed_effects_full_ols.txt"), "w") as f:
                f.write(str(fe_model.summary()))
            try:
                from statsmodels.stats.anova import anova_lm
                fe_anova = anova_lm(fe_model, typ=2)
                fe_anova.to_csv(os.path.join(save_path, "fixed_effects_anova_type2.csv"))
            except Exception as _e_anova:
                print(f"[TFC-MixedLM-CondBase] Fixed-effects ANOVA failed: {_e_anova}")
            print("[TFC-MixedLM-CondBase] Fixed-effects OLS summary saved.")
        except Exception as e:
            print(f"[TFC-MixedLM-CondBase] Fixed-effects OLS failed: {e}")

    print("[TFC-Inference-CondBase] Wald = MixedLM asymptotic z-test on planned fixed-effect contrasts.")

    # --- Wald contrasts: all referenced to Within TFC_cond ---
    contrast_spec = [
        # Panel B: Test A
        ("Within Test A − Within TFC_cond",
         "within_Test_A", "within_TFC_cond"),
        ("(TFC → Test A) − Within TFC_cond",
         "TFC_cond_to_Test_A", "within_TFC_cond"),
        # Panel C: Test B
        ("Within Test B − Within TFC_cond",
         "within_Test_B", "within_TFC_cond"),
        ("(TFC → Test B) − Within TFC_cond",
         "TFC_cond_to_Test_B", "within_TFC_cond"),
    ]
    all_contrasts = {}
    for label, cA, cB in contrast_spec:
        rows = []
        for g in _TFC_GROUPS:
            c = _wald_contrast_generic(model_res, g, cA, cB)
            c["group"] = g
            c["contrast"] = label
            rows.append(c)
        df_c = pd.DataFrame(rows)
        all_contrasts[label] = df_c
        print(f"\n[TFC-MixedLM-CondBase] {label}:")
        print(df_c.to_string(index=False))

    df_all_contrasts = pd.concat(all_contrasts.values(), ignore_index=True)
    df_all_contrasts.to_csv(
        os.path.join(save_path, "contrasts_cond_baseline.csv"), index=False)

    # Build contrast → (condA, condB) mapping for between-group brackets
    contrast_cond_map = {label: (cA, cB) for label, cA, cB in contrast_spec}

    # --- Plot using the shared plotter with cond-baseline contrast keys ---
    _plot_tfc_cross_vs_within_figure(
        df_model, err_col, model_res, all_contrasts,
        stat_label=stat_label, scoring_method=scoring_method,
        save_path=save_path, auto_close=auto_close,
        panel_B_keys=[
            "Within Test A − Within TFC_cond",
            "(TFC → Test A) − Within TFC_cond",
        ],
        panel_C_keys=[
            "Within Test B − Within TFC_cond",
            "(TFC → Test B) − Within TFC_cond",
        ],
        file_prefix="tfc_cross_vs_withinCond",
        contrast_cond_map=contrast_cond_map,
    )

    df_all_f_contrasts = None
    if fe_model is not None:
        print("[TFC-Inference-CondBase] F = fixed-effects OLS HC3 contrast test with mouse included as a fixed effect.")
        all_f_contrasts = {}
        for label, cA, cB in contrast_spec:
            rows = []
            for g in _TFC_GROUPS:
                c = _f_contrast_generic(fe_model, g, cA, cB)
                c["group"] = g
                c["contrast"] = label
                rows.append(c)
            df_c = pd.DataFrame(rows)
            all_f_contrasts[label] = df_c
            print(f"\n[TFC-FTest-CondBase] {label}:")
            print(df_c.to_string(index=False))

        df_all_f_contrasts = pd.concat(all_f_contrasts.values(), ignore_index=True)
        df_all_f_contrasts.to_csv(
            os.path.join(save_path, "contrasts_cond_baseline_f_tests.csv"), index=False)

        _plot_tfc_cross_vs_within_figure(
            df_model, err_col, model_res, all_f_contrasts,
            stat_label=stat_label, scoring_method=scoring_method,
            save_path=save_path, auto_close=auto_close,
            panel_B_keys=[
                "Within Test A − Within TFC_cond",
                "(TFC → Test A) − Within TFC_cond",
            ],
            panel_C_keys=[
                "Within Test B − Within TFC_cond",
                "(TFC → Test B) − Within TFC_cond",
            ],
            file_prefix="tfc_cross_vs_withinCond",
            contrast_cond_map=contrast_cond_map,
            annotation_prefix="f",
            save_panel_a=False,
            contrast_between_res=fe_model,
            contrast_between_test_kind="f",
        )
    else:
        print("[TFC-FTest-CondBase] Skipping F-test contrast plots: fixed-effects OLS model unavailable.")

    df_lrt = _run_tfc_mixedlm_lrt_suite(
        df_model, err_col, save_path,
        file_prefix="tfc_cross_vs_withinCond")

    emmeans_out = _run_tfc_emmeans_posthoc_suite(
        model_res, contrast_spec, save_path,
        file_prefix="tfc_cross_vs_withinCond")

    _write_tfc_methods_txt(
        save_path,
        file_prefix="tfc_cross_vs_withinCond",
        err_col=err_col,
        df_model=df_model,
        df_wald=df_all_contrasts,
        df_f=df_all_f_contrasts,
        df_lrt=df_lrt,
        emmeans_out=emmeans_out,
    )

    return dict(df=df, model=model_res, fixed_effects_model=fe_model,
                contrasts=df_all_contrasts)


    print(f"[TFC-MixedLM-CondBase] Figures saved → {save_path}")


# ==========================================================================
# ==  PARADIGM A-BEHAV : Error vs. Behaviour (freezing, speed, occupancy) ==
# ==========================================================================

def _compute_chunk_behavior(sess, idx_use, dt_sec, min_speed=2.0):
    """
    For each decoded chunk, compute behavioural metrics from the session.

    Parameters
    ----------
    sess : session object with ``velocities_miniscope_smooth``
    idx_use : (n_chunks, w) frame indices
    dt_sec : float, seconds per frame
    min_speed : float, cm/s threshold for mobility

    Returns
    -------
    dict with arrays of length n_chunks:
        chunk_mean_speed, chunk_freeze_frac
    """
    vel = np.asarray(sess.velocities_miniscope_smooth, dtype=float)
    n_chunks = idx_use.shape[0]
    mean_speed = np.full(n_chunks, np.nan)
    freeze_frac = np.full(n_chunks, np.nan)

    for c in range(n_chunks):
        frames = idx_use[c]
        valid = frames[frames < len(vel)]
        if valid.size == 0:
            continue
        v = vel[valid]
        mean_speed[c] = np.nanmean(v)
        freeze_frac[c] = float(np.sum(v < min_speed)) / valid.size

    return {"chunk_mean_speed": mean_speed, "chunk_freeze_frac": freeze_frac}


def _session_behavior_stats(sess, mask, dt_sec, min_speed=2.0,
                            n_x_bins=20, n_y_bins=20):
    """
    Whole-session (masked period) behavioural summary.

    Returns dict:
        session_freeze_frac, session_mean_speed, session_coverage
    """
    vel = np.asarray(sess.velocities_miniscope_smooth, dtype=float)
    T = min(len(vel), len(mask))
    vel = vel[:T]; mask = mask[:T]
    v_masked = vel[mask]

    freeze_frac = float(np.sum(v_masked < min_speed)) / max(v_masked.size, 1)
    mean_speed = float(np.nanmean(v_masked)) if v_masked.size else np.nan

    # Spatial coverage: fraction of 2D bins visited during masked period
    x = np.asarray(sess.loc_X_miniscope_smooth, dtype=float)[:T]
    y = np.asarray(sess.loc_Y_miniscope_smooth, dtype=float)[:T]
    x_m, y_m = x[mask], y[mask]

    x_edges = np.linspace(np.nanmin(x), np.nanmax(x), n_x_bins + 1)
    y_edges = np.linspace(np.nanmin(y), np.nanmax(y), n_y_bins + 1)
    bx = np.clip(np.digitize(x_m, x_edges) - 1, 0, n_x_bins - 1)
    by = np.clip(np.digitize(y_m, y_edges) - 1, 0, n_y_bins - 1)
    visited = set(zip(bx.tolist(), by.tolist()))
    coverage = len(visited) / (n_x_bins * n_y_bins)

    return {
        "session_freeze_frac": freeze_frac,
        "session_mean_speed": mean_speed,
        "session_coverage": coverage,
    }


def build_error_vs_behavior_df(
    all_results: dict,
    mouse_groups: dict,
    train_sessions: dict,
    test_targets: dict,
    train_label: str = "TFC_cond",
    min_speed: float = 2.0,
    first_n_sec: float = 180.0,
    n_x_bins: int = 20,
    n_y_bins: int = 20,
    encoder_period: str = "pre-tone",
) -> Tuple[pd.DataFrame, pd.DataFrame]:
    """
    Build two DataFrames from paradigm-A style results:

    1. **session_df**: one row per (mouse, condition) — session-level summaries
       Columns: mouse, group, condition, median_err, mean_err,
                     session_freeze_frac, session_mean_speed, session_coverage,
                     error_unit, distance_scale_cm_per_px

    2. **chunk_df**: one row per decoded chunk — time-bin resolution
       Columns: mouse, group, condition, chunk_err, Ksum,
                     chunk_mean_speed, chunk_freeze_frac,
                     error_unit, distance_scale_cm_per_px

    Parameters
    ----------
    all_results : output of run_2D_decoder_all_mice
    train_sessions, test_targets : original session dicts (for behavioural data)
    """
    sess_rows = []
    chunk_rows = []

    for mouse, mres in all_results.items():
        group = mouse_groups.get(mouse, mres.get("group", "NA"))
        train_s = train_sessions.get(mouse)
        default_unit = mres.get("position_unit", _TFC_TEST_2D_DISTANCE_UNIT)
        default_scale = float(mres.get("position_scale", _TFC_TEST_2D_CM_PER_PX))

        # --- Within-session CV on training session ---
        within = mres.get("within_train", {})
        if within.get("ok", False) and train_s is not None:
            cond = f"within_{train_label}"
            within_unit = within.get("position_unit", default_unit)
            within_scale = float(within.get("position_scale", default_scale))
            # Session-level behaviour (use full masked period without speed filter)
            mask_tr = build_pretone_mask_TFC(
                train_s, first_n_sec=first_n_sec,
                use_speed=False, min_speed=min_speed,
                encoder_period=encoder_period)[:train_s.S.shape[1]]
            dt_tr = _infer_dt_sec(train_s)
            sbeh = _session_behavior_stats(train_s, mask_tr, dt_tr,
                                           min_speed=min_speed,
                                           n_x_bins=n_x_bins, n_y_bins=n_y_bins)

            # Chunk-level: pool both CV folds
            for split_key in ["even_to_odd", "odd_to_even"]:
                sp = within.get(split_key, {})
                if "out" not in sp:
                    continue
                out = sp["out"]
                err = out.get("euclidean_err", np.array([]))
                Ksum = out.get("Ksum", np.array([]))
                idx_use = out.get("idx_use", np.zeros((0, 1), dtype=int))
                if err.size == 0:
                    continue
                cbeh = _compute_chunk_behavior(train_s, idx_use, dt_tr,
                                               min_speed=min_speed)
                for ci in range(err.size):
                    chunk_rows.append({
                        "mouse": mouse, "group": group, "condition": cond,
                        "chunk_err": float(err[ci]),
                        "Ksum": float(Ksum[ci]) if ci < len(Ksum) else np.nan,
                        "chunk_mean_speed": cbeh["chunk_mean_speed"][ci],
                        "chunk_freeze_frac": cbeh["chunk_freeze_frac"][ci],
                        "error_unit": within_unit,
                        "distance_scale_cm_per_px": within_scale,
                    })

            # Session-level error
            w_err = np.asarray(within.get("pooled_euclidean_err", []), float)
            # Ksum filtering
            w_Ksum_parts = []
            for sk in ["even_to_odd", "odd_to_even"]:
                sp = within.get(sk, {})
                if "out" in sp and "Ksum" in sp["out"]:
                    w_Ksum_parts.append(np.asarray(sp["out"]["Ksum"], float))
            w_Ksum = np.concatenate(w_Ksum_parts) if w_Ksum_parts else np.array([])
            if w_Ksum.size == w_err.size and w_err.size > 0:
                keep = np.isfinite(w_err)
            elif w_err.size > 0:
                keep = np.isfinite(w_err)
            else:
                keep = np.array([], dtype=bool)
            err_f = w_err[keep] if keep.any() else w_err

            sess_rows.append({
                "mouse": mouse, "group": group, "condition": cond,
                "median_err": float(np.nanmedian(err_f)) if err_f.size else np.nan,
                "mean_err": float(np.nanmean(err_f)) if err_f.size else np.nan,
                "error_unit": within_unit,
                "distance_scale_cm_per_px": within_scale,
                **sbeh,
            })

        # --- Cross-session targets ---
        targets = mres.get("targets", {})
        for tgt_name, tgt_res in targets.items():
            if not tgt_res.get("ok", False):
                continue
            cond = f"{train_label}_to_{tgt_name}"
            tgt_unit = tgt_res.get("position_unit", default_unit)
            tgt_scale = float(tgt_res.get("position_scale", default_scale))

            # Locate test session
            test_s = None
            if tgt_name in test_targets and mouse in test_targets[tgt_name]:
                test_s = test_targets[tgt_name][mouse]
            if test_s is None:
                continue

            out = tgt_res["out"]
            err_raw = np.asarray(out["euclidean_err"], float)
            Ksum = np.asarray(out["Ksum"], float)
            idx_use = out.get("idx_use", np.zeros((0, 1), dtype=int))

            # Session-level behaviour on test session (pre-tone mask without speed filter)
            dt_te = _infer_dt_sec(test_s)
            mask_te = build_pretone_mask_TFC(
                test_s, first_n_sec=first_n_sec,
                use_speed=False, min_speed=min_speed,
                encoder_period="pre-tone")[:test_s.S.shape[1]]
            sbeh = _session_behavior_stats(test_s, mask_te, dt_te,
                                           min_speed=min_speed,
                                           n_x_bins=n_x_bins, n_y_bins=n_y_bins)

            # Session-level error
            keep = np.isfinite(err_raw)
            err_f = err_raw[keep]
            sess_rows.append({
                "mouse": mouse, "group": group, "condition": cond,
                "median_err": float(np.nanmedian(err_f)) if err_f.size else np.nan,
                "mean_err": float(np.nanmean(err_f)) if err_f.size else np.nan,
                "error_unit": tgt_unit,
                "distance_scale_cm_per_px": tgt_scale,
                **sbeh,
            })

            # Chunk-level
            cbeh = _compute_chunk_behavior(test_s, idx_use, dt_te,
                                           min_speed=min_speed)
            for ci in range(err_raw.size):
                chunk_rows.append({
                    "mouse": mouse, "group": group, "condition": cond,
                    "chunk_err": float(err_raw[ci]),
                    "Ksum": float(Ksum[ci]) if ci < len(Ksum) else np.nan,
                    "chunk_mean_speed": cbeh["chunk_mean_speed"][ci],
                    "chunk_freeze_frac": cbeh["chunk_freeze_frac"][ci],
                    "error_unit": tgt_unit,
                    "distance_scale_cm_per_px": tgt_scale,
                })

    session_df = pd.DataFrame(sess_rows)
    chunk_df = pd.DataFrame(chunk_rows)
    return session_df, chunk_df


def _prepare_abehav_subsets(session_df_raw, chunk_df_raw, pooling_mode,
                            train_label="TFC_cond"):
    """
    Return a list of ``(sub_tag, session_df, chunk_df)`` tuples -- one per
    sub-analysis dictated by *pooling_mode*.

    ``'separate'``      -- one analysis per unique condition (5 decoders).
    ``'pooled'``        -- two analyses: TestA_48_1wk, TestB_48_1wk (drop within).
    ``'cross_session'`` -- one analysis: all cross-session merged (drop within).
    """
    if pooling_mode == "separate":
        out = []
        for cond in sorted(session_df_raw["condition"].unique()):
            s = session_df_raw[session_df_raw["condition"] == cond].copy()
            c = chunk_df_raw[chunk_df_raw["condition"] == cond].copy()
            out.append((cond, s, c))
        return out

    # Drop within-session rows for pooled / cross_session
    s_cross = session_df_raw[
        ~session_df_raw["condition"].str.startswith("within_")
    ].copy()
    c_cross = chunk_df_raw[
        ~chunk_df_raw["condition"].str.startswith("within_")
    ].copy()

    if pooling_mode == "pooled":
        out = []
        s_a = s_cross[s_cross["condition"].str.contains("Test_A")].copy()
        c_a = c_cross[c_cross["condition"].str.contains("Test_A")].copy()
        if not s_a.empty:
            out.append(("TestA_48_1wk", s_a, c_a))
        s_b = s_cross[s_cross["condition"].str.contains("Test_B")].copy()
        c_b = c_cross[c_cross["condition"].str.contains("Test_B")].copy()
        if not s_b.empty:
            out.append(("TestB_48_1wk", s_b, c_b))
        return out

    if pooling_mode == "cross_session":
        s_cross["condition"] = "cross_session"
        c_cross["condition"] = "cross_session"
        return [("cross_session", s_cross, c_cross)]

    return []


def run_error_vs_behavior_analysis(
    all_results: dict,
    mouse_groups: dict,
    train_sessions: dict,
    test_targets: dict,
    PLOTS_DIR: str,
    train_label: str = "TFC_cond",
    min_speed: float = 2.0,
    first_n_sec: float = 180.0,
    n_x_bins: int = 20,
    n_y_bins: int = 20,
    encoder_period: str = "pre-tone",
    pooling_mode: str = "separate",
    auto_close: bool = True,
):
    """
    Paradigm A-Behav: regress decoder error against freezing, speed,
    and spatial occupancy.

    Parameters
    ----------
    pooling_mode : str
        ``'separate'``       (A-Behav-Separate) — one analysis per decoder
                              (5 total), no pooling.
        ``'pooled'``         (A-Behav-Pooled)   — two sub-analyses:
                              TestA_48_1wk and TestB_48_1wk,
                              exclude within-TFC_cond.
        ``'cross_session'``  (A-Behav-Cross_session) — all cross-session conditions
                              merged, exclude within-TFC_cond.

    Each sub-analysis calls ``_run_abehav_single()`` which produces scatter
    plots, per-group panels, chunk-level scatter, and MixedLM models.
    """
    save_path = os.path.join(PLOTS_DIR, f"error_vs_behavior_{pooling_mode}")
    os.makedirs(save_path, exist_ok=True)

    # ---- Build raw DataFrames (all conditions) ----
    session_df_raw, chunk_df_raw = build_error_vs_behavior_df(
        all_results, mouse_groups, train_sessions, test_targets,
        train_label=train_label,
        min_speed=min_speed, first_n_sec=first_n_sec,
        n_x_bins=n_x_bins, n_y_bins=n_y_bins,
        encoder_period=encoder_period,
    )

    if session_df_raw.empty:
        print(f"[A-Behav-{pooling_mode}] No data -- skipping.")
        return

    subsets = _prepare_abehav_subsets(session_df_raw, chunk_df_raw,
                                     pooling_mode, train_label)
    for sub_tag, s_df, c_df in subsets:
        _run_abehav_single(s_df, c_df, save_path, sub_tag=sub_tag,
                           auto_close=auto_close)

    print(f"\n[A-Behav-{pooling_mode}] All sub-analyses saved to {save_path}")


def _run_abehav_single(
    session_df: pd.DataFrame,
    chunk_df: pd.DataFrame,
    save_path: str,
    sub_tag: str,
    auto_close: bool = True,
):
    """Run the full A-Behav pipeline (scatter + MixedLM) for one data subset.
    All output files include *sub_tag* in the name."""
    import matplotlib.pyplot as plt
    from matplotlib.lines import Line2D
    import statsmodels.formula.api as smf
    from scipy import stats as sp_stats

    session_df.to_csv(os.path.join(save_path, f"{sub_tag}_session_summary.csv"),
                      index=False)
    chunk_df.to_csv(os.path.join(save_path, f"{sub_tag}_chunk_summary.csv"),
                    index=False)

    print(f"\n[A-Behav {sub_tag}] Session-level df: {len(session_df)} rows")
    print(session_df.to_string(index=False))
    print(f"\n[A-Behav {sub_tag}] Chunk-level df: {len(chunk_df)} rows")

    if session_df.empty:
        print(f"[A-Behav {sub_tag}] No data -- skipping.")
        return

    # ---- Colour / marker setup ----
    group_colors = {
        "mCherry": _PAPER_COLORS["mCherry"],
        "hM3D": _PAPER_COLORS["hM3D"],
        "hM4D": _PAPER_COLORS["hM4D"],
    }
    cond_markers = {}
    all_conds = sorted(session_df["condition"].unique(),
                       key=lambda c: (0 if c.startswith("within") else 1, c))
    marker_cycle = ["o", "s", "D", "^", "v", "P", "X"]
    for i, c in enumerate(all_conds):
        cond_markers[c] = marker_cycle[i % len(marker_cycle)]

    has_multi_conds = len(all_conds) > 1

    # ================================================================
    # Panel 1: Session-level scatter — Error vs Freezing / Speed / Coverage
    # ================================================================
    for err_col, ylabel, tag in [
        ("mean_err", f"Mean Euclidean error ({_TFC_TEST_2D_DISTANCE_UNIT})", "mean"),
        ("median_err", f"Median Euclidean error ({_TFC_TEST_2D_DISTANCE_UNIT})", "median"),
    ]:
        for beh_col, xlabel, btag in [
            ("session_freeze_frac", "Freezing fraction (session)", "freeze"),
            ("session_mean_speed", "Mean speed (cm/s, session)", "speed"),
            ("session_coverage", "Spatial coverage (fraction of bins)", "coverage"),
        ]:
            fig, ax = plt.subplots(figsize=(5.5, 4.5), dpi=200)
            for _, row in session_df.iterrows():
                g = row["group"]
                c = row["condition"]
                ax.scatter(row[beh_col], row[err_col],
                           color=group_colors.get(g, "#888"),
                           marker=cond_markers.get(c, "o"),
                           s=50, alpha=0.8, edgecolors="white", linewidths=0.4)

            # Overall correlation
            xv = session_df[beh_col].values
            yv = session_df[err_col].values
            fin = np.isfinite(xv) & np.isfinite(yv)
            if fin.sum() > 3:
                r, p = sp_stats.pearsonr(xv[fin], yv[fin])
                ax.set_title(f"r = {r:.3f}, p = {p:.4f}", fontsize=9)

            ax.set_xlabel(xlabel); ax.set_ylabel(ylabel)
            # Legend: groups as colours
            g_handles = [Line2D([0], [0], marker="o", color="w",
                                markerfacecolor=group_colors.get(g, "#888"),
                                markersize=8, label=_PAPER_LABELS.get(g, g))
                         for g in _PAPER_GROUP_ORDER if g in session_df["group"].values]
            # Conditions as markers
            c_handles = [Line2D([0], [0], marker=cond_markers[c], color="w",
                                markerfacecolor="#555", markersize=7,
                                label=c.replace("_", " "))
                         for c in all_conds]
            ax.legend(handles=g_handles + c_handles,
                      fontsize=6, loc="best", framealpha=0.7)
            fig.tight_layout()
            fig.savefig(os.path.join(save_path,
                        f"{sub_tag}_session_{tag}_err_vs_{btag}.png"), dpi=300)
            if auto_close:
                plt.close(fig)

    # ================================================================
    # Panel 2: Per-group session-level scatter (Error vs Freezing)
    # ================================================================
    for err_col, ylabel, tag in [
        ("mean_err", f"Mean Euclidean error ({_TFC_TEST_2D_DISTANCE_UNIT})", "mean"),
        ("median_err", f"Median Euclidean error ({_TFC_TEST_2D_DISTANCE_UNIT})", "median"),
    ]:
        groups_present = [g for g in _PAPER_GROUP_ORDER
                          if g in session_df["group"].values]
        n_grp = len(groups_present)
        if n_grp == 0:
            continue

        fig, axes = plt.subplots(1, n_grp, figsize=(4.5 * n_grp, 4.2), dpi=200,
                                 squeeze=False)
        axes = axes.ravel()

        for gi, grp in enumerate(groups_present):
            ax = axes[gi]
            dfg = session_df[session_df["group"] == grp]
            for _, row in dfg.iterrows():
                c = row["condition"]
                ax.scatter(row["session_freeze_frac"], row[err_col],
                           color=group_colors.get(grp, "#888"),
                           marker=cond_markers.get(c, "o"),
                           s=55, alpha=0.85, edgecolors="white", linewidths=0.4)
            xv = dfg["session_freeze_frac"].values
            yv = dfg[err_col].values
            fin = np.isfinite(xv) & np.isfinite(yv)
            if fin.sum() > 3:
                r, p = sp_stats.pearsonr(xv[fin], yv[fin])
                # OLS trend line
                slope, intercept = np.polyfit(xv[fin], yv[fin], 1)
                xr = np.linspace(np.nanmin(xv[fin]), np.nanmax(xv[fin]), 50)
                ax.plot(xr, slope * xr + intercept, "--",
                        color=group_colors.get(grp, "#888"), lw=1.2, alpha=0.7)
                ax.set_title(f"{_PAPER_LABELS.get(grp, grp)}\nr={r:.3f}, p={p:.4f}",
                             fontsize=9)
            else:
                ax.set_title(_PAPER_LABELS.get(grp, grp), fontsize=9)
            ax.set_xlabel("Freezing fraction")
            if gi == 0:
                ax.set_ylabel(ylabel)
            # Marker legend
            c_handles = [Line2D([0], [0], marker=cond_markers[c], color="w",
                                markerfacecolor=group_colors.get(grp, "#555"),
                                markersize=7, label=c.replace("_", " "))
                         for c in all_conds if c in dfg["condition"].values]
            ax.legend(handles=c_handles, fontsize=5.5, loc="best", framealpha=0.7)

        fig.tight_layout()
        fig.savefig(os.path.join(save_path,
                    f"{sub_tag}_session_pergroup_{tag}_err_vs_freeze.png"), dpi=300)
        if auto_close:
            plt.close(fig)

    # ================================================================
    # Panel 3: Chunk-level scatter — Error vs Speed / Freeze
    # ================================================================
    if not chunk_df.empty:
        chunk_filt = chunk_df[
            np.isfinite(chunk_df["chunk_err"])
        ].copy()

        for beh_col, xlabel, btag in [
            ("chunk_mean_speed", "Chunk mean speed (cm/s)", "speed"),
            ("chunk_freeze_frac", "Chunk freezing fraction", "freeze"),
        ]:
            groups_present = [g for g in _PAPER_GROUP_ORDER
                              if g in chunk_filt["group"].values]
            n_grp = len(groups_present)
            if n_grp == 0:
                continue
            fig, axes = plt.subplots(1, n_grp, figsize=(4.5 * n_grp, 4.2),
                                     dpi=200, squeeze=False)
            axes = axes.ravel()
            for gi, grp in enumerate(groups_present):
                ax = axes[gi]
                dfg = chunk_filt[chunk_filt["group"] == grp]
                for cond in all_conds:
                    dfc = dfg[dfg["condition"] == cond]
                    if dfc.empty:
                        continue
                    ax.scatter(dfc[beh_col], dfc["chunk_err"],
                               color=group_colors.get(grp, "#888"),
                               marker=cond_markers.get(cond, "o"),
                               s=8, alpha=0.15, edgecolors="none")
                xv = dfg[beh_col].values
                yv = dfg["chunk_err"].values
                fin = np.isfinite(xv) & np.isfinite(yv)
                if fin.sum() > 10:
                    r, p = sp_stats.pearsonr(xv[fin], yv[fin])
                    ax.set_title(f"{_PAPER_LABELS.get(grp, grp)}\nr={r:.3f}, p={p:.1e}",
                                 fontsize=8)
                else:
                    ax.set_title(_PAPER_LABELS.get(grp, grp), fontsize=8)
                ax.set_xlabel(xlabel)
                if gi == 0:
                    ax.set_ylabel(f"Chunk Euclidean error ({_TFC_TEST_2D_DISTANCE_UNIT})")
            fig.tight_layout()
            fig.savefig(os.path.join(save_path,
                        f"{sub_tag}_chunk_err_vs_{btag}.png"), dpi=300)
            if auto_close:
                plt.close(fig)

    # ================================================================
    # MixedLM: session-level — does freezing explain the Test A effect?
    # ================================================================
    print("\n" + "=" * 70)
    print(f"  MixedLM [{sub_tag}]: Decoder error vs behaviour (session-level)")
    print("=" * 70)

    mlm_log = []

    for err_col, stat_tag in [("mean_err", "mean"), ("median_err", "median")]:
        df_m = session_df[np.isfinite(session_df[err_col])].copy()
        if df_m.shape[0] < 6:
            msg = f"[A-Behav {sub_tag} MixedLM] Too few rows ({df_m.shape[0]}) for {stat_tag}."
            print(msg); mlm_log.append(msg)
            continue

        if has_multi_conds:
            df_m["condition"] = pd.Categorical(df_m["condition"])
        df_m["group"] = pd.Categorical(df_m["group"],
                                        categories=_PAPER_GROUP_ORDER)

        cond_term = "C(condition) + " if has_multi_conds else ""

        # Model 1: base
        formula1 = f"{err_col} ~ C(condition)" if has_multi_conds else f"{err_col} ~ 1"
        try:
            md1 = smf.mixedlm(formula1, df_m,
                               groups=df_m["mouse"])
            fit1 = md1.fit(reml=False)
            aic1, bic1 = fit1.aic, fit1.bic
            msg1 = (f"\n--- Model 1 (base, {stat_tag}): "
                    f"{formula1} | (1|mouse) ---\n"
                    f"AIC={aic1:.1f}  BIC={bic1:.1f}\n"
                    f"{fit1.summary()}\n")
            print(msg1); mlm_log.append(msg1)
        except Exception as e:
            msg1 = f"[Model1 {stat_tag}] Failed: {e}"
            print(msg1); mlm_log.append(msg1)
            fit1 = None

        # Model 2: + freezing + speed
        formula2 = f"{err_col} ~ {cond_term}session_freeze_frac + session_mean_speed"
        try:
            md2 = smf.mixedlm(formula2, df_m, groups=df_m["mouse"])
            fit2 = md2.fit(reml=False)
            aic2, bic2 = fit2.aic, fit2.bic
            msg2 = (f"\n--- Model 2 (full, {stat_tag}): "
                    f"{formula2} | (1|mouse) ---\n"
                    f"AIC={aic2:.1f}  BIC={bic2:.1f}\n"
                    f"{fit2.summary()}\n")
            print(msg2); mlm_log.append(msg2)
        except Exception as e:
            msg2 = f"[Model2 {stat_tag}] Failed: {e}"
            print(msg2); mlm_log.append(msg2)
            fit2 = None

        # Model 3: + group interaction
        if has_multi_conds:
            formula3 = (f"{err_col} ~ C(condition) * C(group) + "
                        f"session_freeze_frac + session_mean_speed")
        else:
            formula3 = (f"{err_col} ~ C(group) + "
                        f"session_freeze_frac + session_mean_speed")
        try:
            md3 = smf.mixedlm(formula3, df_m, groups=df_m["mouse"])
            fit3 = md3.fit(reml=False)
            aic3, bic3 = fit3.aic, fit3.bic
            msg3 = (f"\n--- Model 3 (group interaction, {stat_tag}): "
                    f"{formula3} | (1|mouse) ---\n"
                    f"AIC={aic3:.1f}  BIC={bic3:.1f}\n"
                    f"{fit3.summary()}\n")
            print(msg3); mlm_log.append(msg3)
        except Exception as e:
            msg3 = f"[Model3 {stat_tag}] Failed: {e}"
            print(msg3); mlm_log.append(msg3)
            fit3 = None

        # Model comparison summary
        if fit1 is not None and fit2 is not None:
            delta_aic = aic2 - aic1
            delta_bic = bic2 - bic1
            # LR test (model 2 vs model 1) — 2 extra params (freezing, speed)
            lr_stat = -2 * (fit1.llf - fit2.llf)
            lr_p = sp_stats.chi2.sf(lr_stat, df=2)
            comp = (f"\n--- Model comparison ({stat_tag}) ---\n"
                    f"  Base  AIC={aic1:.1f}  BIC={bic1:.1f}  LL={fit1.llf:.1f}\n"
                    f"  Full  AIC={aic2:.1f}  BIC={bic2:.1f}  LL={fit2.llf:.1f}\n"
                    f"  dAIC (full-base) = {delta_aic:+.1f}\n"
                    f"  dBIC (full-base) = {delta_bic:+.1f}\n"
                    f"  LR chi2={lr_stat:.2f}, df=2, p={lr_p:.4f}\n"
                    f"  -> {'Full model is better' if delta_aic < 0 else 'Base model is sufficient'} "
                    f"(AIC criterion)\n")
            print(comp); mlm_log.append(comp)

    # ================================================================
    # Chunk-level MixedLM: instantaneous error ~ speed + freezing
    # ================================================================
    if not chunk_df.empty:
        chunk_filt = chunk_df[
            np.isfinite(chunk_df["chunk_err"])
        ].copy()
        chunk_filt = chunk_filt.dropna(
            subset=["chunk_err", "chunk_mean_speed", "chunk_freeze_frac"])

        if chunk_filt.shape[0] >= 20:
            if has_multi_conds:
                chunk_filt["condition"] = pd.Categorical(chunk_filt["condition"])
            chunk_filt["group"] = pd.Categorical(
                chunk_filt["group"], categories=_PAPER_GROUP_ORDER)

            cond_term_c = "C(condition) + " if has_multi_conds else ""
            try:
                formula_c1 = f"chunk_err ~ {cond_term_c}chunk_mean_speed + chunk_freeze_frac"
                md_c = smf.mixedlm(formula_c1, chunk_filt,
                                    groups=chunk_filt["mouse"])
                fit_c = md_c.fit(reml=False)
                msg_c = (f"\n--- Chunk-level MixedLM ---\n"
                         f"  {formula_c1} | (1|mouse)\n"
                         f"AIC={fit_c.aic:.1f}  BIC={fit_c.bic:.1f}\n"
                         f"{fit_c.summary()}\n")
                print(msg_c); mlm_log.append(msg_c)
            except Exception as e:
                msg_c = f"[Chunk MixedLM] Failed: {e}"
                print(msg_c); mlm_log.append(msg_c)

            if has_multi_conds:
                formula_c2 = ("chunk_err ~ C(condition) * C(group) + "
                              "chunk_mean_speed + chunk_freeze_frac")
            else:
                formula_c2 = ("chunk_err ~ C(group) + "
                              "chunk_mean_speed + chunk_freeze_frac")
            try:
                md_c2 = smf.mixedlm(formula_c2, chunk_filt,
                                     groups=chunk_filt["mouse"])
                fit_c2 = md_c2.fit(reml=False)
                msg_c2 = (f"\n--- Chunk-level MixedLM (group interaction) ---\n"
                          f"  {formula_c2} | (1|mouse)\n"
                          f"AIC={fit_c2.aic:.1f}  BIC={fit_c2.bic:.1f}\n"
                          f"{fit_c2.summary()}\n")
                print(msg_c2); mlm_log.append(msg_c2)
            except Exception as e:
                msg_c2 = f"[Chunk MixedLM group] Failed: {e}"
                print(msg_c2); mlm_log.append(msg_c2)

    # Save log
    with open(os.path.join(save_path, f"{sub_tag}_mixedlm_results.txt"), "w") as f:
        f.write("\n".join(mlm_log))

    print(f"\n[A-Behav {sub_tag}] Done.")


# ===================================================================
#  LT Position-vs-Time decoder pipeline
#  Mirrors the 2D PF xy_position_vs_time plots for linear track data.
#  Four decoder variants:  S_1D, PF_1D, S_2D, PF_2D
#  Three conditions:       within_LT1, within_LT2, LT1_to_LT2
# ===================================================================

def _project_decoded_2d_to_1d(decoded_x, decoded_y, centerline):
    """Project decoded (x, y) positions back to 1D arc-length along *centerline*.

    Uses the same continuous-projection helper used for raw position data.
    Returns 1D arc-length positions (pixels).
    """
    # (project_points_to_polyline_continuous imported at top of file)

    xy = np.column_stack([
        np.asarray(decoded_x, float),
        np.asarray(decoded_y, float),
    ])
    s_1d, _, _, _ = project_points_to_polyline_continuous(
        xy, np.asarray(centerline, float),
        seg_window=25, teleport_d_px=60.0, fallback_full_search=True,
    )
    return s_1d


def _build_1d_rate_map_from_2d_pf(
    fm,
    centerline_miniscope,
    n_pos_bins,
    pos_range,
    fm_cell_indices=None,
):
    """Build 1D tuning curves by evaluating 2D GMM place fields along the centerline.

    For each cell, evaluate the fitted BayesianGaussianMixture log-density
    (via ``pf.model_[s_idx].score_samples``) at densely-sampled centerline
    points, then bin into *n_pos_bins* along the arc-length axis.

    Parameters
    ----------
    fm : FluorescenceMap
        Must have ``.pf`` (PlaceFields) with ``model_`` dict, and ``.cells``.
    centerline_miniscope : (M, 2) array
        Centerline polyline in miniscope coordinate space.
    n_pos_bins : int
    pos_range : (float, float)
        (min_1d, max_1d) arc-length range for binning.
    fm_cell_indices : list[int] or None
        Indices into ``fm.cells`` to use. ``None`` → all cells.

    Returns
    -------
    lam_1d : (n_cells, n_pos_bins) array  — rate (a.u. / frame)
    bin_edges : (n_pos_bins + 1,) array
    bin_centers : (n_pos_bins,) array
    used_cell_ids : list[int]  — indices into fm.cells that were used
    """
    pf = fm.pf
    cl = np.asarray(centerline_miniscope, float)

    # arc-length of each centerline vertex (px → cm so units match pos_range)
    seg = cl[1:] - cl[:-1]
    seglen = np.sqrt((seg ** 2).sum(axis=1))
    s_nodes = np.concatenate([[0.0], np.cumsum(seglen)])
    s_nodes = s_nodes * _LT_1D_CM_PER_PX          # px → cm

    # Centerline points in bin-index space [row, col] for GMM evaluation
    bw = float(fm.loc.bin_width)
    cl_bin = cl / bw  # (M, 2) → [x_bin, y_bin]
    # GMM was fit on [row_bin, col_bin] = [y_bin, x_bin]
    cl_bin_rc = cl_bin[:, ::-1]  # (M, 2) → [row, col]

    bin_edges = np.linspace(pos_range[0], pos_range[1], n_pos_bins + 1)
    bin_centers = 0.5 * (bin_edges[:-1] + bin_edges[1:])

    all_cells = list(fm.cells) if fm.cells is not None else []
    if fm_cell_indices is None:
        fm_cell_indices = list(range(len(all_cells)))

    n_cells = len(fm_cell_indices)
    eps = 1e-6
    lam_1d = np.full((n_cells, n_pos_bins), eps, dtype=float)
    used_cell_ids = []

    for i, fm_idx in enumerate(fm_cell_indices):
        s_idx = all_cells[fm_idx]
        used_cell_ids.append(s_idx)

        if s_idx not in pf.model_:
            continue

        gmm = pf.model_[s_idx]
        try:
            log_dens = gmm.score_samples(cl_bin_rc)  # (M,)
            density_along = np.exp(log_dens)
        except Exception:
            continue

        if np.max(density_along) <= 0:
            continue

        # Scale by peak of occupancy-corrected rate map (same as BayesianDecoder2D_PF)
        peak_fm = 0.0
        if fm.fluorescence_map_occup is not None:
            peak_fm = float(np.max(fm.fluorescence_map_occup[:, :, fm_idx]))
        peak_dens = float(np.max(density_along))
        scale = (peak_fm / peak_dens) if (peak_dens > 0 and peak_fm > 0) else 1.0
        density_along *= scale

        # Bin the density along arc-length
        bin_idx = np.digitize(s_nodes, bin_edges) - 1
        bin_idx = np.clip(bin_idx, 0, n_pos_bins - 1)
        for b in range(n_pos_bins):
            sel = (bin_idx == b)
            if np.any(sel):
                lam_1d[i, b] = max(float(np.mean(density_along[sel])), eps)

    return lam_1d, bin_edges, bin_centers, used_cell_ids


class BayesianDecoder1D_PF:
    """1D Poisson Bayesian decoder using place-field tuning curves projected to 1D."""

    def __init__(self, n_pos_bins=60, time_bin_frames=5, rate_smooth_eps=1e-6):
        self.n_pos_bins = int(n_pos_bins)
        self.time_bin_frames = int(time_bin_frames)
        self.rate_smooth_eps = float(rate_smooth_eps)
        self.lam = None
        self.log_prior = None
        self.bin_edges = None
        self.bin_centers = None
        self.dt_sec = None
        self.fitted = False

    def fit_from_place_fields(
        self,
        fm,
        centerline_miniscope,
        pos_range,
        dt_sec,
        x_1d_train=None,
        train_mask=None,
        fm_cell_indices=None,
    ):
        """Build tuning curves from 2D PFs projected onto the 1D track."""
        lam_1d, bin_edges, bin_centers, _ = _build_1d_rate_map_from_2d_pf(
            fm, centerline_miniscope, self.n_pos_bins, pos_range,
            fm_cell_indices=fm_cell_indices,
        )
        self.lam = np.maximum(lam_1d, self.rate_smooth_eps)
        self.bin_edges = bin_edges
        self.bin_centers = bin_centers
        self.dt_sec = float(dt_sec)

        # Occupancy prior from training positions
        B = bin_centers.size
        if x_1d_train is not None and train_mask is not None:
            x_tr = np.asarray(x_1d_train, float)
            m_tr = np.asarray(train_mask, bool)[:x_tr.size]
            x_tr = x_tr[:m_tr.size]
            pos_bin = np.clip(np.digitize(x_tr[m_tr], bin_edges) - 1, 0, B - 1)
            occ = np.bincount(pos_bin, minlength=B).astype(float) * dt_sec
            occ = np.maximum(occ, dt_sec)
            p = occ / np.sum(occ)
        else:
            p = np.ones(B, dtype=float) / B
        self.log_prior = np.log(np.maximum(p, 1e-12))
        self.fitted = True

    def decode(
        self,
        S, x_1d, mask,
        use_posterior_mean=False,
        use_continuity_constraint=False,
        speed_vec=None,
        continuity_sigma_k=35.0,
        continuity_speed_ref=20.0,
        continuity_exp=1.0,
        continuity_sigma_min=10.0,
        continuity_sigma_max=30.0,
        continuity_sigma_default=18.0,
        save_posterior=False,
    ):
        """Decode using the same Poisson MAP logic as BayesianDecoder1D."""
        assert self.fitted, "Call fit_from_place_fields() first."
        # Reuse BayesianDecoder1D decoding by constructing a temporary wrapper
        tmp = BayesianDecoder1D.__new__(BayesianDecoder1D)
        tmp.lam = self.lam
        tmp.log_prior = self.log_prior
        tmp.bin_edges = self.bin_edges
        tmp.bin_centers = self.bin_centers
        tmp.dt_sec = self.dt_sec
        tmp.time_bin_frames = self.time_bin_frames
        tmp.fitted = True
        return tmp.decode(
            S, x_1d, mask,
            use_posterior_mean=use_posterior_mean,
            use_continuity_constraint=use_continuity_constraint,
            speed_vec=speed_vec,
            continuity_sigma_k=continuity_sigma_k,
            continuity_speed_ref=continuity_speed_ref,
            continuity_exp=continuity_exp,
            continuity_sigma_min=continuity_sigma_min,
            continuity_sigma_max=continuity_sigma_max,
            continuity_sigma_default=continuity_sigma_default,
            save_posterior=save_posterior,
        )


# ---- Lap mask helpers ----------------------------------------------------

def _classify_laps_by_direction(LT):
    """Classify each lap as rightward (+1) or leftward (-1) via majority vote.

    Returns (laps_R, laps_L) — sorted lists of lap indices, or (None, None)
    if lap segmentation is missing.
    """
    seg = getattr(LT, "ls", None)
    if seg is None:
        return None, None
    T = LT.S.shape[1]
    lap_idx = np.asarray(getattr(seg, "lap_idx", None), int)[:T]
    lap_dir = np.asarray(getattr(seg, "lap_dir", None), float)[:T]
    if lap_idx is None or lap_dir is None:
        return None, None

    lapdir = {}
    for lap in np.unique(lap_idx):
        if lap < 0:
            continue
        m = (lap_idx == lap) & np.isfinite(lap_dir)
        if not np.any(m):
            continue
        vals = lap_dir[m]
        vals = vals[np.abs(vals) > 0.1]
        if vals.size == 0:
            continue
        lapdir[int(lap)] = +1 if np.sum(vals > 0) >= np.sum(vals < 0) else -1

    laps_R = sorted(k for k, v in lapdir.items() if v == +1)
    laps_L = sorted(k for k, v in lapdir.items() if v == -1)
    return laps_R, laps_L


def _shuffle_and_split_laps(laps, rng_seed=0):
    """Shuffle lap indices then do an alternating train/test split.

    Returns (train_laps, test_laps) as numpy arrays, or (None, None) if
    there are fewer than 2 laps.
    """
    laps = np.asarray(laps, int)
    if laps.size < 2:
        return None, None
    rng = np.random.RandomState(rng_seed)
    laps_shuf = laps.copy()
    rng.shuffle(laps_shuf)
    train_laps = laps_shuf[::2]
    test_laps  = laps_shuf[1::2]
    if test_laps.size == 0:
        test_laps = train_laps[-1:]
        train_laps = train_laps[:-1]
    if train_laps.size == 0 or test_laps.size == 0:
        return None, None
    return train_laps, test_laps


def _build_lap_mask(LT, laps, *, use_speed=True, min_speed=2.0):
    """Boolean frame mask for the given lap indices with standard filters.

    Applies: isin(lap_idx, laps) & valid_mask & speed_filter & (lap_idx >= 0).
    Returns a bool array of length T, or None if lap segmentation is missing.
    """
    seg = getattr(LT, "ls", None)
    if seg is None:
        return None
    T = LT.S.shape[1]
    lap_idx = np.asarray(seg.lap_idx, int)[:T]
    mask = np.isin(lap_idx, list(laps))
    mask &= (lap_idx >= 0)
    valid = getattr(seg, "valid_mask", None)
    if valid is not None:
        mask &= np.asarray(valid, bool)[:T]
    if use_speed:
        mask &= _get_speed_mask(LT, min_speed=min_speed)
    return mask


def _build_even_odd_lap_masks(LT, *, use_speed=True, min_speed=2.0):
    """Pool both running directions; split laps by even/odd lap_idx.

    Returns (even_mask, odd_mask, dt_sec, n_laps_even, n_laps_odd) or None on failure.
    """
    seg = getattr(LT, "ls", None)
    if seg is None:
        return None
    T = LT.S.shape[1]
    lap_idx = np.asarray(seg.lap_idx, int)[:T]

    base = np.ones(T, dtype=bool)
    valid = getattr(seg, "valid_mask", None)
    if valid is not None:
        base &= np.asarray(valid, bool)[:T]
    base &= (lap_idx >= 0)
    if use_speed:
        base &= _get_speed_mask(LT, min_speed=min_speed)

    unique_laps = np.unique(lap_idx[lap_idx >= 0])
    even_laps = unique_laps[unique_laps % 2 == 0]
    odd_laps = unique_laps[unique_laps % 2 == 1]

    even_mask = base & np.isin(lap_idx, even_laps)
    odd_mask = base & np.isin(lap_idx, odd_laps)
    dt_sec = _infer_dt_sec(LT)

    return even_mask, odd_mask, dt_sec, len(even_laps), len(odd_laps)


def _build_all_laps_mask(LT, *, use_speed=True, min_speed=2.0):
    """Mask covering all valid laps (both directions, all laps)."""
    seg = getattr(LT, "ls", None)
    if seg is None:
        return None, None
    T = LT.S.shape[1]
    lap_idx = np.asarray(seg.lap_idx, int)[:T]
    base = np.ones(T, dtype=bool)
    valid = getattr(seg, "valid_mask", None)
    if valid is not None:
        base &= np.asarray(valid, bool)[:T]
    base &= (lap_idx >= 0)
    if use_speed:
        base &= _get_speed_mask(LT, min_speed=min_speed)
    return base, _infer_dt_sec(LT)


# ---- Within-session decode -----------------------------------------------

def _pool_split_results(r1, r2):
    """Concatenate results from two direction-specific _run_split dicts.

    Handles both 1D-projecting modes (with true_pos_1d/decoded_pos_1d) and
    true-2D modes (without them).  After concatenation the arrays are
    **sorted by time** (using ``idx_use``) so that downstream plotting
    draws traces in chronological order.

    Returns a single merged dict, or the one successful result if only
    one direction succeeded.
    """
    ok1, ok2 = r1.get("ok", False), r2.get("ok", False)
    if ok1 and ok2:
        merged = {"ok": True}
        _array_keys = ("abs_err", "Ksum", "idx_use", "true_pos_1d", "decoded_pos_1d",
                       "frac_active", "frac_PF_active", "posterior_entropy",
                       "posterior")
        for key in _array_keys:
            a, b = r1.get(key), r2.get(key)
            if a is not None and b is not None:
                merged[key] = np.concatenate([a, b])
        # Sort all pooled arrays by chronological order (idx_use)
        idx = merged.get("idx_use")
        if idx is not None and len(idx) > 0:
            sort_key = np.mean(np.asarray(idx), axis=1) if np.ndim(idx) == 2 else np.asarray(idx, float)
            order = np.argsort(sort_key)
            for key in _array_keys:
                arr = merged.get(key)
                if arr is not None:
                    merged[key] = arr[order]
        # Keep decoder output metadata from first result
        if "out" in r1:
            merged["out"] = r1["out"]
        return merged
    if ok1:
        return r1
    if ok2:
        return r2
    return {"ok": False, "reason": "both directions failed"}


def decode_within_LT_position_vs_time(
    LT,
    decoder_mode,
    *,
    n_pos_bins=60,
    time_bin_frames=5,
    use_speed=True,
    min_speed=2.0,
    rng_seed=0,
    min_laps_per_dir=2,
    S_override=None,
    S_override_unit_ids=None,
    use_z_score="none",
    use_posterior_mean=True,
    use_continuity_constraint=True,
    continuity_sigma_k=35.0,
    continuity_speed_ref=20.0,
    continuity_exp=1.0,
    continuity_sigma_min=10.0,
    continuity_sigma_max=30.0,
    continuity_sigma_default=18.0,
    n_x_bins=20,
    n_y_bins=20,
    shuffle_type: str = "none",
    shuffle_seed: Optional[int] = None,
):
    """Within-session leave-one-lap-out (LOLO) CV for one LT session.

    All laps (both directions) are pooled.  For each lap, the decoder is
    trained on the remaining N-1 laps and tested on the held-out lap.
    All N held-out predictions are concatenated into a single pooled
    error distribution.

    Parameters
    ----------
    decoder_mode : str
        ``'S_1D'``, ``'PF_1D'``, ``'S_2D'``, ``'PF_2D'``,
        ``'S_2D_full'``, or ``'PF_2D_full'``
    rng_seed : int
        Unused (kept for API compatibility).
    min_laps_per_dir : int
        Legacy; minimum total laps is 2.
    """
    # ---- Pool all laps (both directions) ----
    seg = getattr(LT, "ls", None)
    if seg is None:
        return {"ok": False, "reason": "No lap segmentation."}
    _T_ls = LT.S.shape[1]
    _lap_idx = np.asarray(seg.lap_idx, int)[:_T_ls]
    all_laps = np.unique(_lap_idx[_lap_idx >= 0])

    _min_laps_total = 2
    if len(all_laps) < _min_laps_total:
        return {"ok": False, "reason": f"Too few laps: {len(all_laps)} < {_min_laps_total}"}

    dt_sec = _infer_dt_sec(LT)
    T = LT.S.shape[1]
    S = np.asarray(S_override if S_override is not None else LT.S, float)[:, :T]
    S = _apply_zscore_single(S, use_z_score)

    # Map original unit-IDs → compact S_override row indices (for PF modes)
    _uid_to_Srow = None
    if S_override is not None and S_override_unit_ids is not None:
        _uid_to_Srow = {int(uid): row for row, uid in enumerate(S_override_unit_ids)}

    if str(shuffle_type).strip().lower() not in ("", "none", "off", "false", "0"):
        S = _apply_decoder_time_shuffle(S, shuffle_type=shuffle_type, rng=default_rng(shuffle_seed))
    x_1d = np.asarray(LT.miniscope_loc_1d_px, float)[:T]
    x_1d = x_1d * _LT_1D_CM_PER_PX        # px -> cm
    speed_vec = _get_miniscope_velocity_vector(LT, T)

    has_fm = hasattr(LT, "fm") and LT.fm is not None
    has_cl = hasattr(LT, "centerline_miniscope") and LT.centerline_miniscope is not None

    # Use all valid laps for pos_range
    all_laps_mask = _build_lap_mask(LT, all_laps, use_speed=use_speed, min_speed=min_speed)
    pos_range = (float(np.nanmin(x_1d[all_laps_mask])),
                 float(np.nanmax(x_1d[all_laps_mask])))

    cc = dict(
        use_posterior_mean=use_posterior_mean,
        use_continuity_constraint=use_continuity_constraint,
        speed_vec=speed_vec,
        continuity_sigma_k=continuity_sigma_k,
        continuity_speed_ref=continuity_speed_ref,
        continuity_exp=continuity_exp,
        continuity_sigma_min=continuity_sigma_min,
        continuity_sigma_max=continuity_sigma_max,
        continuity_sigma_default=continuity_sigma_default,
        save_posterior=True,
    )

    # Precompute cm-converted 2D coordinates (used by S_2D / PF_2D branches)
    _cm = float(_LT_1D_CM_PER_PX)
    _loc_X_cm = np.asarray(LT.loc_X_miniscope_smooth, float)[:T] * _cm
    _loc_Y_cm = np.asarray(LT.loc_Y_miniscope_smooth, float)[:T] * _cm
    _bw_cm = (float(LT.fm.loc.bin_width) if has_fm else 4.5) * _cm
    _cl_cm = (np.asarray(LT.centerline_miniscope, float) * _cm
              if has_cl else None)

    def _get_pf_cell_indices():
        """Return fm cell indices for place cells (sig_responses) or all."""
        fm_cells = list(LT.fm.cells)
        if LT.fm.sig_responses is not None:
            return [i for i, c in enumerate(fm_cells) if c in LT.fm.sig_responses]
        return list(range(len(fm_cells)))

    # Precompute PF-cell mask over S rows for frac_PF_active
    N = S.shape[0]
    if has_fm and hasattr(LT.fm, 'pf') and hasattr(LT.fm.pf, 'merged_means'):
        _pf_ids = set(int(LT.fm.cells[k]) for k in LT.fm.pf.merged_means
                       if len(LT.fm.pf.merged_means[k]) > 0)
        if _uid_to_Srow is not None:
            _pf_row_mask = np.array([int(S_override_unit_ids[i]) in _pf_ids
                                     for i in range(N)], dtype=bool)
        else:
            _pf_row_mask = np.array([i in _pf_ids for i in range(N)], dtype=bool)
    else:
        _pf_row_mask = np.zeros(N, dtype=bool)

    def _add_diagnostics(result, out_dict, is_pf_mode):
        """Extract per-bin diagnostics from decoder output dict."""
        result["frac_active"] = out_dict["frac_active"]
        result["posterior_entropy"] = out_dict["posterior_entropy"]
        K = out_dict["K"]
        if is_pf_mode or not _pf_row_mask.any():
            result["frac_PF_active"] = out_dict["frac_active"]
        else:
            result["frac_PF_active"] = (K[:, _pf_row_mask] > 0).mean(axis=1) if K.shape[0] > 0 else np.array([])
        if "posterior" in out_dict:
            result["posterior"] = out_dict["posterior"]
        if "grid_x_flat" in out_dict:
            result["grid_x_flat"] = out_dict["grid_x_flat"]
            result["grid_y_flat"] = out_dict["grid_y_flat"]
        return result

    def _run_split(train_mask, test_mask, label):
        if train_mask.sum() < 10 * time_bin_frames or test_mask.sum() < time_bin_frames:
            return {"ok": False, "reason": f"Not enough frames for {label}"}

        if decoder_mode == "S_1D":
            dec = BayesianDecoder1D(n_pos_bins=n_pos_bins, time_bin_frames=time_bin_frames)
            dec.fit(S, x_1d, train_mask, dt_sec)
            out = dec.decode(S, x_1d, test_mask, **cc)
            return _add_diagnostics({"ok": True, "out": out,
                    "true_pos_1d": out["true_pos"], "decoded_pos_1d": out["decoded_pos"],
                    "abs_err": BayesianDecoder1D.abs_error(out["decoded_pos"], out["true_pos"]),
                    "Ksum": out["Ksum"], "idx_use": out["idx_use"]}, out, is_pf_mode=False)

        elif decoder_mode == "PF_1D":
            if not has_fm or not has_cl:
                return {"ok": False, "reason": "No .fm or centerline for PF_1D"}
            pf_idx = _get_pf_cell_indices()
            if len(pf_idx) == 0:
                return {"ok": False, "reason": "No place cells for PF_1D"}
            fm_cells = list(LT.fm.cells)
            if _uid_to_Srow is not None:
                pf_idx = [i for i in pf_idx if fm_cells[i] in _uid_to_Srow]
                if len(pf_idx) == 0:
                    return {"ok": False, "reason": "No PF cells in crossreg set for PF_1D"}
                S_pf = S[np.array([_uid_to_Srow[fm_cells[i]] for i in pf_idx]), :]
            else:
                S_pf = S[np.array([fm_cells[i] for i in pf_idx]), :]
            dec = BayesianDecoder1D_PF(n_pos_bins=n_pos_bins, time_bin_frames=time_bin_frames)
            dec.fit_from_place_fields(
                LT.fm, LT.centerline_miniscope, pos_range, dt_sec,
                x_1d_train=x_1d, train_mask=train_mask,
                fm_cell_indices=pf_idx,
            )
            out = dec.decode(S_pf, x_1d, test_mask, **cc)
            return _add_diagnostics({"ok": True, "out": out,
                    "true_pos_1d": out["true_pos"], "decoded_pos_1d": out["decoded_pos"],
                    "abs_err": BayesianDecoder1D.abs_error(out["decoded_pos"], out["true_pos"]),
                    "Ksum": out["Ksum"], "idx_use": out["idx_use"]}, out, is_pf_mode=True)

        elif decoder_mode == "S_2D":
            if not has_cl:
                return {"ok": False, "reason": "No centerline for S_2D"}
            _nx = max(2, round((np.nanmax(_loc_X_cm) - np.nanmin(_loc_X_cm)) / _bw_cm))
            _ny = max(2, round((np.nanmax(_loc_Y_cm) - np.nanmin(_loc_Y_cm)) / _bw_cm))
            dec2d = BayesianDecoder2D(n_x_bins=_nx, n_y_bins=_ny,
                                      time_bin_frames=time_bin_frames)
            dec2d.fit(S, _loc_X_cm, _loc_Y_cm, train_mask, dt_sec)
            out2d = dec2d.decode(
                S, _loc_X_cm, _loc_Y_cm, test_mask,
                **cc,
            )
            dec_1d = _project_decoded_2d_to_1d(out2d["decoded_x"], out2d["decoded_y"],
                                                _cl_cm)
            true_1d = _project_decoded_2d_to_1d(out2d["true_x"], out2d["true_y"],
                                                 _cl_cm)
            return _add_diagnostics({"ok": True, "out": out2d,
                    "true_pos_1d": true_1d, "decoded_pos_1d": dec_1d,
                    "abs_err": np.abs(dec_1d - true_1d),
                    "Ksum": out2d["Ksum"], "idx_use": out2d["idx_use"]}, out2d, is_pf_mode=False)

        elif decoder_mode == "PF_2D":
            if not has_fm or not has_cl:
                return {"ok": False, "reason": "No .fm or centerline for PF_2D"}
            pf_idx = _get_pf_cell_indices()
            if len(pf_idx) == 0:
                return {"ok": False, "reason": "No place cells for PF_2D"}
            fm = LT.fm
            fm_cells = list(fm.cells)
            if _uid_to_Srow is not None:
                pf_idx = [i for i in pf_idx if fm_cells[i] in _uid_to_Srow]
                if len(pf_idx) == 0:
                    return {"ok": False, "reason": "No PF cells in crossreg set for PF_2D"}
                S_pf = S[np.array([_uid_to_Srow[fm_cells[i]] for i in pf_idx]), :]
            else:
                S_pf = S[np.array([fm_cells[i] for i in pf_idx]), :]
            fm.check_fluorescence_map_occup()
            dec2d_pf = BayesianDecoder2D_PF(time_bin_frames=time_bin_frames)
            dec2d_pf.fit_from_place_fields(
                fm.pf, fm.fluorescence_map_occup, fm.loc.occupancy,
                fm_cells=fm_cells, cell_indices=pf_idx,
                dt_sec=dt_sec, bin_width=_bw_cm,
            )
            _Tpf = S_pf.shape[1]
            out2d = dec2d_pf.decode(
                S_pf, _loc_X_cm[:_Tpf], _loc_Y_cm[:_Tpf], test_mask[:_Tpf],
                use_posterior_mean=use_posterior_mean,
                use_continuity_constraint=use_continuity_constraint,
                speed_vec=speed_vec[:_Tpf] if speed_vec is not None else None,
                continuity_sigma_k=continuity_sigma_k,
                continuity_speed_ref=continuity_speed_ref,
                continuity_exp=continuity_exp,
                continuity_sigma_min=continuity_sigma_min,
                continuity_sigma_max=continuity_sigma_max,
                continuity_sigma_default=continuity_sigma_default,
                save_posterior=True,
            )
            dec_1d = _project_decoded_2d_to_1d(out2d["decoded_x"], out2d["decoded_y"],
                                                _cl_cm)
            true_1d = _project_decoded_2d_to_1d(out2d["true_x"], out2d["true_y"],
                                                 _cl_cm)
            return _add_diagnostics({"ok": True, "out": out2d,
                    "true_pos_1d": true_1d, "decoded_pos_1d": dec_1d,
                    "abs_err": np.abs(dec_1d - true_1d),
                    "Ksum": out2d["Ksum"], "idx_use": out2d["idx_use"]}, out2d, is_pf_mode=True)

        # ---- True-2D modes (no 1D projection, euclidean error) ----------
        elif decoder_mode == "S_2D_full":
            _nx = max(2, round((np.nanmax(_loc_X_cm) - np.nanmin(_loc_X_cm)) / _bw_cm))
            _ny = max(2, round((np.nanmax(_loc_Y_cm) - np.nanmin(_loc_Y_cm)) / _bw_cm))
            dec2d = BayesianDecoder2D(n_x_bins=_nx, n_y_bins=_ny,
                                      time_bin_frames=time_bin_frames)
            dec2d.fit(S, _loc_X_cm, _loc_Y_cm, train_mask, dt_sec)
            out2d = dec2d.decode(
                S, _loc_X_cm, _loc_Y_cm, test_mask,
                **cc,
            )
            return _add_diagnostics({"ok": True, "out": out2d,
                    "abs_err": out2d["euclidean_err"],
                    "Ksum": out2d["Ksum"], "idx_use": out2d["idx_use"]}, out2d, is_pf_mode=False)

        elif decoder_mode == "PF_2D_full":
            if not has_fm:
                return {"ok": False, "reason": "No .fm for PF_2D_full"}
            pf_idx = _get_pf_cell_indices()
            if len(pf_idx) == 0:
                return {"ok": False, "reason": "No place cells for PF_2D_full"}
            fm = LT.fm
            fm_cells = list(fm.cells)
            if _uid_to_Srow is not None:
                pf_idx = [i for i in pf_idx if fm_cells[i] in _uid_to_Srow]
                if len(pf_idx) == 0:
                    return {"ok": False, "reason": "No PF cells in crossreg set for PF_2D_full"}
                S_pf = S[np.array([_uid_to_Srow[fm_cells[i]] for i in pf_idx]), :]
            else:
                S_pf = S[np.array([fm_cells[i] for i in pf_idx]), :]
            fm.check_fluorescence_map_occup()
            dec2d_pf = BayesianDecoder2D_PF(time_bin_frames=time_bin_frames)
            dec2d_pf.fit_from_place_fields(
                fm.pf, fm.fluorescence_map_occup, fm.loc.occupancy,
                fm_cells=fm_cells, cell_indices=pf_idx,
                dt_sec=dt_sec, bin_width=_bw_cm,
            )
            _Tpf = S_pf.shape[1]
            out2d = dec2d_pf.decode(
                S_pf, _loc_X_cm[:_Tpf], _loc_Y_cm[:_Tpf], test_mask[:_Tpf],
                use_posterior_mean=use_posterior_mean,
                use_continuity_constraint=use_continuity_constraint,
                speed_vec=speed_vec[:_Tpf] if speed_vec is not None else None,
                continuity_sigma_k=continuity_sigma_k,
                continuity_speed_ref=continuity_speed_ref,
                continuity_exp=continuity_exp,
                continuity_sigma_min=continuity_sigma_min,
                continuity_sigma_max=continuity_sigma_max,
                continuity_sigma_default=continuity_sigma_default,
                save_posterior=True,
            )
            return _add_diagnostics({"ok": True, "out": out2d,
                    "abs_err": out2d["euclidean_err"],
                    "Ksum": out2d["Ksum"], "idx_use": out2d["idx_use"]}, out2d, is_pf_mode=True)

        return {"ok": False, "reason": f"Unknown decoder_mode={decoder_mode}"}

    # ---- Leave-one-lap-out (LOLO) CV: N folds, one held-out lap each ----
    _array_keys = ("abs_err", "Ksum", "idx_use", "true_pos_1d", "decoded_pos_1d",
                   "frac_active", "frac_PF_active", "posterior_entropy")
    _fold_arrays = {k: [] for k in _array_keys}
    _n_folds_ok = 0
    _fold_fail_reasons = []

    for held_out_lap in all_laps:
        train_laps_fold = all_laps[all_laps != held_out_lap]
        train_mask_fold = _build_lap_mask(LT, train_laps_fold, use_speed=use_speed, min_speed=min_speed)
        test_mask_fold = _build_lap_mask(LT, [held_out_lap], use_speed=use_speed, min_speed=min_speed)

        r_fold = _run_split(train_mask_fold, test_mask_fold, f"LOLO fold (held-out lap {held_out_lap})")
        if not r_fold.get("ok", False):
            _fold_fail_reasons.append(r_fold.get("reason", "?"))
            continue

        _n_folds_ok += 1
        for k in _array_keys:
            arr = r_fold.get(k)
            if arr is not None:
                _fold_arrays[k].append(np.asarray(arr))

    if _n_folds_ok == 0:
        _uniq = sorted(set(_fold_fail_reasons))
        return {"ok": False, "reason": f"All LOLO folds failed ({len(all_laps)} laps): {'; '.join(_uniq)}"}

    # Concatenate held-out predictions across folds
    _lolo_result = {"ok": True}
    for k in _array_keys:
        parts = _fold_arrays[k]
        if parts:
            _lolo_result[k] = np.concatenate(parts)

    # Sort all pooled arrays chronologically by idx_use
    idx = _lolo_result.get("idx_use")
    if idx is not None and len(idx) > 0:
        sort_key = np.mean(np.asarray(idx), axis=1) if np.ndim(idx) == 2 else np.asarray(idx, float)
        order = np.argsort(sort_key)
        for k in _array_keys:
            arr = _lolo_result.get(k)
            if arr is not None:
                _lolo_result[k] = arr[order]

    # Classify laps by direction purely for metadata
    laps_R, laps_L = _classify_laps_by_direction(LT)
    return {
        "ok": True,
        "train_to_test": _lolo_result,
        "cv_method": "LOLO",
        "n_folds": _n_folds_ok,
        "dt_sec": dt_sec,
        "n_cells": int(S.shape[0]),
        "decoder_mode": decoder_mode,
        "n_laps_total": int(len(all_laps)),
        "n_laps_R": len(laps_R) if laps_R is not None else 0,
        "n_laps_L": len(laps_L) if laps_L is not None else 0,
    }


# ---- Cross-session decode -----------------------------------------------

def decode_LT_cross_session_position_vs_time(
    LT_train,
    LT_test,
    decoder_mode,
    *,
    mapping="LT1+LT2",
    n_pos_bins=60,
    time_bin_frames=5,
    use_speed=True,
    min_speed=2.0,
    use_z_score="none",
    use_posterior_mean=True,
    use_continuity_constraint=True,
    continuity_sigma_k=35.0,
    continuity_speed_ref=20.0,
    continuity_exp=1.0,
    continuity_sigma_min=10.0,
    continuity_sigma_max=30.0,
    continuity_sigma_default=18.0,
    n_x_bins=20,
    n_y_bins=20,
    shuffle_type: str = "none",
    shuffle_seed: Optional[int] = None,
):
    """Cross-session decode: train on all LT_train laps, decode all LT_test laps.

    Uses cross-registered cells.
    """
    # Get mapped S matrices
    try:
        df_mapping = LT_train.crossreg.get_mappings_cells(mapping_type=mapping)
    except Exception as e:
        return {"ok": False, "reason": f"Mapping error: {e}"}

    cells_train = df_mapping[LT_train.session_group].astype(float).astype(int).tolist()
    cells_test = df_mapping[LT_test.session_group].astype(float).astype(int).tolist()
    S_train_mapped, _ = get_mapped_S_from_unit_ids(LT_train, cells_train)
    S_test_mapped, _ = get_mapped_S_from_unit_ids(LT_test, cells_test)
    S_train_mapped, S_test_mapped = _apply_zscore_pair(S_train_mapped, S_test_mapped, use_z_score)
    if str(shuffle_type).strip().lower() not in ("", "none", "off", "false", "0"):
        _rng = default_rng(shuffle_seed)
        S_train_mapped = _apply_decoder_time_shuffle(S_train_mapped, shuffle_type=shuffle_type, rng=_rng)
        S_test_mapped = _apply_decoder_time_shuffle(S_test_mapped, shuffle_type=shuffle_type, rng=_rng)

    if S_train_mapped.shape[0] == 0 or S_test_mapped.shape[0] == 0:
        return {"ok": False, "reason": "No mapped cells."}

    train_mask, dt_train = _build_all_laps_mask(LT_train, use_speed=use_speed, min_speed=min_speed)
    test_mask, dt_test = _build_all_laps_mask(LT_test, use_speed=use_speed, min_speed=min_speed)
    if train_mask is None or test_mask is None:
        return {"ok": False, "reason": "No lap segmentation."}
    if train_mask.sum() < 10 * time_bin_frames or test_mask.sum() < 10 * time_bin_frames:
        return {"ok": False, "reason": "Not enough frames."}

    T_train = LT_train.S.shape[1]
    T_test = LT_test.S.shape[1]
    x_1d_train = np.asarray(LT_train.miniscope_loc_1d_px, float)[:T_train]
    x_1d_train = x_1d_train * _LT_1D_CM_PER_PX    # px -> cm
    x_1d_test = np.asarray(LT_test.miniscope_loc_1d_px, float)[:T_test]
    x_1d_test = x_1d_test * _LT_1D_CM_PER_PX      # px -> cm
    speed_test = _get_miniscope_velocity_vector(LT_test, T_test)

    has_fm_train = hasattr(LT_train, "fm") and LT_train.fm is not None
    has_cl_train = hasattr(LT_train, "centerline_miniscope") and LT_train.centerline_miniscope is not None
    has_cl_test = hasattr(LT_test, "centerline_miniscope") and LT_test.centerline_miniscope is not None

    # pos_range from merged train + test
    all_valid = np.concatenate([x_1d_train[train_mask[:T_train]], x_1d_test[test_mask[:T_test]]])
    pos_range = (float(np.nanmin(all_valid)), float(np.nanmax(all_valid)))

    cc = dict(
        use_posterior_mean=use_posterior_mean,
        use_continuity_constraint=use_continuity_constraint,
        speed_vec=speed_test,
        continuity_sigma_k=continuity_sigma_k,
        continuity_speed_ref=continuity_speed_ref,
        continuity_exp=continuity_exp,
        continuity_sigma_min=continuity_sigma_min,
        continuity_sigma_max=continuity_sigma_max,
        continuity_sigma_default=continuity_sigma_default,
        save_posterior=True,
    )

    # Precompute cm-converted 2D coordinates for 2D decoder branches
    _cm = float(_LT_1D_CM_PER_PX)
    _bw_cm = (float(LT_train.fm.loc.bin_width) if has_fm_train else 4.5) * _cm
    _cl_cm = (np.asarray(LT_test.centerline_miniscope, float) * _cm
              if has_cl_test else None)

    # Precompute PF-cell mask over mapped rows for frac_PF_active
    N_mapped = S_train_mapped.shape[0]
    if has_fm_train and hasattr(LT_train.fm, 'pf') and hasattr(LT_train.fm.pf, 'merged_means'):
        _pf_train_ids = set(int(LT_train.fm.cells[k]) for k in LT_train.fm.pf.merged_means
                            if len(LT_train.fm.pf.merged_means[k]) > 0)
        _pf_mapped_mask = np.array([int(cells_train[i]) in _pf_train_ids
                                     for i in range(N_mapped)], dtype=bool)
    else:
        _pf_mapped_mask = np.zeros(N_mapped, dtype=bool)

    def _add_diag(result, out_dict, is_pf_mode):
        """Extract per-bin diagnostics from decoder output dict."""
        result["frac_active"] = out_dict["frac_active"]
        result["posterior_entropy"] = out_dict["posterior_entropy"]
        K = out_dict["K"]
        if is_pf_mode or not _pf_mapped_mask.any():
            result["frac_PF_active"] = out_dict["frac_active"]
        else:
            result["frac_PF_active"] = (K[:, _pf_mapped_mask] > 0).mean(axis=1) if K.shape[0] > 0 else np.array([])
        if "posterior" in out_dict:
            result["posterior"] = out_dict["posterior"]
        if "grid_x_flat" in out_dict:
            result["grid_x_flat"] = out_dict["grid_x_flat"]
            result["grid_y_flat"] = out_dict["grid_y_flat"]
        return result

    if decoder_mode == "S_1D":
        dec = BayesianDecoder1D(n_pos_bins=n_pos_bins, time_bin_frames=time_bin_frames)
        dec.fit(S_train_mapped, x_1d_train, train_mask[:T_train], dt_train)
        out = dec.decode(S_test_mapped, x_1d_test, test_mask[:T_test], **cc)
        if out["decoded_pos"].size == 0:
            return {"ok": False, "reason": "Empty decode."}
        return _add_diag({"ok": True, "out": out,
                "true_pos_1d": out["true_pos"], "decoded_pos_1d": out["decoded_pos"],
                "abs_err": BayesianDecoder1D.abs_error(out["decoded_pos"], out["true_pos"]),
                "Ksum": out["Ksum"], "idx_use": out["idx_use"],
                "dt_sec": dt_test, "n_cells_mapped": int(S_train_mapped.shape[0]),
                "decoder_mode": decoder_mode}, out, is_pf_mode=False)

    elif decoder_mode == "PF_1D":
        if not has_fm_train or not has_cl_train:
            return {"ok": False, "reason": "No .fm or centerline on train for PF_1D"}
        fm = LT_train.fm
        fm_cells = list(fm.cells)
        # Map fm cells to trained-S row indices
        pf_idx = []
        if fm.sig_responses is not None:
            pf_idx = [i for i, c in enumerate(fm_cells) if c in fm.sig_responses]
        else:
            pf_idx = list(range(len(fm_cells)))

        # For cross-session PF_1D, the tuning curves come from the training fm
        # but we need to find the corresponding mapped test neurons.
        # The fm.cells are indices into LT_train.S. We need to find which
        # mapped rows correspond to which fm cells.
        train_unit_ids = [int(u) for u in cells_train if u is not None and np.isfinite(u)]
        pf_cells_S = [fm_cells[i] for i in pf_idx]
        # Find which mapping rows correspond to PF cells
        mapped_pf_rows = []
        pf_idx_used = []
        for pi, sc in zip(pf_idx, pf_cells_S):
            if sc in train_unit_ids:
                row_in_mapped = train_unit_ids.index(sc)
                mapped_pf_rows.append(row_in_mapped)
                pf_idx_used.append(pi)

        if len(mapped_pf_rows) == 0:
            return {"ok": False, "reason": "No PF cells in cross-reg mapping for PF_1D"}

        S_test_pf = S_test_mapped[mapped_pf_rows, :]
        dec = BayesianDecoder1D_PF(n_pos_bins=n_pos_bins, time_bin_frames=time_bin_frames)
        dec.fit_from_place_fields(
            fm, LT_train.centerline_miniscope, pos_range, dt_train,
            x_1d_train=x_1d_train, train_mask=train_mask[:T_train],
            fm_cell_indices=pf_idx_used,
        )
        out = dec.decode(S_test_pf, x_1d_test, test_mask[:T_test], **cc)
        if out["decoded_pos"].size == 0:
            return {"ok": False, "reason": "Empty decode."}
        return _add_diag({"ok": True, "out": out,
                "true_pos_1d": out["true_pos"], "decoded_pos_1d": out["decoded_pos"],
                "abs_err": BayesianDecoder1D.abs_error(out["decoded_pos"], out["true_pos"]),
                "Ksum": out["Ksum"], "idx_use": out["idx_use"],
                "dt_sec": dt_test, "n_cells_mapped": len(mapped_pf_rows),
                "decoder_mode": decoder_mode}, out, is_pf_mode=True)

    elif decoder_mode == "S_2D":
        if not has_cl_test:
            return {"ok": False, "reason": "No centerline on test for S_2D"}
        loc_X_tr = np.asarray(LT_train.loc_X_miniscope_smooth, float)[:T_train] * _cm
        loc_Y_tr = np.asarray(LT_train.loc_Y_miniscope_smooth, float)[:T_train] * _cm
        loc_X_te = np.asarray(LT_test.loc_X_miniscope_smooth, float)[:T_test] * _cm
        loc_Y_te = np.asarray(LT_test.loc_Y_miniscope_smooth, float)[:T_test] * _cm
        _nx = max(2, round((np.nanmax(loc_X_tr) - np.nanmin(loc_X_tr)) / _bw_cm))
        _ny = max(2, round((np.nanmax(loc_Y_tr) - np.nanmin(loc_Y_tr)) / _bw_cm))
        dec2d = BayesianDecoder2D(n_x_bins=_nx, n_y_bins=_ny,
                                   time_bin_frames=time_bin_frames)
        dec2d.fit(S_train_mapped, loc_X_tr, loc_Y_tr, train_mask[:T_train], dt_train)
        out2d = dec2d.decode(
            S_test_mapped, loc_X_te, loc_Y_te, test_mask[:T_test],
            **cc,
        )
        if out2d["decoded_x"].size == 0:
            return {"ok": False, "reason": "Empty decode."}
        dec_1d = _project_decoded_2d_to_1d(out2d["decoded_x"], out2d["decoded_y"],
                                            _cl_cm)
        true_1d = _project_decoded_2d_to_1d(out2d["true_x"], out2d["true_y"],
                                             _cl_cm)
        return _add_diag({"ok": True, "out": out2d,
                "true_pos_1d": true_1d, "decoded_pos_1d": dec_1d,
                "abs_err": np.abs(dec_1d - true_1d),
                "Ksum": out2d["Ksum"], "idx_use": out2d["idx_use"],
                "dt_sec": dt_test, "n_cells_mapped": int(S_train_mapped.shape[0]),
                "decoder_mode": decoder_mode}, out2d, is_pf_mode=False)

    elif decoder_mode == "PF_2D":
        if not has_fm_train or not has_cl_test:
            return {"ok": False, "reason": "No .fm on train or no centerline on test for PF_2D"}
        fm = LT_train.fm
        fm_cells = list(fm.cells)
        pf_idx = []
        if fm.sig_responses is not None:
            pf_idx = [i for i, c in enumerate(fm_cells) if c in fm.sig_responses]
        else:
            pf_idx = list(range(len(fm_cells)))

        train_unit_ids = [int(u) for u in cells_train if u is not None and np.isfinite(u)]
        pf_cells_S = [fm_cells[i] for i in pf_idx]
        mapped_pf_rows = []
        pf_idx_used = []
        for pi, sc in zip(pf_idx, pf_cells_S):
            if sc in train_unit_ids:
                row_in_mapped = train_unit_ids.index(sc)
                mapped_pf_rows.append(row_in_mapped)
                pf_idx_used.append(pi)

        if len(mapped_pf_rows) == 0:
            return {"ok": False, "reason": "No PF cells in cross-reg for PF_2D"}

        S_test_pf = S_test_mapped[mapped_pf_rows, :]
        fm.check_fluorescence_map_occup()
        dec2d_pf = BayesianDecoder2D_PF(time_bin_frames=time_bin_frames)
        dec2d_pf.fit_from_place_fields(
            fm.pf, fm.fluorescence_map_occup, fm.loc.occupancy,
            fm_cells=fm_cells, cell_indices=pf_idx_used,
            dt_sec=dt_train, bin_width=_bw_cm,
        )
        loc_X_te = np.asarray(LT_test.loc_X_miniscope_smooth, float)[:T_test] * _cm
        loc_Y_te = np.asarray(LT_test.loc_Y_miniscope_smooth, float)[:T_test] * _cm
        out2d = dec2d_pf.decode(
            S_test_pf, loc_X_te, loc_Y_te, test_mask[:T_test],
            use_posterior_mean=use_posterior_mean,
            use_continuity_constraint=use_continuity_constraint,
            speed_vec=speed_test[:T_test] if speed_test is not None else None,
            continuity_sigma_k=continuity_sigma_k,
            continuity_speed_ref=continuity_speed_ref,
            continuity_exp=continuity_exp,
            continuity_sigma_min=continuity_sigma_min,
            continuity_sigma_max=continuity_sigma_max,
            continuity_sigma_default=continuity_sigma_default,
            save_posterior=True,
        )
        if out2d["decoded_x"].size == 0:
            return {"ok": False, "reason": "Empty decode."}
        dec_1d = _project_decoded_2d_to_1d(out2d["decoded_x"], out2d["decoded_y"],
                                            _cl_cm)
        true_1d = _project_decoded_2d_to_1d(out2d["true_x"], out2d["true_y"],
                                             _cl_cm)
        return _add_diag({"ok": True, "out": out2d,
                "true_pos_1d": true_1d, "decoded_pos_1d": dec_1d,
                "abs_err": np.abs(dec_1d - true_1d),
                "Ksum": out2d["Ksum"], "idx_use": out2d["idx_use"],
                "dt_sec": dt_test, "n_cells_mapped": len(mapped_pf_rows),
                "decoder_mode": decoder_mode}, out2d, is_pf_mode=True)

    # ---- True-2D cross-session modes (no 1D projection) ------------------
    elif decoder_mode == "S_2D_full":
        loc_X_tr = np.asarray(LT_train.loc_X_miniscope_smooth, float)[:T_train] * _cm
        loc_Y_tr = np.asarray(LT_train.loc_Y_miniscope_smooth, float)[:T_train] * _cm
        loc_X_te = np.asarray(LT_test.loc_X_miniscope_smooth, float)[:T_test] * _cm
        loc_Y_te = np.asarray(LT_test.loc_Y_miniscope_smooth, float)[:T_test] * _cm
        _nx = max(2, round((np.nanmax(loc_X_tr) - np.nanmin(loc_X_tr)) / _bw_cm))
        _ny = max(2, round((np.nanmax(loc_Y_tr) - np.nanmin(loc_Y_tr)) / _bw_cm))
        dec2d = BayesianDecoder2D(n_x_bins=_nx, n_y_bins=_ny,
                                   time_bin_frames=time_bin_frames)
        dec2d.fit(S_train_mapped, loc_X_tr, loc_Y_tr, train_mask[:T_train], dt_train)
        out2d = dec2d.decode(
            S_test_mapped, loc_X_te, loc_Y_te, test_mask[:T_test],
            **cc,
        )
        if out2d["decoded_x"].size == 0:
            return {"ok": False, "reason": "Empty decode."}
        return _add_diag({"ok": True, "out": out2d,
                "abs_err": out2d["euclidean_err"],
                "Ksum": out2d["Ksum"], "idx_use": out2d["idx_use"],
                "dt_sec": dt_test, "n_cells_mapped": int(S_train_mapped.shape[0]),
                "decoder_mode": decoder_mode}, out2d, is_pf_mode=False)

    elif decoder_mode == "PF_2D_full":
        if not has_fm_train:
            return {"ok": False, "reason": "No .fm on train for PF_2D_full"}
        fm = LT_train.fm
        fm_cells = list(fm.cells)
        pf_idx = []
        if fm.sig_responses is not None:
            pf_idx = [i for i, c in enumerate(fm_cells) if c in fm.sig_responses]
        else:
            pf_idx = list(range(len(fm_cells)))

        train_unit_ids = [int(u) for u in cells_train if u is not None and np.isfinite(u)]
        pf_cells_S = [fm_cells[i] for i in pf_idx]
        mapped_pf_rows = []
        pf_idx_used = []
        for pi, sc in zip(pf_idx, pf_cells_S):
            if sc in train_unit_ids:
                row_in_mapped = train_unit_ids.index(sc)
                mapped_pf_rows.append(row_in_mapped)
                pf_idx_used.append(pi)

        if len(mapped_pf_rows) == 0:
            return {"ok": False, "reason": "No PF cells in cross-reg for PF_2D_full"}

        S_test_pf = S_test_mapped[mapped_pf_rows, :]
        fm.check_fluorescence_map_occup()
        dec2d_pf = BayesianDecoder2D_PF(time_bin_frames=time_bin_frames)
        dec2d_pf.fit_from_place_fields(
            fm.pf, fm.fluorescence_map_occup, fm.loc.occupancy,
            fm_cells=fm_cells, cell_indices=pf_idx_used,
            dt_sec=dt_train, bin_width=_bw_cm,
        )
        loc_X_te = np.asarray(LT_test.loc_X_miniscope_smooth, float)[:T_test] * _cm
        loc_Y_te = np.asarray(LT_test.loc_Y_miniscope_smooth, float)[:T_test] * _cm
        out2d = dec2d_pf.decode(
            S_test_pf, loc_X_te, loc_Y_te, test_mask[:T_test],
            use_posterior_mean=use_posterior_mean,
            use_continuity_constraint=use_continuity_constraint,
            speed_vec=speed_test[:T_test] if speed_test is not None else None,
            continuity_sigma_k=continuity_sigma_k,
            continuity_speed_ref=continuity_speed_ref,
            continuity_exp=continuity_exp,
            continuity_sigma_min=continuity_sigma_min,
            continuity_sigma_max=continuity_sigma_max,
            continuity_sigma_default=continuity_sigma_default,
            save_posterior=True,
        )
        if out2d["decoded_x"].size == 0:
            return {"ok": False, "reason": "Empty decode."}
        return _add_diag({"ok": True, "out": out2d,
                "abs_err": out2d["euclidean_err"],
                "Ksum": out2d["Ksum"], "idx_use": out2d["idx_use"],
                "dt_sec": dt_test, "n_cells_mapped": len(mapped_pf_rows),
                "decoder_mode": decoder_mode}, out2d, is_pf_mode=True)

    return {"ok": False, "reason": f"Unknown decoder_mode={decoder_mode}"}


# ---- Position-vs-time gap helpers ----------------------------------------

def _find_speed_filtered_gaps(t, gap_factor=2.0):
    """Detect speed-filtered gaps in a 1-D time vector.

    A gap is any consecutive pair whose spacing exceeds
    *gap_factor* × the median spacing (typically caused by
    bins excluded due to low running speed).

    Returns list of ``(idx_before, idx_after, t_start, t_end)``.
    """
    if len(t) < 2:
        return []
    dt = np.diff(t)
    median_dt = np.median(dt)
    if median_dt <= 0:
        return []
    threshold = gap_factor * median_dt
    return [
        (i, i + 1, float(t[i]), float(t[i + 1]))
        for i, d in enumerate(dt)
        if d > threshold
    ]


def _insert_nans_at_gaps(t, arrays, gaps):
    """Insert NaN between points that straddle a speed-filtered gap to break lines.

    Parameters
    ----------
    t : 1-D ndarray
    arrays : list of 1-D ndarrays (same length as *t*)
    gaps : list from :func:`_find_speed_filtered_gaps`

    Returns ``(t_out, arr0_out, arr1_out, ...)``.
    """
    if not gaps:
        return (t,) + tuple(arrays)

    break_indices = sorted({g[0] for g in gaps})
    n_cols = 1 + len(arrays)
    parts = [[] for _ in range(n_cols)]
    _nan1 = np.array([np.nan])
    prev = 0
    for bi in break_indices:
        parts[0].append(t[prev:bi + 1])
        for j, a in enumerate(arrays):
            parts[1 + j].append(a[prev:bi + 1])
        parts[0].append(_nan1)
        for j in range(len(arrays)):
            parts[1 + j].append(_nan1)
        prev = bi + 1
    if prev < len(t):
        parts[0].append(t[prev:])
        for j, a in enumerate(arrays):
            parts[1 + j].append(a[prev:])

    return tuple(np.concatenate(p) for p in parts)


def _shade_speed_filtered_gaps(ax, gaps, **kwargs):
    """Add light-grey shading over speed-filtered gap regions on *ax*."""
    kw = dict(color="#cccccc", alpha=0.45, zorder=0, lw=0)
    kw.update(kwargs)
    for _, _, t0, t1 in gaps:
        ax.axvspan(t0, t1, **kw)


def _compact_time(t, gaps):
    """Remove gap durations from *t* and rescale to the original range.

    The returned array spans ``[t[0], t[-1]]`` but speed-filtered gap
    durations are excised so data stretches to fill the full axis.
    """
    if not gaps or len(t) < 2:
        return t.copy()
    t_out = np.asarray(t, float).copy()
    cum_gap = 0.0
    gap_idx = 0
    for i in range(len(t_out)):
        while gap_idx < len(gaps) and i >= gaps[gap_idx][1]:
            cum_gap += gaps[gap_idx][3] - gaps[gap_idx][2]
            gap_idx += 1
        t_out[i] -= cum_gap
    # rescale to original [t[0], t[-1]]
    t0, t1 = float(t[0]), float(t[-1])
    tc0, tc1 = t_out[0], t_out[-1]
    if tc1 > tc0:
        t_out = t0 + (t_out - tc0) * ((t1 - t0) / (tc1 - tc0))
    return t_out


# ---- Plotting -----------------------------------------------------------

def plot_position_vs_time_LT(
    all_results,
    *,
    PLOTS_DIR,
    decoder_tag="S_1D",
    auto_close=True,
):
    """Plot 1D position vs time for each mouse/condition in *all_results*.

    Creates a single-panel figure per mouse per condition, styled to match
    the 2D ``plot_xy_time_per_mouse`` so they can be shown side-by-side.

    Parameters
    ----------
    all_results : dict
        ``{mouse: {"group": str, "conditions": {cond_name: result_dict}}}``
        Each *result_dict* must contain ``"ok"`` and, when ok,
        a ``"train_to_test"`` sub-dict (LOLO CV result, for within)
        or top-level ``"true_pos_1d"`` / ``"decoded_pos_1d"`` (for cross-session).
    """
    save_dir = os.path.join(PLOTS_DIR, "position_vs_time")
    os.makedirs(save_dir, exist_ok=True)

    def _plot_single(mouse, group, cond_name, true_1d, dec_1d, dt_sec, idx_use, suffix=""):
        true_1d = np.asarray(true_1d, float)
        dec_1d = np.asarray(dec_1d, float)
        if true_1d.size == 0:
            return

        if dt_sec is not None and idx_use is not None and len(idx_use) > 0:
            t = np.mean(np.asarray(idx_use), axis=1) * float(dt_sec)
            xlabel = "Time (s)"
        else:
            t = np.arange(len(true_1d))
            xlabel = "Chunk index"

        tag = f"{mouse}_{group}_{cond_name}_{decoder_tag}{suffix}"
        gaps = _find_speed_filtered_gaps(t)

        # ---- Normal plot (grey-out speed-filtered periods) ----
        t_b, true_b, dec_b = _insert_nans_at_gaps(t, [true_1d, dec_1d], gaps)
        fig, ax = plt.subplots(figsize=(14, 5), dpi=150)
        ax.plot(t_b, true_b, color="black", lw=1.2, label="Real")
        ax.plot(t_b, dec_b, color="#555555", lw=1.0, ls="--", label="Decoded")
        _shade_speed_filtered_gaps(ax, gaps)
        ax.set_ylabel(f"Position along track ({_LT_1D_DISTANCE_UNIT})")
        ax.set_xlabel(xlabel)
        _nice_suffix = suffix.lstrip("_").replace("_", " ") if suffix else ""
        _title_base = f"{mouse} ({group})  {cond_name}  [{decoder_tag}]"
        _title = f"{_title_base}  {_nice_suffix}" if _nice_suffix else _title_base
        ax.set_title(_title)
        ax.legend(loc="upper right", fontsize=8)
        ax.grid(True, alpha=0.25)
        fig.tight_layout()
        fig.savefig(os.path.join(save_dir, f"{tag}_pos_vs_time.png"), dpi=300)
        if auto_close:
            plt.close(fig)

        # ---- Compact plot (speed-filtered periods excised) ----
        if gaps:
            t_c = _compact_time(t, gaps)
            fig2, ax2 = plt.subplots(figsize=(14, 5), dpi=150)
            ax2.plot(t_c, true_1d, color="black", lw=1.2, label="Real")
            ax2.plot(t_c, dec_1d, color="#555555", lw=1.0, ls="--", label="Decoded")
            ax2.set_ylabel(f"Position along track ({_LT_1D_DISTANCE_UNIT})")
            ax2.set_xlabel(xlabel)
            ax2.set_title(f"{_title}  (compact)")
            ax2.legend(loc="upper right", fontsize=8)
            ax2.grid(True, alpha=0.25)
            fig2.tight_layout()
            fig2.savefig(os.path.join(save_dir, f"{tag}_pos_vs_time_compact.png"), dpi=300)
            if auto_close:
                plt.close(fig2)

    for mouse, mres in all_results.items():
        group = mres.get("group", "NA")
        conditions = mres.get("conditions", {})
        for cond_name, cres in conditions.items():
            if not cres.get("ok", False):
                continue
            dt_sec = cres.get("dt_sec")

            # Within-session: LOLO result stored under train_to_test
            for split_key in ("train_to_test",):
                sub = cres.get(split_key)
                if isinstance(sub, dict) and sub.get("ok", False):
                    _plot_single(mouse, group, cond_name,
                                 sub["true_pos_1d"], sub["decoded_pos_1d"],
                                 dt_sec, sub.get("idx_use"), suffix=f"_{split_key}")

            # Cross-session: top-level true_pos_1d / decoded_pos_1d
            if "true_pos_1d" in cres and "train_to_test" not in cres:
                _plot_single(mouse, group, cond_name,
                             cres["true_pos_1d"], cres["decoded_pos_1d"],
                             dt_sec, cres.get("idx_use"))

    print(f"[LT-POS-TIME] Saved position vs time plots → {save_dir}")


# ---- 2-D decoder-error diagnostic plots ---------------------------------

def _get_session_for_condition(cond_name, mouse, LT1_dict, LT2_dict):
    """Return the LT session whose 2-D coordinates match the *test* data."""
    if "LT1" in cond_name and "LT2" not in cond_name:
        return LT1_dict.get(mouse)
    return LT2_dict.get(mouse)          # within_LT2  or  LT1_to_LT2 (test=LT2)


def plot_decoder_2d_error_LT(
    all_results,
    LT1_dict,
    LT2_dict,
    *,
    PLOTS_DIR,
    decoder_tag="S_1D",
    mouse_groups=None,
    auto_close=True,
):
    """2-D linear-track diagnostic plots showing decoder error in physical space.

    For every mouse / condition / fold two figures are produced:

    **Plot A — decoded overlay**
        Dark-grey trajectory background.  Real test-frame positions plotted
        as small dark dots.  Decoded positions plotted as coloured scatter
        (hue = error magnitude, size ∝ error).

    **Plot B — error at real position**
        Light-grey trajectory background.  At the *real* 2-D position of each
        test frame a dot is drawn whose colour/size encodes the decode error.
        This directly shows which track regions have high error.

    Both plots draw the centerline in red.
    """
    if mouse_groups is None:
        mouse_groups = {}

    save_dir = os.path.join(PLOTS_DIR, "decoder_2d_error")
    os.makedirs(save_dir, exist_ok=True)

    _rcparams = {
        "font.size": 14,
        "axes.labelsize": 16,
        "axes.titlesize": 16,
        "xtick.labelsize": 12,
        "ytick.labelsize": 12,
    }

    def _plot_pair(mouse, group, cond_name, true_1d, dec_1d, idx_use, LT, suffix=""):
        """Generate the two 2-D error diagnostic figures for one fold."""
        true_1d = np.asarray(true_1d, float)
        dec_1d  = np.asarray(dec_1d, float)
        if true_1d.size == 0 or LT is None:
            return

        centerline = getattr(LT, "centerline_miniscope", None)
        if centerline is None:
            return
        centerline = np.asarray(centerline, float)
        cm_per_px = float(_LT_1D_CM_PER_PX)

        # Full session 2-D trajectory (convert pixels → cm)
        xy_full = np.column_stack([
            np.asarray(LT.loc_X_miniscope_smooth, float),
            np.asarray(LT.loc_Y_miniscope_smooth, float),
        ]) * cm_per_px

        # Map decoded and real 1-D arc-length back to 2-D on centerline (pixels), then → cm
        real_2d = _arclength_to_2d_on_centerline(true_1d, centerline) * cm_per_px
        dec_2d  = _arclength_to_2d_on_centerline(dec_1d,  centerline) * cm_per_px

        abs_err = np.abs(dec_1d - true_1d)

        # Skip entirely if no finite errors (e.g. all NaN)
        finite_mask = np.isfinite(abs_err)
        if not np.any(finite_mask):
            return

        # Dot size: min 4 at 0 error, max 50 at max(abs_err)
        err_max = np.nanmax(abs_err[finite_mask])
        err_max = max(err_max, 1.0)
        sizes = np.where(finite_mask, 4.0 + 46.0 * (np.nan_to_num(abs_err) / err_max), 4.0)

        tag = f"{mouse}_{group}_{cond_name}_{decoder_tag}{suffix}"

        vmin, vmax = 0.0, float(np.nanpercentile(abs_err[finite_mask], 97))
        vmax = max(vmax, 1.0)

        # Filter to finite-error points only for scatter plots
        fm = finite_mask
        real_2d_f, dec_2d_f = real_2d[fm], dec_2d[fm]
        abs_err_f, sizes_f = abs_err[fm], sizes[fm]

        # ==============================================================
        # Plot A — real vs decoded in 2-D
        # ==============================================================
        with plt.rc_context(_rcparams):
            fig_a, ax_a = plt.subplots(figsize=(12, 8), dpi=150)

            # Full trajectory background
            ax_a.plot(
                xy_full[:, 0], xy_full[:, 1],
                color="#888888", alpha=0.25, linewidth=0.6, zorder=1,
            )
            # Real test-frame positions in darker grey
            ax_a.scatter(
                real_2d_f[:, 0], real_2d_f[:, 1],
                s=6, color="#444444", alpha=0.5, zorder=2, label="Real",
            )
            # Decoded positions coloured by error
            sc_a = ax_a.scatter(
                dec_2d_f[:, 0], dec_2d_f[:, 1],
                c=abs_err_f, cmap="RdYlGn_r", s=sizes_f, alpha=0.7,
                vmin=vmin, vmax=vmax, edgecolors="none", zorder=3,
                label="Decoded",
            )
            # Lines from decoded to real for large-error points
            _err_thr = np.nanpercentile(abs_err_f, 75)
            for _i in np.where(abs_err_f >= _err_thr)[0]:
                ax_a.plot(
                    [dec_2d_f[_i, 0], real_2d_f[_i, 0]],
                    [dec_2d_f[_i, 1], real_2d_f[_i, 1]],
                    color="black", linewidth=0.5, alpha=0.5, zorder=2,
                )

            ax_a.set_aspect("equal", adjustable="box")
            ax_a.set_xlabel(f"X ({_LT_1D_DISTANCE_UNIT})")
            ax_a.set_ylabel(f"Y ({_LT_1D_DISTANCE_UNIT})")
            _sfx = suffix.lstrip("_").replace("_", " ") if suffix else ""
            _t = f"{mouse} ({group})  {cond_name}  [{decoder_tag}]"
            if _sfx:
                _t += f"  {_sfx}"
            ax_a.set_title(f"{_t}\nReal vs Decoded 2-D")
            ax_a.legend(loc="upper right", fontsize=9)
            cbar_a = fig_a.colorbar(sc_a, ax=ax_a, fraction=0.046, pad=0.04)
            cbar_a.set_label(f"Decode error ({_LT_1D_DISTANCE_UNIT})")
            fig_a.tight_layout()
            fig_a.savefig(
                os.path.join(save_dir, f"{tag}_2d_real_vs_decoded.png"),
                dpi=300, bbox_inches="tight",
            )
            if auto_close:
                plt.close(fig_a)

        # ==============================================================
        # Plot B — error heatmap at real 2-D position
        # ==============================================================
        with plt.rc_context(_rcparams):
            fig_b, ax_b = plt.subplots(figsize=(12, 8), dpi=150)

            # Full trajectory background (lighter)
            ax_b.plot(
                xy_full[:, 0], xy_full[:, 1],
                color="#cccccc", alpha=0.35, linewidth=0.6, zorder=1,
            )
            # Error at real position
            sc_b = ax_b.scatter(
                real_2d_f[:, 0], real_2d_f[:, 1],
                c=abs_err_f, cmap="RdYlGn_r", s=sizes_f, alpha=0.7,
                vmin=vmin, vmax=vmax, edgecolors="none", zorder=2,
            )
            # Lines from real to decoded for large-error points
            _err_thr_b = np.nanpercentile(abs_err_f, 75)
            for _i in np.where(abs_err_f >= _err_thr_b)[0]:
                ax_b.plot(
                    [real_2d_f[_i, 0], dec_2d_f[_i, 0]],
                    [real_2d_f[_i, 1], dec_2d_f[_i, 1]],
                    color="black", linewidth=0.5, alpha=0.5, zorder=1,
                )

            ax_b.set_aspect("equal", adjustable="box")
            ax_b.set_xlabel(f"X ({_LT_1D_DISTANCE_UNIT})")
            ax_b.set_ylabel(f"Y ({_LT_1D_DISTANCE_UNIT})")
            ax_b.set_title(f"{_t}\nDecode error at real position")
            cbar_b = fig_b.colorbar(sc_b, ax=ax_b, fraction=0.046, pad=0.04)
            cbar_b.set_label(f"Decode error ({_LT_1D_DISTANCE_UNIT})")
            fig_b.tight_layout()
            fig_b.savefig(
                os.path.join(save_dir, f"{tag}_2d_error_at_real_pos.png"),
                dpi=300, bbox_inches="tight",
            )
            if auto_close:
                plt.close(fig_b)

    # ---- iterate mice / conditions / folds ------------------------------
    for mouse, mres in all_results.items():
        group = mres.get("group", "NA")
        conditions = mres.get("conditions", {})
        for cond_name, cres in conditions.items():
            if not cres.get("ok", False):
                continue

            LT = _get_session_for_condition(cond_name, mouse, LT1_dict, LT2_dict)

            # Within-session folds
            for split_key in ("train_to_test",):
                sub = cres.get(split_key)
                if isinstance(sub, dict) and sub.get("ok", False):
                    _plot_pair(mouse, group, cond_name,
                               sub["true_pos_1d"], sub["decoded_pos_1d"],
                               sub.get("idx_use"), LT, suffix=f"_{split_key}")

            # Cross-session (top-level keys)
            if "true_pos_1d" in cres and "train_to_test" not in cres:
                _plot_pair(mouse, group, cond_name,
                           cres["true_pos_1d"], cres["decoded_pos_1d"],
                           cres.get("idx_use"), LT)

    print(f"[LT-2D-ERR]   Saved 2-D decoder error plots → {save_dir}")


def plot_decoder_error_vs_interarm_LT(
    all_results,
    LT1_dict,
    LT2_dict,
    *,
    PLOTS_DIR,
    decoder_tag="S_1D",
    mouse_groups=None,
    auto_close=True,
):
    """Scatter of decoder error vs inter-arm 2-D distance.

    For every decoded frame the "mirror" position on the opposite arm is
    computed as *L - s* (where *L* is the total 1-D track length and *s* is
    the true 1-D position).  The Euclidean distance between pos(s) and
    pos(L-s) in 2-D pixel space (converted to cm) gives the inter-arm
    separation at that location.

    If decoder errors are driven by place-cell ambiguity across the two
    arms of the U-shaped track, large errors should concentrate where
    inter-arm distance is *small* (negative correlation).
    """
    from scipy.stats import spearmanr

    if mouse_groups is None:
        mouse_groups = {}

    save_dir = os.path.join(PLOTS_DIR, "decoder_interarm")
    os.makedirs(save_dir, exist_ok=True)

    _rcparams = {
        "font.size": 14,
        "axes.labelsize": 16,
        "axes.titlesize": 16,
        "xtick.labelsize": 12,
        "ytick.labelsize": 12,
    }

    def _compute_total_cm(centerline_px, cm_per_px):
        cl = np.asarray(centerline_px, float)
        diffs = np.diff(cl, axis=0)
        seg_px = np.sqrt((diffs ** 2).sum(axis=1))
        return float(seg_px.sum()) * cm_per_px

    def _plot_interarm(mouse, group, cond_name, true_1d, dec_1d, LT, suffix=""):
        true_1d = np.asarray(true_1d, float)
        dec_1d = np.asarray(dec_1d, float)
        if true_1d.size == 0 or LT is None:
            return None

        centerline = getattr(LT, "centerline_miniscope", None)
        if centerline is None:
            return None
        centerline = np.asarray(centerline, float)

        cm_per_px = float(_LT_1D_CM_PER_PX)
        L_cm = _compute_total_cm(centerline, cm_per_px)
        if L_cm <= 0:
            return None

        # Mirror position: s' = L - s
        mirror_1d = L_cm - true_1d

        # Map both to 2-D on centerline
        pos_real = _arclength_to_2d_on_centerline(true_1d, centerline)
        pos_mirror = _arclength_to_2d_on_centerline(mirror_1d, centerline)

        # Inter-arm distance in cm
        interarm_px = np.sqrt(((pos_real - pos_mirror) ** 2).sum(axis=1))
        interarm_cm = interarm_px * cm_per_px

        abs_err = np.abs(dec_1d - true_1d)

        # Filter to finite values
        fm = np.isfinite(abs_err) & np.isfinite(interarm_cm)
        if fm.sum() < 5:
            return None

        ia = interarm_cm[fm]
        err = abs_err[fm]
        pos = true_1d[fm]

        # Spearman correlation
        rho, pval = spearmanr(ia, err)

        # Trend line
        coeffs = np.polyfit(ia, err, 1)
        ia_sorted = np.sort(ia)
        trend = np.polyval(coeffs, ia_sorted)

        tag = f"{mouse}_{group}_{cond_name}_{decoder_tag}{suffix}"

        with plt.rc_context(_rcparams):
            fig, ax = plt.subplots(figsize=(10, 7), dpi=150)

            sc = ax.scatter(
                ia, err,
                c=pos, cmap="viridis", s=12, alpha=0.6,
                edgecolors="none", zorder=2,
            )
            ax.plot(
                ia_sorted, trend,
                color="red", linewidth=2, alpha=0.8, zorder=3,
                label=f"trend (slope={coeffs[0]:.2f})",
            )

            ax.set_xlabel(f"Inter-arm 2-D distance ({_LT_1D_DISTANCE_UNIT})")
            ax.set_ylabel(f"Decoder error ({_LT_1D_DISTANCE_UNIT})")

            _sfx = suffix.lstrip("_").replace("_", " ") if suffix else ""
            _t = f"{mouse} ({group})  {cond_name}  [{decoder_tag}]"
            if _sfx:
                _t += f"  {_sfx}"
            ax.set_title(
                f"{_t}\nDecoder error vs inter-arm distance"
                f"   (Spearman ρ={rho:.3f}, p={pval:.2e})"
            )

            ax.legend(loc="upper right", fontsize=10)
            cbar = fig.colorbar(sc, ax=ax, fraction=0.046, pad=0.04)
            cbar.set_label(f"True 1-D position ({_LT_1D_DISTANCE_UNIT})")
            fig.tight_layout()
            fig.savefig(
                os.path.join(save_dir, f"{tag}_error_vs_interarm.png"),
                dpi=300, bbox_inches="tight",
            )
            if auto_close:
                plt.close(fig)

        return {
            "mouse": mouse, "group": group, "condition": cond_name,
            "fold": suffix.lstrip("_") if suffix else "full",
            "spearman_rho": rho, "spearman_p": pval,
            "slope": coeffs[0], "n_frames": int(fm.sum()),
        }

    # ---- iterate mice / conditions / folds ------------------------------
    all_stats = []
    for mouse, mres in all_results.items():
        group = mres.get("group", "NA")
        conditions = mres.get("conditions", {})
        for cond_name, cres in conditions.items():
            if not cres.get("ok", False):
                continue

            LT = _get_session_for_condition(cond_name, mouse, LT1_dict, LT2_dict)

            # Within-session folds
            for split_key in ("train_to_test",):
                sub = cres.get(split_key)
                if isinstance(sub, dict) and sub.get("ok", False):
                    row = _plot_interarm(mouse, group, cond_name,
                                         sub["true_pos_1d"], sub["decoded_pos_1d"],
                                         LT, suffix=f"_{split_key}")
                    if row is not None:
                        all_stats.append(row)

            # Cross-session (top-level keys)
            if "true_pos_1d" in cres and "train_to_test" not in cres:
                row = _plot_interarm(mouse, group, cond_name,
                                     cres["true_pos_1d"], cres["decoded_pos_1d"],
                                     LT)
                if row is not None:
                    all_stats.append(row)

    print(f"[LT-INTERARM]  Saved error-vs-interarm plots → {save_dir}")
    return all_stats


def plot_decoder_interarm_aggregate_LT(
    interarm_stats,
    *,
    PLOTS_DIR,
    decoder_tag="S_1D",
    auto_close=True,
):
    """Aggregate inter-arm-distance vs decoder-error correlations across mice.

    Takes the list of per-mouse dicts returned by
    ``plot_decoder_error_vs_interarm_LT`` and produces:

    * CSV of all per-mouse Spearman ρ values
    * One-sample Wilcoxon signed-rank test of ρ ≠ 0 per group × condition
    * Dot-plot with group means ± SEM and individual mouse dots
    """
    from scipy.stats import wilcoxon as sp_wilcoxon

    if not interarm_stats:
        print("[LT-INTERARM-AGG]  No per-mouse stats to aggregate.")
        return

    save_dir = os.path.join(PLOTS_DIR, "decoder_interarm")
    os.makedirs(save_dir, exist_ok=True)

    df = pd.DataFrame(interarm_stats)

    # ---- Average across within-session folds per mouse/condition ---------
    # (LOLO result → single ρ per mouse/condition)
    df_agg = (
        df.groupby(["mouse", "group", "condition"], as_index=False)
        .agg(
            rho_mean=("spearman_rho", "mean"),
            slope_mean=("slope", "mean"),
            n_frames_total=("n_frames", "sum"),
        )
    )

    csv_path = os.path.join(save_dir, f"{decoder_tag}_interarm_per_mouse.csv")
    df_agg.to_csv(csv_path, index=False)
    print(f"[LT-INTERARM-AGG]  Per-mouse CSV → {csv_path}")

    # ---- One-sample Wilcoxon signed-rank: ρ ≠ 0 -------------------------
    groups = sorted(df_agg["group"].unique())
    _preferred_cond_order = ["within_LT1", "within_LT2", "LT1_to_LT2"]
    _data_conds = set(df_agg["condition"].unique())
    conditions = [c for c in _preferred_cond_order if c in _data_conds]
    conditions += sorted(_data_conds - set(conditions))

    test_rows = []
    for grp in groups:
        for cond in conditions:
            sub = df_agg[(df_agg["group"] == grp) & (df_agg["condition"] == cond)]
            rhos = sub["rho_mean"].dropna().values
            n = len(rhos)
            med = float(np.median(rhos)) if n else np.nan
            mn = float(np.mean(rhos)) if n else np.nan
            sem = float(np.std(rhos, ddof=1) / np.sqrt(n)) if n > 1 else np.nan
            if n >= 5:
                try:
                    W, p = sp_wilcoxon(rhos)
                except ValueError:
                    W, p = np.nan, np.nan
            else:
                W, p = np.nan, np.nan
            sig = ""
            if np.isfinite(p):
                sig = ("***" if p < 0.001 else
                       ("**" if p < 0.01 else
                        ("*" if p < 0.05 else
                         (f"p={p:.3f}" if p < 0.10 else ""))))
            test_rows.append({
                "group": grp, "condition": cond, "n_mice": n,
                "median_rho": round(med, 4), "mean_rho": round(mn, 4),
                "sem_rho": round(sem, 4) if np.isfinite(sem) else "",
                "W": round(W, 3) if np.isfinite(W) else "",
                "p": round(p, 5) if np.isfinite(p) else "",
                "significant": sig,
            })

    df_tests = pd.DataFrame(test_rows)
    csv_tests = os.path.join(save_dir, f"{decoder_tag}_interarm_wilcoxon.csv")
    df_tests.to_csv(csv_tests, index=False)
    print(f"\n=== Wilcoxon signed-rank: Spearman ρ ≠ 0 (error vs inter-arm dist) ===")
    print(df_tests.to_string(index=False))

    # ---- Dot-plot: mean ρ ± SEM per group × condition --------------------
    _rcparams = {
        "font.size": 14,
        "axes.labelsize": 16,
        "axes.titlesize": 16,
        "xtick.labelsize": 12,
        "ytick.labelsize": 12,
    }

    # Colour per group
    group_colours = {}
    _palette = ["#1f77b4", "#ff7f0e", "#2ca02c", "#d62728", "#9467bd", "#8c564b"]
    for i, g in enumerate(groups):
        group_colours[g] = _palette[i % len(_palette)]

    n_conds = len(conditions)
    n_groups = len(groups)
    if n_conds == 0:
        return

    bar_width = 0.35
    with plt.rc_context(_rcparams):
        fig, ax = plt.subplots(figsize=(max(6, n_conds * 2.5), 6), dpi=150)

        x_base = np.arange(n_conds)
        offsets = np.linspace(-bar_width * (n_groups - 1) / 2,
                              bar_width * (n_groups - 1) / 2, n_groups)

        for gi, grp in enumerate(groups):
            means, sems, xs_all, ys_all = [], [], [], []
            for ci, cond in enumerate(conditions):
                sub = df_agg[(df_agg["group"] == grp) & (df_agg["condition"] == cond)]
                rhos = sub["rho_mean"].dropna().values
                mn = float(np.mean(rhos)) if len(rhos) else 0
                se = float(np.std(rhos, ddof=1) / np.sqrt(len(rhos))) if len(rhos) > 1 else 0
                means.append(mn)
                sems.append(se)
                xs_all.extend([x_base[ci] + offsets[gi]] * len(rhos))
                ys_all.extend(rhos.tolist())

            xs_bar = x_base + offsets[gi]
            ax.bar(xs_bar, means, width=bar_width * 0.85, yerr=sems,
                   color=group_colours[grp], alpha=0.35, edgecolor=group_colours[grp],
                   capsize=4, label=grp, zorder=2)
            # Individual mouse dots
            ax.scatter(xs_all, ys_all, color=group_colours[grp],
                       edgecolors="k", linewidths=0.5, s=40, zorder=3)

        ax.axhline(0, color="grey", linestyle="--", linewidth=1, zorder=1)
        ax.set_xticks(x_base)
        ax.set_xticklabels(conditions)
        ax.set_ylabel("Spearman ρ  (decoder error vs inter-arm dist)")
        ax.set_title(f"Inter-arm distance correlation [{decoder_tag}]")
        ax.legend(loc="best", fontsize=10)

        # Annotate significance stars
        for ci, cond in enumerate(conditions):
            for gi, grp in enumerate(groups):
                row = df_tests[(df_tests["group"] == grp) & (df_tests["condition"] == cond)]
                if row.empty:
                    continue
                sig = row.iloc[0]["significant"]
                if sig and not sig.startswith("p="):
                    sub = df_agg[(df_agg["group"] == grp) & (df_agg["condition"] == cond)]
                    rhos = sub["rho_mean"].dropna().values
                    if len(rhos):
                        y_top = max(rhos) + 0.03
                        ax.text(x_base[ci] + offsets[gi], y_top, sig,
                                ha="center", va="bottom", fontsize=11, fontweight="bold")

        fig.tight_layout()
        fig.savefig(
            os.path.join(save_dir, f"{decoder_tag}_interarm_aggregate.png"),
            dpi=300, bbox_inches="tight",
        )
        if auto_close:
            plt.close(fig)

    print(f"[LT-INTERARM-AGG]  Aggregate plot → {save_dir}")


# ---- 5-zone decoder error analysis -------------------------------------

def _compute_5_zone_boundaries(LT, cm_per_px=None):
    """Compute 5-zone boundaries on the U-shaped linear track.

    Uses Y-percentile arm detection (same logic as _compute_turn_lines_safe
    in caban.analysis.py) to find the junction region, then splits each
    arm at its midpoint.

    Returns
    -------
    list of (label, s_min_cm, s_max_cm)  — 5 tuples, or None on failure.
    Also returns dict with 'turn1_1d', 'turn2_1d', 'L_cm' for reference.
    """
    if cm_per_px is None:
        cm_per_px = float(_LT_1D_CM_PER_PX)

    loc_1d_px = getattr(LT, "miniscope_loc_1d_px", None)
    if loc_1d_px is None:
        return None, {}

    loc_X = np.asarray(LT.loc_X_miniscope_smooth, float)
    loc_Y = np.asarray(LT.loc_Y_miniscope_smooth, float)
    loc_1d = np.asarray(loc_1d_px, float) * cm_per_px

    # ---- replicate _compute_turn_lines_safe logic ----
    valid = np.isfinite(loc_X) & np.isfinite(loc_Y) & np.isfinite(loc_1d)
    if np.sum(valid) < 50:
        return None, {}

    xv, yv, p1dv = loc_X[valid], loc_Y[valid], loc_1d[valid]
    x_min, x_max = np.nanmin(xv), np.nanmax(xv)
    if (x_max - x_min) < 1e-6:
        return None, {}

    x_thresh = x_min + 0.8 * (x_max - x_min)
    y_lo_arm = np.nanpercentile(yv, 40)
    y_hi_arm = np.nanpercentile(yv, 60)
    mask_top = yv >= y_hi_arm
    mask_bot = yv <= y_lo_arm

    turn1_1d = turn2_1d = None
    for bf in (0.02, 0.04, 0.06, 0.08, 0.10, 0.14, 0.18):
        x_band = bf * (x_max - x_min)
        mask_xband = np.abs(xv - x_thresh) <= x_band
        n_top = int(np.sum(mask_top & mask_xband))
        n_bot = int(np.sum(mask_bot & mask_xband))
        if n_top >= 10 and n_bot >= 10:
            turn_top = float(np.nanmedian(p1dv[mask_top & mask_xband]))
            turn_bot = float(np.nanmedian(p1dv[mask_bot & mask_xband]))
            turns = np.sort([turn_top, turn_bot])
            turn1_1d, turn2_1d = float(turns[0]), float(turns[1])
            break

    if turn1_1d is None:
        return None, {}

    # Total track length in cm
    centerline = getattr(LT, "centerline_miniscope", None)
    if centerline is not None:
        cl = np.asarray(centerline, float)
        diffs = np.diff(cl, axis=0)
        L_cm = float(np.sqrt((diffs ** 2).sum(axis=1)).sum()) * cm_per_px
    else:
        L_cm = float(np.nanmax(loc_1d))

    # ---- Determine which arm is upper vs lower ----
    # Arm A = [0, turn1_1d), Arm B = (turn2_1d, L]
    mask_armA = (p1dv < turn1_1d)
    mask_armB = (p1dv > turn2_1d)
    y_mean_A = float(np.nanmean(yv[mask_armA])) if np.any(mask_armA) else 0
    y_mean_B = float(np.nanmean(yv[mask_armB])) if np.any(mask_armB) else 0

    # Higher Y = upper arm (in behavcam pixel coords, Y typically increases downward
    # but the user's plots show Y increasing upward — use raw means and label accordingly)
    if y_mean_A >= y_mean_B:
        # Arm A is upper, Arm B is lower
        arm_A_label_end, arm_A_label_horiz = "Upper end", "Upper horiz"
        arm_B_label_horiz, arm_B_label_end = "Lower horiz", "Lower end"
    else:
        # Arm B is upper, Arm A is lower
        arm_A_label_end, arm_A_label_horiz = "Lower end", "Lower horiz"
        arm_B_label_horiz, arm_B_label_end = "Upper horiz", "Upper end"

    # Split each arm at midpoint of its arc-length range
    arm_A_mid = turn1_1d / 2.0
    arm_B_mid = turn2_1d + (L_cm - turn2_1d) / 2.0

    zones = [
        (arm_A_label_end,   0.0,       arm_A_mid),
        (arm_A_label_horiz, arm_A_mid, turn1_1d),
        ("Junction",        turn1_1d,  turn2_1d),
        (arm_B_label_horiz, turn2_1d,  arm_B_mid),
        (arm_B_label_end,   arm_B_mid, L_cm),
    ]

    info = {"turn1_1d": turn1_1d, "turn2_1d": turn2_1d, "L_cm": L_cm,
            "y_mean_A": y_mean_A, "y_mean_B": y_mean_B}
    return zones, info


def compute_zone_decoder_errors(
    all_results,
    LT1_dict,
    LT2_dict,
    *,
    mouse_groups=None,
    pct_threshold: float = 15.0,
):
    """Compute decoder error stats per 5-zone segment for every mouse/condition.

    Returns a DataFrame with columns:
        mouse, group, condition, zone_label, mean_err, median_err,
        pct_correct, n_frames
    where *pct_correct* = fraction of frames with |error| < *pct_threshold*.
    """
    if mouse_groups is None:
        mouse_groups = {}

    rows = []

    for mouse, mres in all_results.items():
        group = mres.get("group", "NA")
        conditions = mres.get("conditions", {})
        for cond_name, cres in conditions.items():
            if not cres.get("ok", False):
                continue

            LT = _get_session_for_condition(cond_name, mouse, LT1_dict, LT2_dict)
            if LT is None:
                continue

            zones, zinfo = _compute_5_zone_boundaries(LT)
            if zones is None:
                continue

            # Collect true/decoded from LOLO result or top-level
            pairs = []
            for split_key in ("train_to_test",):
                sub = cres.get(split_key)
                if isinstance(sub, dict) and sub.get("ok", False):
                    pairs.append((sub["true_pos_1d"], sub["decoded_pos_1d"]))
            if "true_pos_1d" in cres and "train_to_test" not in cres:
                pairs.append((cres["true_pos_1d"], cres["decoded_pos_1d"]))

            if not pairs:
                continue

            # Pool across folds
            true_all = np.concatenate([np.asarray(t, float) for t, _ in pairs])
            dec_all  = np.concatenate([np.asarray(d, float) for _, d in pairs])
            abs_err  = np.abs(dec_all - true_all)
            fm = np.isfinite(abs_err) & np.isfinite(true_all)

            for zlabel, s_min, s_max in zones:
                zmask = fm & (true_all >= s_min) & (true_all < s_max)
                n = int(zmask.sum())
                if n > 0:
                    errs = abs_err[zmask]
                    me = float(np.nanmean(errs))
                    md = float(np.nanmedian(errs))
                    pct = float(np.nanmean(errs < pct_threshold))
                else:
                    me = md = pct = np.nan
                rows.append({
                    "mouse": mouse, "group": group, "condition": cond_name,
                    "zone_label": zlabel, "mean_err": me, "median_err": md,
                    "pct_correct": pct, "n_frames": n,
                })

    return pd.DataFrame(rows)


# ====================================================================
#  Zone Cross-Registration Analysis Suite  (Phases 1–5)
# ====================================================================

try:
    from tqdm.auto import tqdm as _tqdm_impl
except ImportError:
    _tqdm_impl = None


def _tqdm_wrap(iterable, **kwargs):
    """Wrap *iterable* with tqdm if available, else return as‑is."""
    if _tqdm_impl is not None:
        return _tqdm_impl(iterable, **kwargs)
    return iterable


def _zone_pct_correct_from_decoded(true_pos, decoded_pos, zones, pct_threshold):
    """Per‑zone and collapsed pct_correct from decoded positions.

    Returns dict  ``{zone_label: float, ..., 'Arms': float, 'Junction': float}``.
    """
    true_pos = np.asarray(true_pos, float)
    decoded_pos = np.asarray(decoded_pos, float)
    abs_err = np.abs(decoded_pos - true_pos)
    fm = np.isfinite(abs_err) & np.isfinite(true_pos)

    result = {}
    arm_err, arm_cnt = [], 0
    junc_err, junc_cnt = [], 0

    for zlabel, s_min, s_max in zones:
        zmask = fm & (true_pos >= s_min) & (true_pos < s_max)
        n = int(zmask.sum())
        if n > 0:
            errs = abs_err[zmask]
            pct = float(np.nanmean(errs < pct_threshold))
            result[zlabel] = pct
            if "horiz" in zlabel.lower():
                arm_err.append(errs)
                arm_cnt += n
            elif "junction" in zlabel.lower():
                junc_err.append(errs)
                junc_cnt += n
        else:
            result[zlabel] = np.nan

    if arm_cnt > 0:
        all_arm = np.concatenate(arm_err)
        result["Arms"] = float(np.nanmean(all_arm < pct_threshold))
    else:
        result["Arms"] = np.nan
    if junc_cnt > 0:
        all_junc = np.concatenate(junc_err)
        result["Junction"] = float(np.nanmean(all_junc < pct_threshold))
    else:
        result["Junction"] = np.nan

    return result


def _extract_decoded_positions(result):
    """Extract (true_pos_1d, decoded_pos_1d) from a PVT decoder result."""
    sub = result.get("train_to_test")
    if isinstance(sub, dict) and sub.get("ok", False):
        return sub.get("true_pos_1d"), sub.get("decoded_pos_1d")
    if "true_pos_1d" in result:
        return result["true_pos_1d"], result["decoded_pos_1d"]
    return None, None


def _cross_session_decode_PF2D_raw(
    S_train, S_test, LT_train, LT_test, *,
    train_unit_ids,
    time_bin_frames=15,
    use_speed=True, min_speed=2.0,
    use_posterior_mean=True,
    use_continuity_constraint=True,
    continuity_sigma_k=35.0,
    continuity_speed_ref=20.0,
    continuity_exp=1.0,
    continuity_sigma_min=10.0,
    continuity_sigma_max=30.0,
    continuity_sigma_default=18.0,
):
    """Minimal PF_2D cross‑session decode with explicit S matrices.

    Uses the place‑field model on *LT_train* and projects decoded
    2‑D positions onto the *LT_test* centerline.

    Parameters
    ----------
    S_train : ndarray
        Unused (kept for call-site compatibility). Training tuning
        curves come from ``LT_train.fm``.
    S_test : ndarray, shape (N_cells, T)
        Activity matrix for test session (only PF-cell rows are used).
    train_unit_ids : list[int]
        Unit IDs (matching ``fm.cells``) for each row of *S_train* / *S_test*.

    Returns ``(true_pos_1d, decoded_pos_1d)`` or ``(None, None)`` on failure.
    """
    has_fm = hasattr(LT_train, "fm") and LT_train.fm is not None
    has_cl = (hasattr(LT_test, "centerline_miniscope")
              and LT_test.centerline_miniscope is not None)
    if not has_fm or not has_cl:
        return None, None

    fm = LT_train.fm
    fm_cells = list(fm.cells)

    # Identify place‑field cell indices inside fm
    if fm.sig_responses is not None:
        pf_idx = [i for i, c in enumerate(fm_cells) if c in fm.sig_responses]
    else:
        pf_idx = list(range(len(fm_cells)))
    if len(pf_idx) == 0:
        return None, None

    # Map PF cells → rows in S_train/S_test via train_unit_ids
    uid_to_row = {int(u): r for r, u in enumerate(train_unit_ids)}
    pf_idx_used = []
    mapped_rows = []
    for pi in pf_idx:
        cid = fm_cells[pi]
        if cid in uid_to_row:
            pf_idx_used.append(pi)
            mapped_rows.append(uid_to_row[cid])
    if len(mapped_rows) == 0:
        return None, None

    T_test = min(LT_test.S.shape[1], S_test.shape[1])
    dt = _infer_dt_sec(LT_train)
    _cm = float(_LT_1D_CM_PER_PX)
    _bw_cm = float(fm.loc.bin_width) * _cm

    test_mask, _ = _build_all_laps_mask(LT_test, use_speed=use_speed, min_speed=min_speed)
    if test_mask is None:
        return None, None
    test_mask = test_mask[:T_test]
    if test_mask.sum() < 10 * time_bin_frames:
        return None, None

    # Subset of S_test for PF cells only
    S_test_pf = S_test[mapped_rows, :T_test]

    # Fit decoder from place fields (training tuning curves)
    fm.check_fluorescence_map_occup()
    dec = BayesianDecoder2D_PF(time_bin_frames=time_bin_frames)
    dec.fit_from_place_fields(
        fm.pf, fm.fluorescence_map_occup, fm.loc.occupancy,
        fm_cells=fm_cells, cell_indices=pf_idx_used,
        dt_sec=dt, bin_width=_bw_cm,
    )

    # Decode in 2‑D
    loc_X_te = np.asarray(LT_test.loc_X_miniscope_smooth, float)[:T_test] * _cm
    loc_Y_te = np.asarray(LT_test.loc_Y_miniscope_smooth, float)[:T_test] * _cm
    speed_test = _get_miniscope_velocity_vector(LT_test, T_test)

    out2d = dec.decode(
        S_test_pf, loc_X_te, loc_Y_te, test_mask,
        use_posterior_mean=use_posterior_mean,
        use_continuity_constraint=use_continuity_constraint,
        speed_vec=speed_test,
        continuity_sigma_k=continuity_sigma_k,
        continuity_speed_ref=continuity_speed_ref,
        continuity_exp=continuity_exp,
        continuity_sigma_min=continuity_sigma_min,
        continuity_sigma_max=continuity_sigma_max,
        continuity_sigma_default=continuity_sigma_default,
        save_posterior=False,
    )
    if out2d["decoded_x"].size == 0:
        return None, None

    # Project 2‑D → 1‑D on test centerline
    _cl_cm = np.asarray(LT_test.centerline_miniscope, float) * _cm
    dec_1d = _project_decoded_2d_to_1d(out2d["decoded_x"], out2d["decoded_y"], _cl_cm)
    true_1d = _project_decoded_2d_to_1d(out2d["true_x"], out2d["true_y"], _cl_cm)
    return true_1d, dec_1d


# -------------------------------------------------------------------
#  Phase 1 — N‑matched random subsampling control
# -------------------------------------------------------------------

def run_zone_decoder_subsampling_control(
    LT1_dict,
    LT2_dict,
    *,
    n_repeats: int = 100,
    pct_threshold: float = 15.0,
    seed: int = 42,
    n_pos_bins: int = 60,
    time_bin_frames: int = 15,
    use_speed: bool = True,
    min_speed: float = 2.0,
    use_z_score: str = "none",
    use_posterior_mean: bool = True,
    use_continuity_constraint: bool = True,
    continuity_sigma_k: float = 35.0,
    continuity_speed_ref: float = 20.0,
    continuity_exp: float = 1.0,
    continuity_sigma_min: float = 10.0,
    continuity_sigma_max: float = 30.0,
    continuity_sigma_default: float = 18.0,
    mouse_groups: dict = None,
    PLOTS_DIR: str = "",
    NPY_SAVE_DIR: str = "",
    load_cached: bool = True,
    auto_close: bool = True,
):
    """Phase 1: N-matched random subsampling null for zone pct_correct.

    For every mouse the decoder is run with the **actual** LT1+LT2+TFC
    cell set (the "observed" value) and then *n_repeats* times with a
    random subsample of the **same size** drawn from the larger LT1+LT2
    set.  Zone pct_correct is compared.

    Uses PF_2D (place-field Bayesian) for within-session and cross-session.
    """
    if mouse_groups is None:
        mouse_groups = {}

    save_dir = os.path.join(PLOTS_DIR, "zone_crossreg_analysis", "phase1_subsampling")
    os.makedirs(save_dir, exist_ok=True)
    _copy_analysis_methods_template("zone_crossreg_phase1_subsampling_methods.txt", save_dir)

    # ---- Per-mouse cache setup ----
    mice = sorted(set(LT1_dict.keys()) & set(LT2_dict.keys()))
    collapsed_zones = ["Arms", "Junction"]
    conditions = ["within_LT1", "within_LT2", "LT1_to_LT2"]

    cell_count_rows = []
    null_rows = []       # per repeat
    observed_rows = []   # single per mouse

    for mi, mouse in enumerate(mice):
        LT1 = LT1_dict[mouse]
        LT2 = LT2_dict[mouse]
        group = mouse_groups.get(mouse, "NA")

        # ---- Per-mouse cache check ----
        _mouse_cache = {
            "counts": f"phase1_{mouse}_counts.csv",
            "null":   f"phase1_{mouse}_null.csv",
            "obs":    f"phase1_{mouse}_obs.csv",
        }
        if load_cached and NPY_SAVE_DIR:
            _all_exist = all(
                os.path.isfile(os.path.join(NPY_SAVE_DIR, fn))
                for fn in _mouse_cache.values()
            )
            if _all_exist:
                _mc = pd.read_csv(os.path.join(NPY_SAVE_DIR, _mouse_cache["counts"]))
                _mn = pd.read_csv(os.path.join(NPY_SAVE_DIR, _mouse_cache["null"]))
                _mo = pd.read_csv(os.path.join(NPY_SAVE_DIR, _mouse_cache["obs"]))
                cell_count_rows.extend(_mc.to_dict("records"))
                null_rows.extend(_mn.to_dict("records"))
                observed_rows.extend(_mo.to_dict("records"))
                print(f"[Phase1] {mouse} — loaded from cache "
                      f"(counts={len(_mc)}, null={len(_mn)}, obs={len(_mo)})")
                continue

        t0 = time.time()

        # ---- Retrieve ALL LT1+LT2 cells (superset) and triple (exact) ----
        # get_cells_for_pair returns all cells in *at least* LT1+LT2
        # (includes pair-only AND triple cells).  get_mappings_cells with
        # exact match would return pair-only, which can be < triple.
        df_all_pair = LT1.crossreg.get_cells_for_pair("LT1", "LT2")
        pair_uids_LT1 = df_all_pair[LT1.session_group].astype(float).astype(int).values
        pair_uids_LT2 = df_all_pair[LT2.session_group].astype(float).astype(int).values
        S_pair_LT1, _ = get_mapped_S_from_unit_ids(LT1, pair_uids_LT1.tolist())
        S_pair_LT2, _ = get_mapped_S_from_unit_ids(LT2, pair_uids_LT2.tolist())

        df_triple = LT1.crossreg.get_mappings_cells(mapping_type="LT1+LT2+TFC_cond")
        triple_uids_LT1 = df_triple[LT1.session_group].astype(float).astype(int).values
        triple_uids_LT2 = df_triple[LT2.session_group].astype(float).astype(int).values
        S_triple_LT1, _ = get_mapped_S_from_unit_ids(LT1, triple_uids_LT1.tolist())
        S_triple_LT2, _ = get_mapped_S_from_unit_ids(LT2, triple_uids_LT2.tolist())

        N_pair = S_pair_LT1.shape[0]
        N_triple = S_triple_LT1.shape[0]
        assert N_pair > 0 and N_triple > 0 and N_triple <= N_pair, \
            f"[{mouse}] Bad cell counts: N_pair={N_pair}, N_triple={N_triple}"

        cell_count_rows.append({
            "mouse": mouse, "group": group,
            "N_LT1_LT2": N_pair, "N_LT1_LT2_TFC": N_triple,
            "N_excluded": N_pair - N_triple,
            "pct_retained": round(100.0 * N_triple / N_pair, 1),
        })

        print(f"\n[Phase1] {mouse} ({group}) — "
              f"N_pair={N_pair}, N_triple={N_triple} ...")

        # ---- Zone boundaries (use LT2 for cross-session test side) ----
        zones_LT1, _ = _compute_5_zone_boundaries(LT1)
        zones_LT2, _ = _compute_5_zone_boundaries(LT2)
        assert zones_LT1 is not None and zones_LT2 is not None, \
            f"[{mouse}] Failed to compute zone boundaries"

        # Common decoder kwargs — threaded through to all decode calls
        _dec_kw = dict(
            n_pos_bins=n_pos_bins, time_bin_frames=time_bin_frames,
            use_speed=use_speed, min_speed=min_speed,
            use_z_score=use_z_score,
            use_posterior_mean=use_posterior_mean,
            use_continuity_constraint=use_continuity_constraint,
            continuity_sigma_k=continuity_sigma_k,
            continuity_speed_ref=continuity_speed_ref,
            continuity_exp=continuity_exp,
            continuity_sigma_min=continuity_sigma_min,
            continuity_sigma_max=continuity_sigma_max,
            continuity_sigma_default=continuity_sigma_default,
        )
        _cross_kw = dict(
            time_bin_frames=time_bin_frames,
            use_speed=use_speed, min_speed=min_speed,
            use_posterior_mean=use_posterior_mean,
            use_continuity_constraint=use_continuity_constraint,
            continuity_sigma_k=continuity_sigma_k,
            continuity_speed_ref=continuity_speed_ref,
            continuity_exp=continuity_exp,
            continuity_sigma_min=continuity_sigma_min,
            continuity_sigma_max=continuity_sigma_max,
            continuity_sigma_default=continuity_sigma_default,
        )

        # ---- Observed (triple-set) decoding ----
        # NOTE: pass original unit IDs (triple_uids_*), NOT position indices
        #       from get_mapped_S_from_unit_ids, because PF_2D needs unit IDs
        #       to match against fm.cells.
        obs_pct = {}  # condition → {zone → pct}
        # within LT1
        r1 = decode_within_LT_position_vs_time(
            LT1, "PF_2D", S_override=S_triple_LT1,
            S_override_unit_ids=triple_uids_LT1.tolist(),
            **_dec_kw)
        if not r1.get("ok"):
            print(f"  WARNING [{mouse}] within_LT1 observed decode FAILED: "
                  f"{r1.get('reason', '?')} — recording NaN")
        tp, dp = _extract_decoded_positions(r1) if r1.get("ok") else (None, None)
        obs_pct["within_LT1"] = _zone_pct_correct_from_decoded(
            tp, dp, zones_LT1, pct_threshold) if tp is not None else {}
        # within LT2
        r2 = decode_within_LT_position_vs_time(
            LT2, "PF_2D", S_override=S_triple_LT2,
            S_override_unit_ids=triple_uids_LT2.tolist(),
            **_dec_kw)
        if not r2.get("ok"):
            print(f"  WARNING [{mouse}] within_LT2 observed decode FAILED: "
                  f"{r2.get('reason', '?')} — recording NaN")
        tp, dp = _extract_decoded_positions(r2) if r2.get("ok") else (None, None)
        obs_pct["within_LT2"] = _zone_pct_correct_from_decoded(
            tp, dp, zones_LT2, pct_threshold) if tp is not None else {}
        # LT1 → LT2
        tp, dp = _cross_session_decode_PF2D_raw(
            S_triple_LT1, S_triple_LT2, LT1, LT2,
            train_unit_ids=triple_uids_LT1.tolist(),
            **_cross_kw)
        if tp is None:
            print(f"  WARNING [{mouse}] LT1→LT2 observed cross-session decode FAILED "
                  f"— recording NaN")
        obs_pct["LT1_to_LT2"] = _zone_pct_correct_from_decoded(
            tp, dp, zones_LT2, pct_threshold) if tp is not None else {}

        for cond in conditions:
            for zone in collapsed_zones:
                val = obs_pct.get(cond, {}).get(zone, np.nan)
                observed_rows.append({
                    "mouse": mouse, "group": group,
                    "condition": cond, "zone": zone,
                    "pct_correct": val,
                })

        # ---- Null distribution (random subsamples of size N_triple) ----
        rng = default_rng(seed + hash(mouse) % (2**31))

        desc = f"  {mouse} ({group}) subsampling"
        for rep in _tqdm_wrap(range(n_repeats), desc=desc, total=n_repeats,
                              leave=True, ncols=90):
            idx = np.sort(rng.choice(N_pair, size=N_triple, replace=False))
            S_sub_LT1 = S_pair_LT1[idx]
            S_sub_LT2 = S_pair_LT2[idx]
            sub_uids_LT1 = pair_uids_LT1[idx].tolist()
            sub_uids_LT2 = pair_uids_LT2[idx].tolist()

            null_pct = {}  # cond → {zone → pct}
            # within LT1
            r1s = decode_within_LT_position_vs_time(
                LT1, "PF_2D", S_override=S_sub_LT1,
                S_override_unit_ids=sub_uids_LT1,
                **_dec_kw)
            tp, dp = _extract_decoded_positions(r1s) if r1s.get("ok") else (None, None)
            null_pct["within_LT1"] = _zone_pct_correct_from_decoded(
                tp, dp, zones_LT1, pct_threshold) if tp is not None else {}
            # within LT2
            r2s = decode_within_LT_position_vs_time(
                LT2, "PF_2D", S_override=S_sub_LT2,
                S_override_unit_ids=sub_uids_LT2,
                **_dec_kw)
            tp, dp = _extract_decoded_positions(r2s) if r2s.get("ok") else (None, None)
            null_pct["within_LT2"] = _zone_pct_correct_from_decoded(
                tp, dp, zones_LT2, pct_threshold) if tp is not None else {}
            # LT1 → LT2
            tp, dp = _cross_session_decode_PF2D_raw(
                S_sub_LT1, S_sub_LT2, LT1, LT2,
                train_unit_ids=sub_uids_LT1,
                **_cross_kw)
            null_pct["LT1_to_LT2"] = _zone_pct_correct_from_decoded(
                tp, dp, zones_LT2, pct_threshold) if tp is not None else {}

            for cond in conditions:
                for zone in collapsed_zones:
                    val = null_pct.get(cond, {}).get(zone, np.nan)
                    null_rows.append({
                        "mouse": mouse, "group": group,
                        "condition": cond, "zone": zone,
                        "rep": rep, "pct_correct": val,
                    })

        elapsed = time.time() - t0
        print(f"  {mouse} done in {elapsed:.1f}s")

        # ---- Per-mouse cache save ----
        if NPY_SAVE_DIR:
            os.makedirs(NPY_SAVE_DIR, exist_ok=True)
            _m_counts = [r for r in cell_count_rows if r["mouse"] == mouse]
            _m_null   = [r for r in null_rows if r["mouse"] == mouse]
            _m_obs    = [r for r in observed_rows if r["mouse"] == mouse]
            pd.DataFrame(_m_counts).to_csv(
                os.path.join(NPY_SAVE_DIR, _mouse_cache["counts"]), index=False)
            pd.DataFrame(_m_null).to_csv(
                os.path.join(NPY_SAVE_DIR, _mouse_cache["null"]), index=False)
            pd.DataFrame(_m_obs).to_csv(
                os.path.join(NPY_SAVE_DIR, _mouse_cache["obs"]), index=False)
            print(f"  {mouse} cached to {NPY_SAVE_DIR}")

    # ---- Build combined DataFrames ----
    df_counts = pd.DataFrame(cell_count_rows)
    df_null = pd.DataFrame(null_rows)
    df_obs = pd.DataFrame(observed_rows)

    # ---- From here: shared path (cached or fresh) ----

    if df_counts.empty:
        print("[Phase1] No mice processed — nothing to plot.")
        return {"df_counts": df_counts, "df_null": df_null, "df_obs": df_obs}

    # ---- Compute summary (percentile rank, p-value) ----
    summary_rows = []
    for _, obs_row in df_obs.iterrows():
        mouse = obs_row["mouse"]
        group = obs_row["group"]
        cond = obs_row["condition"]
        zone = obs_row["zone"]
        obs_val = obs_row["pct_correct"]
        sub = df_null[(df_null["mouse"] == mouse) &
                      (df_null["condition"] == cond) &
                      (df_null["zone"] == zone)]
        null_vals = sub["pct_correct"].dropna().values
        if len(null_vals) == 0 or not np.isfinite(obs_val):
            continue
        prank = float(np.mean(null_vals <= obs_val)) * 100.0
        p_val = float(np.mean(null_vals >= obs_val))
        summary_rows.append({
            "mouse": mouse, "group": group,
            "condition": cond, "zone": zone,
            "observed": obs_val,
            "null_mean": float(np.nanmean(null_vals)),
            "null_std": float(np.nanstd(null_vals)),
            "percentile_rank": prank,
            "p_value": p_val,
            "n_repeats": len(null_vals),
        })
    df_summary = pd.DataFrame(summary_rows)

    # ---- Save CSVs ----
    df_counts.to_csv(os.path.join(save_dir, "cell_counts_table.csv"), index=False)
    df_null.to_csv(os.path.join(save_dir, "subsampling_null.csv"), index=False)
    df_obs.to_csv(os.path.join(save_dir, "subsampling_observed.csv"), index=False)
    df_summary.to_csv(os.path.join(save_dir, "subsampling_summary.csv"), index=False)
    print(f"[Phase1] CSVs saved to {save_dir}")

    # ---- Plots ----
    _plot_phase1_cell_counts(df_counts, save_dir, auto_close=auto_close)
    _plot_phase1_null_vs_observed(df_null, df_obs, df_summary, save_dir,
                                  auto_close=auto_close)
    _plot_phase1_null_vs_observed_aggregate(df_null, df_obs, save_dir,
                                            auto_close=auto_close)
    _plot_phase1_null_vs_observed_aggregate_boxplot(df_null, df_obs, save_dir,
                                                    auto_close=auto_close)
    _plot_phase1_percentile_rank(df_null, df_obs, save_dir,
                                 auto_close=auto_close)
    _plot_phase1_summary_heatmap(df_summary, save_dir, auto_close=auto_close)

    # ---- Statistical analysis of group differences ----
    run_phase1_group_stats(df_summary, save_dir, auto_close=auto_close)

    return {"df_counts": df_counts, "df_null": df_null, "df_obs": df_obs,
            "df_summary": df_summary}


def _plot_phase1_cell_counts(df_counts, save_dir, *, auto_close=True):
    """Grouped bar: N_cells per group × crossreg type, per-mouse dots."""
    groups = GROUPS
    col = _PAPER_COLORS
    fig, ax = plt.subplots(figsize=(5, 4), dpi=160)
    x_base = np.arange(len(groups))
    width = 0.35

    for ci, (label, col_name) in enumerate([("LT1+LT2", "N_LT1_LT2"),
                                             ("LT1+LT2+TFC", "N_LT1_LT2_TFC")]):
        offset = (ci - 0.5) * width
        means, sems = [], []
        for g in groups:
            vals = df_counts.loc[df_counts["group"] == g, col_name].values
            means.append(np.nanmean(vals) if len(vals) > 0 else 0)
            sems.append(np.nanstd(vals) / max(1, np.sqrt(len(vals))) if len(vals) > 0 else 0)

        ax.bar(x_base + offset, means, width=width, yerr=sems,
               capsize=3, label=label,
               color=["#888888", "#5b8db8"][ci], alpha=0.6,
               edgecolor="black", linewidth=0.5)

        # Per‑mouse scatter
        for gi, g in enumerate(groups):
            vals = df_counts.loc[df_counts["group"] == g, col_name].values
            jitter = (np.random.default_rng(42).random(len(vals)) - 0.5) * width * 0.4
            ax.scatter(np.full(len(vals), x_base[gi] + offset) + jitter,
                       vals, s=18, zorder=5, color="k", alpha=0.5)

    ax.set_xticks(x_base)
    ax.set_xticklabels([GROUP_LABELS.get(g, g) for g in groups])
    ax.set_ylabel("Number of cells")
    ax.set_title("Cell counts: LT1+LT2 vs LT1+LT2+TFC")
    ax.legend(fontsize=8)
    ax.grid(True, axis="y", alpha=0.25)
    fig.tight_layout()
    fig.savefig(os.path.join(save_dir, "cell_counts_by_group.png"),
                dpi=300, bbox_inches="tight")
    fig.savefig(os.path.join(save_dir, "cell_counts_by_group.pdf"),
                dpi=300, bbox_inches="tight")
    if auto_close:
        plt.close(fig)


def _plot_phase1_null_vs_observed(df_null, df_obs, df_summary, save_dir,
                                   *, auto_close=True):
    """Per condition × zone: violin of null vs observed marker, faceted by group."""
    groups = GROUPS
    col = _PAPER_COLORS
    collapsed_zones = ["Arms", "Junction"]
    conditions = ["within_LT1", "within_LT2", "LT1_to_LT2"]
    cond_nice = {
        "within_LT1": "Within LT1",
        "within_LT2": "Within LT2",
        "LT1_to_LT2": r"LT1$\to$LT2",
    }

    for cond in conditions:
        for zone in collapsed_zones:
            fig, axes = plt.subplots(1, len(groups), figsize=(3.2 * len(groups), 4),
                                     sharey=True, dpi=160)
            if len(groups) == 1:
                axes = [axes]

            for gi, g in enumerate(groups):
                ax = axes[gi]
                # Null per mouse in this group
                mice_in_group = df_obs.loc[
                    (df_obs["group"] == g) & (df_obs["condition"] == cond) &
                    (df_obs["zone"] == zone), "mouse"].unique()

                all_null = []
                obs_vals = []
                for m in mice_in_group:
                    null_vals = df_null.loc[
                        (df_null["mouse"] == m) & (df_null["condition"] == cond) &
                        (df_null["zone"] == zone), "pct_correct"].dropna().values
                    all_null.append(null_vals)
                    ov = df_obs.loc[
                        (df_obs["mouse"] == m) & (df_obs["condition"] == cond) &
                        (df_obs["zone"] == zone), "pct_correct"].values
                    obs_vals.append(ov[0] if len(ov) > 0 else np.nan)

                # Violin for each mouse
                positions = np.arange(len(mice_in_group))
                if len(all_null) > 0:
                    parts = ax.violinplot(
                        [v for v in all_null if len(v) > 0],
                        positions=[p for p, v in zip(positions, all_null) if len(v) > 0],
                        showmedians=True, showextrema=False)
                    for pc in parts.get("bodies", []):
                        pc.set_facecolor(col[g])
                        pc.set_alpha(0.4)

                # Observed markers
                for pi, ov in enumerate(obs_vals):
                    if np.isfinite(ov):
                        ax.scatter(pi, ov, marker="D", s=60, zorder=5,
                                   color="red", edgecolors="darkred", linewidths=0.6)

                ax.set_xticks(positions)
                ax.set_xticklabels([str(m) for m in mice_in_group],
                                   fontsize=7, rotation=45)
                ax.set_title(GROUP_LABELS.get(g, g), fontsize=10)
                if gi == 0:
                    ax.set_ylabel("pct_correct")
                ax.grid(True, axis="y", alpha=0.25)

            fig.suptitle(f"Null vs Observed — {cond_nice.get(cond, cond)}, {zone}",
                         fontsize=11)
            fig.tight_layout()
            tag = f"subsampling_null_{cond}_{zone}"
            fig.savefig(os.path.join(save_dir, f"{tag}.png"),
                        dpi=300, bbox_inches="tight")
            fig.savefig(os.path.join(save_dir, f"{tag}.pdf"),
                        dpi=300, bbox_inches="tight")
            if auto_close:
                plt.close(fig)


def _gather_phase1_aggregate_data(df_null, df_obs, groups, cond, zone):
    """Collect per-mouse null arrays and observed values per group.

    Returns dict[group] with keys:
      - "null_pool"       : all null values concatenated (for violin/box display)
      - "obs"             : array of per-mouse observed values
      - "null_per_mouse"  : list of per-mouse null arrays (parallel with obs)
      - "mice"            : mouse labels (parallel with obs)
    """
    data = {}
    for g in groups:
        mice_g = df_obs.loc[
            (df_obs["group"] == g) & (df_obs["condition"] == cond) &
            (df_obs["zone"] == zone), "mouse"].unique()
        null_per_mouse = []
        null_pool = []
        obs_vals = []
        mouse_ids = []
        for m in mice_g:
            nv = df_null.loc[
                (df_null["mouse"] == m) & (df_null["condition"] == cond) &
                (df_null["zone"] == zone), "pct_correct"].dropna().values
            null_per_mouse.append(nv)
            null_pool.append(nv)
            ov = df_obs.loc[
                (df_obs["mouse"] == m) & (df_obs["condition"] == cond) &
                (df_obs["zone"] == zone), "pct_correct"].values
            obs_vals.append(ov[0] if len(ov) > 0 else np.nan)
            mouse_ids.append(m)
        null_pool = np.concatenate(null_pool) if null_pool else np.array([])
        obs_vals = np.array(obs_vals)
        # Keep only mice with valid observed + non-empty null
        keep = [i for i in range(len(obs_vals))
                if np.isfinite(obs_vals[i]) and len(null_per_mouse[i]) > 0]
        data[g] = {
            "null_pool": null_pool,
            "obs": obs_vals[keep] if len(keep) > 0 else np.array([]),
            "null_per_mouse": [null_per_mouse[i] for i in keep],
            "mice": [mouse_ids[i] for i in keep],
        }
    return data


def _phase1_aggregate_stats(data):
    """Per-group test: is the observed pct_correct consistently above/below the
    per-mouse null distribution?

    For each mouse, compute the percentile rank of the observed value within
    that mouse's own null distribution.  Then test whether the group's
    percentile ranks differ from 50 % (chance) using a one-sample Wilcoxon
    signed-rank test.  Falls back to a binomial sign-test when n < 6.

    Returns dict  g -> (stat, p, n_mice, median_pctile, pctiles).
    """
    from scipy import stats as _sp_agg
    results = {}
    for g, d in data.items():
        obs = d["obs"]
        null_per_mouse = d["null_per_mouse"]
        if len(obs) == 0:
            results[g] = (np.nan, np.nan, 0, np.nan, np.array([]))
            continue
        # Per-mouse percentile rank of observed within its null
        pctiles = np.array([
            float(np.mean(null_per_mouse[i] <= obs[i])) * 100.0
            for i in range(len(obs))
        ])
        n = len(pctiles)
        med_pctile = float(np.median(pctiles))
        if n >= 6:
            # Wilcoxon signed-rank against median = 50
            stat, p = _sp_agg.wilcoxon(pctiles - 50.0, alternative="two-sided")
        elif n >= 3:
            # Sign test: count how many are above 50
            n_above = int(np.sum(pctiles > 50.0))
            p = float(_sp_agg.binomtest(n_above, n, 0.5).pvalue)
            stat = float(n_above)
        else:
            stat, p = np.nan, np.nan
        results[g] = (stat, p, n, med_pctile, pctiles)
    return results


def _sig_stars(p):
    if p <= 0.001:
        return "***"
    if p <= 0.01:
        return "**"
    if p <= 0.05:
        return "*"
    return "n.s."


def _draw_sig_bracket(ax, x1, x2, y, h, text):
    """Draw a significance bracket between x1 and x2 at height y."""
    ax.plot([x1, x1, x2, x2], [y, y + h, y + h, y],
            lw=1.0, color="black")
    ax.text((x1 + x2) / 2, y + h, text, ha="center", va="bottom",
            fontsize=8, fontweight="bold")


def _plot_phase1_null_vs_observed_aggregate(df_null, df_obs, save_dir,
                                             *, auto_close=True):
    """Per-group aggregate: paired null / observed violins, one pair per group.

    Significance is tested via per-mouse percentile-rank approach (Wilcoxon
    signed-rank or sign test) to avoid pooling-across-mice artifacts.
    """
    groups = GROUPS
    col = _PAPER_COLORS
    collapsed_zones = ["Arms", "Junction"]
    conditions = ["within_LT1", "within_LT2", "LT1_to_LT2"]
    cond_nice = {
        "within_LT1": "Within LT1",
        "within_LT2": "Within LT2",
        "LT1_to_LT2": r"LT1$\to$LT2",
    }
    spacing = 3.0
    half_w = 0.45

    for cond in conditions:
        for zone in collapsed_zones:
            data = _gather_phase1_aggregate_data(df_null, df_obs, groups, cond, zone)
            stat_results = _phase1_aggregate_stats(data)

            fig, ax = plt.subplots(figsize=(2.2 * len(groups) + 0.8, 4.4), dpi=160)
            tick_positions = []
            tick_labels = []

            for gi, g in enumerate(groups):
                cx = gi * spacing
                pos_null = cx - half_w
                pos_obs = cx + half_w
                null_pool = data[g]["null_pool"]
                obs_vals = data[g]["obs"]

                # Null violin
                if len(null_pool) > 1:
                    vp = ax.violinplot([null_pool], positions=[pos_null],
                                       showmedians=True, showextrema=False,
                                       widths=0.7)
                    for pc in vp.get("bodies", []):
                        pc.set_facecolor(col[g])
                        pc.set_alpha(0.35)
                    if "cmedians" in vp:
                        vp["cmedians"].set_color("black")

                # Observed violin
                if len(obs_vals) > 2:
                    vp2 = ax.violinplot([obs_vals], positions=[pos_obs],
                                        showmedians=True, showextrema=False,
                                        widths=0.7)
                    for pc in vp2.get("bodies", []):
                        pc.set_facecolor(col[g])
                        pc.set_alpha(0.75)
                    if "cmedians" in vp2:
                        vp2["cmedians"].set_color("black")

                # Observed points
                if len(obs_vals) > 0:
                    jitter = np.random.default_rng(42).uniform(-0.12, 0.12,
                                                                size=len(obs_vals))
                    ax.scatter(pos_obs + jitter, obs_vals,
                               marker="D", s=40, zorder=5,
                               color="red", edgecolors="darkred", linewidths=0.5)

                # Significance bracket (percentile-rank test)
                all_vals = np.concatenate([null_pool, obs_vals]) if len(null_pool) > 0 else obs_vals
                if len(all_vals) > 0:
                    y_top = np.nanmax(all_vals)
                    _, p, n_mice, med_pctile, _ = stat_results[g]
                    if np.isfinite(p):
                        star_txt = _sig_stars(p)
                        pctile_txt = f"{med_pctile:.0f}%ile" if np.isfinite(med_pctile) else ""
                        bracket_label = f"{star_txt}\n{pctile_txt}" if pctile_txt else star_txt
                        _draw_sig_bracket(ax, pos_null, pos_obs,
                                          y_top + 0.02, 0.015, bracket_label)

                tick_positions.extend([pos_null, pos_obs])
                tick_labels.extend(["Null", "Obs"])

            ax.set_xticks(tick_positions)
            ax.set_xticklabels(tick_labels, fontsize=7)
            for gi, g in enumerate(groups):
                cx = gi * spacing
                ax.text(cx, -0.08, GROUP_LABELS.get(g, g),
                        transform=ax.get_xaxis_transform(),
                        ha="center", va="top", fontsize=10, fontweight="bold")

            ax.set_ylabel("pct_correct")
            ax.grid(True, axis="y", alpha=0.25)
            fig.suptitle(
                f"Null vs Observed (per group) — {cond_nice.get(cond, cond)}, {zone}",
                fontsize=11)
            fig.tight_layout()
            tag = f"subsampling_null_aggregate_{cond}_{zone}"
            fig.savefig(os.path.join(save_dir, f"{tag}.png"),
                        dpi=300, bbox_inches="tight")
            fig.savefig(os.path.join(save_dir, f"{tag}.pdf"),
                        dpi=300, bbox_inches="tight")
            if auto_close:
                plt.close(fig)


