def _plot_cross_fate_boxplot(mouse_data, metric_key, *,
                             ylabel, title, save_dir, fname,
                             auto_close=True):
    """Boxplot of a single fraction metric grouped by experimental group.

    Delegates to ``_pv_paper_boxplot`` for consistent styling.
    """
    groups_data = {}
    for mouse, md in mouse_data.items():
        val = md[metric_key]
        if np.isfinite(val):
            groups_data.setdefault(md["group"], []).append(val)
    groups_data = {g: np.array(v) for g, v in groups_data.items()}

    if not any(len(v) >= 2 for v in groups_data.values()):
        return

    fig, ax = plt.subplots(figsize=(3.5, 3.5), dpi=300)
    _pv_paper_boxplot(ax, groups_data, ylabel=ylabel, title=title)
    fig.tight_layout()
    for ext in ("png", "pdf"):
        fig.savefig(os.path.join(save_dir, f"{fname}.{ext}"),
                    dpi=300, bbox_inches="tight")
    if auto_close:
        plt.close(fig)


def _plot_cross_fate_stacked_2cat(mouse_data, count_keys, cat_labels,
                                   cat_colors, total_key, *,
                                   ylabel, title, save_dir, fname,
                                   auto_close=True):
    """Stacked bar (2 categories) of cross-fate fractions per group."""
    group_counts = {}
    for mouse, md in mouse_data.items():
        g = md["group"]
        gc = group_counts.setdefault(g, {k: 0 for k in count_keys})
        for k in count_keys:
            gc[k] += md[k]
        gc.setdefault("_total", 0)
        gc["_total"] += md[total_key]

    groups_to_plot = [g for g in GROUPS if g in group_counts]
    if len(groups_to_plot) < 2:
        return

    x = np.arange(len(groups_to_plot))
    fig, ax = plt.subplots(figsize=(3.5, 3.5), dpi=300)

    bottom = np.zeros(len(groups_to_plot))
    for ki, k in enumerate(count_keys):
        vals = np.array([
            group_counts[g][k] / group_counts[g]["_total"]
            if group_counts[g]["_total"] > 0 else 0
            for g in groups_to_plot
        ])
        ax.bar(x, vals, bottom=bottom, width=0.6,
               color=cat_colors[ki], edgecolor="white", linewidth=0.5,
               label=cat_labels[ki])
        bottom += vals

    ax.set_xticks(x)
    ax.set_xticklabels([GROUP_LABELS.get(g, g) for g in groups_to_plot],
                       fontsize=8)
    ax.set_ylabel(ylabel, fontsize=8)
    ax.set_title(title, fontsize=9)
    ax.legend(fontsize=6, frameon=False, loc="upper right")
    ax.spines["top"].set_visible(False)
    ax.spines["right"].set_visible(False)
    ax.tick_params(labelsize=7)
    ax.set_ylim(0, 1.05)
    fig.tight_layout()
    for ext in ("png", "pdf"):
        fig.savefig(os.path.join(save_dir, f"{fname}.{ext}"),
                    dpi=300, bbox_inches="tight")
    if auto_close:
        plt.close(fig)


